DROP FUNCTION IF EXISTS `att_start_end_date_fn`;;
CREATE FUNCTION `att_start_end_date_fn` (`start_date` varchar(20), `year_month` varchar(20)) RETURNS varchar(30) CHARACTER SET 'latin1' LANGUAGE SQL
begin

declare vattendance_date int;
declare vreturn varchar(30) ;
declare thisDate timestamp;
   declare nextDate timestamp;
declare vcount int;
  

select attendance_date into vattendance_date from db_config where upper(active)='Y';
 set thisDate = concat(vattendance_date,'-01-2015');
select count(*) into vcount from date_intervel_monthyear where month_year >=date_format(current_date,'%Y-%m');
if vcount >=1 then
delete from date_intervel_monthyear where month_year >=date_format(current_date,'%Y-%m');

end if;


         if  vattendance_date =1 then

 
         set  vreturn = current_date;
        else

        set  vreturn= current_date;
         end if;



  set  vreturn= 'successfull';

return (vreturn) ;
end;;

DROP FUNCTION IF EXISTS `att_start_end_fn`;;
CREATE FUNCTION `att_start_end_fn` (`Pyear_month` date, `patt_start_end` int) RETURNS date LANGUAGE SQL
begin
declare vfullcnt float;
declare vhalfcnt float;
declare vleavecnt float;
declare vstart_month date;
declare vend_month date;
declare vleave_for_thyear float;
declare vcarry_forwarded float;
declare vemp_pkey int;
declare vfin_count int;
declare pfinyear varchar(30);
declare vmonthly_att_fromdate date;
declare vmonthly_att_todate date;
DECLARE exit_loop1 BOOLEAN default FALSE;
DECLARE vattendance_format varchar(10);
DECLARE vattendance_date  int;
declare vattdate date;

select attendance_format,attendance_date into vattendance_format,	vattendance_date   from db_config limit 1;

if patt_start_end=1 then

if vattendance_format='B' then
if vattendance_date =0 then

set vattdate =DATE_FORMAT(Pyear_month, '%Y-%m-01');

else
   set vattdate =date_format(DATE_SUB(concat(DATE_FORMAT(DATE_SUB(Pyear_month,INTERVAL 1 month), '%Y-%m-'),date_format(last_day(DATE_SUB(Pyear_month,INTERVAL 1 month)),'%d')),INTERVAL vattendance_date-1 day),'%Y-%m-%d');  

end if ;
else 
set vattdate =date_format(concat(DATE_FORMAT(DATE_SUB(Pyear_month,INTERVAL 1 month), '%Y-%m-'),vattendance_date),'%Y-%m-%d') ;
end if;

elseif patt_start_end=2 then
if vattendance_format='B' then
if vattendance_date =0 then

set vattdate =LAST_DAY(DATE_FORMAT(Pyear_month, '%Y-%m-%d'));

else

set vattdate =DATE_SUB(concat(DATE_FORMAT(Pyear_month, '%Y-%m-'),date_format(last_day(Pyear_month),'%d')),INTERVAL vattendance_date day);
 
end if ;
else 
set vattendance_date=vattendance_date-1;
set vattdate =date_add(date_format(concat(DATE_FORMAT(DATE_SUB(Pyear_month,INTERVAL 1 month), '%Y-%m-'),vattendance_date),'%Y-%m-%d'),interval  1 month) ;
end if;

end if;

return vattdate;
end;;

DROP PROCEDURE IF EXISTS `bulk_company_idupdate`;;
CREATE PROCEDURE `bulk_company_idupdate` (IN `pemp_pkey` int)
begin

declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
declare vDeviceId int;
DECLARE exit_loop BOOLEAN default FALSE;

declare rec_count int;
declare vdevice_count int ;
declare vemp_co_id int;
declare vemp_company_id varchar(100);
declare vusername varchar(100);
declare vemp_branch varchar(30);
declare pcompany_code varchar(30);
DECLARE vemail varchar(100);


declare cur cursor for
select distinct emp_fkey,emp_company_id,concat(substr(emp_branch,1,4),emp_company_id) username ,emp_branch
                                     from emp_proff where emp_fkey=if(pemp_pkey in(null,''),emp_fkey,pemp_pkey) 
									 order by 1;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;

open cur;
start_loop: loop
    fetch cur into vemp_pkey,vemp_company_id,vusername,vemp_branch;
IF exit_loop THEN
        LEAVE start_loop;
     END IF;
   select company_code,email into pcompany_code,vemail from emp_details where emp_pkey=vemp_pkey;
 select count(*) into rec_count from mypayrol_control_db.emp_device_comp_branch where Company_code=pcompany_code and 
      branch_code=vemp_branch and emp_fkey=vemp_pkey;

if rec_count=0 then
   insert into mypayrol_control_db.emp_device_comp_branch(deviceid,emp_device_id,emp_name,Company_code,branch_code,emp_fkey,email ) 
         values (vDeviceId,vemp_company_id,vfirst_name,pcompany_code,vemp_branch,vemp_pkey,vemail);  
 		 
   update emp_details set emp_id=vemp_company_id where emp_pkey=vemp_pkey;
   update  user_credentials set user_id=vusername where emp_fkey=vemp_pkey ;
 else
  update emp_details set emp_id=vemp_company_id where emp_pkey=vemp_pkey;
   update  user_credentials set user_id=vusername where emp_fkey=vemp_pkey ;
   update mypayrol_control_db.emp_device_comp_branch set emp_device_id=vemp_company_id,emp_id=vemp_company_id,
   emp_username=vusername,email=vemail
            where emp_fkey=vemp_pkey and Company_code=pcompany_code ;
 end if;
  end loop;
close cur;




end;;

DROP PROCEDURE IF EXISTS `bulk_device_logs_iteration_prc`;;
CREATE PROCEDURE `bulk_device_logs_iteration_prc` (IN `p_year_month` date)
begin
    declare v_emp_id varchar(20);
    declare v_done int default 0;
    
    declare emp_cursor cursor for
        select `emp_id`
        from `emp_details`
        where `status` = 1 order by emp_pkey;
    
    declare continue handler for not found set v_done = 1;
    
    open emp_cursor;
    
    emp_loop: loop
        fetch emp_cursor into v_emp_id;
        
        if v_done = 1 then
            leave emp_loop;
        end if;
        
        select device_logs_iteration_fn(v_emp_id, p_year_month) into @err_msg;
    end loop emp_loop;
    
    close emp_cursor;
end;;

DROP PROCEDURE IF EXISTS `calculate_emp_component_breakup`;;
CREATE PROCEDURE `calculate_emp_component_breakup` (IN `Pstructure_id` int, IN `Psalary_head_item_pkey` int, IN `Pmonthly_comp` decimal(10,2), IN `Pmonthly_gross` decimal(10,2))
begin
DECLARE exit_loop6 BOOLEAN default FALSE;
declare vhead_fkey int;
declare vhead_fkey1 int;
declare vstructure_det_depends  float;
declare vstructure_det_depends1  float;
declare vstructure_formula varchar(600);
declare vstructure_formula1 varchar(600);
declare vstructure_derived_perc float;
declare vstructure_derived_perc1 float;
declare vsalary_head_item_fkey int;
declare vsalary_head_item_fkey1 int;
declare vitem varchar(600);
declare vitem1 varchar(600);
declare vhead_operator varchar(20);
declare vhead_operator1 varchar(20);
declare vstructure_det_value float;
declare vstructure_det_value1 float;
declare vnewformula varchar(200);
declare vformula_value float;
declare vremarks varchar(1000);
declare vremarks1 varchar(1000);
declare vvalue float;
declare vdeduction_flag char(1);
DECLARE vdistributed_total DECIMAL(14,4) DEFAULT 0;
DECLARE vstructure_det_calequation VARCHAR(1000); 
  
declare adjustment cursor for
SELECT h.head_pkey,ssd.salary_head_item_fkey , trim(shi.item) as item,ssd.structure_det_operator as operator,ssd.structure_det_value,ssd.structure_det_depends ,
case
  when lower(h.head_operator) = 'deduction' then 'Y'
  else 'N'
end as deduction_flag,
  ssd.structure_formula,ssd.structure_derived_perc,
  ssd.structure_det_calequation 
  FROM salary_structure_details as ssd join salary_head_items as shi on shi.salary_head_item_pkey = ssd.salary_head_item_fkey
   join salary_heads as h ON h.head_pkey = shi.head_fkey
 where structure_id =Pstructure_id and upper(structure_formula) RLIKE'[A-Z]'
 and head_pkey IN (4, 5) -- Edited by Akshay on 11-12-2025
	order by (ssd.structure_det_operator = 'rembalance');
    
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop6 = TRUE;
  
    CREATE TEMPORARY TABLE IF NOT EXISTS salary_breakup_temp (
    salary_head_item_fkey 	INT,
    item					VARCHAR(255),
    structure_det_value		DECIMAL(10,2),
	structure_formula		varchar(1000),
    structure_det_calequation  VARCHAR(1000), 
    is_deduction			CHAR(1),
        structure_det_operator  VARCHAR(50),         
    structure_det_depends   DECIMAL(10,4)        
  );
  TRUNCATE TABLE salary_breakup_temp;
  
open adjustment ;
start_loop1: loop
	fetch adjustment into vhead_fkey1,vsalary_head_item_fkey1,vitem1,vhead_operator1 ,vstructure_det_value1, vstructure_det_depends1, vdeduction_flag,
	vstructure_formula1, vstructure_derived_perc1, vstructure_det_calequation;
   
IF exit_loop6 THEN 
       LEAVE start_loop1 ;   
  END IF;
   
  INSERT INTO salary_breakup_temp (
      salary_head_item_fkey, item, structure_det_value, structure_formula, structure_det_calequation, is_deduction,
      structure_det_operator, structure_det_depends
  ) VALUES (
      vsalary_head_item_fkey1, vitem1, vstructure_det_value1, vstructure_formula1, vstructure_det_calequation, vdeduction_flag,
      vhead_operator1, vstructure_det_depends1
  );
   
   block60:begin
	
   DECLARE exit_loop60 BOOLEAN default FALSE;
    declare comp_cur cursor for
	SELECT shi.head_fkey,salary_head_item_fkey , trim(shi.item) as item,structure_det_operator,structure_det_value,
  structure_det_depends ,structure_formula,structure_derived_perc
  FROM salary_structure_details ,salary_head_items shi
 where  salary_head_item_fkey =salary_head_item_pkey
and structure_id =Pstructure_id ;
	
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop60 = TRUE;
 
  open comp_cur;
  start_loop60: loop
    fetch comp_cur into vhead_fkey,vsalary_head_item_fkey,vitem,vhead_operator,vstructure_det_value,
	vstructure_det_depends,vstructure_formula,vstructure_derived_perc;
	
	IF exit_loop60 THEN 
       LEAVE start_loop60 ;   
    END IF;
	if vsalary_head_item_fkey = Psalary_head_item_pkey then
	if INSTR(vstructure_formula1,vitem) >0 then
	 update salary_breakup_temp set structure_formula=replace (structure_formula,vitem,Pmonthly_comp)  
	where salary_head_item_fkey=vsalary_head_item_fkey1;
   end if;
	else
	 if INSTR(vstructure_formula1,vitem) >0 then
	 update salary_breakup_temp set structure_formula=replace (structure_formula,vitem,vstructure_det_value)  
	where salary_head_item_fkey=vsalary_head_item_fkey1;
   end if;
   end if;
   if INSTR(vstructure_formula1,'Monthly Gross Salary') >0 then
		update salary_breakup_temp set structure_formula=replace (structure_formula,'Monthly Gross Salary', Pmonthly_gross)
		where salary_head_item_fkey=vsalary_head_item_fkey1;
   end if;
   
 end loop start_loop60;              			
 	
	close comp_cur;
   end block60 ;
 
 SET vformula_value = (vstructure_derived_perc1 / 100) * Pmonthly_gross;

    IF vhead_operator1 = 'formula' THEN
      SET vvalue = vformula_value;

    ELSEIF vhead_operator1 = 'fixed' THEN
      SET vvalue = vstructure_det_value1;

    ELSEIF vhead_operator1 = 'limit' THEN
      SET vvalue = LEAST(vstructure_det_value1, vformula_value);

    ELSEIF vhead_operator1 = 'limit_wl' THEN
      SET vvalue = LEAST(vstructure_det_depends1, vformula_value);

    ELSEIF vhead_operator1 = 'limit_wg' THEN
      SET vvalue = GREATEST(vstructure_det_depends1, vformula_value);

    ELSEIF vhead_operator1 = 'rembalance' THEN
      SET vvalue = Pmonthly_gross - vdistributed_total;

    ELSE
      SET vvalue = 0;
    END IF;

    IF vdeduction_flag = 'Y' THEN
      SET vvalue = -ABS(vvalue);
    END IF;
   
   update salary_breakup_temp set structure_det_value = vvalue
	where salary_head_item_fkey=vsalary_head_item_fkey1;
 
 IF vhead_operator1 <> 'rembalance' AND vvalue > 0 AND vhead_fkey1 = 1 THEN
      SET vdistributed_total = vdistributed_total + vvalue;
    END IF;
	
  end loop start_loop1;
 
 close adjustment;
 
 SELECT * FROM salary_breakup_temp order by salary_head_item_fkey;


  DROP TEMPORARY TABLE IF EXISTS salary_breakup_temp;
 
 end;;

DROP PROCEDURE IF EXISTS `calculate_emp_salary_breakup`;;
CREATE PROCEDURE `calculate_emp_salary_breakup` (IN `Pemp_fkey` int, IN `Pstructure_id` int, IN `Pmonthly_gross` decimal(10,2))
BEGIN
  DECLARE done               INT DEFAULT 0;
  DECLARE vhead_id           INT;
  DECLARE vhead_name         VARCHAR(255);
  DECLARE voperator          VARCHAR(30);
  DECLARE vdeduction_flag    CHAR(1);
  DECLARE vderived_perc      DECIMAL(12,6);
  DECLARE vdet_value         DECIMAL(10,2);
  DECLARE vdet_depends       DECIMAL(10,2);
  DECLARE vformula_value     DECIMAL(18,6);
  DECLARE vvalue             DECIMAL(18,6);
  DECLARE vdistributed_total DECIMAL(18,6) DEFAULT 0;
  DECLARE vhead_key          INT;

  
  DECLARE cur CURSOR FOR
    SELECT 
      ssd.salary_head_item_fkey,
      shi.item                  AS head_name,
      ssd.structure_det_operator AS operator,
      ssd.structure_derived_perc,
      ssd.structure_det_value,
      ssd.structure_det_depends,
      CASE 
        WHEN LOWER(h.head_operator) = 'deduction' THEN 'Y' 
        ELSE 'N' 
      END AS deduction_flag,
      h.head_pkey               AS head_key
    FROM salary_structure_details ssd
    JOIN salary_head_items      shi ON shi.salary_head_item_pkey = ssd.salary_head_item_fkey
    JOIN salary_heads           h   ON h.head_pkey = shi.head_fkey
    WHERE ssd.structure_id = Pstructure_id
      AND (ssd.structure_det_value <> 0 
           OR ssd.structure_derived_perc <> 0 
           OR ssd.structure_det_operator = 'rembalance')
    ORDER BY (ssd.structure_det_operator = 'rembalance');

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

  
  CREATE TEMPORARY TABLE IF NOT EXISTS salary_breakup_temp (
    salary_head_item_fkey INT,
    head_name             VARCHAR(255),
    amount                DECIMAL(10,2),
    is_deduction          CHAR(1)
  );
  TRUNCATE TABLE salary_breakup_temp;

  
  OPEN cur;
  read_loop: LOOP
    FETCH cur 
      INTO vhead_id, vhead_name, voperator, vderived_perc, vdet_value, vdet_depends, vdeduction_flag, vhead_key;
    IF done THEN 
      LEAVE read_loop;
    END IF;

    SET vformula_value = (vderived_perc / 100) * Pmonthly_gross;

    IF voperator = 'formula' THEN
      SET vvalue = vformula_value;

    ELSEIF voperator = 'fixed' THEN
      SET vvalue = vdet_value;

    ELSEIF voperator = 'limit' THEN
      SET vvalue = LEAST(vdet_value, vformula_value);

    ELSEIF voperator = 'limit_wl' THEN
      SET vvalue = LEAST(vdet_depends, vformula_value);

    ELSEIF voperator = 'limit_wg' THEN
      SET vvalue = GREATEST(vdet_depends, vformula_value);

    ELSEIF voperator = 'rembalance' THEN
      SET vvalue = Pmonthly_gross - vdistributed_total;

    ELSE
      SET vvalue = 0;
    END IF;

    IF vdeduction_flag = 'Y' THEN
      SET vvalue = -ABS(vvalue);
    END IF;

    INSERT INTO salary_breakup_temp (salary_head_item_fkey, head_name, amount, is_deduction)
    VALUES (vhead_id, vhead_name, ROUND(vvalue, 2), vdeduction_flag);

    IF voperator <> 'rembalance' AND vvalue > 0 AND vhead_key = 1 THEN
      SET vdistributed_total = vdistributed_total + vvalue;
    END IF;
  END LOOP;
  CLOSE cur;

  
  SELECT * FROM salary_breakup_temp;

  
  DROP TEMPORARY TABLE IF EXISTS salary_breakup_temp;
END;;

DROP PROCEDURE IF EXISTS `calculate_holiday_allowances_prc`;;
CREATE PROCEDURE `calculate_holiday_allowances_prc` (IN `pemp_pkey` int, IN `pmonth_year` varchar(7), IN `pcreated_by` varchar(30))
BEGIN
main_block: BEGIN

    
    
    
    DECLARE v_sunday_days DECIMAL(10,2) DEFAULT 0;
    DECLARE v_sun_hol_days DECIMAL(10,2) DEFAULT 0;

    DECLARE v_weekoff DECIMAL(10,2) DEFAULT 0;
    DECLARE v_holiday DECIMAL(10,2) DEFAULT 0;

    DECLARE v_has_sunday_structure BOOLEAN DEFAULT FALSE;
    DECLARE v_has_sunhol_structure BOOLEAN DEFAULT FALSE;

    DECLARE v_from_date DATE;
    DECLARE v_to_date DATE;
    DECLARE vwork_time_day_off_cal_ot int;
    
    
    
    SET v_from_date = STR_TO_DATE(CONCAT(pmonth_year,'-01'),'%Y-%m-%d');
    SET v_to_date   = LAST_DAY(v_from_date);

    
    
    
    DROP TEMPORARY TABLE IF EXISTS tmp_holiday_totals;
    CREATE TEMPORARY TABLE tmp_holiday_totals (
        salary_head_item_fkey INT PRIMARY KEY,
        salary_head_item_desc VARCHAR(250),
        structure_det_value DECIMAL(10,2),
        head_operator VARCHAR(30),
        head_type VARCHAR(30),
        item_part VARCHAR(30),
        total_days DECIMAL(10,2),
        total_amount DECIMAL(10,2)
    ) ENGINE=MEMORY;

    
    
    
    SELECT 
        MAX(CASE WHEN LOWER(ess.salary_head_item_desc) = 'sunday allowance' THEN 1 ELSE 0 END),
        MAX(CASE WHEN LOWER(ess.salary_head_item_desc) = 'sunday or holiday allowance' THEN 1 ELSE 0 END)
    INTO v_has_sunday_structure, v_has_sunhol_structure
    FROM emp_salary_structure ess
    WHERE ess.emp_fkey = pemp_pkey
      AND ess.end_date_effective IS NULL
      AND LOWER(ess.salary_head_item_desc) 
          IN ('sunday allowance','sunday or holiday allowance');

    
    
    
    IF v_has_sunday_structure = 1 OR v_has_sunhol_structure = 1 THEN

        CALL get_present_in_weekoff_holiday_count_prc(
            pemp_pkey,
            pmonth_year,
            v_weekoff,
            v_holiday
        );

        SET v_sunday_days  = IFNULL(v_weekoff, 0);
        SET v_sun_hol_days = IFNULL(v_weekoff, 0) + IFNULL(v_holiday, 0);

        SELECT work_time_day_off_cal_ot 
        INTO vwork_time_day_off_cal_ot 
        FROM working_day_time_procedures
        WHERE day_time_seq IN (
            SELECT day_time_seq 
            FROM emp_proff 
            WHERE emp_fkey = pemp_pkey
        );

        IF vwork_time_day_off_cal_ot != 4 THEN
            SET v_sunday_days = 0;
        END IF;

        IF vwork_time_day_off_cal_ot != 5 THEN
            SET v_sun_hol_days = 0;
        END IF;
        
        INSERT INTO tmp_holiday_totals (
            salary_head_item_fkey,
            salary_head_item_desc,
            structure_det_value,
            head_operator,
            head_type,
            item_part,
            total_days,
            total_amount
        )
        SELECT
            ess.salary_head_item_fkey,
            ess.salary_head_item_desc,
            ess.structure_det_value,
            ess.head_operator,
            ess.head_type,
            ess.item_part,

            CASE
                WHEN LOWER(ess.salary_head_item_desc) = 'sunday allowance'
                    THEN v_sunday_days
                WHEN LOWER(ess.salary_head_item_desc) = 'sunday or holiday allowance'
                    THEN v_sun_hol_days
                ELSE 0
            END AS total_days,

            CASE
                WHEN LOWER(ess.salary_head_item_desc) = 'sunday allowance'
                    THEN v_sunday_days * ess.structure_det_value
                WHEN LOWER(ess.salary_head_item_desc) = 'sunday or holiday allowance'
                    THEN v_sun_hol_days * ess.structure_det_value
                ELSE 0
            END AS total_amount
        FROM emp_salary_structure ess
        WHERE ess.emp_fkey = pemp_pkey
          AND ess.end_date_effective IS NULL
          AND LOWER(ess.salary_head_item_desc) 
              IN ('sunday allowance','sunday or holiday allowance')
        HAVING total_days > 0;

        
        
        
        IF (SELECT COUNT(*) FROM tmp_holiday_totals) = 0 THEN
            DROP TEMPORARY TABLE IF EXISTS tmp_holiday_totals;
            LEAVE main_block;
        END IF;



        
        
        
        INSERT INTO emp_calc_variable_components (
            emp_fkey,
            month_year,
            salary_head_item_fkey,
            salary_head_item_desc,
            structure_det_value,
            salary_rate,
            salary_amount,
            head_operator,
            head_type,
            item_part,
            created_by,
            created_date
        )
        SELECT
            pemp_pkey,
            pmonth_year,
            salary_head_item_fkey,
            salary_head_item_desc,
            structure_det_value,
            structure_det_value,
            total_amount,
            head_operator,
            head_type,
            item_part,
            pcreated_by,
            NOW()
        FROM tmp_holiday_totals;

        DROP TEMPORARY TABLE IF EXISTS tmp_holiday_totals;

    END IF;

END main_block;
END;;

DROP PROCEDURE IF EXISTS `calculate_leave_encashment_prc`;;
CREATE PROCEDURE `calculate_leave_encashment_prc` (IN `pemp_pkey` int, IN `pmonth_year` varchar(7), IN `pcreated_by` varchar(30))
proc_main: BEGIN

    
    
    
    DECLARE vleaveencashmentkey INT DEFAULT NULL;
    DECLARE vleaveencashmentrate DECIMAL(10,2) DEFAULT 0;

    DECLARE vapproved_count INT DEFAULT 0;
    DECLARE vapproved_days DECIMAL(10,2) DEFAULT 0;

    DECLARE vemp_salary DECIMAL(10,2) DEFAULT 0;

    DECLARE vmonth_start DATE;
    DECLARE vmonth_end DATE;

    
    
    
    SET vmonth_start = STR_TO_DATE(CONCAT(pmonth_year, '-01'), '%Y-%m-%d');
    SET vmonth_end   = DATE_ADD(vmonth_start, INTERVAL 1 MONTH);

    
    
    
    SELECT 
        ess.salary_head_item_fkey,
        ess.structure_det_value
    INTO 
        vleaveencashmentkey,
        vleaveencashmentrate
    FROM emp_salary_structure ess
    WHERE ess.emp_fkey = pemp_pkey
      AND ess.end_date_effective IS NULL
      AND LOWER(ess.salary_head_item_desc) = 'leave encashment'
    LIMIT 1;

    
    IF vleaveencashmentkey IS NULL THEN
        LEAVE proc_main;
    END IF;

    
    
    
    SELECT 
        COUNT(*),
        IFNULL(SUM(approved_days), 0)
    INTO 
        vapproved_count,
        vapproved_days
    FROM leave_encashment_master
    WHERE emp_fkey = pemp_pkey
      AND approved_date >= vmonth_start
      AND approved_date < vmonth_end
      AND is_approved = 'Y'
      AND salary_paid = 'N'
      AND status = 1
      AND salary_head_item_fkey != 0;

    
    
    
    IF vapproved_count > 0 AND vapproved_days > 0 THEN
        SET vemp_salary = vleaveencashmentrate * vapproved_days;
    ELSE
        SET vemp_salary = 0;
    END IF;
	
    IF vemp_salary > 0 THEN

        INSERT INTO emp_calc_variable_components (
            emp_fkey,
            month_year,
            salary_head_item_fkey,
            salary_head_item_desc,
            structure_det_value,
            salary_rate,
            salary_amount,
            head_operator,
            head_type,
            item_part,
            remarks,
            created_by,
            created_date
        )
        SELECT
            pemp_pkey,
            pmonth_year,
            vleaveencashmentkey,
            'Leave Encashment',
            vleaveencashmentrate,
            vleaveencashmentrate,
            vemp_salary,
            ess.head_operator,
            ess.head_type,
            ess.item_part,
            NULL,
            pcreated_by,
            NOW()
        FROM emp_salary_structure ess
        WHERE ess.emp_fkey = pemp_pkey
          AND ess.salary_head_item_fkey = vleaveencashmentkey
          AND ess.end_date_effective IS NULL
        LIMIT 1;

    END IF;

END;;

DROP PROCEDURE IF EXISTS `calculate_monthly_salary_components_prc`;;
CREATE PROCEDURE `calculate_monthly_salary_components_prc` (IN `pemp_pkey` int(11), IN `pmonth` varchar(20), IN `puser_id` varchar(30), OUT `poutput` varchar(30))
begin
	declare vemp_fkey int;
	declare vexist_count int;
	declare vbranch_code varchar(30); 
	declare vemp_type varchar(30);	
	declare vpresant_total float;	
	declare vweekoff_total float;
	declare vholiday_total float;
	declare vleave_total float;
	declare vlop_only float;
	declare vlop_total float;
	declare vwd_lop_total float;
	declare vemp_structure_id int ;
	declare vprorate_code int;
	declare vsalary_head_item_fkey int;
	declare vsalary_head_item_desc varchar(100);
	declare vstructure_det_value float;
	declare vhead_operator varchar(20);
	declare vhead_type varchar(25);
	declare vitem_part varchar(25);
	declare vemp_salary float;
	declare vworking_days float;
	declare vrate float;
	declare vfixed_days float;
	declare vworking_time1 varchar(30);
	declare vworking_time2 varchar(30);
	declare vdaytotal float;
	declare vtotal_hours float;
	declare vduration float;
	declare vcalander_days int;
	declare voutput_count int;
	declare vemp_monthly_ctc float;
	declare vleave_salary float;
	declare vmessage varchar(100);
	declare vstructure_id int;
	declare vpayroll_type varchar(10);
	declare vfrom_date date;
	declare vto_date date;
	declare vm_calander_days float;
	declare vm_working_days float;
	declare vm_weekoff_total float;
	declare vm_holiday_total float;
	
	declare exit_loop boolean default false;
	
	declare structurecur cursor for
	select emp_fkey, emp_structure_id, prorate_code, salary_head_item_fkey, salary_head_item_desc, structure_det_value, head_operator, head_type, item_part from emp_salary_structure 
	where emp_fkey = pemp_pkey and end_date_effective is null and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items where head_fkey in (select head_pkey from salary_heads where head_pkey = 1));
	
	declare continue handler for not found set exit_loop = true;
	
	select count(*) into vexist_count from emp_monthly_salary_components where emp_fkey = pemp_pkey and month_year = pmonth and end_date_effective is null;
	
	if vexist_count > 0 then
		update emp_monthly_salary_components set end_date_effective = current_date, modified_by = puser_id where emp_fkey = pemp_pkey and month_year = pmonth and end_date_effective is null;
	end if;
	
	select emp_type, structure_id into vemp_type, vstructure_id from emp_proff where emp_fkey = pemp_pkey order by emp_proff_pkey desc limit 1;
	
	select branch_code, presant_total, leave_total, lop_only, lop_total, wd_lop_total, weekoff_total, holiday_total, working_days, calander_days
	into vbranch_code, vpresant_total, vleave_total, vlop_only, vlop_total, vwd_lop_total, vweekoff_total, vholiday_total, vworking_days, vcalander_days from attendance_register 
	where emp_fkey = pemp_pkey and month_year = pmonth and isdelete = 'N';
	
	if upper(vemp_type) = 'HOURLY WAGES' then
		select working_time1, working_time2 into vworking_time1, vworking_time2 from working_day_time_procedures
		where day_time_seq in (select day_time_seq from emp_proff where emp_fkey = pemp_pkey);
		
		if vworking_time2 > 0 then
			set vdaytotal = (vworking_time1 + vworking_time2) / 60;
        else
			set vdaytotal = vworking_time1 / 60;
        end if;
		
        select emp_anual_ctc into vemp_monthly_ctc
		from emp_ctc_transaction where emp_fkey = pemp_pkey and end_date_effective is null;
		
		set vleave_salary = (ifnull(vleave_total, 0) * ifnull(vdaytotal, 0)) * vemp_monthly_ctc;
		
		select sum(duration) / 60 into vduration from emp_detail_timeattandance
		where emp_pkey = pemp_pkey and yearmonth in (select date_format(concat(month_year, '-01'), '%Y-%m-01')
		from attendance_register where emp_fkey = pemp_pkey and isdelete = 'N' and month_year = pmonth);
		
		set vtotal_hours = ifnull(vduration, 0) + (ifnull(vleave_total, 0) * ifnull(vdaytotal, 0));
		set vemp_monthly_ctc = vduration * vemp_monthly_ctc;
		set vemp_monthly_ctc = ifnull(vemp_monthly_ctc, 0) + vleave_salary;
		
		select site_sal_structure_distribution_fn(vbranch_code, pemp_pkey, vstructure_id, vemp_monthly_ctc, puser_id) into vmessage;
	end if;
	
	open structurecur;
		start_loop: loop
			fetch structurecur into vemp_fkey, vemp_structure_id, vprorate_code, vsalary_head_item_fkey, vsalary_head_item_desc, vstructure_det_value, vhead_operator, vhead_type, vitem_part;
			
			if exit_loop then 
				leave start_loop ;   
			end if;
			
			select distinct payroll_type into vpayroll_type from db_config where active = 'Y';
			
			if vpayroll_type = 'M' then
				set vfrom_date = date_format(concat(pmonth, '-01'), '%Y-%m-01');
				set vto_date = last_day(vfrom_date);
				
				call get_policy_weekoff_holiday_count_prc(pemp_pkey, vfrom_date, vto_date, vm_weekoff_total, vm_holiday_total);
				
				set vm_calander_days = day(vto_date);
				set vm_working_days = vm_calander_days - (vm_weekoff_total + vm_holiday_total);
				
				if upper(vemp_type) = 'DAILY WAGES' then
					if vwd_lop_total = vworking_days then
						if vm_working_days > vworking_days then
							set vwd_lop_total = vm_working_days;
						end if;
					end if;
				elseif upper(vemp_type) <> 'HOURLY WAGES' then
					if vprorate_code = 3 then
						select fixed_days into vfixed_days from salary_structure where structure_id = vemp_structure_id;
						
						if vlop_total = vcalander_days then
							if vfixed_days > vcalander_days then
								set vlop_total = vfixed_days;
							end if;
						end if;
					elseif vprorate_code = 2 then
						if vwd_lop_total = vworking_days then
							if vm_working_days > vworking_days then
								set vwd_lop_total = vm_working_days;
							end if;
						end if;
					elseif vprorate_code = 1 then
						if vlop_total = vcalander_days then
							if vm_calander_days > vcalander_days then
								set vlop_total = vm_calander_days;
							end if;
						end if;
					end if;
				end if;
				
				set vcalander_days = vm_calander_days;
				set vworking_days = vm_working_days;
				set vweekoff_total = vm_weekoff_total;
				set vholiday_total = vm_holiday_total;
			end if;
			
			if upper(vemp_type) = 'DAILY WAGES' then
				if lcase(vhead_type) != 'fixed' then
					if vworking_days >= vwd_lop_total then
						set vrate = vworking_days - vwd_lop_total;
					else
						set vrate = 0;
					end if;
					
					set vemp_salary = vstructure_det_value * vrate;
				else
					set vemp_salary = vstructure_det_value; 
				end if;
				
				insert into emp_monthly_salary_components (emp_fkey, month_year, salary_head_item_fkey, salary_head_item_desc, structure_det_value, salary_rate, salary_amount, head_operator, head_type, item_part, created_by)
				values (vemp_fkey, pmonth, vsalary_head_item_fkey, vsalary_head_item_desc, (vstructure_det_value/vrate), vstructure_det_value, vemp_salary, vhead_operator, vhead_type, vitem_part, puser_id);
			elseif upper(vemp_type) = 'HOURLY WAGES' then
				set vemp_salary = vstructure_det_value;
				
				if lcase(vhead_type) != 'fixed' then
					insert into emp_monthly_salary_components (emp_fkey, month_year, salary_head_item_fkey, salary_head_item_desc, structure_det_value, salary_rate, salary_amount, head_operator, head_type, item_part, created_by)
					values (vemp_fkey, pmonth, vsalary_head_item_fkey, vsalary_head_item_desc, (vstructure_det_value/vtotal_hours), vstructure_det_value, vemp_salary, vhead_operator, vhead_type, vitem_part, puser_id);
				else
					insert into emp_monthly_salary_components (emp_fkey, month_year, salary_head_item_fkey, salary_head_item_desc, structure_det_value, salary_rate, salary_amount, head_operator, head_type, item_part, created_by)
					values (vemp_fkey, pmonth, vsalary_head_item_fkey, vsalary_head_item_desc, vemp_salary, vstructure_det_value, vemp_salary, vhead_operator, vhead_type, vitem_part, puser_id);
				end if;
			else
				if lcase(vhead_type) != 'fixed' then
					if vprorate_code = 3 then
						select fixed_days into vfixed_days from salary_structure where structure_id = vemp_structure_id;
						
						if vfixed_days >= vlop_total then
							set vrate = vfixed_days - vlop_total;
						else
							set vrate = 0;
						end if;
						
						set vemp_salary = (vstructure_det_value / vfixed_days) * vrate;
					elseif vprorate_code = 2 then						
						if vworking_days >= vwd_lop_total then
							set vrate = vworking_days - vwd_lop_total;
						else
							set vrate = 0;
						end if;
						
						set vemp_salary = (vstructure_det_value / vworking_days) * vrate;
					elseif vprorate_code = 1 then
						if vcalander_days >= vlop_total then
							set vrate = vcalander_days - vlop_total;
						else
							set vrate = 0;
						end if;
						
						set vemp_salary = (vstructure_det_value / vcalander_days) * vrate ; 	  	 
					end if;
				else
					set vemp_salary = vstructure_det_value;
					
					if vprorate_code = 3 then
						if vfixed_days - vlop_total <= 0 then
							set vemp_salary = 0;
						end if;
					elseif vprorate_code = 2 then
						if vworking_days - vwd_lop_total <= 0 then
							set vemp_salary = 0;
						end if;
					elseif vprorate_code = 1 then
						if vcalander_days - vlop_total <= 0 then
							set vemp_salary = 0;
						end if;
					end if;
				end if;
				
				insert into emp_monthly_salary_components (emp_fkey, month_year, salary_head_item_fkey, salary_head_item_desc, structure_det_value, salary_rate, salary_amount, head_operator, head_type, item_part, created_by)
				values (vemp_fkey, pmonth, vsalary_head_item_fkey, vsalary_head_item_desc, vstructure_det_value, vstructure_det_value, vemp_salary, vhead_operator, vhead_type, vitem_part, puser_id);
			end if;
		end loop start_loop;
	close structurecur;
	
	select count(*) into voutput_count from emp_monthly_salary_components where emp_fkey = vemp_fkey and month_year = pmonth and end_date_effective is null;
	
	if voutput_count > 0 then 
		set poutput = 'success';
	else
		set poutput = 'failure';
	end if;
end;;

DROP PROCEDURE IF EXISTS `calculate_ot_allowance_prc`;;
CREATE PROCEDURE `calculate_ot_allowance_prc` (IN `pemp_pkey` int, IN `pmonth_year` varchar(7), IN `pcreated_by` varchar(30))
BEGIN
    DECLARE vset_duration DECIMAL(10,2);
    DECLARE votcomponent INT;
    DECLARE vsalary_head_item_desc VARCHAR(250);
    DECLARE vstructure_det_value DECIMAL(10,2);
    DECLARE vday_time_seq INT; 
    DECLARE vhead_operator VARCHAR(10);
    DECLARE vhead_type VARCHAR(10);
    DECLARE vitem_part VARCHAR(10);
    DECLARE vot_salary DECIMAL(10,2);
    DECLARE v_exists INT DEFAULT 0;

    DECLARE finished INT DEFAULT 0;

    
    DECLARE monthly_ot_cursor CURSOR FOR
        SELECT eot.set_duration, wdt.otcomponents, wdt.day_time_seq
        FROM emp_ot_master eot
        LEFT JOIN emp_proff ep ON eot.emp_fkey = ep.emp_fkey
        LEFT JOIN working_day_time_procedures wdt ON ep.day_time_seq = wdt.day_time_seq
        WHERE eot.emp_fkey = pemp_pkey
          AND DATE_FORMAT(eot.month, '%Y-%m') = pmonth_year
          AND eot.is_verified = 'Y'
          AND wdt.otcomponents IS NOT NULL
          AND TRIM(COALESCE(wdt.otcomponents, '')) != '';

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET finished = 1;



    OPEN monthly_ot_cursor;

    ot_loop: LOOP

        FETCH monthly_ot_cursor INTO vset_duration, votcomponent, vday_time_seq;

        IF finished = 1 THEN
            LEAVE ot_loop;
        END IF;


        
        SELECT COUNT(*)
        INTO v_exists
        FROM emp_salary_structure
        WHERE emp_fkey = pemp_pkey
          AND end_date_effective IS NULL
          AND salary_head_item_fkey = votcomponent;

        IF v_exists = 0 THEN
            
            ITERATE ot_loop;
        END IF;

        
        SELECT salary_head_item_desc, structure_det_value, head_operator, head_type, item_part
        INTO vsalary_head_item_desc, vstructure_det_value, vhead_operator, vhead_type, vitem_part
        FROM emp_salary_structure 
        WHERE emp_fkey = pemp_pkey
          AND end_date_effective IS NULL
          AND salary_head_item_fkey = votcomponent
        LIMIT 1;

        
        SET vot_salary = (vset_duration / 60) * vstructure_det_value;

        IF vot_salary > 0 THEN

            INSERT INTO emp_calc_variable_components (
                emp_fkey,
                month_year,
                day_time_seq,
                salary_head_item_fkey,
                salary_head_item_desc,
                structure_det_value,
                salary_rate,
                salary_amount,
                head_operator,
                head_type,
                item_part,
                created_by,
                created_date
            )
            VALUES (
                pemp_pkey,
                pmonth_year,
                vday_time_seq,
                votcomponent,
                vsalary_head_item_desc,
                vstructure_det_value,
                vstructure_det_value,
                vot_salary,
                vhead_operator,
                vhead_type,
                vitem_part,
                pcreated_by,
                NOW()
            );
        END IF;

    END LOOP ot_loop;

    CLOSE monthly_ot_cursor;

END;;

DROP PROCEDURE IF EXISTS `calculate_salary_main_prc`;;
CREATE PROCEDURE `calculate_salary_main_prc` (IN `pmonth` varchar(20), IN `pbranch_code` varchar(30), IN `pemp_pkey` int(11), IN `ppayroll_master_pkey` int(11), IN `puser_id` varchar(30), OUT `perr_msg` varchar(2000))
begin
	declare vemp_pkey int;
	declare vfirst_name varchar(50);
	declare vDeviceId int;
	declare vjoining_date	  date;
	declare vemp_company_id	varchar(30);	 
	declare vemp_type	varchar(30);	 
	declare vdesignation	varchar(30); 
	declare vemp_dept	varchar(30);
	declare vemp_grade	varchar(30);
	declare vemp_vertical   varchar(30);
	declare vemp_branch varchar(30);	 
	declare vHOLIDAY_GROUP_ID int;	 
	declare vLEAVEPOLICY_GROUP_ID int;
	declare vday_time_seq  int;
	declare vpresant_total float;
	declare vleave_total float;
	declare vlop_total float;
	declare vwd_lop_total float;
	declare vlop_only float;
	declare vemp_anual_ctc float;
	declare vemp_monthly_ctc float ;
	declare vemp_structure_id int ;
	declare vprorate_code int;
	declare vprorate_desc varchar(50);
	declare vdefined_structure_for varchar(50);
	declare vsalary_head_item_fkey int;
	declare vsalary_head_item_desc varchar(100);
	declare vstructure_det_value float;
	declare vhead_operator varchar(20);
	declare vhead_type varchar(25);
	declare vitem_part varchar(25);
	declare vstructure_id int;
	declare vemp_salary float;
	declare vday_count float ;
	declare vattendance_date date;
	declare vmonthly_att_fromdate date;
	declare vmonthly_att_todate date;
	declare vworking_days float;
	declare vweekoff_day float;
	declare vexistcount int;
	declare vmonthly_amount float;
	declare vindirect_amount float;
	declare vtotal_deduction float;
	declare vtotal_variables float;
	declare vmonth date;
	declare vrate float;
	declare vholiday_count  float;
	declare vot_duration float;
	declare v_holiday_woff_count float;
	declare v_holiday_halfwoff_count float;
	declare vshift_allowance int;
	declare votcomponents int;
	declare vweekoff_total float;
	declare vholiday_total float;
	declare vfixed_days float;
	declare vcompany_code varchar(25);
	declare vemp_monthly_ctc1 float;
	declare vproff_tax int;
	declare vfinyear int;
	declare vtds float;
	declare vtaxable_income float;
	declare vtax_include varchar(10);
	declare vtax float;
	declare vpftax_components int;
	declare vpf_count int;
	declare vLOPonweekoffs float;
	declare vweekoff_count float;
	declare vhalfweekoff_count float;
	declare vLeavesonweekoffs float;
	declare vLOPonHolidays float;
	declare vLeavesonHolidays float;
	declare vuploaded_amount int;
	declare rec_count int;
	declare voperator  varchar(10);
	declare vsalaryamount float;
	declare vapproved_days float;
	declare vapproved_count int;
	declare vleaveencashmentkey int;
	declare vwork_time_day_off_cal_ot int;
	declare vstart_month date ;
	declare vend_month  date;
	declare vsunday float;
	declare vmessage varchar(100);
	declare vworking_time1 varchar(30);
	declare vworking_time2 varchar(30); 
	declare vminuts_calc_perday varchar(30);
	declare vdaytotal float;
	declare vleavetotal float; 
	declare vfullcnt float;
	declare vhalfcnt float;
	declare vleave_salary float;
	declare vtotal_hours float;
	declare vduration float;
	declare vsunday_allowance int;
	declare voption_type varchar(10);							  
	declare vdesignations	varchar(100); 
	declare vemp_depts	varchar(100);
	declare vemp_grades	varchar(100);
	declare vemp_verticals   varchar(100);
	declare vemp_branchs varchar(100);	
	declare vemp_sections  varchar(100);
	declare vemp_sep_priv  int;	
	declare vvertical_name varchar(100);	
	declare voccurance int;
	declare vstart_date_effective date;
	declare	vend_date_effective	date;	  
	declare vaddition_dty float;
	declare vsubdomain varchar(50);
	declare vpayroll_type varchar(10);
	declare vcalander_days int;
	declare veps varchar(30);
	declare vprobation int;
	declare vcontract_start_date  date ;
	declare vcontract_end_date  date;
	declare vcmscp_output varchar(30);
	declare vcscp_output varchar(30);
	declare vexistcount_calc_var int;
	declare vexistcount_fixed_var int;
	declare exit_loop boolean default false;
	
	declare cur cursor for
	select distinct ed.emp_pkey, concat(ed.first_name,' ',ed.last_name) as empname, ep.joining_date, ep.emp_company_id, ep.emp_type, ep.designation, ep.emp_dept, ep.emp_grade, ep.emp_vertical, ep.emp_branch, ep.HOLIDAY_GROUP_ID, ep.LEAVEPOLICY_GROUP_ID, ep.day_time_seq, ep.structure_id, ep.emp_sep_priv
	from emp_details as ed join emp_proff as ep on ed.Branch_code = ep.emp_branch and ed.emp_pkey = ep.emp_fkey
	where ed.Branch_code = pbranch_code and ed.emp_pkey = pemp_pkey and ed.status = 1 and ed.emp_pkey in
	(select emp_fkey from attendance_register where month_year = pmonth and isdelete = 'N');
	
	declare continue handler for not found set exit_loop = true;
	
	select distinct payroll_type into vpayroll_type from db_config where active = 'Y';
	
	select branch, designation, department, grade
	into vemp_branchs, vdesignations, vemp_depts, vemp_grades
	from employee_info where emp_pkey = pemp_pkey;
	
	select eps into veps from emp_details where emp_pkey = pemp_pkey;
	
	select attr2, emp_type into vprobation, vemp_type from emp_proff where emp_fkey = pemp_pkey order by emp_proff_pkey desc limit 1;
	
	if upper(vemp_type) = 'CONTRACT' then
		select count(*) into rec_count from contracted_days where emp_fkey = pemp_pkey and status = 1;
		
		if (rec_count != 0) then
			select contract_start_date, contract_end_date into vcontract_start_date, vcontract_end_date from contracted_days where emp_fkey = pemp_pkey and status = 1;
		end if;
	end if;
	
	open cur;
		start_loop: loop
			fetch cur into vemp_pkey, vfirst_name, vjoining_date, vemp_company_id, vemp_type, vdesignation, vemp_dept, vemp_grade, vemp_vertical, vemp_branch, vHOLIDAY_GROUP_id, vLEAVEPOLICY_GROUP_ID, vday_time_seq, vstructure_id, vemp_sep_priv;
			
			if exit_loop then
				leave start_loop;
			end if;
			
			select count(*) into vexistcount from emp_salary_slip where emp_fkey = vemp_pkey and month_year = pmonth and end_date_effective is null and head_type <> 'Arrear';
			
			if vexistcount > 0 then
				update emp_salary_slip set end_date_effective = current_date, modified_by = puser_id where emp_fkey = vemp_pkey and month_year = pmonth and end_date_effective is null and head_type <> 'Arrear';
			end if;
			
			select section_name into vemp_sections from section where id = vemp_sep_priv;
			
			select vertical_name into vvertical_name from verticals where vert_code = vemp_vertical;
			
			select presant_total, leave_total, lop_only, lop_total, wd_lop_total, weekoff_total, holiday_total, working_days, calander_days
			into vpresant_total, vleave_total, vlop_only, vlop_total, vwd_lop_total, vweekoff_total, vholiday_total, vworking_days, vcalander_days from attendance_register
			where emp_fkey = vemp_pkey and month_year = pmonth and isdelete = 'N';
			
			if upper(vemp_type) = 'DAILY WAGES' then
				set vlop_total = vwd_lop_total;
			elseif upper(vemp_type) <> 'HOURLY WAGES' then
				select prorate_code into vprorate_code from salary_structure where structure_id = vstructure_id and structure_active = 1;
				
				if vprorate_code = 2 then
					set vlop_total = vwd_lop_total;
				end if;
			end if;
			
			call calculate_monthly_salary_components_prc(vemp_pkey, pmonth, puser_id, vcmscp_output);
			
			insert into emp_salary_slip (payroll_master_fkey, emp_fkey, month_year, salary_head_item_fkey, salary_head_item_desc, structure_det_value, salary_rate, salary_amount, presant_total, leave_total, lop_total, head_operator, head_type, item_part, remarks, created_by, end_date_effective)
			select ppayroll_master_pkey, emp_fkey, month_year, salary_head_item_fkey, salary_head_item_desc, structure_det_value, salary_rate, salary_amount, vpresant_total, vleave_total, vlop_total, head_operator, head_type, item_part, remarks, created_by, end_date_effective
			from emp_monthly_salary_components where emp_fkey = vemp_pkey and month_year = pmonth and end_date_effective is null;
			
			select count(*) into vexistcount_calc_var from emp_calc_variable_components where emp_fkey = vemp_pkey and month_year = pmonth and end_date_effective is null;
			
			if vexistcount_calc_var > 0 then
				update emp_calc_variable_components set end_date_effective = current_date, modified_by = puser_id where emp_fkey = vemp_pkey and month_year = pmonth and end_date_effective is null;
			end if;
			
			call calculate_holiday_allowances_prc(vemp_pkey, pmonth, puser_id);
			call calculate_shift_allowance_prc(vemp_pkey, pmonth, puser_id);
			call calculate_ot_allowance_prc(vemp_pkey, pmonth, puser_id);
			call calculate_leave_encashment_prc(vemp_pkey, pmonth, puser_id);
			
			insert into emp_salary_slip (payroll_master_fkey, emp_fkey, month_year, salary_head_item_fkey, salary_head_item_desc, structure_det_value, salary_rate, salary_amount, presant_total, leave_total, lop_total, head_operator, head_type, item_part, remarks, created_by, end_date_effective)
			select ppayroll_master_pkey, emp_fkey, month_year, salary_head_item_fkey, salary_head_item_desc, structure_det_value, salary_rate, salary_amount, vpresant_total, vleave_total, vlop_total, head_operator, head_type, item_part, remarks, created_by, end_date_effective
			from emp_calc_variable_components where emp_fkey = vemp_pkey and month_year = pmonth and end_date_effective is null;
			
			select count(*) into vexistcount_fixed_var from emp_variables_upload where emp_fkey = vemp_pkey and month_year = date_format(concat(pmonth, '-01'), '%m-%Y') and status = 1 and lcase(head_type) = 'fixed';
			
			if vexistcount_fixed_var > 0 then
				update emp_variables_upload set status = 0 where emp_fkey = vemp_pkey and month_year = date_format(concat(pmonth, '-01'), '%m-%Y') and status = 1 and lcase(head_type) = 'fixed';
			end if;
			
			BLOCK2:begin
				declare exit_loop2 boolean default false;
				
				declare fixed_var_cur cursor for
				select emp_fkey, emp_structure_id, prorate_code, prorate_desc, defined_structure_for, salary_head_item_fkey, salary_head_item_desc, abs(structure_det_value), head_operator, head_type, item_part
				from emp_salary_structure where emp_fkey = vemp_pkey and end_date_effective is null and head_type = 'fixed'
				and salary_head_item_Fkey in (select salary_head_item_pkey from salary_head_items where head_fkey in (select head_pkey from salary_heads where head_pkey in (9, 10)));
				
				declare continue handler for not found set exit_loop2 = true;
				
				open fixed_var_cur;
					start_loop2: loop
						fetch fixed_var_cur into vemp_pkey, vemp_structure_id, vprorate_code, vprorate_desc, vdefined_structure_for, vsalary_head_item_fkey, vsalary_head_item_desc, vstructure_det_value, vhead_operator, vhead_type, vitem_part;
						
						if exit_loop2 then
							leave start_loop2;   
						end if;
						
						set vemp_salary = vstructure_det_value;
						
						if vprorate_code = 3 then
							select fixed_days into vfixed_days from salary_structure where structure_id = vemp_structure_id;
							
							if vfixed_days - vlop_total <= 0 then
								set vemp_salary = 0;
							end if;
						elseif vprorate_code = 2 then
							if vworking_days - vwd_lop_total <= 0 then
								set vemp_salary = 0;
							end if;
						elseif vprorate_code = 1 then
							if vcalander_days - vlop_total <= 0 then
								set vemp_salary = 0;
							end if;
						end if;
						
						insert into emp_variables_upload (emp_fkey, salary_head_item_fkey, month_year, salary_head_item_desc, uploaded_amount, head_operator, head_type, item_part, action, remarks, created_by)
						values (vemp_pkey, vsalary_head_item_fkey, date_format(concat(pmonth, '-01'), '%m-%Y'), vsalary_head_item_desc, vemp_salary, vhead_operator, 'Fixed', vitem_part, 'Salary Processing', 'Fixed component in variable section of salary structure', puser_id);
					end loop start_loop2;
				close fixed_var_cur;
			end BLOCK2;
			
			BLOCK3: begin
				declare variable_date varchar(10);
				DECLARE exit_loop3 BOOLEAN default FALSE;
				
				declare variablescur cursor for
					select emp_fkey, salary_head_item_fkey, salary_head_item_desc, sum(uploaded_amount), head_operator, head_type, item_part
					from emp_variables_upload where emp_fkey = vemp_pkey and status = 1 and month_year = variable_date
					group by emp_fkey, salary_head_item_fkey, salary_head_item_desc, head_operator, head_type, item_part;
				
				DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop3 = TRUE;
				
				set variable_date = DATE_FORMAT(concat(pmonth,'-01'), '%m-%Y');
				
				open variablescur;
					start_loop1: loop
						fetch variablescur into vemp_pkey, vsalary_head_item_fkey, vsalary_head_item_desc, vstructure_det_value, vhead_operator, vhead_type, vitem_part;
						
						IF exit_loop3 THEN
							LEAVE start_loop1;
						END IF;
						
						if lcase(vhead_operator)='addition'  then
							insert into emp_salary_slip (payroll_master_fkey,emp_fkey,	 
									month_year	,	 
									salary_head_item_fkey	,
									salary_head_item_desc,
									salary_amount ,	 
									presant_total,	 
									leave_total	,
									lop_total	,
									head_operator,
									head_type,
									item_part,action) values(ppayroll_master_pkey,vemp_pkey,pmonth ,vsalary_head_item_fkey,vsalary_head_item_desc,vstructure_det_value,
														vpresant_total,vleave_total,vlop_total,vhead_operator,vhead_type	,vitem_part,'P');
						elseif lcase(vhead_operator)='deduction'  then
							set vemp_salary = vstructure_det_value*-1;
							
							insert into emp_salary_slip (payroll_master_fkey,emp_fkey,	 
								month_year	,	 
								salary_head_item_fkey	,
								salary_head_item_desc,
								salary_amount ,	 
								presant_total,	 
								leave_total	,
								lop_total	,
								head_operator,
								head_type,
								item_part) values(ppayroll_master_pkey,vemp_pkey,pmonth ,vsalary_head_item_fkey,vsalary_head_item_desc,vemp_salary,
													vpresant_total,vleave_total,vlop_total,vhead_operator,vhead_type	,vitem_part);
						else	
							set vemp_salary = vstructure_det_value;
							
							insert into emp_salary_slip (payroll_master_fkey,emp_fkey,	 
								month_year	,	 
								salary_head_item_fkey	,
								salary_head_item_desc,
								salary_amount ,	 
								presant_total,	 
								leave_total	,
								lop_total	,
								head_operator,
								head_type,
								item_part,action) values(ppayroll_master_pkey,vemp_pkey,pmonth ,vsalary_head_item_fkey,vsalary_head_item_desc,vemp_salary,
													vpresant_total,vleave_total,vlop_total,vhead_operator,vhead_type	,vitem_part,'P');
						end if;
					end loop start_loop1;
				close variablescur;
			end BLOCK3;
			
			BLOCK4: begin
				DECLARE exit_loop4 BOOLEAN default FALSE;
				
				declare advancecur cursor for
					select emp_fkey,0 as salary_head_item_fkey,'Salary Advance' as salary_head_item_desc,advance_amount as uploaded_amount,'Deduction' as head_operator,'Fixed' as head_type,'Direct' as item_part
					from emp_advance where emp_fkey = vemp_pkey and status= 1 and affected_month = pmonth ;
				
				DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop4 = TRUE;
				
				open advancecur ;
					start_loop1: loop
						fetch advancecur into vemp_pkey, vsalary_head_item_fkey,vsalary_head_item_desc,vstructure_det_value,vhead_operator,vhead_type,vitem_part;
						
						if exit_loop4 then 
							leave start_loop1 ;   
						end if;
						
						set vemp_salary = vstructure_det_value*-1;
						
						insert into emp_salary_slip (payroll_master_fkey,emp_fkey,	 
							month_year	,	 
							salary_head_item_fkey	,
							salary_head_item_desc,
							salary_amount ,	 
							presant_total,	 
							leave_total	,
							lop_total	,
							head_operator,
							head_type,
							item_part) values(ppayroll_master_pkey,vemp_pkey,pmonth ,vsalary_head_item_fkey,vsalary_head_item_desc,vemp_salary,
												vpresant_total,vleave_total,vlop_total,vhead_operator,vhead_type	,vitem_part);
					end loop start_loop1;
				close advancecur;
			end BLOCK4;
			
			select sum(loan_emi) into vuploaded_amount from emp_loan_info
			where emp_fkey = vemp_pkey and status = 1 and loan_month = pmonth and paid_status in ('A', 'S');
			
			if (vuploaded_amount) > 0 then
				BLOCK6:begin
					DECLARE exit_loop6 BOOLEAN default FALSE;
					
					declare advancecur cursor for
						select emp_fkey,00 salary_head_item_fkey,'Loan'salary_head_item_desc,sum(loan_emi) uploaded_amount,'Deduction' head_operator,'Fixed' head_type,'Direct'item_part 	
						from emp_loan_info where emp_fkey = vemp_pkey and status= 1 and loan_month = pmonth and paid_status in ('A','S');
					
					DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop6 = TRUE;
					
					open advancecur ;
						start_loop1: loop
							fetch advancecur into vemp_pkey, vsalary_head_item_fkey,vsalary_head_item_desc,vstructure_det_value,vhead_operator,vhead_type,vitem_part;
							
							IF exit_loop6 THEN 
								LEAVE start_loop1 ;   
							END IF;
							
							if vstructure_det_value >0 then
								set vemp_salary = vstructure_det_value*-1;
									insert into emp_salary_slip (payroll_master_fkey,emp_fkey,	 
										month_year	,	 
										salary_head_item_fkey	,
										salary_head_item_desc,
										salary_amount ,	 
										presant_total,	 
										leave_total	,
										lop_total	,
										head_operator,
										head_type,
										item_part) values(ppayroll_master_pkey,vemp_pkey,pmonth ,vsalary_head_item_fkey,vsalary_head_item_desc,vemp_salary,
															vpresant_total,vleave_total,vlop_total,vhead_operator,vhead_type	,vitem_part);
							end if;
						end loop start_loop1;
					close advancecur;
				end BLOCK6;
			end if;
			
			call calculate_statutory_components_prc(vemp_pkey, pmonth, puser_id, vcscp_output);
			
			insert into emp_salary_slip (payroll_master_fkey, emp_fkey, month_year, salary_head_item_fkey, salary_head_item_desc, structure_det_value, salary_rate, salary_amount, presant_total, leave_total, lop_total, head_operator, head_type, item_part, remarks, created_by, end_date_effective)
			select ppayroll_master_pkey, emp_fkey, month_year, salary_head_item_fkey, salary_head_item_desc, structure_det_value, salary_rate, salary_amount, vpresant_total, vleave_total, vlop_total, head_operator, head_type, item_part, remarks, created_by, end_date_effective
			from emp_statutory_components where emp_fkey = vemp_pkey and month_year = pmonth and end_date_effective is null;
			
			select salary_head_item_Fkey, operator into vpftax_components, voperator from tax_salary_components where tax_salary_components_name = 'Professional Tax';
			
			select count(*) into vpf_count from emp_salary_slip where salary_head_item_fkey = vpftax_components and payroll_master_fkey = ppayroll_master_pkey and month_year = pmonth and end_date_effective is null;
			
			select ifnull(sum(salary_amount),0) into vsalaryamount from emp_salary_slip
			where emp_fkey = vemp_pkey and month_year = pmonth and end_date_effective is null;
			
			if vsalaryamount > 0 then
				if vpftax_components is not null and vpf_count = 0 then
					if voperator ='A' then
						select profession_tax_cal_fn(vemp_pkey, pmonth) into vproff_tax;
						
						insert into emp_salary_slip (payroll_master_fkey,emp_fkey,	 
									month_year	,	 
									salary_head_item_fkey	,
									salary_head_item_desc,
									salary_amount ,	 
									presant_total,	 
									leave_total	,
									lop_total	,
									head_operator,
									head_type,
									item_part,
									created_by) values(ppayroll_master_pkey,vemp_pkey,pmonth ,vpftax_components,'Professional Tax',vproff_tax*-1 ,
														vpresant_total,vleave_total,vlop_total,'Deduction','manually','Direct',puser_id);
					end if;								 
				end if;
				
				select ifnull(tax_include,'N') into vtax_include from payroll_master where payroll_master_pkey = ppayroll_master_pkey;
				
				select fin_year into vfinyear from fin_year where lcase(Year_status)='open' and BRANCH_code=pbranch_code and is_current_finyear='Y' and status=1 and vattr1=1;
				
				if vtax_include = 'Y' then
					select option_type into voption_type  from emp_tax_regime where emp_fkey=vemp_pkey  and fin_year=vfinyear and end_date_effective is null;
					
					if voption_type='O' then
						SELECT tax_salary_distribution_fn('', vemp_pkey, vfinyear, puser_id) into vtax;
						
						if vtax=1 then
							select tax_monthly_proj ,taxable_income into vtds, vtaxable_income from emp_tax_sal_trans_sum where end_date_effective is null and emp_fkey= vemp_pkey;
							
							if vtaxable_income <= 500000 then
								set vtds = 0;
							end if;	 
							
							if vtds<>0 then
								insert into emp_salary_slip (payroll_master_fkey,emp_fkey,	 
										month_year	,	 
										salary_head_item_fkey	,
										salary_head_item_desc,
										salary_amount ,	 
										presant_total,	 
										leave_total	,
										lop_total	,
										head_operator,
										head_type,
										item_part,
										created_by) values(ppayroll_master_pkey,vemp_pkey,pmonth ,82,'TDS',vtds*-1,
															0,0,0,'Deduction','Manually','Direct',puser_id);
								
								select `tax_computation_fn` (vemp_pkey, pmonth, vfinyear) into vtax;
							end if;
						end if;	
					else			
						SELECT tax_salary_distribution_new_fn('', vemp_pkey, vfinyear, puser_id) into vtax;
						
						if vtax=1 then
							select tax_monthly_proj ,taxable_income into vtds, vtaxable_income  from emp_tax_sal_trans_sum_new  where end_date_effective is null and emp_fkey= vemp_pkey;
							
							if vtaxable_income <= 1200000 then
								set vtds = 0;
							end if;
							
							if vtds<>0 then
								insert into emp_salary_slip (payroll_master_fkey,emp_fkey,	 
										month_year	,	 
										salary_head_item_fkey	,
										salary_head_item_desc,
										salary_amount ,	 
										presant_total,	 
										leave_total	,
										lop_total	,
										head_operator,
										head_type,
										item_part,
										created_by) values(ppayroll_master_pkey,vemp_pkey,pmonth ,82,'TDS',vtds*-1,
															0,0,0,'Deduction','Manually','Direct',puser_id);
												
								select `tax_computation_fn`(vemp_pkey, pmonth, vfinyear) into vtax;
							end if;
						end if;	  
					end if;	  
				end if;
			end if;
			
			select emp_derived_anualctc into vemp_anual_ctc from emp_ctc_transaction  where emp_fkey=vemp_pkey and end_date_effective is null;
			
			select round(sum( salary_amount ),2) into vmonthly_amount  from  emp_salary_slip  where (isnull( end_date_effective ) and (lcase( head_operator ) = 'addition')  and emp_fkey= vemp_pkey and month_year =pmonth ) group by  emp_fkey ,  month_year ;
			
			select round(sum( salary_amount ),2) into vindirect_amount  from  emp_salary_slip  where (isnull( end_date_effective ) and (lcase( head_operator ) = 'addition')  and lcase(item_part)= 'indirect' and emp_fkey= vemp_pkey and month_year =pmonth ) group by  emp_fkey ,  month_year ;
			
			select round(sum( salary_amount ),2) into vtotal_deduction  from  emp_salary_slip  where (isnull( end_date_effective ) and (lcase( head_operator ) = 'deduction')  and emp_fkey= vemp_pkey and month_year =pmonth ) group by  emp_fkey ,  month_year ;
			
			select round(sum( salary_amount ),2) into vtotal_variables  from  emp_salary_slip  where (isnull( end_date_effective ) and (lcase(head_type)='variable')  and emp_fkey= vemp_pkey and month_year =pmonth ) group by  emp_fkey ,  month_year ;
			
			update payroll_master set days_presant = vpresant_total, days_leave = vleave_total, loss_of_pay = vlop_total, calander_days = vcalander_days, working_days = vworking_days, week_off_days = vweekoff_total ,holidays = vholiday_total, monthly_ctc=(vemp_anual_ctc),
			monthly_amount=vmonthly_amount,   gross_salary= vmonthly_amount-ifnull(vindirect_amount,0) , total_deduction=ifnull(vtotal_deduction,0),net_salary=(gross_salary +ifnull(total_deduction,0))+ifnull(vtotal_variables,0),action='Processed' ,created_by=puser_id,total_variables=ifnull(vtotal_variables,0)
			where payroll_master_pkey=ppayroll_master_pkey and emp_fkey=vemp_pkey and month_year=pmonth;
			
			update payroll_master set 
			desig=ifnull(vdesignations,''),
			departments=ifnull(vemp_depts,''),
			grade=ifnull(vemp_grades,''),	
			branch_name =ifnull(vemp_branchs,'')
			,section =ifnull(vemp_sections,'')
			,division=ifnull(vvertical_name,''),joining_date=ifnull(vjoining_date,''),eps=ifnull(veps,''),probation=ifnull(vprobation,''),contract_start_date=ifnull(vcontract_start_date,''),
			contract_end_date=ifnull(vcontract_end_date,'')
			where payroll_master_pkey=ppayroll_master_pkey and emp_fkey=vemp_pkey and month_year=pmonth;
			
			insert into `salary_processing_audit` (`payroll_master_fkey`, `branch_code`, `emp_fkey`, `month_year`, `payroll_type`, `day_time_seq`, `HOLIDAY_GROUP_ID`, `LEAVEPOLICY_GROUP_ID`, `structure_id`, `remarks`, `created_by`)
			values (ppayroll_master_pkey, pbranch_code, pemp_pkey, pmonth, vpayroll_type, vday_time_seq, vHOLIDAY_GROUP_id, vLEAVEPOLICY_GROUP_ID, vstructure_id, 'Salary Processed', puser_id);
			
			set vmonthly_amount = 0;
			set vindirect_amount = 0;
			set vtotal_deduction = 0;
		end loop start_loop;
	close cur;
end;;

DROP PROCEDURE IF EXISTS `calculate_shift_allowance_prc`;;
CREATE PROCEDURE `calculate_shift_allowance_prc` (IN `pemp_pkey` int, IN `pmonth_year` varchar(7), IN `pcreated_by` varchar(30))
BEGIN
    
    DECLARE vfinished INT DEFAULT 0;

    DECLARE vday_time_seq INT;
    DECLARE vpresent_count DECIMAL(5,2);

    DECLARE vshift_allowance INT;
    DECLARE vstructure_det_value DECIMAL(10,2);
    DECLARE vsalary_amount DECIMAL(10,2);

    DECLARE vsalary_head_item_desc VARCHAR(250);
    DECLARE vhead_operator VARCHAR(30);
    DECLARE vhead_type VARCHAR(30);
    DECLARE vitem_part VARCHAR(30);

    DECLARE shift_cursor CURSOR FOR
        SELECT day_time_seq, present_count
        FROM tmp_shift_present
        WHERE present_count > 0;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET vfinished = 1;

    
    DROP TEMPORARY TABLE IF EXISTS tmp_shift_present;
    CREATE TEMPORARY TABLE tmp_shift_present (
        day_time_seq INT,
        present_count DECIMAL(5,2)
    );

    INSERT INTO tmp_shift_present (day_time_seq, present_count)
    SELECT
        t.shift_id,
        SUM(
            CASE
                WHEN t.attendance_value = 'P/P' THEN 1
                WHEN t.attendance_value LIKE 'P/%'
                  OR t.attendance_value LIKE '%/P'
                  THEN 0.5
                ELSE 0
            END
        )
    FROM (
        SELECT
            COALESCE(esp.shift_id, ep.day_time_seq) AS shift_id,
            CASE d.field_no
                WHEN 1  THEN ar.FIELD1
                WHEN 2  THEN ar.FIELD2
                WHEN 3  THEN ar.FIELD3
                WHEN 4  THEN ar.FIELD4
                WHEN 5  THEN ar.FIELD5
                WHEN 6  THEN ar.FIELD6
                WHEN 7  THEN ar.FIELD7
                WHEN 8  THEN ar.FIELD8
                WHEN 9  THEN ar.FIELD9
                WHEN 10 THEN ar.FIELD10
                WHEN 11 THEN ar.FIELD11
                WHEN 12 THEN ar.FIELD12
                WHEN 13 THEN ar.FIELD13
                WHEN 14 THEN ar.FIELD14
                WHEN 15 THEN ar.FIELD15
                WHEN 16 THEN ar.FIELD16
                WHEN 17 THEN ar.FIELD17
                WHEN 18 THEN ar.FIELD18
                WHEN 19 THEN ar.FIELD19
                WHEN 20 THEN ar.FIELD20
                WHEN 21 THEN ar.FIELD21
                WHEN 22 THEN ar.FIELD22
                WHEN 23 THEN ar.FIELD23
                WHEN 24 THEN ar.FIELD24
                WHEN 25 THEN ar.FIELD25
                WHEN 26 THEN ar.FIELD26
                WHEN 27 THEN ar.FIELD27
                WHEN 28 THEN ar.FIELD28
                WHEN 29 THEN ar.FIELD29
                WHEN 30 THEN ar.FIELD30
                WHEN 31 THEN ar.FIELD31
            END AS attendance_value
        FROM attendance_register ar
        JOIN (
            SELECT 1 field_no UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4
            UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8
            UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12
            UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15 UNION ALL SELECT 16
            UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL SELECT 20
            UNION ALL SELECT 21 UNION ALL SELECT 22 UNION ALL SELECT 23 UNION ALL SELECT 24
            UNION ALL SELECT 25 UNION ALL SELECT 26 UNION ALL SELECT 27 UNION ALL SELECT 28
            UNION ALL SELECT 29 UNION ALL SELECT 30 UNION ALL SELECT 31
        ) d
        LEFT JOIN emp_shift_planner esp
               ON esp.emp_fkey = ar.emp_fkey
              AND esp.month_year = ar.month_year
              AND esp.shift_date =
                  DATE_ADD(
                      att_start_end_fn(CONCAT(ar.month_year,'-01'),1),
                      INTERVAL d.field_no - 1 DAY
                  )
              AND esp.status = 1
        LEFT JOIN emp_proff ep
               ON ep.emp_fkey = ar.emp_fkey
        WHERE ar.emp_fkey = pemp_pkey
          AND ar.month_year = pmonth_year
          AND ar.isdelete = 'N'
          AND ar.branch_code IN (SELECT branch_code FROM emp_details ed WHERE ed.emp_pkey = pemp_pkey)
    ) t
    GROUP BY t.shift_id;

    
    OPEN shift_cursor;

    shift_loop: LOOP

        
        SET vfinished = 0;

        FETCH shift_cursor INTO vday_time_seq, vpresent_count;

        IF vfinished = 1 THEN
            LEAVE shift_loop;
        END IF;

        
        SET vshift_allowance = NULL;
        SET vstructure_det_value = 0;
        SET vsalary_head_item_desc = NULL;
        SET vhead_operator = NULL;
        SET vhead_type = NULL;
        SET vitem_part = NULL;

        
        SELECT
            w.shift_allowance,
            es.structure_det_value,
            es.salary_head_item_desc,
            es.head_operator,
            es.head_type,
            es.item_part
        INTO
            vshift_allowance,
            vstructure_det_value,
            vsalary_head_item_desc,
            vhead_operator,
            vhead_type,
            vitem_part
        FROM working_day_time_procedures w
        JOIN emp_salary_structure es
             ON es.salary_head_item_fkey = w.shift_allowance
            AND es.emp_fkey = pemp_pkey
            AND es.end_date_effective IS NULL
        WHERE w.day_time_seq = vday_time_seq
        LIMIT 1;

        SET vsalary_amount = IFNULL(vstructure_det_value, 0) * vpresent_count;

        IF vshift_allowance IS NOT NULL THEN

            UPDATE emp_calc_variable_components
            SET salary_amount = salary_amount + vsalary_amount,
                modified_by   = pcreated_by,
                modified_date = NOW()
            WHERE emp_fkey = pemp_pkey
              AND month_year = pmonth_year
              AND day_time_seq = vday_time_seq
              AND salary_head_item_fkey = vshift_allowance
              AND end_date_effective IS NULL;

            IF ROW_COUNT() = 0 THEN
                INSERT INTO emp_calc_variable_components (
                    emp_fkey,
                    month_year,
                    day_time_seq,
                    salary_head_item_fkey,
                    salary_head_item_desc,
                    structure_det_value,
                    salary_rate,
                    salary_amount,
                    head_operator,
                    head_type,
                    item_part,
                    remarks,
                    created_by,
                    created_date
                ) VALUES (
                    pemp_pkey,
                    pmonth_year,
                    vday_time_seq,
                    vshift_allowance,
                    vsalary_head_item_desc,
                    vstructure_det_value,
                    vstructure_det_value,
                    vsalary_amount,
                    vhead_operator,
                    vhead_type,
                    vitem_part,
                    NULL,
                    pcreated_by,
                    NOW()
                );
            END IF;

        END IF;

    END LOOP;

    CLOSE shift_cursor;

    DROP TEMPORARY TABLE tmp_shift_present;

END;;

DROP PROCEDURE IF EXISTS `calculate_statutory_components_prc`;;
CREATE PROCEDURE `calculate_statutory_components_prc` (IN `pemp_pkey` int(11), IN `pmonth` varchar(20), IN `puser_id` varchar(30), OUT `poutput` varchar(30))
begin
	declare vemp_fkey int;
	declare vexist_count int;
	declare vbranch_code varchar(30);
	declare vemp_type varchar(30);
	declare vpresant_total float;
	declare vleave_total float;
	declare vlop_total float;
	declare vwd_lop_total float;
	declare vlop_only float;
	declare vweekoff_total float;
	declare vholiday_total float;
	declare vemp_structure_id int;
	declare vprorate_code int;
	declare vsalary_head_item_fkey int;
	declare vsalary_head_item_desc varchar(100);
	declare vstructure_det_value float;
	declare vhead_operator varchar(20);
	declare vhead_type varchar(25);
	declare vitem_part varchar(25);
	declare vemp_salary float;
	declare vworking_days float;
	declare vemp_monthly_ctc float;
	declare vemp_monthly_ctc1 float;
	declare vrate float;
	declare vfixed_days float;
	declare vworking_time1 varchar(30);
	declare vworking_time2 varchar(30);
	declare vdaytotal float;
	declare vtotal_hours float;
	declare vduration float;
	declare vcalander_days int;
	declare voutput_count int;
	declare vstructure_id int;
	declare vleave_salary float;
	declare vmessage varchar(100);
	declare vpayroll_type varchar(10);
	declare vfrom_date date;
	declare vto_date date;
	declare vm_calander_days float;
	declare vm_working_days float;
	declare vm_weekoff_total float;
	declare vm_holiday_total float;
	
	declare exit_loop boolean default false;
	
	declare structurecur cursor for
	select emp_fkey, emp_structure_id, prorate_code, salary_head_item_fkey, salary_head_item_desc, structure_det_value, head_operator, head_type, item_part from emp_salary_structure 
	where emp_fkey = pemp_pkey and end_date_effective is null and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items where head_fkey in (select head_pkey from salary_heads where head_pkey in (4, 5)));
	
	declare continue handler for not found set exit_loop = true;
	
	select count(*) into vexist_count from emp_statutory_components where emp_fkey = pemp_pkey and month_year = pmonth and end_date_effective is null;
	
	if vexist_count > 0 then
		update emp_statutory_components set end_date_effective = current_date, modified_by = puser_id where emp_fkey = pemp_pkey and month_year = pmonth and end_date_effective is null;
	end if;
	
	select emp_type, structure_id into vemp_type, vstructure_id from emp_proff where emp_fkey = pemp_pkey order by emp_proff_pkey desc limit 1;
	
	select branch_code, presant_total, leave_total, lop_only, lop_total, wd_lop_total, weekoff_total, holiday_total, working_days, calander_days
	into vbranch_code, vpresant_total, vleave_total, vlop_only, vlop_total, vwd_lop_total, vweekoff_total, vholiday_total, vworking_days, vcalander_days from attendance_register 
	where emp_fkey = pemp_pkey and month_year = pmonth and isdelete = 'N';
	
	if upper(vemp_type) = 'DAILY WAGES' then
		select emp_anual_ctc into vemp_monthly_ctc  
		from emp_ctc_transaction where emp_fkey = pemp_pkey and end_date_effective is null;
		
		set vemp_monthly_ctc = vemp_monthly_ctc * vpresant_total;
		set vemp_monthly_ctc1 = vemp_monthly_ctc * vpresant_total;
	elseif upper(vemp_type) = 'HOURLY WAGES' then
		select working_time1, working_time2 into vworking_time1, vworking_time2 from working_day_time_procedures
		where day_time_seq in (select day_time_seq from emp_proff where emp_fkey = pemp_pkey);
		
		if vworking_time2 > 0 then
			set vdaytotal = (vworking_time1 + vworking_time2) / 60;
        else
			set vdaytotal = vworking_time1 / 60;
        end if;
		
        select emp_anual_ctc into vemp_monthly_ctc  
		from emp_ctc_transaction where emp_fkey = pemp_pkey and end_date_effective is null;
		
		set vleave_salary = (ifnull(vleave_total, 0) * ifnull(vdaytotal, 0)) * vemp_monthly_ctc;
		
		select sum(duration) / 60 into vduration from emp_detail_timeattandance
		where emp_pkey = pemp_pkey and yearmonth in (select date_format(concat(month_year, '-01'), '%Y-%m-01')
		from attendance_register where emp_fkey = pemp_pkey and isdelete = 'N' and month_year = pmonth);
		
		set vtotal_hours = ifnull(vduration, 0) + (ifnull(vleave_total, 0) * ifnull(vdaytotal, 0));
		set vemp_monthly_ctc = vduration * vemp_monthly_ctc;
		set vemp_monthly_ctc = ifnull(vemp_monthly_ctc, 0) + vleave_salary;
		set vemp_monthly_ctc1 = vemp_monthly_ctc;
		
		select site_sal_structure_distribution_fn(vbranch_code, pemp_pkey, vstructure_id, vemp_monthly_ctc, puser_id) into vmessage;
	else
		select emp_anual_ctc / 12 into vemp_monthly_ctc from emp_ctc_transaction where emp_fkey = pemp_pkey and end_date_effective is null;
		
		set vemp_monthly_ctc1 = vemp_monthly_ctc;
	end if;
	
	open structurecur;
		start_loop: loop
			fetch structurecur into vemp_fkey, vemp_structure_id, vprorate_code, vsalary_head_item_fkey, vsalary_head_item_desc, vstructure_det_value, vhead_operator, vhead_type, vitem_part;
			
			if exit_loop then 
				leave start_loop ;   
			end if;
			
			select distinct payroll_type into vpayroll_type from db_config where active = 'Y';
			
			if vpayroll_type = 'M' then
				set vfrom_date = date_format(concat(pmonth, '-01'), '%Y-%m-01');
				set vto_date = last_day(vfrom_date);
				
				call get_policy_weekoff_holiday_count_prc(pemp_pkey, vfrom_date, vto_date, vm_weekoff_total, vm_holiday_total);
				
				set vm_calander_days = day(vto_date);
				set vm_working_days = vm_calander_days - (vm_weekoff_total + vm_holiday_total);
				
				if upper(vemp_type) = 'DAILY WAGES' then
					if vwd_lop_total = vworking_days then
						if vm_working_days > vworking_days then
							set vwd_lop_total = vm_working_days;
						end if;
					end if;
				elseif upper(vemp_type) <> 'HOURLY WAGES' then
					if vprorate_code = 3 then
						select fixed_days into vfixed_days from salary_structure where structure_id = vemp_structure_id;
						
						if vlop_total = vcalander_days then
							if vfixed_days > vcalander_days then
								set vlop_total = vfixed_days;
							end if;
						end if;
					elseif vprorate_code = 2 then
						if vwd_lop_total = vworking_days then
							if vm_working_days > vworking_days then
								set vwd_lop_total = vm_working_days;
							end if;
						end if;
					elseif vprorate_code = 1 then
						if vlop_total = vcalander_days then
							if vm_calander_days > vcalander_days then
								set vlop_total = vm_calander_days;
							end if;
						end if;
					end if;
				end if;
				
				set vcalander_days = vm_calander_days;
				set vworking_days = vm_working_days;
				set vweekoff_total = vm_weekoff_total;
				set vholiday_total = vm_holiday_total;
			end if;
			
			if upper(vemp_type) = 'DAILY WAGES' then
				if lcase(vhead_type) != 'fixed' then
					if vworking_days >= vwd_lop_total then
						set vrate = vworking_days - vwd_lop_total;
					else
						set vrate = 0;
					end if;
					
					set vemp_salary = vstructure_det_value * vrate;
				else
					set vemp_salary = vstructure_det_value; 
				end if;
				
				insert into emp_statutory_components (emp_fkey, month_year, salary_head_item_fkey, salary_head_item_desc, structure_det_value, salary_rate, salary_amount, head_operator, head_type, item_part, created_by)
				values (vemp_fkey, pmonth, vsalary_head_item_fkey, vsalary_head_item_desc, (vstructure_det_value/vrate), vstructure_det_value, vemp_salary, vhead_operator, vhead_type, vitem_part, puser_id);
			elseif upper(vemp_type) = 'HOURLY WAGES' then
				set vemp_salary = vstructure_det_value;
				
				if lcase(vhead_type) != 'fixed' then
					insert into emp_statutory_components (emp_fkey, month_year, salary_head_item_fkey, salary_head_item_desc, structure_det_value, salary_rate, salary_amount, head_operator, head_type, item_part, created_by)
					values (vemp_fkey, pmonth, vsalary_head_item_fkey, vsalary_head_item_desc, (vstructure_det_value/vtotal_hours), vstructure_det_value, vemp_salary, vhead_operator, vhead_type, vitem_part, puser_id);
				else
					insert into emp_statutory_components (emp_fkey, month_year, salary_head_item_fkey, salary_head_item_desc, structure_det_value, salary_rate, salary_amount, head_operator, head_type, item_part, created_by)
					values (vemp_fkey, pmonth, vsalary_head_item_fkey, vsalary_head_item_desc, vemp_salary, vstructure_det_value, vemp_salary, vhead_operator, vhead_type, vitem_part, puser_id);
				end if;
			else
				if lcase(vhead_type) != 'fixed' then
					if vprorate_code = 3 then
						select fixed_days into vfixed_days from salary_structure where structure_id = vemp_structure_id;
						
						if vfixed_days >= vlop_total then
							set vrate = vfixed_days - vlop_total;
						else
							set vrate = 0;
						end if;
						
						set vemp_salary = (vstructure_det_value / vfixed_days) * vrate;
					elseif vprorate_code = 2 then
						if vworking_days >= vwd_lop_total then
							set vrate = vworking_days - vwd_lop_total;
						else
							set vrate = 0;
						end if;
						
						set vemp_salary = (vstructure_det_value / vworking_days) * vrate;
					elseif vprorate_code = 1 then
						if vcalander_days >= vlop_total then
							set vrate = vcalander_days - vlop_total;
						else
							set vrate = 0;
						end if;
						
						set vemp_salary = (vstructure_det_value / vcalander_days) * vrate;
					end if;
				else
					set vemp_salary = vstructure_det_value;
					
					if vprorate_code = 3 then
						if vfixed_days - vlop_total <= 0 then
							set vemp_salary = 0;
						end if;
					elseif vprorate_code = 2 then
						if vworking_days - vwd_lop_total <= 0 then
							set vemp_salary = 0;
						end if;
					elseif vprorate_code = 1 then
						if vcalander_days - vlop_total <= 0 then
							set vemp_salary = 0;
						end if;
					end if;
				end if;
				
				insert into emp_statutory_components (emp_fkey, month_year, salary_head_item_fkey, salary_head_item_desc, structure_det_value, salary_rate, salary_amount, head_operator, head_type, item_part, created_by)
				values (vemp_fkey, pmonth, vsalary_head_item_fkey, vsalary_head_item_desc, vstructure_det_value, vstructure_det_value, vemp_salary, vhead_operator, vhead_type, vitem_part, puser_id);
			end if;
		end loop start_loop;
	close structurecur;
	
	block2: begin
		declare vhead_fkey int;
		declare vstructure_det_depends  float;
		declare vstructure_formula varchar(500);
		declare vstructure_derived_perc float;
		declare vsalary_head_item_fkey1 int;
		declare vsalary_head_item_desc1 varchar(500);
		declare vsalary_amount1  float;
		declare vnewformula varchar(1000);
		declare vformula_value float;
		declare vstructure_det_calequation varchar(500);
		
		declare exit_loop2 boolean default false;
		
		declare formula_cur cursor for
		select shi.head_fkey, ssd.salary_head_item_fkey, trim(shi.item), ssd.structure_det_operator, ssd.structure_det_value, ssd.structure_det_depends, ssd.structure_formula, ssd.structure_derived_perc, ssd.structure_det_calequation
		from salary_structure_details as ssd join salary_head_items as shi on ssd.salary_head_item_fkey = shi.salary_head_item_pkey
		where ssd.structure_id = vstructure_id and shi.head_fkey in (4,5) and upper(ssd.structure_formula) rlike '[A-Z]';
		
		declare continue handler for not found set exit_loop2 = true;
		
		open formula_cur;
			start_loop2: loop
				fetch formula_cur into vhead_fkey, vsalary_head_item_fkey, vsalary_head_item_desc, vhead_operator, vstructure_det_value, vstructure_det_depends, vstructure_formula, vstructure_derived_perc, vstructure_det_calequation;
				
				if exit_loop2 then 
					leave start_loop2 ;   
				end if;
				
				set vnewformula = vstructure_det_calequation;
				
				block20:begin
					declare exit_loop20 boolean default false;
					
					declare replacement_cur cursor for
					select salary_head_item_fkey, trim(salary_head_item_desc) as salary_head_item_desc, salary_amount from emp_salary_slip
					where emp_fkey = pemp_pkey and month_year = pmonth and end_date_effective is null and salary_amount <> 0
					union
					select ssd.salary_head_item_fkey, trim(shi.item) as salary_head_item_desc, 0 as salary_amount
					from salary_structure_details as ssd join salary_head_items as shi on ssd.salary_head_item_fkey = shi.salary_head_item_pkey
					where ssd.structure_id = vstructure_id and ssd.salary_head_item_fkey not in (select salary_head_item_fkey from emp_salary_slip
					where emp_fkey = pemp_pkey and month_year = pmonth and end_date_effective is null and salary_amount <> 0)
					order by 1 desc;
					
					declare continue handler for not found set exit_loop20 = true;
					
					open replacement_cur;
						start_loop20: loop
							fetch replacement_cur into vsalary_head_item_fkey1,vsalary_head_item_desc1,vsalary_amount1 ;
							
							if exit_loop20 then 
								leave start_loop20;   
							end if;
							
							set vnewformula = replace(vnewformula, concat(vsalary_head_item_fkey1, '_', replace(replace(replace(vsalary_head_item_desc1, ' ', '_'), '(', '_'), ')', '_')), vsalary_amount1);
						end loop start_loop20;
						
						select sum(salary_amount) into vemp_monthly_ctc from emp_salary_slip
						where emp_fkey = pemp_pkey and month_year = pmonth and end_date_effective is null and lower(head_operator) = 'addition' and lower(item_part) = 'direct'
						group by emp_fkey, month_year;
						
						set vnewformula = replace(vnewformula, 'monthsal', vemp_monthly_ctc);
						set vnewformula = replace(vnewformula, '. ', '.');
						set vnewformula = replace(vnewformula, ' .', '.');
						
						update emp_statutory_components set remarks = vnewformula
						where salary_head_item_fkey = vsalary_head_item_fkey and emp_fkey = pemp_pkey and month_year = pmonth and end_date_effective is null;
						
						set vnewformula = null;
						set vhead_fkey = null;
						set vsalary_head_item_fkey = null;
						set vsalary_head_item_desc = null;
						set vhead_operator = null;
						set vstructure_det_value = null;
						set vstructure_det_depends = null;
						set vstructure_formula = null;
						set vstructure_det_calequation = null;
						set vstructure_derived_perc = null;
					close replacement_cur;
				end block20;
			end loop start_loop2;
		close formula_cur;
	end block2;
	
	block3: begin
		declare vhead_fkey int;
		declare vstructure_det_depends  float;
		declare vstructure_formula varchar(600);
		declare vstructure_derived_perc float;
		declare vsalary_head_item_fkey1 int;
		declare vsalary_head_item_desc1 varchar(600);
		declare vsalary_amount1  float;
		declare vnewformula varchar(200);
		declare vformula_value float;
		declare vremarks varchar(1000);
		declare vremarks1 varchar(1000);
		declare vstructure_det_calequation varchar(600);
		
		declare exit_loop3 boolean default false;
		
		declare structure_cur cursor for
		select shi.head_fkey, ssd.salary_head_item_fkey, trim(shi.item), ssd.structure_det_operator, ssd.structure_det_value, ssd.structure_det_depends, ssd.structure_formula, ssd.structure_derived_perc, ssd.structure_det_calequation
		from salary_structure_details as ssd join salary_head_items as shi on ssd.salary_head_item_fkey = shi.salary_head_item_pkey
		where ssd.structure_id = vstructure_id;
		
		declare continue handler for not found set exit_loop3 = true;
		
		open structure_cur;
			start_loop3: loop
				fetch structure_cur into vhead_fkey, vsalary_head_item_fkey, vsalary_head_item_desc, vhead_operator, vstructure_det_value, vstructure_det_depends, vstructure_formula, vstructure_derived_perc, vstructure_det_calequation;
			
				if exit_loop3 then 
					leave start_loop3;   
				end if;
				
				set vnewformula = vstructure_det_calequation;
				
				block30:begin
					declare exit_loop30 boolean default false;
					
					declare self_ref_cur cursor for 
					select salary_head_item_fkey, trim(salary_head_item_desc) as salary_head_item_desc, salary_amount, remarks
					from emp_statutory_components where emp_fkey = pemp_pkey and month_year = pmonth and end_date_effective is null and upper(remarks) rlike '[A-Z]'
					order by 1 desc;
					
					declare continue handler for not found set exit_loop30 = true;
					
					open self_ref_cur;
						start_loop30: loop
							fetch self_ref_cur into vsalary_head_item_fkey1, vsalary_head_item_desc1, vsalary_amount1, vremarks;
							
							if exit_loop30 then 
								leave start_loop30;
							end if;
							
							if instr(vremarks, concat(vsalary_head_item_fkey, '_', replace(replace(replace(vsalary_head_item_desc, ' ', '_'), '(', '_'), ')', '_'))) > 0 then
								update emp_statutory_components set remarks = replace(remarks, concat(vsalary_head_item_fkey, '_', replace(replace(replace(vsalary_head_item_desc, ' ', '_'), '(', '_'), ')', '_')), '0')
								where salary_head_item_fkey = vsalary_head_item_fkey1 and emp_fkey = pemp_pkey 
								and month_year = pmonth and end_date_effective is null;
							end if;
						end loop start_loop30;
					close self_ref_cur;
				end block30;
			end loop start_loop3;
		close structure_cur;
	end block3;
	
	block4: begin
		declare vsalary_head_item_fkey int;
		declare vremarks varchar(1000);
		declare vhead_operator varchar(20);
		declare vemp_salary float;
		
		declare exit_loop4 boolean default false;
		
		declare formula_eval_cur cursor for
        select salary_head_item_fkey, trim(remarks) as remarks, head_operator from emp_statutory_components
        where emp_fkey = pemp_pkey and month_year = pmonth and end_date_effective is null
		and trim(remarks) regexp '^[0-9.(].*[0-9.)]$' and trim(remarks) regexp '^[0-9.() +*/-]+$' and not trim(remarks) regexp '[+*/]{2,}' and not trim(remarks) regexp '[+*/-][ ]*[+*/]'
		and not trim(remarks) regexp '[+*/-][ ]*$' and not trim(remarks) regexp '^[ ]*[+*/]' and not trim(remarks) regexp '\\.{2,}' and not trim(remarks) regexp '[0-9][ ]+[0-9]'
		and (length(trim(remarks)) - length(replace(trim(remarks), '(', ''))) = (length(trim(remarks)) - length(replace(trim(remarks), ')', '')));
		
		declare continue handler for not found set exit_loop4 = true;
		
		open formula_eval_cur;
			start_loop4: loop
				fetch formula_eval_cur into vsalary_head_item_fkey, vremarks, vhead_operator;
				
				if exit_loop4 then 
					leave start_loop4; 
				end if;
				
				if vremarks is not null and vremarks != '' then
					block40: begin
						declare continue handler for sqlexception
						begin
							set @salary = null;
							set vemp_salary = null;
						end;
						
						set @sql_query = concat('select (', vremarks, ') into @salary');
						prepare stmt from @sql_query;
						execute stmt;
						deallocate prepare stmt;
						set vemp_salary = @salary;
						set @salary = null;
					end block40;
					
					if vemp_salary is not null then
						if vhead_operator = 'Deduction' then
							set vemp_salary = vemp_salary * -1;
						end if;
						
						update emp_statutory_components set salary_rate = vemp_salary, salary_amount = vemp_salary
						where emp_fkey = pemp_pkey and month_year = pmonth and salary_head_item_fkey = vsalary_head_item_fkey and end_date_effective is null;
					end if;
				end if;
				
				set vsalary_head_item_fkey = null;
				set vremarks = null;
				set vhead_operator = null;
				set vemp_salary = null;
			end loop start_loop4;
		close formula_eval_cur;
	end block4;
	
	block5: begin
		declare vesi_head_item_fkey int;
		declare vesi_head_operator varchar(20);
		declare vesi_salary_rate float;
		declare vesi_salary_amount float;
		declare exit_loop5 boolean default false;
		
		declare esi_round_cur cursor for
		select salary_head_item_fkey, head_operator, salary_rate, salary_amount
		from emp_statutory_components
		where emp_fkey = pemp_pkey and month_year = pmonth and end_date_effective is null
		and lower(trim(salary_head_item_desc)) in ('esi', 'esi - employer contribution', 'esi - employee contribution');
		
		declare continue handler for not found set exit_loop5 = true;
		
		open esi_round_cur;
			start_loop5: loop
				fetch esi_round_cur into vesi_head_item_fkey, vesi_head_operator, vesi_salary_rate, vesi_salary_amount;
				
				if exit_loop5 then
					leave start_loop5;
				end if;
				
				if vesi_head_operator = 'Deduction' then
					set vesi_salary_rate   = ceil(abs(vesi_salary_rate)) * -1;
					set vesi_salary_amount = ceil(abs(vesi_salary_amount)) * -1;
				else
					set vesi_salary_rate   = round(vesi_salary_rate);
					set vesi_salary_amount = round(vesi_salary_amount);
				end if;
				
				update emp_statutory_components
				set salary_rate = vesi_salary_rate, salary_amount = vesi_salary_amount
				where salary_head_item_fkey = vesi_head_item_fkey and emp_fkey = pemp_pkey
				and month_year = pmonth and end_date_effective is null;
				
				set vesi_head_item_fkey  = null;
				set vesi_head_operator   = null;
				set vesi_salary_rate     = null;
				set vesi_salary_amount   = null;
			end loop start_loop5;
		close esi_round_cur;
	end block5;
	
	block6: begin
		declare vsalary_head_item_fkey int;
		declare vstructure_det_value float;
		declare vsalary_amount float;
		declare vhead_type varchar(25);
		declare vhead_operator varchar(20);
		declare vitem_value float;
		declare vlimited_amount float;
		
		declare exit_loop6 boolean default false;
		
		declare limit_cur cursor for
		select salary_head_item_fkey, structure_det_value, round(salary_amount), head_type, head_operator from emp_statutory_components
		where emp_fkey = pemp_pkey and month_year = pmonth and head_type in ('limit_wl', 'limit_wg') and end_date_effective is null and salary_amount <> 0
		order by 1 desc;
		
		declare continue handler for not found set exit_loop6 = true;
		
		open limit_cur;
			start_loop6: loop
				fetch limit_cur into vsalary_head_item_fkey, vstructure_det_value, vsalary_amount, vhead_type, vhead_operator;
				
				if exit_loop6 then 
					leave start_loop6;   
				end if;
				
				select structure_det_depends into vitem_value from salary_structure_details 
				where salary_head_item_fkey = vsalary_head_item_fkey and structure_id = vstructure_id;
				
				if vitem_value is null or vitem_value = 0 then
					set vitem_value = vstructure_det_value;
				end if;
				
				if vhead_type = 'limit_wl' then
					set vlimited_amount = least(abs(vitem_value), abs(vsalary_amount));
				elseif vhead_type = 'limit_wg' then
					set vlimited_amount = greatest(abs(vitem_value), abs(vsalary_amount));
				end if;
				
				if vhead_operator = 'Deduction' then
					set vlimited_amount = vlimited_amount * -1;
				end if;
				
				update emp_statutory_components set salary_amount = round(vlimited_amount)  
				where salary_head_item_fkey = vsalary_head_item_fkey and emp_fkey = pemp_pkey and month_year = pmonth and end_date_effective is null;
				
				set vitem_value = null;
				set vsalary_head_item_fkey = null;
				set vstructure_det_value = null;
				set vsalary_amount = null;
				set vhead_type = null;
				set vhead_operator = null;
				set vlimited_amount = null;
			end loop start_loop6;
		close limit_cur;
	end block6;
	
	select count(*) into voutput_count from emp_statutory_components where emp_fkey = pemp_pkey and month_year = pmonth and end_date_effective is null;
	
	if voutput_count > 0 then
		set poutput = 'success';
	else
		set poutput = 'failure';
	end if;
end;;

DROP PROCEDURE IF EXISTS `carryforward_insert_prc`;;
CREATE PROCEDURE `carryforward_insert_prc` (IN `pfin_year` varchar(30), OUT `perr_msg` varchar(30))
begin
declare vemp_leave_balance_year_pkey int;
declare vsalary_head_item_fkey int;
declare vfin_year varchar(30);
declare vstart_date date;
declare vend_date date;
declare vemp_fkey int;

declare exit_loop boolean default false;

declare cur cursor for 
select emp_leave_balance_year_pkey, emp_fkey, salary_head_item_fkey, fin_year
from emp_leave_balance_year
where status = 1 and fin_year = pfin_year;

declare continue handler for not found set exit_loop = true;

open cur;
start_loop: loop
	fetch cur into vemp_leave_balance_year_pkey, vemp_fkey, vsalary_head_item_fkey, vfin_year;
	
	if exit_loop then
		leave start_loop;
	end if;
	
	if substr(vfin_year,5,1) = '-' then
		select att_start_end_fn(date_add(vfin_year, interval 1 month), 1) into vstart_date;
		select att_start_end_fn(date_add(vfin_year, interval 1 month), 2) into vend_date;
		
		update emp_leave_balance_year set leave_cycle_start_date = vstart_date, leave_cycle_end_date = vend_date
		where emp_leave_balance_year_pkey = vemp_leave_balance_year_pkey;
	else
		select start_month, end_month into vstart_date, vend_date
		from fin_year where fin_year = vfin_year and vattr1 = 0
		and status = 1 and branch_code in (select branch_code from emp_details where emp_pkey = vemp_fkey);
		
		update emp_leave_balance_year set leave_cycle_start_date = vstart_date, leave_cycle_end_date = vend_date
        where emp_leave_balance_year_pkey = vemp_leave_balance_year_pkey;
	end if;
end loop start_loop;
close cur;

set perr_msg = 'OK';
end;;

DROP FUNCTION IF EXISTS `check_fn`;;
CREATE FUNCTION `check_fn` (`pcompany_code ` varchar(20), `PBranch_code` varchar(20), `Puserid` varchar(20), `Pmonth` date) RETURNS varchar(100) CHARACTER SET 'latin1' LANGUAGE SQL
begin

declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
declare vholidayId int;
declare vdaytimeId int;
declare vHOLIDAYDATE  date;
DECLARE l_sql VARCHAR(4000);
DECLARE nday int;
DECLARE yearmonth varchar(30);
DECLARE vworking_days  int;
DECLARE vatt_date  date;
DECLARE vsunday  char(1);
DECLARE vmonday  char(1);
DECLARE vtuesday  char(1);
DECLARE vwednesday  char(1);
DECLARE vthursday  char(1);
DECLARE vfriday  char(1);
DECLARE vsaturday  char(1);
declare i int;
DECLARE exit_loop1 BOOLEAN default FALSE;
declare vleave_session int;
declare vleave_date date;
DECLARE exit_loop BOOLEAN default FALSE;
declare vmonthly_att_fromdate date;
declare vmonthly_att_todate date;
declare vatt_count int;
declare vattendance_date int;
declare vLOGDATE_intime datetime;
declare vLOGDATE_outime datetime;
declare vduration int;
declare vminuts_calc_perday int;
declare vsetvalue varchar(10);
declare vexistvalue varchar(10);
declare vminutes_per_half int;


declare branch_cur cursor for
   select Branch_code from branches
      where ifnull(pBranch_code,Branch_code)=Branch_code and company_code=pcompany_code;

declare cur cursor for
select emp_pkey,first_name from emp_details where company_code= pcompany_code and Branch_code=pBranch_code
  and emp_pkey in (select emp_fkey from emp_proff where date_format(joining_date,'%Y-%m-%d') <= vmonthly_att_todate  and day_time_seq is not null)
 and emp_pkey not in (select emp_fkey from attendance_register where isdelete='N' and month_year=yearmonth) ;

declare att_cur cursor for   
   select distinct emp_pkey,date_format(LOGDATE,'%Y-%m-%d')   
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 

 and lcase(c1)='in' and ucase(att.status)='Y'
and date_format(LOGDATE,'%Y-%m-%d') between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d')
 and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d') 
and emp_pkey not in (select emp_fkey from attendance_register where isdelete='N' and month_year=yearmonth)
and emp_pkey in (select emp_fkey from emp_proff where date_format(joining_date,'%Y-%m-%d') <= vmonthly_att_todate and day_time_seq is not null) 
 and att.company_code= pcompany_code order by 1;
 


SET yearmonth =DATE_FORMAT(Pmonth,'%Y-%m');

select distinct attendance_date into vattendance_date
                           from db_config where company_code= pcompany_code and active='Y';

if vattendance_date =0 then

set vmonthly_att_fromdate =DATE_FORMAT(Pmonth, '%Y-%m-01');
set vmonthly_att_todate =LAST_DAY(DATE_FORMAT(Pmonth, '%Y-%m-%d'));
else
   set vmonthly_att_fromdate =date_format(DATE_SUB(concat(DATE_FORMAT(DATE_SUB(Pmonth,INTERVAL 1 month), '%Y-%m-'),date_format(last_day(DATE_SUB(Pmonth,INTERVAL 1 month)),'%d')),INTERVAL vattendance_date day),'%Y-%m-%d');  
                      



set vmonthly_att_todate =DATE_SUB(concat(DATE_FORMAT(Pmonth, '%Y-%m-'),date_format(last_day(Pmonth),'%d')),INTERVAL vattendance_date day);
 
 




end if ;

 delete from attendance_register where  month_year=yearmonth 
    and company_code=Pcompany_code and Branch_code=PBranch_code and userid=puserid and isdelete='Y';
  insert into attendance_register (company_code,branch_code,emp_fkey,month_year,emp_name,userid)
   values(Pcompany_code,PBranch_code,1111111,yearmonth ,'AAA',puserid );
open cur;
start_loop: loop
    fetch cur into vemp_pkey,vfirst_name;
   IF exit_loop THEN   LEAVE start_loop;     END IF; 
   insert into attendance_register (company_code,branch_code,emp_fkey,month_year,emp_name,userid)
   values(Pcompany_code,PBranch_code,vemp_pkey,yearmonth ,vfirst_name,puserid );
 



 
end loop start_loop;
close cur;

return 'OK';
end;;

DROP PROCEDURE IF EXISTS `copy_salary_structure_to_new`;;
CREATE PROCEDURE `copy_salary_structure_to_new` (IN `vemp_fkey` int)
BEGIN
    
    UPDATE emp_new_salary_structure
    SET end_date_effective = CURDATE()
    WHERE emp_fkey = vemp_fkey AND end_date_effective IS NULL;

    
    INSERT INTO emp_new_salary_structure (
        emp_fkey,
        emp_structure_id,
        prorate_code,
        prorate_desc,
        defined_structure_for,
        salary_head_item_fkey,
        salary_head_item_desc,
        structure_det_value,
        creation_date,
        head_operator,
        head_type,
        item_part,
        end_date_effective,
        created_by,
        modified_by,
        remarks
    )
    SELECT 
        emp_fkey,
        emp_structure_id,
        prorate_code,
        prorate_desc,
        defined_structure_for,
        salary_head_item_fkey,
        salary_head_item_desc,
        structure_det_value,
        NOW(), 
        head_operator,
        head_type,
        item_part,
        NULL AS end_date_effective,
        created_by,
        modified_by,
        remarks
    FROM emp_salary_structure
    WHERE emp_fkey = vemp_fkey AND end_date_effective IS NULL;

END;;

