select emp_id  into vemp_id from emp_details where emp_pkey=vemp_fkey;
 update emp_salcomp_upload set status=0 where emp_id =vemp_id;
	
  
 
 end loop start_loop1;
 close empcur;
 end BLOCK4;
 

 
 
 

  
  set pmessage='Success';
end;;

