  where lcase(head_operator)='addition' and lcase(item_part)= 'direct' and end_date_effective is null
  and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items where head_fkey=1) and lcase(head_type)<>'manually'
 and emp_fkey=vemp_fkey group by emp_fkey;
 

 
update emp_ctc_transaction set emp_derived_anualctc=vderived_ctc ,emp_anual_ctc=vemp_anual_ctc,ctc_upload_type=2 where emp_fkey=vemp_fkey and end_date_effective is null;
 

select emp_id  into vemp_id from emp_details where emp_pkey=vemp_fkey;
 update emp_salcomp_upload set status=0 where emp_id =vemp_id;
	
  
 
 end loop start_loop1;
 close empcur;
 end BLOCK4;
 

 
 
 

  
  set pmessage='Success';
 end;;

DROP FUNCTION IF EXISTS `customer_visit_history_fn`;;
CREATE FUNCTION `customer_visit_history_fn` (`pemp_pkey` int) RETURNS varchar(100) CHARACTER SET 'latin1' LANGUAGE SQL
READS SQL DATA
    DETERMINISTIC
begin

declare vemp_pkey int;
declare vatt_date  datetime;
declare vemp_count int;
declare vcompany_code varchar(30);
declare vbranch_code varchar(30);
declare vemp_id varchar(30);
declare Pyear_month varchar(20);
declare vuser_id varchar(50);
declare vcustomer_name varchar(200);
declare vmob_user_locations_pkey int;
declare vmob_user_locations_pkey1 int;
declare vmob_user_locations_pkey2 int;
declare vstepinout varchar(50);
declare vpurpose  varchar(200);
declare vuploaded_time datetime;
declare vcreated_time datetime;
declare voutexist  int;
declare vlatitude  varchar(100);
declare vlongitude  varchar(100);
declare vlocation  varchar(500);
declare vcount int;  
DECLARE exit_loop1 BOOLEAN default FALSE;

declare att_cur cursor for   
  select mob_user_locations_pkey,uc.emp_fkey ,mul.user_id ,customer_name,created_time 
  from user_credentials uc ,mob_user_locations mul
  where 
   stepinout ='OUT' and uc.user_id=mul.user_id and mob_user_locations_pkey not in 
  (select mob_user_locations_pkey from cus_visit_locations)
  order by user_id,customer_name,created_time desc;


DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;

open att_cur;
att_loop: loop
    fetch att_cur into vmob_user_locations_pkey,vemp_pkey,vuser_id,vcustomer_name,vatt_date;

  IF exit_loop1 THEN LEAVE att_loop;
  END IF;
 select count(*) into voutexist from  cus_visit_locations where emp_fkey=vemp_pkey and mob_user_locations_pkey=vmob_user_locations_pkey ;
 insert into test(field1,field2) values(vmob_user_locations_pkey,'out');
 if voutexist= 0 then
  select latitude,longitude,location,stepinout,uploaded_time,customer_name,purpose
  into vlatitude,vlongitude,vlocation,vstepinout,vuploaded_time,vcustomer_name,vpurpose
  from mob_user_locations where mob_user_locations_pkey=vmob_user_locations_pkey ;
  
 INSERT INTO cus_visit_locations ( mob_user_locations_pkey, emp_fkey, user_id,stepout_time,
     stepout_latitude, stepout_longitude, stepout_location, stepout_uploaded_time, action3, customer_name3, purpose) VALUES
  (vmob_user_locations_pkey,vemp_pkey, vuser_id,vatt_date,vlatitude,vlongitude,vlocation,vuploaded_time,'OUT',vcustomer_name,vpurpose); 
 end if; 

 
 select mob_user_locations_pkey,latitude,longitude,location,stepinout,uploaded_time,customer_name,purpose,created_time
  into vmob_user_locations_pkey1,vlatitude,vlongitude,vlocation,vstepinout,vuploaded_time,vcustomer_name,vpurpose,vcreated_time
  from mob_user_locations where mob_user_locations_pkey in 
  (select max(mob_user_locations_pkey) from mob_user_locations where user_id=vuser_id and customer_name=vcustomer_name and stepinout= 'IN' 
  and mob_user_locations_pkey<vmob_user_locations_pkey );
  
 
 insert into test(field1,field2) values(vmob_user_locations_pkey,'in');
  if vmob_user_locations_pkey1 is not null then
   update cus_visit_locations set customer_name1=vcustomer_name,stepin_time=vcreated_time  ,action2='IN',
   stepin_latitude=vlatitude,stepin_longitude=vlongitude,stepin_location= vlocation ,stepin_uploaded_time=vuploaded_time
   where mob_user_locations_pkey=vmob_user_locations_pkey;
 
  end if; 
 
  
  select max(mob_user_locations_pkey) into vmob_user_locations_pkey2  from mob_user_locations
  where user_id=vuser_id and customer_name=vcustomer_name and stepinout= 'START FROM' 
  and created_time>=date_add(vcreated_time,INTERVAL -500 MINUTE) and mob_user_locations_pkey<vmob_user_locations_pkey1
  group by vcustomer_name,user_id  ;
  
  if vmob_user_locations_pkey2 is not null then
 select mob_user_locations_pkey,latitude,longitude,location,stepinout,uploaded_time,customer_name,purpose,created_time
  into vmob_user_locations_pkey2,vlatitude,vlongitude,vlocation,vstepinout,vuploaded_time,vcustomer_name,vpurpose,vcreated_time
  from mob_user_locations where mob_user_locations_pkey in 
  (select max(mob_user_locations_pkey) from mob_user_locations where user_id=vuser_id and customer_name=vcustomer_name and stepinout= 'START FROM' 
  and mob_user_locations_pkey<vmob_user_locations_pkey1 );
  insert into test(field1,field2) values(vmob_user_locations_pkey,'start');
  
   update cus_visit_locations set start_time=vcreated_time  ,action1='START',
   start_latitude=vlatitude,start_longitude=vlongitude,start_location= vlocation ,start_uploaded_time=vuploaded_time
   where mob_user_locations_pkey=vmob_user_locations_pkey;
 
  end if; 
 
 set vmob_user_locations_pkey=null;
 set vmob_user_locations_pkey2=null;
 set vmob_user_locations_pkey1=null;
  end loop ;
  close att_cur;
  
  return 'OK';
   end;;

DROP PROCEDURE IF EXISTS `delete_an_count_records_fn`;;
CREATE PROCEDURE `delete_an_count_records_fn` (IN `pcompany_code` varchar(255), IN `ppkey` int, IN `pyearmonth1` date, OUT `vrecord_count` int)
BEGIN
    DELETE FROM attendance_register 
    WHERE company_code = pcompany_code
    AND month_year = DATE_FORMAT(pyearmonth1, '%Y-%m')
    AND emp_fkey = ppkey
    AND isdelete = 'Y'
    AND emp_fkey IN (
        SELECT emp_fkey 
        FROM (
            SELECT ar.emp_fkey 
            FROM attendance_register ar
            LEFT JOIN emp_details ed ON ar.emp_fkey = ed.emp_pkey
            WHERE 
                ar.branch_code != ed.branch_code
                AND ar.emp_fkey = ppkey
        ) AS subquery
    )
    AND month_year = DATE_FORMAT(pyearmonth1, '%Y-%m');

    SELECT COUNT(*) INTO vrecord_count
    FROM attendance_register ar
    LEFT JOIN payroll_master pm ON pm.emp_fkey = ar.emp_fkey AND pm.month_year = ar.month_year
    WHERE ar.emp_fkey = ppkey
    AND ar.isdelete = 'N'
    AND pm.action IS NULL
    AND ar.month_year = DATE_FORMAT(pyearmonth1, '%Y-%m');
END;;

DROP FUNCTION IF EXISTS `device_logs_iteration_fn`;;
CREATE FUNCTION `device_logs_iteration_fn` (`pemp_id` varchar(20), `pyear_month` date) RETURNS varchar(100) CHARACTER SET 'latin1' LANGUAGE SQL
MODIFIES SQL DATA
    DETERMINISTIC
begin
	create temporary table temp_device_attandance as select * from device_attandance where emp_id = pemp_id and date_format(LOGDATE, '%Y-%m-%d') between att_start_end_fn(pyear_month,1) and att_start_end_fn(pyear_month,2);
	
	delete from device_attandance where emp_id = pemp_id and date_format(LOGDATE, '%Y-%m-%d') between att_start_end_fn(pyear_month,1) and att_start_end_fn(pyear_month,2);
	
	insert into device_attandance (company_code, branch_code, DEVICELOGID, DOWNLOADDATE, DEVICEID, device_USERID, emp_id, LOGDATE, DIRECTION, ATTDIRECTION, C1, C2, C3, C4, C5, C6, C7, WORKCODE, status)
	select company_code, branch_code, DEVICELOGID, DOWNLOADDATE, DEVICEID, device_USERID, emp_id, LOGDATE, DIRECTION, ATTDIRECTION, C1, C2, C3, C4, C5, C6, C7, WORKCODE, status from temp_device_attandance order by LOGDATE;
	
	drop temporary table if exists temp_device_attandance;
	
	return 'success';
end;;

DROP FUNCTION IF EXISTS `device_logs_resync_fn`;;
CREATE FUNCTION `device_logs_resync_fn` (`pemp_id` varchar(20), `pyear_month` date) RETURNS varchar(30) CHARACTER SET 'latin1' LANGUAGE SQL
MODIFIES SQL DATA
    DETERMINISTIC
begin
	declare vcompany_code varchar(20);
	declare vbranch_code varchar(20);
	declare vDeviceId int;
	declare vdevice_USERID varchar(100);
	declare vuser_id varchar(100);
	declare vpunch_type char(1);
	
	select company_code, branch_code into vcompany_code, vbranch_code from emp_details where emp_id = pemp_id and status = 1;
	
	select emp_company_id into vdevice_USERID from emp_proff where emp_fkey in (select emp_pkey from emp_details where emp_id = pemp_id and status = 1);
	
	-- select DeviceId into vDeviceId from mypayrol_control_db.devices where company_code = vcompany_code and branch_code = vbranch_code limit 1;
	select deviceid into vDeviceId from mypayrol_control_db.emp_device_comp_branch where emp_device_id = vdevice_USERID and Company_code = vcompany_code;
	
	set vuser_id = concat(vcompany_code, pemp_id);
	
	select punchtype into vpunch_type from mob_user_credentials where user_id = vuser_id;
	
	if vDeviceId != 0 and vpunch_type in ('M','W') then
		drop temporary table if exists temp_bioserver;
		
		create temporary table temp_bioserver as
		select * from ebiosync.devicelogs where DeviceId = vDeviceId and UserId = vdevice_USERID and date_format(LogDate, '%Y-%m-%d') between att_start_end_fn(pyear_month, 1) and att_start_end_fn(pyear_month, 2);
		
		delete from device_attandance where emp_id = pemp_id and C2 is null and date_format(LOGDATE, '%Y-%m-%d') between att_start_end_fn(pyear_month, 1) and att_start_end_fn(pyear_month, 2);
		
		insert into device_attandance (company_code, branch_code, DEVICELOGID, DOWNLOADDATE, DEVICEID, device_USERID, emp_id, LOGDATE, DIRECTION, ATTDIRECTION, C1, C2, C3, C4, C5, C6, C7, WORKCODE)
		select vcompany_code, vbranch_code, DeviceLogId, DownloadDate, DeviceId, UserId, pemp_id, LogDate, Direction, AttDirection, C1, C2, C3, C4, C5, C6, C7, WorkCode from temp_bioserver order by LOGDATE;
		
		drop temporary table if exists temp_bioserver;
	end if;
	
	return 'success';
end;;

DROP FUNCTION IF EXISTS `editpunch_rules`;;
CREATE FUNCTION `editpunch_rules` (`pemp_fkey` int, `pmessage` varchar(250), `pinout_order` varchar(30), `Pyear_month` date, `pfirst_half` varchar(30)) RETURNS varchar(100) CHARACTER SET 'latin1' LANGUAGE SQL
READS SQL DATA
    DETERMINISTIC
begin

declare vemp_pkey int;
declare vatt_date  date;
declare nday  int;
declare vdaytimeId  int;
declare vLOGDATE_intime datetime;
declare vLOGDATE_outime datetime;
declare vduration int;
declare vminuts_calc_perday int;
declare vminutes_per_half int;
declare vsetvalue varchar(10);
declare vexistvalue varchar(10);
declare vattendance_date int;
declare vmonthly_att_fromdate datetime;
declare vmonthly_att_todate datetime;
declare vemp_count int;
declare vcompany_code varchar(30);
declare vbranch_code varchar(30);
declare vemp_id varchar(30);
declare visnextday int;
declare vincount int;
declare vmin_bfr_on_dutty_cal_ot	int;
declare vmin_aftr_off_dutty_cal_ot int ;
declare vwork_time_day_off_cal_ot int;
declare von_dutty1 varchar(30);
declare voff_dutty1 varchar(30);
declare vworking_time1 int;
declare voff_dutty1_ot varchar(30);
declare von_dutty1_ot  varchar(30);
declare von_dutty2 varchar(30);
DECLARE voff_dutty2 varchar(30);
declare vworking_time2 int;
declare vot_duration int;
declare voutdate date;
declare vafterout int;
declare vbeforein int;
declare vouttime datetime;
DECLARE exit_loop1 BOOLEAN default FALSE;

declare att_cur cursor for   
   select distinct emp_pkey,date_format(LOGDATE,'%Y-%m-%d')   
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 

 and lcase(c1)='in' and ucase(att.status)='Y'
 and date_format(LOGDATE,'%Y-%m-%d') between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d') and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d')
  and emp_pkey in
 (select emp_fkey from emp_proff where to_days(DATE_FORMAT(joining_date , '%Y-%m-%d')) <= to_days(DATE_FORMAT(vmonthly_att_todate , '%Y-%m-%d'))
  and day_time_seq in(select day_time_seq from working_day_time_procedures where working_time1 > 10) ) and emp_pkey=if(pemp_fkey in(null,''),emp_pkey,pemp_fkey) order by 1;
 


DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;


select distinct attendance_date into vattendance_date
                           from db_config where active='Y';

if vattendance_date =0 then

set vmonthly_att_fromdate =DATE_FORMAT(Pyear_month, '%Y-%m-01');
set vmonthly_att_todate =LAST_DAY(DATE_FORMAT(Pyear_month, '%Y-%m-%d'));

else
   set vmonthly_att_fromdate =date_format(DATE_SUB(concat(DATE_FORMAT(DATE_SUB(Pyear_month,INTERVAL 1 month), '%Y-%m-'),date_format(last_day(DATE_SUB(Pyear_month,INTERVAL 1 month)),'%d')),INTERVAL vattendance_date-1 day),'%Y-%m-%d');  
                      



set vmonthly_att_todate =DATE_SUB(concat(DATE_FORMAT(Pyear_month, '%Y-%m-'),date_format(last_day(Pyear_month),'%d')),INTERVAL vattendance_date day);
 
 




end if ;

open att_cur;
att_loop: loop
    fetch att_cur into vemp_pkey,vatt_date;

  IF exit_loop1 THEN
	LEAVE att_loop;
  END IF;

   select min(LOGDATE) into vLOGDATE_intime
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 
 and lcase(c1)='in' and emp_pkey=vemp_pkey and ucase(att.status)='Y'
and date_format(LOGDATE,'%Y-%m-%d') =vatt_date
and (LOGDATE,att.emp_id)
 in (select min(LOGDATE) ,emp_id from device_attandance where date_format(LOGDATE,'%Y-%m-%d') =vatt_date 
  and lcase(c1)='in' and ucase(status)='Y' group by emp_id);
 
 select min(LOGDATE) into vLOGDATE_outime
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 
 and lcase(c1)='out'
and date_format(LOGDATE,'%Y-%m-%d') >=vatt_date and emp_pkey=vemp_pkey and ucase(att.status)='Y'
 and (LOGDATE,att.emp_id) 
 in (select min(LOGDATE) ,emp_id from device_attandance where date_format(LOGDATE,'%Y-%m-%d') >=vatt_date and LOGDATE between vLOGDATE_intime and  vLOGDATE_intime + INTERVAL 1400 MINUTE and lcase(c1)='out' and ucase(status)='Y' group by emp_id);
 
 
 
 
 if pinout_order ='in/out' then
 
 if vLOGDATE_outime is not null then
 
 select count(*) into vincount from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 
  and lcase(c1)='in'
  and date_format(LOGDATE,'%Y-%m-%d') >=vatt_date and emp_pkey=vemp_pkey and ucase(att.status)='Y'
  and LOGDATE between vLOGDATE_intime and  vLOGDATE_outime ;
  if vincount>0 then
  update device_attandance set status='N' ,c3='in/out rule applied' where lcase(c1)='in' and LOGDATE between vLOGDATE_outime-Interval 5 minute and  vLOGDATE_outime ;
   end if;
  end if;
  
  elseif pinout_order ='out/in' then
  
   select count(*) into vincount from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 
  and lcase(c1)='out'
  and date_format(LOGDATE,'%Y-%m-%d') >=vatt_date and emp_pkey=vemp_pkey and ucase(att.status)='Y'
  and LOGDATE between vLOGDATE_outime and  vLOGDATE_outime+Interval 5 minute ; 
  if vincount>0 then
  update device_attandance set status='N' ,c3='out/in rule applied' where lcase(c1)='out' and LOGDATE between vLOGDATE_outime and  vLOGDATE_outime+Interval 5 minute ;
  end if;
  elseif pinout_order ='missout' then
   if vLOGDATE_intime is not null then
   select count(*) into vincount from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 
  and lcase(c1)='out'
  and date_format(LOGDATE,'%Y-%m-%d') >=vatt_date and emp_pkey=vemp_pkey and ucase(att.status)='Y'
  and LOGDATE between vLOGDATE_intime and  vLOGDATE_intime + INTERVAL 1000 MINUTE ;
  
	  if vincount=0 then
	  select day_time_seq into vdaytimeId from emp_proff where emp_fkey=vemp_pkey;
	   
	 select distinct minuts_calc_perday,min_bfr_on_dutty_cal_ot,min_aftr_off_dutty_cal_ot,work_time_day_off_cal_ot,on_dutty1,off_dutty1,working_time1,isnextday
	 into vminuts_calc_perday ,vmin_bfr_on_dutty_cal_ot,vmin_aftr_off_dutty_cal_ot,vwork_time_day_off_cal_ot,von_dutty1,voff_dutty1,vworking_time1,visnextday
	   from working_day_time_procedures where day_time_seq=vdaytimeId ;
	   select company_code,branch_code,emp_id into vcompany_code,vbranch_code,vemp_id from emp_details where emp_pkey=vemp_pkey;
	   if visnextday =1 then
		  set voutdate=vatt_date+Interval 1 day;
	   end if;	  
	  INSERT INTO device_attandance (company_code, branch_code, DEVICELOGID, DOWNLOADDATE, DEVICEID, device_USERID, emp_id, LOGDATE, DIRECTION, ATTDIRECTION, C1, C2, C3, C4, C5, C6, C7, WORKCODE, status) VALUES
	(vcompany_code,	vbranch_code,	0,	now(),	0,	vemp_id,	vemp_id,	concat(vatt_date,' ',von_dutty1) + INTERVAL vworking_time1 MINUTE,	'',	'',	'out',	'',	'Miss out rule applied',	'0',	'1',	'',	'',	'',	'Y');
	  
	  end if;
  end if;
   end if;
  end loop;
  close att_cur;
  
  
    if pinout_order ='breakoff' then
      
	  select day_time_seq into vdaytimeId from emp_proff where emp_fkey=pemp_fkey;
	   
	 select distinct minuts_calc_perday,min_bfr_on_dutty_cal_ot,min_aftr_off_dutty_cal_ot,work_time_day_off_cal_ot,on_dutty1,off_dutty1,working_time1,isnextday,
	 on_dutty2,off_dutty2,working_time2
	 into vminuts_calc_perday ,vmin_bfr_on_dutty_cal_ot,vmin_aftr_off_dutty_cal_ot,vwork_time_day_off_cal_ot,von_dutty1,voff_dutty1,vworking_time1,visnextday,
	 von_dutty2,voff_dutty2,vworking_time2
	   from working_day_time_procedures where day_time_seq=vdaytimeId ;
	   select company_code,branch_code,emp_id into vcompany_code,vbranch_code,vemp_id from emp_details where emp_pkey=pemp_fkey;
	
	
     
	   if visnextday =1 then
		  set voutdate=Pyear_month+Interval 1 day;
		else 
       	  set voutdate=Pyear_month;	
	   end if;
	   if vworking_time2>0 THEN
	   set vouttime=concat(Pyear_month,' ',voff_dutty2);
	   ELSE
	    set vouttime=concat(Pyear_month,' ',voff_dutty1);
	   end if;
	   set vworking_time1=vminuts_calc_perday ;
	   
	   
	
	 
 
 if pfirst_half='N' then
	INSERT INTO device_attandance (company_code, branch_code, DEVICELOGID, DOWNLOADDATE, DEVICEID, device_USERID, emp_id, LOGDATE, DIRECTION, ATTDIRECTION, C1, C2, C3, C4, C5, C6, C7, WORKCODE, status) VALUES
	(vcompany_code,	vbranch_code,	0,	now(),	0,	vemp_id,	vemp_id,	concat(Pyear_month,' ',von_dutty1),	'',	'',	'in',	'',	pmessage,	'0',	'1',	'',	'',	'',	'Y');
	
   INSERT INTO device_attandance (company_code, branch_code, DEVICELOGID, DOWNLOADDATE, DEVICEID, device_USERID, emp_id, LOGDATE, DIRECTION, ATTDIRECTION, C1, C2, C3, C4, C5, C6, C7, WORKCODE, status) VALUES
	(vcompany_code,	vbranch_code,	0,	now(),	0,	vemp_id,	vemp_id,	date_add(vouttime , INTERVAL 1 MINUTE) ,	'',	'',	'out',	'',	pmessage,	'0',	'1',	'',	'',	'',	'Y');
 elseif upper(pfirst_half) ='I' then	
    INSERT INTO device_attandance (company_code, branch_code, DEVICELOGID, DOWNLOADDATE, DEVICEID, device_USERID, emp_id, LOGDATE, DIRECTION, ATTDIRECTION, C1, C2, C3, C4, C5, C6, C7, WORKCODE, status) VALUES
	(vcompany_code,	vbranch_code,	0,	now(),	0,	vemp_id,	vemp_id,	concat(Pyear_month,' ',von_dutty1),	'',	'',	'in',	'',	pmessage,	'0',	'1',	'',	'',	'',	'Y');
 elseif upper(pfirst_half) ='O' then
     INSERT INTO device_attandance (company_code, branch_code, DEVICELOGID, DOWNLOADDATE, DEVICEID, device_USERID, emp_id, LOGDATE, DIRECTION, ATTDIRECTION, C1, C2, C3, C4, C5, C6, C7, WORKCODE, status) VALUES
	(vcompany_code,	vbranch_code,	0,	now(),	0,	vemp_id,	vemp_id,	date_add(vouttime , INTERVAL 1 MINUTE) ,	'',	'',	'out',	'',	pmessage,	'0',	'1',	'',	'',	'',	'Y');
	end if;
  
   end if;
  
   
  
  

 
 
 
 

return 'OK';

end;;

DROP PROCEDURE IF EXISTS `emp_detail_att_reg`;;
CREATE PROCEDURE `emp_detail_att_reg` (IN `Pcompany_code` varchar(30), IN `PBranch_code` varchar(30), IN `Puserid` varchar(30), IN `Pmonth` date, IN `pemp_pkey` int, OUT `Perr_msg` varchar(500))
begin

declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
declare vholidayId int;
declare vdaytimeId int;
declare vHOLIDAYDATE  date;
DECLARE l_sql VARCHAR(4000);
DECLARE nday int;
DECLARE pyearmonth varchar(30);
DECLARE vworking_days  int;
DECLARE vatt_date  date;

DECLARE vsunday  char(1);
DECLARE vmonday  char(1);
DECLARE vtuesday  char(1);
DECLARE vwednesday  char(1);
DECLARE vthursday  char(1);
DECLARE vfriday  char(1);
DECLARE vsaturday  char(1);
declare i int;
declare vleave_session int;
declare vleave_date date;
DECLARE exit_loop BOOLEAN default FALSE;
declare vmonthly_att_fromdate date;
declare vmonthly_att_todate date;
declare vatt_count int;
declare vattendance_date int;
declare vfunctionop varchar(30);
declare vwork_time_day_off_cal_ot int;
declare vis_multiple_days varchar(2);
declare vBranch_code varchar(30);

declare branch_cur cursor for
   select Branch_code from branches
       where Branch_code=if(PBranch_code in(null,'','X'),Branch_code,PBranch_code) and company_code=pcompany_code and status=1;

declare cur cursor for
select emp_pkey,concat(first_name,' ',ifnull(middile_name,''),' ',ifnull(last_name,'')) first_name,branch_code from emp_details where company_code= pcompany_code 
 and Branch_code=if(PBranch_code in(null,'','X'),Branch_code,PBranch_code)
  and emp_pkey in (select emp_fkey from emp_proff where date_format(joining_date,'%Y-%m-%d') <= vmonthly_att_todate  and day_time_seq is not null) 
 and emp_pkey not in (select emp_fkey from attendance_register where isdelete='N' and month_year=pyearmonth)
 and  emp_pkey=if(pemp_pkey in(null,''),emp_pkey,pemp_pkey)  ;




DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;

SET pyearmonth =DATE_FORMAT(Pmonth,'%Y-%m');

select distinct attendance_date into vattendance_date
                           from db_config where company_code= pcompany_code and active='Y';

if vattendance_date =0 then

set vmonthly_att_fromdate =DATE_FORMAT(Pmonth, '%Y-%m-01');
set vmonthly_att_todate =LAST_DAY(DATE_FORMAT(Pmonth, '%Y-%m-%d'));
else
   set vmonthly_att_fromdate =date_format(DATE_SUB(concat(DATE_FORMAT(DATE_SUB(Pmonth,INTERVAL 1 month), '%Y-%m-'),date_format(last_day(DATE_SUB(Pmonth,INTERVAL 1 month)),'%d')),INTERVAL vattendance_date-1 day),'%Y-%m-%d');  
                      



set vmonthly_att_todate =DATE_SUB(concat(DATE_FORMAT(Pmonth, '%Y-%m-'),date_format(last_day(Pmonth),'%d')),INTERVAL vattendance_date day);
 
 




end if ;
 
open cur;
start_loop: loop
    fetch cur into vemp_pkey,vfirst_name,vBranch_code;
   IF exit_loop THEN        LEAVE start_loop;     END IF; 
  
   	select ifnull(is_multiple_days,'N') into vis_multiple_days from working_day_time_procedures 
            where day_time_seq in( select day_time_seq from emp_proff where emp_fkey=vemp_pkey);
			
 

    if ucase(vis_multiple_days)='Y' then
    SELECT time_duration_check_multishift(DATE_FORMAT(Pmonth, '%Y-%m-01'), vemp_pkey, vBranch_code) into vfunctionop ;
	 else 
	  SELECT time_duration_check(DATE_FORMAT(Pmonth, '%Y-%m-01'), vemp_pkey, vBranch_code) into vfunctionop ;
	 end if; 
   
 end loop start_loop;
 close cur ;
  
 


end;;

DROP FUNCTION IF EXISTS `emp_inactive_fn`;;
CREATE FUNCTION `emp_inactive_fn` () RETURNS tinyint(4) LANGUAGE SQL
begin
declare vfullcnt float;
declare vhalfcnt float;
declare vleavecnt float;
declare vstart_month date;
declare vend_month date;
declare vleave_for_thyear float;
declare vcarry_forwarded float;
declare vemp_pkey int;
declare vfin_count int;
declare pfinyear varchar(30);
declare vemp_company_id varchar(30);
DECLARE vbankaccount varchar(100);
DECLARE vbankname varchar(100);
DECLARE vifsc_code varchar(100);
DECLARE vbank_branch  varchar(100);
declare vESI varchar(100);
declare vPF_NO varchar(100);
declare vUAN varchar(100);
DECLARE exit_loop1 BOOLEAN default FALSE;

declare emp_cur cursor for   
   select distinct emp_fkey ,emp_company_id  
  from emp_proff ed  WHERE emp_company_id in (select companyemployeeid from inactive_list where status=1)
 order by 1;
 


DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;

open emp_cur;
att_loop: loop
    fetch emp_cur into vemp_pkey,vemp_company_id;

  IF exit_loop1 THEN
	LEAVE att_loop;
  END IF;
 


 




 update emp_details set status=2,attr5='Inactive from backend on demand on30102019'
 where emp_pkey=vemp_pkey ;

update inactive_list set status=0 where companyemployeeid=vemp_company_id;

 end loop att_loop;
close emp_cur;
return 'OK';
end;;

DROP PROCEDURE IF EXISTS `estern_username_update`;;
CREATE PROCEDURE `estern_username_update` (IN `pemp_pkey` int)
begin

declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
declare vDeviceId int;
DECLARE exit_loop BOOLEAN default FALSE;

declare rec_count int;
declare vdevice_count int ;
declare vemp_co_id int;
declare vemp_company_id varchar(100);
declare vusername varchar(100);
declare vemp_branch varchar(30);
declare pcompany_code varchar(30);
DECLARE vemail varchar(100);


declare cur cursor for
select distinct emp_fkey,trim(emp_company_id),concat(substr(emp_branch,1,4),emp_company_id) username ,emp_branch
                                     from emp_proff where emp_fkey=pemp_pkey 
									 order by 1;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;

open cur;
start_loop: loop
    fetch cur into vemp_pkey,vemp_company_id,vusername,vemp_branch;
IF exit_loop THEN
        LEAVE start_loop;
     END IF;
	
	
   select company_code,email,first_name into pcompany_code,vemail,vfirst_name from emp_details where emp_pkey=vemp_pkey;
 select count(*) into rec_count from mypayrol_control_db.emp_device_comp_branch where Company_code=pcompany_code and 
      branch_code=vemp_branch and emp_fkey=vemp_pkey;
 select ifnull(DeviceId,1000) into vDeviceId  from mypayrol_control_db.devices where company_code= pcompany_code limit 1;
 if vDeviceId is null THEN
  set vDeviceId=1000;
  end if;
if rec_count=0 then

   insert into mypayrol_control_db.emp_device_comp_branch(deviceid,emp_device_id,emp_name,Company_code,branch_code,emp_id,emp_username,emp_fkey,email ) 
         values (vDeviceId,vemp_company_id,vfirst_name,pcompany_code,vemp_branch,vemp_company_id,vusername,vemp_pkey,vemail);  
 		 
   update emp_details set emp_id=vemp_company_id where emp_pkey=vemp_pkey;
   update  user_credentials set user_id=vusername where emp_fkey=vemp_pkey ;
 else
  update emp_details set emp_id=vemp_company_id where emp_pkey=vemp_pkey;
   update  user_credentials set user_id=vusername where emp_fkey=vemp_pkey ;
   update mypayrol_control_db.emp_device_comp_branch set emp_device_id=vemp_company_id,emp_id=vemp_company_id,
   emp_username=vusername,email=vemail
            where emp_fkey=vemp_pkey and Company_code=pcompany_code ;
 end if;
  end loop;
close cur;




end;;

DROP PROCEDURE IF EXISTS `final_settle_pay_prc`;;
CREATE PROCEDURE `final_settle_pay_prc` (IN `pbranch_code` varchar(30), IN `pmonth_year` varchar(30), IN `pemp_pkey` int, IN `ppresant_days` float, IN `pencash_days` float, IN `puser_id` varchar(50), OUT `perror_message` varchar(500))
begin
declare vemp_pkey int;
declare vpayroll_master_pkey int;
declare vfirst_name varchar(50);
declare vDeviceId int;

declare vemp_company_id	varchar(30);	 
declare vemp_type	varchar(30);	 
declare vdesignation	varchar(30); 
declare vemp_dept	varchar(30);
