declare vpt_deducted float;
declare vpt_balance float;
declare vpftax_components int;
declare vpfsalary_last_count int;
declare vptcount int;
declare vencashed_amount int;
declare vgross int;
declare vgrossbonus float;
declare vyear float;
declare vmonthcount float;
declare vgrativity int;
declare vbonus int;
declare vbonus_year int;
declare vloan_amount int;
declare vadvance_amount int;
declare vpt_adjamount int;
declare vpt_taxable_salary int;
declare vfin_year  int;
declare vtax_salary_components_fkey  int;
declare vemp_tax_sal_trans_pkey  int;
declare vtax  int;
declare rec_count int;
declare vstart_month_previous date;
declare vend_month_previous date;
declare vfin_year_previous int;
declare v1 int;
declare vtax_salary_components_pkey int; 
declare vtax_salary_components_name varchar(100);
declare vhra1 float;
declare vhra2 float;
declare vhra3 float;
declare vavailed_salary float;
declare vtaxable_salary float ;
declare vupper_limit float;
declare vtaxable_income float;
declare vtax_heads_limitsum float;
declare vtax_yearly float;
declare vtax_monthly float;
declare vother_income float;
declare vfirst_portion float;
declare vsecond_portion float;
declare vthird_portion float ;
declare vhradeclared float;
declare vtaxable_salary1 float;
declare vtax_head_value  float;
declare vtax_heads_limit   float;
