declare vfinal_income int;
declare vnetpay int;
declare vslipcount int;
declare vcount int;
declare vgross_total float;
declare vgross_total_current float;
declare vbonus_deducted float;
declare vbonus_deducted_current float;
declare vtottalgross_current float;
DECLARE vtottalgross_previous float;


declare vhead_fkey int;
		declare vstructure_det_depends  float;
		declare vstructure_formula varchar(500);
		declare vstructure_derived_perc float;
		declare vsalary_head_item_fkey1 int;
		declare vsalary_head_item_desc1 varchar(500);
		declare vsalary_amount1  float;
		declare vnewformula varchar(200);
		declare vnewformulaold varchar(200);
		declare vformula_value float;
		declare vvalue float;
		declare vsalary_previous float; 
		declare vsalary_current float;
		
declare cur cursor for
  select emp_fkey,emp_name,presant_total,leave_total,lop_total,weekoff_total,holiday_total  from attendance_register 
	       where branch_code=pbranch_code and emp_fkey= pemp_pkey and month_year=pmonth_year and isdelete= 'N' ;
		   
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;


open cur;
start_loop: loop
    fetch cur into vemp_pkey,vfirst_name,vpresant_total,vleave_total,vlop_total,vweekoff_total,vholiday_total;

IF exit_loop THEN
        LEAVE start_loop;
     END IF;
select count(*) into vexistcount  from payroll_master
    where emp_fkey=vemp_pkey and branch_code=pbranch_code and month_year=pmonth_year ;

  if vexistcount=0  then
 select distinct attendance_date into vattendance_date
								   from db_config where active='Y';
 if vattendance_date =0 then
       set vmonth=concat(pmonth_year,'-01');
			 set vmonthly_att_fromdate =DATE_FORMAT(vmonth, '%Y-%m-01');
			 set vmonthly_att_todate =LAST_DAY(DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d'));

		   else
		   set vmonth=concat(pmonth_year,'-01');
		   set vmonthly_att_fromdate =date_format(DATE_SUB(concat(DATE_FORMAT(DATE_SUB(vmonth,INTERVAL 1 month), '%Y-%m-'),date_format(last_day(DATE_SUB(vmonth,INTERVAL 1 month)),'%d')),INTERVAL vattendance_date day),'%Y-%m-%d');  

		   set vmonthly_att_todate =DATE_SUB(concat(DATE_FORMAT(vmonth, '%Y-%m-'),date_format(last_day(vmonth),'%d')),INTERVAL vattendance_date day);
		 
   end if;

		set vday_count = weekoff_days_count_fn(vemp_pkey, vmonthly_att_fromdate , vmonthly_att_todate ) ;
			set vworking_day = (DATEDIFF(vmonthly_att_todate,vmonthly_att_fromdate)+1)-vday_count ;
			
		 select distinct company_code into vcompany_code  from branches where branch_code=pbranch_code LIMIT 1;	
		 
    if vcompany_code='CLYS'  then 		 
		select structure_id into vstructure_id from emp_proff where emp_fkey=vemp_pkey;
		
		select prorate_code into vprorate_code  from 	salary_structure where structure_id= vstructure_id;
		if vprorate_code=1 then
		set ppresant_days = vpresant_total+ifnull(vweekoff_total,0)+ifnull(vholiday_total,0) ;
		
		end if;
		
	end if;	
		
	
    insert into payroll_master(emp_fkey, emp_name,	branch_code,month_year,days_presant, days_leave,loss_of_pay,calander_days,working_days)
                   values(vemp_pkey,vfirst_name,pbranch_code,pmonth_year,ppresant_days,pencash_days+vleave_total,vlop_total,
				   DATEDIFF(vmonthly_att_todate,vmonthly_att_fromdate)+1
				   ,vworking_day ) ;
	
 	
 select distinct payroll_master_pkey into vpayroll_master_pkey  from payroll_master where emp_fkey=vemp_pkey and month_year=pmonth_year and branch_code=pbranch_code;

call calculate_salary_main_prc(pmonth_year, pbranch_code, vemp_pkey, vpayroll_master_pkey, puser_id, @perr_msg);
 else
  select  count(*) into vslipcount
				from emp_salary_slip
		where emp_fkey = vemp_pkey and month_year = pmonth_year and end_date_effective is null;
		
if vslipcount=0 then
 select distinct payroll_master_pkey into vpayroll_master_pkey  from payroll_master where emp_fkey=vemp_pkey
 and month_year=pmonth_year and branch_code=pbranch_code;
call calculate_salary_main_prc(pmonth_year, pbranch_code, vemp_pkey, vpayroll_master_pkey, puser_id, @perr_msg);

end if;		
 
 end if;
 end loop;
close cur;


 update emp_settle_slip set status='N'  where status='Y' and emp_fkey=vemp_pkey ;	
	block60:begin
	   declare vsalary_head_item_fkey1 int;
	   declare vsalary_head_item_desc1 varchar(100);
	   declare vsalary_amount1 int;
       declare   vremarks varchar(100);
	   DECLARE exit_loop60 BOOLEAN default FALSE;
		declare slip_cur cursor for 
		select  payroll_master_fkey,salary_head_item_fkey	,
				trim(salary_head_item_desc) salary_head_item_desc,salary_amount   ,remarks
				from emp_salary_slip
		where emp_fkey = vemp_pkey and month_year = pmonth_year and end_date_effective is null and item_part='Direct'
		order by 1 ;
		 
	
		DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop60 = TRUE;
	 
	  open slip_cur;
	  start_loop60: loop
		fetch slip_cur into vpayroll_master_pkey,vsalary_head_item_fkey1,vsalary_head_item_desc1,vsalary_amount1 ,vremarks;
		
		IF exit_loop60 THEN 
		   LEAVE start_loop60 ;   
		END IF;
		   INSERT INTO `emp_settle_slip` ( `payroll_master_fkey`, `emp_fkey`, `type`, `month_year`, `salary_head_item_fkey`, `salary_head_item_desc`, `structure_det_value`, `salary_rate`, `salary_amount`, `presant_total`, `leave_total`, `lop_total`, `head_operator`, `head_type`, `item_part`, `creation_date`, `created_by`, `modified_by`, `remarks`, `approved`, `status`, `action`) VALUES
	( vpayroll_master_pkey, vemp_pkey,	'SALARY',	pmonth_year,	vsalary_head_item_fkey1,	concat(vsalary_head_item_desc1,' for the month-',pmonth_year)  ,	0,	vsalary_amount1,	vsalary_amount1,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	current_timestamp,	puser_id,	NULL,	NULL,	'N',	'Y',	NULL); 
		 end loop start_loop60;
		
		close slip_cur;
	   end block60 ;
  select count(*) into vcount  from attendance_register 
	       where branch_code=pbranch_code and emp_fkey= pemp_pkey and month_year=pmonth_year and isdelete= 'N' ;

if vcount!=0 then		   
  
  select salary_head_item_Fkey ,tax_salary_components_pkey into vpftax_components ,vtax_salary_components_fkey from tax_salary_components where tax_salary_components_name='Professional Tax';
  
   select  start_month,end_month,fin_year into vstart_month,vend_month,vfin_year  from  fin_year where  vattr1=1
    and is_current_finyear='Y' and status=1 and year_status='OPEN'
		   and branch_code= (select branch_code from emp_details where emp_Pkey=vemp_pkey );
 			  
  if vpftax_components is not null then
  
		   
if substr(pmonth_year,6,2) <='09' and substr(pmonth_year,6,2) >'03' then	   
	set vend_month=  last_day(DATE_ADD(vstart_month, INTERVAL 5 MONTH)) ;
	else
    set vstart_month=   DATE_ADD(vstart_month, INTERVAL 6 MONTH) ; 
	set vend_month= vend_month;
 end if;
  
  select  sum(abs(salary_amount)) into vactaul_salary from emp_salary_slip where emp_fkey=vemp_pkey 
     and end_date_effective is null and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	 and payroll_master_fkey in (select payroll_master_pkey from payroll_master where action in ('Approved','Processed'))
     and head_operator<>'Deduction' and item_part <> 'Indirect';
	 
   select  ifnull(sum(abs(salary_amount)),0) into vpt_deducted from emp_salary_slip where salary_head_item_Fkey=vpftax_components 
    and emp_fkey=vemp_pkey and end_date_effective is null and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	 and payroll_master_fkey in (select payroll_master_pkey from payroll_master where action in ('Approved','Processed'));

select  ifnull(min(tax_half_yearly),0) into vtax_half_yearly from profession_tax_slab where salary_range_to >=vactaul_salary;
	 
   set vpt_balance= ifnull(vtax_half_yearly,0)-ifnull(vpt_deducted,0); 
       	  
	   INSERT INTO `emp_settle_slip` ( `payroll_master_fkey`, `emp_fkey`, `type`, `month_year`, `salary_head_item_fkey`, `salary_head_item_desc`, `structure_det_value`, `salary_rate`, `salary_amount`, `presant_total`, `leave_total`, `lop_total`, `head_operator`, `head_type`, `item_part`, `creation_date`, `created_by`, `modified_by`, `remarks`, `approved`, `status`, `action`) VALUES
	( vpayroll_master_pkey, vemp_pkey,	'Professional Tax',	current_date,	vpftax_components,	'Professional Tax Balance',	0,	vpt_balance*-1,	vpt_balance*-1,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	current_timestamp,	puser_id,	NULL,	NULL,	'N',	'Y',	NULL);

  end if;	
  
 select encashed_amount into vencashed_amount from leave_encashment_master where remarks='terminate' and emp_fkey=vemp_pkey and status=1 limit 1 ;
	 	  
	INSERT INTO `emp_settle_slip` ( `payroll_master_fkey`, `emp_fkey`, `type`, `month_year`, `salary_head_item_fkey`, `salary_head_item_desc`, `structure_det_value`, `salary_rate`, `salary_amount`, `presant_total`, `leave_total`, `lop_total`, `head_operator`, `head_type`, `item_part`, `creation_date`, `created_by`, `modified_by`, `remarks`, `approved`, `status`, `action`) VALUES
	( vpayroll_master_pkey, vemp_pkey,	'ENCASHMENT',	current_date,	0,	'Leave Encashment',	0,	ifnull(vencashed_amount,0),	ifnull(vencashed_amount,0),	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	current_timestamp,	puser_id,	NULL,	NULL,	'N',	'Y',	NULL);
	
 select sum(loan_emi) into vloan_amount	
 from emp_loan_info 
  where emp_fkey = vemp_pkey and status= 1 and loan_month > pmonth_year and paid_status='A';
	
	
	   INSERT INTO `emp_settle_slip` ( `payroll_master_fkey`, `emp_fkey`, `type`, `month_year`, `salary_head_item_fkey`, `salary_head_item_desc`, `structure_det_value`, `salary_rate`, `salary_amount`, `presant_total`, `leave_total`, `lop_total`, `head_operator`, `head_type`, `item_part`, `creation_date`, `created_by`, `modified_by`, `remarks`, `approved`, `status`, `action`) VALUES
	( vpayroll_master_pkey, vemp_pkey,	'LOAN',	current_date,	0,	concat('Loan Balance'),	0,	ifnull(vloan_amount,0)*-1,ifnull(vloan_amount,0)*-1,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	current_timestamp,	puser_id,	NULL,	NULL,	'N',	'Y',	NULL);
 
 
 select sum(advance_amount) into vadvance_amount
 from emp_advance 
  where emp_fkey = vemp_pkey and status= 1 and date_format(affected_month,'%Y-%m')> pmonth_year ;

	   INSERT INTO `emp_settle_slip` ( `payroll_master_fkey`, `emp_fkey`, `type`, `month_year`, `salary_head_item_fkey`, `salary_head_item_desc`, `structure_det_value`, `salary_rate`, `salary_amount`, `presant_total`, `leave_total`, `lop_total`, `head_operator`, `head_type`, `item_part`, `creation_date`, `created_by`, `modified_by`, `remarks`, `approved`, `status`, `action`) VALUES
	( vpayroll_master_pkey, vemp_pkey,'ADVANCE',current_date,0,concat('Advance Balance'),0,ifnull(vadvance_amount,0)*-1,ifnull(vadvance_amount,0)*-1,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	current_timestamp,	puser_id,	NULL,	NULL,	'N',	'Y',	NULL);
 

	 SELECT round(datediff(now(),joining_date)/365) into vyear FROM `emp_proff` WHERE `emp_fkey` = vemp_pkey ;
	 
if vyear >=5  then 
 select sum(structure_det_value) into vgross from emp_salary_structure as ectc  
     where ectc.emp_fkey = vemp_pkey and salary_head_item_fkey in (select salary_head_item_Fkey from tax_salary_components 
	 where tax_salary_components_name in('Basic','Dearness Allowance (DA)'))
	 and end_date_effective is null ; 

   set vgrativity = round((vgross /26*15)* vyear);
	 
   INSERT INTO `emp_settle_slip` ( `payroll_master_fkey`, `emp_fkey`, `type`, `month_year`, `salary_head_item_fkey`, `salary_head_item_desc`, `structure_det_value`, `salary_rate`, `salary_amount`, `presant_total`, `leave_total`, `lop_total`, `head_operator`, `head_type`, `item_part`, `creation_date`, `created_by`, `modified_by`, `remarks`, `approved`, `status`, `action`) VALUES
	( vpayroll_master_pkey, vemp_pkey,	'Gratuity',	current_date,	0,	concat('Gratuity','(Basic+DA/26*15)*',vyear),	0,	ifnull(vgrativity,0),	ifnull(vgrativity,0),	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	current_timestamp,	puser_id,	NULL,	NULL,	'N',	'Y',	NULL);
	
 end if;
 
  select count(*) into vcount  from salary_structure_details where (structure_id,salary_head_item_fkey) in 
 (select emp_structure_id,salary_head_item_fkey from emp_salary_structure where emp_fkey = vemp_pkey 
   and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items 
     where item in('Bonus') and status = 1 and occurance='Yearly') and end_date_effective is null );
	 if vcount >0 then
  select  start_month,end_month,fin_year into vstart_month,vend_month,vfin_year  from  fin_year where  vattr1=1
    and is_current_finyear='Y' and status=1 and year_status='OPEN'
		   and branch_code= (select branch_code from emp_details where emp_Pkey=vemp_pkey );
		   
 select structure_formula,structure_derived_perc into vstructure_formula,vstructure_derived_perc  
 from salary_structure_details where (structure_id,salary_head_item_fkey) in 
 (select emp_structure_id,salary_head_item_fkey from emp_salary_structure where emp_fkey = vemp_pkey 
   and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items 
     where item in('Bonus') and status = 1 and occurance='Yearly') and end_date_effective is null );
	 
 select start_month,end_month,fin_year into vstart_month_previous,vend_month_previous,vfin_year_previous  
     from fin_year where  vattr1=1 and is_current_finyear='N' and status=1 and year_status='CLOSED' and fin_year = (vfin_year - 1)
     and branch_code= (select branch_code from emp_details where emp_Pkey=vemp_pkey );
  
 select ifnull(sum(abs(salary_amount)),0) into vbonus_deducted_current from emp_salary_slip where salary_head_item_Fkey in (select salary_head_item_pkey from salary_head_items 
     where item in('Bonus') and status = 1 ) 
     and emp_fkey=vemp_pkey and end_date_effective is null and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	 and payroll_master_fkey in (select payroll_master_pkey from payroll_master where action in ('Approved','Processed'));
	 
 select ifnull(sum(abs(salary_amount)),0) into vbonus_deducted from emp_salary_slip where salary_head_item_Fkey in (select salary_head_item_pkey from salary_head_items 
     where item in('Bonus') and status = 1 ) 
     and emp_fkey=vemp_pkey and end_date_effective is null and month_year between date_format(vstart_month_previous,'%Y-%m') and date_format(vend_month_previous,'%Y-%m')
	 and payroll_master_fkey in (select payroll_master_pkey from payroll_master where action in ('Approved','Processed')); 

   select upper(emp_type) into vemp_type from emp_proff where emp_fkey=vemp_pkey ;
   
  IF vemp_type ='DAILY WAGES' THEN
   select emp_anual_ctc*26 into vemp_anual_ctc from  emp_ctc_transaction  where emp_fkey=vemp_pkey and end_date_effective is null;
    else
   select emp_anual_ctc/12 into vemp_anual_ctc from  emp_ctc_transaction  where emp_fkey=vemp_pkey and end_date_effective is null;
  END IF; 
  
    select sum(gross_salary) into vtottalgross_current from payroll_master where 
      emp_fkey=vemp_pkey and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	 and action in ('Approved','Processed');
	 
  select sum(gross_salary) into vtottalgross_previous from payroll_master where 
      emp_fkey=vemp_pkey and month_year between date_format(vstart_month_previous,'%Y-%m') and date_format(vend_month_previous,'%Y-%m')
	 and action in ('Approved','Processed');
 
	 BLOCK5:begin
		DECLARE exit_loop5 BOOLEAN default FALSE;
		
		declare adjustment cursor for
		  SELECT shi.head_fkey,salary_head_item_fkey , trim(shi.item) ,structure_det_operator,structure_det_value,
		  structure_det_depends ,structure_formula,structure_derived_perc
		  FROM salary_structure_details ,salary_head_items shi
		 where  salary_head_item_fkey =salary_head_item_pkey
		 AND (structure_id,salary_head_item_fkey) in 
