		   and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items 
			 where item in('Bonus') and status = 1 and occurance='Yearly') and end_date_effective is null );
			
		  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop5 = TRUE;
		open adjustment ;
