			where emp_fkey = vemp_pkey and end_date_effective is null 
			and structure_det_value >=0  order by 1 desc;
			DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop50 = TRUE;
		 
		  open slip_cur;
		  start_loop50: loop
			fetch slip_cur into vsalary_head_item_fkey1,vsalary_head_item_desc1,vsalary_amount1 ;
			
			IF exit_loop50 THEN 
			   LEAVE start_loop50 ;   
			END IF;
	select ifnull(sum(abs(salary_amount)),0) into vsalary_current from emp_salary_slip where salary_head_item_Fkey =vsalary_head_item_fkey1
     and emp_fkey=vemp_pkey and end_date_effective is null and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	 and payroll_master_fkey in (select payroll_master_pkey from payroll_master where action in ('Approved','Processed'));
	 
   select ifnull(sum(abs(salary_amount)),0) into vsalary_previous from emp_salary_slip where salary_head_item_Fkey =vsalary_head_item_fkey1
     and emp_fkey=vemp_pkey and end_date_effective is null and month_year between date_format(vstart_month_previous,'%Y-%m') and date_format(vend_month_previous,'%Y-%m')
	 and payroll_master_fkey in (select payroll_master_pkey from payroll_master where action in ('Approved','Processed')); 
	 
			   set vnewformulaold=replace(vnewformulaold,vsalary_head_item_desc1,vsalary_previous) ;
			   set vnewformula=replace(vnewformula,vsalary_head_item_desc1,vsalary_current) ;
		 
		 end loop start_loop50;
		 
		   if vnewformula like '%Monthly Gross Salary%' then
		  
			set vnewformula=replace(vnewformula,'Monthly Gross Salary',ifnull(vtottalgross_current,0)) ;
			set vnewformula=replace(vnewformula,'. ','.') ;
			
			set vnewformulaold=replace(vnewformulaold,'Monthly Gross Salary',ifnull(vtottalgross_previous,0)) ;
			set vnewformulaold=replace(vnewformulaold,'. ','.') ;
		 end if;	
		 		
			
			close slip_cur;
		   end block50 ;
		  
		  end loop start_loop1;
		 close adjustment;
		 end BLOCK5;
		 
	  select concat('Current FY Bonus (', date_format(vstart_month,'%Y'),' - ',date_format(vend_month,'%Y'),')') into vfinyear_curr;
       select ifnull(concat('Previous FY Bonus (', date_format(vstart_month_previous,'%Y'),' - ',date_format(vend_month_previous,'%Y'),')'),'Previous FY Bonus - NA') into vfinyear_prev;
  select ifnull(vfin_year_previous,0) into vfin_year_previous;
  
  
   INSERT INTO `emp_settle_slip` ( `payroll_master_fkey`, `emp_fkey`, `type`, `month_year`, `salary_head_item_fkey`, `salary_head_item_desc`, `structure_det_value`, `salary_rate`, `salary_amount`, `presant_total`, `leave_total`, `lop_total`, `head_operator`, `head_type`, `item_part`, `creation_date`, `created_by`, `modified_by`, `remarks`, `approved`, `status`, `action`) VALUES
	( vpayroll_master_pkey, vemp_pkey,'BONUS',	vfin_year_previous,	vsalary_head_item_fkey,vfinyear_prev,	vbonus_deducted,	0,	0,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	current_timestamp,	puser_id,	NULL,	concat(vnewformulaold,'-',ifnull(vbonus_deducted,0)),	'N',	'Y',	'P');
 
 

 INSERT INTO `emp_settle_slip` ( `payroll_master_fkey`, `emp_fkey`, `type`, `month_year`, `salary_head_item_fkey`, `salary_head_item_desc`, `structure_det_value`, `salary_rate`, `salary_amount`, `presant_total`, `leave_total`, `lop_total`, `head_operator`, `head_type`, `item_part`, `creation_date`, `created_by`, `modified_by`, `remarks`, `approved`, `status`, `action`) VALUES
	( vpayroll_master_pkey, vemp_pkey,'BONUS',	vfin_year,	vsalary_head_item_fkey,vfinyear_curr,	vbonus_deducted_current,	0,	0,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	current_timestamp,	puser_id,	NULL,	concat(vnewformula,'-',ifnull(vbonus_deducted_current,0)),	'N',	'Y',	'P');
  end if;
 
 
 
 select sum(availed_salary)availed_salary, sum(taxable_salary)taxable_salary ,sum(actual_salary_recd)actual_salary_recd,sum(projected_salary)
    into vavailed_salary,vtaxable_salary,vsumactual_salary_recd,vsumprojected_salary
	from emp_tax_sal_trans
 where end_date_effective is null and salary_head_item_Fkey in (select salary_head_item_fkey from emp_salary_structure where head_operator<>'Deduction' and emp_fkey=vemp_pkey and end_date_effective is null and item_part <> 'Indirect')
   and fin_year=vfin_year and emp_fkey=vemp_pkey ;
   
 set vfinal_income=ifnull(vsumactual_salary_recd,0)+ifnull(vencashed_amount,0);
   
  set vinclude_decleration='Y';
  set vpt_balance= ifnull(vtax_half_yearly,0)-ifnull(vpt_deducted,0);
if vinclude_decleration='Y' then  
   set vtaxable_income=(ifnull(vother_income,0)+(ifnull(vfinal_income,0)-abs(ifnull(vtax_heads_limitsum,0))))-(ifnull(vpt_deducted,0)+ifnull(vpt_balance,0)) ;
 else 
 set vtaxable_income=ifnull(vfinal_income,0)-(ifnull(vpt_deducted,0)+ifnull(vpt_balance,0)) ;
end if; 
   	set vstanderd_deduction=50000;
	set vtaxable_income=vtaxable_income-vstanderd_deduction;
if vtaxable_income >=250000 then	
	set vbaselimit=250000;
	set vnewtaxable_income=vtaxable_income-250000;
 if  vnewtaxable_income >250000 then 
   set vfirst_portion = 250000;
   set vnewtaxable_income=vtaxable_income-500000;
   set vtax_yearly=vfirst_portion*.05;
 else
 if (vtaxable_income-250000)>0 then
  set vfirst_portion = vtaxable_income-250000;
  set vnewtaxable_income=0;
  set vtax_yearly=vfirst_portion*.05;
  else 
  set vfirst_portion = 0 ;
  set vnewtaxable_income=0;
  end if;
  end if; 

 if  vnewtaxable_income > 500000 then 
   set vsecond_portion = 500000;
   set vnewtaxable_income=vtaxable_income-1000000;
    set vtax_yearly=vtax_yearly+(vsecond_portion*.2);
 else
   if (vtaxable_income-500000)>0 then
    set vsecond_portion = vtaxable_income-500000;
    set vnewtaxable_income=0;
    set vtax_yearly=vtax_yearly+(vsecond_portion*.2);
	else 
	 set vsecond_portion = 0;
     set vnewtaxable_income=0;
	end if;
  end if;
  
  
   if  vnewtaxable_income >=1 then 
   set vthird_portion = vnewtaxable_income;
    set vtax_yearly=vtax_yearly+(vthird_portion*.3);
	else 
	set vthird_portion =0;
   end if;
 else
  set vbaselimit=vtaxable_income-250000;
  set vtax_yearly=0;
  end if;
  
  if vtaxable_income between 5000000 and 10000000 then 
	set vsurcharge= vtax_yearly*.1;
	elseif vtaxable_income >10000000 then
	set vsurcharge= vtax_yearly*.15;
	else
	set vsurcharge=0;
	end if;
	
	set vcess=vtax_yearly*.04 ;
	
	if vtaxable_income <= 500000 then
	 if vtax_yearly >0 then
     set vrebate = 12500;
	
	
	set vcess=0;
	 else
	  set vrebate = 0;
	 end if;
	else
     set vrebate = 0 ;
    end if;
   select  sum(abs(salary_amount)) into vtaxdeducted_sum from emp_salary_slip where emp_fkey= vemp_pkey
 and end_date_effective is null  and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	 and payroll_master_fkey in (select payroll_master_pkey from payroll_master where action in ('Approved','Processed'))
     and ucase(salary_head_item_desc) = 'TDS' group by emp_fkey ; 
		
    set vtax_monthly= ((vtax_yearly+ifnull(vcess,0))-round(ifnull(vtaxdeducted_sum,0),0)) ;
	
	if vtax_monthly<=0 then
	  set vtax_monthly=0;
	end if;  
  
 	  
  INSERT INTO `emp_settle_slip` ( `payroll_master_fkey`, `emp_fkey`, `type`, `month_year`, `salary_head_item_fkey`, `salary_head_item_desc`, `structure_det_value`, `salary_rate`, `salary_amount`, `presant_total`, `leave_total`, `lop_total`, `head_operator`, `head_type`, `item_part`, `creation_date`, `created_by`, `modified_by`, `remarks`, `approved`, `status`, `action`) VALUES
( 0, vemp_pkey,	'TDS',	current_date,	0,	'TDS Balance',	0,	vtax_monthly,	vtax_monthly,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	current_timestamp,	NULL,	NULL,	NULL,	'N',	'Y',	NULL);
 else
 
 set perror_message='Attendance not verified';
 
 end if;
end;;

DROP FUNCTION IF EXISTS `find_pf_tax_cal_fn`;;
CREATE FUNCTION `find_pf_tax_cal_fn` (`pemp_fkey` int) RETURNS int(11) LANGUAGE SQL
begin

declare vstart_month date;
declare vend_month date;
declare vsalary_amount int;
declare vfin_year varchar(30);
declare vjoining_date date;
declare vtotalmonth int;
declare vproj_count int;
declare vstructure_det_value int;
declare vactual_count int;
declare vactaul_salary int;
declare vactual_salary_recd int;
declare vprojected_salary int;
declare vvalue int;

select start_month, end_month,fin_year into vstart_month ,vend_month ,vfin_year  from fin_year
     where year_status='OPEN' and vattr1=1 and is_current_finyear='Y'  and status=1 
	 AND branch_code in (select branch_code from emp_details where emp_pkey=Pemp_fkey);

 select  sum(salary_amount) into vsalary_amount  from emp_salary_slip
    where emp_fkey = pemp_fkey  and concat(month_year,'-01') between vstart_month and vend_month
 and end_date_effective is null 
and salary_head_item_Fkey in (select salary_head_item_Fkey from tax_salary_components 
                                where tax_salary_components_name in('Employee EPF'));
								
select count(distinct month_year) into vactual_count from emp_salary_slip where  
    emp_fkey=Pemp_fkey and end_date_effective is null and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	 and payroll_master_fkey in (select payroll_master_pkey from payroll_master where action in ('Approved','Processed'))
     and salary_head_item_Fkey in (select salary_head_item_Fkey from tax_salary_components 
                                where tax_salary_components_name in('Employee EPF' )); 
  
  select  sum(abs(salary_amount)) into vactaul_salary from emp_salary_slip where emp_fkey=Pemp_fkey and end_date_effective is null and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	 and payroll_master_fkey in (select payroll_master_pkey from payroll_master where action in ('Approved','Processed'))
     and salary_head_item_Fkey in (select salary_head_item_Fkey from tax_salary_components 
                                where tax_salary_components_name in('Employee EPF'));
	
	select date_format(joining_date,'%Y-%m-%d') into vjoining_date from emp_proff  where emp_fkey=Pemp_fkey;
	
	if vjoining_date > vstart_month then
	  
	set vtotalmonth= TIMESTAMPDIFF(MONTH,vjoining_date, vend_month);
	
	
	else 
	set vtotalmonth= TIMESTAMPDIFF(MONTH,vstart_month, vend_month);
	
	
	end if;
	
	set vproj_count=abs(vtotalmonth)+1-ifnull(vactual_count,0);
	
	select 
    sum(abs(structure_det_value)) into vstructure_det_value
     from emp_salary_structure where emp_fkey=Pemp_fkey and salary_head_item_fkey in (select salary_head_item_Fkey from tax_salary_components where tax_salary_components_name in('Employee EPF')) and end_date_effective is null;
  
    set vactual_salary_recd= ifnull(vactaul_salary,0);
   set	vprojected_salary  = vstructure_det_value*vproj_count;
    set vvalue =(vstructure_det_value*vproj_count)+ifnull(vactaul_salary,0); 

return vvalue;

end;;

DROP PROCEDURE IF EXISTS `get_policy_weekoff_holiday_count_prc`;;
CREATE PROCEDURE `get_policy_weekoff_holiday_count_prc` (IN `pemp_pkey` int, IN `pstart_date` date, IN `pend_date` date, OUT `pweekoff_count` float, OUT `pholiday_count` float)
begin
    declare vholidayId int;
    declare vdaytimeId int;
    declare vSunday char(1);
    declare vMonday char(1);
    declare vTuesday char(1);
    declare vWednesday char(1);
    declare vThursday char(1);
    declare vFriday char(1);
    declare vSaturday char(1);
    declare vSunday_F char(1);
    declare vMonday_F char(1);
    declare vTuesday_F char(1);
    declare vWednesday_F char(1);
    declare vThursday_F char(1);
    declare vFriday_F char(1);
    declare vSaturday_F char(1);
    declare vday_name varchar(20);
    declare vweek int;
    declare vex_count int;
    declare vweekoff_check int;
    declare i int;
    declare vholiday_found int;
    
    set pweekoff_count = 0;
    set pholiday_count = 0;
    
    select HOLIDAY_GROUP_ID, day_time_seq into vholidayId, vdaytimeId 
    from emp_proff where emp_fkey = pemp_pkey order by emp_proff_pkey desc limit 1;
    
    select Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, 
           Sunday_F, Monday_F, Tuesday_F, Wednesday_F, Thursday_F, Friday_F, Saturday_F
    into vSunday, vMonday, vTuesday, vWednesday, vThursday, vFriday, vSaturday, 
         vSunday_F, vMonday_F, vTuesday_F, vWednesday_F, vThursday_F, vFriday_F, vSaturday_F
    from working_day_time_procedures where day_time_seq = vdaytimeId;
    
    select to_days(pstart_date) into i;
    
    while i <= to_days(pend_date) do
        set vholiday_found = 0;
        set vweekoff_check = 0;
        
        select count(*) into vholiday_found from holidays 
        where HOLIDAY_GROUP_ID = vholidayId 
        and status = 1 and HOLIDAYDATE = date_format(from_days(i), '%Y-%m-%d');
        
        if vholiday_found > 0 then
            set pholiday_count = pholiday_count + 1;
        end if;
        
        select sum(weekoff) into vweekoff_check from
        (    
            select count(*) as weekoff from working_day_time_procedures 
            where day_time_seq = vdaytimeId and active = 1
            and (Sunday = 'N' or Monday = 'N' or Tuesday = 'N' or Wednesday = 'N' or Thursday = 'N' or Friday = 'N' or Saturday = 'N' 
            or Sunday_F = 'Y' or Monday_F = 'Y' or Tuesday_F = 'Y' or Wednesday_F = 'Y' or Thursday_F = 'Y' or Friday_F = 'Y' or Saturday_F = 'Y')
            union all
            select count(*) as weekoff from shift_exceptions
            where shift_id = vdaytimeId and week_off = 'Y' and status = 1
        ) as shift_policy;
        
        if vweekoff_check > 0 then
            set vday_name = lcase(dayname(date_format(from_days(i), '%Y-%m-%d')));
            set vweek = floor((dayofmonth(date_format(from_days(i),'%Y-%m-%d'))-1)/7)+1;
            
            select count(*) into vex_count from shift_exceptions
            where shift_id = vdaytimeId and week_off = 'Y' and status = 1
            and lcase(ex_week_day) = vday_name and cast(ex_week as unsigned) = vweek;
			
			if (vday_name = 'sunday' and (vSunday = 'N' or vex_count > 0)) or
			   (vday_name = 'monday' and (vMonday = 'N' or vex_count > 0)) or
			   (vday_name = 'tuesday' and (vTuesday = 'N' or vex_count > 0)) or
			   (vday_name = 'wednesday' and (vWednesday = 'N' or vex_count > 0)) or
			   (vday_name = 'thursday' and (vThursday = 'N' or vex_count > 0)) or
			   (vday_name = 'friday' and (vFriday = 'N' or vex_count > 0)) or
			   (vday_name = 'saturday' and (vSaturday = 'N' or vex_count > 0)) then
				if vholiday_found > 0 then
					set pholiday_count = pholiday_count - 1;
				end if;	
				
				set pweekoff_count = pweekoff_count + 1;
			elseif (vday_name = 'sunday' and vSunday_F = 'Y') or
			       (vday_name = 'monday' and vMonday_F = 'Y') or
			       (vday_name = 'tuesday' and vTuesday_F = 'Y') or
			       (vday_name = 'wednesday' and vWednesday_F = 'Y') or
			       (vday_name = 'thursday' and vThursday_F = 'Y') or
			       (vday_name = 'friday' and vFriday_F = 'Y') or
			       (vday_name = 'saturday' and vSaturday_F = 'Y') then
				if vholiday_found > 0 then
					set pholiday_count = pholiday_count - 0.5;
				end if;	
				
				set pweekoff_count = pweekoff_count + 0.5;
			end if;
        end if;
        
        set i = i + 1;
    end while;
    
end;;

DROP PROCEDURE IF EXISTS `get_present_in_weekoff_holiday_count_prc`;;
CREATE PROCEDURE `get_present_in_weekoff_holiday_count_prc` (IN `pemp_fkey` int, IN `pmonth_year` varchar(7), OUT `o_weekoff_count` float, OUT `o_holiday_count` float)
BEGIN
    DECLARE vholidayId INT;
    DECLARE vdaytimeId INT;
    DECLARE vSunday CHAR(1);
    DECLARE vMonday CHAR(1);
    DECLARE vTuesday CHAR(1);
    DECLARE vWednesday CHAR(1);
    DECLARE vThursday CHAR(1);
    DECLARE vFriday CHAR(1);
    DECLARE vSaturday CHAR(1);
    DECLARE vSunday_F CHAR(1);
    DECLARE vMonday_F CHAR(1);
    DECLARE vTuesday_F CHAR(1);
    DECLARE vWednesday_F CHAR(1);
    DECLARE vThursday_F CHAR(1);
    DECLARE vFriday_F CHAR(1);
    DECLARE vSaturday_F CHAR(1);
    DECLARE vday_name VARCHAR(15);
    DECLARE vweek INT;
    DECLARE vex_count INT DEFAULT 0;
    DECLARE v_is_holiday INT DEFAULT 0;
    DECLARE vstart_date DATE;
    DECLARE vend_date DATE;
    DECLARE vdate DATE;
    DECLARE vholiday_count DECIMAL(10,2) DEFAULT 0;
    DECLARE vweekoff_count DECIMAL(10,2) DEFAULT 0;
    DECLARE v_attendance VARCHAR(10);
    DECLARE v_att_multiplier DECIMAL(3,2);
    
    SET vstart_date = att_start_end_fn(CONCAT(pmonth_year,'-01'), 1);
    SET vend_date   = att_start_end_fn(CONCAT(pmonth_year,'-01'), 2);

    SELECT holiday_group_id, day_time_seq
    INTO vholidayId, vdaytimeId
    FROM emp_proff
    WHERE emp_fkey = pemp_fkey;

    SELECT
        Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday,
        Sunday_F, Monday_F, Tuesday_F, Wednesday_F, Thursday_F, Friday_F, Saturday_F
    INTO
        vSunday, vMonday, vTuesday, vWednesday, vThursday, vFriday, vSaturday,
        vSunday_F, vMonday_F, vTuesday_F, vWednesday_F, vThursday_F, vFriday_F, vSaturday_F
    FROM working_day_time_procedures
    WHERE day_time_seq = vdaytimeId;
	
    SET vdate = vstart_date;

    date_loop: WHILE vdate <= vend_date DO

        SET v_attendance = NULL;
        SET v_att_multiplier = 0;
        SET v_is_holiday = 0;
        SET vex_count = 0;
		
        SELECT IFNULL(present,'')
        INTO v_attendance
        FROM emp_detail_timeattandance
        WHERE emp_pkey = pemp_fkey
        AND att_date = vdate
        LIMIT 1;
		
        IF v_attendance = 'P/P' THEN
            SET v_att_multiplier = 1;
        ELSEIF v_attendance IN ('P/A','A/P') THEN
            SET v_att_multiplier = 0.5;
        ELSE
            SET v_att_multiplier = 0;
        END IF;
		
        SELECT COUNT(*)
        INTO v_is_holiday
        FROM holidays
        WHERE holiday_group_id = vholidayId
        AND status = 1
        AND holidaydate = vdate;

        IF v_is_holiday > 0 THEN
            SET vholiday_count = vholiday_count + v_att_multiplier;
        ELSE
			
            SET vday_name = LCASE(DAYNAME(vdate));
            SET vweek = FLOOR((DAYOFMONTH(vdate) - 1) / 7) + 1;

            SELECT COUNT(*)
            INTO vex_count
            FROM shift_exceptions
            WHERE shift_id = vdaytimeId
            AND week_off = 'Y'
            AND status = 1
            AND LCASE(ex_week_day) = vday_name
            AND CAST(ex_week AS UNSIGNED) = vweek;

            IF (
                (vday_name = 'sunday'    AND (vSunday = 'N'    OR vex_count > 0)) OR
                (vday_name = 'monday'    AND (vMonday = 'N'    OR vex_count > 0)) OR
                (vday_name = 'tuesday'   AND (vTuesday = 'N'   OR vex_count > 0)) OR
                (vday_name = 'wednesday' AND (vWednesday = 'N' OR vex_count > 0)) OR
                (vday_name = 'thursday'  AND (vThursday = 'N'  OR vex_count > 0)) OR
                (vday_name = 'friday'    AND (vFriday = 'N'    OR vex_count > 0)) OR
                (vday_name = 'saturday'  AND (vSaturday = 'N'  OR vex_count > 0))
            ) THEN

                SET vweekoff_count = vweekoff_count + v_att_multiplier;

            ELSEIF (
                (vday_name = 'sunday'    AND vSunday_F = 'Y') OR
                (vday_name = 'monday'    AND vMonday_F = 'Y') OR
                (vday_name = 'tuesday'   AND vTuesday_F = 'Y') OR
                (vday_name = 'wednesday' AND vWednesday_F = 'Y') OR
                (vday_name = 'thursday'  AND vThursday_F = 'Y') OR
                (vday_name = 'friday'    AND vFriday_F = 'Y') OR
                (vday_name = 'saturday'  AND vSaturday_F = 'Y')
            ) THEN

                SET vweekoff_count = vweekoff_count + (v_att_multiplier / 2);

            END IF;
        END IF;
		
        SET vdate = DATE_ADD(vdate, INTERVAL 1 DAY);

    END WHILE;
	
    SET o_weekoff_count = vweekoff_count;
    SET o_holiday_count = vholiday_count;
END;;

DROP PROCEDURE IF EXISTS `insert_default_menu`;;
CREATE PROCEDURE `insert_default_menu` (IN `Pemp_fkey` int)
BEGIN
  DECLARE done INT DEFAULT FALSE;
  DECLARE a CHAR(16);
  DECLARE b, c INT;
  DECLARE cur1 CURSOR FOR SELECT menu_id FROM emp_menu where is_default = 'Y';
  
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

  OPEN cur1;
  

  read_loop: LOOP
    FETCH cur1 INTO a;
    
    IF done THEN
      LEAVE read_loop;
    END IF;
    
    
    


INSERT INTO user_access (organization_id, user_fkey, menu_id,active)
SELECT * FROM (SELECT '1',Pemp_fkey,a,'Y') AS tmp
WHERE NOT EXISTS (
    SELECT user_fkey FROM user_access WHERE user_fkey = Pemp_fkey and menu_id = a and active = 'Y'
) LIMIT 1;

  END LOOP;

  CLOSE cur1;
 
END;;

DROP PROCEDURE IF EXISTS `insert_emp_att_reg`;;
CREATE PROCEDURE `insert_emp_att_reg` (IN `Pcompany_code` varchar(30), IN `PBranch_code` varchar(30), IN `Puserid` varchar(30), IN `Pmonth` date, OUT `Perr_msg` varchar(5000))
