select emp_pkey,concat(first_name,' ',ifnull(middile_name,''),' ',ifnull(last_name,'')) first_name from emp_details where company_code= pcompany_code and Branch_code=pBranch_code
  and emp_pkey in (select emp_fkey from emp_proff where date_format(joining_date,'%Y-%m-%d') <= vmonthly_att_todate  and day_time_seq is not null) 
 and emp_pkey not in (select emp_fkey from attendance_register where isdelete='N' and month_year=pyearmonth)
 ;



DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;

SET pyearmonth =DATE_FORMAT(Pmonth,'%Y-%m');

select distinct attendance_date into vattendance_date
                           from db_config where company_code= pcompany_code and active='Y';

if vattendance_date =0 then

set vmonthly_att_fromdate =DATE_FORMAT(Pmonth, '%Y-%m-01');
set vmonthly_att_todate =LAST_DAY(DATE_FORMAT(Pmonth, '%Y-%m-%d'));
else
   set vmonthly_att_fromdate =date_format(DATE_SUB(concat(DATE_FORMAT(DATE_SUB(Pmonth,INTERVAL 1 month), '%Y-%m-'),date_format(last_day(DATE_SUB(Pmonth,INTERVAL 1 month)),'%d')),INTERVAL vattendance_date-1 day),'%Y-%m-%d');  
                      



set vmonthly_att_todate =DATE_SUB(concat(DATE_FORMAT(Pmonth, '%Y-%m-'),date_format(last_day(Pmonth),'%d')),INTERVAL vattendance_date day);
 
 




end if ;

 delete from attendance_register where  month_year=pyearmonth 
    and company_code=Pcompany_code and Branch_code=PBranch_code and isdelete='Y';
  open branch_cur;
  branch_loop: loop
    fetch branch_cur into pBranch_code;
     
IF exit_loop THEN
        LEAVE branch_loop;
     END IF;


open cur;
start_loop: loop
    fetch cur into vemp_pkey,vfirst_name;
   IF exit_loop THEN        LEAVE start_loop;     END IF; 
   
   
   set vweekoff_count = weekoff_days_count_fn(vemp_pkey, vmonthly_att_fromdate , vmonthly_att_todate ) ;
   select count(HOLIDAYDATE) into vholiday_count from holidays where status=1 and HOLIDAY_GROUP_ID in
   (select HOLIDAY_GROUP_ID from emp_proff where emp_fkey=vemp_pkey)
  and HOLIDAYDATE  between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d') and vmonthly_att_todate ;
  
   insert into attendance_register (company_code,branch_code,emp_fkey,month_year,emp_name,userid,weekoff_total,holiday_total)
   values(Pcompany_code,PBranch_code,vemp_pkey,pyearmonth ,vfirst_name,puserid,vweekoff_count,vholiday_count );
 
  

select is_multiple_days into vis_multiple_days from working_day_time_procedures 
            where day_time_seq in( select day_time_seq from emp_proff where emp_fkey=vemp_pkey);
    if ucase(vis_multiple_days)='Y' then
    SELECT time_duration_check_multishift(DATE_FORMAT(Pmonth, '%Y-%m-01'), vemp_pkey, PBranch_code) into vfunctionop ;
	else
	
	
	  SELECT time_duration_check(DATE_FORMAT(Pmonth, '%Y-%m-01'), vemp_pkey, PBranch_code) into vfunctionop ;
	end if;  
	
 
		BLOCK7:begin
