				elseif vloop_count=24 then 
				update attendance_register set FIELD24=vsetfield where emp_fkey=vemp_pkey and month_year=pyearmonth 
					 and company_code=Pcompany_code and Branch_code=PBranch_code;
				elseif vloop_count=25 then 
				update attendance_register set FIELD25=vsetfield where emp_fkey=vemp_pkey and month_year=pyearmonth 
					 and company_code=Pcompany_code and Branch_code=PBranch_code;
				elseif vloop_count=26 then 
				update attendance_register set FIELD26=vsetfield where emp_fkey=vemp_pkey and month_year=pyearmonth 
					 and company_code=Pcompany_code and Branch_code=PBranch_code;
				elseif vloop_count=27 then 
				update attendance_register set FIELD27=vsetfield where emp_fkey=vemp_pkey and month_year=pyearmonth 
					 and company_code=Pcompany_code and Branch_code=PBranch_code;
				elseif vloop_count=28 then 
				update attendance_register set FIELD28=vsetfield where emp_fkey=vemp_pkey and month_year=pyearmonth 
					 and company_code=Pcompany_code and Branch_code=PBranch_code;
