end;;

DROP PROCEDURE IF EXISTS `insert_update_att_reg`;;
CREATE PROCEDURE `insert_update_att_reg` (IN `pbranch_code` varchar(30), IN `pstart_date` date, IN `pend_date` date, IN `puserid` varchar(30), OUT `poutput` varchar(20))
begin
declare vend_date date;
declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vholidayId int;
declare vdaytimeId int;
declare vcompany_code varchar(20);
declare vmonth varchar(7);
declare vcalendar_days float;
declare vHOLIDAYDATE date;
declare vleave_session int;
declare vsalary_head_item_fkey int;
declare vsalary_head_item_fkey1 int;
declare vsalary_head_item_fkey2 int;
declare vleaveshort varchar(20);
declare vleaveshort1 varchar(20);
declare vleaveshort2 varchar(20);
declare vlast_approved_working_date date;
declare vsetfield varchar(30);
declare vSunday char(1);
declare vMonday char(1);
declare vTuesday char(1);
declare vWednesday char(1);
declare vThursday char(1);
declare vFriday char(1);
declare vSaturday char(1);
declare vSunday_F char(1);
declare vMonday_F char(1);
declare vTuesday_F char(1);
declare vWednesday_F char(1);
declare vThursday_F char(1);
declare vFriday_F char(1);
declare vSaturday_F char(3);
declare vex_count int;
declare vday_name varchar(20);
declare vresig_count int;
declare vjoinNA_count int;
declare vleave_count int;
declare vholiday_count int;
declare vweekoff_count int;
declare vatt_count int;
declare vpresent varchar(20);
declare vweek int;
declare vloop_count int;
declare i int;
declare vfrom_date date;
declare vto_date date;
declare vyearmonth date;
declare vsimple_att int;
declare is_full_status boolean default false;
declare exit_loop boolean default false;
declare is_na_period boolean default false;

declare emp_cur cursor for
select emp_pkey, concat(first_name,' ',ifnull(middile_name,''),' ',ifnull(last_name,'')) as first_name from emp_details where branch_code = pbranch_code
and emp_pkey in (select emp_fkey from emp_proff where date_format(joining_date,'%Y-%m-%d') <= pend_date and day_time_seq is not null and HOLIDAY_GROUP_ID is not null and LEAVEPOLICY_GROUP_ID is not null) 
and emp_pkey not in (select emp_fkey from attendance_register where isdelete='N' and month_year=vmonth);

declare continue handler for not found set exit_loop = true;

select att_start_end_fn(date_format(pstart_date, '%Y-%m-01'), 1) into vfrom_date;
select att_start_end_fn(date_format(pstart_date, '%Y-%m-01'), 2) into vto_date;

if pstart_date between vfrom_date and vto_date then
	set vyearmonth = date_format(pstart_date, '%Y-%m-01');
else
	set vyearmonth = date_add(date_format(pstart_date, '%Y-%m-01'), interval 1 month);
end if;

select company_code into vcompany_code from branches where branch_code = pbranch_code;

set vmonth = date_format(pend_date, '%Y-%m');
set vcalendar_days = datediff(pend_date, pstart_date) + 1;

delete from attendance_register where month_year = vmonth
and branch_code = pbranch_code and isdelete = 'Y';

open emp_cur;
	start_loop: loop
		fetch emp_cur into vemp_pkey,vfirst_name;
		
		if exit_loop then
			leave start_loop;
		end if;
		
		insert into attendance_register (company_code, branch_code, emp_fkey, month_year, emp_name,FIELD1, FIELD2, FIELD3, FIELD4, FIELD5, FIELD6, FIELD7, FIELD8, FIELD9, FIELD10,FIELD11, FIELD12, FIELD13, FIELD14, FIELD15, FIELD16, FIELD17, FIELD18, FIELD19,FIELD20, FIELD21, FIELD22, FIELD23, FIELD24, FIELD25, FIELD26, FIELD27, FIELD28,FIELD29, FIELD30, FIELD31,isdelete, calander_days, record_status, userid)
		values (vcompany_code, pbranch_code, vemp_pkey, vmonth, vfirst_name, 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'NA', 'Y', vcalendar_days, '1', puserid);
		
		select HOLIDAY_GROUP_ID, day_time_seq into vholidayId, vdaytimeId from emp_proff
		where emp_fkey = vemp_pkey and emp_branch = pbranch_code;
		
		select count(*) into vresig_count from termination where emp_fkey = vemp_pkey and status = 1;
		
		if vresig_count > 0 then
			select last_approved_working_date into vlast_approved_working_date from termination where emp_fkey = vemp_pkey and status = 1;
		end if;
		
		set vend_date = pend_date;
		
		select to_days(pstart_date) into i;
		
		set vloop_count = 1;
		
		while i <= to_days(vend_date) do
			select count(*) into vjoinNA_count from emp_proff 
			where emp_fkey = vemp_pkey and joining_date is not null 
			and joining_date > date_format(from_days(i), '%Y-%m-%d');
			
			set is_na_period = false;
			
			if vjoinNA_count > 0 then
				set is_na_period = true;
			end if;
			
			if vresig_count > 0 and date_format(from_days(i), '%Y-%m-%d') > vlast_approved_working_date then
				set is_na_period = true;
			end if;
			
			select count(*) into vholiday_count from holidays where HOLIDAY_GROUP_ID=vholidayId 
			and status = 1 and HOLIDAYDATE = date_format(from_days(i), '%Y-%m-%d');
			
			select sum(weekoff) into vweekoff_count from
			(	
				select count(*) as weekoff from working_day_time_procedures where day_time_seq = vdaytimeId and active = 1
				and (Sunday = 'N' or Monday = 'N' or Tuesday = 'N' or Wednesday = 'N' or Thursday = 'N' or Friday = 'N' or Saturday = 'N' 
				or Sunday_F = 'Y' or Monday_F = 'Y' or Tuesday_F = 'Y' or Wednesday_F = 'Y' or Thursday_F = 'Y' or Friday_F = 'Y' or Saturday_F = 'Y')
				union all
				select count(*) as weekoff from shift_exceptions
				where shift_id = vdaytimeId and week_off = 'Y' and status = 1
			) as shift_policy;
			
			if is_na_period = false then
				select count(*) into vleave_count
				from emp_leave_transactions as elt join leaveentries as l on elt.LEAVEENTRYID = l.LEAVEENTRYID
				where elt.Leavestatus in('Authorized','Approved') and l.EMP_fkey = vemp_pkey
				and DATE_FORMAT(elt.leave_date, '%Y-%m-%d') = date_format(from_days(i), '%Y-%m-%d');
				
				select count(*) into vatt_count from emp_detail_timeattandance where emp_pkey = vemp_pkey and yearmonth = vyearmonth
				and att_date = date_format(from_days(i), '%Y-%m-%d') and present is not null and duration is not null order by emp_detail_timeattandance_pkey desc limit 1;
			else
				set vleave_count = 0;
				set vatt_count = 0;
			end if;
			
            if vweekoff_count > 0 and is_full_status = false then
				select Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday_F, Monday_F, Tuesday_F, Wednesday_F, Thursday_F, Friday_F, Saturday_F
				into vSunday, vMonday, vTuesday, vWednesday, vThursday, vFriday, vSaturday, vSunday_F, vMonday_F, vTuesday_F, vWednesday_F, vThursday_F, vFriday_F, vSaturday_F
				from working_day_time_procedures where day_time_seq = vdaytimeId;
				
				set vday_name = lcase(dayname(date_format(from_days(i), '%Y-%m-%d')));
				set vweek = floor((dayofmonth(date_format(from_days(i),'%Y-%m-%d'))-1)/7)+1;
				
				select count(*) into vex_count from shift_exceptions
				where shift_id = vdaytimeId and week_off = 'Y' and status = 1
				and lcase(ex_week_day) = vday_name and cast(ex_week as unsigned) = vweek;
				
				if vday_name = 'sunday' then
                    if vSunday = 'N' then
						set vsetfield = 'WO';
                    elseif vex_count > 0 then
                        set vsetfield = 'WO';
                    elseif vSunday_F = 'Y' then
						if is_na_period = true then
							set vsetfield = 'NA/WO';
						else
							set vsetfield = 'A/WO';
						end if;
					end if;
				elseif vday_name = 'monday' then
					if vMonday = 'N' then
						set vsetfield = 'WO';
                    elseif vex_count > 0 then
                        set vsetfield = 'WO';
                    elseif vMonday_F = 'Y' then
						if is_na_period = true then
							set vsetfield = 'NA/WO';
						else
							set vsetfield = 'A/WO';
						end if;
					end if;
				elseif vday_name = 'tuesday' then
					if vTuesday = 'N' then
						set vsetfield = 'WO';
                    elseif vex_count > 0 then
                        set vsetfield = 'WO';
                    elseif vTuesday_F = 'Y' then
						if is_na_period = true then
							set vsetfield = 'NA/WO';
						else
							set vsetfield = 'A/WO';
						end if;
					end if;
				elseif vday_name = 'wednesday' then
					if vWednesday = 'N' then
						set vsetfield = 'WO';
                    elseif vex_count > 0 then
                        set vsetfield = 'WO';
                    elseif vWednesday_F = 'Y' then
						if is_na_period = true then
							set vsetfield = 'NA/WO';
						else
							set vsetfield = 'A/WO';
						end if;
					end if;
				elseif vday_name = 'thursday' then
					if vThursday = 'N' then
						set vsetfield = 'WO';
                    elseif vex_count > 0 then
                        set vsetfield = 'WO';
                    elseif vThursday_F = 'Y' then
						if is_na_period = true then
							set vsetfield = 'NA/WO';
						else
							set vsetfield = 'A/WO';
						end if;
					end if;
				elseif vday_name = 'friday' then
					if vFriday = 'N' then
						set vsetfield = 'WO';
                    elseif vex_count > 0 then
                        set vsetfield = 'WO';
                    elseif vFriday_F = 'Y' then
						if is_na_period = true then
							set vsetfield = 'NA/WO';
						else
							set vsetfield = 'A/WO';
						end if;
					end if;
				elseif vday_name = 'saturday' then
					if vSaturday = 'N' then
						set vsetfield = 'WO';
                    elseif vex_count > 0 then
                        set vsetfield = 'WO';
                    elseif vSaturday_F = 'Y' then
						if is_na_period = true then
							set vsetfield = 'NA/WO';
						else
							set vsetfield = 'A/WO';
						end if;
					end if;
				end if;
				
				if vsetfield = 'WO' then
					set is_full_status = true;
				end if;
			end if;
			
			if vholiday_count > 0 and is_full_status = false then
				if vsetfield in ('A/WO', 'NA/WO') then
					set vsetfield = 'HO/WO';
				else
					set vsetfield = 'HO';
				end if;
				
				set is_full_status = true;
			end if;
			
			if vleave_count > 0 and is_full_status = false and is_na_period = false then
				if vleave_count = 1 then
					select elt.leave_session,l.salary_head_item_fkey into vleave_session, vsalary_head_item_fkey
					from emp_leave_transactions elt join leaveentries l on(elt.LEAVEENTRYID = l.LEAVEENTRYID)
					where elt.Leavestatus in('Authorized','Approved') and l.EMP_fkey = vemp_pkey
					and DATE_FORMAT(elt.leave_date, '%Y-%m-%d') = date_format(from_days(i), '%Y-%m-%d');
					
					select ifnull(occurance,'LOP') as leaveshort into vleaveshort
					from salary_head_items where salary_head_item_pkey=vsalary_head_item_fkey;
					
					if vsetfield is not null then
						if vleave_session in (1,3) then
							set vsetfield = replace(vsetfield, substr(vsetfield,1,1), vleaveshort);
						end if;
					else
						if vleave_session = 3 then 
							set vsetfield = concat(ucase(vleaveshort),'/',ucase(vleaveshort));
						elseif vleave_session = 2 then 
							set vsetfield = concat('A/',ucase(vleaveshort));
						elseif vleave_session = 1 then 
							set vsetfield = concat(ucase(vleaveshort),'/A');		 
						end if;
					end if;
				elseif vleave_count = 2 then
					select l.salary_head_item_fkey into vsalary_head_item_fkey1
					from emp_leave_transactions elt join leaveentries l on(elt.LEAVEENTRYID = l.LEAVEENTRYID)
					where elt.Leavestatus in('Authorized','Approved') and l.EMP_fkey = vemp_pkey and  elt.leave_session = 1
					and DATE_FORMAT(elt.leave_date, '%Y-%m-%d') = date_format(from_days(i), '%Y-%m-%d');
					
					select l.salary_head_item_fkey into vsalary_head_item_fkey2
					from emp_leave_transactions elt join leaveentries l on(elt.LEAVEENTRYID = l.LEAVEENTRYID)
					where elt.Leavestatus in('Authorized','Approved') and l.EMP_fkey = vemp_pkey and  elt.leave_session = 2
					and DATE_FORMAT(elt.leave_date, '%Y-%m-%d') = date_format(from_days(i), '%Y-%m-%d');
					
					select ifnull(occurance, 'LOP') as leaveshort into vleaveshort1
					from salary_head_items where salary_head_item_pkey = vsalary_head_item_fkey1;
					
					select ifnull(occurance, 'LOP') as leaveshort into vleaveshort2
					from salary_head_items where salary_head_item_pkey = vsalary_head_item_fkey2;
					
					if vsetfield is not null then
						set vsetfield = replace(vsetfield, substr(vsetfield,1,1), vleaveshort1);
					else
						set vsetfield = concat(ucase(vleaveshort1),'/',ucase(vleaveshort2));
					end if;
				end if;
				
				if substr(vsetfield,length(vsetfield)-1,length(vsetfield))!='/A' and substr(vsetfield,1,2)!='A/' then
					set is_full_status = true;
				end if;
			end if;
			
			if vatt_count > 0 and is_full_status = false and is_na_period = false then
				select present into vpresent from emp_detail_timeattandance where emp_pkey = vemp_pkey and yearmonth = vyearmonth
				and att_date = date_format(from_days(i), '%Y-%m-%d') and present is not null and duration is not null order by emp_detail_timeattandance_pkey desc limit 1;
				
				if vsetfield is not null then
					if substr(vsetfield,1,2) = 'A/' then
						set vsetfield =  replace(vsetfield, substr(vsetfield,1,1), substr(vpresent,1,1));
					elseif substr(vsetfield,length(vsetfield)-1,length(vsetfield)) = '/A' then
						set vsetfield = replace(vsetfield, substr(vsetfield,length(vsetfield),length(vsetfield)), substr(vpresent,length(vpresent),length(vpresent)));
					end if;
				else
					set vsetfield = vpresent;
				end if;
				
				if substr(vsetfield,length(vsetfield)-1,length(vsetfield)) != '/A' and substr(vsetfield,1,2) != 'A/' then
					set is_full_status = true;
				end if;
			end if;
			
			if is_full_status = false then
				if is_na_period = true then
					if vsetfield is not null then
						set vsetfield = vsetfield;
					else
						set vsetfield = 'NA';
					end if;
				else
					select count(*) into vsimple_att from emp_proff
					where emp_fkey = vemp_pkey and day_time_seq in (select day_time_seq from working_day_time_procedures where working_time1 <= 10);
					
					if vsimple_att > 0 then
						if vsetfield is not null then
							if substr(vsetfield,1,2) = 'A/' then
								set vsetfield = replace(vsetfield, substr(vsetfield,1,1), 'P');
							elseif substr(vsetfield,length(vsetfield)-1,length(vsetfield)) = '/A' then
								set vsetfield = replace(vsetfield, substr(vsetfield,length(vsetfield),length(vsetfield)), 'P');
							end if;
						else
							set vsetfield = 'P/P';
						end if;
					else
						if vsetfield is not null then
							if substr(vsetfield,1,2) = 'A/' then
								set vsetfield = replace(vsetfield, substr(vsetfield,1,1), 'LOP');
							elseif substr(vsetfield,length(vsetfield)-1,length(vsetfield)) = '/A' then
								set vsetfield = replace(vsetfield, substr(vsetfield,length(vsetfield),length(vsetfield)), 'LOP');
							end if;
						else
							set vsetfield = 'LOP/LOP';
						end if;
					end if;
				end if;
			end if;
			
			if vloop_count=1 then 
				update attendance_register set FIELD1=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=2 then 
				update attendance_register set FIELD2=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=3 then 
				update attendance_register set FIELD3=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=4 then 
				update attendance_register set FIELD4=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=5 then 
				update attendance_register set FIELD5=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=6 then 
				update attendance_register set FIELD6=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=7 then 
				update attendance_register set FIELD7=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=8 then 
				update attendance_register set FIELD8=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=9 then 
				update attendance_register set FIELD9=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=10 then 
				update attendance_register set FIELD10=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=11 then 
				update attendance_register set FIELD11=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=12 then 
				update attendance_register set FIELD12=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=13 then 
				update attendance_register set FIELD13=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=14 then 
				update attendance_register set FIELD14=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=15 then 
				update attendance_register set FIELD15=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=16 then 
				update attendance_register set FIELD16=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
			elseif vloop_count=17 then 
				update attendance_register set FIELD17=vsetfield where emp_fkey=vemp_pkey and month_year=vmonth 
				and company_code=vcompany_code and branch_code=pbranch_code;
