CREATE PROCEDURE `insert_update_att_reg_hierarchy` (IN `Pcompany_code` varchar(30), IN `PBranch_code` varchar(30), IN `Puserid` varchar(30), IN `Pmonth` date, OUT `Perr_msg` varchar(500))
