 BLOCK4:begin
 declare vsalary_head_item_fkey int;
 declare vleaveshort varchar(10);
 declare vfdl varchar(10);
 declare vshl varchar(10);
 declare vFhl varchar(10);
DECLARE exit_loop4 BOOLEAN default FALSE;
declare leavecur cursor for
 select elt.leave_date,elt.leave_session,l.EMP_fkey,l.salary_head_item_fkey
          from emp_leave_transactions elt join leaveentries l on(elt.LEAVEENTRYID = l.LEAVEENTRYID)
where elt.Leavestatus in('Authorized','Approved')
    and DATE_FORMAT(elt.leave_date, '%Y-%m-%d') 
   between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d') and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d') and l.EMP_fkey=vemp_pkey ;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop4 = TRUE;
open leavecur ;
start_loop1: loop
    fetch leavecur into vleave_date , vleave_session,vemp_pkey,vsalary_head_item_fkey ;
	
	
   
IF exit_loop4 THEN 
       LEAVE start_loop1;   
  END IF;
 
    select DATE_FORMAT(vleave_date,'%d') into nday ;
 
 
   
   select ifnull(occurance,'LOP') leaveshort into vleaveshort
     from salary_head_items where  salary_head_item_pkey=vsalary_head_item_fkey ; 
	 
	 if vleave_session=3 then 
	     set vfdl =concat(ucase(vleaveshort),'/',ucase(vleaveshort));
	 elseif vleave_session=2 then 
         set vshl= concat('A/',ucase(vleaveshort));
     elseif vleave_session=1 then 
         set vFhl= concat(ucase(vleaveshort),'/A');		 
	 end if;

if nday=01 then
  if vleave_session=3 then
  update attendance_register set FIELD1=vfdl where emp_fkey=vemp_pkey and month_year=yearmonth 
    and company_code=Pcompany_code and Branch_code=PBranch_code;
   elseif vleave_session=2 then
   update attendance_register set FIELD1=vshl where emp_fkey=vemp_pkey and month_year=yearmonth 
    and company_code=Pcompany_code and Branch_code=PBranch_code;
   elseif vleave_session=1 then
   update attendance_register set FIELD1=vFhl where emp_fkey=vemp_pkey and month_year=yearmonth 
    and company_code=Pcompany_code and Branch_code=PBranch_code;
  end if;
