 BLOCK2:begin
declare vLOGDATE_intime datetime;
declare vLOGDATE_outime datetime;
declare vduration int;
declare vminuts_calc_perday int;
declare vsetvalue varchar(10);
declare vexistvalue varchar(10);
declare vminutes_per_half int;
declare vassigned_value varchar(20);
DECLARE exit_loop1 BOOLEAN default FALSE;

declare att_cur cursor for   
   select distinct emp_pkey,date_format(LOGDATE,'%Y-%m-%d')   
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 

 and lcase(c1)='in' and ucase(att.status)='Y' and emp_pkey=vemp_pkey
and date_format(LOGDATE,'%Y-%m-%d') between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d')
 and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d') 
and emp_pkey not in (select emp_fkey from attendance_register where isdelete='N' and month_year=yearmonth)
and emp_pkey in (select emp_fkey from emp_proff where date_format(joining_date,'%Y-%m-%d') <= vmonthly_att_todate and attr1=Puserid and day_time_seq in(select day_time_seq from working_day_time_procedures where working_time1 > 10 )) 
 and att.company_code= pcompany_code order by 1;
 


DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;

open att_cur;
att_loop: loop
    fetch att_cur into vemp_pkey,vatt_date;

  IF exit_loop1 THEN
	LEAVE att_loop;
  END IF;

   select DATE_FORMAT(vatt_date,'%d') into nday ;
   

   select min(LOGDATE) into vLOGDATE_intime
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 
 and lcase(c1)='in' and emp_pkey=vemp_pkey and ucase(att.status)='Y'
and date_format(LOGDATE,'%Y-%m-%d') =vatt_date
and (LOGDATE,att.emp_id)
 in (select min(LOGDATE) ,emp_id from device_attandance where date_format(LOGDATE,'%Y-%m-%d') =vatt_date and lcase(c1)='in' and emp_pkey=vemp_pkey and ucase(status)='Y' group by emp_id);
 
 select min(LOGDATE) into vLOGDATE_outime
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 
 and lcase(c1)='out'
and date_format(LOGDATE,'%Y-%m-%d') >=vatt_date and emp_pkey=vemp_pkey and ucase(att.status)='Y'
 and (LOGDATE,att.emp_id) 
 in (select min(LOGDATE) ,emp_id from device_attandance where date_format(LOGDATE,'%Y-%m-%d') >=vatt_date and LOGDATE between vLOGDATE_intime and  vLOGDATE_intime + INTERVAL 1400 MINUTE and lcase(c1)='out' and emp_pkey=vemp_pkey and ucase(status)='Y' group by emp_id);
 
 
 if vLOGDATE_outime is not null then
set vduration=TIMESTAMPDIFF(Minute, vLOGDATE_intime,vLOGDATE_outime); 

select day_time_seq into vdaytimeId from emp_proff where emp_fkey=vemp_pkey;
   
 select distinct minuts_calc_perday,minutes_per_half
 into vminuts_calc_perday ,vminutes_per_half
   from working_day_time_procedures where day_time_seq=vdaytimeId ;
   
   
   if vduration >= vminuts_calc_perday then 
   set vsetvalue='P/P';
   elseif vduration >= vminutes_per_half then
   set vsetvalue='P/A';
   elseif vduration < vminutes_per_half then
   set vsetvalue='A/A';
   else
   set vsetvalue='A/A';
   end if;
    
	
if nday=01 then
   select FIELD1 into vexistvalue from attendance_register
  where emp_fkey=vemp_pkey and month_year=yearmonth 
    and company_code=Pcompany_code and Branch_code=PBranch_code and userid=puserid;
	
if vexistvalue is null then
    set vassigned_value=vsetvalue;
 elseif substr(vexistvalue,length(vexistvalue)-1,length(vexistvalue))='/A' and vsetvalue= 'P/A' then	
    set vassigned_value=replace(vexistvalue,'/A','/P');
	
  elseif substr(vexistvalue,length(vexistvalue)-1,length(vexistvalue))='/A' and vsetvalue= 'P/P' then
   set vassigned_value=vsetvalue;
  
 elseif  substr(vexistvalue,length(vexistvalue)-1,length(vexistvalue))='/A' and vsetvalue= 'A/A' then
    set vassigned_value=vexistvalue;


elseif substr(vexistvalue,1,2)='A/' and vsetvalue= 'P/A' then	
      set vassigned_value=replace(vexistvalue,'A/','P/');
	
  elseif substr(vexistvalue,1,2)='A/' and vsetvalue= 'P/P' then	
    set vassigned_value=vsetvalue;
	
  elseif substr(vexistvalue,1,2)='A/' and vsetvalue= 'A/A' then
     set vassigned_value=vexistvalue;
	 
 
	 
elseif vexistvalue in(select ifnull(occurance,'LOP') from salary_head_items where ucase(item_type)='LEAVE') and vsetvalue= 'P/A' then	
   set vassigned_value=vsetvalue;
 
  elseif vexistvalue in(select ifnull(occurance,'LOP') from salary_head_items where ucase(item_type)='LEAVE') and vsetvalue= 'P/P' then	
     set vassigned_value=vsetvalue;
  
 elseif vexistvalue in(select ifnull(occurance,'LOP') from salary_head_items where ucase(item_type)='LEAVE') and vsetvalue= 'A/A' then
