DROP PROCEDURE IF EXISTS `insert_update_att_reg_rep`;;
CREATE PROCEDURE `insert_update_att_reg_rep` (IN `Pcompany_code` varchar(30), IN `PBranch_code` varchar(30), IN `Puserid` varchar(30), IN `Pmonth` date, OUT `Perr_msg` varchar(200))
begin

declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
declare vholidayId int;
declare vdaytimeId int;
declare vHOLIDAYDATE  date;
DECLARE l_sql VARCHAR(4000);
DECLARE nday int;
DECLARE yearmonth varchar(30);
DECLARE vworking_days  int;
DECLARE vatt_date  date;

DECLARE vsunday  char(1);
DECLARE vmonday  char(1);
DECLARE vtuesday  char(1);
DECLARE vwednesday  char(1);
DECLARE vthursday  char(1);
DECLARE vfriday  char(1);
DECLARE vsaturday  char(1);
declare i int;
declare vleave_session int;
declare vleave_date date;
DECLARE exit_loop BOOLEAN default FALSE;
declare vmonthly_att_fromdate date;
declare vmonthly_att_todate date;
declare vatt_count int;
declare vattendance_date int;

declare branch_cur cursor for
   select Branch_code from branches
      where ifnull(pBranch_code,Branch_code)=Branch_code and company_code=pcompany_code;

declare cur cursor for
select emp_pkey,first_name from emp_details where company_code= pcompany_code and Branch_code=pBranch_code
  and emp_pkey in (select emp_fkey from emp_proff where date_format(joining_date,'%Y-%m-%d') <= vmonthly_att_todate  and day_time_seq is not null)
 and emp_pkey not in (select emp_fkey from attendance_register_rep where isdelete='N' and month_year=yearmonth) ;



DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;

SET yearmonth =DATE_FORMAT(Pmonth,'%Y-%m');

select distinct attendance_date into vattendance_date
                           from db_config where company_code= pcompany_code and active='Y';

if vattendance_date =0 then

set vmonthly_att_fromdate =DATE_FORMAT(Pmonth, '%Y-%m-01');
set vmonthly_att_todate =LAST_DAY(DATE_FORMAT(Pmonth, '%Y-%m-%d'));
else
   set vmonthly_att_fromdate =date_format(DATE_SUB(concat(DATE_FORMAT(DATE_SUB(Pmonth,INTERVAL 1 month), '%Y-%m-'),date_format(last_day(DATE_SUB(Pmonth,INTERVAL 1 month)),'%d')),INTERVAL vattendance_date day),'%Y-%m-%d');  
                      



set vmonthly_att_todate =DATE_SUB(concat(DATE_FORMAT(Pmonth, '%Y-%m-'),date_format(last_day(Pmonth),'%d')),INTERVAL vattendance_date day);
 
 




end if ;

 delete from attendance_register_rep where  month_year=yearmonth 
    and company_code=Pcompany_code and Branch_code=PBranch_code and userid=puserid and isdelete='Y';
  open branch_cur;
  branch_loop: loop
    fetch branch_cur into pBranch_code;
     
IF exit_loop THEN
        LEAVE branch_loop;
     END IF;


open cur;
start_loop: loop
    fetch cur into vemp_pkey,vfirst_name;
   IF exit_loop THEN        LEAVE start_loop;     END IF; 
   insert into attendance_register_rep (company_code,branch_code,emp_fkey,month_year,emp_name,userid)
   values(Pcompany_code,PBranch_code,vemp_pkey,yearmonth ,vfirst_name,puserid );
 
   
 select HOLIDAY_GROUP_ID,day_time_seq into vholidayId ,vdaytimeId from emp_proff where emp_fkey=vemp_pkey;

 select sunday,  monday,  tuesday,  wednesday,  thursday  ,  friday,  saturday
 into vsunday,  vmonday,  vtuesday,  vwednesday,  vthursday  ,  vfriday,  vsaturday 
   from working_day_time_procedures where day_time_seq=vdaytimeId ;


select to_days(DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d'))into i;

if vsunday='N' then 
