DECLARE exit_loop4 BOOLEAN default FALSE;
declare leavecur cursor for
 select elt.leave_date,elt.leave_session,l.EMP_fkey
       from emp_leave_transactions elt,leaveentries l where elt.Leavestatus in('Authorized','Approved')
   and elt.LEAVEENTRYID = l.LEAVEENTRYID and DATE_FORMAT(elt.leave_date, '%Y-%m-%d')  between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d') and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d') and l.EMP_fkey=vemp_pkey ;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop4 = TRUE;
open leavecur ;
start_loop1: loop
