   BLOCK3:begin
declare vb4joinindate int;
DECLARE exit_loop1 BOOLEAN default FALSE;
declare joiningdate_cur cursor for   
  select emp_fkey,DATE_SUB(date_format(joining_date,'%Y-%m-%d'),INTERVAL 1 day)joining_date from emp_proff
 where date_format(joining_date,'%Y-%m-%d') between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d')
 and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d')
 and emp_fkey not in (select emp_fkey from attendance_register_rep where isdelete='N' and month_year=yearmonth)
 and emp_fkey in (select emp_fkey from emp_proff where joining_date  is not null)
 and emp_fkey=vemp_pkey;

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;

open joiningdate_cur ;
att_loop1: loop
    fetch joiningdate_cur into vemp_pkey,vatt_date;

  IF exit_loop1 THEN
	LEAVE att_loop1;
  END IF;

select to_days(DATE_FORMAT(vmonthly_att_fromdate , '%Y-%m-%d'))into i;
select to_days(DATE_FORMAT(vatt_date, '%Y-%m-%d'))into vb4joinindate ;

