end;;

DROP PROCEDURE IF EXISTS `insert_update_att_reg_view`;;
CREATE PROCEDURE `insert_update_att_reg_view` (IN `Pcompany_code` varchar(30), IN `Pbranch_code` varchar(30), IN `Puserid` varchar(30), IN `Pmonth` date, OUT `Perr_msg` varchar(500))
begin

declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
declare vholidayId int;
declare vdaytimeId int;
declare vHOLIDAYDATE  date;
declare l_sql VARCHAR(4000);
declare nday int;
declare pyearmonth varchar(30);
declare vworking_days  int;
declare vatt_date  date;
declare vsunday  char(1);
declare vmonday  char(1);
declare vtuesday  char(1);
declare vwednesday  char(1);
declare vthursday  char(1);
declare vfriday  char(1);
declare vsaturday  char(1);
declare i int;
declare vleave_session int;
declare vleave_date date;
declare vmonthly_att_fromdate date;
declare vmonthly_att_todate date;
declare vatt_count int;
declare vattendance_date int;
declare vfunctionop varchar(30);
declare vwork_time_day_off_cal_ot int;
declare vis_multiple_days varchar(2);
declare vweekoff_count float;
declare vholiday_count float;
declare v_holiday_woff_count  float;
declare v_holiday_halfwoff_count float;
declare vcompany_code varchar(30);
declare vhalfweekoff_count float;
declare vsetfield varchar(30);

declare exit_loop boolean default false;

declare branch_cur cursor for
select branch_code from branches
where ifnull(Pbranch_code,branch_code)=branch_code and company_code = pcompany_code;

declare cur cursor for
select emp_pkey,concat(first_name,' ',ifnull(middile_name,''),' ',ifnull(last_name,'')) as first_name from emp_details where company_code= pcompany_code and branch_code=Pbranch_code
and emp_pkey in (select emp_fkey from emp_proff where date_format(joining_date,'%Y-%m-%d') <= vmonthly_att_todate  and day_time_seq is not null and HOLIDAY_GROUP_ID is not null and LEAVEPOLICY_GROUP_ID is not null and structure_id is not null) 
and emp_pkey not in (select emp_fkey from attendance_register where isdelete='N' and month_year=pyearmonth);

declare continue handler for not found set exit_loop = true;

set pyearmonth =date_format(Pmonth,'%Y-%m');

select att_start_end_fn(date_format(Pmonth, '%Y-%m-01'), 1) into vmonthly_att_fromdate;
select att_start_end_fn(date_format(Pmonth, '%Y-%m-01'), 2) into vmonthly_att_todate;

delete from attendance_register where month_year=pyearmonth 
and company_code=Pcompany_code and branch_code=Pbranch_code and isdelete='Y';

open branch_cur;
	branch_loop: loop
		
		fetch branch_cur into Pbranch_code;
		
		if exit_loop then
			leave branch_loop;
		end if;
		
		open cur;
			start_loop: loop
				
				fetch cur into vemp_pkey,vfirst_name;
				
				if exit_loop then
					leave start_loop;
				end if;
				
				select distinct company_code into vcompany_code  from branches where branch_code=Pbranch_code limit 1;	
				
				select count(weekoff) into vweekoff_count from emp_detail_timeattandance where emp_pkey = vemp_pkey and yearmonth = date_format(Pmonth, '%Y-%m-01')
				and weekoff ='WO' and ifnull(others,'X') !='NA' ; 
				
				select count(weekoff)*.5 into vhalfweekoff_count from emp_detail_timeattandance where emp_pkey = vemp_pkey and yearmonth = date_format(Pmonth, '%Y-%m-01') 
				and weekoff in('/WO','WO/') and ifnull(others,'X') !='NA' ; 
				
				set vweekoff_count =vweekoff_count+ vhalfweekoff_count; 			 
				
				select count(HOLIDAYDATE) into vholiday_count from holidays where status=1 and HOLIDAY_GROUP_ID in
				(select HOLIDAY_GROUP_ID from emp_proff where emp_fkey=vemp_pkey)
				and HOLIDAYDATE  between date_format(vmonthly_att_fromdate, '%Y-%m-%d') and vmonthly_att_todate
				and HOLIDAYDATE in (select att_date from emp_detail_timeattandance where  ifnull(others,'X') != 'NA' 
				and emp_pkey=vemp_pkey and yearmonth=date_format(Pmonth, '%Y-%m-01')
				union all 
				select att_date from emp_detail_timeattandance where ifnull(leaves,'X') != 'LOP/LOP' 
				and emp_pkey=vemp_pkey and yearmonth=date_format(Pmonth, '%Y-%m-01'));
				
				if vholiday_count >0 then		
					select count(*) into v_holiday_woff_count from emp_detail_timeattandance 
					where weekoff ='WO' and holiday is not null and emp_pkey=vemp_pkey 
					and yearmonth=date_format(Pmonth, '%Y-%m-01') and ((ifnull(others,'X') !='NA') or (ifnull(leaves,'X') !='LOP/LOP'));
					
					select count(*)*.5 into v_holiday_halfwoff_count from emp_detail_timeattandance 
					where weekoff ='/WO' and holiday is not null and emp_pkey=vemp_pkey 
					and yearmonth=date_format(Pmonth, '%Y-%m-01') and ((ifnull(others,'X') !='NA') or (ifnull(leaves,'X') not in('LOP/','/LOP','LOP')));
					
					if (v_holiday_woff_count >0 or v_holiday_halfwoff_count >0) then 
						set vholiday_count= vholiday_count-(v_holiday_woff_count+v_holiday_halfwoff_count);  
					end if; 
				end if;
				
				insert into attendance_register (company_code,branch_code,emp_fkey,month_year,emp_name,userid,weekoff_total,holiday_total)
				values(Pcompany_code,Pbranch_code,vemp_pkey,pyearmonth ,vfirst_name,puserid,vweekoff_count,vholiday_count );
				
				block7: begin
					
					declare vempatt_pkey int;
					declare vatt_date date;
					declare vweekoff  varchar(30);
					declare vpresent  varchar(30);
					declare vleaves  varchar(30);
					declare vholiday  varchar(30);
					declare vothers  varchar(30);
					declare vloop_count int;
					declare vsimple_att int;
					declare vsetfield varchar(30);
					declare vprorate_code int;
					
					declare exit_loop7 boolean default false;
					
					declare att_reg cursor for 
					select emp_pkey,att_date,present,weekoff,leaves,holiday,others from emp_detail_timeattandance 
					where yearmonth=Pmonth and emp_pkey=vemp_pkey order by att_date;
					
					declare continue handler for not found set exit_loop7 = true;
					
					set vloop_count=1;
					
					open att_reg;
						start_loop7: loop
							
							fetch att_reg into vempatt_pkey,vatt_date,vpresent,vweekoff,vleaves,vholiday,vothers;
							
							if exit_loop7 then
								leave start_loop7;
							end if;
							
							select prorate_code into vprorate_code from salary_structure where structure_id in (select structure_id from emp_proff where emp_fkey=vemp_pkey);
							
							select work_time_day_off_cal_ot into vwork_time_day_off_cal_ot from working_day_time_procedures 
							where day_time_seq in (select day_time_seq from emp_proff where emp_fkey=vemp_pkey);
							
							select count(*) into vsimple_att from emp_proff where  
							day_time_seq in(select day_time_seq from working_day_time_procedures where working_time1 <= 10 ) 
							and emp_fkey=vemp_pkey;
							
							if vsimple_att<>0 then
								
								if vleaves is not null then
									set vpresent='P/P';
									if substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'P/A' then	
										set vsetfield=replace(vleaves,'/A','/P');
									elseif substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'P/P' then
										set vsetfield=vpresent;
									elseif substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vweekoff='/WO' then
										set vpresent='A/A';
									elseif substr(vleaves,length(vleaves)-1,length(vleaves))!='/A' and vweekoff='/WO' then
										set vpresent='A/A';
									elseif substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'A/A' then
										set vsetfield=vleaves;
									elseif substr(vleaves,1,2)='A/' and vpresent= 'P/A' then
										set vsetfield=replace(vleaves,'A/','P/');
									elseif substr(vleaves,1,2)='A/' and vpresent= 'P/P' then
										set vsetfield=vpresent;
									elseif substr(vleaves,1,2)='A/' and vpresent= 'A/A' then
										set vsetfield=vleaves;	
									else
										set vsetfield=vleaves;	
									end if;
								elseif vweekoff='/WO' and vholiday is not null then
									set vweekoff='HO/WO';	
								elseif vweekoff='/WO'  then
									set vpresent='P/A';		 
								elseif vweekoff ='WO' then
									set vsetfield=vweekoff;
								elseif vholiday is not null then
									set vsetfield=vholiday;
								elseif vothers is not null then
									set vsetfield= vothers;	 
								else
									set vsetfield='P/P';
								end if;
								
							elseif vwork_time_day_off_cal_ot=1 then
								
								if vleaves is not null then
									if substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'P/A' then	
										set vsetfield=replace(vleaves,'/A','/P');
									elseif substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'P/P' then
										set vsetfield=vpresent;
									elseif  substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'A/A' then
										set vsetfield=vleaves;
									elseif substr(vleaves,1,2)='A/' and vpresent= 'P/A' then	
										set vsetfield=replace(vleaves,'A/','P/');
									elseif substr(vleaves,1,2)='A/' and vpresent= 'P/P' then	
										set vsetfield=vpresent;
									elseif substr(vleaves,1,2)='A/' and vpresent= 'A/A' then
										set vsetfield=vleaves;
									else
										set vsetfield=vleaves;						 
									end if;
								elseif vweekoff is not null then
									set vsetfield=vweekoff;
								elseif vholiday is not null then
									set vsetfield=vholiday;
								elseif vothers is not null then
									set vsetfield= vothers;
								elseif vpresent is not null then
									if vleaves is not null  then
										if substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'P/A' then	
											set vsetfield=replace(vleaves,'/A','/P');
										elseif substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'P/P' then
											set vsetfield=vpresent;
										elseif  substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'A/A' then
											set vsetfield=vleaves;
										elseif substr(vleaves,1,2)='A/' and vpresent= 'P/A' then	
											set vsetfield=replace(vleaves,'A/','P/');
										elseif substr(vleaves,1,2)='A/' and vpresent= 'P/P' then	
											set vsetfield=vpresent;
										elseif substr(vleaves,1,2)='A/' and vpresent= 'A/A' then
											set vsetfield=vleaves;	
										else
											set vsetfield=vpresent;	
										end if;
									else
										set vsetfield=vpresent;
									end if;
								end if;
								
							elseif vwork_time_day_off_cal_ot in(2,4,5) then
								
								if vpresent is not null then  
									if vleaves is not null  then
										if substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'P/A' then	
											set vsetfield=replace(vleaves,'/A','/P');
										elseif substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'P/P' then
											set vsetfield=vpresent;
										elseif  substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'A/A' then
											set vsetfield=vleaves;
										elseif substr(vleaves,1,2)='A/' and vpresent= 'P/A' then	
											set vsetfield=replace(vleaves,'A/','P/');
										elseif substr(vleaves,1,2)='A/' and vpresent= 'P/P' then	
											set vsetfield=vpresent;
										elseif substr(vleaves,1,2)='A/' and vpresent= 'A/A' then
											set vsetfield=vleaves;	
										else
											set vsetfield=vpresent;	
										end if;
									else
										set vsetfield=vpresent;
									end if;
								elseif vleaves is not null then
									set vsetfield=vleaves;
								elseif vweekoff is not null then
									set vsetfield=vweekoff;
								elseif vholiday is not null then
									set vsetfield=vholiday;
								elseif vothers is not null then
									set vsetfield= vothers;
								end if;
								
							elseif vwork_time_day_off_cal_ot=0 then
								
								if vpresent is not null then
									if vleaves is not null then
										if substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'P/A' then	
											set vsetfield=replace(vleaves,'/A','/P');
										elseif substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'P/P' then
											set vsetfield=vpresent;
										elseif  substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'A/A' then
											set vsetfield=vleaves;
										elseif substr(vleaves,1,2)='A/' and vpresent= 'P/A' then	
											set vsetfield=replace(vleaves,'A/','P/');
										elseif substr(vleaves,1,2)='A/' and vpresent= 'P/P' then	
											set vsetfield=vpresent;
										elseif substr(vleaves,1,2)='A/' and vpresent= 'A/A' then
											set vsetfield=vleaves;	
										else
											set vsetfield=vpresent;	
										end if;
									else
										set vsetfield=vpresent;
									end if;
								elseif vleaves is not null then
									set vsetfield=vleaves;
								elseif vweekoff='/WO' and vpresent='P/A' then
									set vsetfield='P/WO';
								elseif vweekoff='/WO' and vpresent is null then
									set vsetfield='A/WO';
								elseif vweekoff='/WO' and vpresent='A/A' then
									set vsetfield='A/WO';
								elseif vweekoff is not null then
									set vsetfield=vweekoff;
								elseif vholiday is not null then
									set vsetfield=vholiday;
								elseif vothers is not null then
									set vsetfield= vothers;
								end if;
								
							end if;
							
							if substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'P/A' then
								set vsetfield=replace(vleaves,'/A','/P');
							elseif substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'P/P' then
								set vsetfield=vpresent;
							elseif  substr(vleaves,length(vleaves)-1,length(vleaves))='/A' and vpresent= 'A/A' then
								set vsetfield=vleaves;
							elseif substr(vleaves,1,2)='A/' and vpresent= 'P/A' then
								set vsetfield=replace(vleaves,'A/','P/');
							elseif substr(vleaves,1,3)='LOP' and vpresent= 'A/P' then
								set vsetfield=replace(vleaves,'/A','/P');
							elseif substr(vleaves,3,2)='/A' and vpresent= 'A/P' then
								set vsetfield=replace(vleaves,'/A','/P');
							elseif substr(vleaves,5,2)='/A' and vpresent= 'A/P' then
								set vsetfield=replace(vleaves,'/A','/P');
							elseif substr(vleaves,1,2)='A/' and vpresent= 'P/P' then
								set vsetfield=vpresent;
							elseif substr(vleaves,1,2)='A/' and vpresent= 'A/A' then
								set vsetfield=vleaves;
							elseif vleaves not in ('A/A','A/','/A') and vpresent= 'A/A' then
								set vsetfield=vleaves;
							elseif vweekoff='/WO' and substr(vleaves,length(vleaves)-1,length(vleaves))='/A' then
								set vsetfield=replace(vleaves,'/A','/WO');
							elseif vweekoff='/WO' and vpresent='P/A' then
								set vsetfield='P/WO';
							elseif vweekoff='/WO' and vholiday is not null then
								set vsetfield='HO/WO';
							elseif ifnull(vweekoff,'X') <>'/WO' and vholiday is not null then
								set vsetfield=vholiday;
							elseif vweekoff='HO/WO' then
								set vsetfield='HO/WO';
							elseif vweekoff='/WO' and vothers='NA' then
								if vprorate_code=2 then
									set vsetfield='NA/WO';
								else
									set vsetfield='NA';
								end if;
							elseif vweekoff='WO' and vothers='NA' then
								if vprorate_code=2 then
									set vsetfield='WO';
								else
									set vsetfield='NA';
								end if;
							elseif vweekoff='/WO' and vpresent is null then
								set vsetfield='A/WO';
							elseif vweekoff='/WO' and vpresent='A/A' then
								set vsetfield='A/WO';
							elseif vweekoff='/WO' and vpresent='A/A' and substr(vleaves,length(vleaves)-1,length(vleaves))='/A'then
								set vsetfield=replace(vleaves,'/A','/WO');
							end if;
							
							if vholiday='HO' and vothers='NA' then
								if vprorate_code=2 then
									set vsetfield='HO';
								else
									set vsetfield='NA';
								end if;
							end if;
							
							if vweekoff='/WO' and vpresent='A/A' and substr(vleaves,length(vleaves)-1,length(vleaves))='/A'then
								set vsetfield=replace(vleaves,'/A','/WO');
							end if;
							
							if vweekoff='WO' and vpresent is not null then
								set vsetfield=vweekoff;
							end if;
							
							if vweekoff is not null then
								if vleaves is not null  then
									if vprorate_code=2 then
										set vsetfield=vweekoff;
									else
										set vsetfield=vleaves;
									end if;
								end if;
							end if;
							
							if vholiday is not null then
								if vleaves is not null  then
									if vprorate_code=2 then
										set vsetfield=vholiday;
									else
										set vsetfield=vleaves;
									end if;
								end if;
							end if;
							
							if vsimple_att<>0 then
								if vleaves is not null  then
									if substr(vleaves,length(vleaves)-1,length(vleaves))='/A' then	
										set vsetfield=concat(replace(vleaves,'/A',''),'/P');
									elseif substr(vleaves,1,2)='A/' then	
										set vsetfield=concat('P/',replace(vleaves,'A/',''))		;	
									end if;
									if vweekoff is not null then
										if vprorate_code=2 then
											set vsetfield=vweekoff;
										else
											set vsetfield=vleaves;
										end if;
									end if;  
									if vholiday is not null then
										if vprorate_code=2 then
											set vsetfield=vholiday;
										else
											set vsetfield=vleaves;
										end if;
									end if;
								end if;
							end if; 	
							
							if vweekoff='/WO' and vpresent is null and substr(vleaves,length(vleaves)-1,length(vleaves))='/A'then
								set vsetfield=replace(vleaves,'/A','/WO');
							end if;
							
							if vweekoff='/WO' and vpresent='A/A' and substr(vleaves,length(vleaves)-1,length(vleaves))='/A'then
								set vsetfield=replace(vleaves,'/A','/WO');
							end if;	
							
							if vweekoff='/WO' and vpresent is null and substr(vleaves,length(vleaves)-1,length(vleaves))!='/A'then
