DROP FUNCTION IF EXISTS `last_punch_fn`;;
CREATE FUNCTION `last_punch_fn` (`pemp_fkey` int) RETURNS varchar(100) CHARACTER SET 'latin1' LANGUAGE SQL
begin
declare vC1 varchar(20);
declare vLOGDATE varchar(30) ;
declare vC3 varchar(20);
declare vdaytimeId int;
declare vmultishift int;
declare vdirection varchar(10);
declare vout varchar(100);
declare vmessage varchar(100);
declare von_dutty1 varchar(10);
declare voff_dutty1 varchar(10);
declare visnextday int;
declare von_dutty2 varchar(10);
declare voff_dutty2 varchar(10);
declare visnextday1 int;
declare vstrict_monitorings varchar(10);


select C1,LOGDATE,C3 into vC1,vLOGDATE,vC3 from device_attandance where emp_id in (select emp_id from emp_details where emp_pkey =pemp_fkey )
				 
and (status = 'Y')  or (status = 'N' and ifnull(c7,'X')='Y') order by LOGDATE desc limit 1 ;

select day_time_seq,multishift into vdaytimeId,vmultishift from emp_proff where emp_fkey=pemp_fkey;

select distinct on_dutty1,off_dutty1,isnextday,strict_monitorings into von_dutty1,voff_dutty1,visnextday,vstrict_monitorings
				
from working_day_time_procedures where day_time_seq=vdaytimeId ;



IF vmultishift IS NULL OR vmultishift = 0 THEN
if visnextday = 1 then
if lower(vc1) ='in' then
if CURRENT_TIMESTAMP between vLOGDATE and ADDTIME(date_format(concat(date_format(DATE_ADD(vLOGDATE, INTERVAL 1 DAY),'%Y-%m-%d'),' ',voff_dutty1),'%Y-%m-%d %H:%i:%s'),'02:00') then
set vdirection='out';
else
set vdirection='in';
set vmessage= 'Have a Great Day';
end if;
end if;
else
if lower(vc1) ='in' then
if CURRENT_TIMESTAMP between vLOGDATE and date_format(concat(date_format(vLOGDATE,'%Y-%m-%d'),' ','23:59:59'),'%Y-%m-%d %H:%i:%s') then
set vdirection='out';
else
set vdirection='in';
set vmessage= 'Have a Great Day';
end if;
end if;
end if;
else
select on_dutty1,off_dutty1,isnextday into von_dutty2,voff_dutty2,visnextday1 from working_day_time_procedures where day_time_seq=vmultishift ;
if visnextday = 1 then
if lower(vc1) ='in' then
if CURRENT_TIMESTAMP between vLOGDATE and ADDTIME(date_format(concat(date_format(DATE_ADD(vLOGDATE, INTERVAL 1 DAY),'%Y-%m-%d'),' ',voff_dutty1),'%Y-%m-%d %H:%i:%s'),'02:00') then
set vdirection='out';
else
set vdirection='in';
set vmessage= 'Have a Great Day';
end if;
end if;
else
if lower(vc1) ='in' then
if CURRENT_TIMESTAMP between vLOGDATE and date_format(concat(date_format(vLOGDATE,'%Y-%m-%d'),' ','23:59:59'),'%Y-%m-%d %H:%i:%s') then
set vdirection='out';
else
set vdirection='in';
set vmessage= 'Have a Great Day';
end if;
end if;
end if;
if visnextday1 = 1 then
if lower(vc1) ='in' then
if CURRENT_TIMESTAMP between vLOGDATE and ADDTIME(date_format(concat(date_format(DATE_ADD(vLOGDATE, INTERVAL 1 DAY),'%Y-%m-%d'),' ',voff_dutty2),'%Y-%m-%d %H:%i:%s'),'02:00') then
set vdirection='out';
else
set vdirection='in';
set vmessage= 'Have a Great Day';
end if;
end if;
else
if lower(vc1) ='in' then
if CURRENT_TIMESTAMP between vLOGDATE and date_format(concat(date_format(vLOGDATE,'%Y-%m-%d'),' ','23:59:59'),'%Y-%m-%d %H:%i:%s') then
set vdirection='out';
else
set vdirection='in';
set vmessage= 'Have a Great Day';
end if;
end if;
end if;
end if;


if vdirection is null then
set vdirection = 'in';
end if;
set vout= vdirection;
return vout;
end;;

DROP PROCEDURE IF EXISTS `leavepolicy_start_end_insert_prc`;;
CREATE PROCEDURE `leavepolicy_start_end_insert_prc` (OUT `perr_msg` varchar(20))
begin
declare vbranch_code varchar(30);

declare exit_loop boolean default false;

declare branch_cur cursor for
select branch_code from branches
where status = 1;

declare continue handler for not found set exit_loop = true;

open branch_cur;
	branch_loop: loop
		fetch branch_cur into vbranch_code;
		
		if exit_loop then
			leave branch_loop;
		end if;
		
		block2:begin
		declare vLEAVEPOLICYID int;
		declare vleave_policy_type char(2);
		declare vsalary_head_item_fkey int;
		declare vleave_cycle_start_date date;
		declare vleave_cycle_end_date date;
		declare vnew_leave_cycle_start_date date;
		declare vnew_leave_cycle_end_date date;
		declare vcount int;
		
		declare exit_loop2 boolean default false;
		
		declare leave_cur cursor for
		select LEAVEPOLICYID, leave_policy_type, salary_head_item_fkey, leave_cycle_start_date, leave_cycle_end_date
		from leavepolicy where status=1 and LEAVEPOLICY_GROUP_ID in (select LEAVEPOLICY_GROUP_ID from leavepolicy_group where status = 1)
		and LEAVEPOLICY_GROUP_ID IN (SELECT LEAVEPOLICY_GROUP_ID from emp_proff where emp_fkey in (select emp_pkey from emp_details where branch_code = vbranch_code and status = 1));

		declare continue handler for not found set exit_loop2 = true;
		
		open leave_cur;
		start_loop: loop
			fetch leave_cur into VLEAVEPOLICYID, vleave_policy_type, vsalary_head_item_fkey, vleave_cycle_start_date, vleave_cycle_end_date;
			
			if exit_loop2 then 
				leave start_loop;
			end if;
			
			select count(*) into vcount from salary_head_items where lcase(item_type) = 'leave'
			and lcase(occurance) = 'coff' and salary_head_item_pkey = vsalary_head_item_fkey and value = 'Y';
			
			if vcount <> 0 then
				update leavepolicy set alloted_leave_forthe_year = 0 ,alloted_leave_forthe_month = 0 where LEAVEPOLICYID = vLEAVEPOLICYID;
			end if;
			
			if vleave_cycle_start_date is null or vleave_cycle_end_date is null then
				if vleave_policy_type = 'Y' then
					select start_month, end_month into vnew_leave_cycle_start_date, vnew_leave_cycle_end_date
					from fin_year where ucase(Year_status) = 'OPEN' and is_current_finyear = 'Y' and vattr1 = 0
					and status = 1 and branch_code = vbranch_code;
				elseif vleave_policy_type = 'M' then
					select att_start_end_fn(date_format(current_date, '%Y-%m-01'), 1) into vnew_leave_cycle_start_date;
					select att_start_end_fn(date_format(current_date, '%Y-%m-01'), 2) into vnew_leave_cycle_end_date;
				elseif vleave_policy_type = 'Q' then
					set vnew_leave_cycle_start_date = date_format(makedate(year(current_date), 1) + interval quarter(current_date) quarter - interval 1 quarter,'%Y-%m-%d');
					set vnew_leave_cycle_end_date = last_day(makedate(year(current_date), 1) + interval quarter(current_date) quarter - interval 1 month);
				elseif vleave_policy_type = 'H' then
					set vnew_leave_cycle_start_date = makedate(year(current_date), 1) + interval if(month(current_date) <= 6, 0, 6) month;
					set vnew_leave_cycle_end_date = date_add(makedate(year(current_date), 1) + interval if(month(current_date) <= 6, 0, 6) month, interval 6 month) - interval 1 day;
				elseif vleave_policy_type = 'P' then
					select start_month, end_month into vnew_leave_cycle_start_date, vnew_leave_cycle_end_date
					from fin_year where ucase(Year_status) = 'OPEN' and is_current_finyear = 'Y' and vattr1 = 0
					and status = 1 and branch_code = vbranch_code;
				end if;
				
				update leavepolicy set leave_cycle_start_date = vnew_leave_cycle_start_date, leave_cycle_end_date = vnew_leave_cycle_end_date where LEAVEPOLICYID = vLEAVEPOLICYID;
			end if;
		end loop start_loop;
		close leave_cur;
		end block2;
	end loop branch_loop;
close branch_cur;

set perr_msg = 'OK';
end;;

DROP FUNCTION IF EXISTS `leave_auth_apr_person_fn`;;
CREATE FUNCTION `leave_auth_apr_person_fn` (`pcompany_code` varchar(10), `plogin_emp_fkey` int, `paction` varchar(10)) RETURNS varchar(1000) CHARACTER SET 'latin1' LANGUAGE SQL
begin
declare vfullcnt float;
declare vhalfcnt float;
declare vleavecnt float;
declare vstart_month date;
declare vend_month date;
declare vleave_for_thyear float;
declare vcarry_forwarded float;
declare vemp_pkey int;
declare vfin_count int;
declare pfinyear varchar(30);
declare vauth_pkey int;
declare vapr_pkey int;
declare vreturn varchar(500);
declare valid_emp_count int;
declare vcompany_code varchar(20);
declare vpolicy_id varchar(20);
DECLARE exit_loop1 BOOLEAN default FALSE;
   
   select company_code into vcompany_code from emp_details where emp_pkey=plogin_emp_fkey;

 if ucase(paction)='AUTH' then
 
      select attr1 into vauth_pkey from emp_proff where emp_fkey=plogin_emp_fkey;
	 
  	 	  
      if vauth_pkey is null then    
         set vreturn=0;
	  else
	   set vreturn=vauth_pkey;
	  end if; 
     
     if vcompany_code='MBCT' THEN
	     if vauth_pkey is null then    
         set vreturn=0;
	  else
	   set vreturn=vauth_pkey;
	  end if;
   elseif vcompany_code='INFR' THEN
	   set vreturn= concat(358,',',381,',',391,',',334,',',234,',',219,',',332,',',376,',',371,',',356,',',373,',',307,',',300,',',403,',',271,',',410,',',217,',',392,',',514,',',515,',',337,',',523) ; 
    
	  else	 
     
	
       if vauth_pkey is not null then  
	    set vreturn=vauth_pkey ;
		else 
		 set vreturn=0;
	   end if;
	 end if;
elseif ucase(paction)='APR' then  
     
   select attr1 into vapr_pkey from emp_proff where emp_fkey=plogin_emp_fkey;
   select GROUP_CONCAT(policy_id) into vpolicy_id from emp_config where type='LAPPR'and emp_fkey=plogin_emp_fkey	 and status=1 ;  
   if vcompany_code='MBCT' THEN
	    if vpolicy_id is not null then
	    set vreturn=vpolicy_id ;
	  else 
		 set vreturn=0;
	 end if ; 
	elseif vcompany_code='INFR' THEN
	set vreturn=concat(plogin_emp_fkey,',',392,',',224,',',490,',',171,',',501,',',514,',',515,',',337,',',523) ; 
	else
	    IF vpolicy_id is not null then
		set vreturn=vpolicy_id;
        elseif vapr_pkey is not null then
	    set vreturn=concat(vapr_pkey,',',plogin_emp_fkey) ;
		else 
		 set vreturn=0;
	   end if;
	end if;
		
elseif ucase(paction)='API' then  

      select attr1 into vapr_pkey from emp_proff where emp_fkey=plogin_emp_fkey;
   select GROUP_CONCAT(policy_id) into vpolicy_id from emp_config where type='LAPPR'and emp_fkey=plogin_emp_fkey	 and status=1 ;  
   if vcompany_code='MBCT' THEN
	    if vpolicy_id is not null then
	    set vreturn=vpolicy_id ;
	  else 
		 set vreturn=0;
	 end if ; 
	elseif vcompany_code='INFR' THEN
	set vreturn=concat(plogin_emp_fkey,',',392,',',224,',',490,',',171,',',501,',',514,',',515,',',337,',',523) ; 
	else
	    IF vpolicy_id is not null then
		set vreturn=vpolicy_id;
        elseif vapr_pkey is not null then
	    set vreturn=concat(vapr_pkey,',',plogin_emp_fkey) ;
		else 
		 set vreturn=0;
	   end if;
	end if;

end if;
	  
return vreturn ;
end;;

DROP FUNCTION IF EXISTS `leave_auth_apr_person_fnmbct`;;
CREATE FUNCTION `leave_auth_apr_person_fnmbct` (`pcompany_code` varchar(10), `plogin_emp_fkey` int, `paction` varchar(10), `psalary_head_item_fkey` int(11)) RETURNS varchar(1000) CHARACTER SET 'latin1' LANGUAGE SQL
begin
declare vfullcnt float;
declare vhalfcnt float;
declare vleavecnt float;
