declare vsanction_by int;
DECLARE exit_loop1 BOOLEAN default FALSE;
   
   select company_code into vcompany_code from emp_details where emp_pkey=plogin_emp_fkey;

 if ucase(paction)='AUTH' then
 
      select attr1 into vauth_pkey from emp_proff where emp_fkey=plogin_emp_fkey;
	 
  	 	  
