elseif ucase(paction)='APR' then  
     
      select attr1 into vapr_pkey from emp_proff where emp_fkey=plogin_emp_fkey;
	  
	select leval_of_approval,sanction_by into vleval_of_approval ,vsanction_by from leavepolicy 
	 where salary_head_item_fkey=psalary_head_item_fkey and LEAVEPOLICY_GROUP_ID 
