	set vreturn=concat(plogin_emp_fkey,',',392,',',224,',',490,',',171,',',501) ;
	
	else
       if vapr_pkey is not null then
	    set vreturn=concat(vapr_pkey,',',plogin_emp_fkey) ;
		ELSeIF vpolicy_id is not null then
		set vreturn=vpolicy_id;
		else 
		 set vreturn=0;
	   end if;
	end if;
elseif ucase(paction)='API' then  

      select attr1 into vauth_pkey from emp_proff where emp_fkey=plogin_emp_fkey;
	
  	  select policy_id  into vpolicy_id from emp_config where type='LAPPR'and emp_fkey=plogin_emp_fkey	 and status=1 limit 1;  	  
      if vauth_pkey is null then    
         set vreturn=0;
	  else
	   set vreturn=vauth_pkey;
	  end if; 
   if vcompany_code='MBCT' THEN
	  if vauth_pkey is null then    
         set vreturn=0;
	  else
	 
	   if vpolicy_id is not null then
	    set vreturn=vpolicy_id ;
	   ELSE
	  set vreturn=vauth_pkey;
	   end if;
	  end if;
   elseif vcompany_code='INFR' THEN
	   set vreturn= concat(358,',',381,',',391,',',334,',',234,',',219,',',332,',',376,',',371,',',356,',',373,',',307,',',300,',',403,',',271,',',410,',',217,',',392,',',224,',',490,',',171,',',501) ; 
    
	  else
    if vpolicy_id is null then
      select attr1 into vpolicy_id from emp_proff where emp_fkey=vauth_pkey;	
	end if;  
	  select count(*) into valid_emp_count from emp_details where emp_pkey=vpolicy_id and status=1;
       if valid_emp_count !=0 then
	    set vreturn=vpolicy_id ;
	  end if;
	   end if;
end if;
	  
return vreturn ;
end;;

DROP FUNCTION IF EXISTS `leave_balance_inthe_month_fn`;;
CREATE FUNCTION `leave_balance_inthe_month_fn` (`Pemp_fkey` int, `psalary_head_item_fkey` int, `Pmonth` date, `pfinyear` varchar(30)) RETURNS float LANGUAGE SQL
READS SQL DATA
    DETERMINISTIC
begin
declare vfullcnt float;
declare vhalfcnt float;
declare vleavecnt float;
declare vfulllastcnt float;
declare vhalflastcnt float;
declare vstart_month date;
declare vend_month date;
declare vleave_forthe_month float;
declare vattendance_date  int;
declare vmonthly_att_fromdate date;
declare vmonthly_att_todate date;
declare vleavetaken float;
declare vmcount float;
declare available_cnt float;
declare cumulated_cnt float;
declare cumulated_monthcnt float;
declare valloted_leave_forthe_year float;
declare vcarry_forwarded float;
declare vcount int;
declare vjoiningdate date;
declare vcompoff float;
declare veligibility float;
declare vencash_days float;
declare vALLOW_NEGETIVE char(1);
declare vleave_policy_type char(1);
declare valloted_leave_forthe_month float;
declare vmonth_yr date;
declare vlastmonth_yr date;
declare vprobationexitdate date;
declare vemp_branch varchar(20);
declare vlastmonthly_att_fromdate date;
declare vlastmonthly_att_todate date;
declare vleavemonthtaken float;
declare vpresant_toatal float;
declare vterminatedcnt int;
declare vlastworkingdate date;
declare vbalance float;
declare vmonthly_limt float;
declare vwork_time_day_off_cal_ot int;

select ifnull(leave_policy_type ,'Y')
  into vleave_policy_type
  from leavepolicy where salary_head_item_fkey=psalary_head_item_fkey and status=1 and LEAVEPOLICY_GROUP_ID
          in (SELECT LEAVEPOLICY_GROUP_ID FROM emp_proff WHERE emp_fkey=PEMP_fkey ) ;
	
	select work_time_day_off_cal_ot into vwork_time_day_off_cal_ot 
				   from working_day_time_procedures where day_time_seq in (select day_time_seq from emp_proff where emp_fkey=Pemp_fkey);
				
	 
if vleave_policy_type='Y' then

select  carry_forwarded into vcarry_forwarded from emp_leave_balance_year where emp_fkey=PEMP_fkey and 
   salary_head_item_fkey=psalary_head_item_fkey and fin_year=pfinyear and status = 1;
   
   select start_month, end_month into vstart_month ,vend_month   from fin_year where fin_year=pfinyear and vattr1=0 and status = 1
   and branch_code = (select branch_code from emp_details where emp_pkey=PEMP_fkey) ;
   
 
   
select alloted_leave_forthe_month ,alloted_leave_forthe_year,ALLOW_NEGETIVE
  into vleave_forthe_month,valloted_leave_forthe_year,vALLOW_NEGETIVE
  from leavepolicy where salary_head_item_fkey=psalary_head_item_fkey and status=1 and LEAVEPOLICY_GROUP_ID
          in (SELECT LEAVEPOLICY_GROUP_ID FROM emp_proff WHERE emp_fkey=PEMP_fkey ) ;
		  
set valloted_leave_forthe_year=valloted_leave_forthe_year ;

select joining_date into vjoiningdate from emp_proff where emp_fkey=PEMP_fkey and joining_date between vstart_month and vend_month ;

select DATE_ADD(joining_date, INTERVAL ifnull(attr2,0) DAY) ,emp_branch into vprobationexitdate ,vemp_branch from emp_proff where emp_fkey=PEMP_fkey and DATE_ADD(joining_date, INTERVAL ifnull(attr2,0) DAY) between vstart_month and vend_month ;

select count(*) into vfullcnt from emp_leave_transactions where leave_session=3 and  Remarks!='No need Leave'
                          and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vstart_month  and vend_month ;

 select count(*) into vhalfcnt from emp_leave_transactions where leave_session!=3 and Remarks!='No need Leave'
                         and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vstart_month  and vend_month ;

select sum(approved_days) into vencash_days from  leave_encashment_master
               where  salary_head_item_fkey=psalary_head_item_fkey and emp_fkey=Pemp_fkey and is_approved ='Y' and status = 1 and approved_date between vstart_month  and vend_month ;					  

set vleavetaken =(ifnull(vfullcnt,0) + ifnull(vhalfcnt,0) *.5 + ifnull(vencash_days,0));
    
	 if substr(vemp_branch,1,4)='INFR' then
    if vprobationexitdate is not null then
	SELECT TIMESTAMPDIFF(MONTH, vprobationexitdate, ifnull(pmonth,current_date))+1 into vmcount;
	elseif vjoiningdate is null then
	SELECT TIMESTAMPDIFF(MONTH, vstart_month, ifnull(pmonth,current_date))+1 into vmcount;
	else 
	SELECT TIMESTAMPDIFF(MONTH, vjoiningdate, ifnull(pmonth,current_date ))+1 into vmcount;
	end if;
	else
	if vjoiningdate is null then
	SELECT TIMESTAMPDIFF(MONTH, vstart_month, ifnull(pmonth,current_date))+1 into vmcount;
	else 
	SELECT TIMESTAMPDIFF(MONTH, vjoiningdate, ifnull(pmonth,current_date ))+1 into vmcount;
	end if;
	end if;
		

if vleavetaken<valloted_leave_forthe_year then
   if vALLOW_NEGETIVE ='Y' then
   if substr(vemp_branch,1,4)='INFR' then
    if vprobationexitdate is not null then
	SELECT TIMESTAMPDIFF(MONTH, vprobationexitdate, vend_month)+1 into vmcount; 
	elseif vjoiningdate is null then
	SELECT TIMESTAMPDIFF(MONTH, vstart_month, vend_month)+1 into vmcount;
	else 
	SELECT TIMESTAMPDIFF(MONTH, vjoiningdate, vend_month)+1 into vmcount;
	end if;
    else
    if vjoiningdate is null then
	SELECT TIMESTAMPDIFF(MONTH, vstart_month, vend_month)+1 into vmcount;
	else 
	SELECT TIMESTAMPDIFF(MONTH, vjoiningdate, vend_month)+1 into vmcount;
	end if; 
    end if;	
   if vmcount=0 then
		 set vmcount=1;
		else
		set vmcount=vmcount;
		end if;
		set cumulated_monthcnt = valloted_leave_forthe_year/12;
		set valloted_leave_forthe_year = vmcount*cumulated_monthcnt;	
		  
    set available_cnt=(ifnull(valloted_leave_forthe_year,0)+ifnull(vcarry_forwarded,0))-vleavetaken;
   
   else
		if vmcount=0 then
		 set vmcount=1;
		else
		set vmcount=vmcount;
		end if;
		set cumulated_monthcnt= valloted_leave_forthe_year/12;
		set cumulated_cnt= (vmcount*cumulated_monthcnt)+ifnull(vcarry_forwarded,0);
		 if cumulated_cnt > vleavetaken then
		     set available_cnt= cumulated_cnt-vleavetaken  ;
			
			 else
			 set available_cnt=0;
			 end if;
	end if;		
		else 
		set available_cnt=(valloted_leave_forthe_year+ifnull(vcarry_forwarded,0))-vleavetaken;
 end if;
  select count(*)  into vcount from salary_head_items where lcase(item_type)='leave' 
      and lcase(occurance)='coff' and salary_head_item_pkey=psalary_head_item_fkey and value='Y';
	  
 if vcount<>0 then 
    select sum(compoff) into vcompoff from 
   (select count(*) as compoff 
                        from attendance_register 
                         where (FIELD1='COFF' OR FIELD2='COFF' OR FIELD3='COFF' OR FIELD4='COFF' 
                         OR FIELD5='COFF' OR FIELD6='COFF' OR FIELD7='COFF' OR FIELD8='COFF' OR 
                         FIELD9='COFF' OR FIELD10='COFF' OR FIELD11='COFF' OR FIELD12='COFF' OR 
                         FIELD13='COFF' OR FIELD14='COFF' OR FIELD15='COFF' OR FIELD16='COFF' OR 
                         FIELD17='COFF' OR FIELD18='COFF' OR FIELD19='COFF' OR FIELD20='COFF' OR 
                         FIELD21='COFF' OR FIELD22='COFF' OR FIELD23='COFF' OR FIELD24='COFF' OR 
                         FIELD25='COFF' OR FIELD26='COFF' OR FIELD27='COFF' OR FIELD28='COFF' OR 
                         FIELD29='COFF' OR FIELD30='COFF' OR FIELD31='COFF' OR FIELD32='COFF')
                        and isdelete='N' and concat(month_year,'-01') between vstart_month and vend_month and attendance_register.emp_fkey = Pemp_fkey
						union all
						select count(*)  from emp_leave_transactions where leave_session=3 and  Remarks!='No need Leave'
                          and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
						  and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items 
                                     where item_type='LEAVE' and occurance='COFF' and status =1)
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vstart_month  and vend_month 
					  union all
					 select count(*)*.5 from emp_leave_transactions where leave_session!=3 and Remarks!='No need Leave'
                         and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
						 and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items 
                                     where item_type='LEAVE' and occurance='COFF' and status =1)
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vstart_month  and vend_month
						union all
						select sum(approved_days) vencash_days from  leave_encashment_master
						where  salary_head_item_fkey=psalary_head_item_fkey 
						and emp_fkey=Pemp_fkey   and is_approved ='Y' and status = 1  and approved_date between vstart_month  and vend_month
						) b; 
				  
				  if  vwork_time_day_off_cal_ot =4 then
				       select sum(v1) into veligibility from (
						select count(*) v1 from
                        emp_detail_timeattandance where holiday is not null and present='P/P'
                        and yearmonth between vstart_month and vend_month and emp_pkey = Pemp_fkey
						union all
						select count(*)*.5 v1 from
                        emp_detail_timeattandance where holiday is not null and present in('P/A','A/P')
                        and yearmonth between vstart_month and vend_month and emp_pkey = Pemp_fkey
                        ) a; 
				  else
						select sum(v1) into veligibility from (
						select count(*) v1 from
                        emp_detail_timeattandance where (weekoff is not null or holiday is not null)and ifnull(weekoff,'X') <>'/WO' and present='P/P'
                        and yearmonth between vstart_month and vend_month and emp_pkey =Pemp_fkey
                        union all
                        select count(*)*.5 v1 from
                        emp_detail_timeattandance  where (weekoff is not null or holiday is not null) 
						and ifnull(weekoff,'X') <>'/WO' and present in('P/A','A/P')
                        and yearmonth between vstart_month and vend_month and emp_pkey =Pemp_fkey
						union all
						select count(*)*.5 v1 from
                        emp_detail_timeattandance where  holiday is not null
						 and ifnull(weekoff,'X') ='/WO' and present='P/A'
						 and yearmonth between vstart_month and vend_month and emp_pkey =Pemp_fkey
                        ) a;
					end if;	
			set available_cnt = ifnull(veligibility,0) - ifnull(vcompoff,0) ;	
                         if available_cnt <=0 then
                            set available_cnt =0;
                      end if; 		
	end if;	
elseif vleave_policy_type='M' then	
select alloted_leave_forthe_month ,CARRY_FORWARD_LIMIT
  into valloted_leave_forthe_month,vcarry_forwarded
  from leavepolicy where salary_head_item_fkey=psalary_head_item_fkey and status=1 and LEAVEPOLICY_GROUP_ID
          in (SELECT LEAVEPOLICY_GROUP_ID FROM emp_proff WHERE emp_fkey=PEMP_fkey ) ;										   
 select count(*)  into vcount from salary_head_items where lcase(item_type)='leave' and lcase(occurance)='coff' and salary_head_item_pkey=psalary_head_item_fkey and value='Y';
 
 set vmonth_yr  = concat(DATE_FORMAT(Pmonth, '%Y-%m'),'-01');
SELECT att_start_end_fn(DATE_FORMAT(vmonth_yr, '%Y-%m-01'), 1) into vmonthly_att_fromdate;
SELECT att_start_end_fn(DATE_FORMAT(vmonth_yr, '%Y-%m-01'), 2) into vmonthly_att_todate;

set vlastmonth_yr  = DATE_ADD(DATE_ADD(LAST_DAY(Pmonth), INTERVAL 1 DAY),INTERVAL - 2 MONTH) ;
SELECT att_start_end_fn(DATE_FORMAT(vlastmonth_yr, '%Y-%m-01'), 1) into vlastmonthly_att_fromdate;
SELECT att_start_end_fn(DATE_FORMAT(vlastmonth_yr, '%Y-%m-01'), 2) into vlastmonthly_att_todate;

 if vcount<>0 then 
  if vcarry_forwarded >0 then
    select sum(compoff) into vcompoff from 
   (	select count(*)compoff  from emp_leave_transactions where leave_session=3 and  Remarks!='No need Leave'
                          and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
						  and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items 
                                     where item_type='LEAVE' and occurance='COFF' and status =1)
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between  vlastmonthly_att_fromdate  and vmonthly_att_todate
					  union all
					 select count(*)*.5 compoff from emp_leave_transactions where leave_session!=3 and Remarks!='No need Leave'
                         and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
						 and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items 
                                     where item_type='LEAVE' and occurance='COFF' and status =1)
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vlastmonthly_att_fromdate  and vmonthly_att_todate						  
   
      union all
         select sum(approved_days) compoff from  leave_encashment_master
				   where  salary_head_item_fkey=psalary_head_item_fkey 
				      and emp_fkey=Pemp_fkey  and is_approved ='Y' and status = 1  and approved_date between vlastmonthly_att_fromdate  and vmonthly_att_todate) b;
					  
				 if  vwork_time_day_off_cal_ot =4 then
				       select sum(v1) into veligibility from (
						select count(*) v1 from
                        emp_detail_timeattandance where holiday is not null and present='P/P'
                        and yearmonth between vlastmonthly_att_fromdate and vmonthly_att_todate and emp_pkey = Pemp_fkey
						union all
						select count(*)*.5 v1 from
                        emp_detail_timeattandance where holiday is not null and present in('P/A','A/P')
                        and yearmonth between vstart_month and vend_month and emp_pkey = Pemp_fkey
                        ) a; 
				  else			
												
						select sum(v1) into veligibility from (
						select count(*) v1 from
                        emp_detail_timeattandance where (weekoff is not null or holiday is not null)and ifnull(weekoff,'X') <>'/WO' and present='P/P'
                        and att_date between vlastmonthly_att_fromdate 
									   and vmonthly_att_todate  and emp_pkey =Pemp_fkey
                        union all
                        select count(*)*.5 v1 from
                        emp_detail_timeattandance  where (weekoff is not null or holiday is not null) 
						and ifnull(weekoff,'X') <>'/WO' and present in('P/A','A/P')
                        and att_date between vlastmonthly_att_fromdate
									   and vmonthly_att_todate and emp_pkey =Pemp_fkey
						union all
						select count(*)*.5 v1 from
                        emp_detail_timeattandance where  holiday is not null
						 and ifnull(weekoff,'X') ='/WO' and present='P/A'
						 and att_date between vlastmonthly_att_fromdate 
									   and vmonthly_att_todate and emp_pkey =Pemp_fkey
                        ) a;
			     end if;			
			set available_cnt = ifnull(veligibility,0) - ifnull(vcompoff,0) ;	
                         if available_cnt <=0 then
                            set available_cnt =0;
                      end if; 
			
      else

      select sum(compoff) into vcompoff from 
   (	select count(*)compoff  from emp_leave_transactions where leave_session=3 and  Remarks!='No need Leave'
                          and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
						  and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items 
                                     where item_type='LEAVE' and occurance='COFF' and status =1)
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between  DATE_FORMAT(Pmonth , '%Y-%m-01') and LAST_DAY(Pmonth ) 
					  union all
					 select count(*)*.5 compoff from emp_leave_transactions where leave_session!=3 and Remarks!='No need Leave'
                         and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
						 and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items 
                                     where item_type='LEAVE' and occurance='COFF' and status =1)
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between DATE_FORMAT(Pmonth , '%Y-%m-01') and LAST_DAY(Pmonth )						  
  		union all
         select sum(approved_days) compoff from  leave_encashment_master
				   where  salary_head_item_fkey=psalary_head_item_fkey 
				      and emp_fkey=Pemp_fkey  and is_approved ='Y' and status = 1  and approved_date between vmonthly_att_fromdate  and vmonthly_att_todate) b;
					  
				 if  vwork_time_day_off_cal_ot =4 then
				       select sum(v1) into veligibility from (
						select count(*) v1 from
                        emp_detail_timeattandance where holiday is not null and present='P/P'
                        and yearmonth between vmonthly_att_fromdate and vmonthly_att_todate and emp_pkey = Pemp_fkey
						union all
						select count(*)*.5 v1 from
                        emp_detail_timeattandance where holiday is not null and present in('P/A','A/P')
                        and yearmonth between vstart_month and vend_month and emp_pkey = Pemp_fkey
                        ) a; 
				  else					
												
						select sum(v1) into veligibility from (
						select count(*) v1 from
                        emp_detail_timeattandance where (weekoff is not null or holiday is not null)and ifnull(weekoff,'X') <>'/WO' and present='P/P'
                        and att_date between vmonthly_att_fromdate
									   and vmonthly_att_todate  and emp_pkey =Pemp_fkey
                        union all
                        select count(*)*.5 v1 from
                        emp_detail_timeattandance  where (weekoff is not null or holiday is not null) 
						and ifnull(weekoff,'X') <>'/WO' and present in('P/A','A/P')
                        and att_date between vmonthly_att_fromdate 
									   and vmonthly_att_todate and emp_pkey =Pemp_fkey
						union all
						select count(*)*.5 v1 from
                        emp_detail_timeattandance where  holiday is not null
						 and ifnull(weekoff,'X') ='/WO' and present='P/A'
						 and att_date between vmonthly_att_fromdate 
									   and vmonthly_att_todate and emp_pkey =Pemp_fkey
                        ) a;
			   end if;			
			set available_cnt = ifnull(veligibility,0) - ifnull(vcompoff,0) ;	
                         if available_cnt <=0 then
                            set available_cnt =0;
                      end if; 



   end if;			 
		  
	else
 select alloted_leave_forthe_month ,CARRY_FORWARD_LIMIT
  into valloted_leave_forthe_month,vcarry_forwarded
  from leavepolicy where salary_head_item_fkey=psalary_head_item_fkey and status=1 and LEAVEPOLICY_GROUP_ID
          in (SELECT LEAVEPOLICY_GROUP_ID FROM emp_proff WHERE emp_fkey=PEMP_fkey ) ;
  select joining_date into vjoiningdate from emp_proff where emp_fkey=PEMP_fkey and joining_date between DATE_ADD(DATE_ADD(LAST_DAY(current_date), INTERVAL 1 DAY),INTERVAL - 1 MONTH)  and LAST_DAY(current_date) ;
  if vjoiningdate is not null then
   set vcarry_forwarded=0 ;
  else
   set vcarry_forwarded=vcarry_forwarded;
  end if;
  
  if vcarry_forwarded >0 then
select count(*) into vfulllastcnt from emp_leave_transactions where leave_session=3 and  Remarks!='No need Leave'
                          and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vlastmonthly_att_fromdate  and vlastmonthly_att_todate ;

 select count(*)*.5 into vhalflastcnt from emp_leave_transactions where leave_session!=3 and Remarks!='No need Leave'
                         and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vlastmonthly_att_fromdate  and vlastmonthly_att_todate;
						  
	select count(*) into vfullcnt from emp_leave_transactions where leave_session=3 and  Remarks!='No need Leave'
                          and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vmonthly_att_fromdate and vmonthly_att_todate ;

 select count(*) into vhalfcnt from emp_leave_transactions where leave_session!=3 and Remarks!='No need Leave'
                         and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vmonthly_att_fromdate and vmonthly_att_todate ;					  
						  
						 
						  
   

	
	if (vfulllastcnt+vhalflastcnt)>=(valloted_leave_forthe_month) then
   set vleavecnt = (valloted_leave_forthe_month - (vfullcnt + vhalfcnt *.5)) ;

		else

		if (vfulllastcnt+vhalflastcnt)=0 then
		set vleavecnt = (valloted_leave_forthe_month-(vfullcnt + vhalfcnt *.5))+vcarry_forwarded;
		else

		set vbalance = valloted_leave_forthe_month-(vfulllastcnt+vhalflastcnt);
			if vbalance < vcarry_forwarded then
			set vcarry_forwarded = vbalance ;
			else
			set vcarry_forwarded = vcarry_forwarded ;
			end if;
		set vleavecnt = (valloted_leave_forthe_month-(vfullcnt + vhalfcnt *.5))+vcarry_forwarded;
		end if;
    end if;		
	 
  set available_cnt=vleavecnt;
  else
  	select count(*) into vfullcnt from emp_leave_transactions where leave_session=3 and  Remarks!='No need Leave'
                          and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vmonthly_att_fromdate and vmonthly_att_todate ;

    select count(*) into vhalfcnt from emp_leave_transactions where leave_session!=3 and Remarks!='No need Leave'
                         and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vmonthly_att_fromdate and vmonthly_att_todate ;	
						  
  set vleavecnt =valloted_leave_forthe_month - (vfullcnt + vhalfcnt *.5)	;
  set available_cnt=vleavecnt;
end if;
end if;	

elseif vleave_policy_type='P' then
	
select  carry_forwarded into vcarry_forwarded from emp_leave_balance_year where emp_fkey=PEMP_fkey and 
   salary_head_item_fkey=psalary_head_item_fkey and fin_year=pfinyear and status = 1;
   
   select start_month, end_month into vstart_month ,vend_month   from fin_year where fin_year=pfinyear and vattr1=0 and status = 1
   and branch_code = (select branch_code from emp_details where emp_pkey=PEMP_fkey) ;
   
select alloted_leave_forthe_month ,alloted_leave_forthe_year,ALLOW_NEGETIVE
  into vleave_forthe_month,valloted_leave_forthe_year,vALLOW_NEGETIVE
  from leavepolicy where salary_head_item_fkey=psalary_head_item_fkey and status=1 and LEAVEPOLICY_GROUP_ID
          in (SELECT LEAVEPOLICY_GROUP_ID FROM emp_proff WHERE emp_fkey=PEMP_fkey ) ;
		  
select sum(presant_total) into vpresant_toatal  from attendance_register
     where isdelete='N' and concat(month_year,'-01') between  vstart_month and vend_month and emp_fkey=PEMP_fkey ;
	 
	
  if vcarry_forwarded>0 or vpresant_toatal>0 then
  
      
    set valloted_leave_forthe_year=vpresant_toatal/valloted_leave_forthe_year ;	
	
	set valloted_leave_forthe_year=ifnull(valloted_leave_forthe_year,0)+ifnull(vcarry_forwarded,0) ;

	select joining_date into vjoiningdate from emp_proff where emp_fkey=PEMP_fkey and joining_date between vstart_month and vend_month ;

	select DATE_ADD(joining_date, INTERVAL ifnull(attr2,0) DAY) ,emp_branch into vprobationexitdate ,vemp_branch from emp_proff where emp_fkey=PEMP_fkey and DATE_ADD(joining_date, INTERVAL ifnull(attr2,0) DAY) between vstart_month and vend_month ;

	select count(*) into vfullcnt from emp_leave_transactions where leave_session=3 and  Remarks!='No need Leave'
							  and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
							  and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vstart_month  and vend_month ;

	 select count(*) into vhalfcnt from emp_leave_transactions where leave_session!=3 and Remarks!='No need Leave'
							 and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
							  and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vstart_month  and vend_month ;

	select sum(approved_days) into vencash_days from  leave_encashment_master
				   where  salary_head_item_fkey=psalary_head_item_fkey and emp_fkey=Pemp_fkey  and is_approved ='Y' and status = 1  and approved_date between vstart_month  and vend_month ;					  

set vleavetaken =(ifnull(vfullcnt,0) + ifnull(vhalfcnt,0) *.5 + ifnull(vencash_days,0));

    set vbalance = valloted_leave_forthe_year-vleavetaken;
  
  if vbalance >0 then
     set vmonth_yr  = concat(DATE_FORMAT(Pmonth, '%Y-%m'),'-01');
     SELECT att_start_end_fn(DATE_FORMAT(vmonth_yr, '%Y-%m-01'), 1) into vmonthly_att_fromdate;
     SELECT att_start_end_fn(DATE_FORMAT(vmonth_yr, '%Y-%m-01'), 2) into vmonthly_att_todate;
  
	select count(*) into vfullcnt from emp_leave_transactions where leave_session=3 and  Remarks!='No need Leave'
                          and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vmonthly_att_fromdate  and vmonthly_att_todate ;

    select count(*) into vhalfcnt from emp_leave_transactions where leave_session!=3 and Remarks!='No need Leave'
                         and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vmonthly_att_fromdate  and vmonthly_att_todate ;

    set vleavemonthtaken =(ifnull(vfullcnt,0) + ifnull(vhalfcnt,0) *.5) ;
   
       set vmonthly_limt= vleave_forthe_month-vleavemonthtaken;
	   if vmonthly_limt >= vbalance then
		  set available_cnt=vbalance ;
		 else
            set available_cnt=vmonthly_limt;
         end if;			
	   		
	else 
	 set available_cnt=0;
 end if;
 else 
	 set available_cnt=0;
 end if;

end if;

return (floor((available_cnt)*2)/2 )  ;
end;;

DROP FUNCTION IF EXISTS `leave_balance_inthe_year_fn`;;
CREATE FUNCTION `leave_balance_inthe_year_fn` (`pemp_fkey` int, `psalary_head_item_fkey` int, `pleave_date` date) RETURNS float LANGUAGE SQL
READS SQL DATA
    DETERMINISTIC
begin
declare vleavecnt float;
declare vstart_date date;
declare vend_date date;
declare vpolicy_allotted_balance float;
declare vcarry_forwarded_balance float;
declare vmonthly_att_fromdate date;
declare vmonthly_att_todate date;
declare vyearmonth date;
declare vcount int;
declare vcompoff float;
declare vattendance_balance float;
declare vencash_days float;
declare vjoiningdate date;
declare vmcount float;
declare available_cnt float;
declare cumulated_cnt float;
declare cumulated_monthcnt float;
declare vleave_policy_type char(2);
declare vpresent_days_for_one_leave float;
declare vpresant_total  float;
declare vleavetaken float;
declare vterminatedcnt int;
declare vlastworkingdate date;
declare vwork_time_day_off_cal_ot int;
declare vstart_from int;
declare vallow_all_leaves char(1);
declare vminimum_service float;
declare vexceptions char(1);
declare vadjustments_balance double;
declare vALLOW_NEGETIVE char(1);
declare vdays float;
declare vendprocess_adjust float;
declare vmonth_end date;
declare vholidayId int;
declare vdaytimeId int;
declare vholiday_count int;
declare vweekoff_count int;
declare vSunday char(1);
declare vMonday char(1);
declare vTuesday char(1);
declare vWednesday char(1);
declare vThursday char(1);
declare vFriday char(1);
declare vSaturday char(1);
declare vSunday_F char(1);
declare vMonday_F char(1);
declare vTuesday_F char(1);
declare vWednesday_F char(1);
declare vThursday_F char(1);
declare vFriday_F char(1);
declare vSaturday_F char(1);
declare vday_name varchar(20);
declare vweek int;
declare vex_count int;
declare i int;
declare vweekoff_status varchar(10);
declare vtill_date date;
declare vfrom_date date;
declare vto_date date;
declare vmonth_year date;
declare vverified int;
declare vatt_start date;
declare vfield_idx int;
declare vatt_field_val varchar(20);
declare vhol_count_v int;
declare vweekoff_status_v varchar(10);

call leave_start_end_prc(pemp_fkey,psalary_head_item_fkey,pleave_date,vstart_date,vend_date);

select work_time_day_off_cal_ot into vwork_time_day_off_cal_ot from working_day_time_procedures
where day_time_seq in (select day_time_seq from emp_proff where emp_fkey=pemp_fkey);

select leave_policy_type, alloted_leave_forthe_year, alloted_leave_forthe_month, exceptions, ifnull(minimum_service,0), allow_all_leaves, ALLOW_NEGETIVE
into vleave_policy_type, vpolicy_allotted_balance, vpresent_days_for_one_leave, vexceptions, vminimum_service, vallow_all_leaves, vALLOW_NEGETIVE
from leavepolicy where salary_head_item_fkey=psalary_head_item_fkey and status=1
and LEAVEPOLICY_GROUP_ID in (select LEAVEPOLICY_GROUP_ID from emp_proff where emp_fkey=pemp_fkey);

select joining_date into vjoiningdate from emp_proff where emp_fkey=pemp_fkey;

if pleave_date is null then
	set pleave_date = current_date;
end if;

if day(vstart_date) = 1 then
	set vmonth_end = last_day(date_format(pleave_date, '%Y-%m-%d'));
else
	set vmonthly_att_fromdate = ifnull(date_format(concat(date_format(date_sub(pleave_date, interval 1 month), '%Y-%m-'), day(vstart_date)), '%Y-%m-%d'), date_format(date_add(date_format(concat(date_format(date_sub(pleave_date, interval 1 month), '%Y-%m-'), day(vstart_date) - 1), '%Y-%m-%d'),interval + 1 day), '%Y-%m-%d'));
	set vmonthly_att_todate = date_add(date_format(concat(date_format(date_sub(pleave_date, interval 1 month), '%Y-%m-'), day(vstart_date) - 1), '%Y-%m-%d'), interval 1 month);
	
	if pleave_date between vmonthly_att_fromdate and vmonthly_att_todate then
		set vyearmonth = date_format(pleave_date, '%Y-%m-01');
	else
		set vyearmonth = date_add(date_format(pleave_date, '%Y-%m-01'), interval 1 month);
	end if;
	
	set vmonth_end = date_add(date_format(concat(date_format(date_sub(vyearmonth, interval 1 month), '%Y-%m-'), day(vstart_date) - 1), '%Y-%m-%d'), interval 1 month);
end if;

if vALLOW_NEGETIVE ='Y' then
	set vtill_date = vend_date;
else
	set vtill_date = vmonth_end;
end if;

if vexceptions = 'Y' then
	if vallow_all_leaves = 'Y' then
		if vjoiningdate between vstart_date and vend_date then
			select timestampdiff(month, vjoiningdate, vtill_date)+1 into vmcount;
		else 
			select timestampdiff(month, vstart_date, vtill_date)+1 into vmcount;
		end if;
	else
		if date_add(vjoiningdate, interval vminimum_service month) between vstart_date and vend_date then
			select timestampdiff(month, date_add(vjoiningdate, interval vminimum_service month), vtill_date)+1 into vmcount;
		else
			select timestampdiff(month, vstart_date, vtill_date)+1 into vmcount;
		end if;
	end if;
else
	if vjoiningdate between vstart_date and vend_date then
		select timestampdiff(month, vjoiningdate, vtill_date)+1 into vmcount;
	else
		select timestampdiff(month, vstart_date, vtill_date)+1 into vmcount;
	end if;
end if;

if vmcount=0 then
	set vmcount=1;
else
	set vmcount=vmcount;
end if;

set vdays = timestampdiff(month, vstart_date, vend_date)+1;
set cumulated_monthcnt = vpolicy_allotted_balance/vdays;
set vpolicy_allotted_balance = cumulated_monthcnt*vmcount;

select carry_forwarded, end_process_adjust into vcarry_forwarded_balance, vendprocess_adjust from emp_leave_balance_year where emp_fkey=pemp_fkey
and salary_head_item_fkey=psalary_head_item_fkey and leave_cycle_start_date = vstart_date and leave_cycle_end_date = vend_date and status = 1;

select adjustment into vadjustments_balance from leave_balance_upload where leave_type = psalary_head_item_fkey
and empid in (select emp_company_id from emp_proff where emp_fkey = pemp_fkey) and created_date between vstart_date and vend_date
order by created_date desc limit 1;

select count(*) into vcount from salary_head_items where lcase(item_type) = 'leave'
and lcase(occurance) = 'coff' and salary_head_item_pkey = psalary_head_item_fkey and value = 'Y';

if vleave_policy_type = 'P' then
	select sum(presant_total) into vpresant_total from attendance_register
	where isdelete='N' and concat(month_year,'-01') between vstart_date and vend_date and emp_fkey=pemp_fkey;
	
	if vpresant_total > 0 then
		set vpolicy_allotted_balance = vpresant_total/vpresent_days_for_one_leave;
	end if;
	
	set vattendance_balance = 0;
else
	if vcount <> 0 then
		select HOLIDAY_GROUP_ID, day_time_seq into vholidayId, vdaytimeId from emp_proff where emp_fkey = pemp_fkey;
		
		select Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday_F, Monday_F, Tuesday_F, Wednesday_F, Thursday_F, Friday_F, Saturday_F
		into vSunday, vMonday, vTuesday, vWednesday, vThursday, vFriday, vSaturday, vSunday_F, vMonday_F, vTuesday_F, vWednesday_F, vThursday_F, vFriday_F, vSaturday_F
		from working_day_time_procedures where day_time_seq = vdaytimeId;
		
		set vattendance_balance = 0;
		
		select to_days(vstart_date) into i;
		
		while i <= to_days(vend_date) do
			select att_start_end_fn(date_format(date_format(from_days(i), '%Y-%m-%d'), '%Y-%m-01'), 1) into vfrom_date;
			select att_start_end_fn(date_format(date_format(from_days(i), '%Y-%m-%d'), '%Y-%m-01'), 2) into vto_date;
			
			if date_format(from_days(i), '%Y-%m-%d') between vfrom_date and vto_date then
				set vmonth_year = date_format(date_format(from_days(i), '%Y-%m-%d'), '%Y-%m-01');
			else
				set vmonth_year = date_add(date_format(date_format(from_days(i), '%Y-%m-%d'), '%Y-%m-01'), interval 1 month);
			end if;
			
			select count(*) into vverified from attendance_register
			where emp_fkey = pemp_fkey
			and month_year = date_format(vmonth_year, '%Y-%m')
			and isdelete = 'N';
			
			if vverified > 0 then
				set vatt_field_val = null;
				set vweekoff_status_v = null;
				set vhol_count_v = 0;
				
				select att_start_end_fn(vmonth_year, 1) into vatt_start;
				set vfield_idx = datediff(date_format(from_days(i), '%Y-%m-%d'), vatt_start) + 1;
				
				select case vfield_idx
					when 1  then FIELD1  when 2  then FIELD2  when 3  then FIELD3  when 4  then FIELD4
					when 5  then FIELD5  when 6  then FIELD6  when 7  then FIELD7  when 8  then FIELD8
					when 9  then FIELD9  when 10 then FIELD10 when 11 then FIELD11 when 12 then FIELD12
					when 13 then FIELD13 when 14 then FIELD14 when 15 then FIELD15 when 16 then FIELD16
					when 17 then FIELD17 when 18 then FIELD18 when 19 then FIELD19 when 20 then FIELD20
					when 21 then FIELD21 when 22 then FIELD22 when 23 then FIELD23 when 24 then FIELD24
					when 25 then FIELD25 when 26 then FIELD26 when 27 then FIELD27 when 28 then FIELD28
					when 29 then FIELD29 when 30 then FIELD30 when 31 then FIELD31 when 32 then FIELD32
					else null
				end into vatt_field_val
				from attendance_register
				where emp_fkey = pemp_fkey
				and month_year = date_format(vmonth_year, '%Y-%m')
				and isdelete = 'N'
				limit 1;
				
				if vatt_field_val = 'HO' or vatt_field_val like 'HO/%' then
					set vhol_count_v = 1;
				else
					set vhol_count_v = 0;
				end if;
				
				if vatt_field_val = 'WO' then
					set vweekoff_status_v = 'WO';
				elseif vatt_field_val like '%/WO' then
					set vweekoff_status_v = '/WO';
				else
					set vweekoff_status_v = null;
				end if;
				
				if vwork_time_day_off_cal_ot = 4 then
					if vhol_count_v > 0 then
						select vattendance_balance + case
						                             	when present = 'P/P' then 1
						                             	when present in ('A/P', 'P/A') then 0.5
						                             	else 0
						                             end into vattendance_balance
						from emp_detail_timeattandance where att_date = date_format(from_days(i), '%Y-%m-%d') and emp_pkey = pemp_fkey limit 1;
					end if;
				elseif vwork_time_day_off_cal_ot = 2 then
					if (vhol_count_v > 0 or (vhol_count_v = 0 and vweekoff_status_v = 'WO')) then
						select vattendance_balance + case
						                             	when present = 'P/P' then 1
						                             	when present in ('A/P', 'P/A') then 0.5
						                             	else 0
						                             end into vattendance_balance
						from emp_detail_timeattandance where att_date = date_format(from_days(i), '%Y-%m-%d') and emp_pkey = pemp_fkey limit 1;
					elseif vhol_count_v = 0 and vweekoff_status_v = '/WO' then
						select vattendance_balance + case 
						                             	when present in ('P/P', 'A/P') then 0.5
						                             	else 0
						                             end into vattendance_balance
						from emp_detail_timeattandance where att_date = date_format(from_days(i), '%Y-%m-%d') and emp_pkey = pemp_fkey limit 1;
					end if;
				end if;
			else
				set vweekoff_status = null;
				set vholiday_count = 0;
				set vweekoff_count = 0;
				
				select count(*) into vholiday_count from holidays 
				where HOLIDAY_GROUP_ID=vholidayId 
				and status = 1 and HOLIDAYDATE = date_format(from_days(i), '%Y-%m-%d');
				
				select sum(weekoff) into vweekoff_count from
				(	
					select count(*) as weekoff from working_day_time_procedures 
					where day_time_seq = vdaytimeId and active = 1
					and (Sunday = 'N' or Monday = 'N' or Tuesday = 'N' or Wednesday = 'N' or Thursday = 'N' or Friday = 'N' or Saturday = 'N' 
					or Sunday_F = 'Y' or Monday_F = 'Y' or Tuesday_F = 'Y' or Wednesday_F = 'Y' or Thursday_F = 'Y' or Friday_F = 'Y' or Saturday_F = 'Y')
					union all
					select count(*) as weekoff from shift_exceptions
					where shift_id = vdaytimeId and week_off = 'Y' and status = 1
				) as shift_policy;
				
				if vweekoff_count > 0 then
					set vday_name = lcase(dayname(date_format(from_days(i), '%Y-%m-%d')));
					set vweek = floor((dayofmonth(date_format(from_days(i),'%Y-%m-%d'))-1)/7)+1;
					
					select count(*) into vex_count from shift_exceptions
					where shift_id = vdaytimeId and week_off = 'Y' and status = 1
					and lcase(ex_week_day) = vday_name and cast(ex_week as unsigned) = vweek;
					
					if (vday_name = 'sunday' and (vSunday = 'N' or vex_count > 0)) or
					   (vday_name = 'monday' and (vMonday = 'N' or vex_count > 0)) or
					   (vday_name = 'tuesday' and (vTuesday = 'N' or vex_count > 0)) or
					   (vday_name = 'wednesday' and (vWednesday = 'N' or vex_count > 0)) or
					   (vday_name = 'thursday' and (vThursday = 'N' or vex_count > 0)) or
					   (vday_name = 'friday' and (vFriday = 'N' or vex_count > 0)) or
					   (vday_name = 'saturday' and (vSaturday = 'N' or vex_count > 0)) then
						set vweekoff_status = 'WO';
					elseif (vday_name = 'sunday' and vSunday_F = 'Y') or
					       (vday_name = 'monday' and vMonday_F = 'Y') or
					       (vday_name = 'tuesday' and vTuesday_F = 'Y') or
					       (vday_name = 'wednesday' and vWednesday_F = 'Y') or
					       (vday_name = 'thursday' and vThursday_F = 'Y') or
					       (vday_name = 'friday' and vFriday_F = 'Y') or
					       (vday_name = 'saturday' and vSaturday_F = 'Y') then
						set vweekoff_status = '/WO';
					end if;
				end if;
				
				if vwork_time_day_off_cal_ot = 4 then
					if vholiday_count > 0 then
						select vattendance_balance + case
						                             	when present = 'P/P' then 1
						                             	when present in ('A/P', 'P/A') then 0.5
						                             	else 0
						                             end into vattendance_balance
						from emp_detail_timeattandance where att_date = date_format(from_days(i), '%Y-%m-%d') and emp_pkey = pemp_fkey limit 1;
					end if;
				elseif vwork_time_day_off_cal_ot = 2 then
					if (vholiday_count > 0 or (vholiday_count = 0 and vweekoff_status = 'WO')) then
						select vattendance_balance + case
						                             	when present = 'P/P' then 1
						                             	when present in ('A/P', 'P/A') then 0.5
						                             	else 0
						                             end into vattendance_balance
						from emp_detail_timeattandance where att_date = date_format(from_days(i), '%Y-%m-%d') and emp_pkey = pemp_fkey limit 1;
					elseif vholiday_count = 0 and vweekoff_status = '/WO' then
						select vattendance_balance + case 
						                             	when present in ('P/P', 'A/P') then 0.5
						                             	else 0
						                             end into vattendance_balance
						from emp_detail_timeattandance where att_date = date_format(from_days(i), '%Y-%m-%d') and emp_pkey = pemp_fkey limit 1;
					end if;
				end if;
			end if;
			
			select i + 1 into i;
		end while;
	else
		set vattendance_balance = 0;
	end if;
end if;

if vcount = 0 then
	select sum(cnt) into vleavetaken from
	(	select count(*) as cnt from emp_leave_transactions where leave_session=3 and  Remarks!='No need Leave'
		and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
		and  emp_fkey=pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vstart_date  and vend_date
		union all
		select count(*)*.5 as cnt from emp_leave_transactions where leave_session!=3 and Remarks!='No need Leave'
		and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
		and  emp_fkey=pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vstart_date  and vend_date
	) b;
else
	select sum(compoff) into vleavetaken from 
	(	select count(*) as compoff from attendance_register where
		(	FIELD1='COFF'  OR FIELD2='COFF'  OR FIELD3='COFF'  OR FIELD4='COFF'  OR
			FIELD5='COFF'  OR FIELD6='COFF'  OR FIELD7='COFF'  OR FIELD8='COFF'  OR 
			FIELD9='COFF'  OR FIELD10='COFF' OR FIELD11='COFF' OR FIELD12='COFF' OR 
			FIELD13='COFF' OR FIELD14='COFF' OR FIELD15='COFF' OR FIELD16='COFF' OR 
			FIELD17='COFF' OR FIELD18='COFF' OR FIELD19='COFF' OR FIELD20='COFF' OR 
			FIELD21='COFF' OR FIELD22='COFF' OR FIELD23='COFF' OR FIELD24='COFF' OR 
			FIELD25='COFF' OR FIELD26='COFF' OR FIELD27='COFF' OR FIELD28='COFF' OR 
			FIELD29='COFF' OR FIELD30='COFF' OR FIELD31='COFF' OR FIELD32='COFF'
		)
		and isdelete='N' and concat(month_year,'-01') between vstart_date and vend_date and attendance_register.emp_fkey = pemp_fkey
		union all
		select count(*) as compoff  from emp_leave_transactions where leave_session=3 and Remarks!='No need Leave'
		and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
		and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items where item_type='LEAVE' and occurance='COFF' and status =1)
		and  emp_fkey=pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) 
		and leave_date between vstart_date and vend_date
		union all
		select count(*)*.5 as compoff from emp_leave_transactions where leave_session!=3 and Remarks!='No need Leave'
		and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
		and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items where item_type='LEAVE' and occurance='COFF' and status =1)
		and  emp_fkey=pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized'))
		and leave_date between vstart_date and vend_date
	) b;
end if;

select sum(approved_days) into vencash_days from leave_encashment_master
where salary_head_item_fkey=psalary_head_item_fkey and emp_fkey=pemp_fkey
and status=1 and is_approved='Y' and approved_date between vstart_date and vend_date;

set vleavecnt = ifnull(vpolicy_allotted_balance,0) + ifnull(vcarry_forwarded_balance,0) + ifnull(vadjustments_balance,0) + ifnull(vattendance_balance,0) - ifnull(vleavetaken,0) - ifnull(vencash_days,0) - ifnull(vendprocess_adjust,0);

if vleavecnt <=0 then
	set vleavecnt =0;
end if;

return (floor((vleavecnt)*2)/2 );
end;;

DROP FUNCTION IF EXISTS `Leave_balance_upload_fn`;;
CREATE FUNCTION `Leave_balance_upload_fn` () RETURNS varchar(30) CHARACTER SET 'latin1' LANGUAGE SQL
begin
declare vfullcnt float;
declare vhalfcnt float;
declare vleavecnt float;
declare vstart_month date;
declare vend_month date;
declare vleave_for_thyear float;
declare vcarry_forwarded float;
declare vemp_pkey int;
declare vfin_count int;
declare pfinyear varchar(30);
declare pclosing_year varchar(30);
declare vleave_type float;
declare vleave_balance float;
 declare vCARRY_FORWARD_LIMIT int;
 declare vsalary_head_item_fkey int;
 declare vis_leave_encash int;
 declare vleavebalance float;
 declare vset_forward float;
 declare vempid varchar(30);
 declare valloted_leave_forthe_year float;
 declare vyearlybalance float;
 DECLARE vcount int;

DECLARE exit_loop1 BOOLEAN default FALSE;

declare emp_cur cursor for   
   select distinct empid ,leave_type,leave_balance
  from leave_balance_upload ed      
    where status=1 
 order by 1 desc;
 


DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;

open emp_cur;
att_loop: loop
    fetch emp_cur into vempid,vleave_type,vleave_balance ;

  IF exit_loop1 THEN
	LEAVE att_loop;
  END IF; 
  
  select emp_fkey into vemp_pkey  from emp_proff where emp_company_id=vempid;
   insert into test(field1,field2,field3)VALUES(vempid,vleave_balance,vemp_pkey);
 if vemp_pkey is not null   then 
  select  fin_year into pfinyear from fin_year 
  where current_date between start_month and end_month and vattr1=1 and is_current_finyear='Y' 
     and branch_code in (select branch_code from emp_details where emp_pkey=vemp_pkey); 
 
  
select ifnull(count(*),0) into vcount
  from leavepolicy where LEAVEPOLICY_GROUP_ID
          in (SELECT LEAVEPOLICY_GROUP_ID FROM emp_proff WHERE emp_fkey=vemp_pkey )
		     and salary_head_item_fkey =vleave_type and status =1 ; 
			 
  
 if vcount > 0  and pfinyear>0 then
 
 update emp_leave_balance_year set status=0 
    where emp_fkey=vemp_pkey and fin_year=pfinyear and salary_head_item_fkey =vleave_type ;
	
	select  count(*) into vcarry_forwarded from emp_leave_balance_year 
  where emp_fkey=vemp_pkey and fin_year=pfinyear and salary_head_item_fkey =vleave_type and status=1 ; 
	
 
 select alloted_leave_forthe_year,CARRY_FORWARD_LIMIT,salary_head_item_fkey,is_leave_encash 
 into valloted_leave_forthe_year,vCARRY_FORWARD_LIMIT,vsalary_head_item_fkey,vis_leave_encash
  from leavepolicy where LEAVEPOLICY_GROUP_ID
          in (SELECT LEAVEPOLICY_GROUP_ID FROM emp_proff WHERE emp_fkey=vemp_pkey )and salary_head_item_fkey =vleave_type and status =1 ;
	 
 SELECT leave_balance_inthe_year_fn(vemp_pkey, vsalary_head_item_fkey, pfinyear) into vyearlybalance;
 
 set vset_forward=vleave_balance-vyearlybalance;


 
 if vcarry_forwarded=0 then
     insert into emp_leave_balance_year(emp_fkey,salary_head_item_fkey,fin_year,carry_forwarded)
	        values(vemp_pkey,vsalary_head_item_fkey,pfinyear,vset_forward);
 else
    update  emp_leave_balance_year set carry_forwarded=vset_forward where 
      	emp_fkey=vemp_pkey and fin_year=pfinyear and salary_head_item_fkey =vleave_type  ;
			
 end if;
   update leave_balance_upload set status=0 where empid =vempid  and leave_type=vleave_type ;
 end if;
 end if; 
 end loop att_loop;
close emp_cur;
return concat (pfinyear,':-',vleave_type,'Updated');
end;;

DROP PROCEDURE IF EXISTS `leave_encash_insert_prc`;;
CREATE PROCEDURE `leave_encash_insert_prc` (IN `pbranch_code` varchar(30), IN `pemp_pkey` int, IN `pitem` int, IN `pmonth` date, IN `puser_id` varchar(30), OUT `perr_msg` varchar(200))
begin
declare vcount int;
declare vstart_date  date;
declare vend_date  date;
declare vemp_pkey  int;
declare vdays int;
declare i int;

DECLARE exit_loop BOOLEAN default FALSE;


declare vfirst_name  varchar(50);
declare cur cursor for
select emp_pkey,trim(concat(emp_details.first_name,' ',emp_details.last_name)) as emp_name from emp_details where emp_details.status = 1 and emp_pkey in 
  (select emp_fkey from emp_proff where LEAVEPOLICY_GROUP_ID in 
   (select  LEAVEPOLICY_GROUP_ID from leavepolicy where is_leave_encash ='Y' and leave_encash_limit is NOT NULL and status = 1 ))
 and emp_pkey=if(pemp_pkey in(null,''),emp_pkey,pemp_pkey) 
 and Branch_code=if(pbranch_code in(null,''),Branch_code,pbranch_code)
and status = 1;

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;

open cur;
start_loop: loop
    fetch cur into vemp_pkey,vfirst_name;
   IF exit_loop THEN        LEAVE start_loop;     END IF;

select count(*) into vcount from leave_encashment_master 
  where is_approved !='Y' and status=1 and emp_fkey= vemp_pkey;

if vcount >0 then
  delete from leave_encashment_master where  is_approved !='Y' and status=1 and emp_fkey= vemp_pkey;
end if;
	
   block1:begin
	declare vmonthlybalance      float;
	declare vyearlybalance       float;
	declare vitem           varchar(100);
	declare vLEAVEPOLICYID   int;
	declare vsalary_head_item_fkey int;
	declare valloted_leave_forthe_year float;
	declare vleave_encash_limit float;
	
	DECLARE exit_loop1 BOOLEAN default FALSE;
	
   declare encash cursor for
   select leave_balance_inthe_year_fn(vemp_pkey,salary_head_items.salary_head_item_pkey,att_start_end_fn(DATE_FORMAT(pmonth, '%Y-%m-01'), 2)) as monthlybalance,
		leave_balance_inthe_year_fn(vemp_pkey,salary_head_items.salary_head_item_pkey,leavepolicy.leave_cycle_end_date) as yearlybalance,
		salary_head_items.item,
		leavepolicy.LEAVEPOLICYID,leavepolicy.salary_head_item_fkey,
		leavepolicy.alloted_leave_forthe_year,
		leavepolicy.leave_encash_limit from leavepolicy ,salary_head_items
		 where salary_head_item_pkey = salary_head_item_fkey and leavepolicy.status = 1  
		 and leavepolicy.LEAVEPOLICY_GROUP_ID in (select LEAVEPOLICY_GROUP_ID from emp_proff where emp_fkey = vemp_pkey)
		 and is_leave_encash ='Y' and salary_head_item_pkey=if(pitem in(null,''),salary_head_item_pkey,pitem)
		 and leave_encash_limit is NOT NULL ;
   
   DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;

open encash;
start_loop1: loop
    fetch encash into vmonthlybalance,vyearlybalance,vitem,vLEAVEPOLICYID,vsalary_head_item_fkey,
	valloted_leave_forthe_year, vleave_encash_limit;
   IF exit_loop1 THEN        LEAVE start_loop1;     END IF;
   
   select leave_cycle_start_date, leave_cycle_end_date into vstart_date, vend_date
	from leavepolicy where salary_head_item_fkey = vsalary_head_item_fkey and status = 1
	and LEAVEPOLICY_GROUP_ID in (select LEAVEPOLICY_GROUP_ID from emp_proff where emp_fkey = vemp_pkey);
   
    select ifnull(sum(approved_days),0) into vdays from leave_encashment_master 
               where salary_head_item_fkey=vsalary_head_item_fkey and is_approved ='Y' 
			   and status=1 and emp_fkey= vemp_pkey and approved_date between vstart_date and vend_date;

 if vmonthlybalance>=0 then
 if vdays < vleave_encash_limit then
 if (vleave_encash_limit-vdays) >= vmonthlybalance then
 INSERT INTO leave_encashment_master 
(emp_fkey, emp_name, branch_code, salary_head_item_fkey, encash_days, available_days,requested_days,approved_days,created_by) 
VALUES (vemp_pkey, vfirst_name, pbranch_code, vsalary_head_item_fkey, vleave_encash_limit, vmonthlybalance,vmonthlybalance,vmonthlybalance,puser_id) ;  
else
INSERT INTO leave_encashment_master 
(emp_fkey, emp_name, branch_code, salary_head_item_fkey, encash_days, available_days,requested_days,approved_days,created_by) 
VALUES (vemp_pkey, vfirst_name, pbranch_code, vsalary_head_item_fkey, (vleave_encash_limit-vdays), (vleave_encash_limit-vdays),(vleave_encash_limit-vdays),(vleave_encash_limit-vdays),puser_id) ; 
end if;
 end if;
 end if;
 
   end loop start_loop1;
   close encash;
   end block1;
  
 
 
end loop start_loop;
 close cur ;

 end;;

DROP PROCEDURE IF EXISTS `leave_encash_prc`;;
CREATE PROCEDURE `leave_encash_prc` (IN `pbranch_code` varchar(30), IN `pemp_pkey` int, IN `ppleave_encashment_master_pkey` int, IN `puser_id` varchar(30), IN `perr_msg` varchar(2000))
begin

declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vDeviceId int;
declare vjoining_date	  date;
declare vemp_company_id	varchar(30);	 
declare vemp_type	varchar(30);	 
declare vdesignation	varchar(30); 
declare vemp_dept	varchar(30);
declare vemp_grade	varchar(30);
declare vemp_vertical   varchar(30);
declare vemp_branch varchar(30);	 
declare vHOLIDAY_GROUP_ID int;	 
declare vLEAVEPOLICY_GROUP_ID int;
declare vday_time_seq  int;
declare vpresant_total float;
declare vleave_total float;
declare vlop_total float;
declare vemp_anual_ctc float;
declare vemp_monthly_ctc float ;
declare vemp_structure_id int ;
declare vprorate_code int;
declare vprorate_desc varchar(50);
declare vdefined_structure_for varchar(50);
declare vsalary_head_item_fkey int;
declare vsalary_head_item_desc varchar(100);
declare vstructure_det_value float;
declare vhead_operator varchar(20);
declare vhead_type varchar(25);
declare vitem_part varchar(25);
declare vstructure_id int;
declare vemp_salary float;
declare vday_count int ;
declare vattendance_date date;
declare vmonthly_att_fromdate date;
declare vmonthly_att_todate date;
declare vworking_day int;
declare vweekoff_day int;
declare vexistcount int;
declare vmonthly_amount float;
declare vindirect_amount float;
declare vtotal_deduction float;
declare vtotal_variables float;
declare vmonth date;
declare vrate float;
declare vholiday_count  int;
declare vot_duration float;
declare vactual_presant_days int;
DECLARE exit_loop BOOLEAN default FALSE;

declare rec_count int;


declare cur cursor for
select distinct ed.emp_pkey,concat(ed.first_name,' ',ed.last_name) empname ,
ep.joining_date	,  
ep.emp_company_id	,	 
ep.emp_type	,	 
ep.designation	,	 
ep.emp_dept	,
ep.emp_grade	, 
ep.emp_vertical,	 
ep.emp_branch	,	 
ep.HOLIDAY_GROUP_ID,	 
ep.LEAVEPOLICY_GROUP_ID,	 
ep.day_time_seq ,
ep.structure_id  from emp_details ed,emp_proff ep 
 where ed.Branch_code=pBranch_code and ed.Branch_code=ep.emp_branch and ed.emp_pkey=pemp_pkey
 and ed.emp_pkey=ep.emp_fkey and status=1;

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;


open cur;
start_loop: loop
    fetch cur into vemp_pkey,vfirst_name , vjoining_date,	
vemp_company_id,
vemp_type	,	
vdesignation	,
vemp_dept	,
vemp_grade	, 
vemp_vertical,	
vemp_branch	,	
vHOLIDAY_GROUP_id ,
vLEAVEPOLICY_GROUP_ID ,
vday_time_seq ,vstructure_id;
IF exit_loop THEN
        LEAVE start_loop;
     END IF;
  
	select  approved_days into vpresant_total  from leave_encashment_master where leave_encashment_master_pkey=ppleave_encashment_master_pkey;
	set vactual_presant_days=vpresant_total;
	
 select emp_derived_anualctc ,emp_anual_ctc/12 into vemp_anual_ctc,vemp_monthly_ctc  from  emp_ctc_transaction  where emp_fkey=vemp_pkey and end_date_effective is null;
 set vleave_total=0;
 set vlop_total=0;
 
 BLOCK2:begin
DECLARE exit_loop3 BOOLEAN default FALSE;
declare structurecur cursor for
 select emp_fkey,emp_structure_id,prorate_code,prorate_desc,defined_structure_for,	 
salary_head_item_fkey,salary_head_item_desc,structure_det_value,head_operator,head_type	,item_part from emp_salary_structure 
  where emp_fkey=vemp_pkey and end_date_effective is null and lcase(salary_head_item_desc) ='leave encashment' ;
  
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop3 = TRUE;
 	
open structurecur ;
start_loop1: loop
    fetch structurecur into vemp_pkey,vemp_structure_id,vprorate_code,vprorate_desc,vdefined_structure_for,	 
vsalary_head_item_fkey,vsalary_head_item_desc,vstructure_det_value,vhead_operator,vhead_type	,vitem_part;
   
IF exit_loop3 THEN 
       LEAVE start_loop1 ;   
  END IF;
  
  if  lcase(vhead_type)!='fixed'  then
  
	  set vemp_salary=(vstructure_det_value*vpresant_total);

	
	  
	 insert into emp_encash_slip (leave_encashment_master_fkey,emp_fkey,	 
			month_year	,	 
			salary_head_item_fkey	,
			salary_head_item_desc,
			structure_det_value	,
			salary_rate	,salary_amount ,	 
			presant_total,	 
			leave_total	,
			lop_total	,
			head_operator,
			head_type,
			item_part,action) values(ppleave_encashment_master_pkey,vemp_pkey,current_date ,vsalary_head_item_fkey,vsalary_head_item_desc,vstructure_det_value,vstructure_det_value,vemp_salary, vactual_presant_days,vleave_total,vlop_total,vhead_operator,vhead_type	,vitem_part,'P');
			
	else  
	
	
	     insert into emp_encash_slip (leave_encashment_master_fkey,emp_fkey,	 
			month_year	,	 
			salary_head_item_fkey	,
			salary_head_item_desc,
			structure_det_value	,
			salary_rate	,salary_amount ,	 
			presant_total,	 
			leave_total	,
			lop_total	,
			head_operator,
			head_type,
			item_part,action) values(ppleave_encashment_master_pkey,vemp_pkey,current_date ,vsalary_head_item_fkey,vsalary_head_item_desc,
			vstructure_det_value,vstructure_det_value,vemp_salary, vactual_presant_days,vleave_total,vlop_total,vhead_operator,vhead_type	,vitem_part,'P');

	
  end if; 
 
 end loop start_loop1;
 close structurecur;
 end block2;
 
 update leave_encashment_master set encashed_amount =vemp_salary where leave_encashment_master_pkey=ppleave_encashment_master_pkey;
  end loop;
close cur;
	
end;;

DROP FUNCTION IF EXISTS `leave_end_process_fn`;;
CREATE FUNCTION `leave_end_process_fn` () RETURNS varchar(30) CHARACTER SET 'latin1' LANGUAGE SQL
MODIFIES SQL DATA
begin
declare vLEAVEPOLICY_GROUP_ID int;
declare vCARRY_FORWARD_LIMIT float;
declare vsalary_head_item_fkey int;
declare vleavebalance float;
declare vcarry_forward float;
declare vleave_policy_type char(2);
declare vleave_cycle_start_date date;
declare vleave_cycle_end_date date;
declare vnew_start_date date;
declare vnew_end_date date;
declare vcount int;
declare vexist_count int;

declare exit_loop boolean default false;

declare leave_cur cursor for
	select LEAVEPOLICY_GROUP_ID, salary_head_item_fkey, leave_policy_type, leave_cycle_start_date, leave_cycle_end_date, CARRY_FORWARD_LIMIT
	from leavepolicy where LEAVEPOLICY_GROUP_ID in (select LEAVEPOLICY_GROUP_ID from leavepolicy_group where status=1) and status = 1 order by LEAVEPOLICY_GROUP_ID;

declare continue handler for not found set exit_loop = true;

open leave_cur;
start_loop: loop
	fetch leave_cur into vLEAVEPOLICY_GROUP_ID, vsalary_head_item_fkey, vleave_policy_type, vleave_cycle_start_date, vleave_cycle_end_date, vCARRY_FORWARD_LIMIT;
	
	if exit_loop then
		leave start_loop;
	end if;
	
	if vleave_cycle_end_date = date_sub(current_date, interval 1 day) then
		if vleave_policy_type = 'D' then
			set vnew_start_date = vleave_cycle_start_date + interval 1 day;
			set vnew_end_date = vleave_cycle_end_date + interval 1 day;
		end if;
		
		if vnew_start_date is not null and vnew_end_date is not null then
			update leavepolicy set leave_cycle_start_date = vnew_start_date, leave_cycle_end_date = vnew_end_date
			where LEAVEPOLICY_GROUP_ID in (select LEAVEPOLICY_GROUP_ID from leavepolicy_group where status=1) and status = 1
			and LEAVEPOLICY_GROUP_ID = vLEAVEPOLICY_GROUP_ID and salary_head_item_fkey = vsalary_head_item_fkey and leave_policy_type = vleave_policy_type;
		end if;
	elseif vleave_cycle_end_date = date_sub(current_date, interval 5 day) then
		if vleave_policy_type = 'Y' then
			set vnew_start_date = vleave_cycle_end_date + interval 1 day;
			set vnew_end_date = vleave_cycle_end_date + interval 1 year;
		elseif vleave_policy_type = 'M' then
			select att_start_end_fn(date_add(date_format(vleave_cycle_end_date, '%Y-%m-01'), interval 1 month), 1) into vnew_start_date;
			select att_start_end_fn(date_add(date_format(vleave_cycle_end_date, '%Y-%m-01'), interval 1 month), 2) into vnew_end_date;
		elseif vleave_policy_type = 'Q' then
			set vnew_start_date = vleave_cycle_end_date + interval 1 day;
			set vnew_end_date = last_day(vleave_cycle_end_date + interval 1 quarter);
		elseif vleave_policy_type = 'H' then
			set vnew_start_date = vleave_cycle_end_date + interval 1 day;
			set vnew_end_date = last_day(vleave_cycle_end_date + interval 2 quarter);
		elseif vleave_policy_type = 'P' then
			set vnew_start_date = vleave_cycle_end_date + interval 1 day;
			set vnew_end_date = vleave_cycle_end_date + interval 1 year;
		end if;
		
		BLOCK1:begin
		declare vemp_pkey int;
		
		declare exit_loop1 boolean default false;
		
		declare emp_cur cursor for
			select distinct emp_pkey from emp_details 
			where status=1 and emp_pkey in (select emp_fkey from emp_proff where LEAVEPOLICY_GROUP_ID = vLEAVEPOLICY_GROUP_ID
			and LEAVEPOLICY_GROUP_ID in (select LEAVEPOLICY_GROUP_ID from leavepolicy_group where status = 1)) order by emp_pkey;
		
		declare continue handler for not found set exit_loop1 = true;
		
		open emp_cur;
		start_loop1: loop
			fetch emp_cur into vemp_pkey;
			
			if exit_loop1 then
				leave start_loop1;
			end if;
			
			if vnew_start_date is not null and vnew_end_date is not null then
				if vCARRY_FORWARD_LIMIT > 0 then
					select leave_balance_inthe_year_fn(vemp_pkey, vsalary_head_item_fkey, vleave_cycle_end_date) into vleavebalance;
					
					set vcarry_forward = 0;
					
					if vleavebalance <= vCARRY_FORWARD_LIMIT then
						set vcarry_forward = vleavebalance;
					elseif vleavebalance > vCARRY_FORWARD_LIMIT then
						set vcarry_forward = vCARRY_FORWARD_LIMIT;
					end if;
					
					select count(*) into vcount from emp_leave_balance_year where emp_fkey = vemp_pkey
					and salary_head_item_fkey = vsalary_head_item_fkey and leave_cycle_start_date = vleave_cycle_start_date and leave_cycle_end_date = vleave_cycle_end_date;
					
					if vcount = 0 then
						insert into emp_leave_balance_year (emp_fkey, salary_head_item_fkey, leave_policy_type, leave_cycle_start_date, leave_cycle_end_date, carry_forwarded, end_process_adjust)
						values (vemp_pkey, vsalary_head_item_fkey, vleave_policy_type, vleave_cycle_start_date, vleave_cycle_end_date, 0, 0);
					end if;
					
					update emp_leave_balance_year set end_process_adjust = vleavebalance where emp_fkey = vemp_pkey and salary_head_item_fkey = vsalary_head_item_fkey
					and leave_cycle_start_date = vleave_cycle_start_date and leave_cycle_end_date = vleave_cycle_end_date and status = 1;
					
					select count(*) into vexist_count from emp_leave_balance_year where emp_fkey = vemp_pkey and salary_head_item_fkey = vsalary_head_item_fkey
					and leave_cycle_start_date = vnew_start_date and leave_cycle_end_date = vnew_end_date;
					
					if vexist_count = 0 then
						insert into emp_leave_balance_year (emp_fkey, salary_head_item_fkey, leave_policy_type, leave_cycle_start_date, leave_cycle_end_date, carry_forwarded, end_process_adjust)
						values (vemp_pkey, vsalary_head_item_fkey, vleave_policy_type, vnew_start_date, vnew_end_date, vcarry_forward, 0);
					end if;
				end if;
			end if;
		end loop start_loop1;
		close emp_cur;
		end BLOCK1;
		
		if vnew_start_date is not null and vnew_end_date is not null then
			update leavepolicy set leave_cycle_start_date = vnew_start_date, leave_cycle_end_date = vnew_end_date
			where LEAVEPOLICY_GROUP_ID in (select LEAVEPOLICY_GROUP_ID from leavepolicy_group where status=1) and status = 1
			and LEAVEPOLICY_GROUP_ID = vLEAVEPOLICY_GROUP_ID and salary_head_item_fkey = vsalary_head_item_fkey and leave_policy_type = vleave_policy_type;
		end if;
	end if;
end loop start_loop;
close leave_cur;

return 'success';
end;;

DROP FUNCTION IF EXISTS `leave_fn`;;
CREATE FUNCTION `leave_fn` () RETURNS int(11) LANGUAGE SQL
begin
declare vleave_value varchar(20);
declare vleave_date date;
declare vleave_session int;
declare vemp_pkey int;
declare vemp_count int;
declare Pyear_month  date;
DECLARE exit_loop4 BOOLEAN default FALSE;
declare leavecur cursor for
 select elt.leave_date,elt.leave_session,l.EMP_fkey
       from emp_leave_transactions elt,leaveentries l where elt.Leavestatus in('Authorized','Approved')
   and elt.LEAVEENTRYID = l.LEAVEENTRYID and DATE_FORMAT(elt.leave_date, '%Y-%m-%d')  
 between DATE_FORMAT('2016-01-01', '%Y-%m-%d') and DATE_FORMAT('2016-01-31', '%Y-%m-%d') ;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop4 = TRUE;

insert into emp_detail_timeattandance (emp_pkey) values (1111 );
set Pyear_month ='2016-01-01';
open leavecur ;
start_loop4: loop
    fetch leavecur into vleave_date , vleave_session,vemp_pkey ;
   
IF exit_loop4 THEN 
       LEAVE start_loop4;   
  END IF;
insert into emp_detail_timeattandance (emp_pkey) values (1111 );
if vleave_session=3 then
  set vleave_value ='FDL';
   elseif vleave_session=2 then
 set vleave_value ='SHL';
   elseif vleave_session=1 then
   set vleave_value ='FHL';
  end if;
select count(*) into vemp_count from emp_detail_timeattandance where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(vleave_date ,'%Y-%m-%d') and yearmonth=Pyear_month  ;
if vemp_count =0 then
 insert into emp_detail_timeattandance (emp_pkey,att_date,leaves,yearmonth) values (vemp_pkey,DATE_FORMAT(vleave_date ,'%Y-%m-%d'),vleave_value ,Pyear_month );
else
update emp_detail_timeattandance set leaves=vleave_value where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(vleave_date ,'%Y-%m-%d') and yearmonth=Pyear_month  ;
end if;
 end loop start_loop4;
  
close leavecur ;
return 0;
end;;

DROP FUNCTION IF EXISTS `leave_rules_fn`;;
CREATE FUNCTION `leave_rules_fn` (`pemp_fkey` int, `psalary_head_item_fkey` int, `pleave_rule` varchar(50), `pfromdate` date, `pfromhalf` int, `ptodate` date, `ptohalf` int) RETURNS varchar(500) CHARACTER SET 'latin1' LANGUAGE SQL
READS SQL DATA
    DETERMINISTIC
begin
declare i int;
declare vworking_time int ;
declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
declare vholidayId int;
declare vdaytimeId int;
declare vHOLIDAYDATE  date;
DECLARE l_sql VARCHAR(4000);
DECLARE nday float;
DECLARE yearmonth varchar(30);
DECLARE vworking_days  int;
DECLARE vatt_date  date;

DECLARE vsunday  char(1);
DECLARE vmonday  char(1);
DECLARE vtuesday  char(1);
DECLARE vwednesday  char(1);
DECLARE vthursday  char(1);
DECLARE vfriday  char(1);
DECLARE vsaturday  char(1);
DECLARE vholicnt  float;
DECLARE vholicnt1  float;
DECLARE vholicnt2  float;
DECLARE vweekofffcnt  float;
DECLARE linfocnt float;
DECLARE vleave_for_thyear float;
DECLARE vleave_forthe_month float;
DECLARE vremainlve_for_thyear float;
DECLARE vremainlve_forthe_month float;
DECLARE vissandwich char(1);
declare vYdays float;
declare vNdays float;
declare vALLOW_NEGETIVE char(1);
declare vweekoffstring varchar(100);
declare vsalary_head_item_fkey int;
declare vexistcount float;
declare vfullcnt float;
declare vhalfcnt float;
declare vleavecnt float;
declare vleaveexistcnt float;
declare vemp_leave_infocnt float;
declare vfin_year  int;
declare vleavesession int;
declare vis_set varchar(10);
declare vitem_part varchar(10);
declare vitem varchar(100);
declare vleave_session int;
declare vremarks varchar(100);
declare voccurance varchar(10);
declare vauthcount int;
declare vminimum_leave float;
declare vmaximum_leave float;
declare vminimum_service float;
declare vmessage varchar(500);
declare vdays float;
declare vjoining_date date;
declare vminus_day float;
declare vmonth float;
declare vmin_day_before_apply  int;
declare vlast_date_of_apply int;
declare v_diff float;
declare vmonthly_att_todate date ;
declare vmonthly_att_fromdate date ;

  set vmessage=null;
  set vleavecnt=0;
select fin_year into vfin_year  from fin_year where lcase(Year_status)='open' and vattr1 = 0 and is_current_finyear='Y' and status=1
   and branch_code= (select branch_code from emp_details where emp_Pkey=Pemp_fkey ); 
   
   select joining_date into vjoining_date from emp_proff where emp_fkey=Pemp_fkey;
   
	 SELECT att_start_end_fn(DATE_FORMAT(pfromdate, '%Y-%m-01'), 1) into vmonthly_att_fromdate;
SELECT att_start_end_fn(DATE_FORMAT(pfromdate, '%Y-%m-01'), 2) into vmonthly_att_todate;

select IS_SANDWICH,ALLOW_NEGETIVE,alloted_leave_forthe_year,alloted_leave_forthe_month,minimum_leave,maximum_leave,minimum_service,min_day_before_apply,last_date_of_apply 
  into vissandwich ,vALLOW_NEGETIVE,vleave_for_thyear,vleave_forthe_month,vminimum_leave,vmaximum_leave,vminimum_service,vmin_day_before_apply,vlast_date_of_apply
  from leavepolicy where salary_head_item_fkey=psalary_head_item_fkey and LEAVEPOLICY_GROUP_ID
          in (SELECT LEAVEPOLICY_GROUP_ID FROM emp_proff WHERE emp_fkey=pemp_fkey ) and status=1;

select item_part,item,occurance into vitem_part,vitem ,voccurance from salary_head_items where salary_head_item_pkey=psalary_head_item_fkey;	

		 SELECT leave_balance_inthe_year_fn (PEMP_fkey , psalary_head_item_fkey , vfin_year ) into vremainlve_for_thyear;
		 if PTODATE<=current_date then
		 SELECT leave_balance_inthe_month_fn(PEMP_fkey, psalary_head_item_fkey, current_date, vfin_year) into vremainlve_forthe_month;
		 else
		 SELECT leave_balance_inthe_month_fn(PEMP_fkey, psalary_head_item_fkey, PTODATE, vfin_year) into vremainlve_forthe_month;
		 end if;
		if vALLOW_NEGETIVE='Y' then
		  set vremainlve_for_thyear=vremainlve_for_thyear;
		  else
		  if (vremainlve_forthe_month < vremainlve_for_thyear) then
		  set vremainlve_for_thyear=vremainlve_forthe_month;
		  end if;
		end if; 
		
	SELECT weekoff_days_count_fn(pemp_fkey, pfromdate, ptodate) into vweekofffcnt  ;

 select count(*) into vholicnt1 from holidays where HOLIDAY_GROUP_ID in 
  ( SELECT HOLIDAY_GROUP_ID FROM emp_proff WHERE emp_fkey=pemp_fkey)
  and DATE_FORMAT(HOLIDAYDATE,'%Y-%m-%d') between DATE_FORMAT(pfromdate,'%Y-%m-%d') and DATE_FORMAT(ptodate,'%Y-%m-%d') and status=1;
  
	 if vitem_part='Indirect' then 
          set vremainlve_for_thyear=365;
		  set vremainlve_forthe_month = 31;
		  set vweekofffcnt = 0;
		  set vholicnt1 = 0;
		  end if;
 
  if pfromdate=ptodate then 
  set vdays=1;
  else
  select TIMESTAMPDIFF(DAY, DATE_FORMAT(pfromdate,'%Y-%m-%d'), DATE_FORMAT(ptodate,'%Y-%m-%d'))+1 into vdays;
 end if;
  
  if pfromhalf=1 and ptohalf=1 then 
   set vminus_day=0.5;
   elseif  pfromhalf=2 and ptohalf=2 then 
    set vminus_day=0.5;
   else 
    set vminus_day=0;   
   end if;	
		
	  if vissandwich='Y' then
		set vleavecnt =vdays-vminus_day;
	  else
		set vleavecnt=vdays-(ifnull(vweekofffcnt,0)+ifnull(vholicnt1,0))-vminus_day;
	  end if;

	  if vminimum_service>0 then
      select TIMESTAMPDIFF(MONTH, DATE_FORMAT(vjoining_date,'%Y-%m-%d'), DATE_FORMAT(current_date,'%Y-%m-%d')) into vmonth;
      end if;   
	 
	 
	 

    
 if vleavecnt = 0 then 
         set vmessage='Can not Apply 0 days';
        else if vminimum_service>0 and vmonth<vminimum_service and vmessage is null then
          set vmessage=concat('Trying to break minimum service limit of ',vminimum_service,' months');
         else if vminimum_leave >0 and vleavecnt<vminimum_leave then
		   set vmessage=concat('Trying to break minimum leave limit of ',vminimum_leave);
          else if vmaximum_leave >0 and vleavecnt>vmaximum_leave then
		    set vmessage=concat('Trying to break maximum leave limit of ',vmaximum_leave);
		       else  if vlast_date_of_apply >0 THEN
			
																												   
					 if DATE_FORMAT(current_date,'%Y-%m-%d') > DATE_FORMAT(concat(DATE_FORMAT(vmonthly_att_todate,'%Y-%m-'),vlast_date_of_apply),'%Y-%m-%d') 
					  AND pfromdate < vmonthly_att_todate then 
					 
					 set vmessage=concat('This Leave can not Apply after ',DATE_FORMAT(concat(DATE_FORMAT(vmonthly_att_todate,'%Y-%m-'),vlast_date_of_apply),'%Y-%m-%d'));
					 end if;	  
					
	       else 
		     set vmessage='Success';
	       end if;
		   end if;
          end if;
         end if;
        end if;
		if vmin_day_before_apply >0 THEN
	  if (current_date< pfromdate) then
	 
	   set v_diff=DATEDIFF(pfromdate,current_date );
	     if vmin_day_before_apply > v_diff then
		 set vmessage=concat('You can apply a minimum of ',vmin_day_before_apply,' days before');
		 end if;
		 else
		 set vmessage=concat('You can apply a minimum of ',vmin_day_before_apply,' days before');
	   end if; 
	 end if;	
																					   
	  
  
  if vmessage is null then
  return 'Success';
  else
  return vmessage;
  end if;

 end;;

DROP PROCEDURE IF EXISTS `leave_start_end_prc`;;
CREATE PROCEDURE `leave_start_end_prc` (IN `pemp_fkey` int, IN `psalary_head_item_fkey` int, IN `pleave_date` date, OUT `pstart_date` date, OUT `pend_date` date)
begin
	declare vleave_policy_type char(2);
	declare vdynamic_period float;
	declare vleave_cycle_start_date date;
	declare vleave_cycle_end_date date;
	declare vmonthly_att_fromdate date;
	declare vmonthly_att_todate date;
	declare vmonth date;
	
	if pleave_date is null then
		set pleave_date = current_date;
	end if;
	
	select leave_policy_type, dynamic_period, leave_cycle_start_date, leave_cycle_end_date
	into vleave_policy_type, vdynamic_period, vleave_cycle_start_date, vleave_cycle_end_date
	from leavepolicy where salary_head_item_fkey = psalary_head_item_fkey and status = 1
	and LEAVEPOLICY_GROUP_ID in (select LEAVEPOLICY_GROUP_ID from emp_proff where emp_fkey = pemp_fkey);
	
	if vleave_cycle_start_date is null or vleave_cycle_end_date is null then
		select start_month, end_month into vleave_cycle_start_date, vleave_cycle_end_date
		from fin_year where ucase(Year_status) = 'OPEN' and is_current_finyear = 'Y' and vattr1 = 0
		and status = 1 and branch_code in (select branch_code from emp_details where emp_pkey=pemp_fkey);
	end if;
	
	if vleave_policy_type = 'Y' then
		if pleave_date between vleave_cycle_start_date and vleave_cycle_end_date then
			set pstart_date = vleave_cycle_start_date;
			set pend_date = vleave_cycle_end_date;
		elseif pleave_date < vleave_cycle_start_date then
			set pstart_date = vleave_cycle_start_date - interval 1 year; 
			set pend_date = vleave_cycle_start_date - interval 1 day;
		elseif pleave_date > vleave_cycle_end_date then
			set pstart_date = vleave_cycle_end_date + interval 1 day; 
			set pend_date = vleave_cycle_end_date + interval 1 year;
		end if;
	elseif vleave_policy_type = 'M' then
		select att_start_end_fn(date_format(pleave_date, '%Y-%m-01'), 1) into vmonthly_att_fromdate;
		select att_start_end_fn(date_format(pleave_date, '%Y-%m-01'), 2) into vmonthly_att_todate;
		if pleave_date between vmonthly_att_fromdate and vmonthly_att_todate then
			set pstart_date = vmonthly_att_fromdate;
			set pend_date = vmonthly_att_todate;
		elseif pleave_date < vmonthly_att_fromdate then
			set vmonth = date_sub(date_format(pleave_date,'%Y-%m-%d'), interval 1 month);
			select att_start_end_fn(date_format(vmonth, '%Y-%m-01'), 1) into pstart_date;
			select att_start_end_fn(date_format(vmonth, '%Y-%m-01'), 2) into pend_date;
		elseif pleave_date > vmonthly_att_todate then
			set vmonth = date_add(date_format(pleave_date,'%Y-%m-%d'), interval 1 month);
			select att_start_end_fn(date_format(vmonth, '%Y-%m-01'), 1) into pstart_date;
			select att_start_end_fn(date_format(vmonth, '%Y-%m-01'), 2) into pend_date;
		end if;
	elseif vleave_policy_type = 'Q' then
		set pstart_date = date_format(makedate(year(pleave_date), 1) + interval quarter(pleave_date) quarter - interval 1 quarter,'%Y-%m-%d');
		set pend_date = last_day(makedate(year(pleave_date), 1) + interval quarter(pleave_date) quarter - interval 1 month);
	elseif vleave_policy_type = 'H' then
		set pstart_date = makedate(year(pleave_date), 1) + interval if(month(pleave_date) <= 6, 0, 6) month;
		set pend_date = date_add(makedate(year(pleave_date), 1) + interval if(month(pleave_date) <= 6, 0, 6) month, interval 6 month) - interval 1 day;
	elseif vleave_policy_type = 'P' then
		if pleave_date between vleave_cycle_start_date and vleave_cycle_end_date then
			set pstart_date = vleave_cycle_start_date;
			set pend_date = vleave_cycle_end_date;
		elseif pleave_date < vleave_cycle_start_date then
			set pstart_date = vleave_cycle_start_date - interval 1 year; 
			set pend_date = vleave_cycle_start_date - interval 1 day;
		elseif pleave_date > vleave_cycle_end_date then
			set pstart_date = vleave_cycle_end_date + interval 1 day; 
			set pend_date = vleave_cycle_end_date + interval 1 year;
		end if;
	elseif vleave_policy_type = 'D' then
		set pstart_date = date_add(pleave_date,interval - vdynamic_period day);
		set pend_date = pleave_date;
	end if;
end;;

DROP FUNCTION IF EXISTS `leave_taken_fn`;;
CREATE FUNCTION `leave_taken_fn` (`pemp_fkey` int, `psalary_head_item_fkey` int, `pleave_date` date) RETURNS float LANGUAGE SQL
READS SQL DATA
    DETERMINISTIC
begin

declare vfullcnt float;
declare vhalfcnt float;
declare vleavecnt float;
declare vstart_month date;
declare vend_month date;
declare vleave_for_thyear float;
declare vcarry_forwarded float;
declare vcount int;
declare vcompoff float;
declare veligibility float;

select count(*)  into vcount from salary_head_items where lcase(item_type)='leave' and lcase(occurance)='coff' 
and salary_head_item_pkey=psalary_head_item_fkey  and value='Y';

call leave_start_end_prc(pemp_fkey, psalary_head_item_fkey, pleave_date, vstart_month, vend_month);

if vstart_month is null or vend_month is null then
	select start_month, end_month into vstart_month, vend_month
	from fin_year where ucase(Year_status) = 'OPEN' and is_current_finyear = 'Y' and vattr1 = 0
	and status = 1 and branch_code in (select branch_code from emp_details where emp_pkey=pemp_fkey);
end if;

if vcount=0 then 
select  carry_forwarded into vcarry_forwarded from emp_leave_balance_year where emp_fkey=PEMP_fkey and 
   salary_head_item_fkey=psalary_head_item_fkey and leave_cycle_start_date = vstart_month and leave_cycle_end_date = vend_month and status = 1;
   

select alloted_leave_forthe_year 
  into vleave_for_thyear
  from leavepolicy where salary_head_item_fkey=psalary_head_item_fkey and LEAVEPOLICY_GROUP_ID
          in (SELECT LEAVEPOLICY_GROUP_ID FROM emp_proff WHERE emp_fkey=PEMP_fkey ) and status=1 ;
		  
set vleave_for_thyear=vleave_for_thyear+ifnull(vcarry_forwarded,0);		  

                
 select count(*) into vfullcnt from emp_leave_transactions where leave_session=3 and  Remarks!='No need Leave'
                          and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vstart_month  and vend_month ;

 select count(*) into vhalfcnt from emp_leave_transactions where leave_session!=3 and Remarks!='No need Leave'
                         and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where salary_head_item_fkey=psalary_head_item_fkey
                          and  emp_fkey=Pemp_fkey and leavestatus in ('Approved','Authorized','Applied','CancellationOfApproved','CancellationOfAuthorized')) and leave_date between vstart_month  and vend_month ;
  
 
 set vleavecnt =vfullcnt + (vhalfcnt *.5) ;
 
  
 elseif vcount<>0 then 
  select sum(compoff) into vcompoff from 
   (select count(*) as compoff 
                        from attendance_register 
                         where (FIELD1='COFF' OR FIELD2='COFF' OR FIELD3='COFF' OR FIELD4='COFF' 
                         OR FIELD5='COFF' OR FIELD6='COFF' OR FIELD7='COFF' OR FIELD8='COFF' OR 
                         FIELD9='COFF' OR FIELD10='COFF' OR FIELD11='COFF' OR FIELD12='COFF' OR 
                         FIELD13='COFF' OR FIELD14='COFF' OR FIELD15='COFF' OR FIELD16='COFF' OR 
                         FIELD17='COFF' OR FIELD18='COFF' OR FIELD19='COFF' OR FIELD20='COFF' OR 
                         FIELD21='COFF' OR FIELD22='COFF' OR FIELD23='COFF' OR FIELD24='COFF' OR 
                         FIELD25='COFF' OR FIELD26='COFF' OR FIELD27='COFF' OR FIELD28='COFF' OR 
                         FIELD29='COFF' OR FIELD30='COFF' OR FIELD31='COFF' OR FIELD32='COFF')
                        and isdelete='N' and concat(month_year,'-01') between vstart_month and vend_month and attendance_register.emp_fkey = Pemp_fkey
						union all
						select sum(leave_days) as compoff from leaveentries where salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items 
                                     where item_type='LEAVE' and occurance='COFF' and status =1) and lcase(LEAVESTATUS)in ('Authorized','Approved')
                                       and TODATE between vstart_month and vend_month and emp_fkey  =Pemp_fkey) b; 
												
						select sum(v1) into veligibility from (
						select count(*) v1 from
                        emp_detail_timeattandance where (weekoff is not null or holiday is not null)and weekoff <>'/WO' and present='P/P'
                        and yearmonth between vstart_month and vend_month and emp_pkey =Pemp_fkey
                        union all
                        select count(*)*.5 v1 from
                        emp_detail_timeattandance  where (weekoff is not null or holiday is not null) 
						and weekoff <>'/WO' and present in('P/A','A/P')
                        and yearmonth between vstart_month and vend_month and emp_pkey =Pemp_fkey
                        ) a;
			set vleavecnt = vcompoff  ;
                        if vleavecnt <=0 then
                      	set vleavecnt =0;
                        end if;		
	end if;					

return (vleavecnt) ;
end;;

DROP PROCEDURE IF EXISTS `leave_transaction_prc`;;
CREATE PROCEDURE `leave_transaction_prc` (IN `PLEAVEENTRYID` int(11), IN `PEMP_fkey` int(11), IN `PFROMDATE` date, IN `PFROMHALF` int, IN `PTODATE` date, IN `PTOHALF` int, IN `Pleave_days` float, IN `Pleave_status` varchar(50), OUT `Perror_message` varchar(200))
begin
declare i int;
declare vworking_time int ;
declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
declare vholidayId int;
declare vdaytimeId int;
declare vHOLIDAYDATE  date;
DECLARE l_sql VARCHAR(4000);
DECLARE nday float;
DECLARE yearmonth varchar(30);
DECLARE vworking_days  int;
DECLARE vatt_date  date;
DECLARE vSunday  char(1);
DECLARE vMonday  char(1);
DECLARE vTuesday  char(1);
DECLARE vWednesday  char(1);
DECLARE vThursday  char(1);
DECLARE vFriday  char(1);
DECLARE vSaturday  char(1);
declare vSunday_F char(1);
declare vMonday_F char(1);
declare vTuesday_F char(1);
declare vWednesday_F char(1);
declare vThursday_F char(1);
declare vFriday_F char(1);
declare vSaturday_F char(1);
DECLARE vholicnt  float;
DECLARE vholicnt1  float;
DECLARE vholicnt2  float;
DECLARE vweekofffcnt  float;
DECLARE linfocnt float;
DECLARE vleave_for_thyear float;
DECLARE vleave_forthe_month float;
DECLARE vremainlve_for_thyear float;
DECLARE vissandwich char(1);
declare vYdays float;
declare vNdays float;
declare vALLOW_NEGETIVE char(1);
declare vweekoffstring varchar(100);
declare vsalary_head_item_fkey int;
declare vexistcount float;
declare vfullcnt float;
declare vhalfcnt float;
declare vleavecnt float;
declare vleaveexistcnt float;
declare vemp_leave_infocnt float;
declare vleavesession int;
declare vis_set varchar(10);
declare vitem_part varchar(10);
declare vitem varchar(100);
declare vleave_session int;
declare vremarks varchar(100);
declare voccurance varchar(10);
declare vauthcount int;
declare vcount int;
declare vday_name varchar(20);
declare vweek int;
declare vex_count int;

select salary_head_item_fkey into vsalary_head_item_fkey from leaveentries where LEAVEENTRYID =PLEAVEENTRYID;

select IS_SANDWICH,ALLOW_NEGETIVE,alloted_leave_forthe_year,alloted_leave_forthe_month 
into vissandwich ,vALLOW_NEGETIVE,vleave_for_thyear,vleave_forthe_month
from leavepolicy where salary_head_item_fkey=vsalary_head_item_fkey and LEAVEPOLICY_GROUP_ID
in (SELECT LEAVEPOLICY_GROUP_ID FROM emp_proff WHERE emp_fkey=PEMP_fkey ) and status=1;

select item_part,item,occurance into vitem_part,vitem ,voccurance from salary_head_items where salary_head_item_pkey=vsalary_head_item_fkey;	  

if vitem_part='Indirect' then
	if PFROMHALF=1 and PTOHALF=1 and PFROMDATE=PTODATE then
		set vleave_session=1;
		
		insert into emp_leave_transactions(LEAVEENTRYID,leave_date,leave_session,Leavestatus,Remarks)
		values(PLEAVEENTRYID,PFROMDATE,vleave_session,'Applied',concat('First Half On',' ',voccurance));
	elseif PFROMHALF=2 and PTOHALF=2 and PFROMDATE=PTODATE then
		set vleave_session=2;
		
		insert into emp_leave_transactions(LEAVEENTRYID,leave_date,leave_session,Leavestatus,Remarks)
		values(PLEAVEENTRYID,PFROMDATE,vleave_session,'Applied',concat('Second Half On',' ',voccurance));
	elseif PFROMHALF=1 and PTOHALF=2 and PFROMDATE=PTODATE then
		set vleave_session=3;
		
		insert into emp_leave_transactions(LEAVEENTRYID,leave_date,leave_session,Leavestatus,Remarks)
		values(PLEAVEENTRYID,PFROMDATE,vleave_session,'Applied',concat('Full day On',' ',voccurance));
	elseif PFROMHALF=1 and PTOHALF=2 and PFROMDATE<>PTODATE then
		set vleave_session=3;		
		
		select to_days(DATE_FORMAT(PFROMDATE,'%Y-%m-%d')) into i;
		
		WHILE i <= to_days(DATE_FORMAT(PTODATE,'%Y-%m-%d')) DO  
			set vleave_session=3;
			
			insert into emp_leave_transactions(LEAVEENTRYID,leave_date,leave_session,Leavestatus,Remarks)
			values(PLEAVEENTRYID,FROM_DAYS(i),vleave_session,'Applied',concat('Full day On',' ',voccurance));
			
			select i + 1 into i;
		end while;
	elseif PFROMHALF=2 and PTOHALF=2 and PFROMDATE<>PTODATE then
		select to_days(DATE_FORMAT(PFROMDATE,'%Y-%m-%d'))into i;
		
		WHILE i <= to_days(DATE_FORMAT(PTODATE,'%Y-%m-%d')) DO  
			if FROM_DAYS(i)=PFROMDATE then
				set vleave_session=2;
				set vremarks=concat('Second Half  On',' ',voccurance);
			elseif FROM_DAYS(i)=PTODATE then
				set vleave_session=3;	
				set vremarks=concat('Full day On',' ',voccurance);		
			else
