			UPDATE `scheduled_break_off` SET `coff_status` = 'N',`leave_entry_id` = 0 where leave_entry_id=PLEAVEENTRYID and emp_fkey=PEMP_fkey and `type` = 'W';
		end if;
	elseif Pleave_status='Cancelled' then
		update emp_leave_transactions set Leavestatus='Cancelled' where LEAVEENTRYID=PLEAVEENTRYID and Remarks!='No need Leave';
		
		update leaveentries set LEAVESTATUS='Cancelled' where LEAVEENTRYID=PLEAVEENTRYID;
		
		select count(*)  into vcount from salary_head_items where lcase(item_type)='leave' 
		and lcase(occurance)='coff' and salary_head_item_pkey=vsalary_head_item_fkey and value='Y';
		
		if vcount>0 THEN
			UPDATE `scheduled_break_off` SET `coff_status` = 'N',`leave_entry_id` = 0 where leave_entry_id=PLEAVEENTRYID and emp_fkey=PEMP_fkey and `type` = 'W' ;
		end if;
	elseif Pleave_status='CancellationOfAuthorized' then
		update emp_leave_transactions set Leavestatus='CancellationOfAuthorized' where LEAVEENTRYID=PLEAVEENTRYID and Remarks!='No need Leave';
		
		update leaveentries set LEAVESTATUS='CancellationOfAuthorized' where LEAVEENTRYID=PLEAVEENTRYID;
		
		select count(*)  into vcount from salary_head_items where lcase(item_type)='leave' 
		and lcase(occurance)='coff' and salary_head_item_pkey=vsalary_head_item_fkey and value='Y';
		
		if vcount>0 THEN
			UPDATE `scheduled_break_off` SET `coff_status` = 'N',`leave_entry_id` = 0 where leave_entry_id=PLEAVEENTRYID and emp_fkey=PEMP_fkey and `type` = 'W';
		end if;
	elseif Pleave_status='CancellationOfApproved' then
		update emp_leave_transactions set Leavestatus='CancellationOfApproved' where LEAVEENTRYID=PLEAVEENTRYID and Remarks!='No need Leave';
		
		update leaveentries set LEAVESTATUS='CancellationOfApproved' where LEAVEENTRYID=PLEAVEENTRYID;
		
		select count(*)  into vcount from salary_head_items where lcase(item_type)='leave' 
		and lcase(occurance)='coff' and salary_head_item_pkey=vsalary_head_item_fkey and value='Y';
		
		if vcount>0 THEN
			UPDATE `scheduled_break_off` SET `coff_status` = 'N',`leave_entry_id` = 0 where leave_entry_id=PLEAVEENTRYID and emp_fkey=PEMP_fkey and `type` = 'W' ;
		end if;
	elseif Pleave_status='Cancellation Approved' then
		update emp_leave_transactions set Leavestatus='Cancellation Approved' where LEAVEENTRYID=PLEAVEENTRYID and Remarks!='No need Leave';
		
		update leaveentries set LEAVESTATUS='Cancellation Approved' where LEAVEENTRYID=PLEAVEENTRYID;
		
		select count(*)  into vcount from salary_head_items where lcase(item_type)='leave'
		and lcase(occurance)='coff' and salary_head_item_pkey=vsalary_head_item_fkey and value='Y';
		
		if vcount>0 THEN
			UPDATE `scheduled_break_off` SET `coff_status` = 'N',`leave_entry_id` = 0 where leave_entry_id=PLEAVEENTRYID and emp_fkey=PEMP_fkey and `type` = 'W';
		end if;
	elseif Pleave_status='Cancellation Authorized' then
		update emp_leave_transactions set Leavestatus='Cancellation Authorized' where LEAVEENTRYID=PLEAVEENTRYID and Remarks!='No need Leave';
		
		update leaveentries set LEAVESTATUS='Cancellation Authorized' where LEAVEENTRYID=PLEAVEENTRYID;
		
		select count(*)  into vcount from salary_head_items where lcase(item_type)='leave'
		and lcase(occurance)='coff' and salary_head_item_pkey=vsalary_head_item_fkey and value='Y';
		
		if vcount>0 THEN
			UPDATE `scheduled_break_off` SET `coff_status` = 'N',`leave_entry_id` = 0 where leave_entry_id=PLEAVEENTRYID and emp_fkey=PEMP_fkey and `type` = 'W';
		end if;
	end if;
end if;
end;;

DROP PROCEDURE IF EXISTS `Linkemp_deviceanddatabase`;;
CREATE PROCEDURE `Linkemp_deviceanddatabase` (IN `Pcompany_code` varchar(30), IN `PBranch_code` varchar(30), IN `Pemp_device_startid` int(11), OUT `Perr_msg` varchar(500))
begin

declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
declare vDeviceId int;
DECLARE exit_loop BOOLEAN default FALSE;

declare rec_count int;
declare vdevice_count int ;
declare vemp_co_id int;
declare vemp_co_id1 int;
declare vsubdomain varchar(30);
declare vemail varchar(100);
declare vattr7 varchar(30);

declare cur cursor for
select distinct emp_pkey,concat(first_name,' ',ifnull(last_name,'')),email from emp_details where company_code= pcompany_code and  ( emp_id is NULL OR trim(emp_id) in(null,'') );
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;

select count(*) into vdevice_count from mypayrol_control_db.devices where company_code= pcompany_code ;

select max(emp_id) into vemp_device_startid
    from mypayrol_control_db.emp_device_comp_branch where company_code= pcompany_code ;

if vdevice_count=0 then
set vDeviceId=1000;

select max(emp_id) into vemp_device_startid
    from mypayrol_control_db.emp_device_comp_branch where company_code= pcompany_code ;

   if vemp_device_startid is null then 
    set vemp_device_startid = concat(vDeviceId,11);
  else   
   set vemp_device_startid = vemp_device_startid+1;
   end if; 
 
else
select DeviceId into vDeviceId  from mypayrol_control_db.devices where company_code= pcompany_code limit 1;
	   

select max(emp_id) into vemp_device_startid
    from mypayrol_control_db.emp_device_comp_branch where company_code= pcompany_code ;
	


  if vemp_device_startid is null then 
    set vemp_device_startid = concat(vDeviceId,11);
  else

   set vemp_device_startid = vemp_device_startid+1;
 
   end if; 

end if;
 
open cur;
start_loop: loop
    fetch cur into vemp_pkey,vfirst_name,vemail;
IF exit_loop THEN
        LEAVE start_loop;
     END IF;
	SELECT subdomain,attr7 into vsubdomain, vattr7 FROM mypayrol_control_db.central_control WHERE Company_code=pcompany_code and subdomain is not null; 
	
if (vsubdomain in('eastern','mbcet','rubak','autoid') or vattr7='enter_id') then
 	CALL estern_username_update(vemp_pkey);
else	
    
  select count(*) into rec_count from mypayrol_control_db.emp_device_comp_branch where Company_code=pcompany_code and 
      emp_fkey=vemp_pkey;
  

if rec_count=0 then
   insert into mypayrol_control_db.emp_device_comp_branch(deviceid,emp_device_id,emp_name,Company_code,branch_code,emp_fkey,email,emp_id,emp_username ) 
         values (vDeviceId,vemp_device_startid,vfirst_name,pcompany_code,pBranch_code,vemp_pkey,vemail,vemp_device_startid,concat(pcompany_code,vemp_device_startid));
		 
   
   update emp_details set emp_id=vemp_device_startid where emp_pkey=vemp_pkey;
   update  user_credentials set user_id=concat(pcompany_code,vemp_device_startid) where emp_fkey=vemp_pkey ;

 select count(*) into vemp_co_id from emp_proff where emp_fkey=vemp_pkey and trim(emp_company_id) is null ;
  if vemp_co_id >0 then
 update emp_proff set emp_company_id =concat(pcompany_code,vemp_device_startid) where emp_fkey=vemp_pkey ; 
 end if; 
 
 select length(trim(emp_company_id)) into vemp_co_id1 from emp_proff where emp_fkey=vemp_pkey ;

  if ( vemp_co_id1 is null OR vemp_co_id1 in(null,0,'')) then
  
 update emp_proff set emp_company_id =concat(pcompany_code,vemp_device_startid) where emp_fkey=vemp_pkey ; 
 
 end if; 

end if;

set vemp_device_startid=vemp_device_startid+1;
end if;
  end loop;
close cur;




end;;

DROP FUNCTION IF EXISTS `mark_site_attendance_fn`;;
CREATE FUNCTION `mark_site_attendance_fn` (`psite_fkey` int, `puser_id` int, `pshift_fkey` int, `pdesig_fkey` int, `pemp_fkey` int, `pin_time` datetime, `pout_time` datetime, `patt_date` date) RETURNS varchar(500) CHARACTER SET 'latin1' LANGUAGE SQL
begin

declare vincount int;
declare von_dutty1 varchar(30);
declare voff_dutty1 varchar(30);
declare vout_existin int;
declare vinout_existouttime int;
declare vinoutcount int;
declare vmaxouttime datetime;
declare vmaxintime datetime;
declare vmessage varchar(200);
declare voutnull int;
declare vsite_id varchar(50);
declare vsite_fkey int;
declare vatt_date date;
declare vvalid_date_cnt int;
declare vexistcount int;


 select count(*) into vvalid_date_cnt from site_transactions where patt_date between start_date_effective and ifnull(end_date_effective,patt_date) 
                       and site_fkey= psite_fkey and day_time_seq_fkey=pshift_fkey and 	designation_id=pdesig_fkey and status=1;
 if vvalid_date_cnt >0 then
select  on_dutty1	,off_dutty1 into von_dutty1	,voff_dutty1   from  working_day_time_procedures where day_time_seq=pshift_fkey;


 select count(*) into voutnull  from site_attendance where att_date=patt_date and emp_fkey=pemp_fkey  
     and in_time is not null and ifnull(out_time,'X')='X' and active=1 ;
 
   if date_format(concat(patt_date,' ',von_dutty1),'%T') >= date_format(concat(patt_date,' ',voff_dutty1),'%T') then
     set vatt_date=DATE_ADD(patt_date, INTERVAL 1 DAY);
   else
     set vatt_date=patt_date;
	end if;
	select count(*) into vexistcount  from site_attendance where att_date between DATE_ADD(patt_date, INTERVAL -1 day) and DATE_ADD(patt_date, INTERVAL 1 day) and emp_fkey=pemp_fkey 
   
    and DATE_ADD(pin_time, INTERVAL 1 Second) between in_time and out_time and active=1; 
		
	
	
	
 if  abs(TIMESTAMPDIFF (MINUTE,pin_time ,concat(vatt_date,' ',voff_dutty1)))<60 then
     set vmessage='Minimum working time';
	 
  elseif vexistcount>0 then
  set vmessage='This Time Marked in another Shift or Site';
  
 else	 
	
	
 if voutnull=0 then
 
 if 
  
   pin_time between concat(patt_date,' ',von_dutty1) and concat(vatt_date,' ',voff_dutty1)
   then
  
 
    
	 
	 select count(*) into vinoutcount  from site_attendance where att_date=patt_date and emp_fkey=pemp_fkey  
    and in_time>=concat(patt_date,' ',von_dutty1)
		 and out_time<=concat(vatt_date,' ',voff_dutty1) and active=1;
   
	
	  if vinoutcount >0 then
	 
		
		 
		 
		 select max(out_time) ,site_fkey  into vmaxouttime,vsite_fkey  from site_attendance where att_date=patt_date and emp_fkey=pemp_fkey  
		 and in_time>=concat(patt_date,' ',von_dutty1)
		 and out_time<=concat(vatt_date,' ',voff_dutty1)
		 and active=1 ;
			
			
			  if vmaxouttime < DATE_ADD(pin_time, INTERVAL 1 Second) then
			 
			  set vmessage='insert';
			  else 
			   select  site_id into vsite_id from site where site_pkey=vsite_fkey;
			  set vmessage=concat('Already Out Marked at ',vmaxouttime,' in ',vsite_id);
			 end if;
		   else
		   
		   set vmessage='insert';   
		   
		   end if;
	
   else
    set vmessage='Invalid Intime';
  end if;
  else	 
 
     select  site_id into vsite_id from site where site_pkey in(
      select site_fkey  from site_attendance where att_date=patt_date and emp_fkey=pemp_fkey
     and in_time is not null and ifnull(out_time,'X')='X'  and active=1); 
	
     set vmessage=concat('Please enter out from -',vsite_id);
	end if; 
  end if; 
 


if vmessage is null then
set vmessage='Invalid Entry' ;
else 
set vmessage=vmessage;
end if;
else
select concat( 'Please choose Date between ',start_date_effective,' and ',end_date_effective)  into vmessage from site_transactions where 
                        site_fkey= psite_fkey and day_time_seq_fkey=pshift_fkey and 	designation_id=pdesig_fkey and status=1;

end if;
return vmessage;



end;;

DROP FUNCTION IF EXISTS `mark_site_attendance_out_fn`;;
CREATE FUNCTION `mark_site_attendance_out_fn` (`psite_fkey` int, `puser_id` int, `pshift_fkey` int, `pdesig_fkey` int, `pemp_fkey` int, `pin_time` datetime, `pout_time` datetime, `patt_date` date) RETURNS varchar(500) CHARACTER SET 'latin1' LANGUAGE SQL
begin

declare vincount int;
declare von_dutty1 varchar(30);
declare voff_dutty1 varchar(30);
declare vout_existin int;
declare vinout_existouttime int;
declare vinoutcount int;
declare vmaxouttime datetime;
declare vmaxintime datetime;
declare vmessage varchar(50);
declare voutnull int;
declare vatt_date date;
declare vexistcount int;
declare visnextday int;


select  on_dutty1	,off_dutty1,isnextday into von_dutty1	,voff_dutty1,visnextday   from  working_day_time_procedures where day_time_seq=pshift_fkey;
if date_format(concat(patt_date,' ',von_dutty1),'%T') > date_format(concat(patt_date,' ',voff_dutty1),'%T') then
     set vatt_date=DATE_ADD(patt_date, INTERVAL 1 DAY);	 
else
     set vatt_date=patt_date;
end if;

if visnextday=1 then
 set vatt_date=DATE_ADD(patt_date, INTERVAL 1 DAY);	
 else
     set vatt_date=patt_date;
end if; 



if 
    pout_time between concat(patt_date,' ',von_dutty1) and concat(vatt_date,' ',voff_dutty1)
then
    select max(in_time) into vmaxintime  from site_attendance where att_date=patt_date and emp_fkey=pemp_fkey  and active=1 
		 and in_time >=concat(patt_date,' ',von_dutty1);
	
	
	
else 
	set vmessage='Invalid Out Time';
end if;
select count(*) into vexistcount  from site_attendance where att_date between DATE_ADD(patt_date, INTERVAL -1 day) and DATE_ADD(patt_date, INTERVAL 1 day) and emp_fkey=pemp_fkey 
   
and DATE_ADD(pout_time, INTERVAL -1 Second) between in_time and out_time and active=1; 

   if (vmaxintime > pout_time) or (vexistcount=0) then
      set vmessage='update';
	   else 
			if vexistcount>0  then
            set vmessage='This Time Marked in another Shift';
             else			
           set vmessage='Invalid Out Time';
		   end if;
	  end if;
 



if vmessage is null then
set vmessage='Invalid Entry' ;
else 
set vmessage=vmessage;
end if;
return vmessage;
end;;

DROP FUNCTION IF EXISTS `master_auidt_fn`;;
CREATE FUNCTION `master_auidt_fn` (`pcompany_code` varchar(20), `pbranch_code` varchar(20), `pmodule` varchar(20), `pusage_type` varchar(20)) RETURNS int(11) LANGUAGE SQL
begin
declare vfullcnt float;
declare vhalfcnt float;
declare vleavecnt float;
declare vstart_month date;
declare vend_month date;
declare vleave_for_thyear float;
declare vcarry_forwarded float;
declare vemp_pkey int;
declare vfin_count int;
declare pfinyear varchar(30);
declare vbusiness_name varchar(200);
declare vcompany_code varchar(20);
declare vbranch_code varchar(20);
declare	vbranch_name varchar(200);
DECLARE vdate VARCHAR(20);
DECLARE exit_loop1 BOOLEAN default FALSE;

declare branch_cur cursor for   
   select company_code,branch_code,	branch_name  
  from branches br    
    where Branch_code=if(pBranch_code in(null,''),Branch_code,pBranch_code) and status=1
 order by 1;
 


DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;

select business_name into vbusiness_name from comp_contact_info ;
if pusage_type='DAILY' THEN
  set vdate=date_format(current_date ,'%Y-%m-%d');
 
ELSE
set vdate= date_format(current_date ,'%Y-%m-01');

end if; 
open branch_cur;
att_loop: loop
    fetch branch_cur into vcompany_code,vbranch_code,vbranch_name;
	
	

  IF exit_loop1 THEN
	LEAVE att_loop;
  END IF;
  if (pmodule is null or pmodule='EMPLOYEE') then
				  
			BLOCK1:begin
				 declare vstatus int;
				 declare vmonthyear varchar(20);
				 declare vcount int;
				 declare vempcount int;
				 
				 DECLARE exit_loop4 BOOLEAN default FALSE;
				 
				 declare emp_cur cursor for
				select branch_code,date_format(creation_date,'%Y-%m')monthyear ,count(*) vcount from emp_details 
				where creation_date>=vdate and Branch_code=vbranch_code and status=1 
                group by branch_code,date_format(creation_date,'%y-%m');
				  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop4 = TRUE;
				  
                 select count(*) into vempcount from emp_details where status=1	and Branch_code=vbranch_code;
				 if vempcount>0 THEN
				 INSERT INTO mypayrol_control_db.master_auidt ( company_code,`branch_name`, `module_name`) VALUES(vcompany_code,'Total ','Employees Active');	
				  
           INSERT INTO mypayrol_control_db.master_auidt ( `company_code`, `company_name`, `branch_code`, `branch_name`, `module_name`, `process_Name`, `process_type`, `process_month`, `process_count`, `remarks`) VALUES
                  (vcompany_code,	vbusiness_name,	vbranch_code,	vbranch_name,	'EMPLOYEE',	'Total',	'Total Employees',	null,	vempcount,	'Total Employees Active');				 
				ELSE
				INSERT INTO mypayrol_control_db.master_auidt ( company_code,`branch_name`, `module_name`) VALUES(vcompany_code,'No Active Employees ','Any Support Need Then Please email to crm@greatleap.tech');	
				end if;
				
           select count(*) into vcount from emp_details where creation_date>=vdate	 and status=1;
            
              if  vcount!=0 THEN 
      			 INSERT INTO mypayrol_control_db.master_auidt (company_code, `branch_name`, `module_name`) VALUES(vcompany_code,vbranch_name,'Added Active Employees ');	  
				  open emp_cur ;
					start_loop1: loop
					fetch emp_cur  into vbranch_code,vmonthyear,vcount ;
				  
				IF exit_loop4 THEN 
					   LEAVE start_loop1 ;   
				  END IF;
				 
				 INSERT INTO mypayrol_control_db.master_auidt ( `company_code`, `company_name`, `branch_code`, `branch_name`, `module_name`, `process_Name`, `process_type`, `process_month`, `process_count`, `remarks`) VALUES
                  (vcompany_code,	vbusiness_name,	vbranch_code,	vbranch_name,	'EMPLOYEE',	'CREATED',	pusage_type,	vdate,	vcount,	'Employee Created');
				 
				 
				end loop start_loop1;
				 
				 close emp_cur;
		     end if;		 
				 end BLOCK1;
  end if;
  
 
  
 end loop att_loop;
close branch_cur;
	  
 if (pmodule is null or pmodule='ACTIVITY') then
  
     BLOCK2:begin
				 declare vstatus int;
				 declare vmonthyear varchar(20);
				 declare vcount int;
				 declare vactivity varchar(200);
				 declare vuser_name varchar(50);
				 declare vdateandtime varchar(20);
				 DECLARE exit_loop4 BOOLEAN default FALSE;
				 
				 declare activity_cur cursor for
				 select  report_type activity ,user_name ,creation_date dateandtime  
                     from report_audit where creation_date >=vdate;
              	
			
				  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop4 = TRUE;
				  select  count(*) into vcount from report_audit where creation_date >=vdate;
				 if vcount >0 then 
				  INSERT INTO mypayrol_control_db.master_auidt ( company_code,`branch_name`, `module_name`) VALUES(vcompany_code,pusage_type,'Activity');
					  
						  open activity_cur ;
					start_loop2: loop
					fetch activity_cur  into vactivity,vuser_name,vdateandtime ;
				   
				IF exit_loop4 THEN 
					   LEAVE start_loop2 ;   
				  END IF;
				 
				 INSERT INTO mypayrol_control_db.master_auidt ( `company_code`, `company_name`, `branch_code`, `branch_name`, `module_name`, `process_Name`, `process_type`, `process_month`, `process_count`, `remarks`) VALUES
                  (vcompany_code,	vbusiness_name,	vbranch_code,	vbranch_name,	'ACTIVITY',	'CREATED',	pusage_type,	vdateandtime,	vuser_name,	vactivity);
				 
				 
				end loop start_loop2;				 
				 close activity_cur;
		   ELSE
		 INSERT INTO mypayrol_control_db.master_auidt ( company_code,`branch_name`, `module_name`) VALUES(vcompany_code,'No Activities found','Any Support Need Then Please email Us to crm@greatleap.tech');
		  end if; 
				 end BLOCK2;
  
  
  end if;
   BLOCK3:begin
        declare vdurn_great_1000 int;
		declare vdurn_less_0  int;
		
  if (pmodule is null or pmodule='ATTENDANCE') then
  set vdate= date_format(current_date ,'%Y-%m-01');
  
      select count(*) into vdurn_great_1000 from emp_detail_timeattandance where duration >1000 and yearmonth=vdate;

      select count(*) into vdurn_less_0 from emp_detail_timeattandance where duration < 0 and yearmonth=vdate;
	  
	   if vdurn_great_1000 >0 then 
				  INSERT INTO mypayrol_control_db.master_auidt ( company_code,company_name,`module_name`, `remarks`,process_type,process_month) 
				  VALUES(vcompany_code,vbusiness_name,'ATTENDANCE',concat('Duration Greater Than 1000',vdurn_great_1000,' times for the month of ',vdate,' found. SO Please Check it and Clear..'),pusage_type,vdate);
		end if;	
    if vdurn_less_0 >0 then 
				  INSERT INTO mypayrol_control_db.master_auidt ( company_code,company_name,`module_name`, `remarks`,process_type,process_month) 
				  VALUES(vcompany_code,vbusiness_name,'ATTENDANCE',concat('Duration Less Than 0',vdurn_less_0,' times foir the month of ',vdate,' found . So Please Check it and Clear..'),pusage_type,vdate);
	end if;			
   end if;
    end BLOCK3;
  
  
 
return 1;
end;;

DROP FUNCTION IF EXISTS `ot_duration_register`;;
CREATE FUNCTION `ot_duration_register` (`Pyear_month` date, `Pemp_pkey` int, `Pbranch_code` varchar(30)) RETURNS varchar(100) CHARACTER SET 'latin1' LANGUAGE SQL
READS SQL DATA
    DETERMINISTIC
begin

declare vemp_pkey int;
declare vatt_date  date;
declare nday  int;
declare vdaytimeId  int;
declare vLOGDATE_intime datetime;
declare vLOGDATE_outime datetime;
declare vduration float;
declare vminuts_calc_perday int;
declare vsetvalue varchar(10);
declare vexistvalue varchar(10);
declare vattendance_date int;
declare vmonthly_att_fromdate datetime;
declare vmonthly_att_todate datetime;
declare vemp_count int;
declare vmin_bfr_on_dutty_cal_ot	int;
declare vmin_aftr_off_dutty_cal_ot int ;
declare vwork_time_day_off_cal_ot int;
declare von_dutty1 varchar(30);
declare voff_dutty1 varchar(30);
declare vworking_time1 int;
declare voff_dutty1_ot varchar(30);
declare von_dutty1_ot  varchar(30);
declare vot_duration int;
declare vstrict_monitorings varchar(30);
declare vcompany_code varchar(10);

		declare vweekoff  varchar(30);
		declare vpresent  varchar(30);
		declare vleaves  varchar(30);
		declare vholiday  varchar(30);
		declare vothers  varchar(30);
		declare vloop_count int;
		declare vsetfield varchar(30);
		

select distinct attendance_date into vattendance_date
                           from db_config where active='Y';
						   
					
		select distinct company_code into vcompany_code  from branches where branch_code=if(pBranch_code in(null,''),Branch_code,pBranch_code) limit 1;			
SELECT att_start_end_fn(DATE_FORMAT(Pyear_month, '%Y-%m-01'), 1) into vmonthly_att_fromdate;
SELECT att_start_end_fn(DATE_FORMAT(Pyear_month, '%Y-%m-01'), 2) into vmonthly_att_todate;





 BLOCK7:begin
DECLARE vsunday  char(1);
DECLARE vmonday  char(1);
DECLARE vtuesday  char(1);
DECLARE vwednesday  char(1);
DECLARE vthursday  char(1);
DECLARE vfriday  char(1);
DECLARE vsaturday  char(1);
declare vcount int;

declare i int;
declare vfirst_name  varchar(50);
declare vholidayId int;
DECLARE exit_loop BOOLEAN default FALSE;

declare cur cursor for
select emp_pkey,first_name from emp_details where emp_pkey in 
  (select emp_fkey from emp_proff where date_format(joining_date,'%Y-%m-%d') <= vmonthly_att_todate 
  and day_time_seq in(select day_time_seq from working_day_time_procedures where (min_aftr_off_dutty_cal_ot <>0   or	 
	min_bfr_on_dutty_cal_ot<>0  or work_time_day_off_cal_ot=1)) )
   and emp_pkey=if(pemp_pkey in(null,0,''),emp_pkey,pemp_pkey) and branch_code=if(pBranch_code in(null,''),Branch_code,pBranch_code)
  and emp_id in (select emp_id  from device_attandance where lcase(c1)='in' and ucase(status)='Y'
 and date_format(LOGDATE,'%Y-%m-%d') between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d') and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d') and ucase(status)='Y')
and emp_pkey not in (select emp_pkey from emp_ot_master where  month=Pyear_month and is_verified='Y')  ;

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;


open cur;
start_loop: loop
    fetch cur into vemp_pkey,vfirst_name;
   IF exit_loop THEN        LEAVE start_loop;     END IF;
   
select count(*) into vcount from emp_proff 
   where day_time_seq in(select day_time_seq from working_day_time_procedures where working_time1 > 10
	 and (min_aftr_off_dutty_cal_ot >0   or	 
	min_bfr_on_dutty_cal_ot	>0  or work_time_day_off_cal_ot=1 )
	) and emp_fkey= vemp_pkey;
	
  
  
	
if vcount >0 then

select to_days(DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d'))into i;

WHILE i <= to_days(vmonthly_att_todate) DO
select count(*) into vemp_count from emp_ot_timeattandance where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and yearmonth=Pyear_month  ;
if vemp_count=0 then
insert into emp_ot_timeattandance (emp_pkey,att_date,yearmonth) values (vemp_pkey,DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d'),Pyear_month );
end if;
select i + 1 into i;
END WHILE;
 end if;
 
 end loop start_loop;
 close cur ;
END BLOCK7; 
 


 BLOCK8:begin
 declare vfunctionop varchar(100);
 declare vempatt_pkey int;
		declare vatt_date date;
		declare vweekoff  varchar(30);
		declare vpresent  varchar(30);
		declare vleaves  varchar(30);
		declare vholiday  varchar(30);
		declare vothers  varchar(30);
		declare vloop_count int;
		declare vsetfield varchar(30);
		declare vduration int;
 DECLARE exit_loop1 BOOLEAN default FALSE;

declare att_cur cursor for   
   select distinct emp_pkey,date_format(LOGDATE,'%Y-%m-%d')   
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 
 and lcase(c1)='in' and ucase(att.status)='Y'
  and date_format(LOGDATE,'%Y-%m-%d') between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d') and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d')
 and emp_pkey in
 (select emp_fkey from emp_proff where to_days(DATE_FORMAT(joining_date , '%Y-%m-%d')) <= to_days(DATE_FORMAT(vmonthly_att_todate , '%Y-%m-%d'))
  and day_time_seq in(select day_time_seq from working_day_time_procedures where working_time1 > 10 and (min_aftr_off_dutty_cal_ot <>0   or	 
	min_bfr_on_dutty_cal_ot<>0  or work_time_day_off_cal_ot=1))) 
	and emp_pkey=if(pemp_pkey in(null,0),emp_pkey,pemp_pkey) and ed.branch_code=if(pBranch_code in(null,''),ed.Branch_code,pBranch_code)
	 and emp_pkey not in (select emp_fkey from emp_ot_master where month=Pyear_month and is_verified='Y')
 order by 1;
 

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;

SELECT time_duration_check(DATE_FORMAT(Pyear_month, '%Y-%m-01'), vemp_pkey, PBranch_code) into vfunctionop ;
open att_cur;
att_loop: loop
    fetch att_cur into vemp_pkey,vatt_date;

  IF exit_loop1 THEN
	LEAVE att_loop;
  END IF;

   select DATE_FORMAT(vatt_date,'%d') into nday ; 


  select present,weekoff,leaves,holiday,others,ifnull(duration,0)duration,att_in_time,att_out_time 
  into vpresent,vweekoff,vleaves,vholiday,vothers,
				  vduration,vLOGDATE_intime,vLOGDATE_outime 
				  from emp_detail_timeattandance 
		   where yearmonth=Pyear_month  and emp_pkey=vemp_pkey and att_date=vatt_date ;  
 


select day_time_seq into vdaytimeId from emp_proff where emp_fkey=vemp_pkey;
   
 select distinct minuts_calc_perday,min_bfr_on_dutty_cal_ot,min_aftr_off_dutty_cal_ot,work_time_day_off_cal_ot,on_dutty1,off_dutty1,working_time1,strict_monitorings
 into vminuts_calc_perday ,vmin_bfr_on_dutty_cal_ot,vmin_aftr_off_dutty_cal_ot,vwork_time_day_off_cal_ot,von_dutty1,voff_dutty1,vworking_time1,vstrict_monitorings
   from working_day_time_procedures where day_time_seq=vdaytimeId ;
   
 
   if vcompany_code='INFR' then 
     set voff_dutty1='17:30';
   elseif  vcompany_code in ('DDP','BRHM','BRHH')  then
    set vworking_time1= vminuts_calc_perday ;	
   else
   set voff_dutty1= voff_dutty1;  
   end if;
   if vduration >= vminuts_calc_perday then 
    if vstrict_monitorings='Y' then
     if vmin_bfr_on_dutty_cal_ot >0  then
     if vLOGDATE_intime <= DATE_ADD(concat(date_format(vatt_date ,'%Y-%m-%d'),' ',von_dutty1),interval concat('-',vmin_bfr_on_dutty_cal_ot) MINUTE) then
	 
	    
	 set von_dutty1_ot=TIMESTAMPDIFF(Minute,vLOGDATE_intime,concat(date_format(vLOGDATE_intime ,'%Y-%m-%d'),' ',von_dutty1));
	 else 
	 set von_dutty1_ot=null;
	 end if;
	 end if; 
	 
	 
	 if vmin_aftr_off_dutty_cal_ot >0 then
	   	   
	    if vLOGDATE_outime >= date_format(DATE_ADD(concat(date_format(vLOGDATE_outime ,'%Y-%m-%d'),' ',voff_dutty1),interval vmin_aftr_off_dutty_cal_ot MINUTE),'%Y-%m-%d %H:%i:%s') then
    	   set voff_dutty1_ot=TIMESTAMPDIFF(Minute,concat(date_format(vLOGDATE_outime ,'%Y-%m-%d'),' ',voff_dutty1),vLOGDATE_outime);
		   
		else  
         set voff_dutty1_ot=null;	
       end if; 		 
     
	  else
	  set voff_dutty1_ot=null;
	 end if;
	
	  set vot_duration = ifnull(von_dutty1_ot,0) + ifnull(voff_dutty1_ot,0);
   else
 
     
	  if vduration > (vworking_time1+vmin_aftr_off_dutty_cal_ot) then
	
	   set vot_duration = vduration - vworking_time1;
	   
	   else 
	   set vot_duration=null;
	 end if; 
	
	end if;
	
   end if; 
 
 
   


if vot_duration >0 then

select count(*) into vemp_count from emp_ot_timeattandance where emp_pkey=vemp_pkey and att_date=vatt_date and yearmonth=Pyear_month  ;

if vemp_count =0 then
 insert into emp_ot_timeattandance (emp_pkey,
att_date, 
att_in_time	,	 
att_out_time,min_bfr_on_dutty_cal_ot,min_aftr_off_dutty_cal_ot,ot_duration,	 
duration,present ,yearmonth,set_duration)
 values (vemp_pkey,vatt_date ,vLOGDATE_intime,vLOGDATE_outime,von_dutty1_ot,abs(voff_dutty1_ot),vot_duration,vduration,vsetvalue,Pyear_month,vot_duration );
else
select count(*) into vemp_count from emp_ot_timeattandance 
  where emp_pkey=vemp_pkey and att_date=vatt_date and yearmonth=Pyear_month and isdelete='N' ;
 if vemp_count =0 then 
	update emp_ot_timeattandance set att_in_time=vLOGDATE_intime,	 
	att_out_time=vLOGDATE_outime,	 
	duration=vduration,present=vsetvalue,min_bfr_on_dutty_cal_ot=von_dutty1_ot,min_aftr_off_dutty_cal_ot=abs(voff_dutty1_ot),
	ot_duration=vot_duration,set_duration=vot_duration
	where emp_pkey=vemp_pkey and att_date=vatt_date and yearmonth=Pyear_month  ;
  end if;	
end if;

 end if;
set vatt_date= null;
set vLOGDATE_intime = null;
set vLOGDATE_outime=null;
set vduration=null;
set von_dutty1_ot=null;
set voff_dutty1_ot=null;
set vot_duration=null;
set vmin_bfr_on_dutty_cal_ot=null;

  end loop att_loop;
close att_cur;
end BLOCK8;

set vatt_date= null;
set vLOGDATE_intime = null;
set vLOGDATE_outime=null;
set vduration=null;
set von_dutty1_ot=null;
set voff_dutty1_ot=null;
set vot_duration=null;


 
 
