  blockmaster:begin
  declare vtotal_duration float;
  declare vemp_name  varchar(200);
  declare vcount_otmaster int;
  DECLARE exit_loop_master BOOLEAN default FALSE;
declare ot_master_cur cursor for   
  select  sum(set_duration) total_duration,emp_pkey
    from emp_ot_timeattandance where yearmonth=Pyear_month 
	and emp_pkey not in(select emp_fkey from emp_ot_master where is_verified='Y'and month=Pyear_month) group by emp_pkey,yearmonth;
	
 	
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop_master = TRUE;

open ot_master_cur ;
start_loop_master: loop
     fetch ot_master_cur into vtotal_duration,vemp_pkey;
	
	IF exit_loop_master THEN        LEAVE start_loop_master;     END IF;
	
	select count(*) into vcount_otmaster from emp_ot_master where month=Pyear_month and emp_fkey=vemp_pkey;
	
	if  vtotal_duration is not null then
	if vcount_otmaster=0 then
		
	select concat(first_name,' ',ifnull(middile_name,''),' ',ifnull(last_name,'')) AS vemp_name into vemp_name from emp_details where emp_pkey=vemp_pkey;
	
   insert into emp_ot_master(emp_fkey,emp_name,month,total_duration)
     values(vemp_pkey,vemp_name,Pyear_month,vtotal_duration ); 
   
   else 
   update emp_ot_master set total_duration=vtotal_duration where emp_fkey=vemp_pkey and month=Pyear_month;
   
   end if;
   end if;
  
  set vtotal_duration=null;
  
  end loop start_loop_master;
  end blockmaster;


return 'OK';

end;;

DROP FUNCTION IF EXISTS `ot_duration_register_date`;;
CREATE FUNCTION `ot_duration_register_date` (`pdate` date, `pemp_pkey` int, `pbranch_code` varchar(30)) RETURNS varchar(100) CHARACTER SET 'latin1' LANGUAGE SQL
MODIFIES SQL DATA
    DETERMINISTIC
begin
declare vemp_pkey int;
declare vatt_date date;
declare vdaytimeId int;
declare vLOGDATE_intime datetime;
declare vLOGDATE_outime datetime;
declare vduration float;
declare vminuts_calc_perday int;
declare vminutes_per_half int;
declare vatt_fromdate datetime;
declare vatt_todate datetime;
declare vmonthly_att_fromdate datetime;
declare vmonthly_att_todate datetime;
declare vemp_count int;
declare vmin_bfr_on_dutty_cal_ot int;
declare vmin_aftr_off_dutty_cal_ot int;
declare vwork_time_day_off_cal_ot int;
declare vot_eligibility_threshold char(1);
declare von_dutty1 varchar(30);
declare voff_dutty1 varchar(30);
declare vworking_time1 int;
declare voff_dutty1_ot varchar(30);
declare von_dutty1_ot varchar(30);
declare vot_duration int;
declare vstrict_monitorings varchar(30);
declare vcompany_code varchar(10);
declare vyear_month date;
declare vLOGDATE_intime_ot datetime;
declare vLOGDATE_outime_ot datetime;
declare vINTIME_ot varchar(30);
declare vOUTIME_ot varchar(30);
declare vbreak_time varchar(30);
declare vatt_count int;
declare vshift_count int;
declare vhalf_day_end datetime;
declare voff_day_duration float;
declare vpresent varchar(30);
declare vINTIME varchar(30);
declare vOUTIME varchar(30);
declare vholidayId int;
declare vholiday_count int;
declare vweekoff_count int;
declare vweekoff_status varchar(10);
declare vday_name varchar(20);
declare vweek int;
declare vex_count int;
declare vSunday char(1);
declare vMonday char(1);
declare vTuesday char(1);
declare vWednesday char(1);
declare vThursday char(1);
declare vFriday char(1);
declare vSaturday char(1);
declare vSunday_F char(1);
declare vMonday_F char(1);
declare vTuesday_F char(1);
declare vWednesday_F char(1);
declare vThursday_F char(1);
declare vFriday_F char(1);
declare vSaturday_F char(1);
declare vvouttime datetime;
declare visnextday int;

declare exit_loop boolean default false;

declare ot_cur cursor for
select distinct ed.emp_pkey, da.SHIFTDATE
from device_attandance as da join emp_details as ed on da.emp_id = ed.emp_id and da.company_code = ed.company_code
join emp_proff as ep on ep.emp_fkey = ed.emp_pkey
left join emp_shift_planner as esp on esp.emp_fkey = ed.emp_pkey and esp.shift_date = da.SHIFTDATE and esp.status = 1
join working_day_time_procedures as wdtp on wdtp.day_time_seq = coalesce(esp.shift_id, ep.day_time_seq)
left join termination as t on t.emp_fkey = ed.emp_pkey and t.status = 1
where lcase(da.C1) = 'in'and ucase(da.status) = 'Y' and da.SHIFTDATE = pdate and ed.emp_pkey = pemp_pkey and ed.branch_code = pbranch_code
and to_days(date_format(ep.joining_date, '%Y-%m-%d')) <= to_days(date_format(vmonthly_att_todate, '%Y-%m-%d'))
and (t.emp_fkey is null or to_days(pdate) <= to_days(t.last_approved_working_date))
and wdtp.working_time1 > 10 and (wdtp.min_aftr_off_dutty_cal_ot <> 0 or wdtp.min_bfr_on_dutty_cal_ot <> 0 or wdtp.work_time_day_off_cal_ot = 1)
and ed.emp_pkey not in (select emp_pkey from emp_ot_timeattandance where att_date = pdate and isdelete = 'N') order by 1;

declare continue handler for not found set exit_loop = true;

delete from emp_ot_timeattandance where emp_pkey = pemp_pkey and att_date = pdate and is_manual = 'N' and isdelete = 'Y';

select distinct company_code into vcompany_code from branches
where branch_code = pbranch_code limit 1;

select att_start_end_fn(date_format(pdate, '%Y-%m-01'), 1) into vatt_fromdate;
select att_start_end_fn(date_format(pdate, '%Y-%m-01'), 2) into vatt_todate;

if pdate between vatt_fromdate and vatt_todate then
    set vyear_month = date_format(pdate, '%Y-%m-01');
else
    set vyear_month = date_add(date_format(pdate, '%Y-%m-01'), interval 1 month);
end if;

select att_start_end_fn(vyear_month, 1) into vmonthly_att_fromdate;
select att_start_end_fn(vyear_month, 2) into vmonthly_att_todate;

open ot_cur;
	start_loop: loop
		fetch ot_cur into vemp_pkey, vatt_date;
		
		if exit_loop then
			leave start_loop;
		end if;
		
		select present, ifnull(duration, 0) as duration, att_in_time, att_out_time
		into vpresent, vduration, vLOGDATE_intime, vLOGDATE_outime
		from emp_detail_timeattandance where yearmonth = vyear_month and emp_pkey = vemp_pkey and att_date = vatt_date;
		
		select count(*) into vshift_count from emp_shift_planner
		where emp_fkey = vemp_pkey and shift_date = vatt_date and status = 1;
		
		if vshift_count > 0 then
			select shift_id into vdaytimeId from emp_shift_planner
			where emp_fkey = vemp_pkey and shift_date = vatt_date and status = 1;
		else
			select day_time_seq into vdaytimeId from emp_proff where emp_fkey = vemp_pkey order by emp_proff_pkey desc limit 1;
		end if;
		
		select distinct minuts_calc_perday, minutes_per_half, min_bfr_on_dutty_cal_ot, min_aftr_off_dutty_cal_ot, work_time_day_off_cal_ot, ot_eligibility_threshold, on_dutty1, off_dutty1, working_time1, isnextday, strict_monitorings, Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday_F, Monday_F, Tuesday_F, Wednesday_F, Thursday_F, Friday_F, Saturday_F
		into vminuts_calc_perday, vminutes_per_half, vmin_bfr_on_dutty_cal_ot, vmin_aftr_off_dutty_cal_ot, vwork_time_day_off_cal_ot, vot_eligibility_threshold, von_dutty1, voff_dutty1, vworking_time1, visnextday, vstrict_monitorings, vSunday, vMonday, vTuesday, vWednesday, vThursday, vFriday, vSaturday, vSunday_F, vMonday_F, vTuesday_F, vWednesday_F, vThursday_F, vFriday_F, vSaturday_F
		from working_day_time_procedures where day_time_seq = vdaytimeId;
		
		select HOLIDAY_GROUP_ID into vholidayId from emp_proff where emp_fkey = vemp_pkey order by emp_proff_pkey desc limit 1;
		
		set vweekoff_status = null;
		set vholiday_count = 0;
		set vweekoff_count = 0;
		set vex_count = 0;
		
		select count(*) into vholiday_count from holidays
		where HOLIDAY_GROUP_ID = vholidayId and status = 1 and HOLIDAYDATE = vatt_date;
		
		select sum(weekoff) into vweekoff_count from
		(
			select count(*) as weekoff from working_day_time_procedures where day_time_seq = vdaytimeId and active = 1
			and (Sunday = 'N' or Monday = 'N' or Tuesday = 'N' or Wednesday = 'N' or Thursday = 'N' or Friday = 'N' or Saturday = 'N'
			or Sunday_F = 'Y' or Monday_F = 'Y' or Tuesday_F = 'Y' or Wednesday_F = 'Y' or Thursday_F = 'Y' or Friday_F = 'Y' or Saturday_F = 'Y')
			union all
			select count(*) as weekoff from shift_exceptions
			where shift_id = vdaytimeId and week_off = 'Y' and status = 1
		) as shift_policy;
		
		if vweekoff_count > 0 then
			set vday_name = lcase(dayname(vatt_date));
			set vweek = floor((dayofmonth(vatt_date) - 1) / 7) + 1;
			
			select count(*) into vex_count from shift_exceptions
			where shift_id = vdaytimeId and week_off = 'Y' and status = 1
			and lcase(ex_week_day) = vday_name and cast(ex_week as unsigned) = vweek;
			
			if (vday_name = 'sunday' and (vSunday    = 'N' or vex_count > 0)) or
			(vday_name = 'monday'    and (vMonday    = 'N' or vex_count > 0)) or
			(vday_name = 'tuesday'   and (vTuesday   = 'N' or vex_count > 0)) or
			(vday_name = 'wednesday' and (vWednesday = 'N' or vex_count > 0)) or
			(vday_name = 'thursday'  and (vThursday  = 'N' or vex_count > 0)) or
			(vday_name = 'friday'    and (vFriday    = 'N' or vex_count > 0)) or
			(vday_name = 'saturday'  and (vSaturday  = 'N' or vex_count > 0)) then
				set vweekoff_status = 'WO';
			elseif (vday_name = 'sunday' and vSunday_F    = 'Y') or
				(vday_name = 'monday'    and vMonday_F    = 'Y') or
				(vday_name = 'tuesday'   and vTuesday_F   = 'Y') or
				(vday_name = 'wednesday' and vWednesday_F = 'Y') or
				(vday_name = 'thursday'  and vThursday_F  = 'Y') or
				(vday_name = 'friday'    and vFriday_F    = 'Y') or
				(vday_name = 'saturday'  and vSaturday_F  = 'Y') then
				set vweekoff_status = '/WO';
			end if;
		end if;
		
		if vwork_time_day_off_cal_ot = 1 and (vholiday_count > 0 or vweekoff_status = 'WO') then
			set vot_duration = vduration;
			set voff_day_duration = vot_duration;
		elseif vweekoff_status = '/WO' and vholiday_count = 0 then
			set vhalf_day_end = date_add(concat(date_format(vatt_date, '%Y-%m-%d'), ' ', von_dutty1), interval vworking_time1 / 2 minute);
			
			if vLOGDATE_intime >= vhalf_day_end then
				if vwork_time_day_off_cal_ot = 1 then
					set vot_duration = vduration;
					set voff_day_duration = vot_duration;
				end if;
			else
				if vmin_bfr_on_dutty_cal_ot > 0 or vmin_aftr_off_dutty_cal_ot > 0 then
					if vot_eligibility_threshold = 'Y' then
						if vduration >= vminutes_per_half then
							if vstrict_monitorings = 'Y' then
								if vmin_bfr_on_dutty_cal_ot > 0 then
									if vLOGDATE_intime <= date_add(concat(date_format(vatt_date, '%Y-%m-%d'), ' ', von_dutty1), interval concat('-', vmin_bfr_on_dutty_cal_ot) minute) then
										set von_dutty1_ot = timestampdiff(minute, vLOGDATE_intime, concat(date_format(vatt_date, '%Y-%m-%d'), ' ', von_dutty1));
									else
										set von_dutty1_ot = null;
									end if;
								end if;
								
								if vmin_aftr_off_dutty_cal_ot > 0 then
									if vLOGDATE_outime >= date_add(concat(date_format(vatt_date, '%Y-%m-%d'), ' ', von_dutty1), interval (vworking_time1 / 2 + vmin_aftr_off_dutty_cal_ot) minute) then
										set voff_dutty1_ot = timestampdiff(minute, vhalf_day_end, vLOGDATE_outime);
									else
										set voff_dutty1_ot = null;
									end if;
								end if;
								
								set vot_duration = ifnull(von_dutty1_ot, 0) + ifnull(voff_dutty1_ot, 0);
							else
								if vduration > (vworking_time1 / 2 + vmin_aftr_off_dutty_cal_ot) then
									set vot_duration = vduration - (vworking_time1 / 2);
									set voff_dutty1_ot = vot_duration;
								end if;
							end if;
						end if;
					else
						if vstrict_monitorings = 'Y' then
							if vmin_bfr_on_dutty_cal_ot > 0 then
								if vLOGDATE_intime <= date_add(concat(date_format(vatt_date, '%Y-%m-%d'), ' ', von_dutty1), interval concat('-', vmin_bfr_on_dutty_cal_ot) minute) then
									set von_dutty1_ot = timestampdiff(minute, vLOGDATE_intime, concat(date_format(vatt_date, '%Y-%m-%d'), ' ', von_dutty1));
								else
									set von_dutty1_ot = null;
								end if;
							end if;
							
							if vmin_aftr_off_dutty_cal_ot > 0 then
								if vLOGDATE_outime >= date_add(concat(date_format(vatt_date, '%Y-%m-%d'), ' ', von_dutty1), interval (vworking_time1 / 2 + vmin_aftr_off_dutty_cal_ot) minute) then
									set voff_dutty1_ot = timestampdiff(minute, vhalf_day_end, vLOGDATE_outime);
								else
									set voff_dutty1_ot = null;
								end if;
							end if;
							
							set vot_duration = ifnull(von_dutty1_ot, 0) + ifnull(voff_dutty1_ot, 0);
						else
							if vduration > (vworking_time1 / 2 + vmin_aftr_off_dutty_cal_ot) then
								set vot_duration = vduration - (vworking_time1 / 2);
								set voff_dutty1_ot = vot_duration;
							end if;
						end if;
					end if;
				end if;
			end if;
		elseif vweekoff_status is null and vholiday_count = 0 and (vmin_bfr_on_dutty_cal_ot > 0 or vmin_aftr_off_dutty_cal_ot > 0) then
			select max(LOGDATE) into vLOGDATE_intime_ot
			from device_attandance as da join emp_details as ed on da.emp_id = ed.emp_id and da.company_code = ed.company_code
			where lcase(c1) = 'in' and ed.emp_pkey = vemp_pkey and ucase(da.status) = 'Y'
			and da.SHIFTDATE = vatt_date and da.LOGDATE > vLOGDATE_intime
			and (da.LOGDATE, ed.emp_id)
			in (select max(LOGDATE), emp_id from device_attandance
			where SHIFTDATE = vatt_date and lcase(c1) = 'in' and ucase(status) = 'Y' group by emp_id);
			
			select min(LOGDATE) into vLOGDATE_outime_ot
			from device_attandance as da join emp_details as ed on da.emp_id = ed.emp_id and da.company_code = ed.company_code
			where lcase(c1) = 'out' and ed.emp_pkey = vemp_pkey and ucase(da.status) = 'Y'
			and SHIFTDATE = vatt_date and da.LOGDATE < vLOGDATE_outime
			and (da.LOGDATE, ed.emp_id)
			in (select min(LOGDATE), emp_id from device_attandance
			where SHIFTDATE = vatt_date and lcase(c1) = 'out' and ucase(status) = 'Y' group by emp_id);
			
			select time(vLOGDATE_intime) into vINTIME;
			select time(vLOGDATE_outime) into vOUTIME;
			select time(vLOGDATE_intime_ot) into vINTIME_ot;
			select time(vLOGDATE_outime_ot) into vOUTIME_ot;
			
			select count(*) into vatt_count from device_attandance
			where SHIFTDATE = vatt_date and emp_id in (select emp_id from emp_details where emp_pkey = vemp_pkey);
			
			if vcompany_code in ('TICM') then
				if vINTIME >= voff_dutty1 then
					set voff_dutty1 = vINTIME;
				else
					if vINTIME_ot >= voff_dutty1 then
						if vOUTIME_ot <= voff_dutty1 then
							set voff_dutty1 = vINTIME_ot;
						else
							set voff_dutty1 = voff_dutty1;
						end if;
					else
						set voff_dutty1 = voff_dutty1;
					end if;	
				end if;
			elseif vcompany_code in ('INFR') then
				set voff_dutty1 = '17:30';
			elseif vcompany_code in ('DDP') then
				set vworking_time1 = vminuts_calc_perday;
			else
				set voff_dutty1 = voff_dutty1;
			end if;
			
			if vcompany_code in ('TICM') then
				if vstrict_monitorings = 'Y' then
					if vmin_bfr_on_dutty_cal_ot > 0 then
						if vLOGDATE_intime <= date_add(concat(date_format(vatt_date, '%Y-%m-%d'), ' ', von_dutty1), interval concat('-', vmin_bfr_on_dutty_cal_ot) minute) then
							set von_dutty1_ot = timestampdiff(minute, vLOGDATE_intime, concat(date_format(vatt_date, '%Y-%m-%d'), ' ', von_dutty1));
						else
							set von_dutty1_ot = null;
						end if;
					end if;
					
					if vmin_aftr_off_dutty_cal_ot > 0 then
						if visnextday = 1 then
							select date_add(vatt_date, interval 1 day) into vvouttime;
						else
							set vvouttime = vatt_date;
						end if;
						
						if vLOGDATE_outime >= date_format(date_add(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), interval vmin_aftr_off_dutty_cal_ot minute), '%Y-%m-%d %H:%i:%s') then
							if vatt_count > 2 then
								if vOUTIME_ot > voff_dutty1 then
									set vbreak_time = timestampdiff(minute, vLOGDATE_outime_ot, vLOGDATE_intime_ot);
								end if;
							end if;
							
							set voff_dutty1_ot = timestampdiff(minute, concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), vLOGDATE_outime) - ifnull(vbreak_time, 0);
						else
							set voff_dutty1_ot = null;
						end if;
					end if;
					
					set vot_duration = ifnull(von_dutty1_ot, 0) + ifnull(voff_dutty1_ot, 0);
				else
					if vduration > (vworking_time1 + vmin_aftr_off_dutty_cal_ot) then
						set vot_duration = vduration - vworking_time1;
						set voff_dutty1_ot = vot_duration;
					else
						set vot_duration = null;
					end if;
				end if;
			else
				if vot_eligibility_threshold = 'Y' then
					if vduration >= vminuts_calc_perday then
						if vstrict_monitorings = 'Y' then
							if vmin_bfr_on_dutty_cal_ot > 0 then
								if vLOGDATE_intime <= date_add(concat(date_format(vatt_date, '%Y-%m-%d'), ' ', von_dutty1), interval concat('-', vmin_bfr_on_dutty_cal_ot) minute) then
									set von_dutty1_ot = timestampdiff(minute, vLOGDATE_intime, concat(date_format(vatt_date, '%Y-%m-%d'), ' ', von_dutty1));
								else
									set von_dutty1_ot = null;
								end if;
							end if;
							
							if vmin_aftr_off_dutty_cal_ot > 0 then
								if visnextday = 1 then
									select date_add(vatt_date, interval 1 day) into vvouttime;
								else
									set vvouttime = vatt_date;
								end if;
								
								if vLOGDATE_outime >= date_format(date_add(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), interval vmin_aftr_off_dutty_cal_ot minute), '%Y-%m-%d %H:%i:%s') then
									set voff_dutty1_ot = timestampdiff(minute, concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), vLOGDATE_outime);
								else
									set voff_dutty1_ot = null;
								end if;
							end if;
							
							set vot_duration = ifnull(von_dutty1_ot, 0) + ifnull(voff_dutty1_ot, 0);
						else
							if vduration > (vworking_time1 + vmin_aftr_off_dutty_cal_ot) then
								set vot_duration = vduration - vworking_time1;
								set voff_dutty1_ot = vot_duration;
							else
								set vot_duration = null;
							end if;
						end if;
					end if;
				else
					if vstrict_monitorings = 'Y' then
						if vmin_bfr_on_dutty_cal_ot > 0 then
							if vLOGDATE_intime <= date_add(concat(date_format(vatt_date, '%Y-%m-%d'), ' ', von_dutty1), interval concat('-', vmin_bfr_on_dutty_cal_ot) minute) then
								set von_dutty1_ot = timestampdiff(minute, vLOGDATE_intime, concat(date_format(vatt_date, '%Y-%m-%d'), ' ', von_dutty1));
							else
								set von_dutty1_ot = null;
							end if;
						end if;
						
						if vmin_aftr_off_dutty_cal_ot > 0 then
							if visnextday = 1 then
								select date_add(vatt_date, interval 1 day) into vvouttime;
							else
								set vvouttime = vatt_date;
							end if;
							
							if vLOGDATE_outime >= date_format(date_add(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), interval vmin_aftr_off_dutty_cal_ot minute), '%Y-%m-%d %H:%i:%s') then
								set voff_dutty1_ot = timestampdiff(minute, concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), vLOGDATE_outime);
							else
								set voff_dutty1_ot = null;
							end if;
						end if;
						
						set vot_duration = ifnull(von_dutty1_ot, 0) + ifnull(voff_dutty1_ot, 0);
					else
						if vduration > (vworking_time1 + vmin_aftr_off_dutty_cal_ot) then
							set vot_duration = vduration - vworking_time1;
							set voff_dutty1_ot = vot_duration;
						else
							set vot_duration = null;
						end if;
					end if;
				end if;
			end if;
		end if;
		
		select count(*) into vemp_count from emp_ot_timeattandance
		where emp_pkey = vemp_pkey and att_date = vatt_date;
		
		if vemp_count = 0 then
			if vot_duration > 0 then
				insert into emp_ot_timeattandance (emp_pkey, att_date, att_in_time, att_out_time, min_bfr_on_dutty_cal_ot, min_aftr_off_dutty_cal_ot, work_time_day_off_cal_ot, ot_duration, duration, present, yearmonth, set_duration)
				values (vemp_pkey, vatt_date, vLOGDATE_intime, vLOGDATE_outime, von_dutty1_ot, abs(voff_dutty1_ot), voff_day_duration, vot_duration, vduration, vpresent, vyear_month, vot_duration);
			end if;
		else
			update emp_ot_timeattandance set att_in_time = vLOGDATE_intime, att_out_time = vLOGDATE_outime, duration = vduration, present = vpresent, min_bfr_on_dutty_cal_ot = von_dutty1_ot, min_aftr_off_dutty_cal_ot = abs(voff_dutty1_ot), work_time_day_off_cal_ot = voff_day_duration, ot_duration = vot_duration, set_duration = vot_duration
			where emp_pkey = vemp_pkey and att_date = vatt_date and yearmonth = vyear_month and is_manual = 'N';
		end if;
		
		set vatt_date = null;
		set vLOGDATE_intime = null;
		set vLOGDATE_outime = null;
		set vduration = null;
		set von_dutty1_ot = null;
		set voff_dutty1_ot = null;
		set voff_day_duration = null;
		set vot_duration = null;
		set vmin_bfr_on_dutty_cal_ot = null;
		set vbreak_time = null;
		set vweekoff_status = null;
		set vholiday_count = 0;
		set vweekoff_count = 0;
		set vex_count = 0;
		set vhalf_day_end = null;
	end loop start_loop;
close ot_cur;

return 'OK';
end;;

DROP PROCEDURE IF EXISTS `payroll_master_approve`;;
CREATE PROCEDURE `payroll_master_approve` (IN `pbranch` varchar(30), IN `pmonth_year` varchar(30), IN `pemp_fkey` int, IN `puser_id` varchar(30), OUT `perror_message` varchar(300))
begin


declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vDeviceId int;
declare vjoining_date	  date;
declare vemp_company_id	varchar(30);	 
declare vemp_type	varchar(30);	 
