declare advancecur cursor for
 select emp_advance_pkey,emp_fkey,0 salary_head_item_fkey,'Salary Advance'salary_head_item_desc,advance_amount uploaded_amount,'Deduction' head_operator,'Fixed' head_type,'Direct'item_part 
 from emp_advance 
  where emp_fkey = pemp_fkey and status= 1 and date_format(affected_month,'%Y-%m') = pmonth_year ;
  
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop4 = TRUE;
 	
open advancecur ;
start_loop1: loop
    fetch advancecur into vemp_advance_pkey ,vemp_pkey,	 
vsalary_head_item_fkey,vsalary_head_item_desc,vstructure_det_value,vhead_operator,vhead_type,vitem_part;
   
IF exit_loop4 THEN 
       LEAVE start_loop1 ;   
  END IF;
 
	select count(*) into vadvance_count from emp_salary_slip where emp_fkey=pemp_fkey and month_year=pmonth_year 
	  and salary_head_item_fkey=vsalary_head_item_fkey and salary_amount=vstructure_det_value and end_date_effective is null;
	  if vadvance_count >0 then
	  
	  update emp_advance set is_credited='Y' ,modified_by=puser_id ,modified_date=current_date
	    where affected_month=pmonth_year and emp_advance_pkey=vemp_advance_pkey;
	  
