 select emp_loan_info_pkey,loan_pkey,emp_fkey,0 salary_head_item_fkey,'Loan'salary_head_item_desc,loan_emi uploaded_amount,'Deduction' head_operator,
 'Fixed' head_type,'Direct'item_part 	
 from emp_loan_info 
  where emp_fkey = pemp_fkey and status= 1 and loan_month = pmonth_year and paid_status in ('A','S');
  
