IF exit_loop6 THEN 
       LEAVE start_loop1 ;   
  END IF;
   select abs(salary_amount) into vloan_count from emp_salary_slip where emp_fkey=pemp_fkey and month_year=pmonth_year 
	  and salary_head_item_desc='Loan'  and end_date_effective is null;
	  if vloan_count >0 then
	    update emp_loan_info set paid_status='P',amount_paid=loan_emi,remarks=concat('EMI Deducted from Salary for the month ',pmonth_year),
       modified_by=puser_id, modified_date= current_date where emp_loan_info_pkey=vemp_loan_info_pkey ;	
	 
