DROP PROCEDURE IF EXISTS `payroll_master_insert`;;
CREATE PROCEDURE `payroll_master_insert` (IN `pbranch` varchar(30), IN `pmonth_year` varchar(30), IN `puser_id` varchar(30), OUT `perror_message` varchar(300))
begin

declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vDeviceId int;
declare vjoining_date	  date;
declare vemp_company_id	varchar(30);	 
declare vemp_type	varchar(30);	 
declare vdesignation	varchar(30); 
declare vemp_dept	varchar(30);
declare vemp_grade	varchar(30);
declare vemp_vertical   varchar(30);
declare vemp_branch varchar(30);	 
declare vHOLIDAY_GROUP_ID int;	 
declare vLEAVEPOLICY_GROUP_ID int;
declare vday_time_seq  int;
declare vpresant_total float;
declare vleave_total float;
declare vlop_total float;
declare vworking_days float;
declare vcalander_days int;
declare vemp_anual_ctc float;
declare vemp_monthly_ctc float ;
declare vemp_structure_id int ;
declare vprorate_code int;
declare vprorate_desc varchar(50);
declare vdefined_structure_for varchar(50);
declare vsalary_head_item_fkey int;
declare vsalary_head_item_desc varchar(100);
declare vstructure_det_value float;
declare vhead_operator varchar(20);
declare vhead_type varchar(25);
declare vitem_part varchar(25);
declare vstructure_id int;
declare vemp_salary float;
declare vday_count float ;
declare vholiday_count  float;
declare vmonthly_att_fromdate date;
declare vmonthly_att_todate date;
declare vmonth_yr  date;
declare vexistcount int;
declare v_holiday_woff_count float;
declare v_holiday_halfwoff_count float;
declare vweekoff_total float;
declare vholiday_total float;
declare vmonth varchar(25);
declare vbracnh_details varchar(500);
declare vexistcountprocessed int;
declare vwd_lop_total float;
declare rec_count int;
declare vpayroll_type varchar(10);
declare vm_weekoff_total float;
declare vm_holiday_total float;

DECLARE exit_loop BOOLEAN default FALSE;

declare cur cursor for
	select emp_fkey,emp_name,presant_total,leave_total,lop_total,wd_lop_total,weekoff_total,holiday_total
	from attendance_register where month_year = pmonth_year and isdelete = 'N'
	and emp_fkey in (select emp_pkey from emp_details where status = 1 and branch_code = pbranch)
	and emp_fkey in (select emp_fkey from emp_proff where structure_id is not null)
	
	union all
	
	select emp_fkey,emp_name,presant_total,leave_total,lop_total,0 as wd_lop_total,weekoff_total,holiday_total
	from site_attendance_register where month_year = pmonth_year and isdelete = 'N'
	and emp_fkey in (select emp_pkey from emp_details where status = 1 and branch_code = pbranch)
	and emp_fkey in (select emp_fkey from emp_proff where structure_id is not null);
	
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;

DELETE FROM payroll_master WHERE action IS NULL AND month_year = pmonth_year;

open cur;
	start_loop: loop
		fetch cur into vemp_pkey,vfirst_name,vpresant_total,vleave_total,vlop_total,vwd_lop_total,vweekoff_total,vholiday_total;
		
		IF exit_loop THEN
			LEAVE start_loop;
		END IF;
		
		select  concat(ifnull(bank_name,''),',',ifnull(branch_name,''),',',ifnull(ifsc_code,''),',',ifnull(account_no,'')) into vbracnh_details
		from emp_details  where emp_pkey=vemp_pkey;  
		
		select count(*) into vexistcount  from payroll_master
		where emp_fkey=vemp_pkey and month_year=pmonth_year and action is NULL;
		
		select count(*) into vexistcountprocessed  from payroll_master
		where emp_fkey=vemp_pkey and month_year=pmonth_year and action in ('Processed','Approved');
		
		set vmonth_yr  = concat(pmonth_year,'-01');
		
		SELECT att_start_end_fn(DATE_FORMAT(vmonth_yr, '%Y-%m-01'), 1) into vmonthly_att_fromdate;
		SELECT att_start_end_fn(DATE_FORMAT(vmonth_yr, '%Y-%m-01'), 2) into vmonthly_att_todate;
		
		select emp_type, structure_id into vemp_type, vstructure_id from emp_proff where emp_fkey = vemp_pkey order by emp_proff_pkey desc limit 1;
		
		if upper(vemp_type) = 'DAILY WAGES' then
			set vlop_total = vwd_lop_total;
		elseif upper(vemp_type) <> 'HOURLY WAGES' then
			select prorate_code into vprorate_code from salary_structure where structure_id = vstructure_id and structure_active = 1;
			
			if vprorate_code = 2 then
				set vlop_total = vwd_lop_total;
			end if;
		end if;
		
		set vcalander_days = datediff(vmonthly_att_todate, vmonthly_att_fromdate)+1;
		set vworking_days = vcalander_days - (vweekoff_total + vholiday_total);
		
		select distinct payroll_type into vpayroll_type from db_config where active = 'Y';
		
		if vpayroll_type = 'M' then
			set vmonthly_att_fromdate = date_format(vmonth_yr, '%Y-%m-01');
			set vmonthly_att_todate = last_day(vmonthly_att_fromdate);
			
			call get_policy_weekoff_holiday_count_prc(vemp_pkey, vmonthly_att_fromdate, vmonthly_att_todate, vm_weekoff_total, vm_holiday_total);
			
			set vcalander_days = day(vmonthly_att_todate);
			set vworking_days = vcalander_days - (vm_weekoff_total + vm_holiday_total);
			set vweekoff_total = vm_weekoff_total;
			set vholiday_total = vm_holiday_total;
		end if;
		
		if vpresant_total >= 0 and vexistcount = 0 and vexistcountprocessed = 0 then
			insert into payroll_master(emp_fkey, emp_name,	branch_code,month_year,days_presant, days_leave,loss_of_pay,calander_days,working_days, week_off_days, holidays, bank_details)
			values(vemp_pkey,vfirst_name,pbranch,pmonth_year,vpresant_total,vleave_total,vlop_total,vcalander_days,vworking_days, vweekoff_total, vholiday_total, vbracnh_details ) ;
		elseif vpresant_total >= 0 and vexistcount > 0 then
			update payroll_master set emp_name = vfirst_name, branch_code = pbranch, days_presant=vpresant_total, days_leave=vleave_total,loss_of_pay=vlop_total,
			calander_days=vcalander_days,working_days=vworking_days,week_off_days=vweekoff_total,holidays=vholiday_total,bank_details=vbracnh_details
			where emp_fkey=vemp_pkey and month_year=pmonth_year and approved='N';
		end if;
	end loop start_loop;
close cur;
end;;

DROP FUNCTION IF EXISTS `presant_leave_holiday_count`;;
CREATE FUNCTION `presant_leave_holiday_count` (`pemp_pkey` int, `pyear_month` date) RETURNS varchar(50) CHARACTER SET 'latin1' LANGUAGE SQL
begin

declare vpcount int;
declare vlcount int;
declare vhcount int;

select count(*) into vpcount  from attendance_register where field1='P/P' and emp_pkey=pemp_pkey;



return concat(vpcount ,vlcount ,vhcount );
end;;

DROP FUNCTION IF EXISTS `process_att_reg_fn`;;
CREATE FUNCTION `process_att_reg_fn` (`pcompany_code` varchar(30), `pbranch_code` varchar(30), `Pyear_month` date, `Pemp_pkey` int) RETURNS varchar(100) CHARACTER SET 'latin1' LANGUAGE SQL
READS SQL DATA
    DETERMINISTIC
begin
declare vemp_pkey int;
declare vatt_date  date;
declare nday  int;
declare vdaytimeId  int;
declare vLOGDATE_intime datetime;
declare vLOGDATE_outime datetime;
declare vduration int;
declare vminuts_calc_perday int;
declare vminutes_per_half int;
declare vsetvalue varchar(10);
declare vexistvalue varchar(10);
declare vattendance_date int;
declare vmonthly_att_fromdate datetime;
declare vmonthly_att_todate datetime;
declare vemp_count int;
DECLARE exit_loop1 BOOLEAN default FALSE;

declare att_cur cursor for   
   select distinct emp_pkey,date_format(LOGDATE,'%Y-%m-%d')   
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 

 and lcase(c1)='in' and ucase(att.status)='Y'
 and date_format(LOGDATE,'%Y-%m-%d') between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d') and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d')
  and emp_pkey in
 (select emp_fkey from emp_proff where to_days(DATE_FORMAT(joining_date , '%Y-%m-%d')) <= to_days(DATE_FORMAT(vmonthly_att_todate , '%Y-%m-%d'))
  and day_time_seq in(select day_time_seq from working_day_time_procedures where working_time1 > 10) ) and emp_pkey=if(pemp_pkey in(null,''),emp_pkey,pemp_pkey)
 order by 1;
 


DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;


select distinct attendance_date into vattendance_date
                           from db_config where active='Y';

if vattendance_date =0 then

set vmonthly_att_fromdate =DATE_FORMAT(Pyear_month, '%Y-%m-01');
set vmonthly_att_todate =LAST_DAY(DATE_FORMAT(Pyear_month, '%Y-%m-%d'));

else
   set vmonthly_att_fromdate =date_format(DATE_SUB(concat(DATE_FORMAT(DATE_SUB(Pyear_month,INTERVAL 1 month), '%Y-%m-'),date_format(last_day(DATE_SUB(Pyear_month,INTERVAL 1 month)),'%d')),INTERVAL vattendance_date-1 day),'%Y-%m-%d');  
                      



set vmonthly_att_todate =DATE_SUB(concat(DATE_FORMAT(Pyear_month, '%Y-%m-'),date_format(last_day(Pyear_month),'%d')),INTERVAL vattendance_date day);
 
 




end if ;



BLOCK7:begin
DECLARE vsunday  char(1);
DECLARE vmonday  char(1);
DECLARE vtuesday  char(1);
DECLARE vwednesday  char(1);
DECLARE vthursday  char(1);
DECLARE vfriday  char(1);
DECLARE vsaturday  char(1);
declare vcount int;
DECLARE exit_loop BOOLEAN default FALSE;
declare i int;

declare vfirst_name  varchar(50);
declare vholidayId int;
declare cur cursor for
select emp_pkey,first_name from emp_details where emp_pkey in 
  (select emp_fkey from emp_proff where date_format(joining_date,'%Y-%m-%d') <= vmonthly_att_todate and day_time_seq is not null )
  and emp_pkey=if(pemp_pkey in(null,''),emp_pkey,pemp_pkey) ;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;

open cur;
start_loop: loop
    fetch cur into vemp_pkey,vfirst_name;
   IF exit_loop THEN        LEAVE start_loop;     END IF;
select count(*) into vcount from emp_proff 
  where day_time_seq in(select day_time_seq from working_day_time_procedures where working_time1 > 10) 
  and emp_fkey= vemp_pkey;
if vcount >0 then
select to_days(DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d'))into i;

WHILE i <= to_days(vmonthly_att_todate) DO

insert into emp_detail_attandance_reg (attandance_batch_key,emp_pkey,
att_date, 
yearmonth) values (concat(vemp_pkey,Pyear_month),vemp_pkey,DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d'),Pyear_month );

select i + 1 into i;
END WHILE;
 end if;
end loop start_loop;
 close cur ;

 end BLOCK7;


open att_cur;
att_loop: loop
    fetch att_cur into vemp_pkey,vatt_date;

  IF exit_loop1 THEN
	LEAVE att_loop;
  END IF;

   select DATE_FORMAT(vatt_date,'%d') into nday ;
   


   select min(LOGDATE) into vLOGDATE_intime
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 
 and lcase(c1)='in' and emp_pkey=vemp_pkey and ucase(att.status)='Y'
and date_format(LOGDATE,'%Y-%m-%d') =vatt_date
and (LOGDATE,att.emp_id)
 in (select min(LOGDATE) ,emp_id from device_attandance where date_format(LOGDATE,'%Y-%m-%d') =vatt_date 
  and lcase(c1)='in' and ucase(status)='Y' group by emp_id);
 
 select max(LOGDATE) into vLOGDATE_outime
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 
 and lcase(c1)='out'
and date_format(LOGDATE,'%Y-%m-%d') >=vatt_date and emp_pkey=vemp_pkey and ucase(att.status)='Y'
 and (LOGDATE,att.emp_id) 
 in (select max(LOGDATE) ,emp_id from device_attandance where date_format(LOGDATE,'%Y-%m-%d') >=vatt_date and LOGDATE between vLOGDATE_intime and  vLOGDATE_intime + INTERVAL 1400 MINUTE and lcase(c1)='out' and ucase(status)='Y' group by emp_id);
 
 
 
 
 if vLOGDATE_outime is not null then
 
  BLOCK4:begin
    declare vFIRST_NAME varchar(100);
declare  vINTIME datetime;
declare	vINVAL varchar(30);
declare	vOUTTIME  datetime;
declare	vOUTVAL varchar(30);
DECLARE exit_loop4 BOOLEAN default FALSE;
declare break_cur cursor for
 SELECT
        FIRST_NAME,     EMP_PKEY,       INTIME,     INVAL,
        (CASE WHEN INVAL = 'in' AND OUTVAL = 'in' THEN NULL ELSE OUTTIME END) AS OUTTIME ,
        OUTVAL
FROM
    (
        SELECT 
               MO.C1 AS OUTVAL,       MO.EMP_PKEY,       MO.FIRST_NAME,
               MO.LOGDATE AS OUTTIME,
               @S AS 'LEAD(logdate) over(PARTITION BY emp_pkey ORDER BY logdate)' ,
               @LOGIN := @S AS INTIME,
               @C AS 'LEAD(c1) over(PARTITION BY emp_pkey ORDER BY logdate)',
               @INVAL := @C AS INVAL,
               (CASE WHEN @PARTITION_BY_COLUMN = EMP_PKEY OR @_SEASON IS NULL THEN @S := LOGDATE
                                                                              ELSE @S := NULL
                 END) TMP_VALUE,
               (CASE WHEN @PARTITION_BY_COLUMN = EMP_PKEY OR @_SEASON IS NULL THEN @C := C1
                                                                              ELSE @C := NULL
                 END) TMP_VALUE1,
               (@PARTITION_BY_COLUMN := EMP_PKEY) PARTITION_COLUMN
        FROM 
               (
                  SELECT 
                        ED.EMP_PKEY,    ED.FIRST_NAME,      ATT.LOGDATE,    ATT.C1
                  FROM (SELECT @PARTITION_BY_COLUMN = NULL,
                               @S := NULL,
                               @C := NULL,
                               @LOGIN := NULL,
                               @INVAL := NULL
                       ) VARS, DEVICE_ATTANDANCE ATT, EMP_DETAILS ED
                  WHERE 
                        ATT.EMP_ID = ED.EMP_ID and ucase(att.status)='Y'
                        AND ED.EMP_PKEY = 	vemp_pkey 
                        AND DATE_FORMAT(ATT.LOGDATE,'%Y-%m-%d %T') BETWEEN 
                            DATE_FORMAT(vLOGDATE_intime, '%Y-%m-%d %T') AND DATE_FORMAT(vLOGDATE_outime, '%Y-%m-%d %T')
                ) MO
    ) XX
WHERE INVAL = 'in' AND OUTVAL IN ('in','out' ) ;


  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop4 = TRUE;
 	set vduration=0;
open break_cur ;
start_loop1: loop
    fetch break_cur into vFIRST_NAME,	vEMP_PKEY,	vINTIME,	vINVAL,	vOUTTIME,	vOUTVAL;
   
IF exit_loop4 THEN 
       LEAVE start_loop1 ;   
  END IF;

  if vINTIME is not null and vOUTTIME is not null then
  set vduration=vduration+TIMESTAMPDIFF(Minute, vINTIME,vOUTTIME);
  
  end if;
 
 end loop start_loop1;
 
 close break_cur;
 end BLOCK4;
 
 
 
 


select day_time_seq into vdaytimeId from emp_proff where emp_fkey=vemp_pkey;
   
 select distinct minuts_calc_perday,minutes_per_half
 into vminuts_calc_perday ,vminutes_per_half
   from working_day_time_procedures where day_time_seq=vdaytimeId ;
   
   
   if vduration >= vminuts_calc_perday then 
   set vsetvalue='P/P';
   elseif vduration >= vminutes_per_half then
   set vsetvalue='P/A';
   elseif vduration < vminutes_per_half then
   set vsetvalue='A/A';
   else
   set vsetvalue='A/A';
   end if;
   
 elseif vLOGDATE_outime is null and  vLOGDATE_intime is not null then
   
   set vsetvalue='A/A';
end if;

select count(*) into vemp_count from emp_detail_attandance_reg where emp_pkey=vemp_pkey and att_date=vatt_date and yearmonth=Pyear_month  ;

if vemp_count =0 then
 insert into emp_detail_attandance_reg (emp_pkey,
att_date, 
att_in_time	,	 
att_out_time,	 
duration,present ,yearmonth) values (vemp_pkey,vatt_date ,vLOGDATE_intime,vLOGDATE_outime,vduration,vsetvalue,Pyear_month );
else
update emp_detail_attandance_reg set att_in_time=vLOGDATE_intime,	 
att_out_time=vLOGDATE_outime,	 
duration=vduration,present=vsetvalue
where emp_pkey=vemp_pkey and att_date=vatt_date and yearmonth=Pyear_month  ;
end if;
set vatt_date= null;
set vLOGDATE_intime = null;
set vLOGDATE_outime=null;
set vduration=null;
set vsetvalue=null;
set vminutes_per_half =null;
set vminuts_calc_perday =null;


  end loop att_loop;
close att_cur;

set vatt_date= null;
set vLOGDATE_intime = null;
set vLOGDATE_outime=null;
set vduration=null;

BLOCK2:begin
DECLARE vsunday  char(1);
DECLARE vmonday  char(1);
DECLARE vtuesday  char(1);
DECLARE vwednesday  char(1);
DECLARE vthursday  char(1);
DECLARE vfriday  char(1);
DECLARE vsaturday  char(1);

DECLARE exit_loop BOOLEAN default FALSE;
declare i int;
declare vfirst_name  varchar(50);
declare vholidayId int;
declare cur cursor for
select emp_pkey,first_name from emp_details where emp_pkey in 
 (select emp_fkey from emp_proff where date_format(joining_date,'%Y-%m-%d') <= vmonthly_att_todate and day_time_seq in(select day_time_seq from working_day_time_procedures where working_time1 > 10))
and emp_pkey=if(pemp_pkey in(null,''),emp_pkey,pemp_pkey) ;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;




open cur;
start_loop: loop
    fetch cur into vemp_pkey,vfirst_name;
   IF exit_loop THEN        LEAVE start_loop;     END IF;

select HOLIDAY_GROUP_ID,day_time_seq into vholidayId ,vdaytimeId from emp_proff where emp_fkey=vemp_pkey;

 select sunday,  monday,  tuesday,  wednesday,  thursday  ,  friday,  saturday
 into vsunday,  vmonday,  vtuesday,  vwednesday,  vthursday  ,  vfriday,  vsaturday 
   from working_day_time_procedures where day_time_seq=vdaytimeId ;

 
select to_days(DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d'))into i;

WHILE i <= to_days(vmonthly_att_todate) DO
if vsunday='N' then
 if WEEKDAY(FROM_DAYS(i))=6 then

