 select HOLIDAYDATE from holidays where HOLIDAY_GROUP_ID=vholidayId 
  and HOLIDAYDATE  between DATE_FORMAT(vmonthly_att_fromdate , '%Y-%m-%d') and vmonthly_att_todate;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop3 = TRUE;
open holidaycur ;
