BLOCK4:begin
declare vleave_value varchar(20);
declare vleave_date date;
declare vleave_session int;
declare vsalary_head_item_fkey int;
declare vleaveshort varchar(20);
DECLARE exit_loop BOOLEAN default FALSE;
declare leavecur cursor for
select elt.leave_date,elt.leave_session,l.salary_head_item_fkey
          from emp_leave_transactions elt join leaveentries l on(elt.LEAVEENTRYID = l.LEAVEENTRYID)
where elt.Leavestatus in('Authorized','Approved')
    and DATE_FORMAT(elt.leave_date, '%Y-%m-%d') 
   between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d') 
   and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d') and l.EMP_fkey=vemp_pkey ;
 
	
	

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;


open leavecur ;
start_loop5: loop
    fetch leavecur into vleave_date ,vleave_session,vsalary_head_item_fkey ;
   IF exit_loop THEN        LEAVE start_loop5;     END IF;

   select ifnull(occurance,'LOP') leaveshort into vleaveshort
     from salary_head_items where  salary_head_item_pkey=vsalary_head_item_fkey ;

	 if vleave_session=3 then 
	     set vleave_value =concat(ucase(vleaveshort),'/',ucase(vleaveshort));
	 elseif vleave_session=2 then 
         set vleave_value= concat('A/',ucase(vleaveshort));
     elseif vleave_session=1 then 
         set vleave_value= concat(ucase(vleaveshort),'/A');		 
	 end if;


 select count(*) into vemp_count from emp_detail_attandance_reg where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(vleave_date ,'%Y-%m-%d') and yearmonth=Pyear_month  ;
if vemp_count =0 then
 insert into emp_detail_attandance_reg (emp_pkey,att_date,leaves,yearmonth) values (vemp_pkey,DATE_FORMAT(vleave_date ,'%Y-%m-%d'),vleave_value ,Pyear_month );
else
update emp_detail_attandance_reg set leaves=vleave_value where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(vleave_date ,'%Y-%m-%d') and yearmonth=Pyear_month  ;
end if;

end loop start_loop5;
 
close leavecur ;



end BLOCK4;

  BLOCK6:begin
declare vb4joinindate int;
declare nday date;
DECLARE exit_loop6 BOOLEAN default FALSE;
declare joiningdate_cur cursor for   
  select emp_fkey,joining_date from emp_proff
 where date_format(joining_date,'%Y-%m-%d') between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d')
 and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d')
 and emp_fkey in (select emp_fkey from emp_proff where joining_date  is not null and day_time_seq in(select day_time_seq from working_day_time_procedures where working_time1 > 10)) and emp_fkey=if(pemp_pkey in(null,''),emp_fkey,pemp_pkey);

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop6 = TRUE;

open joiningdate_cur ;
    fetch joiningdate_cur into vemp_pkey,vatt_date;
  

select to_days(DATE_FORMAT(vmonthly_att_fromdate , '%Y-%m-%d'))into i;
select to_days(DATE_FORMAT(vatt_date, '%Y-%m-%d'))into vb4joinindate ;

WHILE i < vb4joinindate DO

  select DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') into nday;

select count(*) into vemp_count from emp_detail_attandance_reg where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(nday,'%Y-%m-%d') and yearmonth=Pyear_month  ;
if vemp_count =0 then
 insert into emp_detail_attandance_reg (emp_pkey,att_date,others,yearmonth) values (vemp_pkey,DATE_FORMAT(nday,'%Y-%m-%d'),'NA',Pyear_month );
else
update emp_detail_attandance_reg set others='NA' where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(nday,'%Y-%m-%d') and yearmonth=Pyear_month  ;
end if;


   select i + 1 into i;
END WHILE;
   
  close joiningdate_cur;
  end BLOCK6;
  
 
end loop start_loop;
 close cur ;
 end BLOCK2;

return concat(vemp_pkey,Pyear_month);

end;;

DROP FUNCTION IF EXISTS `profession_tax_cal_fn`;;
CREATE FUNCTION `profession_tax_cal_fn` (`pemp_fkey` int, `pmonth_year` varchar(30)) RETURNS int(11) LANGUAGE SQL
begin
declare vreturn int;
declare i int;
declare vworking_time int ;
declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
declare vholidayId int;
declare vdaytimeId int;
declare vHOLIDAYDATE  date;
DECLARE l_sql VARCHAR(4000);
DECLARE nday int;
DECLARE yearmonth varchar(30);
DECLARE vworking_days  int;
DECLARE vatt_date  date;

DECLARE vsunday  char(1);
DECLARE vmonday  char(1);
DECLARE vtuesday  char(1);
DECLARE vwednesday  char(1);
DECLARE vthursday  char(1);
DECLARE vfriday  char(1);
DECLARE vsaturday  char(1);
DECLARE vholicnt  int;
DECLARE vholicnt1  int;
DECLARE linfocnt int;
DECLARE vleave_for_thyear int;
DECLARE vleave_forthe_month int;
DECLARE vremainlve_for_thyear int;
DECLARE vremainlve_forthe_month int;
DECLARE vissandwich char(1);
declare vYdays int;
declare vNdays int;
declare vALLOW_NEGETIVE char(1);
declare vweekoffstring varchar(100);
declare vsalary_head_item_fkey int;
declare vexistcount int;
declare vfullcnt int;
declare vhalfcnt int;
declare vleavecnt int;
declare vleaveexistcnt int;
declare vemp_leave_infocnt int;
declare vfin_year  int;
declare vdistribution_cnt int;
declare vemp_anual_ctc  float;
declare vemp_monthly_ctc  float;
declare vemp_balance_ctc  float;
declare vstructure_name varchar(100);
declare vprorate_code varchar(100);
declare vprorate_desc varchar(100);
declare vdefined_structure_for varchar(100);
declare vstructure_det_operator varchar(100);
declare vstructure_det_value float;
declare vstructure_derived_perc double;
declare vstructure_det_depends float;
declare vvalue float;
declare vstructure_id int;
declare vsalary_head_item_desc varchar(100);
declare vformula_value float;
declare rem_salary_head_item_fkey int;
declare vdedcount int;
declare vhead_operator varchar(30);
declare vhead_type varchar(30);
declare vitem_part varchar(30);
declare vcount int;
declare vtax_salary_components_pkey int; 
declare vtax_salary_components_name varchar(100);
declare vhra1 float;
declare vhra2 float;
declare vhra3 float;
declare vavailed_salary float;
declare vtaxable_salary float ;
declare vupper_limit float;
declare vtaxable_income float;
declare vtax_heads_limitsum float;
declare vtax_yearly float;
declare vtax_monthly float;
declare vother_income float;
declare vfirst_portion float;
declare vsecond_portion float;
declare vthird_portion float ;
declare vhradeclared float;
declare vtaxable_salary1 float;
declare vtax_head_value  float;
declare vtax_heads_limit   float;
declare vtax_heads_fkey int;
declare vtax_heads_details_fkey int;
declare vtax_head_detail_value float ;
declare vtax_head_detail_limit  float;
declare vtax_head_detail_balsum float;
declare vtaxsumcount int;
declare vstart_month date ;
declare vend_month date;
declare vactaul_salary float;
declare vproj_count int;
declare vactual_salary_recd float;
declare vprojected_salary float;
declare vbaselimit float;
declare vclassification varchar(20);
declare vsumprojected_salary float;
declare vtaxdeducted_sum float;
declare vsumactual_salary_recd float;
declare vactual_count int;
declare vjoining_date date;
declare vtotalmonth int;
declare vtax_heads_totsum float;
declare vsurcharge float;
declare  vcess  float;
declare  vrebate float;
declare vnewtaxable_income float;
declare vstanderd_deduction float;
declare vpt_deducted int;
declare vtax_half_yearly int;
declare voccurance int;
declare vstart_from int;
declare vbalance_month int;
declare vmonth date;
declare vno_pt int;
declare vstate varchar(50);
declare vavailed_salary1 float;
declare vemp_type varchar(20);
declare vday_time_seq int;
DECLARE vweeokoff float;
declare vdays int;
DECLARE exit_loop BOOLEAN default FALSE;

 select  start_month,end_month into vstart_month,vend_month  from  fin_year where  vattr1=1
    and is_current_finyear='Y' and status=1 and year_status='OPEN'
		   and branch_code= (select branch_code from emp_details where emp_Pkey=Pemp_fkey );
		   
select count(no_pt) into vno_pt from branch_exceptions where branch_code in  
                      (select branch_code from emp_details where emp_Pkey=Pemp_fkey ) and no_pt='Y'; 
select upper(ifnull(state,'KERALA')) into vstate from branches  where branch_code in  
                      (select branch_code from emp_details where emp_Pkey=Pemp_fkey ) limit 1;						  
if vno_pt=0 then				  
		   
if substr(pmonth_year,6,2) <='09' and substr(pmonth_year,6,2) >'03' then	   
	set vend_month=  last_day(DATE_ADD(vstart_month, INTERVAL 5 MONTH)) ;
	else
    set vstart_month=   DATE_ADD(vstart_month, INTERVAL 6 MONTH) ; 
	set vend_month= vend_month;
 end if;
 
 
	select salary_head_item_Fkey into vsalary_head_item_Fkey  from tax_salary_components where ucase(tax_salary_components_name)='PROFESSIONAL TAX';
	select occurance,	start_from	  into voccurance,vstart_from  from salary_head_items where salary_head_item_pkey=vsalary_head_item_Fkey;
	
	select date_format(joining_date,'%Y-%m-%d'),emp_type,day_time_seq into vjoining_date,vemp_type,vday_time_seq from emp_proff  where emp_fkey=Pemp_fkey;	
	
	select working_days into vworking_days  from payroll_master where emp_fkey= Pemp_fkey and month_year= pmonth_year;
	
	if vjoining_date > vstart_month then
	  
	set vtotalmonth= TIMESTAMPDIFF(MONTH,vjoining_date, vend_month)+1;
	
		else 
	set vtotalmonth= TIMESTAMPDIFF(MONTH,vstart_month, vend_month)+1;
		
	end if;
	
	select count(distinct month_year) into vactual_count from emp_salary_slip where  
    emp_fkey=Pemp_fkey and end_date_effective is null and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	
    and head_operator<>'Deduction' and item_part <> 'Indirect'  ;	 
	
  if ucase(vstate)='TELANGANA' THEN
     select  sum(abs(salary_amount)) into vactaul_salary from emp_salary_slip where emp_fkey=Pemp_fkey 
     and end_date_effective is null and month_year=pmonth_year 
     and head_operator<>'Deduction' and item_part <> 'Indirect' 
	 and salary_head_item_Fkey in (select salary_head_item_Fkey from emp_salary_structure where emp_fkey=Pemp_fkey  and end_date_effective is null and head_operator<>'Deduction' 
	and end_date_effective is null and item_part <> 'Indirect'
	and salary_head_item_Fkey not in (select salary_head_item_Fkey from tax_salary_components where tax_salary_components_pkey in(2,5,19,20) ));
	 
	
    set vavailed_salary1= vactaul_salary;
	
	set vprojected_salary=0;
	set vpt_deducted=0;
	select  ifnull(min(tax_half_yearly),0) into vtax_half_yearly from profession_tax_slab 
	where salary_range_to >=vactaul_salary and state=vstate
         and date_format(concat(pmonth_year,'-01'),'%Y-%m-%d')  
	 between IFNULL(DATE_ADD(date_format(start_date_effective,'%Y-%m-%d') , INTERVAL -1 DAY),DATE_ADD(date_format(concat(pmonth_year,'-01'),'%Y-%m-%d'), INTERVAL +1 DAY))
         AND IFNULL(date_format(end_date_effective,'%Y-%m-%d'), DATE_ADD(date_format(concat(pmonth_year,'-01'),'%Y-%m-%d'), INTERVAL +1 DAY));	
	set vreturn=vtax_half_yearly;
  else
  select  sum(abs(salary_amount)) into vactaul_salary from emp_salary_slip where emp_fkey=Pemp_fkey 
     and end_date_effective is null and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')	
     and head_operator<>'Deduction' and item_part <> 'Indirect' 
	 and salary_head_item_Fkey in (select salary_head_item_Fkey from emp_salary_structure where emp_fkey=Pemp_fkey  and end_date_effective is null and head_operator<>'Deduction' 
	and end_date_effective is null and item_part <> 'Indirect'
	and salary_head_item_Fkey not in (select salary_head_item_Fkey from tax_salary_components where tax_salary_components_pkey in(3,4,5) ));
	 
	  set vavailed_salary1= vactaul_salary;
  if upper(vemp_type)='DAILY WAGES' then
      select  weekoff_days_count_fn(Pemp_fkey, concat(pmonth_year,'-01'), concaT(vend_month,'-30')) into vweeokoff ;
	 
	set vdays=(((ifnull(vtotalmonth,0)-ifnull(vactual_count,0))*30)-ifnull(vweeokoff,0));
	 	
	 select ifnull(round(sum(structure_det_value)),0)*vdays into vprojected_salary
     from emp_salary_structure where emp_fkey=Pemp_fkey  and end_date_effective is null and head_operator<>'Deduction' 
	and end_date_effective is null and item_part <> 'Indirect' 
	and salary_head_item_Fkey not in (select salary_head_item_Fkey from tax_salary_components where tax_salary_components_pkey in(3,4,5) );
      
   else   
   select ifnull(round(sum(structure_det_value)),0)*(ifnull(vtotalmonth,0)-ifnull(vactual_count,0)) into vprojected_salary
     from emp_salary_structure where emp_fkey=Pemp_fkey  and end_date_effective is null and head_operator<>'Deduction' 
	and end_date_effective is null and item_part <> 'Indirect' 
	and salary_head_item_Fkey not in (select salary_head_item_Fkey from tax_salary_components where tax_salary_components_pkey in(3,4,5) )
	and salary_head_item_Fkey in (select salary_head_item_pkey from salary_head_items where head_fkey=1);
	end if;
	set vactaul_salary=ifnull(vactaul_salary,0)+ifnull(vprojected_salary,0);	
	
	   select  ifnull(sum(abs(salary_amount)),0) into vpt_deducted from emp_salary_slip where salary_head_item_Fkey=vsalary_head_item_fkey 
    and emp_fkey=Pemp_fkey and end_date_effective is null and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	 and payroll_master_fkey in (select payroll_master_pkey from payroll_master where action in ('Approved','Processed'));
	 
	 
	select  ifnull(min(tax_half_yearly),0) into vtax_half_yearly from profession_tax_slab 
	where salary_range_to >=vactaul_salary and state=ifnull(vstate,'KERALA')
         and date_format(concat(pmonth_year,'-01'),'%Y-%m-%d')  
	 between IFNULL(DATE_ADD(date_format(start_date_effective,'%Y-%m-%d') , INTERVAL -1 DAY),DATE_ADD(date_format(concat(pmonth_year,'-01'),'%Y-%m-%d'), INTERVAL +1 DAY))
         AND IFNULL(date_format(end_date_effective,'%Y-%m-%d'), DATE_ADD(date_format(concat(pmonth_year,'-01'),'%Y-%m-%d'), INTERVAL +1 DAY));	

	set vmonth=concat(pmonth_year,'-01');
	if ifnull(vtax_half_yearly,0) > ifnull(vpt_deducted,0) then
	if voccurance='Monthly' then
	set vbalance_month=(ABS(TIMESTAMPDIFF(MONTH,vmonth, vend_month))+1);
	
	set vreturn= (ifnull(vtax_half_yearly,0)-ifnull(vpt_deducted,0))/vbalance_month; 
 
	elseif voccurance='Half Yearly' then
	if date_format(vstart_from,'%Y-%m')=date_format(pmonth_year,'%Y-%m') then
	  set vreturn= ifnull(vtax_half_yearly,0)-ifnull(vpt_deducted,0); 
	end if;
	
	elseif voccurance='Yearly' then
		
  set vreturn= ifnull(vtax_half_yearly,0)-ifnull(vpt_deducted,0); 
  
  end if;
  end if;
  end if;
  
  update emp_pt_details set end_date_effective=CURRENT_TIMESTAMP where month_year=pmonth_year ;
  
  insert into emp_pt_details(emp_fkey,state1,month_year,start_month,end_month,month_count,availed_salary,projected_salary,total_salary,pt_deducted,tax_half_yearly,balance_month,balance_pt)
    values(Pemp_fkey,vstate,pmonth_year,vstart_month,vend_month,vtotalmonth,vavailed_salary1,vprojected_salary,vactaul_salary,vpt_deducted,vtax_half_yearly,vbalance_month,vreturn);
  
  else
  set vreturn=0 ;
  end if;
if vreturn > 0 then
return vreturn ;
else
return 0;
end if;
end;;

DROP PROCEDURE IF EXISTS `salary_process_prc`;;
CREATE PROCEDURE `salary_process_prc` (IN `pmonth` varchar(20), IN `pbranch_code` varchar(30), IN `pemp_pkey` int(11), IN `ppayroll_master_pkey` int(11), IN `puser_id` varchar(30), OUT `perr_msg` varchar(2000))
begin

declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vDeviceId int;
declare vjoining_date	  date;
declare vemp_company_id	varchar(30);	 
declare vemp_type	varchar(30);	 
declare vdesignation	varchar(30); 
declare vemp_dept	varchar(30);
declare vemp_grade	varchar(30);
declare vemp_vertical   varchar(30);
declare vemp_branch varchar(30);	 
declare vHOLIDAY_GROUP_ID int;	 
declare vLEAVEPOLICY_GROUP_ID int;
declare vday_time_seq  int;
declare vpresant_total float;
declare vleave_total float;
declare vlop_total float;
declare vemp_anual_ctc float;
declare vemp_monthly_ctc float ;
declare vemp_structure_id int ;
declare vprorate_code int;
declare vprorate_desc varchar(50);
declare vdefined_structure_for varchar(50);
declare vsalary_head_item_fkey int;
declare vsalary_head_item_desc varchar(100);
declare vstructure_det_value float;
declare vhead_operator varchar(20);
declare vhead_type varchar(25);
declare vitem_part varchar(25);
declare vstructure_id int;
declare vemp_salary float;
declare vday_count float ;
declare vattendance_date date;
declare vmonthly_att_fromdate date;
declare vmonthly_att_todate date;
declare vworking_day float;
declare vweekoff_day float;
declare vexistcount int;
declare vmonthly_amount float;
declare vindirect_amount float;
declare vtotal_deduction float;
declare vtotal_variables float;
declare vmonth date;
declare vrate float;
declare vholiday_count  float;
declare vot_duration float;
declare vactual_presant_days float;
declare v_holiday_woff_count float;
declare v_holiday_halfwoff_count float;
declare vshift_allowance int;
declare votcomponents int;
declare vweekoff_total float;
declare vholiday_total float;
declare vfixed_days float;
declare vcompany_code varchar(25);
DECLARE exit_loop BOOLEAN default FALSE;
declare vemp_monthly_ctc1 float;
declare vproff_tax int;
declare vfinyear int;
declare vtds float;
declare vtaxable_income float;
declare vtax_include varchar(10);
declare vtax float;
declare vpftax_components int;
declare vpf_count int;
declare vLOPonweekoffs float;
declare vweekoff_count float;
declare vhalfweekoff_count float;
declare vLeavesonweekoffs float;
declare vLOPonHolidays float;
declare vLeavesonHolidays float;
declare vuploaded_amount int;
declare rec_count int;
declare voperator  varchar(10);
declare vsalaryamount float;
declare vapproved_days float;
declare vapproved_count int;
declare vleaveencashmentkey int;
declare vwork_time_day_off_cal_ot int;
declare vstart_month date ;
declare vend_month  date;
declare vsunday float;
declare vmessage varchar(100);
declare vworking_time1 varchar(30);
declare vworking_time2 varchar(30); 
declare vminuts_calc_perday varchar(30);
declare vdaytotal float;
declare vleavetotal float; 
declare vfullcnt float;
declare vhalfcnt float;
declare vleave_salary float;
declare vtotal_hours float;
declare vduration float;
declare vsunday_allowance int;
declare voption_type varchar(10);
declare vdesignations	varchar(100); 
declare vemp_depts	varchar(100);
declare vemp_grades	varchar(100);
declare vemp_verticals   varchar(100);
declare vemp_branchs varchar(100);	
declare vemp_sections  varchar(100);
declare vemp_sep_priv  int;	
declare vvertical_name varchar(100);	
declare voccurance int;
declare vstart_date_effective date;
declare	vend_date_effective	date;	  
declare vaddition_dty float;
declare vsubdomain varchar(50);
declare vpayroll_type varchar(10);
declare vcalander_days int;
declare vmonth_yr date;
declare veps varchar(30);
declare vprobation int;
declare vcontract_start_date  date ;
declare vcontract_end_date  date;
declare vpay_scale varchar(50);
declare vcategory_name varchar(50);				   

declare cur cursor for
select distinct ed.emp_pkey,concat(ed.first_name,' ',ed.last_name) empname ,
ep.joining_date	,  
ep.emp_company_id	,	 
ep.emp_type	,	 
ep.designation	,	 
ep.emp_dept	,
ep.emp_grade	, 
ep.emp_vertical,	 
ep.emp_branch	,	 
ep.HOLIDAY_GROUP_ID,	 
ep.LEAVEPOLICY_GROUP_ID,	 
ep.day_time_seq ,
ep.structure_id,emp_sep_priv   from emp_details ed,emp_proff ep 
 where ed.Branch_code=pBranch_code and ed.Branch_code=ep.emp_branch and ed.emp_pkey=pemp_pkey
 and ed.emp_pkey=ep.emp_fkey and status=1 and ed.emp_pkey in (select emp_fkey from attendance_register 
	       where month_year=pmonth and isdelete= 'N');

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;

 select branch,designation,department,grade,joining_date into vemp_branchs,vdesignations,vemp_depts,vemp_grades,vjoining_date  
			   
 from employee_info where emp_pkey=pemp_pkey;
 select eps into veps from emp_details where emp_pkey=pemp_pkey;
 select attr2 into vprobation from emp_proff where emp_fkey=pemp_pkey;
 select count(*) into rec_count from contracted_days where emp_fkey=pemp_pkey;
 if (rec_count != 0) then
 select contract_start_date,contract_end_date into vcontract_start_date,vcontract_end_date from contracted_days where emp_fkey=pemp_pkey;
end if;


open cur;
start_loop: loop
    fetch cur into vemp_pkey,vfirst_name , vjoining_date,	
vemp_company_id,
vemp_type	,	
vdesignation	,
vemp_dept	,
vemp_grade	, 
vemp_vertical,	
vemp_branch	,	
vHOLIDAY_GROUP_id ,
vLEAVEPOLICY_GROUP_ID ,
vday_time_seq ,vstructure_id,vemp_sep_priv;
IF exit_loop THEN
        LEAVE start_loop;
     END IF;
    
   select section_name into vemp_sections from section where id=vemp_sep_priv; 
  select vertical_name into vvertical_name from verticals where vert_code=  vemp_vertical ;
	select presant_total,leave_total,lop_total,weekoff_total,holiday_total 
	into vpresant_total,vleave_total,vlop_total,vweekoff_total,vholiday_total from attendance_register 
	       where emp_fkey=vemp_pkey and month_year=pmonth and isdelete= 'N' ;
	
	SELECT att_start_end_fn(DATE_FORMAT(concat(pmonth,'-01'), '%Y-%m-01'), 1) into vmonthly_att_fromdate;
	SELECT att_start_end_fn(DATE_FORMAT(concat(pmonth,'-01'), '%Y-%m-01'), 2) into vmonthly_att_todate; 
	
	set vactual_presant_days=vpresant_total;
		if upper(vemp_type)='DAILY WAGES' then 
		select emp_derived_anualctc ,emp_anual_ctc into vemp_anual_ctc,vemp_monthly_ctc  
		    from  emp_ctc_transaction  where emp_fkey=vemp_pkey and end_date_effective is null;
		 set vemp_monthly_ctc=vemp_monthly_ctc*vpresant_total;
	     set vemp_monthly_ctc1=vemp_monthly_ctc*vpresant_total;
		 
		 elseif upper(vemp_type)='HOURLY WAGES' then
		 
		 select working_time1,working_time2 ,minuts_calc_perday into vworking_time1,vworking_time2 ,vminuts_calc_perday   from  working_day_time_procedures
	            where day_time_seq in (select day_time_seq from emp_proff where emp_fkey=vemp_pkey);
				
			if vworking_time2 >0 then
            set vdaytotal= (vworking_time1 + vworking_time2)/60;
            else
       		set vdaytotal= vworking_time1/60;
            end if;
 			select count(*) into vfullcnt from emp_leave_transactions where leave_session=3 and  Remarks!='No need Leave'
                          and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where emp_fkey=vemp_pkey and leavestatus in ('Approved','Authorized')
						  and salary_head_item_fkey not in(SELECT salary_head_item_pkey FROM `salary_head_items` WHERE head_fkey in(select head_pkey from  salary_heads where 
                          lcase(item_type)='leave' and value='Y' and status=1) and occurance = 'LOP'))
						  and leave_date between vmonthly_att_fromdate  and vmonthly_att_todate  ;

           select count(*)*.5 into vhalfcnt from emp_leave_transactions where leave_session!=3 and Remarks!='No need Leave'
                         and LEAVEENTRYID in (select LEAVEENTRYID from leaveentries where emp_fkey=vemp_pkey and leavestatus in ('Approved','Authorized')
						 and salary_head_item_fkey not in(SELECT salary_head_item_pkey FROM `salary_head_items` WHERE head_fkey in(select head_pkey from  salary_heads where 
                          lcase(item_type)='leave' and value='Y' and status=1) and occurance = 'LOP'))
						 and leave_date between vmonthly_att_fromdate  and vmonthly_att_todate ;
		  			 
			set vleavetotal= vfullcnt+vhalfcnt;			  
        select emp_derived_anualctc,emp_anual_ctc into vemp_anual_ctc,vemp_monthly_ctc  
		    from  emp_ctc_transaction  where emp_fkey=vemp_pkey and end_date_effective is null;
			
		set vleave_salary=(ifnull(vleavetotal,0)*ifnull(vdaytotal,0))*vemp_monthly_ctc;	
		
		select (sum(duration)/60) into vduration from emp_detail_timeattandance 
		  where emp_pkey = vemp_pkey and yearmonth = DATE_FORMAT(concat(pmonth,'-01'), '%Y-%m-01') ;
		  set vtotal_hours= ifnull(vduration,0)+(ifnull(vleavetotal,0)*ifnull(vdaytotal,0));
		  set vemp_monthly_ctc=vduration*vemp_monthly_ctc;
		  set vemp_monthly_ctc=ifnull(vemp_monthly_ctc,0)+vleave_salary;
		  set vemp_monthly_ctc1=vemp_monthly_ctc;
		  
		
		SELECT site_sal_structure_distribution_fn(pBranch_code, vemp_pkey, vstructure_id, vemp_monthly_ctc,puser_id) into vmessage;
		else
		 select emp_derived_anualctc ,emp_anual_ctc/12 into vemp_anual_ctc,vemp_monthly_ctc  from  emp_ctc_transaction  where emp_fkey=vemp_pkey and end_date_effective is null;
		  set vemp_monthly_ctc1=vemp_monthly_ctc;
	   end if ;
 
 BLOCK2:begin
DECLARE exit_loop3 BOOLEAN default FALSE;
declare structurecur cursor for
 select emp_fkey,emp_structure_id,prorate_code,prorate_desc,defined_structure_for,	 
salary_head_item_fkey,salary_head_item_desc,structure_det_value,head_operator,head_type	,item_part from emp_salary_structure 
  where emp_fkey=vemp_pkey and end_date_effective is null 
  and salary_head_item_Fkey in (select salary_head_item_pkey  from salary_head_items where head_fkey in 
   (select head_pkey from  salary_heads where head_pkey not in (2)) );
  
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop3 = TRUE;
  select count(*) into vexistcount from emp_salary_slip where emp_fkey=vemp_pkey and month_year=pmonth;
  
  select distinct attendance_date into vattendance_date
								   from db_config where active='Y';
  
	  
	  set vweekoff_day= vweekoff_total;
      set vholiday_count=	vholiday_total;	
  
	  
  set vworking_day = (DATEDIFF(vmonthly_att_todate,vmonthly_att_fromdate)+1)-(vweekoff_day+vholiday_count) ;
  update payroll_master set working_days=vworking_day
                where payroll_master_pkey=ppayroll_master_pkey and emp_fkey=vemp_pkey and month_year=pmonth ;
  
		 
  if vexistcount >0 then
    update emp_salary_slip set end_date_effective=current_date  where emp_fkey=vemp_pkey and month_year=pmonth;
  end if;	
  
   
open structurecur ;
start_loop1: loop
    fetch structurecur into vemp_pkey,vemp_structure_id,vprorate_code,vprorate_desc,vdefined_structure_for,	 
vsalary_head_item_fkey,vsalary_head_item_desc,vstructure_det_value,vhead_operator,vhead_type	,vitem_part;
   
IF exit_loop3 THEN 
       LEAVE start_loop1 ;   
  END IF;
  
  if upper(vemp_type)='DAILY WAGES' then 
    set vrate=vemp_monthly_ctc;
	if lcase(vhead_type)!='fixed' then    
    set vemp_salary=(vstructure_det_value) * (vpresant_total+ vleave_total) ; 
    else
     set vemp_salary=vstructure_det_value ; 
    end if;	
	insert into emp_salary_slip (payroll_master_fkey,emp_fkey,	 
			month_year	,	 
			salary_head_item_fkey	,
			salary_head_item_desc,
			structure_det_value	,
			salary_rate	,salary_amount ,	 
			presant_total,	 
			leave_total	,
			lop_total	,
			head_operator,
			head_type,
			item_part,action) values(ppayroll_master_pkey,vemp_pkey,pmonth ,vsalary_head_item_fkey,vsalary_head_item_desc,(vstructure_det_value/vpresant_total),vstructure_det_value,vemp_salary, vactual_presant_days,vleave_total,vlop_total,vhead_operator,vhead_type	,vitem_part,'P');
			
	 elseif upper(vemp_type)='HOURLY WAGES' then
    
     set vemp_salary=vstructure_det_value ; 
   	if  lcase(vhead_type)!='fixed'  then
	insert into emp_salary_slip (payroll_master_fkey,emp_fkey,	 
			month_year	,	 
			salary_head_item_fkey	,
			salary_head_item_desc,
			structure_det_value	,
			salary_rate	,salary_amount ,	 
			presant_total,	 
			leave_total	,
			lop_total	,
			head_operator,
			head_type,
			item_part,action) values(ppayroll_master_pkey,vemp_pkey,pmonth ,vsalary_head_item_fkey,vsalary_head_item_desc,(vstructure_det_value/vtotal_hours),vstructure_det_value,vemp_salary, vactual_presant_days,vleave_total,vlop_total,vhead_operator,vhead_type	,vitem_part,'P');
    else
    insert into emp_salary_slip (payroll_master_fkey,emp_fkey,	 
			month_year	,	 
			salary_head_item_fkey	,
			salary_head_item_desc,
			structure_det_value	,
			salary_rate	,salary_amount ,	 
			presant_total,	 
			leave_total	,
			lop_total	,
			head_operator,
			head_type,
			item_part,action) values(ppayroll_master_pkey,vemp_pkey,pmonth ,vsalary_head_item_fkey,vsalary_head_item_desc,vemp_salary,vstructure_det_value,vemp_salary, vactual_presant_days,vleave_total,vlop_total,vhead_operator,vhead_type	,vitem_part,'P');
    end if;
	
  else
  
   select shift_allowance,otcomponents into vshift_allowance,votcomponents   from  working_day_time_procedures
	            where day_time_seq in (select day_time_seq from emp_proff where emp_fkey=vemp_pkey);
		 select distinct company_code into vcompany_code  from branches where branch_code=pbranch_code LIMIT 1;	
		 


  if  lcase(vhead_type)!='fixed'  then
   if vprorate_code=3 then  
  
    set vday_count =vweekoff_day;
   set vworking_day = (DATEDIFF(vmonthly_att_todate,vmonthly_att_fromdate)+1)-(vday_count+vholiday_count) ;
   if vpresant_total+vleave_total>vworking_day then
     set vpresant_total=vworking_day;
    end if;	

 	 if vcompany_code='TGPC'  then 
	   set vfixed_days=26;
	 else 
        set vfixed_days=30;	 
	 end if;
	 
    if vpresant_total>vfixed_days then
     set vpresant_total=vfixed_days;
    end if;		
	
    set vrate= vpresant_total+vleave_total;	   
    set vemp_salary=(vstructure_det_value/vfixed_days) * vrate ;
  
    elseif vprorate_code= 2 then  
		
             set vday_count =vweekoff_day;
			
			set vworking_day = (DATEDIFF(vmonthly_att_todate,vmonthly_att_fromdate)+1)-(vday_count+vholiday_count) ;
			if vpresant_total+vleave_total>vworking_day then
			set vpresant_total=vworking_day;
			
			 set vemp_salary=(vstructure_det_value/vworking_day) * (vpresant_total) ;
			 
			 
			 elseif vpresant_total+vleave_total<=vworking_day then
			 set vemp_salary=(vstructure_det_value/vworking_day) * (vpresant_total+vleave_total) ;
			
			end if;
			
	 elseif vprorate_code= 1 then  

		 select distinct attendance_date into vattendance_date
								   from db_config where active='Y';
	 
		  
    set vday_count = DATEDIFF(vmonthly_att_todate,vmonthly_att_fromdate)+1  ;
	set vworking_day = (DATEDIFF(vmonthly_att_todate,vmonthly_att_fromdate)+1)-(vweekoff_total+vholiday_count);
	if vpresant_total>vworking_day then
     set vpresant_total=vworking_day;
    end if;

		  
	  set vrate=vpresant_total+vleave_total+vweekoff_total+vholiday_count;
	  	 	
	 set vemp_salary=(vstructure_det_value/vday_count) * vrate ; 	  	 
	 
    end if;
	
	
	  select shift_allowance,otcomponents ,work_time_day_off_cal_ot into vshift_allowance,votcomponents,vwork_time_day_off_cal_ot   from  working_day_time_procedures
	            where day_time_seq in (select day_time_seq from emp_proff where emp_fkey=vemp_pkey);
				
		
			
	  if lcase(vsalary_head_item_desc) ='sunday allowance'  then		
	  
	    if vwork_time_day_off_cal_ot=4 then
	  
	   select start_month, end_month into vstart_month ,vend_month   from fin_year 
	      where Year_status='OPEN' and is_current_finyear='Y'  and vattr1=0 and status = 1 
		  and branch_code = (select branch_code from emp_details where emp_pkey=vemp_pkey) ;
	   
	      select sum(v1) into vsunday from (
						select count(*) v1 from
                        emp_detail_timeattandance where weekoff is not null and present='P/P'
                        and yearmonth =DATE_FORMAT(concat(pmonth,'-01'), '%Y-%m-01') and emp_pkey = vemp_pkey
						union all
						select count(*)*.5 v1 from
                        emp_detail_timeattandance where weekoff is not null and present in('P/A','A/P')
                        and yearmonth =DATE_FORMAT(concat(pmonth,'-01'), '%Y-%m-01') and emp_pkey = vemp_pkey
                        ) a; 
		
		else
		 set vsunday =0;
		end if; 
  
	   if vsunday >0 then
         set vemp_salary = vstructure_det_value*vsunday;
		 set vemp_salary=vemp_salary;
												 
		 else 
		 set vemp_salary =0;
		 set vstructure_det_value=0;
         end if;
		 
	  end if;
	 if lcase(vsalary_head_item_desc) ='sunday or holiday allowance' then
 
       	 if vwork_time_day_off_cal_ot=5 then
	  
	   select start_month, end_month into vstart_month ,vend_month   from fin_year 
	      where Year_status='OPEN' and is_current_finyear='Y'  and vattr1=0 and status = 1 
		  and branch_code = (select branch_code from emp_details where emp_pkey=vemp_pkey) ;
	   
	      select sum(v1) into vsunday from (
						select count(*) v1 from
                        emp_detail_timeattandance where weekoff is not null and present='P/P'
                        and yearmonth =DATE_FORMAT(concat(pmonth,'-01'), '%Y-%m-01') and emp_pkey = vemp_pkey
						union all
						select count(*)*.5 v1 from
                        emp_detail_timeattandance where weekoff is not null and present in('P/A','A/P')
                        and yearmonth =DATE_FORMAT(concat(pmonth,'-01'), '%Y-%m-01') and emp_pkey = vemp_pkey
						union all
						select count(*) v1 from
                        emp_detail_timeattandance where holiday is not null and present='P/P'
                        and yearmonth =DATE_FORMAT(concat(pmonth,'-01'), '%Y-%m-01') and emp_pkey = vemp_pkey
						union all
						select count(*)*.5 v1 from
                        emp_detail_timeattandance where holiday is not null and present in('P/A','A/P')
                        and yearmonth =DATE_FORMAT(concat(pmonth,'-01'), '%Y-%m-01') and emp_pkey = vemp_pkey
                        ) a; 
		
		else
		 set vsunday =0;
		end if; 
	    
 
		if vsunday >0 then
         set vemp_salary = vstructure_det_value*vsunday;
		 set vemp_salary=vemp_salary;
												  
		 else 
		 set vemp_salary =0;
		 set vstructure_det_value=0;
         end if;
		 
	  end if;  
	
	 if vsalary_head_item_fkey=vshift_allowance then
	  select structure_det_depends into vstructure_det_value from salary_structure_details 
	      where salary_head_item_fkey=vsalary_head_item_fkey and structure_id=vstructure_id ;
	   set vemp_salary=vstructure_det_value*vactual_presant_days;
	   set vstructure_det_value=vstructure_det_value*vworking_day;
	  
	  end if; 
	   if vsalary_head_item_fkey=votcomponents    then
      select sum(ifnull(set_duration,0)) into vot_duration  from emp_ot_master
        where emp_fkey = vemp_pkey and DATE_FORMAT(month,'%Y-%m')=pmonth and is_verified='Y';
    	if vot_duration is not null then
         set vemp_salary = vstructure_det_value*(vot_duration/60);
		 set vemp_salary=vemp_salary;
		 else 
		 set vemp_salary =0;
		 set vstructure_det_value=0;
         end if;		
	 
	end if;
	 if lcase(vsalary_head_item_desc) ='leave encashment'  then 
	         set vleaveencashmentkey=vsalary_head_item_fkey;
			   select count(*)  into vapproved_count from leave_encashment_master 
				 where DATE_FORMAT(approved_date,'%Y-%m')=pmonth and emp_fkey=vemp_pkey 
				 and is_approved ='Y' and salary_paid='N'  and status=1 and salary_head_item_fkey != 0;
		
		  if vapproved_count >0 then	 
			 select ifnull(sum(approved_days),0) into vapproved_days from leave_encashment_master 
				 where DATE_FORMAT(approved_date,'%Y-%m')=pmonth and emp_fkey=vemp_pkey 
				 and is_approved ='Y' and salary_paid='N'  and status=1 and salary_head_item_fkey != 0 group by DATE_FORMAT(approved_date,'%Y-%m');
				 
			  if vapproved_days >0 then
				  
			   set vemp_salary=vstructure_det_value*vapproved_days;
			   set vstructure_det_value=vemp_salary;
			   else
			set vemp_salary=0;
			set vstructure_det_value=0;
		     end if ;
		  else
			set vemp_salary=0;
			set vstructure_det_value=0;
		  end if;  
	
	 end if;  
	 if vemp_salary !=0 then
	 insert into emp_salary_slip (payroll_master_fkey,emp_fkey,	 
			month_year	,	 
			salary_head_item_fkey	,
			salary_head_item_desc,
			structure_det_value	,
			salary_rate	,salary_amount ,	 
			presant_total,	 
			leave_total	,
			lop_total	,
			head_operator,
			head_type,
			item_part,action) values(ppayroll_master_pkey,vemp_pkey,pmonth ,vsalary_head_item_fkey,vsalary_head_item_desc,vstructure_det_value,vstructure_det_value,vemp_salary, vactual_presant_days,vleave_total,vlop_total,vhead_operator,vhead_type	,vitem_part,'P');
		end if;
			
	else  
	
	
	  if vsalary_head_item_fkey=vshift_allowance then
	    select structure_det_depends into vstructure_det_value from salary_structure_details 
	      where salary_head_item_fkey=vsalary_head_item_fkey and structure_id=vstructure_id ;
	   set vemp_salary=vstructure_det_value*vactual_presant_days;
	   set vstructure_det_value=vstructure_det_value*vworking_day;
	  else
	  set vemp_salary = vstructure_det_value;
	   if vactual_presant_days=0 then
	     set vemp_salary=0;
	  end if;	
	  end if;
	   if vsalary_head_item_fkey=votcomponents  then
     select sum(ifnull(set_duration,0)) into vot_duration  from emp_ot_master
        where emp_fkey = vemp_pkey and DATE_FORMAT(month,'%Y-%m')=pmonth and is_verified='Y';
    	if vot_duration is not null then
         set vemp_salary = vstructure_det_value*(vot_duration/60) ;
		 set vstructure_det_value=vemp_salary;
		 else 
		 set vemp_salary =0;
		 set vstructure_det_value=0;
         end if;		
	  else	  
	  set vemp_salary = vstructure_det_value;
	   if (vactual_presant_days+vleave_total)=0 then
	     set vemp_salary=0;
	  end if;	
	  end if;
   if lcase(vsalary_head_item_desc) ='leave encashment'  then 
			   select count(*)  into vapproved_count from leave_encashment_master 
				 where DATE_FORMAT(approved_date,'%Y-%m')=pmonth and emp_fkey=vemp_pkey 
				 and is_approved ='Y' and salary_paid='N'  and status=1 and salary_head_item_fkey != 0;
				 
		  if vapproved_count >0 then	 
			 select ifnull(sum(approved_days),0) into vapproved_days from leave_encashment_master 
