			leave_total	,
			lop_total	,
			head_operator,
			head_type,
			item_part,action) values(ppayroll_master_pkey,vemp_pkey,pmonth ,vsalary_head_item_fkey,vsalary_head_item_desc,
			vstructure_det_value,vstructure_det_value,vemp_salary, vactual_presant_days,vleave_total,vlop_total,vhead_operator,vhead_type	,vitem_part,'P');
  
 
  end if;    

 end if;
 
 
 end loop start_loop1;
 close structurecur;
 end block2;
 
 
 
 
