declare adjustment cursor for
  SELECT shi.head_fkey,salary_head_item_fkey , trim(shi.item) ,structure_det_operator,structure_det_value,
  structure_det_depends ,structure_formula,structure_derived_perc
  FROM salary_structure_details ,salary_head_items shi
 where  salary_head_item_fkey =salary_head_item_pkey
and structure_id =vstructure_id ;
    
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop6 = TRUE;
  
open adjustment ;
