   block60:begin
   
   DECLARE exit_loop60 BOOLEAN default FALSE;
    declare slip_cur cursor for 
	select  salary_head_item_fkey	,
			trim(salary_head_item_desc) salary_head_item_desc,salary_amount   ,remarks
			from emp_salary_slip
    where emp_fkey = vemp_pkey and month_year = pmonth and end_date_effective is null  and upper(remarks) RLIKE'[A-Z]'
	
	order by 1 desc;
	
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop60 = TRUE;
 
  open slip_cur;
  start_loop60: loop
