	 if INSTR(vremarks,vsalary_head_item_desc) >0 then
	 update emp_salary_slip set remarks=replace (remarks,vsalary_head_item_desc,'0')  
	where salary_head_item_fkey=vsalary_head_item_fkey1 and emp_fkey = vemp_pkey 
    and month_year = pmonth and end_date_effective is null ; 
	
   end if;
 end loop start_loop60;
 	
	close slip_cur;
   end block60 ;
 
  end loop start_loop1;
 
 close adjustment;
