 select salary_head_item_Fkey,operator into vpftax_components,voperator from tax_salary_components where tax_salary_components_name='Professional Tax';
 select count(*) into vpf_count from emp_salary_slip where salary_head_item_fkey=vpftax_components and payroll_master_fkey=ppayroll_master_pkey 
              and month_year=pmonth and end_date_effective is null;
 			  
	select ifnull(sum(salary_amount),0) into vsalaryamount from emp_salary_slip
    where emp_fkey = vemp_pkey and month_year = pmonth and end_date_effective is null ;		
	if vsalaryamount >0 then 						   
  if vpftax_components is not null and vpf_count=0 then 
   if voperator ='A' then  
  SELECT profession_tax_cal_fn(vemp_pkey, pmonth) into vproff_tax;
 
 
  insert into emp_salary_slip (payroll_master_fkey,emp_fkey,	 
			month_year	,	 
			salary_head_item_fkey	,
			salary_head_item_desc,
			salary_amount ,	 
			presant_total,	 
			leave_total	,
			lop_total	,
			head_operator,
			head_type,
			item_part) values(ppayroll_master_pkey,vemp_pkey,pmonth ,vpftax_components,'Professional Tax',vproff_tax*-1 ,
								 vactual_presant_days,vleave_total,vlop_total,'Deduction','manually','Direct');
  end if;								 
 end if;
 
  select  ifnull(tax_include,'N') into vtax_include  from payroll_master where payroll_master_pkey=ppayroll_master_pkey;

		select  fin_year into vfinyear  from  fin_year where lcase(Year_status)='open' 
		   AND BRANCH_code=pBranch_code and is_current_finyear='Y' and status=1 and vattr1=1;
			 if vtax_include='Y' then 
																																															
	
							
			 SELECT tax_salary_distribution_fn('', vemp_pkey, vfinyear, puser_id) into vtax;
			  if vtax=1 then
			  
			  select tax_monthly_proj ,taxable_income into vtds, vtaxable_income  from emp_tax_sal_trans_sum  where end_date_effective is null and emp_fkey= vemp_pkey;
			  
			   if vtaxable_income <= 500000 then
				 set vtds = 0;
			   end if;	 
			  
			  if vtds<>0 then
				 insert into emp_salary_slip (payroll_master_fkey,emp_fkey,	 
						month_year	,	 
						salary_head_item_fkey	,
						salary_head_item_desc,
						salary_amount ,	 
						presant_total,	 
						leave_total	,
						lop_total	,
						head_operator,
						head_type,
						item_part) values(ppayroll_master_pkey,vemp_pkey,pmonth ,82,'TDS',vtds*-1,
											 0,0,0,'Deduction','Manually','Direct');
			
																			  
			  
			  end if;
	end if;		   
			  
																					  
				   
			  
																																								  
			  
										
				  
			   
	 
					
																								 
					
							 
							
					   
					  
				   
				 
					
				
																																															
																																					  
			
																			  
	 
			
			   end if;
	   
				 
		  
			  end if; 
			  
 select distinct attendance_date into vattendance_date
								   from db_config where active='Y';
 if vattendance_date =0 then
       set vmonth=concat(pmonth,'-01');
			 set vmonthly_att_fromdate =DATE_FORMAT(vmonth, '%Y-%m-01');
			 set vmonthly_att_todate =LAST_DAY(DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d'));

		   else
		   set vmonth=concat(pmonth,'-01');
		   set vmonthly_att_fromdate =date_format(DATE_SUB(concat(DATE_FORMAT(DATE_SUB(vmonth,INTERVAL 1 month), '%Y-%m-'),date_format(last_day(DATE_SUB(vmonth,INTERVAL 1 month)),'%d')),INTERVAL vattendance_date day),'%Y-%m-%d');  

		   set vmonthly_att_todate =DATE_SUB(concat(DATE_FORMAT(vmonth, '%Y-%m-'),date_format(last_day(vmonth),'%d')),INTERVAL vattendance_date day);
		 

           end if ;

		set vday_count = vweekoff_day ; 
			set vworking_day = (DATEDIFF(vmonthly_att_todate,vmonthly_att_fromdate)+1)-(vday_count+vholiday_count);
	select round(sum( salary_amount ),2) into vmonthly_amount  from  emp_salary_slip  where (isnull( end_date_effective ) and (lcase( head_operator ) = 'addition')  and emp_fkey= vemp_pkey and month_year =pmonth ) group by  emp_fkey ,  month_year ;
	
 select round(sum( salary_amount ),2) into vindirect_amount  from  emp_salary_slip  where (isnull( end_date_effective ) and (lcase( head_operator ) = 'addition')  and lcase(item_part)= 'indirect' and emp_fkey= vemp_pkey and month_year =pmonth ) group by  emp_fkey ,  month_year ;
 
  select round(sum( salary_amount ),2) into vtotal_deduction  from  emp_salary_slip  where (isnull( end_date_effective ) and (lcase( head_operator ) = 'deduction')  and emp_fkey= vemp_pkey and month_year =pmonth ) group by  emp_fkey ,  month_year ;
  
   select round(sum( salary_amount ),2) into vtotal_variables  from  emp_salary_slip  where (isnull( end_date_effective ) and (lcase(head_type)='variable')  and emp_fkey= vemp_pkey and month_year =pmonth ) group by  emp_fkey ,  month_year ;
	
	
	if vmonthly_amount>=0 then
  update payroll_master set calander_days= DATEDIFF(vmonthly_att_todate,vmonthly_att_fromdate)+1 , week_off_days=vday_count ,monthly_ctc=(vemp_anual_ctc),
          monthly_amount=vmonthly_amount,   gross_salary= vmonthly_amount-ifnull(vindirect_amount,0) , total_deduction=ifnull(vtotal_deduction,0),net_salary=(gross_salary +ifnull(total_deduction,0))+ifnull(vtotal_variables,0),action='Processed' ,created_by=puser_id,total_variables=ifnull(vtotal_variables,0)
   where payroll_master_pkey=ppayroll_master_pkey and emp_fkey=vemp_pkey and month_year=pmonth ;
   else
 
							 
   update payroll_master set action=null,calander_days= DATEDIFF(vmonthly_att_todate,vmonthly_att_fromdate)+1 , week_off_days=vday_count ,monthly_ctc=(vemp_anual_ctc),
          monthly_amount=vmonthly_amount,   gross_salary= vmonthly_amount-ifnull(vindirect_amount,0) , total_deduction=ifnull(vtotal_deduction,0),net_salary=(gross_salary +ifnull(total_deduction,0))+ifnull(vtotal_variables,0),action=null ,created_by=puser_id,total_variables=ifnull(vtotal_variables,0)
   where payroll_master_pkey=ppayroll_master_pkey and emp_fkey=vemp_pkey and month_year=pmonth ;
   end if;
 update payroll_master set 
  desig=ifnull(vdesignations,''),
   departments=ifnull(vemp_depts,''),
   grade=ifnull(vemp_grades,''),	
   branch_name =ifnull(vemp_branchs,'')
   ,section =ifnull(vemp_sections,'')
   ,division=ifnull(vvertical_name,''),joining_date=ifnull(vjoining_date,''),eps=ifnull(veps,''),probation=ifnull(vprobation,''),contract_start_date=ifnull(vcontract_start_date,''),
   contract_end_date=ifnull(vcontract_end_date,''),pay_scale=ifnull(vpay_scale,''),category_name=ifnull(vcategory_name,'')
    where payroll_master_pkey=ppayroll_master_pkey and emp_fkey=vemp_pkey and month_year=pmonth ;
   
   set vmonthly_amount=0;
   set vindirect_amount=0;
   set vtotal_deduction=0;
  
  end loop;
close cur;




end;;

DROP PROCEDURE IF EXISTS `salary_structure_limit_prc`;;
CREATE PROCEDURE `salary_structure_limit_prc` (IN `pemp_fkey` int, IN `puser_id` varchar(30), OUT `perr_msg` varchar(500))
begin
 
declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vDeviceId int;
declare vjoining_date	  date;
declare vemp_company_id	varchar(30);	 
declare vemp_type	varchar(30);	 
declare vdesignation	varchar(30); 
declare vemp_dept	varchar(30);
declare vemp_grade	varchar(30);
declare vemp_vertical   varchar(30);
declare vemp_branch varchar(30);	 
declare vHOLIDAY_GROUP_ID int;	 
declare vLEAVEPOLICY_GROUP_ID int;
declare vday_time_seq  int;
declare vpresant_total float;
declare vleave_total float;
declare vlop_total float;
declare vemp_anual_ctc float;
declare vemp_monthly_ctc float ;
declare vemp_structure_id int ;
declare vprorate_code int;
declare vprorate_desc varchar(50);
declare vdefined_structure_for varchar(50);
declare vsalary_head_item_fkey int;
declare vsalary_head_item_desc varchar(100);
declare vstructure_det_value float;
declare vhead_operator varchar(20);
declare vhead_type varchar(25);
declare vitem_part varchar(25);
declare vstructure_id int;
declare vemp_salary float;
declare vday_count int ;
declare vattendance_date date;
declare vmonthly_att_fromdate date;
declare vmonthly_att_todate date;
declare vworking_day int;
declare vweekoff_day int;
declare vexistcount int;
declare vmonthly_amount float;
declare vindirect_amount float;
declare vtotal_deduction float;
declare vtotal_variables float;
declare vsalary_rate float;
declare vsalary_amount float;
declare vmonth date;
declare vrate float;
declare vholiday_count  int;
declare vfinyear varchar(20);
declare vtds float;
declare vtax float;
declare vvalue float;
declare vtax_include varchar(30);
declare vtaxable_income float;
declare vstructure_det_depends int;
DECLARE exit_loop BOOLEAN default FALSE;

declare rec_count int;


declare cur cursor for
select distinct ed.emp_pkey,concat(ed.first_name,' ',ed.last_name) empname ,
ep.joining_date	,  
ep.emp_company_id	,	 
ep.emp_type	,	 
ep.designation	,	 
ep.emp_dept	,
ep.emp_grade	, 
ep.emp_vertical,	 
ep.emp_branch	,	 
ep.HOLIDAY_GROUP_ID,	 
ep.LEAVEPOLICY_GROUP_ID,	 
ep.day_time_seq ,
ep.structure_id  from emp_details ed,emp_proff ep 
 where ed.Branch_code=ep.emp_branch and ed.emp_pkey=pemp_fkey
 and ed.emp_pkey=ep.emp_fkey and status=1 ;

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;
 select distinct attendance_date into vattendance_date
								   from db_config where active='Y';
 

open cur;
start_loop: loop
    fetch cur into vemp_pkey,vfirst_name , vjoining_date,	
vemp_company_id,
vemp_type	,	
vdesignation	,
vemp_dept	,
vemp_grade	, 
vemp_vertical,	
vemp_branch	,	
vHOLIDAY_GROUP_id ,
vLEAVEPOLICY_GROUP_ID ,
vday_time_seq ,vstructure_id;
IF exit_loop THEN
        LEAVE start_loop;
     END IF;
	 			   
 select emp_derived_anualctc ,emp_anual_ctc/12 into vemp_anual_ctc,vemp_monthly_ctc  from  emp_ctc_transaction  where emp_fkey=vemp_pkey and end_date_effective is null;
  set vweekoff_day=weekoff_days_count_fn(vemp_pkey, vmonthly_att_fromdate , vmonthly_att_todate );							   
select count(HOLIDAYDATE) into vholiday_count from holidays where HOLIDAY_GROUP_ID in (select HOLIDAY_GROUP_ID from emp_proff where emp_fkey=vemp_pkey)
  and HOLIDAYDATE  between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d') and vmonthly_att_todate ;
  set vworking_day = (DATEDIFF(vmonthly_att_todate,vmonthly_att_fromdate)+1)-(vweekoff_day+vholiday_count) ;
   if vpresant_total>vworking_day then
     set vpresant_total=vworking_day;
    end if;
	 
	 block50:begin
   DECLARE exit_loop50 BOOLEAN default FALSE;
    declare vitem_value float;
    declare slip_cur cursor for 
   select  salary_head_item_fkey	,
			trim(salary_head_item_desc) salary_head_item_desc,
			structure_det_value	 ,head_type  ,head_operator,emp_structure_id
			from emp_salary_structure
    where emp_fkey = vemp_pkey  and head_type in('limit_wl','limit_wg') and end_date_effective is null 
		and structure_det_value<>0  
order by 1 desc;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop50 = TRUE;
 
  open slip_cur;
  start_loop50: loop
    fetch slip_cur into vsalary_head_item_fkey,vsalary_head_item_desc,vstructure_det_value,
	vhead_type,vhead_operator, vemp_structure_id;
	
	IF exit_loop50 THEN 
       LEAVE start_loop50 ;   
    END IF;
	select structure_det_depends into vitem_value   from salary_structure_details where salary_head_item_fkey =vsalary_head_item_fkey and structure_id=vemp_structure_id ;
	if vitem_value is null or vitem_value=0 then
	   set vitem_value = vstructure_det_value;
	else    
	   set vitem_value = vitem_value;
   end if;
   
	if vhead_type ='limit_wl' then
        set vvalue=LEAST(abs(vitem_value) ,abs(vstructure_det_value));
		if vhead_operator='Deduction' then
		  set vvalue=vvalue*-1;
		end if;  
		 update emp_salary_structure set structure_det_value=round(vvalue)  
			where salary_head_item_fkey=vsalary_head_item_fkey and emp_fkey = vemp_pkey 
			 and end_date_effective is null ;
   elseif vhead_type ='limit_wg' then
       set vvalue= GREATEST(abs(vitem_value) ,abs(vstructure_det_value));
	   if vhead_operator='Deduction' then
		  set vvalue=vvalue*-1;
		end if;
	    update emp_salary_structure set structure_det_value=round(vvalue)  
			where salary_head_item_fkey=vsalary_head_item_fkey and emp_fkey = vemp_pkey 
			and end_date_effective is null ;
  end if;	
  set vitem_value =null;
 end loop start_loop50;
   close slip_cur;
   end block50 ;
	 
	 
   set vmonthly_amount=0;
   set vindirect_amount=0;
  set vtotal_deduction=0;
  
   end loop;
close cur;




end;;

DROP PROCEDURE IF EXISTS `sal_structure_distribution`;;
CREATE PROCEDURE `sal_structure_distribution` (IN `Pcompany_code` varchar(30), IN `Pemp_fkey` int, IN `Pemp_structure_id` int, IN `Puserid` varchar(30), OUT `Perror_massage` varchar(200))
begin
declare i int;
declare vworking_time int ;
declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
declare vholidayId int;
declare vdaytimeId int;
declare vHOLIDAYDATE  date;
DECLARE l_sql VARCHAR(4000);
DECLARE nday int;
DECLARE yearmonth varchar(30);
DECLARE vworking_days  int;
DECLARE vatt_date  date;

DECLARE vsunday  char(1);
DECLARE vmonday  char(1);
DECLARE vtuesday  char(1);
DECLARE vwednesday  char(1);
DECLARE vthursday  char(1);
DECLARE vfriday  char(1);
DECLARE vsaturday  char(1);
DECLARE vholicnt  int;
DECLARE vholicnt1  int;
DECLARE linfocnt int;
DECLARE vleave_for_thyear int;
DECLARE vleave_forthe_month int;
DECLARE vremainlve_for_thyear int;
DECLARE vremainlve_forthe_month int;
DECLARE vissandwich char(1);
declare vYdays int;
declare vNdays int;
declare vALLOW_NEGETIVE char(1);
declare vweekoffstring varchar(100);
declare vsalary_head_item_fkey int;
declare vexistcount int;
declare vfullcnt int;
declare vhalfcnt int;
declare vleavecnt int;
declare vleaveexistcnt int;
declare vemp_leave_infocnt int;
declare vfin_year  int;
declare vdistribution_cnt int;
declare vemp_anual_ctc  float;
declare vemp_monthly_ctc  float;
declare vemp_balance_ctc  float;
declare vstructure_name varchar(100);
declare vprorate_code varchar(100);
declare vprorate_desc varchar(100);
declare vdefined_structure_for varchar(100);
declare vstructure_det_operator varchar(100);
declare vstructure_det_value float;
declare vstructure_derived_perc double;
declare vstructure_det_depends float;
declare vvalue float;
declare vstructure_id int;
declare vsalary_head_item_desc varchar(100);
declare vformula_value float;
declare rem_salary_head_item_fkey int;
declare vdedcount int;
DECLARE exit_loop BOOLEAN default FALSE;

declare structurecur cursor for 
 select ss.structure_id,ss.structure_name,ss.prorate_code,ss.prorate_desc,ss.defined_structure_for,ssd.salary_head_item_fkey,
          ssd.structure_det_operator,structure_det_value,structure_derived_perc ,structure_det_depends
     from salary_structure ss, salary_structure_details ssd 
       where ss.structure_id=ssd.structure_id and ss.structure_id=Pemp_structure_id ;

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;


select fin_year into vfin_year  from fin_year where lcase(Year_status)='open' and vattr1 = 1 and is_current_finyear='Y' and status=1; 


select count(*) into vdistribution_cnt  from emp_salary_structure where emp_fkey=Pemp_fkey and end_date_effective is null;
if vdistribution_cnt <>0 then
  update emp_salary_structure  set end_date_effective =current_date,modified_by=Puserid where emp_fkey=Pemp_fkey and end_date_effective is null;
end if;


select emp_anual_ctc  into vemp_anual_ctc  from  emp_ctc_transaction  where emp_fkey=Pemp_fkey and end_date_effective is null;



set vemp_monthly_ctc  =vemp_anual_ctc/12;
open structurecur ;
start_loop: loop
    fetch structurecur into vstructure_id ,vstructure_name,vprorate_code,vprorate_desc,vdefined_structure_for,
         vsalary_head_item_fkey,vstructure_det_operator,vstructure_det_value,vstructure_derived_perc ,vstructure_det_depends  ;

   IF exit_loop THEN        LEAVE start_loop;     END IF;

  set vformula_value=((vemp_anual_ctc/12) * vstructure_derived_perc )/100;
   if vstructure_det_operator ='formula' then
      set vvalue = vformula_value ;
   elseif vstructure_det_operator ='limit' then
     set vvalue=vstructure_det_depends ;
   elseif vstructure_det_operator ='limit_wl' then
     set vvalue=LEAST(vstructure_det_depends ,vformula_value);
   elseif vstructure_det_operator ='limit_wg' then
     set vvalue= GREATEST(vstructure_det_depends ,vformula_value);
 else
    set vvalue =vstructure_det_value; 
  end if;
  
  select count(*) into vdedcount from  salary_head_items  where head_fkey in (select head_pkey from salary_heads where lcase(head_operator)='deduction')
  and salary_head_item_pkey=vsalary_head_item_fkey ;
  
  if vdedcount >0 then 
    set vvalue = vvalue * -1 ;
  end if ;
  
	
 select item  into vsalary_head_item_desc from salary_head_items  where salary_head_item_pkey=vsalary_head_item_fkey;

 insert into emp_salary_structure (emp_fkey,emp_structure_id,prorate_code,prorate_desc,defined_structure_for,	 
salary_head_item_fkey,salary_head_item_desc,structure_det_value)
 values(Pemp_fkey ,vstructure_id ,vprorate_code,vprorate_desc,vdefined_structure_for,vsalary_head_item_fkey,
  vsalary_head_item_desc ,vvalue);

set vemp_balance_ctc =vemp_balance_ctc + vvalue ;
 end loop start_loop ;
 
 select sum(structure_det_value) into vemp_balance_ctc from emp_salary_structure where emp_fkey=Pemp_fkey 
 and end_date_effective is null and structure_det_value > 0;

 
set vvalue =vemp_monthly_ctc - vemp_balance_ctc ;
SELECT salary_head_item_fkey into rem_salary_head_item_fkey  FROM salary_structure_details
 where structure_id =Pemp_structure_id  and structure_det_operator='rembalance';

update emp_salary_structure  set structure_det_value=structure_det_value+vvalue where emp_fkey=Pemp_fkey
 and salary_head_item_fkey=rem_salary_head_item_fkey and end_date_effective is null  ; 




close structurecur ;






end;;

DROP FUNCTION IF EXISTS `sal_structure_distribution_fn`;;
CREATE FUNCTION `sal_structure_distribution_fn` (`Pcompany_code` varchar(30), `Pemp_fkey` int, `Pemp_structure_id` int, `Puserid` varchar(30)) RETURNS int(11) LANGUAGE SQL
begin

declare vreturn int;
declare i int;
declare vworking_time int ;
declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
declare vholidayId int;
declare vdaytimeId int;
declare vHOLIDAYDATE  date;
DECLARE l_sql VARCHAR(4000);
DECLARE nday int;
DECLARE yearmonth varchar(30);
DECLARE vworking_days  int;
DECLARE vatt_date  date;

DECLARE vsunday  char(1);
DECLARE vmonday  char(1);
DECLARE vtuesday  char(1);
DECLARE vwednesday  char(1);
DECLARE vthursday  char(1);
DECLARE vfriday  char(1);
DECLARE vsaturday  char(1);
DECLARE vholicnt  int;
DECLARE vholicnt1  int;
DECLARE linfocnt int;
DECLARE vleave_for_thyear int;
DECLARE vleave_forthe_month int;
DECLARE vremainlve_for_thyear int;
DECLARE vremainlve_forthe_month int;
DECLARE vissandwich char(1);
declare vYdays int;
declare vNdays int;
declare vALLOW_NEGETIVE char(1);
declare vweekoffstring varchar(100);
declare vsalary_head_item_fkey int;
declare vexistcount int;
declare vfullcnt int;
declare vhalfcnt int;
declare vleavecnt int;
declare vleaveexistcnt int;
declare vemp_leave_infocnt int;
declare vfin_year  int;
declare vdistribution_cnt int;
declare vemp_anual_ctc  float;
declare vemp_monthly_ctc  float;
declare vemp_balance_ctc  float;
declare vstructure_name varchar(100);
declare vprorate_code varchar(100);
declare vprorate_desc varchar(100);
declare vdefined_structure_for varchar(100);
declare vstructure_det_operator varchar(100);
declare vstructure_det_value float;
declare vstructure_derived_perc double;
declare vstructure_det_depends float;
declare vvalue float;
declare vstructure_id int;
declare vsalary_head_item_desc varchar(100);
declare vformula_value float;
declare rem_salary_head_item_fkey int;
declare vdedcount int;
declare vhead_operator varchar(30);
declare vhead_type varchar(30);
declare vitem_part varchar(30);
declare vderived_ctc float;
declare vhead_occurance varchar(30);
declare vctc_upload_type int;
declare vhead_fkey int;
declare vemp_type varchar(50);
DECLARE exit_loop BOOLEAN default FALSE;

declare structurecur cursor for 
 select ss.structure_id,ss.structure_name,ss.prorate_code,ss.prorate_desc,ss.defined_structure_for,ssd.salary_head_item_fkey,
          ssd.structure_det_operator,structure_det_value,structure_derived_perc ,structure_det_depends
     from salary_structure ss, salary_structure_details ssd 
       where ss.structure_id=ssd.structure_id 
	   and ss.structure_id=Pemp_structure_id  and structure_det_value<>0;
	 

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;


select fin_year into vfin_year  from fin_year where lcase(Year_status)='open' and vattr1 = 1 and is_current_finyear='Y'
   and status=1 and branch_code= (select branch_code from emp_details where emp_Pkey=Pemp_fkey );

select emp_anual_ctc ,ctc_upload_type into vemp_anual_ctc ,vctc_upload_type from  emp_ctc_transaction  where emp_fkey=Pemp_fkey and end_date_effective is null;



select count(*) into vdistribution_cnt  from emp_salary_structure where emp_fkey=Pemp_fkey and end_date_effective is null;
if vdistribution_cnt <>0 then
 if vctc_upload_type=2 then
  update emp_salary_structure  set end_date_effective =current_date,modified_by=Puserid where emp_fkey=Pemp_fkey and end_date_effective is null
  and  salary_head_item_fkey not in (select salary_head_item_pkey from salary_head_items where head_fkey=1);
    
 else
  update emp_salary_structure  set end_date_effective =current_date,modified_by=Puserid where emp_fkey=Pemp_fkey and end_date_effective is null;
  end if;
end if;
 
 select upper(emp_type) into vemp_type from emp_proff where emp_fkey=Pemp_fkey ;
if vemp_type = 'DAILY WAGES' then
  set vemp_monthly_ctc  =vemp_anual_ctc ;

else
set vemp_monthly_ctc  =vemp_anual_ctc/12;

end if;
open structurecur ;
start_loop: loop
    fetch structurecur into vstructure_id ,vstructure_name,vprorate_code,vprorate_desc,vdefined_structure_for,
         vsalary_head_item_fkey,vstructure_det_operator,vstructure_det_value,vstructure_derived_perc ,vstructure_det_depends  ;

   IF exit_loop THEN        LEAVE start_loop;     END IF;
  if vemp_type = 'DAILY WAGES' then
   set vformula_value=(vemp_anual_ctc * vstructure_derived_perc )/100;
  else
  set vformula_value=((vemp_anual_ctc/12) * vstructure_derived_perc )/100;
  end if;
  
   if vstructure_det_operator ='formula'  then
      set vvalue = vformula_value ;

   elseif vstructure_det_operator ='limit' then
     set vvalue=vstructure_det_depends ;
   elseif vstructure_det_operator ='limit_wl' then
     set vvalue=LEAST(vstructure_det_depends ,vformula_value);
   elseif vstructure_det_operator ='limit_wg' then
     set vvalue= GREATEST(vstructure_det_depends ,vformula_value);
   elseif vstructure_det_operator ='fixed' then
     set vvalue= vstructure_det_value ;  
 
 else
    set vvalue =vstructure_det_value; 
  end if;
  
  select count(*) into vdedcount from  salary_head_items  where head_fkey in (select head_pkey from salary_heads where lcase(head_operator)='deduction')
  and salary_head_item_pkey=vsalary_head_item_fkey ;
  
  if vdedcount >0 then 
    set vvalue = vvalue * -1 ;
  end if ;
  
select head_operator,head_occurance into vhead_operator,vhead_occurance 
 from salary_heads  where head_pkey in (select head_fkey from  salary_head_items 
 where  salary_head_item_pkey=vsalary_head_item_fkey); 

 select item ,item_part,item_type ,head_fkey into vsalary_head_item_desc ,vitem_part,vhead_type,vhead_fkey from salary_head_items  where salary_head_item_pkey=vsalary_head_item_fkey;

 if vctc_upload_type=2 then
  if vhead_fkey!=1 then
  if vvalue<>0 then
 insert into emp_salary_structure (emp_fkey,emp_structure_id,prorate_code,prorate_desc,defined_structure_for,	 
salary_head_item_fkey,salary_head_item_desc,structure_det_value,head_operator,head_type	,item_part)
 values(Pemp_fkey ,vstructure_id ,vprorate_code,vprorate_desc,vdefined_structure_for,vsalary_head_item_fkey,
  vsalary_head_item_desc ,vvalue,vhead_operator,vstructure_det_operator,vitem_part);
 end if;
 ELSE 
  update emp_salary_structure  set prorate_code=vprorate_code ,	prorate_desc=vprorate_desc where emp_fkey=Pemp_fkey and end_date_effective is null
  and  salary_head_item_fkey=vsalary_head_item_fkey;
  
 end if;
 else 
  if vvalue<>0 then
 insert into emp_salary_structure (emp_fkey,emp_structure_id,prorate_code,prorate_desc,defined_structure_for,	 
salary_head_item_fkey,salary_head_item_desc,structure_det_value,head_operator,head_type	,item_part)
 values(Pemp_fkey ,vstructure_id ,vprorate_code,vprorate_desc,vdefined_structure_for,vsalary_head_item_fkey,
  vsalary_head_item_desc ,vvalue,vhead_operator,vstructure_det_operator,vitem_part);
  end if;
 end if;
set vvalue=0 ;


 end loop start_loop ; 
 
 select sum(structure_det_value) into vemp_balance_ctc from emp_salary_structure where emp_fkey=Pemp_fkey 
 and end_date_effective is null and structure_det_value > 0 
  and lcase(head_operator)='addition' and lcase(item_part)='direct' 
   and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items where head_fkey=1) and lcase(head_type)<>'manually' ;

 
 set vvalue =vemp_monthly_ctc - vemp_balance_ctc ;
SELECT salary_head_item_fkey into rem_salary_head_item_fkey  FROM salary_structure_details
 where structure_id =Pemp_structure_id  and structure_det_operator='rembalance' and structure_det_value>0 ;
if vctc_upload_type!=2 then
update emp_salary_structure  set structure_det_value=structure_det_value+vvalue where emp_fkey=Pemp_fkey
 and salary_head_item_fkey=rem_salary_head_item_fkey and end_date_effective is null  ; 
end if;


close structurecur ;


BLOCK5:begin
DECLARE exit_loop5 BOOLEAN default FALSE;
declare vhead_fkey int;
declare vstructure_det_depends  float;
declare vstructure_formula varchar(500);
declare vstructure_derived_perc float;
declare vsalary_head_item_fkey1 int;
declare vsalary_head_item_desc1 varchar(500);
declare vsalary_amount1  float;
declare vnewformula varchar(200);
