  SELECT shi.head_fkey,salary_head_item_fkey , trim(shi.item) ,structure_det_operator,structure_det_value,
  structure_det_depends ,structure_formula,structure_derived_perc
  FROM salary_structure_details ,salary_head_items shi
 where  salary_head_item_fkey =salary_head_item_pkey
and structure_id =vstructure_id  and head_fkey <> 1
 and length(structure_formula) <>'0' ;
    
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop5 = TRUE;
  
open adjustment ;
start_loop1: loop
    fetch adjustment into vhead_fkey,vsalary_head_item_fkey,vsalary_head_item_desc,vhead_operator,vstructure_det_value,
	vstructure_det_depends,vstructure_formula,vstructure_derived_perc;
   
IF exit_loop5 THEN 
       LEAVE start_loop1 ;   
  END IF;
   set vnewformula=vstructure_formula;
   
   block50:begin
   DECLARE exit_loop50 BOOLEAN default FALSE;
    declare slip_cur cursor for 
   select  salary_head_item_fkey	,
			trim(salary_head_item_desc) salary_head_item_desc,
			structure_det_value from emp_salary_structure
    where emp_fkey = Pemp_fkey and end_date_effective is null 
	and structure_det_value<>0  order by 1 desc;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop50 = TRUE;
 
  open slip_cur;
  start_loop50: loop
    fetch slip_cur into vsalary_head_item_fkey1,vsalary_head_item_desc1,vsalary_amount1 ;
	
	IF exit_loop50 THEN 
       LEAVE start_loop50 ;   
    END IF;
	
	
	
	
	
	
	 
	   set vnewformula=replace(vnewformula,vsalary_head_item_desc1,vsalary_amount1) ;
	   
   
 
 end loop start_loop50;
 
    set vnewformula=replace(vnewformula,'Monthly Gross Salary',vemp_monthly_ctc) ;
	set vnewformula=replace(vnewformula,'. ','.') ;
    update emp_salary_structure set remarks=replace(vnewformula,'. ','.')  
	where salary_head_item_fkey=vsalary_head_item_fkey and emp_fkey = Pemp_fkey 
    and end_date_effective is null ; 
	
	set vnewformula=null;
	set vhead_fkey =null;
	set vsalary_head_item_fkey =null;
	set vsalary_head_item_desc=null;
	set vhead_operator=null;
	set vstructure_det_value=null;
	set vstructure_det_depends =null;
	set vstructure_formula=null;
	set vstructure_derived_perc=null ; 
	
	close slip_cur;
   end block50 ;
  
  end loop start_loop1;
 close adjustment;
 end BLOCK5;

 BLOCK6:begin
DECLARE exit_loop6 BOOLEAN default FALSE;
declare vhead_fkey int;
declare vstructure_det_depends  float;
declare vstructure_formula varchar(600);
declare vstructure_derived_perc float;
declare vsalary_head_item_fkey1 int;
declare vsalary_head_item_desc1 varchar(600);
declare vsalary_amount1  float;
declare vnewformula varchar(200);
declare vformula_value float;
declare vremarks varchar(1000);
declare vremarks1 varchar(1000);
declare vvalue float;
declare adjustment cursor for
  SELECT shi.head_fkey,salary_head_item_fkey , trim(shi.item) ,structure_det_operator,structure_det_value,
  structure_det_depends ,structure_formula,structure_derived_perc
  FROM salary_structure_details ,salary_head_items shi
 where  salary_head_item_fkey =salary_head_item_pkey
and structure_id =vstructure_id ;
    
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop6 = TRUE;
  
open adjustment ;
start_loop1: loop
    fetch adjustment into vhead_fkey,vsalary_head_item_fkey,vsalary_head_item_desc,vhead_operator,vstructure_det_value,
	vstructure_det_depends,vstructure_formula,vstructure_derived_perc;
   
IF exit_loop6 THEN 
       LEAVE start_loop1 ;   
  END IF;
   set vnewformula=vstructure_formula;
   
   block60:begin
   
   DECLARE exit_loop60 BOOLEAN default FALSE;
    declare slip_cur cursor for 
	select  salary_head_item_fkey	,
			trim(salary_head_item_desc) salary_head_item_desc,structure_det_value   ,remarks
			from emp_salary_structure
    where emp_fkey = Pemp_fkey and end_date_effective is null  and upper(remarks) RLIKE'[A-Z]'
	
	order by 1 desc;
	
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop60 = TRUE;
 
  open slip_cur;
  start_loop60: loop
    fetch slip_cur into vsalary_head_item_fkey1,vsalary_head_item_desc1,vsalary_amount1 ,vremarks;
	
	IF exit_loop60 THEN 
       LEAVE start_loop60 ;   
    END IF;
	
	 if INSTR(vremarks,vsalary_head_item_desc) >0 then
	
	 update emp_salary_structure set remarks=replace (remarks,vsalary_head_item_desc,'0')  
	where salary_head_item_fkey=vsalary_head_item_fkey1 and emp_fkey = Pemp_fkey 
    and end_date_effective is null ; 
	
	update emp_salary_structure set remarks=replace (remarks,' ','')  
	where salary_head_item_fkey=vsalary_head_item_fkey1 and emp_fkey = Pemp_fkey 
    and end_date_effective is null ; 
	
   end if;
 end loop start_loop60;
 	
	close slip_cur;
   end block60 ;
 
  end loop start_loop1;
 
 close adjustment;
 end BLOCK6;

 select sum(structure_det_value) into vderived_ctc from emp_salary_structure 
  where lcase(head_operator)='addition' and end_date_effective is null
 and emp_fkey=Pemp_fkey group by emp_fkey;
 
update emp_ctc_transaction set emp_derived_anualctc=vderived_ctc ,ctc_upload_type=1 where emp_fkey=Pemp_fkey and end_date_effective is null;

 select count(*) into vreturn from emp_salary_structure where emp_fkey=Pemp_fkey
 and emp_structure_id=Pemp_structure_id and end_date_effective is null;
if vreturn > 0 then
return 1;
else
return 0;
end if;


end;;

