else
   set vmonthly_att_fromdate =date_format(DATE_SUB(concat(DATE_FORMAT(DATE_SUB(Pmonth,INTERVAL 1 month), '%Y-%m-'),date_format(last_day(DATE_SUB(Pmonth,INTERVAL 1 month)),'%d')),INTERVAL vattendance_date-1 day),'%Y-%m-%d');  
                      



