FROM salary_structure_details
 where structure_id =Pemp_structure_id  and structure_det_operator='rembalance' and structure_det_value>0 ;
 
 
 

update emp_salary_structure  set structure_det_value=structure_det_value+vvalue where emp_fkey=Pemp_fkey
 and salary_head_item_fkey=rem_salary_head_item_fkey and end_date_effective is null  ; 



close structurecur ;


