DROP FUNCTION IF EXISTS `site_time_duration_check`;;
CREATE FUNCTION `site_time_duration_check` (`Pyear_month` date, `Pemp_pkey` int, `psite_pkey` int) RETURNS varchar(300) CHARACTER SET 'latin1' LANGUAGE SQL
READS SQL DATA
    DETERMINISTIC
begin

declare vemp_pkey int;
declare vatt_date  date;
declare nday  int;
declare vdaytimeId  int;
declare vLOGDATE_intime datetime;
declare vLOGDATE_outime datetime;
declare vduration int;
declare vminuts_calc_perday int;
declare vminutes_per_half int;
declare vsetvalue varchar(10);
declare vexistvalue varchar(10);
declare vattendance_date int;
declare vmonthly_att_fromdate datetime;
declare vmonthly_att_todate datetime;
declare vemp_count int;
declare von_dutty1 varchar(10);
declare voff_dutty1 varchar(10);
declare visnextday int;
declare vstrict_monitorings varchar(10);
DECLARE vsunday_F  char(1);
DECLARE vmonday_F  char(1);
DECLARE vtuesday_F  char(1);
DECLARE vwednesday_F  char(1);
DECLARE vthursday_F  char(1);
DECLARE vfriday_F  char(1);
DECLARE vsaturday_F  char(1);
declare vis_exception int;
declare von_dutty4 varchar(30);
declare voff_dutty4 varchar(30);
declare vworking_time4 varchar(30);
declare vsite_transactions_fkey int;
declare vsite_fkey int;
DECLARE exit_loop1 BOOLEAN default FALSE;

declare att_cur cursor for   
  select distinct emp_pkey,date_format(LOGDATE,'%Y-%m-%d'),att.c6,ifnull(c7,0)as c7 ,att.c4 
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 

 and lcase(c1)='in' and ucase(att.status)='Y'
 and date_format(LOGDATE,'%Y-%m-%d') between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d') and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d')
  and emp_pkey in
 (select emp_fkey from emp_proff where to_days(DATE_FORMAT(joining_date , '%Y-%m-%d')) <= to_days(DATE_FORMAT(vmonthly_att_todate , '%Y-%m-%d'))
  
  ) 
 and emp_pkey=if(pemp_pkey in(null,0,''),emp_pkey,pemp_pkey) 
   and att.C2 = 'SIT' and att.c6=if(psite_pkey in(null,0,''),att.c6,psite_pkey)  group by att.c6,date_format(LOGDATE,'%Y-%m-%d'),emp_pkey,att.c4
 order by 1,LOGDATE ;
 


DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;


select distinct attendance_date into vattendance_date
                           from db_config where active='Y';

if vattendance_date =0 then

set vmonthly_att_fromdate =DATE_FORMAT(Pyear_month, '%Y-%m-01');
set vmonthly_att_todate =LAST_DAY(DATE_FORMAT(Pyear_month, '%Y-%m-%d'));

else
   set vmonthly_att_fromdate =date_format(DATE_SUB(concat(DATE_FORMAT(DATE_SUB(Pyear_month,INTERVAL 1 month), '%Y-%m-'),date_format(last_day(DATE_SUB(Pyear_month,INTERVAL 1 month)),'%d')),INTERVAL vattendance_date-1 day),'%Y-%m-%d');  
                      



set vmonthly_att_todate =DATE_SUB(concat(DATE_FORMAT(Pyear_month, '%Y-%m-'),date_format(last_day(Pyear_month),'%d')),INTERVAL vattendance_date day);
 
 




end if ;

 
BLOCK7:begin
DECLARE vsunday  char(1);
DECLARE vmonday  char(1);
DECLARE vtuesday  char(1);
DECLARE vwednesday  char(1);
DECLARE vthursday  char(1);
DECLARE vfriday  char(1);
DECLARE vsaturday  char(1);
declare vcount int;
declare vsite_pkey int;
declare vsite_transactions_fkey int;
declare vcheckout_limit date;
DECLARE exit_loop BOOLEAN default FALSE;
declare i int;

declare vfirst_name  varchar(50);
declare vholidayId int;
declare cur cursor for
   select distinct emp_pkey,att.c6 ,att.c7
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 

 and lcase(c1)='in' and ucase(att.status)='Y'
 and date_format(LOGDATE,'%Y-%m-%d') between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d') and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d')
  and emp_pkey in
 (select emp_fkey from emp_proff where to_days(DATE_FORMAT(joining_date , '%Y-%m-%d')) <= to_days(DATE_FORMAT(vmonthly_att_todate , '%Y-%m-%d'))
 
  ) 
 and emp_pkey=if(pemp_pkey in(null,0,''),emp_pkey,pemp_pkey) 
   and att.C2 = 'SIT' and att.c6=if(psite_pkey in(null,0,''),att.c6,psite_pkey)
 order by 1,2;

  
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;

open cur;
start_loop: loop
    fetch cur into vemp_pkey,vsite_pkey,vsite_transactions_fkey;
   IF exit_loop THEN        LEAVE start_loop;     END IF;
 


 		select to_days(DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d'))into i;

		WHILE i <= to_days(vmonthly_att_todate) DO
            select count(*) into vemp_count from emp_site_detail_timeattandance where emp_pkey=vemp_pkey and site_fkey=vsite_pkey
			and yearmonth=Pyear_month and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') ;
   if vemp_count =0 then
		insert into emp_site_detail_timeattandance (emp_pkey,
		att_date, yearmonth,site_fkey) values (vemp_pkey,DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d'),Pyear_month,vsite_pkey );
  end if;
		select i + 1 into i;
		END WHILE;
  
 
end loop start_loop;
 close cur ;

 end BLOCK7;


open att_cur;
att_loop: loop
    fetch att_cur into vemp_pkey,vatt_date,vsite_fkey,vsite_transactions_fkey,vdaytimeId;

  IF exit_loop1 THEN
	LEAVE att_loop;
  END IF;

select count(*) into vemp_count from emp_site_detail_timeattandance 
 where emp_pkey=vemp_pkey and att_date=vatt_date and site_fkey=vsite_fkey  and yearmonth=Pyear_month ;

if vemp_count >0 then 
   select DATE_FORMAT(vatt_date,'%d') into nday ;
   
   
  
   
 select distinct on_dutty1,off_dutty1,isnextday,strict_monitorings
 into von_dutty1,voff_dutty1,visnextday,vstrict_monitorings
   from working_day_time_procedures where day_time_seq=vdaytimeId ;

  
select min(LOGDATE) into vLOGDATE_intime
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 
 and lcase(c1)='in' and emp_pkey=vemp_pkey and ucase(att.status)='Y'
and date_format(LOGDATE,'%Y-%m-%d') =vatt_date 
  and ifnull(c6,0)=vsite_fkey  group by ed.emp_id;
  
 

    
   SELECT max(isnextday) into visnextday FROM working_day_time_procedures WHERE day_time_seq 
                   IN (select day_time_seq_fkey from site_transactions where site_fkey=vsite_fkey and day_time_seq_fkey=vdaytimeId and status=1) ;
				   
    if 	visnextday=1 then
	SELECT off_dutty1 into voff_dutty1 FROM working_day_time_procedures WHERE isnextday= visnextday and day_time_seq 
                   IN (select day_time_seq_fkey from site_transactions where site_fkey=vsite_fkey and day_time_seq_fkey=vdaytimeId and status=1) limit 1;
     select max(LOGDATE) into vLOGDATE_outime
		  from device_attandance att,emp_details ed      
			where att.emp_id=ed.emp_id 
		   and att.company_code=ed.company_code 
		 and lcase(c1)='out'
		
		and date_format(LOGDATE,'%Y-%m-%d') >=vatt_date and LOGDATE between vLOGDATE_intime  
		and  date_format(concat(date_format(DATE_ADD(vatt_date, INTERVAL 1 DAY),'%Y-%m-%d'),' ',voff_dutty1),'%Y-%m-%d %H:%i:%s')
		and emp_pkey=vemp_pkey and ucase(att.status)='Y'  and ifnull(c6,0)=vsite_fkey;
		 
	

    else 
	SELECT max(off_dutty1) into voff_dutty1 FROM working_day_time_procedures WHERE 
                  isnextday=0 and day_time_seq 
                   IN (select day_time_seq_fkey from site_transactions where site_fkey=vsite_fkey and status=1) ;
		  select max(LOGDATE) into vLOGDATE_outime
		  from device_attandance att,emp_details ed      
			where att.emp_id=ed.emp_id 
		   and att.company_code=ed.company_code 
		 and lcase(c1)='out'
		and date_format(LOGDATE,'%Y-%m-%d') =vatt_date and emp_pkey=vemp_pkey and ucase(att.status)='Y' 
	
	
		
		
		   and ifnull(c6,0)=vsite_fkey  group by att.emp_id ;
		 
  end if;  
  
   
 
  
  
  
 if vLOGDATE_outime is not null and vLOGDATE_intime is not null then
 
  BLOCK4:begin
    declare vFIRST_NAME varchar(100);
declare  vINTIME datetime;
declare	vINVAL varchar(30);
declare	vOUTTIME  datetime;
declare	vOUTVAL varchar(30);
declare vbreakintime datetime;
declare vbreakouttime datetime;
DECLARE exit_loop4 BOOLEAN default FALSE;
declare break_cur cursor for
 SELECT
        FIRST_NAME,     EMP_PKEY,       INTIME,     INVAL,
        (CASE WHEN INVAL = 'in' AND OUTVAL = 'in' THEN NULL ELSE OUTTIME END) AS OUTTIME ,
        OUTVAL
FROM
    (
        SELECT 
               MO.C1 AS OUTVAL,       MO.EMP_PKEY,       MO.FIRST_NAME,
               MO.LOGDATE AS OUTTIME,
               @S AS 'LEAD(logdate) over(PARTITION BY emp_pkey ORDER BY logdate)' ,
               @LOGIN := @S AS INTIME,
               @C AS 'LEAD(c1) over(PARTITION BY emp_pkey ORDER BY logdate)',
               @INVAL := @C AS INVAL,
               (CASE WHEN @PARTITION_BY_COLUMN = EMP_PKEY OR @_SEASON IS NULL THEN @S := LOGDATE
                                                                              ELSE @S := NULL
                 END) TMP_VALUE,
               (CASE WHEN @PARTITION_BY_COLUMN = EMP_PKEY OR @_SEASON IS NULL THEN @C := C1
                                                                              ELSE @C := NULL
                 END) TMP_VALUE1,
               (@PARTITION_BY_COLUMN := EMP_PKEY) PARTITION_COLUMN
        FROM 
               (
                  SELECT 
                        ed.emp_pkey,    ed.first_name,      att.logdate,    lcase(att.c1) c1
                  FROM (SELECT @PARTITION_BY_COLUMN = NULL,
                               @S := NULL,
                               @C := NULL,
                               @LOGIN := NULL,
                               @INVAL := NULL
                       ) vars, device_attandance att, emp_details ed
                  where 
                        att.emp_id = ed.emp_id and ucase(att.status)='Y' and ifnull(c6,0)=vsite_fkey
                        and ed.emp_pkey = 	vemp_pkey
                        and date_format(att.logdate,'%Y-%m-%d %T') BETWEEN 
                            DATE_FORMAT(vLOGDATE_intime, '%Y-%m-%d %T') AND DATE_FORMAT(vLOGDATE_outime, '%Y-%m-%d %T')
             order by LOGDATE ) MO
    ) XX
WHERE INVAL = 'in' AND OUTVAL IN ('out' ) ;


  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop4 = TRUE;
 	set vduration=0;
	
  
open break_cur ;
start_loop1: loop
    fetch break_cur into vFIRST_NAME,	vEMP_PKEY,	vINTIME,	vINVAL,	vOUTTIME,	vOUTVAL;
   
IF exit_loop4 THEN 
       LEAVE start_loop1 ;   
  END IF;
 
   
 select distinct minuts_calc_perday,minutes_per_half,strict_monitorings,on_dutty1,off_dutty1
 into vminuts_calc_perday ,vminutes_per_half,vstrict_monitorings,von_dutty1,voff_dutty1
   from working_day_time_procedures where day_time_seq=vdaytimeId ;
   
 
  if vINTIME is not null and vOUTTIME is not null then
  set vINTIME = vINTIME - interval 2 second;
  set vduration=vduration+TIMESTAMPDIFF(Minute, vINTIME,vOUTTIME);
 insert into test(field1,field2,field3) values(vduration,vINTIME,vOUTTIME);
 
  end if;
  
 end loop start_loop1;
 
 close break_cur;
 end BLOCK4;

 set vduration=abs(vduration);
 
 
 


  
   
 select distinct minuts_calc_perday,minutes_per_half,sunday_F,  monday_F,  tuesday_F,  wednesday_F,  thursday_F  ,  friday_F,  saturday_F,on_dutty4,off_dutty4,working_time4,is_exception
 into vminuts_calc_perday ,vminutes_per_half,vsunday_F,  vmonday_F,  vtuesday_F,  vwednesday_F,  vthursday_F  ,  vfriday_F,  vsaturday_F,von_dutty4,voff_dutty4,vworking_time4,vis_exception
   from working_day_time_procedures where day_time_seq=vdaytimeId ;
   
   
   if vduration >= vminuts_calc_perday then 
   set vsetvalue='P/P';
   elseif vduration >= vminutes_per_half then
   set vsetvalue='P/A';
   elseif vduration < vminutes_per_half then
   set vsetvalue='A/A';
   else
   set vsetvalue='A/A';
   end if;
  
              
   if WEEKDAY(vatt_date)=6 then
    if vsunday_F='Y' then
       if vduration >= vminutes_per_half then 
	   set vsetvalue='P/P';
	   elseif vduration < vminutes_per_half then
	   set vsetvalue='A/A';
	   end if; 
	 end if;  
	if vis_exception=1 then  
	 if vsunday_F='1' then
	   if FLOOR((DayOfMonth(vatt_date)-1)/7)+1 !=1 then
		   if vduration >= vworking_time4 then 
		   set vsetvalue='P/P';
		   elseif vduration >= (vworking_time4/2) then
		   set vsetvalue='P/A';
		   elseif vduration < (vworking_time4/2) then
		   set vsetvalue='A/A';
		   end if;
		
         end if;
		 elseif vsunday_F='2' then
	   if FLOOR((DayOfMonth(vatt_date)-1)/7)+1 !=2 then
		   if vduration >= vworking_time4 then 
		   set vsetvalue='P/P';
		   elseif vduration >= (vworking_time4/2) then
		   set vsetvalue='P/A';
		   elseif vduration < (vworking_time4/2) then
		   set vsetvalue='A/A';
		   end if;
		
         end if; 
		  elseif vsunday_F='3' then
	   if FLOOR((DayOfMonth(vatt_date)-1)/7)+1 !=3 then
		   if vduration >= vworking_time4 then 
		   set vsetvalue='P/P';
		   elseif vduration >= (vworking_time4/2) then
		   set vsetvalue='P/A';
		   elseif vduration < (vworking_time4/2) then
		   set vsetvalue='A/A';
		   end if;
		
         end if; 
		 
		   elseif vsunday_F='4' then
	   if FLOOR((DayOfMonth(vatt_date)-1)/7)+1 !=4 then
		   if vduration >= vworking_time4 then 
		   set vsetvalue='P/P';
		   elseif vduration >= (vworking_time4/2) then
		   set vsetvalue='P/A';
		   elseif vduration < (vworking_time4/2) then
		   set vsetvalue='A/A';
		   end if;
		
         end if; 
		
         elseif vsunday_F='A' then
	   	   if vduration >= vworking_time4 then 
		   set vsetvalue='P/P';
		   elseif vduration >= (vworking_time4/2) then
		   set vsetvalue='P/A';
		   elseif vduration < (vworking_time4/2) then
		   set vsetvalue='A/A';
		   end if;
		   
		 elseif vsunday_F='L' then
		  if FLOOR((DayOfMonth(vatt_date)-1)/7)+1 not in(2,4) then
	   	   if vduration >= vworking_time4 then 
		   set vsetvalue='P/P';
		   elseif vduration >= (vworking_time4/2) then
		   set vsetvalue='P/A';
		   elseif vduration < (vworking_time4/2) then
