DROP FUNCTION IF EXISTS `stock_bal_qty_fn`;;
CREATE FUNCTION `stock_bal_qty_fn` (`pstart_date` date, `pstore_pkey` int(11), `pitem_pkey` int(11)) RETURNS float LANGUAGE SQL
begin

DECLARE vitem_master_pkey	int(11)	 ;
DECLARE vitem_code	int(11)	 ;
DECLARE vqtyuptodate	float	 ;
DECLARE vsumvqtyuptodate varchar(1000);
declare vreturn float;
declare i int;

DECLARE exit_loop2 BOOLEAN default FALSE; 
		select to_days(DATE_FORMAT(pstart_date, '%Y-%m-%d'))into i;

		WHILE i <= to_days(current_date) DO
          
		select a.item_master_pkey,a.item_code,sum(item_qty)qtyuptodate into vitem_master_pkey,vitem_code,vqtyuptodate from 
        (select store_master_pkey,store_location,item_master_pkey,item_code,item_desc,sum(item_qty) item_qty from
        item_except_grn_allocation_view  where  creation_date <= DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and 
		store_master_pkey= pstore_pkey and item_master_pkey=pitem_pkey group by store_master_pkey,item_master_pkey,item_code,item_desc
        union all
        select store_master_pkey,store_location,item_master_pkey,item_code,item_desc,sum(item_qty) item_qty from 
        grn_stock_details_date_view where gr_date <= DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and store_master_pkey= pstore_pkey and 
		item_master_pkey=pitem_pkey group by store_master_pkey,item_master_pkey,item_code,item_desc
        union all
        select store_master_pkey,store_location,item_master_pkey,item_code,item_desc,(sum(qty)-sum(returned_qty ))*-1 item_qty	
        from Item_allocation_details_view where date_allocated <= DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and store_master_pkey= pstore_pkey and 
		item_master_pkey=pitem_pkey group by store_master_pkey,item_master_pkey,item_code,item_desc) a
        group by store_master_pkey,item_master_pkey;
		  
		  if i = to_days(DATE_FORMAT(pstart_date, '%Y-%m-%d')) and vqtyuptodate >=0 
		  then
		    set vreturn=vqtyuptodate ;
		  else
		    set vreturn=least(vreturn,vqtyuptodate);
		  end if;
		  set vqtyuptodate=null;
		select i + 1 into i;
		END WHILE;
		
return 	vreturn;
end;;

DROP PROCEDURE IF EXISTS `stock_tranfer_item_pkey_update`;;
CREATE PROCEDURE `stock_tranfer_item_pkey_update` ()
BEGIN
declare vstock_item_pkey int;
declare vitem_desc varchar(200);
declare vitem_pkey int;
DECLARE exit_loop BOOLEAN default FALSE;

DECLARE cur cursor  for select stock_item_pkey,item_desc from stock_tranfer_item;

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;

open cur ;
start_loop: loop
    fetch cur into vstock_item_pkey,vitem_desc  ;

   IF exit_loop THEN        LEAVE start_loop;     END IF;
   
   select item_master_pkey into vitem_pkey from item_master where item_desc=vitem_desc limit 1;
   
   update stock_tranfer_item set item_fkey=vitem_pkey where stock_item_pkey=vstock_item_pkey;
   
   
   end loop start_loop ; 
 
close cur ;
end;;

DROP PROCEDURE IF EXISTS `stock_tranfer_pkey_prc`;;
CREATE PROCEDURE `stock_tranfer_pkey_prc` (IN `pstock_tranfer_pkey` int, OUT `perr_msg` varchar(500))
begin
DECLARE vitem_fkey	int(11)	 ;
DECLARE vitem_desc	varchar(50)	 ;
DECLARE vitem_code	int(11)	 ;
DECLARE vtranfer_stock	int(11)	 ;
DECLARE vavailable_qty	int(11)	 ;
DECLARE vrequired_qty	float	 ;
DECLARE vcreated_by    varchar(50)	 ;
DECLARE vadjustment_date	date	; 
DECLARE vfrom_store	varchar(50)	 ;
DECLARE vto_store	varchar(50)	 ;
DECLARE vremarks	varchar(50)	 ;

DECLARE exit_loop2 BOOLEAN default FALSE;
          
         declare stock_tranfer_cur cursor for 
          select  adjustment_date,from_store,to_store,remarks,item_fkey	,item_desc	,	item_code	, tranfer_stock	, available_qty	,required_qty	,stock_tranfer.created_by 
		  from stock_tranfer_item ,stock_tranfer 
		  where stock_tranfer_item.stock_tranfer_fkey=stock_tranfer.stock_tranfer_pkey 
		  and stock_tranfer_fkey=pstock_tranfer_pkey and stock_tranfer.status=1 and stock_tranfer_item.status=1;
                                
          DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop2 = TRUE;
           open stock_tranfer_cur ;
           stock_tranfer_cur_loop1: loop
           fetch stock_tranfer_cur  into vadjustment_date,vfrom_store,vto_store,vremarks,vitem_fkey	,vitem_desc	,	vitem_code	, vtranfer_stock	, vavailable_qty	,vrequired_qty	,vcreated_by ;

           IF exit_loop2 THEN
	        LEAVE stock_tranfer_cur_loop1;
           END IF;

if vfrom_store != vto_store then
INSERT INTO `stock_details` (`store_fkey`, `supplier_fkey`, `invoice_no`, `mr_no`, `po_no`, `item_batch`, `item_fkey`, `received_qty`, `item_qty`, `free_stock`, `offer_stock`, `purchase_rate`, `amount`, `item_mrp`, `varified_by`, `item_state`, `created_by`, `creation_date`, `modified_by`, `modified_date`, `status`) VALUES
(vfrom_store,	0,	pstock_tranfer_pkey,	0,	0,	NULL,	vitem_fkey,	0,vrequired_qty*-1,NULL,	NULL,	NULL,	0,	NULL,	vcreated_by,	'TRANSFER',	vcreated_by,	vadjustment_date,	NULL,	NULL,	1);

INSERT INTO `stock_details` (`store_fkey`, `supplier_fkey`, `invoice_no`, `mr_no`, `po_no`, `item_batch`, `item_fkey`, `received_qty`, `item_qty`, `free_stock`, `offer_stock`, `purchase_rate`, `amount`, `item_mrp`, `varified_by`, `item_state`, `created_by`, `creation_date`, `modified_by`, `modified_date`, `status`) VALUES
(vto_store,	0,	pstock_tranfer_pkey,	0,	0,	NULL,	vitem_fkey,	0,vrequired_qty,NULL,	NULL,	NULL,	0,	NULL,	vcreated_by,	'TRANSFER',	vcreated_by,	vadjustment_date,	NULL,	NULL,	1);

end if;

 end loop stock_tranfer_cur_loop1;
         close stock_tranfer_cur ;
end;;

DROP PROCEDURE IF EXISTS `stock_trans_prc`;;
CREATE PROCEDURE `stock_trans_prc` (IN `pfrom_store` varchar(400), IN `pto_store` varchar(400), IN `pitem_pkey` int, IN `pitem_qty` int, IN `pdate_created` date, IN `pcreated_by` varchar(100), OUT `perrm` varchar(400))
begin

if pfrom_store != pto_store then
INSERT INTO `stock_details` (`store_fkey`, `supplier_fkey`, `invoice_no`, `mr_no`, `po_no`, `item_batch`, `item_fkey`, `received_qty`, `item_qty`, `free_stock`, `offer_stock`, `purchase_rate`, `amount`, `item_mrp`, `varified_by`, `item_state`, `created_by`, `creation_date`, `modified_by`, `modified_date`, `status`) VALUES
(pfrom_store,	0,	NULL,	0,	0,	NULL,	pitem_pkey,	0,pitem_qty*-1,NULL,	NULL,	NULL,	0,	NULL,	pcreated_by,	'TRANSFER',	pcreated_by,	pdate_created,	NULL,	NULL,	1);

INSERT INTO `stock_details` (`store_fkey`, `supplier_fkey`, `invoice_no`, `mr_no`, `po_no`, `item_batch`, `item_fkey`, `received_qty`, `item_qty`, `free_stock`, `offer_stock`, `purchase_rate`, `amount`, `item_mrp`, `varified_by`, `item_state`, `created_by`, `creation_date`, `modified_by`, `modified_date`, `status`) VALUES
(pto_store,	0,	NULL,	0,	0,	NULL,	pitem_pkey,	0,pitem_qty,NULL,	NULL,	NULL,	0,	NULL,	pcreated_by,	'TRANSFER',	pcreated_by,	pdate_created,	NULL,	NULL,	1);

end if;
end;;

DROP FUNCTION IF EXISTS `structure_calc`;;
CREATE FUNCTION `structure_calc` (`psalary_head_item_fkey` int, `pemp_pkey` int) RETURNS varchar(200) CHARACTER SET 'latin1' LANGUAGE SQL
begin 
declare vvalue varchar(200);
select remarks into vvalue  from emp_salary_structure 
	 where salary_head_item_fkey= psalary_head_item_fkey and emp_fkey =pemp_pkey 
            and end_date_effective is null and remarks is not null ;
return vvalue;
end;;

DROP PROCEDURE IF EXISTS `structure_preview_prc`;;
CREATE PROCEDURE `structure_preview_prc` (IN `Pcompany_code` varchar(30), IN `Pemp_fkey` int, IN `Pemp_structure_id` int, IN `Pemp_anual_ctc` float)
begin

declare vreturn int;
declare i int;
declare vworking_time int ;
declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
declare vholidayId int;
declare vdaytimeId int;
declare vHOLIDAYDATE  date;
DECLARE l_sql VARCHAR(4000);
DECLARE nday int;
DECLARE yearmonth varchar(30);
DECLARE vworking_days  int;
DECLARE vatt_date  date;
DECLARE vsunday  char(1);
DECLARE vmonday  char(1);
DECLARE vtuesday  char(1);
DECLARE vwednesday  char(1);
DECLARE vthursday  char(1);
DECLARE vfriday  char(1);
DECLARE vsaturday  char(1);
DECLARE vholicnt  int;
DECLARE vholicnt1  int;
DECLARE linfocnt int;
DECLARE vleave_for_thyear int;
DECLARE vleave_forthe_month int;
DECLARE vremainlve_for_thyear int;
DECLARE vremainlve_forthe_month int;
DECLARE vissandwich char(1);
declare vYdays int;
declare vNdays int;
declare vALLOW_NEGETIVE char(1);
declare vweekoffstring varchar(100);
declare vsalary_head_item_fkey int;
declare vexistcount int;
declare vfullcnt int;
declare vhalfcnt int;
declare vleavecnt int;
declare vleaveexistcnt int;
declare vemp_leave_infocnt int;
declare vdistribution_cnt int;
declare vemp_anual_ctc  float;
declare vemp_monthly_ctc  float;
declare vemp_balance_ctc  float;
declare vstructure_name varchar(100);
declare vprorate_code varchar(100);
declare vprorate_desc varchar(100);
declare vdefined_structure_for varchar(100);
declare vstructure_det_operator varchar(100);
declare vstructure_det_value float;
declare vstructure_derived_perc double;
declare vstructure_det_depends float;
declare vvalue float;
declare vstructure_id int;
declare vsalary_head_item_desc varchar(100);
declare vformula_value float;
declare rem_salary_head_item_fkey int;
declare vdedcount int;
declare vhead_operator varchar(30);
declare vhead_type varchar(30);
declare vitem_part varchar(30);
declare vderived_ctc float;
declare vhead_occurance varchar(30);
declare vctc_upload_type int;
declare vhead_fkey int;
declare vemp_type varchar(50);

DECLARE exit_loop BOOLEAN default FALSE;

declare structurecur cursor for 
	select ss.structure_id,ss.structure_name,ss.prorate_code,ss.prorate_desc,ss.defined_structure_for,ssd.salary_head_item_fkey,
	ssd.structure_det_operator,structure_det_value,structure_derived_perc ,structure_det_depends
	from salary_structure ss, salary_structure_details ssd 
	where ss.structure_id=ssd.structure_id 
	and ss.structure_id=Pemp_structure_id  and structure_det_value<>0;

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;

CREATE TEMPORARY TABLE IF NOT EXISTS salary_preview_temp (
	emp_fkey				INT,
	emp_structure_id		INT,
	prorate_code			varchar(30),
	prorate_desc			varchar(100),
	defined_structure_for	varchar(250),
	salary_head_item_fkey 	INT,
	salary_head_item_desc	varchar(250),
	structure_det_value		decimal(10,0),
	head_operator			VARCHAR(30),
	head_type				VARCHAR(30),
	item_part				VARCHAR(30),
	remarks					VARCHAR(3000)
 );
 
TRUNCATE TABLE salary_preview_temp;
 
select upper(emp_type) into vemp_type from emp_proff where emp_fkey=Pemp_fkey;

set vemp_anual_ctc = Pemp_anual_ctc;

if vemp_type = 'DAILY WAGES' then
	set vemp_monthly_ctc  =vemp_anual_ctc ;
else
	set vemp_monthly_ctc  =vemp_anual_ctc/12;
end if;

open structurecur ;

start_loop: loop
	fetch structurecur into vstructure_id ,vstructure_name,vprorate_code,vprorate_desc,vdefined_structure_for,
	vsalary_head_item_fkey,vstructure_det_operator,vstructure_det_value,vstructure_derived_perc ,vstructure_det_depends  ;

	IF exit_loop THEN
		LEAVE start_loop;
	END IF;
	
  if vemp_type = 'DAILY WAGES' then
   set vformula_value=(vemp_anual_ctc * vstructure_derived_perc )/100;
  else
  set vformula_value=((vemp_anual_ctc/12) * vstructure_derived_perc )/100;
  end if;
  
   if vstructure_det_operator ='formula'  then
      set vvalue = vformula_value ;

   elseif vstructure_det_operator ='limit' then
     set vvalue=vstructure_det_depends ;
   elseif vstructure_det_operator ='limit_wl' then
     set vvalue=LEAST(vstructure_det_depends ,vformula_value);
   elseif vstructure_det_operator ='limit_wg' then
     set vvalue= GREATEST(vstructure_det_depends ,vformula_value);
   elseif vstructure_det_operator ='fixed' then
     set vvalue= vstructure_det_value ;  
 
 else
    set vvalue =vstructure_det_value; 
  end if;
  
  select count(*) into vdedcount from  salary_head_items  where head_fkey in (select head_pkey from salary_heads where lcase(head_operator)='deduction')
  and salary_head_item_pkey=vsalary_head_item_fkey ;
  
  if vdedcount >0 then 
    set vvalue = vvalue * -1 ;
  end if ;
  
select head_operator,head_occurance into vhead_operator,vhead_occurance 
from salary_heads  where head_pkey in (select head_fkey from  salary_head_items 
where  salary_head_item_pkey=vsalary_head_item_fkey); 

select item ,item_part,item_type ,head_fkey into vsalary_head_item_desc ,vitem_part,vhead_type,vhead_fkey from salary_head_items  where salary_head_item_pkey=vsalary_head_item_fkey;

-- if vvalue<>0 then -- Edited by Akshay on 20-11-2025
	insert into salary_preview_temp (emp_fkey,emp_structure_id,prorate_code,prorate_desc,defined_structure_for,	 
	salary_head_item_fkey,salary_head_item_desc,structure_det_value,head_operator,head_type	,item_part)
	values(Pemp_fkey ,vstructure_id ,vprorate_code,vprorate_desc,vdefined_structure_for,vsalary_head_item_fkey,
	vsalary_head_item_desc ,vvalue,vhead_operator,vstructure_det_operator,vitem_part);
-- end if;

set vvalue=0 ;

end loop start_loop ; 
 
 select sum(structure_det_value) into vemp_balance_ctc from salary_preview_temp where emp_fkey=Pemp_fkey 
  and structure_det_value > 0 
  and lcase(head_operator)='addition' and lcase(item_part)='direct' 
   and salary_head_item_fkey in (select salary_head_item_pkey from salary_head_items where head_fkey=1) and lcase(head_type)<>'manually' ;

 set vvalue =vemp_monthly_ctc - vemp_balance_ctc ;
 
SELECT salary_head_item_fkey into rem_salary_head_item_fkey  FROM salary_structure_details
 where structure_id =Pemp_structure_id  and structure_det_operator='rembalance' and structure_det_value>0 ;
 
update salary_preview_temp  set structure_det_value=structure_det_value+vvalue where emp_fkey=Pemp_fkey
and salary_head_item_fkey=rem_salary_head_item_fkey ; 

close structurecur ;

BLOCK5:begin

declare vhead_fkey int;
declare vstructure_det_depends  float;
declare vstructure_formula varchar(500);
declare vstructure_derived_perc float;
declare vsalary_head_item_fkey1 int;
declare vsalary_head_item_desc1 varchar(500);
declare vsalary_amount1  float;
declare vnewformula varchar(200);
declare vformula_value float;
declare vvalue float;

DECLARE exit_loop5 BOOLEAN default FALSE;

declare adjustment cursor for
	SELECT shi.head_fkey,salary_head_item_fkey , trim(shi.item) ,structure_det_operator,structure_det_value,
	structure_det_depends ,structure_formula,structure_derived_perc
	FROM salary_structure_details ,salary_head_items shi
	where  salary_head_item_fkey =salary_head_item_pkey
	and structure_id =vstructure_id  and head_fkey <> 1
	and length(structure_formula) <>'0' ;

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop5 = TRUE;
  
open adjustment ;
start_loop1: loop
    fetch adjustment into vhead_fkey,vsalary_head_item_fkey,vsalary_head_item_desc,vhead_operator,vstructure_det_value,
	vstructure_det_depends,vstructure_formula,vstructure_derived_perc;
   
IF exit_loop5 THEN 
       LEAVE start_loop1 ;   
  END IF;
   set vnewformula=vstructure_formula;
   
   block50:begin
   DECLARE exit_loop50 BOOLEAN default FALSE;
    declare slip_cur cursor for 
   select  salary_head_item_fkey	,
			trim(salary_head_item_desc) salary_head_item_desc,
			structure_det_value from salary_preview_temp
    where emp_fkey = Pemp_fkey 
	and structure_det_value<>0  order by 1 desc;
	
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop50 = TRUE;
 
  open slip_cur;
  start_loop50: loop
    fetch slip_cur into vsalary_head_item_fkey1,vsalary_head_item_desc1,vsalary_amount1 ;
	
	IF exit_loop50 THEN 
       LEAVE start_loop50 ;   
    END IF;

	   set vnewformula=replace(vnewformula,vsalary_head_item_desc1,vsalary_amount1) ;
	   
 end loop start_loop50;
 
    set vnewformula=replace(vnewformula,'Monthly Gross Salary',vemp_monthly_ctc) ;
	set vnewformula=replace(vnewformula,'. ','.') ;
    update salary_preview_temp set remarks=replace(vnewformula,'. ','.')  
	where salary_head_item_fkey=vsalary_head_item_fkey and emp_fkey = Pemp_fkey ; 
	
	set vnewformula=null;
	set vhead_fkey =null;
	set vsalary_head_item_fkey =null;
	set vsalary_head_item_desc=null;
	set vhead_operator=null;
	set vstructure_det_value=null;
	set vstructure_det_depends =null;
	set vstructure_formula=null;
	set vstructure_derived_perc=null ; 
	
	close slip_cur;
   end block50 ;
  
  end loop start_loop1;
 close adjustment;
 end BLOCK5;

 BLOCK6:begin
DECLARE exit_loop6 BOOLEAN default FALSE;
declare vhead_fkey int;
declare vstructure_det_depends  float;
declare vstructure_formula varchar(600);
declare vstructure_derived_perc float;
declare vsalary_head_item_fkey1 int;
declare vsalary_head_item_desc1 varchar(600);
declare vsalary_amount1  float;
declare vnewformula varchar(200);
declare vformula_value float;
declare vremarks varchar(1000);
declare vremarks1 varchar(1000);
declare vvalue float;

declare adjustment cursor for
  SELECT shi.head_fkey,salary_head_item_fkey , trim(shi.item) ,structure_det_operator,structure_det_value,
  structure_det_depends ,structure_formula,structure_derived_perc
  FROM salary_structure_details ,salary_head_items shi
 where  salary_head_item_fkey =salary_head_item_pkey
and structure_id =vstructure_id ;
    
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop6 = TRUE;
  
open adjustment ;
start_loop1: loop
    fetch adjustment into vhead_fkey,vsalary_head_item_fkey,vsalary_head_item_desc,vhead_operator,vstructure_det_value,
	vstructure_det_depends,vstructure_formula,vstructure_derived_perc;
   
IF exit_loop6 THEN 
       LEAVE start_loop1 ;   
  END IF;
   set vnewformula=vstructure_formula;
   
   block60:begin
   
   DECLARE exit_loop60 BOOLEAN default FALSE;
    declare slip_cur cursor for 
	select  salary_head_item_fkey	,
			trim(salary_head_item_desc) salary_head_item_desc,structure_det_value   ,remarks
			from salary_preview_temp
    where emp_fkey = Pemp_fkey  and upper(remarks) RLIKE'[A-Z]'
	
	order by 1 desc;
	
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop60 = TRUE;
 
  open slip_cur;
  start_loop60: loop
    fetch slip_cur into vsalary_head_item_fkey1,vsalary_head_item_desc1,vsalary_amount1 ,vremarks;
	
	IF exit_loop60 THEN 
       LEAVE start_loop60 ;   
    END IF;
	
	 if INSTR(vremarks,vsalary_head_item_desc) >0 then
	
	 update salary_preview_temp set remarks=replace (remarks,vsalary_head_item_desc,'0')  
	where salary_head_item_fkey=vsalary_head_item_fkey1 and emp_fkey = Pemp_fkey ; 
	
	update salary_preview_temp set remarks=replace (remarks,' ','')  
	where salary_head_item_fkey=vsalary_head_item_fkey1 and emp_fkey = Pemp_fkey  ; 
	
   end if;
 end loop start_loop60;
 	
	close slip_cur;
   end block60 ;
 
  end loop start_loop1;
 
 close adjustment;
 end BLOCK6;

SELECT * FROM salary_preview_temp;

DROP TEMPORARY TABLE IF EXISTS salary_preview_temp;

end;;

DROP FUNCTION IF EXISTS `tax_computation_fn`;;
CREATE FUNCTION `tax_computation_fn` (`Pemp_fkey` int, `pmonth` varchar(20), `pfin_year` int) RETURNS int(11) LANGUAGE SQL
begin
declare vreturn int;
declare vemp_anual_ctc  float;
declare vemp_monthly_ctc  float;
declare vemp_balance_ctc  float;
declare vstructure_name varchar(100);
declare vprorate_code varchar(100);
declare vprorate_desc varchar(100);
declare vdefined_structure_for varchar(100);
declare vstructure_det_operator varchar(100);
declare vstructure_det_value float;
declare vstructure_derived_perc double;
declare vstructure_det_depends float;
declare vvalue float;
declare vstructure_id int;
declare vsalary_head_item_desc varchar(100);
declare vformula_value float;
declare rem_salary_head_item_fkey int;
declare vdedcount int;
declare vhead_operator varchar(30);
declare vhead_type varchar(30);
declare vitem_part varchar(30);
declare vcount int;
declare vtax_salary_components_pkey int; 
declare vtax_salary_components_name varchar(100);
declare vhra1 float;
declare vhra2 float;
declare vhra3 float;
declare vavailed_salary float;
declare vtaxable_salary float ;
declare vupper_limit float;
declare vtaxable_income float;
declare vtax_heads_limitsum float;
declare vtax_yearly float;
declare vtax_monthly float;
declare vother_income float;
declare vfirst_portion float;
declare vsecond_portion float;
declare vthird_portion float ;
declare vforth_portion float;
declare vfifth_portion float;
declare vsixth_portion float ;
declare vseventh_portion float;
declare vhradeclared float;
declare vtaxable_salary1 float;
declare vtax_head_value  float;
declare vtax_heads_limit   float;
declare vtax_heads_fkey int;
declare vtax_heads_details_fkey int;
declare vtax_head_detail_value float ;
declare vtax_head_detail_limit  float;
declare vtax_head_detail_balsum float;
declare vtaxsumcount int;
declare vstart_month date ;
declare vend_month date;
declare vactaul_salary float;
declare vproj_count int;
declare vactual_salary_recd float;
declare vprojected_salary float;
declare vbaselimit float;
declare vclassification varchar(20);
declare vsumprojected_salary float;
declare vtaxdeducted_sum float;
declare vsumactual_salary_recd float;
declare vactual_count int;
declare vjoining_date date;
declare vtotalmonth int;
declare vtax_heads_totsum float;
declare vsurcharge float;
declare  vcess  float;
declare  vrebate float;
declare vnewtaxable_income float;
declare vstanderd_deduction float;
declare vtax_half_yearly int;
declare vvariable_count int;
declare vcount1 int;
declare vage int;
declare vstate varchar(30);
declare vmonthly_sal float;
declare vfirst_portion_tax float;
declare vsecond_portion_tax float;
DECLARE vthird_portion_tax float;
declare vfourth_portion_tax float;
DECLARE vfifth_portion_tax float;
DECLARE vsixth_portion_tax float;
declare vseventh_portion_tax float;
DECLARE vdeduction  float;
declare vdeclared_deduction float;
DECLARE vtax_monthly_proj  float;
declare vemp_type varchar(10);
declare voption_type varchar(10);
declare vmarginal_relief float;

DECLARE exit_loop BOOLEAN default FALSE;

select emp_type into vemp_type from emp_proff where emp_fkey=pemp_fkey;

select sum(abs(salary_amount)) into vmonthly_sal
from emp_salary_slip where emp_fkey=Pemp_fkey and head_operator<>'Deduction' 
and end_date_effective is null and item_part <> 'Indirect'  and  month_year =pmonth	
and salary_head_item_fkey not in (select salary_head_item_fkey from emp_salary_structure 
where emp_fkey=Pemp_fkey and end_date_effective is null 
and head_operator='Deduction' and  item_part = 'Indirect' )  ;

select sum(abs(salary_amount)) into vdeduction
from emp_salary_slip where emp_fkey=Pemp_fkey and end_date_effective is null
and head_operator='Deduction' and item_part <> 'Indirect'  and  month_year =pmonth	
and salary_head_item_fkey not in (select salary_head_item_fkey from emp_salary_structure 
where emp_fkey=Pemp_fkey and end_date_effective is null 
and head_operator='Deduction' and item_part <> 'Indirect' )  ;

if upper(vemp_type)='DAILY WAGES' then 
	
	select emp_derived_anualctc ,emp_anual_ctc into vemp_anual_ctc,vemp_monthly_ctc  
	from  emp_ctc_transaction  where emp_fkey=Pemp_fkey and end_date_effective is null;
	
elseif upper(vemp_type)='HOURLY WAGES' then
	
	select sum(abs(structure_det_value))vemp_monthly_ctc,sum(abs(structure_det_value))*12  into vemp_monthly_ctc,vemp_anual_ctc 
	from emp_salary_structure where emp_fkey=Pemp_fkey and end_date_effective is null and head_operator<>'Deduction' 
	and end_date_effective is null and item_part <> 'Indirect' ;

else

	select emp_derived_anualctc ,emp_anual_ctc/12 into vemp_anual_ctc,vemp_monthly_ctc  from  emp_ctc_transaction  
	where emp_fkey=Pemp_fkey and end_date_effective is null;

end if ;

select start_month,end_month into vstart_month,vend_month  from  fin_year where fin_year=pfin_year and vattr1=1
and is_current_finyear='Y' and status=1 
and branch_code in (select branch_code from emp_details where emp_Pkey=Pemp_fkey );

select  sum(abs(salary_amount)) into vtaxdeducted_sum from emp_salary_slip where emp_fkey= Pemp_fkey
and end_date_effective is null  and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
and payroll_master_fkey in (select payroll_master_pkey from payroll_master where action in ('Approved','Processed'))
and ucase(salary_head_item_desc) = 'TDS' group by emp_fkey;

select option_type into voption_type  from emp_tax_regime where emp_fkey=Pemp_fkey  and fin_year=pfin_year and end_date_effective is null;

if voption_type='O' then
	
	select taxable_income,other_income,declared_deduction,standerd_deduction ,first_portion,	second_portion,	third_portion,
	tax_yearly,	tax_monthly_proj,	surcharge,	cess,rebate,first_portion,second_portion,third_portion,hra3
	into vtaxable_salary,vother_income,vdeclared_deduction,vstanderd_deduction,vfirst_portion,vsecond_portion,vthird_portion,
	vtax_yearly,vtax_monthly_proj,vsurcharge,vcess,vrebate,vfirst_portion_tax,vsecond_portion_tax,vthird_portion_tax,vhra1
	from emp_tax_sal_trans_sum where emp_fkey=Pemp_fkey and end_date_effective is null and status=1 and fin_year=pfin_year;
	
	set vtax_yearly = vtax_yearly + vsurcharge + vcess;
	
	INSERT INTO `tax_computation_report` ( `emp_fkey`, `Month_year`, `regime`, `Monthly_Salary`, `Availed_Salary`,`Hra_exemption`, `Deductions`,
	`Taxable_Income_from_Salary`, `Taxable_Income_from_Other_Sources`, `Investments_Other_Deductions`, `Standard_deduction`, 
	`Total_Taxable_Income`, `Above_first_income`, `Above_Secnd_income`, `Above_third_income`, `Total_Income`, 
	`Above_first_slab`, `Above_second_slab`, `Above_third_slab`, `Total_Tax`, `Cess`, `Surcharge`, 
	`Rebate`, `Total`, `Tax_Deducted`, `Balance_Tax`, `Monthly_Tax`) 
	VALUES
	(Pemp_fkey,	pmonth,	'OLD',	vemp_monthly_ctc,	vmonthly_sal,vhra1,vdeduction,	
	vtaxable_salary,	vother_income,	vdeclared_deduction,	vstanderd_deduction,
	(vtaxable_salary+vother_income),	vfirst_portion,	vsecond_portion,	vthird_portion,	(vfirst_portion+vsecond_portion+vthird_portion),
	vfirst_portion_tax,vsecond_portion_tax,vthird_portion_tax,(vfirst_portion_tax+vsecond_portion_tax+vthird_portion_tax),	vcess,	vsurcharge,
	vrebate,	vtax_yearly,	vtaxdeducted_sum,	(vtax_yearly-ifnull(vtaxdeducted_sum,0)),	vtax_monthly_proj);
	
	select count(*) into vreturn from emp_tax_sal_trans 
	where emp_fkey=Pemp_fkey and end_date_effective is null;

else
	
	select taxable_income,taxable_salary,other_income,declared_deduction,standerd_deduction ,
	tax_yearly,	tax_monthly_proj,	surcharge,	cess,rebate,marginal_relief,
	first_portion,second_portion,third_portion,forth_portion,fifth_portion ,	sixth_portion ,	seventh_portion,
	first_portion_tax ,	second_portion_tax ,	third_portion_tax,fourth_portion_tax,fifth_portion_tax,sixth_portion_tax,seventh_portion_tax,hra3  
	into vtaxable_income,vtaxable_salary,vother_income,vdeclared_deduction,vstanderd_deduction,
	vtax_yearly,vtax_monthly_proj,vsurcharge,vcess,vrebate,vmarginal_relief,
	vfirst_portion,vsecond_portion,vthird_portion,vforth_portion,vfifth_portion ,vsixth_portion ,vseventh_portion,
	vfirst_portion_tax ,vsecond_portion_tax ,vthird_portion_tax,vfourth_portion_tax,vfifth_portion_tax,vsixth_portion_tax,vseventh_portion_tax,vhra1
	from emp_tax_sal_trans_sum_new where emp_fkey=Pemp_fkey and end_date_effective is null and status=1 and fin_year=pfin_year;
	
	set vtax_yearly = vtax_yearly + vsurcharge + vcess;
	
	INSERT INTO `tax_computation_report` ( `emp_fkey`, `Month_year`, `regime`, `Monthly_Salary`, `Availed_Salary`,`Hra_exemption`, `Deductions`,
	`Taxable_Income_from_Salary`, `Taxable_Income_from_Other_Sources`, `Investments_Other_Deductions`, `Standard_deduction`, 
	`Total_Taxable_Income`, 
	`Above_first_income`, `Above_Secnd_income`, `Above_third_income`,`Above_fourth_income`,`Above_fifth_income`,
	`Above_sixth_income`,`Above_seventh_income`,`Total_Income`, 
	`Above_first_slab`, `Above_second_slab`, `Above_third_slab`,`Above_fourth_slab`,`Above_fifth_slab`,`Above_sixth_slab`,`Above_seventh_slab`,`Total_Tax`, `Cess`, `Surcharge`, 
	`Rebate`,`Marginal_Relief`, `Total`, `Tax_Deducted`, `Balance_Tax`, `Monthly_Tax` )
	VALUES
	(Pemp_fkey,	pmonth,	'NEW',	vemp_monthly_ctc,	vmonthly_sal,vhra1,	vdeduction,	
	vtaxable_salary,	vother_income,	vdeclared_deduction,	vstanderd_deduction,
	(vtaxable_income),
	vfirst_portion,	vsecond_portion,	vthird_portion	,vforth_portion,vfifth_portion ,vsixth_portion, vseventh_portion,
	(vfirst_portion+vsecond_portion+vthird_portion+vforth_portion+vfifth_portion+vsixth_portion+vseventh_portion),
	vfirst_portion_tax,vsecond_portion_tax,vthird_portion_tax,vfourth_portion_tax,vfifth_portion_tax,vsixth_portion_tax,vseventh_portion_tax,
	(vfirst_portion_tax+vsecond_portion_tax+vthird_portion_tax+vfourth_portion_tax+vfifth_portion_tax+vsixth_portion_tax+vseventh_portion_tax),
	vcess,	vsurcharge, vrebate,vmarginal_relief,	vtax_yearly,	vtaxdeducted_sum,	(vtax_yearly-ifnull(vtaxdeducted_sum,0)),	vtax_monthly_proj);
	
	select count(*) into vreturn from emp_tax_sal_trans_new
	where emp_fkey=Pemp_fkey and end_date_effective is null;
	
end if;	 



if vreturn > 0 then
	return 1;
else
	return 0;
end if;

end;;

DROP FUNCTION IF EXISTS `tax_salary_distribution_fn`;;
CREATE FUNCTION `tax_salary_distribution_fn` (`Pcompany_code` varchar(30), `Pemp_fkey` int, `pfin_year` varchar(30), `Puserid` varchar(30)) RETURNS int(11) LANGUAGE SQL
begin
declare vreturn int;
declare i int;
declare vworking_time int ;
declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
declare vholidayId int;
declare vdaytimeId int;
declare vHOLIDAYDATE  date;
DECLARE l_sql VARCHAR(4000);
DECLARE nday int;
DECLARE yearmonth varchar(30);
DECLARE vworking_days  int;
DECLARE vatt_date  date;

DECLARE vsunday  char(1);
DECLARE vmonday  char(1);
DECLARE vtuesday  char(1);
DECLARE vwednesday  char(1);
DECLARE vthursday  char(1);
DECLARE vfriday  char(1);
DECLARE vsaturday  char(1);
DECLARE vholicnt  int;
DECLARE vholicnt1  int;
DECLARE linfocnt int;
DECLARE vleave_for_thyear int;
DECLARE vleave_forthe_month int;
DECLARE vremainlve_for_thyear int;
DECLARE vremainlve_forthe_month int;
DECLARE vissandwich char(1);
declare vYdays int;
declare vNdays int;
declare vALLOW_NEGETIVE char(1);
declare vweekoffstring varchar(100);
declare vsalary_head_item_fkey int;
declare vexistcount int;
declare vfullcnt int;
declare vhalfcnt int;
declare vleavecnt int;
declare vleaveexistcnt int;
declare vemp_leave_infocnt int;
declare vfin_year  int;
declare vdistribution_cnt int;
declare vemp_anual_ctc  float;
declare vemp_monthly_ctc  float;
declare vemp_balance_ctc  float;
declare vstructure_name varchar(100);
declare vprorate_code varchar(100);
declare vprorate_desc varchar(100);
declare vdefined_structure_for varchar(100);
declare vstructure_det_operator varchar(100);
declare vstructure_det_value float;
declare vstructure_derived_perc double;
declare vstructure_det_depends float;
declare vvalue float;
declare vstructure_id int;
declare vsalary_head_item_desc varchar(100);
declare vformula_value float;
declare rem_salary_head_item_fkey int;
declare vdedcount int;
declare vhead_operator varchar(30);
declare vhead_type varchar(30);
declare vitem_part varchar(30);
declare vcount int;
declare vtax_salary_components_pkey int; 
declare vtax_salary_components_name varchar(100);
declare vhra1 float;
declare vhra2 float;
declare vhra3 float;
declare vavailed_salary float;
declare vtaxable_salary float ;
declare vupper_limit float;
declare vtaxable_income float;
declare vtax_heads_limitsum float;
declare vtax_yearly float;
declare vtax_monthly float;
declare vother_income float;
declare vfirst_portion float;
declare vsecond_portion float;
declare vthird_portion float ;
declare vhradeclared float;
declare vtaxable_salary1 float;
declare vtax_head_value  float;
declare vtax_heads_limit   float;
declare vtax_heads_fkey int;
declare vtax_heads_details_fkey int;
declare vtax_head_detail_value float ;
declare vtax_head_detail_limit  float;
declare vtax_head_detail_balsum float;
declare vtaxsumcount int;
declare vstart_month date ;
declare vend_month date;
declare vactaul_salary float;
declare vproj_count int;
declare vactual_salary_recd float;
declare vprojected_salary float;
declare vbaselimit float;
declare vclassification varchar(20);
declare vsumprojected_salary float;
declare vtaxdeducted_sum float;
declare vsumactual_salary_recd float;
declare vactual_count int;
declare vjoining_date date;
declare vtotalmonth int;
declare vtax_heads_totsum float;
declare vsurcharge float;
declare  vcess  float;
declare  vrebate float;
declare vnewtaxable_income float;
declare vstanderd_deduction float;
declare vtax_half_yearly int;
declare vvariable_count int;
declare vcount1 int;
declare vage int;
declare vstate varchar(30);
declare vfirst_portion_tax float;
declare vsecond_portion_tx float;
DECLARE vthird_portion_tx float;
DECLARE exit_loop BOOLEAN default FALSE;

declare structurecur cursor for 
select salary_head_item_fkey,
salary_head_item_desc,
abs(structure_det_value),head_operator,head_type,item_part
     from emp_salary_structure where emp_fkey=Pemp_fkey and end_date_effective is null and head_operator<>'Deduction' and end_date_effective is null and item_part <> 'Indirect' 
union 
select salary_head_item_fkey,salary_head_item_desc,sum(abs(salary_amount)),head_operator,head_type,item_part
from emp_salary_slip where emp_fkey=Pemp_fkey and end_date_effective is null and head_operator<>'Deduction' and end_date_effective is null and item_part <> 'Indirect'  and  month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')	
and salary_head_item_fkey not in (select salary_head_item_fkey from emp_salary_structure where emp_fkey=Pemp_fkey and end_date_effective is null 
and head_operator<>'Deduction' and end_date_effective is null and item_part <> 'Indirect' ) group by salary_head_item_fkey ;
	 
	

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;



 set vfin_year=pfin_year;

select count(*) into vdistribution_cnt  from emp_tax_sal_trans where emp_fkey=Pemp_fkey and end_date_effective is null;
if vdistribution_cnt <>0 then
  update emp_tax_sal_trans set end_date_effective =current_date,modified_by=Puserid where emp_fkey=Pemp_fkey and end_date_effective is null;
end if;







  select  start_month,end_month into vstart_month,vend_month  from  fin_year where fin_year=pfin_year and vattr1=1
    and is_current_finyear='Y' and status=1 
		   and branch_code= (select branch_code from emp_details where emp_Pkey=Pemp_fkey );
		   
open structurecur ;
start_loop: loop
    fetch structurecur into vsalary_head_item_fkey,vsalary_head_item_desc,vstructure_det_value,vhead_operator ,vhead_type,vitem_part  ;

   IF exit_loop THEN        LEAVE start_loop;     END IF;
   
   
 select count(distinct month_year) into vactual_count from emp_salary_slip where  
    emp_fkey=Pemp_fkey and end_date_effective is null and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	
     and ucase(salary_head_item_desc) not in ('SALARY ADVANCE','LOANS','TDS DEDUCTED')  ;	 
	
  
  select  sum(abs(salary_amount)) into vactaul_salary from emp_salary_slip where salary_head_item_Fkey=vsalary_head_item_fkey 
    and emp_fkey=Pemp_fkey and end_date_effective is null and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	
     and ucase(salary_head_item_desc) not in ('SALARY ADVANCE','LOANS','TDS DEDUCTED')  ;
	
	
	select date_format(joining_date,'%Y-%m-%d') into vjoining_date from emp_proff  where emp_fkey=Pemp_fkey;
	
	
	if vjoining_date > vstart_month then
	  
	set vtotalmonth= TIMESTAMPDIFF(MONTH,vjoining_date, vend_month);
	
	
	else 
	set vtotalmonth= TIMESTAMPDIFF(MONTH,vstart_month, vend_month);
	
	
	end if;
	
	set vproj_count=abs(vtotalmonth)+1-ifnull(vactual_count,0);
	
	
  
    set vactual_salary_recd= ifnull(vactaul_salary,0);
	select count(*) into vvariable_count from salary_heads
       where head_occurance ='VARIABLE' and  head_pkey  in (select head_fkey from salary_head_items where salary_head_item_pkey=vsalary_head_item_fkey );
	   
	   select count(*) into vcount1
					 from emp_salary_structure where emp_fkey=Pemp_fkey and salary_head_item_fkey=vsalary_head_item_fkey and end_date_effective is null and head_operator<>'Deduction' 
				and end_date_effective is null and item_part <> 'Indirect' ;
				
			
    
	if vvariable_count=0 and vcount1!=0 then 
     set	vprojected_salary  = vstructure_det_value*vproj_count;
       else 
	   set vprojected_salary=0;
     end if;
    set vvalue =(vstructure_det_value*vproj_count)+ifnull(vactaul_salary,0); 
	
	 
	 select count(*) into vcount from tax_salary_components where salary_head_item_Fkey= vsalary_head_item_fkey;
	 if vcount=0 then
	  set vvalue =ifnull(vactaul_salary,0); 	 
	 end if;
	
  
  if vcount>0 then   
  
   select tax_salary_components_pkey,tax_salary_components_name,ifnull(upper_limit,0) 
   into vtax_salary_components_pkey,vtax_salary_components_name,vupper_limit 
   from tax_salary_components where salary_head_item_Fkey= vsalary_head_item_fkey and status=1;
   
   
   
	
	if ucase(vtax_salary_components_name)='HOUSE RENT ALLOWANCE (HRA)' then
	
	select sum(availed_salary)*.4  into vhra1 from emp_tax_sal_trans where salary_head_item_fkey in 
	   (select  salary_head_item_Fkey from  tax_salary_components where ucase(tax_salary_components_name)='BASIC')
	    and emp_fkey =Pemp_fkey and end_date_effective is null;
		
		

   set vhra2=vvalue;		
		
		select ifnull(sum(tax_value),0) into vhradeclared from emp_tax_transactions where tax_heads_fkey=15 and emp_fkey= Pemp_fkey 
		           and tax_heads_details_fkey<>0 and tax_value <>0;
				  
	if ifnull(vhradeclared,0)<>0 then	
    select sum(tax_value) -(vhra1/4) into vhra3 from emp_tax_transactions where tax_heads_fkey=15 and emp_fkey= Pemp_fkey
	     and tax_heads_details_fkey<>0 and tax_value <>0;	
	  if vhra3<0 THEN
     set vhra3=0;
     end if;
	else
	set vhra3=0;
	
	end if;
               select least(vhra1,vhra2,vhra3) into vupper_limit;
			   
	
	end if;
	
	
   

   if abs(vvalue) <= ifnull(vupper_limit,0) then 
   set vtaxable_salary1=0;

   else
   set vtaxable_salary1=abs(vvalue)-ifnull(vupper_limit,0);
  
   end if;
   if vcount1=0 then
   set vvalue= vactaul_salary;
  
   end if; 
   insert into test(field1,field2,field3) values(vsalary_head_item_fkey,vactaul_salary,'10000');
    INSERT INTO emp_tax_sal_trans (emp_fkey, tax_salary_components_fkey, salary_head_item_Fkey, availed_salary, upper_limit, taxable_salary, fin_year, start_date_effective, created_by,actual_salary_recd,	projected_salary) VALUES
( Pemp_fkey,	vtax_salary_components_pkey,	vsalary_head_item_fkey,	abs(vvalue),	ifnull(vupper_limit,0),	vtaxable_salary1,	pfin_year,	current_date,Puserid, vactual_salary_recd,vprojected_salary);
  
   else
  
   set vupper_limit=0;
   set vtax_salary_components_pkey=null;
    INSERT INTO emp_tax_sal_trans (emp_fkey, tax_salary_components_fkey, salary_head_item_Fkey, availed_salary, upper_limit, taxable_salary, fin_year, start_date_effective, created_by,actual_salary_recd	,projected_salary) VALUES
( Pemp_fkey,	vtax_salary_components_pkey,	vsalary_head_item_fkey,	abs(vvalue),	vupper_limit,	vvalue,	pfin_year,	current_date,Puserid,vactual_salary_recd,vprojected_salary);

   end if;
  
 end loop start_loop ;

close structurecur ;



  BLOCK3:begin


declare vb4joinindate int;
DECLARE exit_loop1 BOOLEAN default FALSE;

 declare tax_head_cur cursor for 
      select  tax_heads_fkey, sum(ifnull(tax_value,0)) from emp_tax_transactions 
	  where tax_heads_fkey in (select tax_heads_pkey  from tax_heads where lcase(tax_type)<>'income' and tax_heads_fkey<>15 )
	  and fin_year=pfin_year and emp_fkey=Pemp_fkey and tax_heads_details_fkey=0 group by tax_heads_fkey ; 


DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;

open tax_head_cur ;
tax_head_cur_loop1: loop
    fetch tax_head_cur into vtax_heads_fkey ,vtax_head_value ;

  IF exit_loop1 THEN
	LEAVE tax_head_cur_loop1;
  END IF;
    
	
  select ifnull(attr1,100000000) into vtax_heads_limit from tax_heads where tax_heads_pkey=vtax_heads_fkey ;

         BLOCK4:begin
          DECLARE exit_loop2 BOOLEAN default FALSE;
          
         declare tax_head_detail_cur cursor for 
          select  tax_heads_details_fkey,ifnull(tax_value,0)tax_value from emp_tax_transactions where tax_heads_fkey in (select tax_heads_pkey  from tax_heads where lcase(tax_type)<>'income' )
		  and tax_heads_fkey=vtax_heads_fkey and tax_heads_details_fkey<>0 and fin_year=pfin_year and emp_fkey=Pemp_fkey and tax_heads_fkey<>15 and tax_value<>0;
                                
          DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop2 = TRUE;
           open tax_head_detail_cur ;
           tax_head_detailcur_loop1: loop
           fetch tax_head_detail_cur  into vtax_heads_details_fkey ,vtax_head_detail_value ;

           IF exit_loop2 THEN
	        LEAVE tax_head_detailcur_loop1;
           END IF;
           select ifnull(tax_heads_details2,100000000) into vtax_head_detail_limit  from tax_heads_details where tax_heads_details_pkey=vtax_heads_details_fkey ;
		   
		   if vtax_head_detail_value<>0  then
		   insert into test(field1,field2,field3,field4)values(Pemp_fkey,vtax_heads_details_fkey,vtax_head_detail_limit,vtax_head_detail_value);
			  if    ifnull(vtax_head_detail_limit,0) <= ifnull(vtax_head_detail_value,0) then 
			  
				set vtax_head_detail_balsum=ifnull(vtax_head_detail_balsum,0)+ifnull(vtax_head_detail_limit,0);
			  else 
			  
			  set vtax_head_detail_balsum=ifnull(vtax_head_detail_balsum,0)+ifnull(vtax_head_detail_value,0);
			 
			  
			  end if;
			  
		  
		  
		   end if;
		  
		 end loop tax_head_detailcur_loop1;
         close tax_head_detail_cur ;
          end BLOCK4;
		  
		  if vtax_head_detail_balsum<>0 then
		    if vtax_head_detail_balsum > vtax_heads_limit then
		   set vtax_head_value=vtax_heads_limit;
		   else 
		    set vtax_head_value=vtax_head_detail_balsum;
			end if;
		  end if;
		  
		if vtax_head_value <>0 then  

		 if  vtax_head_value > vtax_heads_limit then
		    set vtax_heads_limitsum = ifnull(vtax_heads_limitsum,0)+vtax_heads_limit;
			else
			set vtax_heads_limitsum = ifnull(vtax_heads_limitsum,0)+vtax_head_value;
		end if;	
			
		
		
		
		
		
	  
		end if; 
		
		select  sum(ifnull(tax_value,0)) into vtax_heads_totsum from emp_tax_transactions 
	  where tax_heads_fkey in (select tax_heads_pkey  from tax_heads where lcase(tax_type)<>'income' )
	  and fin_year=pfin_year and emp_fkey=Pemp_fkey and tax_heads_details_fkey=0 ;
	  		  
		
		 
		set vtax_head_detail_balsum=0;
		
     end loop tax_head_cur_loop1;
close tax_head_cur ;
  end BLOCK3;

select  ifnull(sum(ifnull(tax_value,0)),0) into vother_income from emp_tax_transactions where tax_heads_fkey in (select tax_heads_pkey  from tax_heads where lcase(tax_type)='income' )
  and tax_value<>0 and fin_year=pfin_year and emp_fkey=Pemp_fkey and tax_heads_details_fkey=0;

select sum(availed_salary)availed_salary, sum(taxable_salary)taxable_salary ,sum(actual_salary_recd)actual_salary_recd,sum(projected_salary)
    into vavailed_salary,vtaxable_salary,vsumactual_salary_recd,vsumprojected_salary
	from emp_tax_sal_trans
 where end_date_effective is null 
   and fin_year=pfin_year and emp_fkey=Pemp_fkey ;
   
   select upper(state) into vstate from branches  where branch_code in  
                      (select branch_code from emp_details where emp_Pkey=Pemp_fkey ) limit 1;
					  
					  
 
 
 if(vstate = 'TELANGANA') then
  select  ifnull(max(tax_yearly),0) into vtax_half_yearly 
   from profession_tax_slab 
     where state=vstate and salary_range_to>=(ifnull(vsumactual_salary_recd,0)+ifnull(vsumprojected_salary,0)) limit 1;
   else
   select  ifnull(max(tax_half_yearly),0)*2 into vtax_half_yearly 
   from profession_tax_slab 
     where state=vstate and salary_range_to>=(ifnull(vsumactual_salary_recd,0)+ifnull(vsumprojected_salary,0)) limit 1;
  end if;
   
   if vtax_half_yearly>0 then
   select salary_head_item_Fkey,tax_salary_components_pkey into vsalary_head_item_Fkey,vtax_salary_components_pkey  from tax_salary_components where ucase(tax_salary_components_name)='PROFESSIONAL TAX';
   
   INSERT INTO emp_tax_sal_trans (emp_fkey, tax_salary_components_fkey, salary_head_item_Fkey, availed_salary, upper_limit, taxable_salary, fin_year, start_date_effective, created_by,actual_salary_recd	,projected_salary) VALUES
( Pemp_fkey,	vtax_salary_components_pkey,	vsalary_head_item_fkey,	0,	0,	vtax_half_yearly*-1,	pfin_year,	current_date,Puserid,0,0);
 end if;
 
  set vtaxable_income=(ifnull(vother_income,0)+(ifnull(vtaxable_salary,0)-abs(ifnull(vtax_heads_limitsum,0))))-ifnull(vtax_half_yearly,0) ;
 
 select ucase(classification),TIMESTAMPDIFF(YEAR, date_of_birth, CURDATE()) into vclassification,vage from emp_details where emp_pkey=Pemp_fkey;
   
  
	set vstanderd_deduction=50000;
	set vtaxable_income=vtaxable_income-vstanderd_deduction;
	if vage >60 THEN
	  if vtaxable_income >=300000 then	
			set vbaselimit=300000;
			set vnewtaxable_income=vtaxable_income-200000;
		 if  vnewtaxable_income >200000 then 
		   set vfirst_portion = 200000;
		   set vnewtaxable_income=vtaxable_income-500000;
		   set vtax_yearly=vfirst_portion*.05;
		   set vfirst_portion_tax=vfirst_portion*.05;
		 else
		 if (vtaxable_income-200000)>0 then
		  set vfirst_portion = vtaxable_income-200000;
		  set vnewtaxable_income=0;
		  set vtax_yearly=vfirst_portion*.05;
		  set vfirst_portion_tax=vfirst_portion*.05;
		  else 
		  set vfirst_portion = 0 ;
		  set vnewtaxable_income=0;
		   set vfirst_portion_tax=0;
		  end if;
		  end if; 

		 if  vnewtaxable_income > 500000 then 
		   set vsecond_portion = 500000;
		   set vnewtaxable_income=vtaxable_income-1000000;
			set vtax_yearly=vtax_yearly+(vsecond_portion*.2);
			set vsecond_portion_tx=(vsecond_portion*.2);
		 else
		 
		   if (vtaxable_income-500000)>0 then
			set vsecond_portion = vtaxable_income-500000;
			set vnewtaxable_income=0;
			set vtax_yearly=vtax_yearly+(vsecond_portion*.2);
			set vsecond_portion_tx=(vsecond_portion*.2);
			else 
			 set vsecond_portion = 0;
			 set vnewtaxable_income=0;
			 set vsecond_portion_tx=0;
			end if;
		  end if;
		  
		  
		   if  vnewtaxable_income >=1 then 
		   set vthird_portion = vnewtaxable_income;
			set vtax_yearly=vtax_yearly+(vthird_portion*.3);
			set vthird_portion_tx=(vthird_portion*.3);
			else 
			set vthird_portion =0;
			set vthird_portion_tx=0;
		   end if;
		 else
		  set vbaselimit=vtaxable_income-250000;
		  set vtax_yearly=0;
		  end if;
	else
	if vtaxable_income >=250000 then	
		set vbaselimit=250000;
		set vnewtaxable_income=vtaxable_income-250000;
	 if  vnewtaxable_income >250000 then 
	   set vfirst_portion = 250000;
	   set vnewtaxable_income=vtaxable_income-500000;
	   set vtax_yearly=vfirst_portion*.05;
	    set vfirst_portion_tax=vfirst_portion*.05;
	 else
	 if (vtaxable_income-250000)>0 then
	  set vfirst_portion = vtaxable_income-250000;
	  set vnewtaxable_income=0;
	  set vtax_yearly=vfirst_portion*.05;
	   set vfirst_portion_tax=vfirst_portion*.05;
	  else 
	  set vfirst_portion = 0 ;
	  set vnewtaxable_income=0;
	   set vfirst_portion_tax=0;
	  end if;
	  end if; 

	 if  vnewtaxable_income > 500000 then 
	   set vsecond_portion = 500000;
	   set vnewtaxable_income=vtaxable_income-1000000;
		set vtax_yearly=vtax_yearly+(vsecond_portion*.2);
		set vsecond_portion_tx=(vsecond_portion*.2);
	 else
	 
	   if (vtaxable_income-500000)>0 then
		set vsecond_portion = vtaxable_income-500000;
		set vnewtaxable_income=0;
		set vtax_yearly=vtax_yearly+(vsecond_portion*.2);
		set vsecond_portion_tx=(vsecond_portion*.2);
		else 
		 set vsecond_portion = 0;
		 set vnewtaxable_income=0;
		 set vsecond_portion_tx=0;
		end if;
	  end if;
	  
	  
	   if  vnewtaxable_income >=1 then 
	   set vthird_portion = vnewtaxable_income;
		set vtax_yearly=vtax_yearly+(vthird_portion*.3);
		set vthird_portion_tx=(vthird_portion*.3);
		else 
		set vthird_portion =0;
		set vthird_portion_tx=0;
	   end if;
	 else
	  set vbaselimit=vtaxable_income-250000;
	  set vtax_yearly=0;
	  end if;
 
   end if;
 
  
	
	if vtaxable_income between 5000000 and 10000000 then 
	set vsurcharge= vtax_yearly*.1;
	elseif vtaxable_income >10000000 then
	set vsurcharge= vtax_yearly*.15;
	else
	set vsurcharge=0;
	end if;
	
	set vcess=(vtax_yearly+vsurcharge)*.04 ;
	
	if vtaxable_income <= 500000 then
	 if vtax_yearly >0 then
     set vrebate = 12500;
	
	
	set vcess=0;
	 else
	  set vrebate = 0;
	 end if;
	else
     set vrebate = 0 ;
    end if;
   select  sum(abs(salary_amount)) into vtaxdeducted_sum from emp_salary_slip where emp_fkey= Pemp_fkey
 and end_date_effective is null  and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	 and payroll_master_fkey in (select payroll_master_pkey from payroll_master where action in ('Approved','Processed'))
     and ucase(salary_head_item_desc) = 'TDS' group by emp_fkey ; 
	if Pcompany_code='' then
	set vproj_count=vproj_count+1;
	else 
	set vproj_count=vproj_count;
	end if;
    set vtax_monthly= ((vtax_yearly+ifnull(vcess,0)+ifnull(vsurcharge,0))-round(ifnull(vtaxdeducted_sum,0),0))/ifnull(vproj_count,1) ;
	
	if vtax_monthly<=0 then
	  set vtax_monthly=0;
	end if;  

	
 select count(*) into vtaxsumcount from emp_tax_sal_trans_sum where emp_fkey=Pemp_fkey and fin_year=pfin_year and end_date_effective is null;
  if vtaxsumcount<>0 then
  update emp_tax_sal_trans_sum set end_date_effective=current_date where end_date_effective is null;
  end if;
 INSERT INTO emp_tax_sal_trans_sum (emp_fkey,actual_salary,availed_salary,hra1,hra2,hra3,declared_deduction,taxable_salary, taxable_income, other_income, tax_heads_limitsum, 
     first_portion, second_portion, third_portion, tax_yearly, tax_monthly_proj, fin_year, start_date_effective, created_by,surcharge,cess,rebate,standerd_deduction,
	 first_portion_tax,second_portion_tx,third_portion_tx)
VALUES (Pemp_fkey,vsumactual_salary_recd,vsumprojected_salary,vhra1,vhra2,vhra3,vtax_heads_totsum,vtaxable_salary, vtaxable_income , vother_income, vtax_heads_limitsum,
     vfirst_portion, vsecond_portion, vthird_portion, vtax_yearly, vtax_monthly, pfin_year, current_date, Puserid,vsurcharge,vcess,vrebate,vstanderd_deduction,
	 vfirst_portion_tax,vsecond_portion_tx,vthird_portion_tx);
 
 
 select count(*) into vreturn from emp_tax_sal_trans where emp_fkey=Pemp_fkey
 and end_date_effective is null;
if vreturn > 0 then
return 1;
else
return 0;
end if;
end;;

DROP FUNCTION IF EXISTS `tax_salary_distribution_new_fn`;;
CREATE FUNCTION `tax_salary_distribution_new_fn` (`Pcompany_code` varchar(30), `Pemp_fkey` int, `pfin_year` varchar(30), `Puserid` varchar(30)) RETURNS int(11) LANGUAGE SQL
READS SQL DATA
    DETERMINISTIC
begin
declare vreturn int;
declare i int;
declare vworking_time int ;
declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
