declare vsalary_head_item_desc varchar(100);
declare vformula_value float;
declare rem_salary_head_item_fkey int;
declare vdedcount int;
declare vhead_operator varchar(30);
declare vhead_type varchar(30);
declare vitem_part varchar(30);
declare vcount int;
declare vtax_salary_components_pkey int; 
declare vtax_salary_components_name varchar(100);
declare vhra1 float;
declare vhra2 float;
declare vhra3 float;
declare vavailed_salary float;
declare vtaxable_salary float ;
declare vupper_limit float;
declare vtaxable_income float;
declare vtaxable_income_new float;
declare vtax_heads_limitsum float;
declare vtax_yearly float;
declare vtax_monthly float;
declare vother_income float;
declare vfirst_portion float;
declare vsecond_portion float;
declare vthird_portion float ;
declare vhradeclared float;
declare vtaxable_salary1 float;
declare vtax_head_value  float;
declare vtax_heads_limit   float;
declare vtax_heads_fkey int;
declare vtax_heads_details_fkey int;
declare vtax_head_detail_value float ;
declare vtax_head_detail_limit  float;
declare vtax_head_detail_sum float;
declare vtax_head_detail_balsum float;
declare vtaxsumcount int;
declare vstart_month date ;
declare vend_month date;
declare vactaul_salary float;
declare vproj_count int;
declare vactual_salary_recd float;
declare vprojected_salary float;
declare vbaselimit float;
declare vclassification varchar(20);
declare vsumprojected_salary float;
declare vtaxdeducted_sum float;
declare vsumactual_salary_recd float;
declare vactual_count int;
declare vjoining_date date;
declare vtotalmonth int;
declare vtax_heads_totsum float;
declare vsurcharge float;
declare vcess float;
declare vsurcharge_perc float;
declare vcess_perc float;
declare vrebate float;
declare vnewtaxable_income float;
declare vstanderd_deduction float;
declare vtax_half_yearly int;
declare vvariable_count int;
declare vcount1 int;
declare vforth_portion float;
declare vfifth_portion float; 
declare vsixth_portion float;
declare vseventh_portion float;
declare vbrcount int;
declare vslab_from int;
declare vslab_to int;
declare vslab_rate int;
declare vfirst_portion_tax  float; declare vsecond_portion_tax float; declare vthird_portion_tax float; declare vfourth_portion_tax float; declare vfifth_portion_tax float; declare vsixth_portion_tax float; declare vseventh_portion_tax float;
declare vnon_taxable_threshold float;
declare vmarginal_relief float;

DECLARE exit_loop BOOLEAN default FALSE;

declare structurecur cursor for 
select salary_head_item_fkey,
salary_head_item_desc,
abs(structure_det_value),head_operator,head_type,item_part
from emp_salary_structure where emp_fkey=Pemp_fkey and end_date_effective is null and head_operator<>'Deduction' and item_part <> 'Indirect' 
union
select salary_head_item_fkey,salary_head_item_desc,sum(abs(salary_amount)),head_operator,head_type,item_part
from emp_salary_slip where emp_fkey=Pemp_fkey and end_date_effective is null and head_operator<>'Deduction' and item_part <> 'Indirect'  and  month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')	
and salary_head_item_fkey not in (select salary_head_item_fkey from emp_salary_structure where emp_fkey=Pemp_fkey and end_date_effective is null 
and head_operator<>'Deduction' and item_part <> 'Indirect' ) group by salary_head_item_fkey ;

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;

set vfin_year=pfin_year;

select count(*) into vdistribution_cnt  from emp_tax_sal_trans_new where emp_fkey=Pemp_fkey and end_date_effective is null;

if vdistribution_cnt <>0 then
	update emp_tax_sal_trans_new set end_date_effective =current_date,modified_by=Puserid where emp_fkey=Pemp_fkey and end_date_effective is null;
end if;

select start_month,end_month into vstart_month,vend_month  from  fin_year where fin_year=pfin_year and vattr1=1
and is_current_finyear='Y' and status=1
and branch_code in (select branch_code from emp_details where emp_Pkey=Pemp_fkey);

open structurecur;

start_loop: loop
	
	fetch structurecur into vsalary_head_item_fkey, vsalary_head_item_desc, vstructure_det_value, vhead_operator, vhead_type, vitem_part;
	
	IF exit_loop THEN        LEAVE start_loop;     END IF;
	
	select count(distinct month_year) into vactual_count from emp_salary_slip where
	emp_fkey=Pemp_fkey and end_date_effective is null and head_type <> 'Arrear' and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	and ucase(salary_head_item_desc) not in ('SALARY ADVANCE','LOANS','TDS DEDUCTED');
	
	select  sum(abs(salary_amount)) into vactaul_salary from emp_salary_slip where salary_head_item_Fkey=vsalary_head_item_fkey 
	and emp_fkey=Pemp_fkey and end_date_effective is null and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	and ucase(salary_head_item_desc) not in ('SALARY ADVANCE','LOANS','TDS DEDUCTED');
	
	select date_format(joining_date,'%Y-%m-%d') into vjoining_date from emp_proff  where emp_fkey=Pemp_fkey;
	
	if vjoining_date > vstart_month then
		
		set vtotalmonth= TIMESTAMPDIFF(MONTH,vjoining_date, vend_month);
		
	else
		
		set vtotalmonth= TIMESTAMPDIFF(MONTH,vstart_month, vend_month);
		
	end if;
	
	set vproj_count=abs(vtotalmonth)+1 - ifnull(vactual_count,0);
	insert into test (field1,field2,field3,field4,field5) values ('Projected_count',Pemp_fkey,vtotalmonth,vactual_count,vproj_count);
    set vactual_salary_recd= ifnull(vactaul_salary,0);
	
	select count(*) into vvariable_count from salary_heads
	where head_occurance ='VARIABLE' and  head_pkey  in (select head_fkey from salary_head_items where salary_head_item_pkey=vsalary_head_item_fkey );
	
	select count(*) into vcount1
	from emp_salary_structure where emp_fkey=Pemp_fkey and salary_head_item_fkey=vsalary_head_item_fkey 
	and head_operator<>'Deduction' and end_date_effective is null and item_part <> 'Indirect';
	
	if vvariable_count=0 and vcount1!=0 then 
		set	vprojected_salary  = vstructure_det_value*vproj_count;
	else 
		set vprojected_salary=0;
	end if;
	
	set vvalue =(vstructure_det_value*vproj_count)+ifnull(vactaul_salary,0); 
	
	select count(*) into vcount from tax_salary_components where salary_head_item_Fkey= vsalary_head_item_fkey;
	
	if vcount=0 then
		set vvalue =ifnull(vactaul_salary,0); 	 
	end if;
	
	if vcount>0 then   
		
		select tax_salary_components_pkey,tax_salary_components_name,ifnull(upper_limit,0) 
		into vtax_salary_components_pkey,vtax_salary_components_name,vupper_limit 
		from tax_salary_components where salary_head_item_Fkey= vsalary_head_item_fkey and status=1;
		
		INSERT INTO emp_tax_sal_trans_new (emp_fkey, tax_salary_components_fkey, salary_head_item_Fkey, availed_salary, upper_limit, taxable_salary, fin_year, start_date_effective, created_by,actual_salary_recd,	projected_salary) VALUES
		( Pemp_fkey,	vtax_salary_components_pkey,	vsalary_head_item_fkey,	abs(vvalue),	ifnull(vupper_limit,0),	abs(vvalue),	pfin_year,	current_date,Puserid, vactual_salary_recd,vprojected_salary);
		
	else
		
		set vupper_limit=0;
		set vtax_salary_components_pkey=null;
		
		INSERT INTO emp_tax_sal_trans_new (emp_fkey, tax_salary_components_fkey, salary_head_item_Fkey, availed_salary, upper_limit, taxable_salary, fin_year, start_date_effective, created_by,actual_salary_recd	,projected_salary) VALUES
		( Pemp_fkey,	vtax_salary_components_pkey,	vsalary_head_item_fkey,	abs(vvalue),	vupper_limit,	vvalue,	pfin_year,	current_date,Puserid,vactual_salary_recd,vprojected_salary);
		
	end if;
	
end loop start_loop;

close structurecur;

BLOCK3:begin


declare vb4joinindate int;
DECLARE exit_loop1 BOOLEAN default FALSE;

 declare tax_head_cur cursor for
      select  tax_heads_fkey, sum(ifnull(tax_value,0)) from emp_tax_transactions 
	  where tax_heads_fkey in (select tax_heads_pkey  from tax_heads where lcase(tax_type)<>'income') and tax_heads_fkey<>15 
	  and fin_year=pfin_year and emp_fkey=Pemp_fkey and tax_heads_details_fkey=0 group by tax_heads_fkey ; 


DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;

open tax_head_cur ;
tax_head_cur_loop1: loop
    fetch tax_head_cur into vtax_heads_fkey ,vtax_head_value ;

  IF exit_loop1 THEN
	LEAVE tax_head_cur_loop1;
  END IF;
    
	
  select ifnull(attr1,100000000) into vtax_heads_limit from tax_heads where tax_heads_pkey=vtax_heads_fkey ;

         BLOCK4:begin
          DECLARE exit_loop2 BOOLEAN default FALSE;
          
         declare tax_head_detail_cur cursor for 
          select  tax_heads_details_fkey,ifnull(tax_value,0) tax_value from emp_tax_transactions where tax_heads_fkey in (select tax_heads_pkey  from tax_heads where lcase(tax_type)<>'income' )
		  and tax_heads_fkey=vtax_heads_fkey and tax_heads_details_fkey<>0 and fin_year=pfin_year and emp_fkey=Pemp_fkey and tax_heads_fkey<>15 and tax_value<>0;
                                
          DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop2 = TRUE;
           open tax_head_detail_cur ;
           tax_head_detailcur_loop1: loop
           fetch tax_head_detail_cur  into vtax_heads_details_fkey ,vtax_head_detail_value ;

           IF exit_loop2 THEN
	        LEAVE tax_head_detailcur_loop1;
           END IF;
           select ifnull(tax_heads_details2,100000000) into vtax_head_detail_limit  from tax_heads_details where tax_heads_details_pkey=vtax_heads_details_fkey ;
		   
		   if vtax_head_detail_value<>0  then
		 
			  if    ifnull(vtax_head_detail_limit,0) <= ifnull(vtax_head_detail_value,0) then 
			  
				set vtax_head_detail_balsum=ifnull(vtax_head_detail_balsum,0)+ifnull(vtax_head_detail_limit,0);
			  else 
			  
			  set vtax_head_detail_balsum=ifnull(vtax_head_detail_balsum,0)+ifnull(vtax_head_detail_value,0);
			 
			  
			  end if;
			  
		  
		  
		   end if;
		  
		 end loop tax_head_detailcur_loop1;
         close tax_head_detail_cur ;
          end BLOCK4;
		  
		  if vtax_head_detail_balsum<>0 then
		    if vtax_head_detail_balsum > vtax_heads_limit then
		   set vtax_head_value=vtax_heads_limit;
		   else 
		    set vtax_head_value=vtax_head_detail_balsum;
			end if;
		  end if;
		  
		if vtax_head_value <>0 then  

		 if  vtax_head_value > vtax_heads_limit then
		    set vtax_heads_limitsum = ifnull(vtax_heads_limitsum,0)+vtax_heads_limit;
			else
			set vtax_heads_limitsum = ifnull(vtax_heads_limitsum,0)+vtax_head_value;
		end if;	
			
		set vtax_heads_limitsum=0;
		
		
		
		
  
	  
		end if; 
		
		select  sum(ifnull(tax_value,0)) into vtax_heads_totsum from emp_tax_transactions
	  where tax_heads_fkey in (select tax_heads_pkey  from tax_heads where lcase(tax_type)<>'income')
	  and fin_year=pfin_year and emp_fkey=Pemp_fkey and tax_heads_details_fkey=0;
	  		  
		set vtax_heads_totsum=0;
		 
		set vtax_head_detail_balsum=0;
		
     end loop tax_head_cur_loop1;
close tax_head_cur ;
  end BLOCK3;

BLOCK5:begin

          DECLARE exit_loop3 BOOLEAN default FALSE;
          
         declare tax_head_detail_cur cursor for 
       
           select tax_heads_details_pkey,ifnull(tax_value,0) tax_value from tax_heads_details 
         left join tax_heads on (tax_heads.tax_heads_pkey = tax_heads_details.tax_heads_fkey)
         left join emp_tax_transactions on (emp_tax_transactions.tax_heads_details_fkey =tax_heads_details.tax_heads_details_pkey)
         WHERE  tax_heads.tax_name Like '%Perquisite Sec 17(2)%' AND status = 1 and fin_year=pfin_year and emp_fkey=Pemp_fkey and tax_value<>0;
		 
          DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop3 = TRUE;
		  
           open tax_head_detail_cur ;
           tax_head_detailcur_loop1: loop
           fetch tax_head_detail_cur  into vtax_heads_details_fkey ,vtax_head_detail_value ;
			
           IF exit_loop3 THEN
	        LEAVE tax_head_detailcur_loop1;
           END IF;
           select ifnull(tax_heads_details2,100000000) into vtax_head_detail_limit  from tax_heads_details where tax_heads_details_pkey=vtax_heads_details_fkey ;
		   
		   if vtax_head_detail_value<>0  then
		 
			  if    ifnull(vtax_head_detail_limit,0) <= ifnull(vtax_head_detail_value,0) then 
			  
				set vtax_head_detail_sum=ifnull(vtax_head_detail_sum,0)+ifnull(vtax_head_detail_limit,0);
			  else 
			  
			  set vtax_head_detail_sum=ifnull(vtax_head_detail_sum,0)+ifnull(vtax_head_detail_value,0);
			 
			  
			  end if;
			  
		  
		  
		   end if;
		  
		 end loop tax_head_detailcur_loop1;
         close tax_head_detail_cur ;
end BLOCK5;
 
 select ifnull(sum(ifnull(tax_value,0)),0) into vother_income from emp_tax_transactions where tax_heads_fkey in (select tax_heads_pkey  from tax_heads where lcase(tax_type)='income' )
 and tax_value<>0 and fin_year=pfin_year and emp_fkey=Pemp_fkey ;
 
 select sum(availed_salary) availed_salary, sum(taxable_salary) taxable_salary ,sum(actual_salary_recd) actual_salary_recd,sum(projected_salary)
    into vavailed_salary,vtaxable_salary,vsumactual_salary_recd,vsumprojected_salary
	from emp_tax_sal_trans_new
 where end_date_effective is null 
   and fin_year=pfin_year and emp_fkey=Pemp_fkey
     and salary_head_item_Fkey not in (select salary_head_item_pkey  from salary_head_items where
  ucase(item)='PROFESSIONAL TAX');
 
 select ucase(classification) into vclassification from emp_details where emp_pkey=Pemp_fkey;
 
 set vtaxable_income = 0;
 
 set vtaxable_income=(ifnull(vother_income,0)+(ifnull(vtaxable_salary,0))-(ifnull(vtax_head_detail_sum,0)))  ;
 
 set vtax_yearly = 0;
 set vfirst_portion = 0;
 set vsecond_portion = 0;
 set vthird_portion = 0;
 set vforth_portion = 0;
 set vfifth_portion = 0;
 set vsixth_portion = 0;
 set vseventh_portion = 0;
 set vfirst_portion_tax = 0;
 set vsecond_portion_tax = 0;
 set vthird_portion_tax = 0;
 set vfourth_portion_tax = 0;
 set vfifth_portion_tax = 0;
 set vsixth_portion_tax = 0;
 set vseventh_portion_tax =0;
 
 select std_deduction into vstanderd_deduction 
 from income_tax_slab 
 where fin_year = vfin_year 
   and regime = 'NEW' 
   and salary_range_to >= vtaxable_income 
   limit 1;
 
 set vtaxable_income = vtaxable_income - vstanderd_deduction;
 
 set vnewtaxable_income = vtaxable_income;
 
  select rebate into vrebate
 from income_tax_slab 
 where fin_year = vfin_year 
   and regime = 'NEW' 
   and salary_range_from <= vtaxable_income
 order by salary_range_from desc
 limit 1;
 
if vrebate = 0 then
 
 select salary_range_to, tax_yearly_perc 
 into vbaselimit, @first_slab_rate
 from income_tax_slab 
 where fin_year = vfin_year 
   and regime = 'NEW' 
   and salary_range_from = 0 
   limit 1;
   
 if vtaxable_income > vbaselimit then
   set vfirst_portion = vbaselimit;
   set vfirst_portion_tax = vfirst_portion * (@first_slab_rate / 100);
   set vtax_yearly = vtax_yearly + vfirst_portion_tax;
   set vnewtaxable_income = vtaxable_income - vbaselimit;
 else
   set vfirst_portion = vtaxable_income;
   set vfirst_portion_tax = vfirst_portion * (@first_slab_rate / 100);
   set vtax_yearly = vtax_yearly + vfirst_portion_tax;
   set vnewtaxable_income = 0;
 end if;
 
 if vnewtaxable_income > 0 then
   select salary_range_from, salary_range_to, tax_yearly_perc 
   into vslab_from, vslab_to, vslab_rate
   from income_tax_slab 
   where fin_year = vfin_year 
     and regime = 'NEW' 
     and salary_range_from > vbaselimit
   order by salary_range_from 
   limit 1;
   
   if vtaxable_income > vslab_to then
     set vsecond_portion = vslab_to - vslab_from + 1;
     set vsecond_portion_tax = vsecond_portion * (vslab_rate / 100);
     set vtax_yearly = vtax_yearly + vsecond_portion_tax;
     set vnewtaxable_income = vtaxable_income - vslab_to;
   else
     set vsecond_portion = vtaxable_income - vslab_from + 1;
     set vsecond_portion_tax = vsecond_portion * (vslab_rate / 100);
     set vtax_yearly = vtax_yearly + vsecond_portion_tax;
     set vnewtaxable_income = 0;
   end if;
 end if;
 
 if vnewtaxable_income > 0 then
   select salary_range_from, salary_range_to, tax_yearly_perc 
   into vslab_from, vslab_to, vslab_rate
   from income_tax_slab 
   where fin_year = vfin_year 
     and regime = 'NEW' 
     and salary_range_from > (select min(salary_range_to) from income_tax_slab 
                            where fin_year = vfin_year and regime = 'NEW' and salary_range_from > vbaselimit
                            order by salary_range_from limit 1)
   order by salary_range_from 
   limit 1;
   
   if vtaxable_income > vslab_to then
     set vthird_portion = vslab_to - vslab_from + 1;
     set vthird_portion_tax = vthird_portion * (vslab_rate / 100);
     set vtax_yearly = vtax_yearly + vthird_portion_tax;
     set vnewtaxable_income = vtaxable_income - vslab_to;
   else
     set vthird_portion = vtaxable_income - vslab_from + 1;
     set vthird_portion_tax = vthird_portion * (vslab_rate / 100);
     set vtax_yearly = vtax_yearly + vthird_portion_tax;
     set vnewtaxable_income = 0;
   end if;
 end if;
 
 if vnewtaxable_income > 0 then
   select salary_range_from, salary_range_to, tax_yearly_perc 
   into vslab_from, vslab_to, vslab_rate
   from income_tax_slab 
   where fin_year = vfin_year 
     and regime = 'NEW' 
     and salary_range_from > (select salary_range_to from income_tax_slab 
                            where fin_year = vfin_year and regime = 'NEW' 
                            and salary_range_from > (select min(salary_range_to) from income_tax_slab 
                                                   where fin_year = vfin_year and regime = 'NEW' and salary_range_from > vbaselimit
                                                   order by salary_range_from limit 1)
                            order by salary_range_from limit 1)
   order by salary_range_from 
   limit 1;
   
   if vtaxable_income > vslab_to then
     set vforth_portion = vslab_to - vslab_from + 1;
     set vfourth_portion_tax = vforth_portion * (vslab_rate / 100);
     set vtax_yearly = vtax_yearly + vfourth_portion_tax;
     set vnewtaxable_income = vtaxable_income - vslab_to;
   else
     set vforth_portion = vtaxable_income - vslab_from + 1;
     set vfourth_portion_tax = vforth_portion * (vslab_rate / 100);
     set vtax_yearly = vtax_yearly + vfourth_portion_tax;
     set vnewtaxable_income = 0;
   end if;
 end if;
 
 if vnewtaxable_income > 0 then
   select salary_range_from, salary_range_to, tax_yearly_perc 
   into vslab_from, vslab_to, vslab_rate
   from income_tax_slab 
   where fin_year = vfin_year 
     and regime = 'NEW' 
     and salary_range_from > (select salary_range_to from income_tax_slab 
                            where fin_year = vfin_year and regime = 'NEW' 
                            and salary_range_from > (select salary_range_to from income_tax_slab 
                                                   where fin_year = vfin_year and regime = 'NEW' 
                                                   and salary_range_from > (select min(salary_range_to) from income_tax_slab 
                                                                          where fin_year = vfin_year and regime = 'NEW' and salary_range_from > vbaselimit
                                                                          order by salary_range_from limit 1)
                                                   order by salary_range_from limit 1)
                            order by salary_range_from limit 1)
   order by salary_range_from 
   limit 1;
   
   if vtaxable_income > vslab_to then
     set vfifth_portion = vslab_to - vslab_from + 1;
     set vfifth_portion_tax = vfifth_portion * (vslab_rate / 100);
     set vtax_yearly = vtax_yearly + vfifth_portion_tax;
     set vnewtaxable_income = vtaxable_income - vslab_to;
   else
     set vfifth_portion = vtaxable_income - vslab_from + 1;
     set vfifth_portion_tax = vfifth_portion * (vslab_rate / 100);
     set vtax_yearly = vtax_yearly + vfifth_portion_tax;
     set vnewtaxable_income = 0;
   end if;
 end if;
 
if vfin_year >= '2025' then
 
 if vnewtaxable_income > 0 then
   select salary_range_from, salary_range_to, tax_yearly_perc 
   into vslab_from, vslab_to, vslab_rate
   from income_tax_slab 
   where fin_year = vfin_year 
     and regime = 'NEW' 
     and salary_range_from > (select salary_range_to from income_tax_slab 
                            where fin_year = vfin_year and regime = 'NEW' 
                            and salary_range_from > (select salary_range_to from income_tax_slab 
                                                   where fin_year = vfin_year and regime = 'NEW' 
                                                   and salary_range_from > (select salary_range_to from income_tax_slab 
																		  where fin_year = vfin_year and regime = 'NEW' 
																		  and salary_range_from > (select min(salary_range_to) from income_tax_slab 
																								 where fin_year = vfin_year and regime = 'NEW' and salary_range_from > vbaselimit
																								 order by salary_range_from limit 1)
																		  order by salary_range_from limit 1)
                                                   order by salary_range_from limit 1)
                            order by salary_range_from limit 1)
   order by salary_range_from 
   limit 1;
   
   if vtaxable_income > vslab_to then
     set vsixth_portion = vslab_to - vslab_from + 1;
     set vsixth_portion_tax = vsixth_portion * (vslab_rate / 100);
     set vtax_yearly = vtax_yearly + vsixth_portion_tax;
     set vnewtaxable_income = vtaxable_income - vslab_to;
   else
     set vsixth_portion = vtaxable_income - vslab_from + 1;
     set vsixth_portion_tax = vsixth_portion * (vslab_rate / 100);
     set vtax_yearly = vtax_yearly + vsixth_portion_tax;
     set vnewtaxable_income = 0;
   end if;
 end if;
 
 if vnewtaxable_income > 0 then
   select tax_yearly_perc into vslab_rate
   from income_tax_slab 
   where fin_year = vfin_year 
     and regime = 'NEW' 
   order by salary_range_from desc 
   limit 1;
   
   set vseventh_portion = vnewtaxable_income;
   set vseventh_portion_tax = vseventh_portion * (vslab_rate / 100);
   set vtax_yearly = vtax_yearly + vseventh_portion_tax;
 end if;
 
else
 
 if vnewtaxable_income > 0 then
   select tax_yearly_perc into vslab_rate
   from income_tax_slab 
   where fin_year = vfin_year 
     and regime = 'NEW' 
   order by salary_range_from desc 
   limit 1;
   
   set vsixth_portion = vnewtaxable_income;
   set vsixth_portion_tax = vsixth_portion * (vslab_rate / 100);
   set vtax_yearly = vtax_yearly + vsixth_portion_tax;
 end if;
 
end if;

select max(salary_range_to) into vnon_taxable_threshold 
from income_tax_slab 
where rebate > 0 and fin_year = vfin_year and regime = 'NEW' and status = 1;

 if vtaxable_income > vnon_taxable_threshold then
  if (vtax_yearly - (vtaxable_income - vnon_taxable_threshold)) > 0 then
    set vmarginal_relief = vtax_yearly - (vtaxable_income - vnon_taxable_threshold);
    set vtax_yearly = vtaxable_income - vnon_taxable_threshold;
  else
    set vmarginal_relief = 0;
  end if;
 end if;

 select max(surcharge_perc) into vsurcharge_perc 
 from income_tax_slab 
 where fin_year = vfin_year 
   and regime = 'NEW' 
   and salary_range_from <= vtaxable_income 
   and salary_range_to >= vtaxable_income;
 
 set vsurcharge = vtax_yearly * (vsurcharge_perc / 100);
 
 select cess_perc into vcess_perc 
 from income_tax_slab 
 where fin_year = vfin_year 
   and regime = 'NEW' 
   and salary_range_to >= vtaxable_income 
   limit 1;
 
 set vcess = (vtax_yearly + ifnull(vsurcharge,0)) * (vcess_perc / 100);
 
 elseif vrebate <> 0 then
	 set vcess = 0;
 end if;

   select  sum(abs(salary_amount)) into vtaxdeducted_sum from emp_salary_slip where emp_fkey= Pemp_fkey
 and end_date_effective is null  and month_year between date_format(vstart_month,'%Y-%m') and date_format(vend_month,'%Y-%m')
	 and payroll_master_fkey in (select payroll_master_pkey from payroll_master where action in ('Approved','Processed'))
     and ucase(salary_head_item_desc) = 'TDS' group by emp_fkey ; 
	if Pcompany_code='' then
	set vproj_count=vproj_count+1;
	else 
	set vproj_count=vproj_count;
	end if;
    set vtax_monthly= ((vtax_yearly+ifnull(vcess,0)+ifnull(vsurcharge,0)-round(ifnull(vtaxdeducted_sum,0),0))/ifnull(vproj_count,1)) ;
 insert into test (field1,field2,field3,field4,field5) values ('tds',(vtax_yearly+vcess+vsurcharge),vtaxdeducted_sum,vproj_count,vtax_monthly);
	if vtax_monthly<=0 then
	  set vtax_monthly=0;
	end if;  

	
 select count(*) into vtaxsumcount from emp_tax_sal_trans_sum_new where emp_fkey=Pemp_fkey and fin_year=pfin_year and end_date_effective is null;
  if vtaxsumcount<>0 then
  update emp_tax_sal_trans_sum_new set end_date_effective=current_date where end_date_effective is null;
  end if;
  
 INSERT INTO emp_tax_sal_trans_sum_new (emp_fkey,actual_salary,availed_salary,hra1,hra2,hra3,declared_deduction,taxable_salary, taxable_income, other_income, tax_heads_limitsum, 
     first_portion, second_portion, third_portion, forth_portion,fifth_portion,sixth_portion,seventh_portion,tax_yearly, tax_monthly_proj, fin_year, start_date_effective, created_by,surcharge,cess,rebate,marginal_relief,standerd_deduction,
	 first_portion_tax,second_portion_tax,third_portion_tax,fourth_portion_tax,fifth_portion_tax,sixth_portion_tax,seventh_portion_tax)
VALUES (Pemp_fkey,vsumactual_salary_recd,vsumprojected_salary,vhra1,vhra2,vhra3,vtax_heads_totsum,vtaxable_salary, vtaxable_income , vother_income, vtax_heads_limitsum,
     vfirst_portion, vsecond_portion, vthird_portion,vforth_portion,vfifth_portion,vsixth_portion,vseventh_portion, vtax_yearly, vtax_monthly, pfin_year, current_date, Puserid,vsurcharge,vcess,vrebate,vmarginal_relief,vstanderd_deduction,
	 vfirst_portion_tax,vsecond_portion_tax,vthird_portion_tax,vfourth_portion_tax,vfifth_portion_tax,vsixth_portion_tax,vseventh_portion_tax);
 
 
 select count(*) into vreturn from emp_tax_sal_trans_new where emp_fkey=Pemp_fkey
 and end_date_effective is null;
if vreturn > 0 then
return 1;
else
return 0;
end if;
end;;

DROP PROCEDURE IF EXISTS `tax_salary_process_prc`;;
CREATE PROCEDURE `tax_salary_process_prc` (IN `pmonth` varchar(20), IN `pbranch_code` varchar(30), IN `pemp_pkey` int, IN `ppayroll_master_pkey` int, IN `puser_id` varchar(30), OUT `perr_msg` varchar(500))
begin
 
declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vDeviceId int;
declare vjoining_date	  date;
declare vemp_company_id	varchar(30);	 
declare vemp_type	varchar(30);	 
declare vdesignation	varchar(30); 
declare vemp_dept	varchar(30);
declare vemp_grade	varchar(30);
declare vemp_vertical   varchar(30);
declare vemp_branch varchar(30);	 
declare vHOLIDAY_GROUP_ID int;	 
declare vLEAVEPOLICY_GROUP_ID int;
declare vday_time_seq  int;
declare vpresant_total float;
declare vleave_total float;
declare vlop_total float;
declare vemp_anual_ctc float;
declare vemp_monthly_ctc float ;
declare vemp_structure_id int ;
declare vprorate_code int;
declare vprorate_desc varchar(50);
declare vdefined_structure_for varchar(50);
declare vsalary_head_item_fkey int;
declare vsalary_head_item_desc varchar(100);
declare vstructure_det_value float;
declare vhead_operator varchar(20);
declare vhead_type varchar(25);
declare vitem_part varchar(25);
declare vstructure_id int;
declare vemp_salary float;
declare vday_count int ;
declare vattendance_date date;
declare vmonthly_att_fromdate date;
declare vmonthly_att_todate date;
declare vworking_day int;
declare vweekoff_day int;
declare vexistcount int;
declare vmonthly_amount float;
declare vindirect_amount float;
declare vtotal_deduction float;
declare vtotal_variables float;
declare vsalary_rate float;
declare vsalary_amount float;
declare vmonth date;
declare vrate float;
declare vholiday_count  int;
declare vfinyear varchar(20);
declare vtds float;
declare vtax float;
declare vvalue float;
declare vtax_include varchar(30);
declare vtaxable_income float;
DECLARE exit_loop BOOLEAN default FALSE;

declare rec_count int;


declare cur cursor for
select distinct ed.emp_pkey,concat(ed.first_name,' ',ed.last_name) empname ,
ep.joining_date	,  
ep.emp_company_id	,	 
ep.emp_type	,	 
ep.designation	,	 
ep.emp_dept	,
ep.emp_grade	, 
ep.emp_vertical,	 
ep.emp_branch	,	 
ep.HOLIDAY_GROUP_ID,	 
ep.LEAVEPOLICY_GROUP_ID,	 
ep.day_time_seq ,
ep.structure_id  from emp_details ed,emp_proff ep 
 where ed.Branch_code=pBranch_code and ed.Branch_code=ep.emp_branch and ed.emp_pkey=pemp_pkey
 and ed.emp_pkey=ep.emp_fkey and status=1 and ed.emp_pkey in (select emp_fkey from attendance_register 
	       where month_year=pmonth and isdelete= 'N');

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;
 select distinct attendance_date into vattendance_date
								   from db_config where active='Y';
 if vattendance_date =0 then
       set vmonth=concat(pmonth,'-01');
			 set vmonthly_att_fromdate =DATE_FORMAT(vmonth, '%Y-%m-01');
			 set vmonthly_att_todate =LAST_DAY(DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d'));

		   else
		   set vmonth=concat(pmonth,'-01');
		   set vmonthly_att_fromdate =date_format(DATE_SUB(concat(DATE_FORMAT(DATE_SUB(vmonth,INTERVAL 1 month), '%Y-%m-'),date_format(last_day(DATE_SUB(vmonth,INTERVAL 1 month)),'%d')),INTERVAL vattendance_date-1 day),'%Y-%m-%d');  

		   set vmonthly_att_todate =DATE_SUB(concat(DATE_FORMAT(vmonth, '%Y-%m-'),date_format(last_day(vmonth),'%d')),INTERVAL vattendance_date day);
		 

           end if ;

open cur;
start_loop: loop
    fetch cur into vemp_pkey,vfirst_name , vjoining_date,	
vemp_company_id,
vemp_type	,	
vdesignation	,
vemp_dept	,
vemp_grade	, 
vemp_vertical,	
vemp_branch	,	
vHOLIDAY_GROUP_id ,
vLEAVEPOLICY_GROUP_ID ,
vday_time_seq ,vstructure_id;
IF exit_loop THEN
        LEAVE start_loop;
     END IF;
	 	
		   
 select emp_derived_anualctc ,emp_anual_ctc/12 into vemp_anual_ctc,vemp_monthly_ctc  from  emp_ctc_transaction  where emp_fkey=vemp_pkey and end_date_effective is null;
  	 
	 block50:begin
   DECLARE exit_loop50 BOOLEAN default FALSE;
    declare vitem_value float;
    declare slip_cur cursor for 
   select  salary_head_item_fkey	,
			trim(salary_head_item_desc) salary_head_item_desc,
			structure_det_value	,salary_rate,round(salary_amount) ,head_type  ,head_operator
			from emp_salary_slip
    where emp_fkey = vemp_pkey and month_year = pmonth  and head_type in('limit_wl','limit_wg') and end_date_effective is null 
		and salary_amount <>0  order by 1 desc;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop50 = TRUE;
 
  open slip_cur;
  start_loop50: loop
    fetch slip_cur into vsalary_head_item_fkey,vsalary_head_item_desc,vstructure_det_value,
	vsalary_rate,vsalary_amount,vhead_type,vhead_operator ;
	
	IF exit_loop50 THEN 
       LEAVE start_loop50 ;   
    END IF;
	select structure_det_depends into vitem_value   from salary_structure_details where salary_head_item_fkey =vsalary_head_item_fkey and structure_id=vstructure_id ;
	
	if vitem_value is null or vitem_value=0 then
	   set vitem_value = vstructure_det_value;
	else    
	   set vitem_value = vitem_value;
   end if;
   
	if vhead_type ='limit_wl' then
        set vvalue=LEAST(abs(vitem_value) ,abs(vsalary_amount));
		if vhead_operator='Deduction' then
		  set vvalue=vvalue*-1;
		end if;  
		 update emp_salary_slip set salary_amount=round(vvalue)  
			where salary_head_item_fkey=vsalary_head_item_fkey and emp_fkey = vemp_pkey 
			and month_year = pmonth and end_date_effective is null ;
   elseif vhead_type ='limit_wg' then
       set vvalue= GREATEST(abs(vitem_value) ,abs(vsalary_amount));
	   if vhead_operator='Deduction' then
		  set vvalue=vvalue*-1;
		end if;
	    update emp_salary_slip set salary_amount=round(vvalue)  
			where salary_head_item_fkey=vsalary_head_item_fkey and emp_fkey = vemp_pkey 
			and month_year = pmonth and end_date_effective is null ;
  end if;	
  set vitem_value =null;
 end loop start_loop50;
   close slip_cur;
   end block50 ;
	 

	select round(sum( salary_amount )) into vmonthly_amount  from  emp_salary_slip  where (isnull( end_date_effective ) and (lcase( head_operator ) = 'addition')  and emp_fkey= vemp_pkey and month_year =pmonth ) group by  emp_fkey ,  month_year ;
	
 select round(sum( salary_amount )) into vindirect_amount  from  emp_salary_slip  where (isnull( end_date_effective ) and (lcase( head_operator ) = 'addition')  and lcase(item_part)= 'indirect' and emp_fkey= vemp_pkey and month_year =pmonth ) group by  emp_fkey ,  month_year ;
 
  select round(sum( salary_amount )) into vtotal_deduction  from  emp_salary_slip  where (isnull( end_date_effective ) and (lcase( head_operator ) = 'deduction')  and emp_fkey= vemp_pkey and month_year =pmonth ) group by  emp_fkey ,  month_year ;
  
   select round(sum( salary_amount )) into vtotal_variables  from  emp_salary_slip  where (isnull( end_date_effective ) and (lcase(head_type)='variable')  and emp_fkey= vemp_pkey and month_year =pmonth ) group by  emp_fkey ,  month_year ;
	
	

   if vmonthly_amount >=0 then
   update payroll_master set calander_days= DATEDIFF(vmonthly_att_todate,vmonthly_att_fromdate)+1 , monthly_ctc=(vemp_anual_ctc),
          monthly_amount=vmonthly_amount,   gross_salary= vmonthly_amount-ifnull(vindirect_amount,0) , total_deduction=ifnull(vtotal_deduction,0),net_salary=(gross_salary +ifnull(total_deduction,0))+ifnull(vtotal_variables,0),action='Processed' ,created_by=puser_id,total_variables=ifnull(vtotal_variables,0)
   where payroll_master_pkey=ppayroll_master_pkey and emp_fkey=vemp_pkey and month_year=pmonth ;
   else 
   update payroll_master set calander_days= DATEDIFF(vmonthly_att_todate,vmonthly_att_fromdate)+1 , monthly_ctc=(vemp_anual_ctc),
          monthly_amount=vmonthly_amount,   gross_salary= vmonthly_amount-ifnull(vindirect_amount,0) , total_deduction=ifnull(vtotal_deduction,0),net_salary=(gross_salary +ifnull(total_deduction,0))+ifnull(vtotal_variables,0),action=Null ,created_by=puser_id,total_variables=ifnull(vtotal_variables,0)
   where payroll_master_pkey=ppayroll_master_pkey and emp_fkey=vemp_pkey and month_year=pmonth ;
  end if;
   set vmonthly_amount=0;
   set vindirect_amount=0;
  set vtotal_deduction=0;
  
   end loop;
close cur;




end;;

DROP FUNCTION IF EXISTS `time_coupon_auto_fn`;;
CREATE FUNCTION `time_coupon_auto_fn` (`Pemp_fkey` int, `patt_date` varchar(30), `pyear_month` varchar(20)) RETURNS varchar(100) CHARACTER SET 'latin1' LANGUAGE SQL
READS SQL DATA
    DETERMINISTIC
begin
declare vemp_pkey int;
declare vatt_date  varchar(30);
declare nday  int;
declare vdaytimeId  int;
declare vLOGDATE_intime datetime;
declare vLOGDATE_outime datetime;
declare vduration int;
declare vminuts_calc_perday int;
declare vminutes_per_half int;
declare vsetvalue varchar(10);
declare vexistvalue varchar(10);
declare vattendance_date int;
declare vmonthly_att_fromdate datetime;
declare vmonthly_att_todate datetime;
declare vemp_count int;
declare von_dutty1 varchar(10);
declare voff_dutty1 varchar(10);
declare visnextday int;
declare vstrict_monitorings varchar(10);
DECLARE vsunday_F  char(1);
DECLARE vmonday_F  char(1);
DECLARE vtuesday_F  char(1);
DECLARE vwednesday_F  char(1);
DECLARE vthursday_F  char(1);
DECLARE vfriday_F  char(1);
DECLARE vsaturday_F  char(1);
declare vis_exception int;
declare von_dutty4 varchar(30);
declare voff_dutty4 varchar(30);
declare vworking_time4 varchar(30);
declare vsite_transactions_fkey int;
declare vinclude_break char(1);
declare  vINTIME datetime;
declare	vOUTTIME  datetime;
declare vcompany_code varchar(30);
declare vLOGDATE_out_nextday  datetime;
declare vLOGDATE_intime_nextday datetime ;
declare von_dutty2 varchar(10);
declare voff_dutty2 varchar(10);
declare vworking_time2 varchar(10);
declare vworking_time1 varchar(10);
declare vfirst_duration float;
declare vsecond_duration float;
declare vsetvalue1 varchar(10);
declare vsetvalue2 varchar(10);
declare vfirst_intime datetime;
		declare vfirst_outtime datetime;
		declare vsecond_intime datetime;
		declare vsecond_outtime datetime;
		declare vvouttime datetime;
		declare vpresent varchar(20);
		declare vfin_year varchar(10);
		declare vleavecnt float;
		declare vsalary_head_item_pkey int;
		declare vminuts_aftr_on_dutty_cal_late int;
		declare vminuts_bfr_off_dutty_cal_early int;
		declare vLEAVEENTRYID int;
		declare vleave_exist int;
		declare vleave_entry_count int;
		DECLARE vallotedmonth float;

DECLARE exit_loop BOOLEAN default FALSE;
declare tc_cur cursor for   
select att_date,present from emp_detail_timeattandance 
 where emp_pkey=vemp_pkey 
 and yearmonth=Pyear_month and present in('P/A','A/P')
 and weekoff is null and  holiday is null and leaves is null 
 and att_date not in(select FROMDATE from leaveentries where EMP_fkey=pemp_fkey );
 
 DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;


set vemp_pkey=Pemp_fkey;

open tc_cur ;
start_loop5: loop
    fetch tc_cur into vatt_date,vpresent;
 IF exit_loop THEN        LEAVE start_loop5;     END IF;
 
if vpresent is not null then
   select day_time_seq into vdaytimeId from emp_proff where emp_fkey=Pemp_fkey ;
   
   SELECT att_start_end_fn(DATE_FORMAT(pyear_month, '%Y-%m-01'), 2) into vmonthly_att_todate;

SELECT salary_head_item_pkey  into vsalary_head_item_pkey  FROM salary_head_items where item = 'Time Coupon' and item_type='LEAVE' limit 1;

select count(*) into vleave_exist from leaveentries where EMP_fkey=pemp_fkey and FROMDATE=vatt_date;  

SELECT leave_balance_inthe_year_fn(pemp_fkey, vsalary_head_item_pkey, vmonthly_att_todate) into vleavecnt;

if (vleavecnt >0) THEN


 select distinct minuts_calc_perday,minutes_per_half,strict_monitorings,on_dutty1,off_dutty1,isnextday,on_dutty2,off_dutty2,working_time1,working_time2,
 include_break,minuts_aftr_on_dutty_cal_late,minuts_bfr_off_dutty_cal_early
		 into vminuts_calc_perday ,vminutes_per_half,vstrict_monitorings,von_dutty1,voff_dutty1,visnextday,von_dutty2,voff_dutty2,vworking_time1,vworking_time2,
		 vinclude_break,vminuts_aftr_on_dutty_cal_late,vminuts_bfr_off_dutty_cal_early
		   from working_day_time_procedures where day_time_seq=vdaytimeId ;


		  if vpresent in('A/P') then 
				  
			   
					  if vinclude_break='Y' then
					  
							   select min(LOGDATE) into vLOGDATE_intime
							  from device_attandance att,emp_details ed      
								where att.emp_id=ed.emp_id 
							   and att.company_code=ed.company_code 
							 and lcase(c1)='in' and emp_pkey=vemp_pkey and ucase(att.status)='Y'
							and date_format(LOGDATE,'%Y-%m-%d') =vatt_date
							and (LOGDATE,att.emp_id)
							 in (select min(LOGDATE) ,emp_id from device_attandance where date_format(LOGDATE,'%Y-%m-%d') =vatt_date 
							  and lcase(c1)='in' and ucase(status)='Y' group by emp_id);
							  
							   
							 select max(LOGDATE) into vLOGDATE_outime
							  from device_attandance att,emp_details ed      
								where att.emp_id=ed.emp_id 
							   and att.company_code=ed.company_code 
							and ucase(att.status)='Y'
							and date_format(LOGDATE,'%Y-%m-%d') =vatt_date and emp_pkey=vemp_pkey and LOGDATE > vLOGDATE_intime 
							  ;
							  
						
				  if vleavecnt>=0.5 then	
					  if ucase(vstrict_monitorings)='Y' and von_dutty2 is not null then
						
						if vLOGDATE_intime between date_format(concat(date_format(vLOGDATE_intime ,'%Y-%m-%d'),' ',von_dutty1),'%Y-%m-%d %H:%i:%s')
						and date_add(date_format(concat(date_format(vLOGDATE_intime ,'%Y-%m-%d'),' ',von_dutty1),'%Y-%m-%d %H:%i:%s'),INTERVAL vminuts_aftr_on_dutty_cal_late MINUTE) then
							
						INSERT INTO leaveentries (salary_head_item_fkey, applied_date, LEAVESTATUS, EMP_fkey, FROMDATE, FROMHALF, TODATE, TOHALF, ISAutherized, ISAutherizedby, Autherized_date, ISAPPROVED, APPROVEDBY, APPROVED_date, Reason,leave_days)  VALUES
					  (vsalary_head_item_pkey,current_date,'Approved',vemp_pkey,	vatt_date,	1,	vatt_date,	1,	1,	0,	current_date,	1,	0,	current_date,	'Time Coupon Applied for Late In',0.5);	
					
					select max(LEAVEENTRYID) into vLEAVEENTRYID from leaveentries
					  where EMP_fkey=vemp_pkey and FROMDATE=vatt_date and salary_head_item_fkey=vsalary_head_item_pkey ;
					  
					  INSERT INTO `emp_leave_transactions` ( `LEAVEENTRYID`, `leave_date`, `leave_session`, `Leavestatus`, `Remarks`, `creation_date`) VALUES
						(vLEAVEENTRYID,	vatt_date,	1,	'Approved',	'Time Coupon Applied for Late In',	current_date);

						end if;		
					   end if;
				   end if;		   
					  end if;
					  
			  else 

					  if vinclude_break='Y' then
					  
							   select min(LOGDATE) into vLOGDATE_intime
							  from device_attandance att,emp_details ed      
								where att.emp_id=ed.emp_id 
							   and att.company_code=ed.company_code 
							 and lcase(c1)='in' and emp_pkey=vemp_pkey and ucase(att.status)='Y'
							and date_format(LOGDATE,'%Y-%m-%d') =vatt_date
							and (LOGDATE,att.emp_id)
							 in (select min(LOGDATE) ,emp_id from device_attandance where date_format(LOGDATE,'%Y-%m-%d') =vatt_date 
							  and lcase(c1)='in' and ucase(status)='Y' group by emp_id);
							  
							   
							 select max(LOGDATE) into vLOGDATE_outime
							  from device_attandance att,emp_details ed      
								where att.emp_id=ed.emp_id 
							   and att.company_code=ed.company_code 
							and ucase(att.status)='Y'
							and date_format(LOGDATE,'%Y-%m-%d') =vatt_date and emp_pkey=vemp_pkey and LOGDATE > vLOGDATE_intime 
							  ;
								  
							
							
				  if vleavecnt>=0.5 then
					  if ucase(vstrict_monitorings)='Y' and von_dutty2 is not null then
						
						if vLOGDATE_outime between date_add(date_format(concat(date_format(vLOGDATE_intime ,'%Y-%m-%d'),' ',voff_dutty2),'%Y-%m-%d %H:%i:%s'),INTERVAL (vminuts_bfr_off_dutty_cal_early*-1) MINUTE)
						and date_format(concat(date_format(vLOGDATE_intime ,'%Y-%m-%d'),' ',voff_dutty2),'%Y-%m-%d %H:%i:%s') then
							
						INSERT INTO leaveentries (salary_head_item_fkey, applied_date, LEAVESTATUS, EMP_fkey, FROMDATE, FROMHALF, TODATE, TOHALF, ISAutherized, ISAutherizedby, Autherized_date, ISAPPROVED, APPROVEDBY, APPROVED_date, Reason,leave_days)  VALUES
					  (vsalary_head_item_pkey,current_date,'Approved',vemp_pkey,	vatt_date,	2,	vatt_date,	2,	1,	0,	current_date,	1,	0,	current_date,	'Time Coupon Applied for Early Out',0.5);	
					  
					   select max(LEAVEENTRYID) into vLEAVEENTRYID from leaveentries
					  where EMP_fkey=vemp_pkey and FROMDATE=vatt_date and salary_head_item_fkey=vsalary_head_item_pkey ;
					  
					  INSERT INTO `emp_leave_transactions` ( `LEAVEENTRYID`, `leave_date`, `leave_session`, `Leavestatus`, `Remarks`, `creation_date`) VALUES
						(vLEAVEENTRYID,	vatt_date,	2,	'Approved',	'Time Coupon Applied for Early Out',	current_date);
						
						end if;		
					   end if;
				 end if;		   
					   end if;
			  
			 end if;
	 set vleavecnt =0; 
	 set vleave_exist=null;
 end if;
 end if;
 end loop start_loop5; 
close tc_cur ;
  return concat(vleavecnt ,' ',vleave_exist);
end;;

DROP FUNCTION IF EXISTS `time_duration_check`;;
CREATE FUNCTION `time_duration_check` (`pshift_date` date, `pemp_pkey` int, `pbranch_code` varchar(30)) RETURNS varchar(30) CHARACTER SET 'latin1' LANGUAGE SQL
READS SQL DATA
    DETERMINISTIC
begin
declare vyearmonth date;
declare vdaytimeId  int;
declare vLOGDATE_intime datetime;
declare vLOGDATE_outime datetime;
declare vduration int;
declare vminuts_calc_perday int;
declare vminutes_per_half int;
declare vsetvalue varchar(10);
declare vmonthly_att_fromdate date;
declare vmonthly_att_todate date;
declare vemp_count int;
declare von_dutty1 varchar(10);
declare voff_dutty1 varchar(10);
declare visnextday int;
declare vstrict_monitorings varchar(10);
declare vis_exception int;
declare von_dutty4 varchar(30);
declare voff_dutty4 varchar(30);
declare vworking_time4 varchar(30);
declare vinclude_break char(1);
declare vINTIME datetime;
declare	vOUTTIME  datetime;
declare von_dutty2 varchar(10);
declare voff_dutty2 varchar(10);
declare vworking_time2 varchar(10);
declare vworking_time1 varchar(10);
declare vfirst_duration float;
declare vsecond_duration float;
declare vvouttime datetime;
declare vtc varchar(100);
declare vminuts_aftr_on_dutty_cal_late int;
declare vminuts_bfr_off_dutty_cal_early int;
declare vstring varchar(1000);
declare vday_time_desc varchar(100);
declare vshift_string varchar(1000);
declare vcount int;
declare vemp_Vercount int;
declare vshift_count int;

select count(*) into vshift_count from emp_shift_planner where emp_fkey = pemp_pkey and shift_date = pshift_date and status = 1;

if vshift_count > 0 then
	select shift_id into vdaytimeId from emp_shift_planner where emp_fkey = pemp_pkey and shift_date = pshift_date and status = 1;
else
	select day_time_seq into vdaytimeId from emp_proff where emp_fkey = pemp_pkey;
end if;

select distinct minuts_calc_perday, minutes_per_half, day_time_desc, strict_monitorings, is_exception, on_dutty1, off_dutty1, working_time1, isnextday, include_break
into vminuts_calc_perday, vminutes_per_half, vday_time_desc, vstrict_monitorings, vis_exception, von_dutty1, voff_dutty1, vworking_time1, visnextday, vinclude_break
from working_day_time_procedures where day_time_seq = vdaytimeId;

if vis_exception = 1 then
	block1:begin
	declare vex_week_day varchar(20);
	declare vex_week varchar(10);
	declare vin_time time;
	declare vout_time time;
	declare vduration int;
	declare vfull_day int;
	declare vhalf_day int;
	declare vweek int;
	
	declare exit_loop1 boolean default false;
	
	declare exception_cur cursor for
	select ex_week_day, ex_week, in_time, out_time, full_day, half_day from shift_exceptions
	where shift_id = vdaytimeId and week_off = 'N' and status = 1;
	
	declare continue handler for not found set exit_loop1 = true;
	
	open exception_cur;
	start_loop1: loop
		fetch exception_cur into vex_week_day, vex_week, vin_time, vout_time, vfull_day, vhalf_day;
		
		if exit_loop1 then
			leave start_loop1;
		end if;
		
		set vweek = floor((dayofmonth(pshift_date) - 1) / 7) + 1;
		
		if lcase(dayname(pshift_date)) = lcase(vex_week_day) then
			if vex_week = 'A' or vweek = cast(vex_week as unsigned) then
				set von_dutty1 = vin_time;
				set voff_dutty1 = vout_time;
				set vminuts_calc_perday = vfull_day;
				set vminutes_per_half = vhalf_day;
			end if;
		end if;
	end loop start_loop1;
	close exception_cur;
	end block1;
end if;

set vstring = concat(vdaytimeId, '(', vday_time_desc, ')-', von_dutty1, ' ', voff_dutty1, ' ', vminuts_calc_perday , ' ', vminutes_per_half, ' ', vstrict_monitorings);

select min(LOGDATE) into vLOGDATE_intime from device_attandance att,emp_details ed
where att.emp_id = ed.emp_id and att.company_code = ed.company_code and lcase(c1) = 'in'
and ed.emp_pkey = pemp_pkey and ucase(att.status) = 'Y' and att.SHIFTDATE = pshift_date;

select max(LOGDATE) into vLOGDATE_outime from device_attandance att,emp_details ed
where att.emp_id = ed.emp_id and att.company_code = ed.company_code and lcase(c1) = 'out'
and ed.emp_pkey = pemp_pkey and ucase(att.status) = 'Y' and att.SHIFTDATE = pshift_date;

if vLOGDATE_outime is not null then
	if vinclude_break = 'Y' then
		set vINTIME = vLOGDATE_intime;
		
		if vLOGDATE_intime < vLOGDATE_outime then
			set vOUTTIME = vLOGDATE_outime;  
		else
			set vOUTTIME = null; 
			set vLOGDATE_outime = null;
		end if; 			  
		
		if ucase(vstrict_monitorings) = 'Y' and vLOGDATE_outime is not null then
			if visnextday = 1 then 
				select date_add(pshift_date, interval 1 day) into vvouttime;
			else
				set vvouttime = vLOGDATE_intime;
			end if;
			
			if vLOGDATE_intime <= date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %T') then
				if vLOGDATE_intime <= date_format(concat(date_format(pshift_date, '%Y-%m-%d'), ' ', von_dutty1), '%Y-%m-%d %H:%i:%s') then
					set vINTIME = date_format(concat(date_format(pshift_date, '%Y-%m-%d'), ' ', von_dutty1), '%Y-%m-%d %H:%i:%s');
				else 
					set vINTIME = vINTIME;
				end if; 
				
				if visnextday = 1 then 
					select date_add(pshift_date, interval 1 day) into vvouttime;
				else
					set vvouttime = vINTIME;
				end if;
				
				if vLOGDATE_outime >= date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %T') then
					set vOUTTIME = date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %T');
				else 
					set vOUTTIME = vLOGDATE_outime;
				end if; 
				
				if vINTIME > vOUTTIME then
					set vOUTTIME = null;   
				end if;
			else
				set vINTIME = vLOGDATE_intime;
				set vOUTTIME = vLOGDATE_outime;  
			end if;
		end if;
		
		if vINTIME is not null and vOUTTIME is not null then
			set vduration = greatest(timestampdiff(minute, vINTIME, vOUTTIME), 0);
		end if;
	else
		block2:begin
		declare vfirst_name varchar(100);
		declare vemp_pkey int;
		declare	vinval varchar(30);
		declare	voutval varchar(30);
		declare vvouttime datetime;
		
		declare exit_loop2 boolean default false;
		
		declare break_cur cursor for
			select
				FIRST_NAME, EMP_PKEY, INTIME, INVAL,
				(case when INVAL = 'in' and OUTVAL = 'in' then null else OUTTIME end) as OUTTIME,
				OUTVAL
			from
				(
					select 
						MO.C1 as OUTVAL, MO.EMP_PKEY, MO.FIRST_NAME,
						MO.LOGDATE as OUTTIME,
						@S as 'lead(logdate) over(partition by emp_pkey order by logdate)' ,
						@LOGIN := @S as INTIME,
						@C as 'lead(c1) over(partition by emp_pkey order by logdate)',
						@INVAL := @C as INVAL,
						(case when @PARTITION_BY_COLUMN = EMP_PKEY or @_SEASON is null then @S := LOGDATE
																						else @S := null
							end) TMP_VALUE,
						(case when @PARTITION_BY_COLUMN = EMP_PKEY or @_SEASON is null then @C := C1
																						else @C := null
							end) TMP_VALUE1,
						(@PARTITION_BY_COLUMN := EMP_PKEY) PARTITION_COLUMN
					from 
						(
							select 
									ed.emp_pkey,    ed.first_name,      att.logdate,    lcase(att.c1) c1
							from (select @PARTITION_BY_COLUMN = null,
										@S := null,
										@C := null,
										@LOGIN := null,
										@INVAL := null
								) vars, device_attandance att, emp_details ed
							where 
									att.emp_id = ed.emp_id and ucase(att.status) = 'Y'
									and ed.emp_pkey = pemp_pkey
									and date_format(att.logdate, '%Y-%m-%d %T') between 
										date_format(vLOGDATE_intime, '%Y-%m-%d %T') and date_format(vLOGDATE_outime, '%Y-%m-%d %T')
						order by LOGDATE) MO
				) XX
			where INVAL = 'in' and OUTVAL in ('out');
		
		declare continue handler for not found set exit_loop2 = true;
		
		set vduration = 0;
		
		open break_cur;
		start_loop2: loop
			fetch break_cur into vfirst_name, vemp_pkey, vINTIME, vinval, vOUTTIME, voutval;
			
			if exit_loop2 then
				leave start_loop2;
			end if;
			
			if ucase(vstrict_monitorings) = 'Y' then
				if visnextday = 1 then 
					select date_add(pshift_date, interval 1 day) into vvouttime;
				else
					set vvouttime = vLOGDATE_intime;
				end if;
				
				if vINTIME <= date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %H:%i:%s') then
					if vINTIME <= date_format(concat(date_format(vINTIME, '%Y-%m-%d'), ' ', von_dutty1), '%Y-%m-%d %H:%i:%s') then
						set vINTIME = date_format(concat(date_format(vINTIME, '%Y-%m-%d'), ' ', von_dutty1), '%Y-%m-%d %H:%i:%s');
					else
						set vINTIME = vINTIME;
					end if; 
					
					if visnextday = 1 then 
						select date_add(pshift_date, interval 1 day) into vvouttime;
					else
						set vvouttime = vLOGDATE_intime;
					end if; 

					if vOUTTIME >= date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %H:%i:%s') then
						set vOUTTIME = date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %H:%i:%s');
					else 
						set vOUTTIME = vOUTTIME;
					end if;
				else
					set vINTIME = null;
					set vOUTTIME = null;
				end if;
			end if;
			
			if vINTIME is not null and vOUTTIME is not null then
				set vduration = greatest(vduration + timestampdiff(minute, vINTIME, vOUTTIME), 0);
			end if;
		end loop start_loop2;
		close break_cur;
		end block2;
	end if;
	
	if ucase(vstrict_monitorings) = 'Y' then
		if vduration >= vminuts_calc_perday then 
			set vsetvalue = 'P/P';
		elseif vduration >= vminutes_per_half then
			if vINTIME = date_format(concat(date_format(vINTIME, '%Y-%m-%d'), ' ', von_dutty1), '%Y-%m-%d %H:%i:%s') then
				set vsetvalue='P/A';
			elseif vouttime = date_format(concat(date_format(vouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %H:%i:%s') then
				set vsetvalue = 'A/P';
			else
				set vsetvalue = 'P/A';
			end if;
		elseif vduration < vminutes_per_half then
			set vsetvalue = 'A/A';
		else
			set vsetvalue = 'A/A';
		end if;
	else
		if vduration >= vminuts_calc_perday then 
			set vsetvalue = 'P/P';
		elseif vduration >= vminutes_per_half then
			set vsetvalue = 'P/A';
		elseif vduration < vminutes_per_half then
			set vsetvalue = 'A/A';
		else
			set vsetvalue = 'A/A';
		end if;
	end if;
elseif vLOGDATE_outime is null and vLOGDATE_intime is not null then
	set vsetvalue = 'A/A';
end if;

select att_start_end_fn(date_format(pshift_date, '%Y-%m-01'), 1) into vmonthly_att_fromdate;
select att_start_end_fn(date_format(pshift_date, '%Y-%m-01'), 2) into vmonthly_att_todate;

if pshift_date between vmonthly_att_fromdate and vmonthly_att_todate then
	set vyearmonth = date_format(pshift_date, '%Y-%m-01');
else
	set vyearmonth = date_add(date_format(pshift_date, '%Y-%m-01'), interval 1 month);
end if;

select count(*) into vemp_count from emp_detail_timeattandance 
where emp_pkey = pemp_pkey and att_date = pshift_date;

select count(*) into vemp_Vercount from emp_ot_timeattandance where emp_pkey = pemp_pkey and att_date = pshift_date and isdelete = 'N';

if vemp_Vercount = 0 then
	if vemp_count = 0 then
		insert into emp_detail_timeattandance (emp_pkey, att_date, att_in_time, att_out_time, duration, present, yearmonth, shift_string, day_time_id)
		values (pemp_pkey, pshift_date, vLOGDATE_intime, vLOGDATE_outime, vduration, vsetvalue, vyearmonth, vstring, vdaytimeId);
	else
		update emp_detail_timeattandance set yearmonth = vyearmonth, att_in_time = vLOGDATE_intime, att_out_time = vLOGDATE_outime, duration = vduration, present = vsetvalue, shift_string = vstring, day_time_id = vdaytimeId
		where emp_pkey = pemp_pkey and att_date = pshift_date;
	end if;
end if;

return 'success';
end;;

DROP FUNCTION IF EXISTS `time_duration_check_date`;;
CREATE FUNCTION `time_duration_check_date` (`Pyear_month` date, `pdate` date, `Pemp_pkey` int, `pbranch_code` varchar(30)) RETURNS varchar(300) CHARACTER SET 'latin1' LANGUAGE SQL
READS SQL DATA
    DETERMINISTIC
begin

declare vemp_pkey int;
declare vatt_date  date;
declare nday  int;
declare vdaytimeId  int;
declare vLOGDATE_intime datetime;
declare vLOGDATE_outime datetime;
declare vduration int;
declare vminuts_calc_perday int;
declare vminutes_per_half int;
declare vsetvalue varchar(10);
declare vexistvalue varchar(10);
declare vattendance_date int;
declare vmonthly_att_fromdate datetime;
declare vmonthly_att_todate datetime;
declare vemp_count int;
declare von_dutty1 varchar(10);
declare voff_dutty1 varchar(10);
declare visnextday int;
declare vstrict_monitorings varchar(10);
DECLARE vsunday_F  char(1);
DECLARE vmonday_F  char(1);
DECLARE vtuesday_F  char(1);
DECLARE vwednesday_F  char(1);
DECLARE vthursday_F  char(1);
DECLARE vfriday_F  char(1);
DECLARE vsaturday_F  char(1);
declare vis_exception int;
declare von_dutty4 varchar(30);
declare voff_dutty4 varchar(30);
declare vworking_time4 varchar(30);
declare vsite_transactions_fkey int;
declare vinclude_break char(1);
declare  vINTIME datetime;
declare	vOUTTIME  datetime;
declare vLOGDATE_out_nextday  datetime;
declare vLOGDATE_intime_nextday datetime ;
declare von_dutty2 varchar(10);
declare voff_dutty2 varchar(10);
declare vworking_time2 varchar(10);
declare vworking_time1 varchar(10);
declare vfirst_duration float;
declare vsecond_duration float;
declare vsetvalue1 varchar(10);
declare vsetvalue2 varchar(10);
declare vfirst_intime datetime;
		declare vfirst_outtime datetime;
		declare vsecond_intime datetime;
		declare vsecond_outtime datetime;
		declare voutmsgot varchar(50);
		
DECLARE exit_loop1 BOOLEAN default FALSE;

declare att_cur cursor for   
   select distinct emp_pkey,date_format(LOGDATE,'%Y-%m-%d'),c7   
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 

 and lcase(c1)='in' and ucase(att.status)='Y'
 and date_format(LOGDATE,'%Y-%m-%d') between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d') and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d')
  and emp_pkey in
 (select emp_fkey from emp_proff where to_days(DATE_FORMAT(joining_date , '%Y-%m-%d')) <= to_days(DATE_FORMAT(vmonthly_att_todate , '%Y-%m-%d'))
  and day_time_seq in(select day_time_seq from working_day_time_procedures where working_time1 > 10) ) and emp_pkey=if(pemp_pkey in(null,''),emp_pkey,pemp_pkey) 
   and ed.Branch_code=if(pBranch_code in(null,''),ed.Branch_code,pBranch_code)
 order by 1,2;
 


DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;


select distinct attendance_date into vattendance_date
                           from db_config where active='Y';
						   
						   
