 BLOCK3:begin
declare vHOLIDAYDATE date;
DECLARE exit_loop3 BOOLEAN default FALSE;
declare holidaycur cursor for
 select HOLIDAYDATE from holidays where HOLIDAY_GROUP_ID=vholidayId and status=1
  and HOLIDAYDATE  =pdate;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop3 = TRUE;
open holidaycur ;
start_loop1: loop
    fetch holidaycur into vHOLIDAYDATE;
   
IF exit_loop3 THEN 
       LEAVE start_loop1;   
  END IF;
 
select count(*) into vemp_count from emp_detail_timeattandance where emp_pkey=vemp_pkey and att_date=pdate  ;
if vemp_count =0 then
 insert into emp_detail_timeattandance (emp_pkey,att_date,holiday,yearmonth) values (vemp_pkey,DATE_FORMAT(vHOLIDAYDATE,'%Y-%m-%d'),'HO',Pyear_month );
else
update emp_detail_timeattandance set holiday='HO' where emp_pkey=vemp_pkey and att_date=pdate  ;
end if;

  end loop start_loop1;
  
close holidaycur ;
end BLOCK3;


BLOCK4:begin
declare vleave_value varchar(20);
declare vleave_date date;
declare vleave_session int;
declare vsalary_head_item_fkey int;
declare vleaveshort varchar(20);
declare vleave_count int;
declare vleave_exist_value varchar(50);
DECLARE exit_loop BOOLEAN default FALSE;
declare leavecur cursor for
 select elt.leave_date,elt.leave_session,l.salary_head_item_fkey
          from emp_leave_transactions elt join leaveentries l on(elt.LEAVEENTRYID = l.LEAVEENTRYID)
where elt.Leavestatus in('Authorized','Approved')
    and DATE_FORMAT(elt.leave_date, '%Y-%m-%d')=pdate and l.EMP_fkey=vemp_pkey ;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;


open leavecur ;
start_loop5: loop
    fetch leavecur into vleave_date ,vleave_session,vsalary_head_item_fkey ;
   IF exit_loop THEN        LEAVE start_loop5;     END IF;

select ifnull(occurance,'LOP') leaveshort into vleaveshort
     from salary_head_items where  salary_head_item_pkey=vsalary_head_item_fkey ;

	 if vleave_session=3 then 
	     set vleave_value =concat(ucase(vleaveshort),'/',ucase(vleaveshort));
	  elseif vleave_session=2 then 
         set vleave_value= concat('A/',ucase(vleaveshort));
     elseif vleave_session=1 then 
         set vleave_value= concat(ucase(vleaveshort),'/A');		 
	 end if;

 select count(*) into vemp_count from emp_detail_timeattandance where emp_pkey=vemp_pkey and att_date=pdate  ;
if vemp_count =0 then
 insert into emp_detail_timeattandance (emp_pkey,att_date,leaves,yearmonth) values (vemp_pkey,DATE_FORMAT(vleave_date ,'%Y-%m-%d'),vleave_value ,Pyear_month );
else
if vleave_session!=3 then
  select count(leaves) into vleave_count from emp_detail_timeattandance where emp_pkey=vemp_pkey 
    and att_date=pdate and yearmonth=Pyear_month and leaves is not null ;

  if vleave_count =0 then		  
     set vleave_value=vleave_value;
  else
    select leaves into vleave_exist_value from emp_detail_timeattandance where emp_pkey=vemp_pkey 
              and att_date=pdate and leaves is not null ;
  
  
     if vleave_session=1 then
	    set vleave_value= replace(vleave_exist_value,'A/',concat(ucase(vleaveshort),'/'));
	  elseif
       vleave_session=2 then
	    set vleave_value= replace(vleave_exist_value,'/A',concat('/',ucase(vleaveshort)));
   
	end if;
  end if;
end if;
update emp_detail_timeattandance set leaves=vleave_value where emp_pkey=vemp_pkey and att_date=pdate  ;
end if;

end loop start_loop5;
 
close leavecur ;



end BLOCK4;


end loop start_loop;
 close cur ;
 end BLOCK2;
 
   SELECT ot_duration_register_date(pdate,vemp_pkey, pBranch_code) into voutmsgot;
  
   
return 'OK';

end;;

