    DETERMINISTIC
begin
declare vemp_pkey int;
declare vatt_date  date;
declare nday  int;
declare vdaytimeId  int;
declare vLOGDATE_intime datetime;
declare vLOGDATE_outime datetime;
declare vduration int;
declare vminuts_calc_perday int;
declare vsetvalue varchar(10);
declare vexistvalue varchar(10);
declare vattendance_date int;
declare vmonthly_att_fromdate datetime;
declare vmonthly_att_todate datetime;
declare vemp_count int;
DECLARE exit_loop1 BOOLEAN default FALSE;

declare att_cur cursor for   
   select distinct emp_pkey,date_format(LOGDATE,'%Y-%m-%d')   
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 

 and lcase(c1)='in' and ucase(att.status)='Y'
 and date_format(LOGDATE,'%Y-%m-%d') between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d') and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d')
  and emp_pkey in
 (select emp_fkey from emp_proff where to_days(DATE_FORMAT(joining_date , '%Y-%m-%d')) <= to_days(DATE_FORMAT(vmonthly_att_todate , '%Y-%m-%d'))
  and day_time_seq in(select day_time_seq from working_day_time_procedures where working_time1 > 10) 
  and attr1=Plogin_emp_pkey) and emp_pkey=if(pemp_pkey in(null,''),emp_pkey,pemp_pkey)
 order by 1;
 



DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;


select distinct attendance_date into vattendance_date
                           from db_config where active='Y';

if vattendance_date =0 then

set vmonthly_att_fromdate =DATE_FORMAT(Pyear_month, '%Y-%m-01');
set vmonthly_att_todate =LAST_DAY(DATE_FORMAT(Pyear_month, '%Y-%m-%d'));

else
   set vmonthly_att_fromdate =date_format(DATE_SUB(concat(DATE_FORMAT(DATE_SUB(Pyear_month,INTERVAL 1 month), '%Y-%m-'),date_format(last_day(DATE_SUB(Pyear_month,INTERVAL 1 month)),'%d')),INTERVAL vattendance_date day),'%Y-%m-%d');  
                      



set vmonthly_att_todate =DATE_SUB(concat(DATE_FORMAT(Pmonth, '%Y-%m-'),date_format(last_day(Pyear_month),'%d')),INTERVAL vattendance_date day);
 
 




end if ;

 delete from emp_detail_timeattandance where  yearmonth=Pyear_month  ;
