select to_days(DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d'))into i;

WHILE i <= to_days(vmonthly_att_todate) DO
if vsunday='N' then
 if WEEKDAY(FROM_DAYS(i))=6 then

select count(*) into vemp_count from emp_detail_timeattandance where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and yearmonth=Pyear_month  ;
if vemp_count =0 then
 insert into emp_detail_timeattandance (emp_pkey,att_date,weekoff,yearmonth) values (vemp_pkey,DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d'),'WO',Pyear_month );
else
update emp_detail_timeattandance set weekoff='WO' where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and yearmonth=Pyear_month  ;
end if;

end if;

end if;
if vsaturday ='N' then
 if WEEKDAY(FROM_DAYS(i))=5 then

select count(*) into vemp_count from emp_detail_timeattandance where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and yearmonth=Pyear_month  ;
if vemp_count =0 then
 insert into emp_detail_timeattandance (emp_pkey,att_date,weekoff,yearmonth) values (vemp_pkey,DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d'),'WO',Pyear_month );
else
update emp_detail_timeattandance set weekoff='WO' where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and yearmonth=Pyear_month  ;
end if;
end if;
end if;
if vfriday='N' then
 if WEEKDAY(FROM_DAYS(i))=4 then

select count(*) into vemp_count from emp_detail_timeattandance where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and yearmonth=Pyear_month  ;
if vemp_count =0 then
 insert into emp_detail_timeattandance (emp_pkey,att_date,weekoff,yearmonth) values (vemp_pkey,DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d'),'WO',Pyear_month );
else
update emp_detail_timeattandance set weekoff='WO' where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and yearmonth=Pyear_month  ;
end if;
end if;
end if;
if vthursday  ='N' then
 if WEEKDAY(FROM_DAYS(i))=3 then

select count(*) into vemp_count from emp_detail_timeattandance where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and yearmonth=Pyear_month  ;
if vemp_count =0 then
 insert into emp_detail_timeattandance (emp_pkey,att_date,weekoff,yearmonth) values (vemp_pkey,DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d'),'WO',Pyear_month );
else
update emp_detail_timeattandance set weekoff='WO' where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and yearmonth=Pyear_month  ;
end if;
end if;
end if;
if vwednesday='N' then
 if WEEKDAY(FROM_DAYS(i))=2 then

select count(*) into vemp_count from emp_detail_timeattandance where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and yearmonth=Pyear_month  ;
if vemp_count =0 then
 insert into emp_detail_timeattandance (emp_pkey,att_date,weekoff,yearmonth) values (vemp_pkey,DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d'),'WO',Pyear_month );
else
update emp_detail_timeattandance set weekoff='WO' where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and yearmonth=Pyear_month  ;
end if;
end if;
end if;
if vtuesday='N' then
 if WEEKDAY(FROM_DAYS(i))=1 then

select count(*) into vemp_count from emp_detail_timeattandance where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and yearmonth=Pyear_month  ;
if vemp_count =0 then
 insert into emp_detail_timeattandance (emp_pkey,att_date,weekoff,yearmonth) values (vemp_pkey,DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d'),'WO',Pyear_month );
else
update emp_detail_timeattandance set weekoff='WO' where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and yearmonth=Pyear_month  ;
end if;
end if;
end if;
if vmonday='N' then
 if WEEKDAY(FROM_DAYS(i))=0 then

select count(*) into vemp_count from emp_detail_timeattandance where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and yearmonth=Pyear_month  ;
if vemp_count =0 then
 insert into emp_detail_timeattandance (emp_pkey,att_date,weekoff,yearmonth) values (vemp_pkey,DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d'),'WO',Pyear_month );
else
update emp_detail_timeattandance set weekoff='WO' where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') and yearmonth=Pyear_month  ;
