end if;

select i + 1 into i;
END WHILE;

 BLOCK3:begin
declare vHOLIDAYDATE date;
DECLARE exit_loop3 BOOLEAN default FALSE;
declare holidaycur cursor for
 select HOLIDAYDATE from holidays where status =1 and HOLIDAY_GROUP_ID=vholidayId 
  and HOLIDAYDATE  between DATE_FORMAT(vmonthly_att_fromdate , '%Y-%m-%d') and vmonthly_att_todate;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop3 = TRUE;
open holidaycur ;
start_loop1: loop
    fetch holidaycur into vHOLIDAYDATE;
   
IF exit_loop3 THEN 
       LEAVE start_loop1;   
  END IF;
 
select count(*) into vemp_count from emp_detail_timeattandance where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(vHOLIDAYDATE,'%Y-%m-%d') and yearmonth=Pyear_month  ;
if vemp_count =0 then
 insert into emp_detail_timeattandance (emp_pkey,att_date,holiday,yearmonth) values (vemp_pkey,DATE_FORMAT(vHOLIDAYDATE,'%Y-%m-%d'),'HO',Pyear_month );
else
update emp_detail_timeattandance set holiday='HO' where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(vHOLIDAYDATE,'%Y-%m-%d') and yearmonth=Pyear_month  ;
end if;

  end loop start_loop1;
  
close holidaycur ;
end BLOCK3;


BLOCK4:begin
declare vleave_value varchar(20);
declare vleave_date date;
declare vleave_session int;
declare vsalary_head_item_fkey int;
declare vleaveshort varchar(20);
DECLARE exit_loop BOOLEAN default FALSE;
declare leavecur cursor for
 select elt.leave_date,elt.leave_session,l.salary_head_item_fkey
          from emp_leave_transactions elt join leaveentries l on(elt.LEAVEENTRYID = l.LEAVEENTRYID)
where elt.Leavestatus in('Authorized','Approved')
    and DATE_FORMAT(elt.leave_date, '%Y-%m-%d') 
   between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d') 
   and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d') and l.EMP_fkey=vemp_pkey ;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;


open leavecur ;
start_loop5: loop
    fetch leavecur into vleave_date ,vleave_session,vsalary_head_item_fkey ;
   IF exit_loop THEN        LEAVE start_loop5;     END IF;

select ifnull(occurance,'LOP') leaveshort into vleaveshort
     from salary_head_items where  salary_head_item_pkey=vsalary_head_item_fkey ;

	 if vleave_session=3 then 
	     set vleave_value =concat(ucase(vleaveshort),'/',ucase(vleaveshort));
	 elseif vleave_session=2 then 
         set vleave_value= concat('A/',ucase(vleaveshort));
     elseif vleave_session=1 then 
         set vleave_value= concat(ucase(vleaveshort),'/A');		 
	 end if;

 select count(*) into vemp_count from emp_detail_timeattandance where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(vleave_date ,'%Y-%m-%d') and yearmonth=Pyear_month  ;
if vemp_count =0 then
 insert into emp_detail_timeattandance (emp_pkey,att_date,leaves,yearmonth) values (vemp_pkey,DATE_FORMAT(vleave_date ,'%Y-%m-%d'),vleave_value ,Pyear_month );
else
update emp_detail_timeattandance set leaves=vleave_value where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(vleave_date ,'%Y-%m-%d') and yearmonth=Pyear_month  ;
end if;

end loop start_loop5;
 
close leavecur ;



end BLOCK4;

  BLOCK6:begin
declare vb4joinindate int;
declare nday date;
DECLARE exit_loop6 BOOLEAN default FALSE;
declare joiningdate_cur cursor for   
  select emp_fkey,joining_date from emp_proff
 where date_format(joining_date,'%Y-%m-%d') between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d')
 and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d')
 and emp_fkey in (select emp_fkey from emp_proff where joining_date  is not null and day_time_seq in(select day_time_seq from working_day_time_procedures where working_time1 > 10)) and emp_fkey=if(pemp_pkey in(null,''),emp_fkey,pemp_pkey)
 and emp_branch=if(pBranch_code in(null,''),emp_branch,pBranch_code);

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop6 = TRUE;

open joiningdate_cur ;
    fetch joiningdate_cur into vemp_pkey,vatt_date;
  

select to_days(DATE_FORMAT(vmonthly_att_fromdate , '%Y-%m-%d'))into i;
select to_days(DATE_FORMAT(vatt_date, '%Y-%m-%d'))into vb4joinindate ;

WHILE i < vb4joinindate DO

  select DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d') into nday;

select count(*) into vemp_count from emp_detail_timeattandance where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(nday,'%Y-%m-%d') and yearmonth=Pyear_month  ;
if vemp_count =0 then
 insert into emp_detail_timeattandance (emp_pkey,att_date,others,yearmonth) values (vemp_pkey,DATE_FORMAT(nday,'%Y-%m-%d'),'NA',Pyear_month );
else
update emp_detail_timeattandance set others='NA' where emp_pkey=vemp_pkey and att_date=DATE_FORMAT(nday,'%Y-%m-%d') and yearmonth=Pyear_month  ;
end if;


   select i + 1 into i;
END WHILE;
   
  close joiningdate_cur;
  end BLOCK6;
  end loop start_loop;
 close cur ;
  end BLOCK2;
  
    BLOCK8:begin
   DECLARE exit_loop1 BOOLEAN default FALSE;
   declare vno_of_shift_days float;

declare att_cur cursor for   
   select distinct emp_pkey,date_format(LOGDATE,'%Y-%m-%d')   
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 

 and lcase(c1)='in' and ucase(att.status)='Y'
 and date_format(LOGDATE,'%Y-%m-%d') between DATE_FORMAT(vmonthly_att_fromdate, '%Y-%m-%d') and DATE_FORMAT(vmonthly_att_todate, '%Y-%m-%d')
  and emp_pkey in
 (select emp_fkey from emp_proff where to_days(DATE_FORMAT(joining_date , '%Y-%m-%d')) <= to_days(DATE_FORMAT(vmonthly_att_todate , '%Y-%m-%d'))
  and day_time_seq in(select day_time_seq from working_day_time_procedures where active=1) ) and emp_pkey=if(pemp_pkey in(null,''),emp_pkey,pemp_pkey) 
  and ed.Branch_code=if(pBranch_code in(null,''),ed.Branch_code,pBranch_code)
 order by 1,2;
 


DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;
  open att_cur;
att_loop: loop
    fetch att_cur into vemp_pkey,vatt_date;
 
  IF exit_loop1 THEN
	LEAVE att_loop;
  END IF;

select count(*) into vemp_count from emp_detail_timeattandance 
 where emp_pkey=vemp_pkey and att_date=vatt_date and yearmonth=Pyear_month and present='P/P' ;

if vemp_count =0 then 
   select DATE_FORMAT(vatt_date,'%d') into nday ;
   
   
   select day_time_seq into vdaytimeId from emp_proff where emp_fkey=vemp_pkey;
   
 select distinct on_dutty1,off_dutty1,isnextday,strict_monitorings,working_time1
 into von_dutty1,voff_dutty1,visnextday,vstrict_monitorings,vworking_time1
   from working_day_time_procedures where day_time_seq=vdaytimeId ;

  
   select min(LOGDATE) into vLOGDATE_intime
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 
 and lcase(c1)='in' and emp_pkey=vemp_pkey and ucase(att.status)='Y'
and date_format(LOGDATE,'%Y-%m-%d') =vatt_date
and (LOGDATE,att.emp_id)
 in (select min(LOGDATE) ,emp_id from device_attandance where date_format(LOGDATE,'%Y-%m-%d') =vatt_date 
  and lcase(c1)='in' and ucase(status)='Y' group by emp_id);
  
   if visnextday=0 then
    set visnextday=1;
  else 
    set visnextday=visnextday+1;
  end if;	
 select max(LOGDATE) into vLOGDATE_outime
  from device_attandance att,emp_details ed      
    where att.emp_id=ed.emp_id 
   and att.company_code=ed.company_code 
 and lcase(c1)='out'
and date_format(LOGDATE,'%Y-%m-%d') >=vatt_date and emp_pkey=vemp_pkey and ucase(att.status)='Y'
 and (LOGDATE,att.emp_id) 
 in (select max(LOGDATE) ,emp_id from device_attandance where date_format(LOGDATE,'%Y-%m-%d') >=vatt_date and LOGDATE between vLOGDATE_intime and  date_format(concat(date_format(DATE_ADD(vatt_date, INTERVAL visnextday DAY),'%Y-%m-%d'),' ',von_dutty1),'%Y-%m-%d %H:%i:%s') and lcase(c1)='out' and ucase(status)='Y' group by emp_id);
 
 
 
 
 
  if vLOGDATE_outime is not null then
 
  BLOCK9:begin
    declare vFIRST_NAME varchar(100);
declare  vINTIME datetime;
declare	vINVAL varchar(30);
declare	vOUTTIME  datetime;
declare	vOUTVAL varchar(30);
DECLARE exit_loop4 BOOLEAN default FALSE;
declare break_cur cursor for
 SELECT
        FIRST_NAME,     EMP_PKEY,       INTIME,     INVAL,
        (CASE WHEN INVAL = 'in' AND OUTVAL = 'in' THEN NULL ELSE OUTTIME END) AS OUTTIME ,
        OUTVAL
FROM
    (
        SELECT 
               MO.C1 AS OUTVAL,       MO.EMP_PKEY,       MO.FIRST_NAME,
               MO.LOGDATE AS OUTTIME,
               @S AS 'LEAD(logdate) over(PARTITION BY emp_pkey ORDER BY logdate)' ,
               @LOGIN := @S AS INTIME,
               @C AS 'LEAD(c1) over(PARTITION BY emp_pkey ORDER BY logdate)',
               @INVAL := @C AS INVAL,
               (CASE WHEN @PARTITION_BY_COLUMN = EMP_PKEY OR @_SEASON IS NULL THEN @S := LOGDATE
                                                                              ELSE @S := NULL
                 END) TMP_VALUE,
               (CASE WHEN @PARTITION_BY_COLUMN = EMP_PKEY OR @_SEASON IS NULL THEN @C := C1
                                                                              ELSE @C := NULL
                 END) TMP_VALUE1,
               (@PARTITION_BY_COLUMN := EMP_PKEY) PARTITION_COLUMN
        FROM 
               (
                  SELECT 
                        ed.emp_pkey,    ed.first_name,      att.logdate,    att.c1
                  FROM (SELECT @PARTITION_BY_COLUMN = NULL,
                               @S := NULL,
                               @C := NULL,
                               @LOGIN := NULL,
                               @INVAL := NULL
                       ) vars, device_attandance att, emp_details ed
                  where 
                        att.emp_id = ed.emp_id and ucase(att.status)='Y'
                        and ed.emp_pkey = 	vemp_pkey
                        and date_format(att.logdate,'%Y-%m-%d %T') BETWEEN 
                            DATE_FORMAT(vLOGDATE_intime, '%Y-%m-%d %T') AND DATE_FORMAT(vLOGDATE_outime, '%Y-%m-%d %T')
             order by LOGDATE ) MO
    ) XX
WHERE INVAL = 'in' AND OUTVAL IN ('in','out' ) ;


  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop4 = TRUE;
 	set vduration=0;
open break_cur ;
start_loop1: loop
    fetch break_cur into vFIRST_NAME,	vEMP_PKEY,	vINTIME,	vINVAL,	vOUTTIME,	vOUTVAL;
   
IF exit_loop4 THEN 
       LEAVE start_loop1 ;   
  END IF;

  if vINTIME is not null and vOUTTIME is not null then
  set vduration=vduration+TIMESTAMPDIFF(Minute, vINTIME,vOUTTIME);
  
  end if;
   
 end loop start_loop1;
 
 close break_cur;
 end BLOCK9; 
 end if;
 
 
 

  
select day_time_seq into vdaytimeId from emp_proff where emp_fkey=vemp_pkey;
   
 select distinct minuts_calc_perday,minutes_per_half,no_of_shift_days
 into vminuts_calc_perday ,vminutes_per_half,vno_of_shift_days
   from working_day_time_procedures where day_time_seq=vdaytimeId ;
   
   set vshift_count= vduration/vminuts_calc_perday;
   set vshift_count= CEILING(vshift_count);
   if  vshift_count > vno_of_shift_days then 
     set vshift_count=vno_of_shift_days ;
	 set vshift_count= CEILING(vshift_count);
	end if; 
	 
	
	 
   if vshift_count=1 then
	 if vduration >= vminuts_calc_perday then 
	   set vsetvalue='P/P';
	   elseif vduration >= vminutes_per_half then
	   set vsetvalue='P/A';
	   elseif vduration < vminutes_per_half then
	   set vsetvalue='A/A';
	   else
	   set vsetvalue='A/A';
	   end if;
	 
			 select min(att_date) into vnew_att_date from emp_detail_timeattandance 
		  where emp_pkey=vemp_pkey and att_date>=vatt_date and yearmonth=Pyear_month 
		  and (weekoff is null or leaves is null or holiday is null) ;
        
		update emp_detail_timeattandance set att_in_time=vLOGDATE_intime,	 
		att_out_time=vLOGDATE_outime,	 
		duration=vduration,present=vsetvalue
		where emp_pkey=vemp_pkey and att_date=vnew_att_date and yearmonth=Pyear_month ;
		
   elseif vshift_count>1 then
  
    set i=1 ;
         WHILE i <= vshift_count DO    

     if vduration >= vminuts_calc_perday then 
	   set vsetvalue='P/P';
	   elseif vduration >= vminutes_per_half then
	   set vsetvalue='P/A';
	   elseif vduration < vminutes_per_half then
	   set vsetvalue='A/A';
	   else
	   set vsetvalue='A/A';
	   end if;
	  			 select min(att_date) into vnew_att_date from emp_detail_timeattandance 
		  where emp_pkey=vemp_pkey and att_date>=vatt_date and yearmonth=Pyear_month  and present is null ;
		 
        
		update emp_detail_timeattandance set att_in_time=vLOGDATE_intime,	 
		att_out_time=vLOGDATE_outime,
		duration=vduration,present=vsetvalue
		where emp_pkey=vemp_pkey and att_date=vnew_att_date and yearmonth=Pyear_month ;
		
  
         set vduration = vduration - vminuts_calc_perday ;
         set vnew_att_date=null;
         select i + 1 into i;
		END WHILE;
		
    end if; 

set vatt_date= null;
set vLOGDATE_intime = null;
set vLOGDATE_outime=null;
set vduration=null;
set vsetvalue=null;
set vminutes_per_half =null;
set vminuts_calc_perday =null;
set vemp_count=null;
 end if;

  end loop att_loop;
  close att_cur;
  end BLOCK8; 
 
 

return 'OK';

end;;

DROP FUNCTION IF EXISTS `update_breakoff`;;
CREATE FUNCTION `update_breakoff` (`pemp_pkey` int) RETURNS varchar(28) CHARACTER SET 'latin1' LANGUAGE SQL
READS SQL DATA
    DETERMINISTIC
begin

declare vemp_pkey int;
declare vatt_date  date;
declare nday  int;
declare vdaytimeId  int;
declare vLOGDATE_intime datetime;
declare vLOGDATE_outime datetime;
declare vduration int;
declare vminuts_calc_perday int;
declare vminutes_per_half int;
declare vsetvalue varchar(10);
declare vexistvalue varchar(10);
declare vattendance_date int;
declare vmonthly_att_fromdate datetime;
declare vmonthly_att_todate datetime;
declare vemp_count int;
declare vcompany_code varchar(30);
declare vbranch_code varchar(30);
declare vemp_id varchar(30);
declare visnextday int;
declare vincount int;
declare vmin_bfr_on_dutty_cal_ot	int;
declare vmin_aftr_off_dutty_cal_ot int ;
declare vwork_time_day_off_cal_ot int;
declare von_dutty1 varchar(30);
declare voff_dutty1 varchar(30);
declare vworking_time1 int;
declare voff_dutty1_ot varchar(30);
declare von_dutty1_ot  varchar(30);
declare vot_duration int;
declare voutdate date;
declare vafterout int;
declare vbeforein int;
declare Pyear_month varchar(20);
DECLARE exit_loop1 BOOLEAN default FALSE;
declare att_cur cursor for   
  select emp_fkey ,break_off_date  from scheduled_break_off where status=1 and emp_fkey=if(pemp_pkey in(NULL,'',0),emp_fkey,pemp_pkey)
  order by 1,2;


DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;

open att_cur;
att_loop: loop
    fetch att_cur into vemp_pkey,vatt_date;

  IF exit_loop1 THEN
	LEAVE att_loop;
  END IF;
  set Pyear_month=vatt_date;
  
   select day_time_seq into vdaytimeId from emp_proff where emp_fkey=vemp_pkey;
	   
	 select distinct minuts_calc_perday,min_bfr_on_dutty_cal_ot,min_aftr_off_dutty_cal_ot,work_time_day_off_cal_ot,on_dutty1,off_dutty1,working_time1,isnextday
	 into vminuts_calc_perday ,vmin_bfr_on_dutty_cal_ot,vmin_aftr_off_dutty_cal_ot,vwork_time_day_off_cal_ot,von_dutty1,voff_dutty1,vworking_time1,visnextday
	   from working_day_time_procedures where day_time_seq=vdaytimeId ;
	   select company_code,branch_code,emp_id into vcompany_code,vbranch_code,vemp_id from emp_details where emp_pkey=vemp_pkey;
	   
	     if visnextday =1 then
		 set voutdate=Pyear_month+Interval 1 day;
		else 
       	set voutdate=Pyear_month;	
	   end if;
	   
	   select count(*) into vafterout from device_attandance att,emp_details ed where att.emp_id=ed.emp_id and  emp_pkey=vemp_pkey and
	        LOGDATE in(select min(LOGDATE) from device_attandance att,emp_details ed where att.emp_id=ed.emp_id and  emp_pkey=vemp_pkey 
			 and  LOGDATE between concat(Pyear_month,' ',von_dutty1)+ INTERVAL 1 MINUTE and concat(Pyear_month,' ',von_dutty1) + INTERVAL (vworking_time1-1) MINUTE and ucase(att.status)='N') 
             and lcase(c1)='out' and ucase(att.status)='N';
			 
     if vafterout<>0 then
	
         INSERT INTO device_attandance (company_code, branch_code, DEVICELOGID, DOWNLOADDATE, DEVICEID, device_USERID, emp_id, LOGDATE, DIRECTION, ATTDIRECTION, C1, C2, C3, C4, C5, C6, C7, WORKCODE, status) VALUES
	(vcompany_code,	vbranch_code,	0,	now(),	0,	vemp_id,	vemp_id,	concat(voutdate,' ',von_dutty1) - INTERVAL 5 MINUTE,	'',	'',	'out',	'',	'breakoff afterout rule applied',	'0',	'1',	'',	'',	'',	'Y');

     end if; 	
      select count(*) into vbeforein from device_attandance att,emp_details ed where att.emp_id=ed.emp_id and  emp_pkey=vemp_pkey and
	        LOGDATE=(select max(LOGDATE) from device_attandance att,emp_details ed where att.emp_id=ed.emp_id and  emp_pkey=vemp_pkey 
			 and  LOGDATE between concat(Pyear_month,' ',von_dutty1)+ INTERVAL 1 MINUTE and concat(Pyear_month,' ',von_dutty1) + INTERVAL (vworking_time1-1) MINUTE and ucase(att.status)='N') 
             and lcase(c1)='in' and ucase(att.status)='Y';
			 
	
      if vbeforein<>0 then
       INSERT INTO device_attandance (company_code, branch_code, DEVICELOGID, DOWNLOADDATE, DEVICEID, device_USERID, emp_id, LOGDATE, DIRECTION, ATTDIRECTION, C1, C2, C3, C4, C5, C6, C7, WORKCODE, status) VALUES
	(vcompany_code,	vbranch_code,	0,	now(),	0,	vemp_id,	vemp_id,	concat(voutdate,' ',von_dutty1) + INTERVAL (vworking_time1+5) MINUTE,	'',	'',	'in',	'',	'breakoff beforein rule applied',	'0',	'1',	'',	'',	'',	'Y');

       end if;	
  
  end loop;
  close att_cur;
  return 'OK';
  end;;

DROP FUNCTION IF EXISTS `user_access_firstime_only`;;
CREATE FUNCTION `user_access_firstime_only` (`pcompany_code` varchar(30), `pBranch_code` varchar(30), `pemp_fkey` int, `ppasswd` varchar(50), `ppasswd_string` varchar(50)) RETURNS varchar(4000) CHARACTER SET 'latin1' LANGUAGE SQL
begin

declare vemp_pkey int;
declare vfirst_name varchar(50);
declare vemp_device_startid int;
declare vDeviceId int;
DECLARE exit_loop BOOLEAN default FALSE;

declare rec_count int;
declare vdevice_count int ;
declare vemp_co_id int;
declare vemp_id int;
declare vmiddile_name varchar(50);
declare vlast_name varchar(50);
declare vmob_count int;
declare vemail varchar(100);
declare vemailcount int;
declare validemailcount int;
declare vissue_email varchar(4000);

declare cur cursor for
select distinct emp_pkey,first_name,middile_name,last_name ,company_code,branch_code,emp_id ,ifnull(trim(email),'')email
from emp_details where
    emp_pkey in (select emp_fkey from user_credentials where password in (null,'',' ')) 
	 and branch_code=pBranch_code and emp_pkey =if(pemp_fkey in(null,0,''),emp_pkey,pemp_fkey) ;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop = TRUE;


open cur;
start_loop: loop
    fetch cur into vemp_pkey,vfirst_name,vmiddile_name,vlast_name,pcompany_code,pBranch_code,vemp_id,vemail;
IF exit_loop THEN
        LEAVE start_loop;
     END IF;
	 
 select count(*) into rec_count from user_credentials where emp_fkey=vemp_pkey;
 
 
 
 if length(vemail)!=0 then 
  update mypayrol_control_db.emp_device_comp_branch set email=vemail where  Company_code=pcompany_code and emp_fkey=vemp_pkey;
 select count(*) into vemailcount from mypayrol_control_db.emp_device_comp_branch 
    where email=vemail and status=1 ;
 	 
	 if vemailcount>1 THEN
	  select count(*) into validemailcount from mypayrol_control_db.emp_device_comp_branch 
		where email=vemail and status=1  and Company_code=pcompany_code and emp_fkey=vemp_pkey ;
	 
	  INSERT INTO  mypayrol_control_db.log_issue_cntrldb (type, module, company_code, emp_pkey, issue) VALUES
	('user_access',	'email login',	pcompany_code,	vemp_pkey,	concat(vemp_id,' email exist ',vemail));
	 set vissue_email=concat(vissue_email,',',vemail);

	ELSE
        update mypayrol_control_db.emp_device_comp_branch set email=vemail where  Company_code=pcompany_code and emp_fkey=vemp_pkey;
	select count(*) into rec_count from user_credentials where emp_fkey=vemp_pkey;
	   if rec_count=0 then  	 
				 INSERT INTO user_credentials ( emp_fkey, company_code, user_id, password, access_allowed, start_date, end_date, first_name, last_name, middle_name, email, phone, reset_login_flag, locked, incorrect_login_attempt, attr1, attr2, avatar, user_group,email) VALUES
		( vemp_pkey,	pcompany_code,	concat(pcompany_code,vemp_id),	ppasswd,	'Y',	NULL,	NULL,	vfirst_name,	vlast_name,	vmiddile_name,	'',	0,	'Y',	0,	0,	NULL,	NULL,	NULL,	1,vemail);

		else 
		  update  user_credentials set password=ppasswd ,access_allowed='Y',reset_login_flag='Y',email=vemail where emp_fkey=vemp_pkey ;

		end if;

   select count(*) into rec_count from mob_user_credentials where user_id=(concat(pcompany_code,vemp_id));

   if rec_count=0 then 
	INSERT INTO mob_user_credentials ( user_id, firstname, lastname, password, securitycode, macid, imei, token, locked, access_allowed, invalid_login, uploaded_time, UID, punchtype,  is_track) VALUES
	(concat(pcompany_code,vemp_id),	vfirst_name,	vlast_name,	ppasswd_string,	' ',	' ',	' ',	'Y',	'N',	'Y',	0,	current_date,	'',	'M','N');
   end if;

		block2:BEGIN
		  DECLARE done INT DEFAULT FALSE;
		  DECLARE a CHAR(16);
		  DECLARE b, c INT;
		  DECLARE cur1 CURSOR FOR SELECT menu_id FROM emp_menu where is_default = 'Y';
		  
		  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

		  OPEN cur1;
		  

		  read_loop: LOOP
			FETCH cur1 INTO a;
			
			IF done THEN
			  LEAVE read_loop;
			END IF;
			
		INSERT INTO user_access (organization_id, user_fkey, menu_id,active)
		SELECT * FROM (SELECT '1',vemp_pkey,a,'Y') AS tmp
		WHERE NOT EXISTS (
			SELECT user_fkey FROM user_access WHERE user_fkey = vemp_pkey and menu_id = a and active = 'Y'
		) LIMIT 1;

		  END LOOP;

		  CLOSE cur1;
		 
		END BLOCK2;
	end if;
else
select count(*) into rec_count from user_credentials where emp_fkey=vemp_pkey;
insert into test(field1,field2) values(rec_count,vemp_pkey);
		 if rec_count=0 then  	 
				 INSERT INTO user_credentials ( emp_fkey, company_code, user_id, password, access_allowed, start_date, end_date, first_name, last_name, middle_name, email, phone, reset_login_flag, locked, incorrect_login_attempt, attr1, attr2, avatar, user_group,email) VALUES
		( vemp_pkey,	pcompany_code,	concat(pcompany_code,vemp_id),	ppasswd,	'Y',	NULL,	NULL,	vfirst_name,	vlast_name,	vmiddile_name,	'',	0,	'Y',	0,	0,	NULL,	NULL,	NULL,	1,vemail);

		else 
		  update  user_credentials set password=ppasswd ,access_allowed='Y',reset_login_flag='Y',email=vemail where emp_fkey=vemp_pkey ;

		end if;

   select count(*) into rec_count from mob_user_credentials where user_id=(concat(pcompany_code,vemp_id));

   if rec_count=0 then 
	INSERT INTO mob_user_credentials ( user_id, firstname, lastname, password, securitycode, macid, imei, token, locked, access_allowed, invalid_login, uploaded_time, UID, punchtype,  is_track) VALUES
	(concat(pcompany_code,vemp_id),	vfirst_name,	vlast_name,	ppasswd_string,	' ',	' ',	' ',	'Y',	'N',	'Y',	0,	current_date,	'',	'M','N');
   end if;

		block1:BEGIN
		  DECLARE done INT DEFAULT FALSE;
		  DECLARE a CHAR(16);
		  DECLARE b, c INT;
		  DECLARE cur1 CURSOR FOR SELECT menu_id FROM emp_menu where is_default = 'Y';
		  
		  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

		  OPEN cur1;
		  

		  read_loop: LOOP
			FETCH cur1 INTO a;
			
			IF done THEN
			  LEAVE read_loop;
			END IF;
			
		INSERT INTO user_access (organization_id, user_fkey, menu_id,active)
		SELECT * FROM (SELECT '1',vemp_pkey,a,'Y') AS tmp
		WHERE NOT EXISTS (
			SELECT user_fkey FROM user_access WHERE user_fkey = vemp_pkey and menu_id = a and active = 'Y'
		) LIMIT 1;

		  END LOOP;

		  CLOSE cur1;
		 
		END BLOCK1;
end if;
  end loop;
close cur;
 if vissue_email is null THEN
RETURN 'SUCCESS' ;
ELSE
RETURN concat(vissue_email,' Not SUCCESS!!!') ;
end if;
end;;

DROP FUNCTION IF EXISTS `vangrd_pfesi_update_fn`;;
CREATE FUNCTION `vangrd_pfesi_update_fn` () RETURNS varchar(30) CHARACTER SET 'latin1' LANGUAGE SQL
begin
declare vfullcnt float;
declare vhalfcnt float;
declare vleavecnt float;
declare vstart_month date;
declare vend_month date;
declare vleave_for_thyear float;
declare vcarry_forwarded float;
declare vemp_pkey int;
declare vfin_count int;
declare pfinyear varchar(30);
declare vemp_company_id varchar(30);
DECLARE vbankaccount varchar(100);
DECLARE vbankname varchar(100);
DECLARE vifsc_code varchar(100);
DECLARE vbank_branch  varchar(100);
declare vESI varchar(100);
declare vPF_NO varchar(100);
declare vUAN varchar(100);
DECLARE exit_loop1 BOOLEAN default FALSE;

declare emp_cur cursor for   
   select distinct emp_fkey ,emp_company_id  
  from emp_proff ed 
 order by 1;
 


DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;

open emp_cur;
att_loop: loop
    fetch emp_cur into vemp_pkey,vemp_company_id;

  IF exit_loop1 THEN
	LEAVE att_loop;
  END IF;
 
select  bankaccount,bankname,ifsc_code,bank_branch into  vbankaccount,vbankname,vifsc_code,vbank_branch from bank_details  where emp_nos=vemp_company_id ; 

 select  ESI into  vESI from esi_details where EMP_NO=vemp_company_id ;

 select  PF_NO,UAN into  vPF_NO,vUAN from pf_details  where EMP_NO=vemp_company_id ;


 update emp_details set bank_name=vbankname  ,branch_name= vbank_branch ,branch_address=vbank_branch, ifsc_code= vifsc_code ,
 account_no=vbankaccount 
,pf= vUAN   ,company_pf=vPF_NO,  esi=vESI
 where emp_pkey=vemp_pkey ;



 end loop att_loop;
close emp_cur;
return 'OK';
end;;

DROP FUNCTION IF EXISTS `weekoff_days_count_fn`;;
CREATE FUNCTION `weekoff_days_count_fn` (`pemp_pkey` int, `first_date` date, `last_date` date) RETURNS float LANGUAGE SQL
BEGIN

DECLARE days_tot float;
DECLARE whole_weeks int;
DECLARE first_day int;
DECLARE last_day int;
DECLARE vsunday  char(1);
DECLARE vmonday  char(1);
DECLARE vtuesday  char(1);
DECLARE vwednesday  char(1);
DECLARE vthursday  char(1);
DECLARE vfriday  char(1);
DECLARE vsunday_F  char(1);
DECLARE vmonday_F  char(1);
DECLARE vtuesday_F  char(1);
DECLARE vwednesday_F  char(1);
DECLARE vthursday_F  char(1);
DECLARE vfriday_F  char(1);
DECLARE vsaturday  char(1);
DECLARE vSaturday_F  char(1);
declare curr_week_day int;
declare vcount float;
declare vdaytimeId int;
declare valternate_count int;
declare i int;
 set i=0;
 set valternate_count=0;
SET whole_weeks = FLOOR((DATEDIFF(last_date,first_date)+1)/7) ;
SET first_day = WEEKDAY(first_date) ;
SET last_day = WEEKDAY(last_date)  ;

select day_time_seq into vdaytimeId from emp_proff where emp_fkey=pemp_pkey;

select sunday,  monday,  tuesday,  wednesday,  thursday  ,  friday,  saturday,sunday_F,  monday_F,  tuesday_F,  wednesday_F,  thursday_F  ,  friday_F,Saturday_F
 into vsunday,  vmonday,  vtuesday,  vwednesday,  vthursday  ,  vfriday,  vsaturday ,vsunday_F,  vmonday_F,  vtuesday_f,  vwednesday_F,  vthursday_F  ,  vfriday_F,vSaturday_F
   from working_day_time_procedures where day_time_seq=vdaytimeId ;
set vcount =0;
if vsunday='N' then
 set curr_week_day = 6 ;
IF first_day - last_day = 1 OR first_day - last_day = -6 THEN
   SET days_tot = whole_weeks;
ELSEIF curr_week_day  >= first_day AND  curr_week_day  <= last_day and first_day <= last_day THEN
   SET days_tot = whole_weeks + 1;
ELSEIF (curr_week_day >= first_day OR curr_week_day <= last_day) and first_day > last_day THEN
   SET days_tot = whole_weeks + 1;
ELSE
   SET days_tot = whole_weeks ;
END IF;
   set vcount =vcount+days_tot ;
end if;

if vmonday  ='N' then
 set curr_week_day = 0 ;
IF first_day - last_day = 1 OR first_day - last_day = -6 THEN
   SET days_tot = whole_weeks;
ELSEIF curr_week_day  >= first_day AND  curr_week_day  <= last_day and first_day <= last_day THEN
   SET days_tot = whole_weeks + 1;
ELSEIF (curr_week_day >= first_day OR curr_week_day <= last_day) and first_day > last_day THEN
   SET days_tot = whole_weeks + 1;
ELSE
   SET days_tot = whole_weeks ;
END IF;
   set vcount =vcount+days_tot ;
end if;

if vtuesday  ='N' then
 set curr_week_day = 1 ;
IF first_day - last_day = 1 OR first_day - last_day = -6 THEN
   SET days_tot = whole_weeks;
ELSEIF curr_week_day  >= first_day AND  curr_week_day  <= last_day and first_day <= last_day THEN
   SET days_tot = whole_weeks + 1;
ELSEIF (curr_week_day >= first_day OR curr_week_day <= last_day) and first_day > last_day THEN
   SET days_tot = whole_weeks + 1;
ELSE
   SET days_tot = whole_weeks ;
END IF;
   set vcount =vcount+days_tot ;
end if;

if vwednesday  ='N' then
 set curr_week_day = 2 ;
IF first_day - last_day = 1 OR first_day - last_day = -6 THEN
   SET days_tot = whole_weeks;
ELSEIF curr_week_day  >= first_day AND  curr_week_day  <= last_day and first_day <= last_day THEN
   SET days_tot = whole_weeks + 1;
ELSEIF (curr_week_day >= first_day OR curr_week_day <= last_day) and first_day > last_day THEN
   SET days_tot = whole_weeks + 1;
ELSE
   SET days_tot = whole_weeks ;
END IF;
   set vcount =vcount+days_tot ;
end if;

if vthursday  ='N' then
 set curr_week_day = 3 ;
IF first_day - last_day = 1 OR first_day - last_day = -6 THEN
   SET days_tot = whole_weeks;
ELSEIF curr_week_day  >= first_day AND  curr_week_day  <= last_day and first_day <= last_day THEN
   SET days_tot = whole_weeks + 1;
ELSEIF (curr_week_day >= first_day OR curr_week_day <= last_day) and first_day > last_day THEN
   SET days_tot = whole_weeks + 1;
ELSE
   SET days_tot = whole_weeks ;
END IF;
   set vcount =vcount+days_tot ;
end if;

if vfriday  ='N' then
 set curr_week_day = 4 ;
IF first_day - last_day = 1 OR first_day - last_day = -6 THEN
   SET days_tot = whole_weeks;
ELSEIF curr_week_day  >= first_day AND  curr_week_day  <= last_day and first_day <= last_day THEN
   SET days_tot = whole_weeks + 1;
ELSEIF (curr_week_day >= first_day OR curr_week_day <= last_day) and first_day > last_day THEN
   SET days_tot = whole_weeks + 1;
ELSE
   SET days_tot = whole_weeks ;
END IF;
   set vcount =vcount+days_tot ;
end if;

if vsaturday  ='N' then
 set curr_week_day = 5 ;
IF first_day - last_day = 1 OR first_day - last_day = -6 THEN
   SET days_tot = whole_weeks;
ELSEIF curr_week_day  >= first_day AND  curr_week_day  <= last_day and first_day <= last_day THEN
   SET days_tot = whole_weeks + 1;
ELSEIF (curr_week_day >= first_day OR curr_week_day <= last_day) and first_day > last_day THEN
   SET days_tot = whole_weeks + 1;
ELSE
   SET days_tot = whole_weeks ;
END IF;
   set vcount =vcount+days_tot ;
end if;
 select to_days(DATE_FORMAT(first_date, '%Y-%m-%d'))into i;
 
WHILE i <= to_days(last_date) DO
	if  FLOOR((DayOfMonth(DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d'))-1)/7)+1 in(2,4) then
	if vsunday_F  ='L' and WEEKDAY(FROM_DAYS(i))=6 then
	set vcount =vcount+1 ;
	end if;
	if vSaturday_F  ='L' and WEEKDAY(FROM_DAYS(i))=5 then
	set vcount =vcount+1 ;
	end if;
	if vfriday_F  ='L' and WEEKDAY(FROM_DAYS(i))=4 then
	set vcount =vcount+1 ;
	end if;
	if vthursday_F  ='L' and WEEKDAY(FROM_DAYS(i))=3 then
	set vcount =vcount+1 ;
	end if;
	if vwednesday_F  ='L' and WEEKDAY(FROM_DAYS(i))=2 then
	set vcount =vcount+1 ;
	end if;
	if  vtuesday_f ='L' and WEEKDAY(FROM_DAYS(i))=1 then
	set vcount =vcount+1 ;
	end if;
	if vmonday_F  ='L' and WEEKDAY(FROM_DAYS(i))=0 then
	set vcount =vcount+1 ;
	end if;
	end if;
	
	if  FLOOR((DayOfMonth(DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d'))-1)/7)+1 =1 then
	if vsunday_F =1 and WEEKDAY(FROM_DAYS(i))=6 then	
	set vcount =vcount+1 ;
	end if;
	if vSaturday_F =1 and WEEKDAY(FROM_DAYS(i))=5 then	
	set vcount =vcount+1 ;
	end if;
	if vfriday_F  =1 and WEEKDAY(FROM_DAYS(i))=4 then	
	set vcount =vcount+1 ;
	end if;
	if vthursday_F  =1 and WEEKDAY(FROM_DAYS(i))=3 then	
	set vcount =vcount+1 ;
	end if;
	if vwednesday_F   =1 and WEEKDAY(FROM_DAYS(i))=2 then	
	set vcount =vcount+1 ;
	end if;
	if  vtuesday_f  =1 and WEEKDAY(FROM_DAYS(i))=1 then	
	set vcount =vcount+1 ;
	end if;
	if vmonday_F  =1 and WEEKDAY(FROM_DAYS(i))=0 then
	set vcount =vcount+1 ;
	end if;
	end if;
	if  FLOOR((DayOfMonth(DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d'))-1)/7)+1 =2 then
	if vsunday_F =2 and WEEKDAY(FROM_DAYS(i))=6 then	
	set vcount =vcount+1 ;
	end if;
	if vSaturday_F =2 and WEEKDAY(FROM_DAYS(i))=5 then	
	set vcount =vcount+1 ;
	end if;
	if vfriday_F  =2 and WEEKDAY(FROM_DAYS(i))=4 then	
	set vcount =vcount+1 ;
	end if;
	if vthursday_F  =2 and WEEKDAY(FROM_DAYS(i))=3 then	
	set vcount =vcount+1 ;
	end if;
	if vwednesday_F   =2 and WEEKDAY(FROM_DAYS(i))=2 then	
	set vcount =vcount+1 ;
	end if;
	if  vtuesday_f  =2 and WEEKDAY(FROM_DAYS(i))=1 then	
	set vcount =vcount+1 ;
	end if;
	if vmonday_F  =2 and WEEKDAY(FROM_DAYS(i))=0 then
	set vcount =vcount+1 ;
	end if;
	end if;
	if  FLOOR((DayOfMonth(DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d'))-1)/7)+1 =3 then
	if vsunday_F =3 and WEEKDAY(FROM_DAYS(i))=6 then	
	set vcount =vcount+1 ;
	end if;
	if vSaturday_F =3 and WEEKDAY(FROM_DAYS(i))=5 then	
	set vcount =vcount+1 ;
	end if;
	if vfriday_F  =3 and WEEKDAY(FROM_DAYS(i))=4 then	
	set vcount =vcount+1 ;
	end if;
	if vthursday_F  =3 and WEEKDAY(FROM_DAYS(i))=3 then	
	set vcount =vcount+1 ;
	end if;
	if vwednesday_F   =3 and WEEKDAY(FROM_DAYS(i))=2 then	
	set vcount =vcount+1 ;
	end if;
	if  vtuesday_f  =3 and WEEKDAY(FROM_DAYS(i))=1 then	
	set vcount =vcount+1 ;
	end if;
	if vmonday_F  =3 and WEEKDAY(FROM_DAYS(i))=0 then
	set vcount =vcount+1 ;
	end if;
	end if;
	if  FLOOR((DayOfMonth(DATE_FORMAT(FROM_DAYS(i),'%Y-%m-%d'))-1)/7)+1 =4 then
	if vsunday_F =4 and WEEKDAY(FROM_DAYS(i))=6 then	
	set vcount =vcount+1 ;
	end if;
	if vSaturday_F =4 and WEEKDAY(FROM_DAYS(i))=5 then	
	set vcount =vcount+1 ;
	end if;
	if vfriday_F  =4 and WEEKDAY(FROM_DAYS(i))=4 then	
	set vcount =vcount+1 ;
	end if;
	if vthursday_F  =4 and WEEKDAY(FROM_DAYS(i))=3 then	
	set vcount =vcount+1 ;
	end if;
	if vwednesday_F   =4 and WEEKDAY(FROM_DAYS(i))=2 then	
	set vcount =vcount+1 ;
	end if;
	if  vtuesday_f  =4 and WEEKDAY(FROM_DAYS(i))=1 then	
	set vcount =vcount+1 ;
	end if;
	if vmonday_F  =4 and WEEKDAY(FROM_DAYS(i))=0 then
	set vcount =vcount+1 ;
	end if;
	end if;
	
select i + 1 into i;
END WHILE;

if vsunday_F  ='Y' then
			set curr_week_day = 6 ;
			IF first_day - last_day = 1 OR first_day - last_day = -6 THEN
			   SET days_tot = whole_weeks;
			ELSEIF curr_week_day  >= first_day AND  curr_week_day  <= last_day and first_day <= last_day THEN
			   SET days_tot = whole_weeks + 1;
