			   SET days_tot = whole_weeks ;
			END IF;
			   set vcount =vcount+(days_tot/2) ;
end if;


if vwednesday_F  ='Y' then
			set curr_week_day = 2 ;
			IF first_day - last_day = 1 OR first_day - last_day = -6 THEN
			   SET days_tot = whole_weeks;
			ELSEIF curr_week_day  >= first_day AND  curr_week_day  <= last_day and first_day <= last_day THEN
			   SET days_tot = whole_weeks + 1;
			ELSEIF (curr_week_day >= first_day OR curr_week_day <= last_day) and first_day > last_day THEN
			   SET days_tot = whole_weeks + 1;
			ELSE
			   SET days_tot = whole_weeks ;
			END IF;
			   set vcount =vcount+(days_tot/2) ;
end if;


if vthursday_F  ='Y' then
			set curr_week_day = 3 ;
			IF first_day - last_day = 1 OR first_day - last_day = -6 THEN
			   SET days_tot = whole_weeks;
			ELSEIF curr_week_day  >= first_day AND  curr_week_day  <= last_day and first_day <= last_day THEN
			   SET days_tot = whole_weeks + 1;
			ELSEIF (curr_week_day >= first_day OR curr_week_day <= last_day) and first_day > last_day THEN
			   SET days_tot = whole_weeks + 1;
			ELSE
			   SET days_tot = whole_weeks ;
			END IF;
			   set vcount =vcount+(days_tot/2) ;
end if;


if vfriday_F  ='Y' then
			set curr_week_day = 4 ;
			IF first_day - last_day = 1 OR first_day - last_day = -6 THEN
			   SET days_tot = whole_weeks;
			ELSEIF curr_week_day  >= first_day AND  curr_week_day  <= last_day and first_day <= last_day THEN
			   SET days_tot = whole_weeks + 1;
			ELSEIF (curr_week_day >= first_day OR curr_week_day <= last_day) and first_day > last_day THEN
			   SET days_tot = whole_weeks + 1;
			ELSE
			   SET days_tot = whole_weeks ;
			END IF;
			   set vcount =vcount+(days_tot/2) ;
end if;

RETURN  vcount ;
END;;

DROP FUNCTION IF EXISTS `year_ending_fn`;;
CREATE FUNCTION `year_ending_fn` (`pclosing_year` varchar(30), `pbranch_code` varchar(30)) RETURNS int(11) LANGUAGE SQL
begin
declare vfullcnt float;
declare vhalfcnt float;
declare vleavecnt float;
declare vstart_month date;
declare vend_month date;
declare vleave_for_thyear float;
declare vcarry_forwarded float;
declare vemp_pkey int;
declare vfin_count int;
declare pfinyear varchar(30);
DECLARE exit_loop1 BOOLEAN default FALSE;

declare emp_cur cursor for   
   select distinct emp_pkey   
  from emp_details ed      
    where Branch_code=if(pBranch_code in(null,''),Branch_code,pBranch_code) and status=1
 order by 1;
 


DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;

open emp_cur;
att_loop: loop
    fetch emp_cur into vemp_pkey;

  IF exit_loop1 THEN
	LEAVE att_loop;
  END IF;
  set pfinyear=pclosing_year+1;
select  count(*) into vcarry_forwarded from emp_leave_balance_year where emp_fkey=vemp_pkey and fin_year=pfinyear; 

if vcarry_forwarded=0 then
 BLOCK4:begin
 declare vCARRY_FORWARD_LIMIT int;
 declare vsalary_head_item_fkey int;
 declare vis_leave_encash int;
 declare vleavebalance float;
 declare vset_forward float;
 DECLARE exit_loop4 BOOLEAN default FALSE;
 
 declare carryleave_cur cursor for
select CARRY_FORWARD_LIMIT,salary_head_item_fkey,is_leave_encash 
  from leavepolicy where LEAVEPOLICY_GROUP_ID
          in (SELECT LEAVEPOLICY_GROUP_ID FROM emp_proff WHERE emp_fkey=vemp_pkey ) and CARRY_FORWARD_LIMIT >0;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop4 = TRUE;
		  
		  open carryleave_cur ;
	start_loop1: loop
    fetch carryleave_cur  into vCARRY_FORWARD_LIMIT,vsalary_head_item_fkey,vis_leave_encash ;
   
IF exit_loop4 THEN 
       LEAVE start_loop1 ;   
  END IF;
 SELECT leave_balance_inthe_year_fn(vemp_pkey, vsalary_head_item_fkey, pclosing_year) into vleavebalance;
 
 if vleavebalance>0 then
 if vCARRY_FORWARD_LIMIT >= vleavebalance then
     set vset_forward=vleavebalance;
  elseif vCARRY_FORWARD_LIMIT < vleavebalance then
       set vset_forward=vCARRY_FORWARD_LIMIT;
	 end if; 
	 
	 
	insert into emp_leave_balance_year(emp_fkey,salary_head_item_fkey,fin_year,carry_forwarded)
	        values(vemp_pkey,vsalary_head_item_fkey,pfinyear,vset_forward);
    
end if;
end loop start_loop1;
 
 close carryleave_cur;
 end BLOCK4;

 select count(*) into vfin_count from fin_year where branch_code=pBranch_code and fin_year=pfinyear and vattr1=0;	
  if  vfin_count=0 then
   insert into fin_year (company_code,branch_code,fin_year,start_month,end_month)
                         select company_code,pBranch_code,pfinyear,DATE_ADD(start_month, INTERVAL 1 YEAR),DATE_ADD(end_month, INTERVAL 1 YEAR)  from fin_year 
						   where fin_year=pclosing_year and branch_code=pBranch_code and vattr1=0 ;
	update 	fin_year set Year_status='CLOSED',is_current_finyear='N' where fin_year=pclosing_year and branch_code=pBranch_code and vattr1=0	;			   
						   
  end if;

end if;
 end loop att_loop;
close emp_cur;
return 1;
end;;

DROP FUNCTION IF EXISTS `year_ending_mission_fn`;;
CREATE FUNCTION `year_ending_mission_fn` (`pclosing_year` varchar(30), `pbranch_code` varchar(30)) RETURNS int(11) LANGUAGE SQL
begin
declare vfullcnt float;
declare vhalfcnt float;
declare vleavecnt float;
declare vstart_month date;
declare vend_month date;
declare vleave_for_thyear float;
declare vcarry_forwarded float;
declare vemp_pkey int;
declare vfin_count int;
declare pfinyear varchar(30);
declare vcompany_code varchar(30);
declare vbranch_code  varchar(30);
declare vfinyear_count int;
declare vleave_yearcnt int;
DECLARE exit_loop1 BOOLEAN default FALSE;

declare emp_cur cursor for   
   select company_code	,branch_code   
  from branches ed      
    where Branch_code=if(pBranch_code in(null,''),Branch_code,pBranch_code) and status=1
 order by 1;
 

DECLARE CONTINUE HANDLER FOR NOT FOUND SET exit_loop1 = TRUE;

open emp_cur;
att_loop: loop
    fetch emp_cur into vcompany_code,vbranch_code;

  IF exit_loop1 THEN
	LEAVE att_loop;
  END IF;
  set pfinyear=pclosing_year+1;
  
select  count(*) into vfinyear_count from fin_year  where branch_code=vbranch_code and fin_year=pfinyear 
      and Year_status='OPEN' and is_current_finyear='Y'   and vattr1=1;
	  
select  count(*) into vleave_yearcnt from fin_year  where branch_code=vbranch_code and fin_year=pfinyear 
      and Year_status='OPEN' and is_current_finyear='Y'   and vattr1=0;
	  


if vfinyear_count=0 then
  INSERT INTO `fin_year` (`company_code`, `branch_code`, `fin_year`, `start_month`, `end_month`, `Year_status`, `is_current_finyear`, `vattr1`, `vattr2`, `vattr3`, `status`) VALUES
(vcompany_code,vbranch_code,	pfinyear,	concat(pfinyear,'-04-01'),	concat(pfinyear+1,'-03-31'),	'OPEN',	'Y',	1,	0,	100,	1);
						   
	update 	fin_year set Year_status='CLOSED',is_current_finyear='N' where fin_year=pclosing_year and branch_code=vbranch_code and vattr1=1	;
	
    
end if;

if vleave_yearcnt=0 then
  INSERT INTO `fin_year` (`company_code`, `branch_code`, `fin_year`, `start_month`, `end_month`, `Year_status`, `is_current_finyear`, `vattr1`, `vattr2`, `vattr3`, `status`) VALUES
(vcompany_code,vbranch_code,	pfinyear,	concat(pfinyear,'-01-01'),	concat(pfinyear,'-12-31'),	'OPEN',	'Y',	0,	0,	100,	1);
						   
	update 	fin_year set Year_status='CLOSED',is_current_finyear='N' where fin_year=pclosing_year and branch_code=vbranch_code and vattr1=0	;
    
end if;

 end loop att_loop;
close emp_cur;
return 1;
end;;

