CREATE TRIGGER `attandance_bu` BEFORE UPDATE ON `attandance` FOR EACH ROW
begin

if old.outtime ='0000-00-00 00:00:00' then

if old.intime <>'0000-00-00 00:00:00' then


 

set new.duration=(unix_timestamp(new.outtime)- unix_timestamp(new.intime))/60;

end if;
end if;


end;;

