  `FIELD31` varchar(20) DEFAULT NULL,
  `FIELD32` varchar(20) DEFAULT NULL,
  `isdelete` varchar(20) NOT NULL DEFAULT 'Y',
  `record_status` varchar(20) NOT NULL DEFAULT '1',
  `userid` varchar(20) NOT NULL,
  PRIMARY KEY (`registerid`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `attendance_register_update` (
  `attendance_register_update` int(11) NOT NULL AUTO_INCREMENT,
  `month_year` date NOT NULL,
  `emp_fkey` int(11) NOT NULL,
  `field` varchar(400) NOT NULL,
  `status` int(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`attendance_register_update`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;


CREATE TABLE `att_in` (`device_attandance_seq` int(11), `EMP_PKEY` int(11), `EmpName` varchar(300), `LOGDATE` datetime, `C1` varchar(100), `c3` varchar(100));


CREATE TABLE `att_out` (`device_attandance_seq` int(11), `EMP_PKEY` int(11), `EmpName` varchar(302), `LOGDATE` datetime, `C1` varchar(100), `location` varchar(100));


CREATE TABLE `bank` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `bank_name` varchar(200) NOT NULL,
  `bank_branch` varchar(200) NOT NULL,
  `ifsc_code` varchar(50) NOT NULL,
  `acct_no` varchar(40) NOT NULL,
  `status` int(11) NOT NULL DEFAULT '1' COMMENT '0 inactive 1 active',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `branches` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_code` varchar(20) NOT NULL,
  `branch_code` varchar(20) NOT NULL,
  `branch_name` varchar(200) NOT NULL,
  `address` text NOT NULL,
  `city` varchar(100) NOT NULL,
  `state` varchar(50) NOT NULL,
  `pincode` varchar(20) NOT NULL,
  `latitude` double NOT NULL,
  `longitude` double NOT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  `deleted` int(11) NOT NULL DEFAULT '-1' COMMENT 'value greater than 0 is deleted',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DELIMITER ;;

CREATE TRIGGER `branches_bi` BEFORE INSERT ON `branches` FOR EACH ROW
begin
declare vcount int;
select count(*) into vcount  from branches;
if vcount =0 then
set vcount =1;
else
set vcount=vcount+1;
end if;
set new.branch_code=concat(NEW.company_code,0,vcount);

end;;

CREATE TRIGGER `branches_ai` AFTER INSERT ON `branches` FOR EACH ROW
begin
declare vcount int;
select count(*) into vcount from mypayrol_control_db.company_branches where branch_code=NEW.branch_code;

if vcount=0 then
insert into mypayrol_control_db.company_branches(company_code,branch_code,branch_name,status)
      VALUES (NEW.company_code,NEW.branch_code,NEW.branch_name,NEW.status);
end if;
end;;

CREATE TRIGGER `branches_au` AFTER UPDATE ON `branches` FOR EACH ROW
BEGIN
  UPDATE mypayrol_control_db.company_branches 
     SET branch_name = NEW.branch_name,
         status = NEW.status
   WHERE company_code = OLD.company_code
   and branch_code=old.branch_code ;
end;;

DELIMITER ;

CREATE TABLE `branch_exceptions` (
  `branch_exceptions_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `branch_code` varchar(30) NOT NULL,
  `no_pt` char(1) NOT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`branch_exceptions_pkey`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;


