CREATE TABLE `category_master` (
  `category_pkey` int(10) NOT NULL AUTO_INCREMENT,
  `code` varchar(100) NOT NULL,
  `description` varchar(50) NOT NULL,
  `created_by` varchar(50) NOT NULL,
  `created_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modified_by` varchar(50) NOT NULL,
  `modified_date` datetime NOT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`category_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `compliance` (
  `cin_no` varchar(100) NOT NULL,
  `pan_no` varchar(100) NOT NULL,
  `service_tax` varchar(100) NOT NULL,
  `tan_no` varchar(100) NOT NULL,
  `pf_no` varchar(100) NOT NULL,
  `emp_state_ins_no` varchar(100) NOT NULL,
  `pt_no_co` varchar(100) NOT NULL,
  `pt_no_dir` varchar(100) NOT NULL,
  `pt_no_emp` varchar(100) NOT NULL,
  `status` int(11) NOT NULL DEFAULT '1' COMMENT '0 inactive 1 active',
  `id` int(11) NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `comp_contact_info` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `business_name` varchar(200) NOT NULL,
  `business_nature` varchar(200) NOT NULL,
  `business_type` varchar(200) NOT NULL,
  `address` varchar(500) NOT NULL,
  `city` varchar(100) NOT NULL,
  `pincode` varchar(10) NOT NULL,
  `state` varchar(100) NOT NULL,
  `phone` varchar(100) NOT NULL,
  `fax` varchar(100) NOT NULL,
  `email` varchar(200) NOT NULL,
  `website` varchar(200) NOT NULL,
  `logo` varchar(200) NOT NULL,
  `subdomain` varchar(200) NOT NULL,
  `logosize` int(11) NOT NULL,
  `max_emp_count` int(11) NOT NULL,
  `plan` varchar(10) NOT NULL DEFAULT 'standard',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

