DELIMITER ;;

CREATE TRIGGER `device_attandance_bi` BEFORE INSERT ON `device_attandance` FOR EACH ROW
begin
declare vemp_pkey int;
declare vatt_date date;
declare vdaytimeId int;
declare vdirection varchar(30);
declare vpunch_count int;
declare vprevday date;
declare vcurday date;
declare vnextday date;
declare vprevday_dir varchar(5);
declare vcurday_dir varchar(5);
declare vprev_dir varchar(5);
declare vprevday_shift_count int;
declare vcurday_shift_count int;
declare vnextday_shift_count int;
declare vprevday_shift int;
declare vcurday_shift int;
declare vnextday_shift int;
declare vprev_off_dutty1 varchar(10);
declare vcur_off_dutty1 varchar(10);
declare vnext_on_dutty1 varchar(10);
declare vprev_max_out_time int;
declare vcur_max_out_time int;
declare vprev_isnextday int;
declare vcur_isnextday int;
declare vprev_max_in_time int;
declare vcur_max_in_time int;
declare vshift_count int;
declare vlast_punch_count int;
declare vlast_punch datetime;
declare vlast_dir varchar(100);

set vatt_date = date_format(new.LOGDATE, '%Y-%m-%d');

select emp_pkey into vemp_pkey from emp_details where emp_id = new.emp_id;

select day_time_seq into vdaytimeId from emp_proff where emp_fkey = vemp_pkey;

set vprevday = date_sub(vatt_date, interval 1 day);

select count(*) into vprevday_shift_count from emp_shift_planner where emp_fkey = vemp_pkey and shift_date = vprevday and status = 1;

if vprevday_shift_count > 0 then
	select shift_id into vprevday_shift from emp_shift_planner where emp_fkey = vemp_pkey and shift_date = vprevday and status = 1;
else
	set vprevday_shift = vdaytimeId;
end if;

select distinct isnextday, off_dutty1, max_in_time, max_out_time into vprev_isnextday, vprev_off_dutty1, vprev_max_in_time, vprev_max_out_time
from working_day_time_procedures where day_time_seq = vprevday_shift;

if vprev_max_in_time is null then
	set vprev_max_in_time = 60;
end if;

if vprev_isnextday = 0 then
	set vprev_max_out_time = round(time_to_sec(timediff('24:00:00', vprev_off_dutty1)) / 60);
else
	set vprevday = vatt_date;
	
	if vprev_max_out_time is null then
		set vprev_max_out_time = 120;
	end if;
end if;

select lcase(C1) into vprevday_dir from device_attandance where device_attandance_seq in
(select max(device_attandance_seq) from device_attandance where emp_id = new.emp_id
and LOGDATE < new.LOGDATE and SHIFT = vprevday_shift and SHIFTDATE = date_sub(vatt_date, interval 1 day) and ucase(status) = 'Y');

set vcurday = vatt_date;

select count(*) into vcurday_shift_count from emp_shift_planner where emp_fkey = vemp_pkey and shift_date = vcurday and status = 1;

if vcurday_shift_count > 0 then
	select shift_id into vcurday_shift from emp_shift_planner where emp_fkey = vemp_pkey and shift_date = vcurday and status = 1;
else
	set vcurday_shift = vdaytimeId;
end if;

select distinct isnextday, off_dutty1, max_in_time, max_out_time into vcur_isnextday, vcur_off_dutty1, vcur_max_in_time, vcur_max_out_time
from working_day_time_procedures where day_time_seq = vcurday_shift;

if vcur_max_in_time is null then
	set vcur_max_in_time = 60;
end if;

if vcur_isnextday = 0 then
	set vcur_max_out_time = round(time_to_sec(timediff('24:00:00', vcur_off_dutty1)) / 60);
else
	set vcurday = date_add(vatt_date, interval 1 day);
	
	if vcur_max_out_time is null then
		set vcur_max_out_time = 120;
	end if;
end if;

select lcase(C1) into vcurday_dir from device_attandance where device_attandance_seq in
(select max(device_attandance_seq) from device_attandance where emp_id = new.emp_id
and LOGDATE < new.LOGDATE and SHIFT = vcurday_shift and SHIFTDATE = vatt_date and ucase(status) = 'Y');

set vnextday = date_add(vatt_date, interval 1 day);

select count(*) into vnextday_shift_count from emp_shift_planner where emp_fkey = vemp_pkey and shift_date = vnextday and status = 1;

if vnextday_shift_count > 0 then
	select shift_id into vnextday_shift from emp_shift_planner where emp_fkey = vemp_pkey and shift_date = vnextday and status = 1;
else
	set vnextday_shift = vdaytimeId;
end if;

select distinct on_dutty1 into vnext_on_dutty1
from working_day_time_procedures where day_time_seq = vnextday_shift;

if vprev_isnextday = 1 then
	if new.LOGDATE > date_add(date_format(concat(vprevday,' ',vprev_off_dutty1), '%Y-%m-%d %H:%i:%s'), interval vprev_max_out_time minute) then
		if new.LOGDATE > date_add(date_format(concat(vcurday,' ',vcur_off_dutty1), '%Y-%m-%d %H:%i:%s'), interval vcur_max_out_time minute) then
			set new.SHIFTDATE = date_add(vatt_date, interval 1 day);
		else
			if new.LOGDATE <= date_sub(date_format(concat(vcurday,' ',vcur_off_dutty1), '%Y-%m-%d %H:%i:%s'), interval vcur_max_in_time minute) then
				set new.SHIFTDATE = vatt_date;
			else
				if vcurday_dir = 'in' then
					set new.SHIFTDATE = vatt_date;
				else
					if new.LOGDATE > date_sub(date_format(concat(vnextday,' ',vnext_on_dutty1), '%Y-%m-%d %H:%i:%s'), interval 120 minute) then
						set new.SHIFTDATE = date_add(vatt_date, interval 1 day);
					else
						set new.SHIFTDATE = vatt_date;
					end if;
				end if;
			end if;
		end if;
	else
		if new.LOGDATE <= date_sub(date_format(concat(vprevday,' ',vprev_off_dutty1), '%Y-%m-%d %H:%i:%s'), interval vprev_max_in_time minute) then
			set new.SHIFTDATE = date_sub(vatt_date, interval 1 day);
		else
			if vprevday_dir = 'in' then
				set new.SHIFTDATE = date_sub(vatt_date, interval 1 day);
			else
				if new.LOGDATE > date_add(date_format(concat(vcurday,' ',vcur_off_dutty1), '%Y-%m-%d %H:%i:%s'), interval vcur_max_out_time minute) then
					set new.SHIFTDATE = date_add(vatt_date, interval 1 day);
				else
					if new.LOGDATE <= date_sub(date_format(concat(vcurday,' ',vcur_off_dutty1), '%Y-%m-%d %H:%i:%s'), interval vcur_max_in_time minute) then
						set new.SHIFTDATE = vatt_date;
					else
						if vcurday_dir = 'in' then
							set new.SHIFTDATE = vatt_date;
						else
							if new.LOGDATE > date_sub(date_format(concat(vnextday,' ',vnext_on_dutty1), '%Y-%m-%d %H:%i:%s'), interval 120 minute) then
								set new.SHIFTDATE = date_add(vatt_date, interval 1 day);
							else
								set new.SHIFTDATE = vatt_date;
							end if;
						end if;
					end if;
				end if;
			end if;
		end if;
	end if;
else
	if new.LOGDATE > date_add(date_format(concat(vcurday,' ',vcur_off_dutty1), '%Y-%m-%d %H:%i:%s'), interval vcur_max_out_time minute) then
		set new.SHIFTDATE = date_add(vatt_date, interval 1 day);
	else
		if new.LOGDATE <= date_sub(date_format(concat(vcurday,' ',vcur_off_dutty1), '%Y-%m-%d %H:%i:%s'), interval vcur_max_in_time minute) then
			set new.SHIFTDATE = vatt_date;
		else
			if vcurday_dir = 'in' then
				set new.SHIFTDATE = vatt_date;
			else
				if new.LOGDATE > date_sub(date_format(concat(vnextday,' ',vnext_on_dutty1), '%Y-%m-%d %H:%i:%s'), interval 120 minute) then
					set new.SHIFTDATE = date_add(vatt_date, interval 1 day);
				else
					set new.SHIFTDATE = vatt_date;
				end if;
			end if;
		end if;
	end if;
end if;

select count(*) into vshift_count from emp_shift_planner where emp_fkey = vemp_pkey and shift_date = new.SHIFTDATE and status = 1;

if vshift_count > 0 then
	select shift_id into vdaytimeId from emp_shift_planner where emp_fkey = vemp_pkey and shift_date = new.SHIFTDATE and status = 1;
end if;

set new.SHIFT = vdaytimeId;

select count(*) into vlast_punch_count from device_attandance where device_attandance_seq in
(select max(device_attandance_seq) from device_attandance where emp_id = new.emp_id
and LOGDATE < new.LOGDATE and ucase(status) = 'Y');

if vlast_punch_count > 0 then
	select LOGDATE, C1 into vlast_punch, vlast_dir from device_attandance where device_attandance_seq in
	(select max(device_attandance_seq) from device_attandance where emp_id = new.emp_id
	and LOGDATE < new.LOGDATE and ucase(status) = 'Y');
	
	if timestampdiff(second, vlast_punch, new.LOGDATE) <= 10 then
		if (new.DEVICEID = 0 and new.C1 = vlast_dir) or new.DEVICEID != 0 then
			set new.status = 'N';
		end if;
	end if;
end if;

select ifnull(DeviceDirection, 'altinout') into vdirection from mypayrol_control_db.devices where DeviceId = new.DEVICEID limit 1;

if new.DEVICEID != 0 and vdirection != 'altinout' then
	set new.C1 = ifnull(new.DIRECTION, new.C1);
elseif (new.DEVICEID != '0' and vdirection = 'altinout') or new.C2 = 'MOB' then
	select count(*) into vpunch_count from device_attandance where SHIFTDATE = new.SHIFTDATE
	and ucase(status) = 'Y' and emp_id = new.emp_id;
	
	if vpunch_count = 0 then
		set new.C1 = 'in';
	else
		select lcase(C1) into vprev_dir from device_attandance where device_attandance_seq in
		(select max(device_attandance_seq) from device_attandance where emp_id = new.emp_id
		and LOGDATE < new.LOGDATE and SHIFTDATE = new.SHIFTDATE and ucase(status) = 'Y');
		
		if vprev_dir='in' then
			set new.C1='out';
		elseif vprev_dir='out' then
			set new.C1='in';
		end if;
	end if;
end if;
end;;

CREATE TRIGGER `device_attandance_ai` AFTER INSERT ON `device_attandance` FOR EACH ROW
begin
declare vemp_pkey int;
declare vshift_date date;
declare vyearmonth date;
declare vdaytimeId  int;
declare vLOGDATE_intime datetime;
declare vLOGDATE_outime datetime;
declare vduration int;
declare vminuts_calc_perday int;
declare vminutes_per_half int;
declare vsetvalue varchar(10);
declare vmonthly_att_fromdate date;
declare vmonthly_att_todate date;
declare vemp_count int;
declare von_dutty1 varchar(10);
declare voff_dutty1 varchar(10);
declare visnextday int;
declare vstrict_monitorings varchar(10);
declare vis_exception int;
declare von_dutty4 varchar(30);
declare voff_dutty4 varchar(30);
declare vworking_time4 varchar(30);
declare vinclude_break char(1);
declare vINTIME datetime;
declare	vOUTTIME  datetime;
declare von_dutty2 varchar(10);
declare voff_dutty2 varchar(10);
declare vworking_time2 varchar(10);
declare vworking_time1 varchar(10);
declare vfirst_duration float;
declare vsecond_duration float;
declare vvouttime datetime;
declare vtc varchar(100);
declare vminuts_aftr_on_dutty_cal_late int;
declare vminuts_bfr_off_dutty_cal_early int;
declare vstring varchar(1000);
declare vday_time_desc varchar(100);
declare vshift_string varchar(1000);
declare vcount int;
declare vemp_Vercount int;
declare vshift_count int;

set vshift_date = new.SHIFTDATE;

select emp_pkey into vemp_pkey from emp_details where emp_id=new.emp_id;

select count(*) into vshift_count from emp_shift_planner where emp_fkey = vemp_pkey and shift_date = vshift_date and status = 1;

if vshift_count > 0 then
	select shift_id into vdaytimeId from emp_shift_planner where emp_fkey = vemp_pkey and shift_date = vshift_date and status = 1;
else
	select day_time_seq into vdaytimeId from emp_proff where emp_fkey = vemp_pkey;
end if;

select distinct minuts_calc_perday, minutes_per_half, day_time_desc, strict_monitorings, is_exception, on_dutty1, off_dutty1, working_time1, isnextday, include_break
into vminuts_calc_perday, vminutes_per_half, vday_time_desc, vstrict_monitorings, vis_exception, von_dutty1, voff_dutty1, vworking_time1, visnextday, vinclude_break
from working_day_time_procedures where day_time_seq = vdaytimeId;

if vis_exception = 1 then
	block1:begin
	declare vex_week_day varchar(20);
	declare vex_week varchar(10);
	declare vin_time time;
	declare vout_time time;
	declare vduration int;
	declare vfull_day int;
	declare vhalf_day int;
	declare vweek int;
	
	declare exit_loop1 boolean default false;
	
	declare exception_cur cursor for
	select ex_week_day, ex_week, in_time, out_time, full_day, half_day from shift_exceptions
	where shift_id = vdaytimeId and week_off = 'N' and status = 1;
	
	declare continue handler for not found set exit_loop1 = true;
	
	open exception_cur;
	start_loop1: loop
		fetch exception_cur into vex_week_day, vex_week, vin_time, vout_time, vfull_day, vhalf_day;
		
		if exit_loop1 then
			leave start_loop1;
		end if;
		
		set vweek = floor((dayofmonth(vshift_date) - 1) / 7) + 1;
		
		if lcase(dayname(vshift_date)) = lcase(vex_week_day) then
			if vex_week = 'A' or vweek = cast(vex_week as unsigned) then
				set von_dutty1 = vin_time;
				set voff_dutty1 = vout_time;
				set vminuts_calc_perday = vfull_day;
				set vminutes_per_half = vhalf_day;
			end if;
		end if;
	end loop start_loop1;
	close exception_cur;
	end block1;
end if;

set vstring = concat(vdaytimeId, '(', vday_time_desc, ')-', von_dutty1, ' ', voff_dutty1, ' ', vminuts_calc_perday , ' ', vminutes_per_half, ' ', vstrict_monitorings);

select min(LOGDATE) into vLOGDATE_intime from device_attandance att, emp_details ed
where att.emp_id = ed.emp_id and att.company_code = ed.company_code and lcase(c1) = 'in'
and ed.emp_pkey = vemp_pkey and ucase(att.status) = 'Y' and att.SHIFTDATE = vshift_date;

select max(LOGDATE) into vLOGDATE_outime from device_attandance att, emp_details ed
where att.emp_id = ed.emp_id and att.company_code = ed.company_code and lcase(c1) = 'out'
and ed.emp_pkey = vemp_pkey and ucase(att.status) = 'Y' and att.SHIFTDATE = vshift_date;

if vLOGDATE_outime is not null then
	if vinclude_break = 'Y' then
		set vINTIME = vLOGDATE_intime;
		
		if vLOGDATE_intime < vLOGDATE_outime then
			set vOUTTIME = vLOGDATE_outime;  
		else
			set vOUTTIME = null; 
			set vLOGDATE_outime = null;
		end if; 			  
		
		if ucase(vstrict_monitorings) = 'Y' and vLOGDATE_outime is not null then
			if visnextday = 1 then 
				select date_add(vshift_date, interval 1 day) into vvouttime;
			else
				set vvouttime = vLOGDATE_intime;
			end if;
			
			if vLOGDATE_intime <= date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %T') then
				if vLOGDATE_intime <= date_format(concat(date_format(vshift_date, '%Y-%m-%d'), ' ', von_dutty1), '%Y-%m-%d %H:%i:%s') then
					set vINTIME = date_format(concat(date_format(vshift_date, '%Y-%m-%d'), ' ', von_dutty1), '%Y-%m-%d %H:%i:%s');
				else 
					set vINTIME = vINTIME;
				end if; 
				
				if visnextday = 1 then 
					select date_add(vshift_date, interval 1 day) into vvouttime;
				else
					set vvouttime = vINTIME;
				end if;
				
				if vLOGDATE_outime >= date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %T') then
					set vOUTTIME = date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %T');
				else 
					set vOUTTIME = vLOGDATE_outime;
				end if; 
				
				if vINTIME > vOUTTIME then
					set vOUTTIME = null;   
				end if;
			else
				set vINTIME = vLOGDATE_intime;
				set vOUTTIME = vLOGDATE_outime;  
			end if;
		end if;
		
		if vINTIME is not null and vOUTTIME is not null then
			set vduration = greatest(timestampdiff(minute, vINTIME, vOUTTIME), 0);
		end if;
	else
		block2:begin
		declare vfirst_name varchar(100);
		declare	vinval varchar(30);
		declare	voutval varchar(30);
		declare vvouttime datetime;
		
		declare exit_loop2 boolean default false;
		
		declare break_cur cursor for
			select
				FIRST_NAME, EMP_PKEY, INTIME, INVAL,
				(case when INVAL = 'in' and OUTVAL = 'in' then null else OUTTIME end) as OUTTIME,
				OUTVAL
			from
				(
					select 
						MO.C1 as OUTVAL, MO.EMP_PKEY, MO.FIRST_NAME,
						MO.LOGDATE as OUTTIME,
						@S as 'lead(logdate) over(partition by emp_pkey order by logdate)',
						@LOGIN := @S as INTIME,
						@C as 'lead(c1) over(partition by emp_pkey order by logdate)',
						@INVAL := @C as INVAL,
						(case when @PARTITION_BY_COLUMN = EMP_PKEY or @_SEASON is null then @S := LOGDATE
																						else @S := null
							end) TMP_VALUE,
						(case when @PARTITION_BY_COLUMN = EMP_PKEY or @_SEASON is null then @C := C1
																						else @C := null
							end) TMP_VALUE1,
						(@PARTITION_BY_COLUMN := EMP_PKEY) PARTITION_COLUMN
					from 
						(
							select 
									ed.emp_pkey, ed.first_name, att.logdate, lcase(att.c1) c1
							from (select @PARTITION_BY_COLUMN = null,
										@S := null,
										@C := null,
										@LOGIN := null,
										@INVAL := null
								) vars, device_attandance att, emp_details ed
							where 
									att.emp_id = ed.emp_id and ucase(att.status) = 'Y'
									and ed.emp_pkey = vemp_pkey
									and date_format(att.logdate, '%Y-%m-%d %T') between 
										date_format(vLOGDATE_intime, '%Y-%m-%d %T') and date_format(vLOGDATE_outime, '%Y-%m-%d %T')
						order by LOGDATE) MO
				) XX
			where INVAL = 'in' and OUTVAL in ('out');
		
		declare continue handler for not found set exit_loop2 = true;
		
		set vduration = 0;
		
		open break_cur;
		start_loop2: loop
			fetch break_cur into vfirst_name, vemp_pkey, vINTIME, vinval, vOUTTIME, voutval;
			
			if exit_loop2 then
				leave start_loop2;
			end if;
			
			if ucase(vstrict_monitorings) = 'Y' then
				if visnextday = 1 then 
					select date_add(vshift_date, interval 1 day) into vvouttime;
				else
					set vvouttime = vLOGDATE_intime;
				end if;
				
				if vINTIME <= date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %H:%i:%s') then
					if vINTIME <= date_format(concat(date_format(vINTIME, '%Y-%m-%d'), ' ', von_dutty1), '%Y-%m-%d %H:%i:%s') then
						set vINTIME = date_format(concat(date_format(vINTIME, '%Y-%m-%d'), ' ', von_dutty1), '%Y-%m-%d %H:%i:%s');
					else
						set vINTIME = vINTIME;
					end if; 
					
					if visnextday = 1 then 
						select date_add(vshift_date, interval 1 day) into vvouttime;
					else
						set vvouttime = vLOGDATE_intime;
					end if; 

					if vOUTTIME >= date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %H:%i:%s') then
						set vOUTTIME = date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %H:%i:%s');
					else 
						set vOUTTIME = vOUTTIME;
					end if;
				else
					set vINTIME = null;
					set vOUTTIME = null;
				end if;
			end if;
			
			if vINTIME is not null and vOUTTIME is not null then
				set vduration = greatest(vduration + timestampdiff(minute, vINTIME, vOUTTIME), 0);
			end if;
		end loop start_loop2;
		close break_cur;
		end block2;
	end if;
	
	if ucase(vstrict_monitorings) = 'Y' then
		if vduration >= vminuts_calc_perday then 
			set vsetvalue = 'P/P';
		elseif vduration >= vminutes_per_half then
			if vINTIME = date_format(concat(date_format(vINTIME, '%Y-%m-%d'), ' ', von_dutty1), '%Y-%m-%d %H:%i:%s') then
				set vsetvalue='P/A';
			elseif vouttime = date_format(concat(date_format(vouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %H:%i:%s') then
				set vsetvalue = 'A/P';
			else
				set vsetvalue = 'P/A';
			end if;
		elseif vduration < vminutes_per_half then
			set vsetvalue = 'A/A';
		else
			set vsetvalue = 'A/A';
		end if;
	else
		if vduration >= vminuts_calc_perday then 
			set vsetvalue = 'P/P';
		elseif vduration >= vminutes_per_half then
			set vsetvalue = 'P/A';
		elseif vduration < vminutes_per_half then
			set vsetvalue = 'A/A';
		else
			set vsetvalue = 'A/A';
		end if;
	end if;
elseif vLOGDATE_outime is null and vLOGDATE_intime is not null then
	set vsetvalue = 'A/A';
end if;

select att_start_end_fn(date_format(vshift_date, '%Y-%m-01'), 1) into vmonthly_att_fromdate;
select att_start_end_fn(date_format(vshift_date, '%Y-%m-01'), 2) into vmonthly_att_todate;

if vshift_date between vmonthly_att_fromdate and vmonthly_att_todate then
	set vyearmonth = date_format(vshift_date, '%Y-%m-01');
else
	set vyearmonth = date_add(date_format(vshift_date, '%Y-%m-01'), interval 1 month);
end if;

select count(*) into vemp_count from emp_detail_timeattandance 
where emp_pkey = vemp_pkey and att_date = vshift_date;

select count(*) into vemp_Vercount from emp_ot_timeattandance where emp_pkey = vemp_pkey and att_date = vshift_date and isdelete = 'N';

if vemp_Vercount = 0 then
	if vemp_count = 0 then
		insert into emp_detail_timeattandance (emp_pkey, att_date, att_in_time, att_out_time, duration, present, yearmonth, shift_string, day_time_id)
		values (vemp_pkey, vshift_date, vLOGDATE_intime, vLOGDATE_outime, vduration, vsetvalue, vyearmonth, vstring, vdaytimeId);
	else
		update emp_detail_timeattandance set yearmonth = vyearmonth, att_in_time = vLOGDATE_intime, att_out_time = vLOGDATE_outime, duration = vduration, present = vsetvalue, shift_string = vstring, day_time_id = vdaytimeId
		where emp_pkey = vemp_pkey and att_date = vshift_date;
	end if;
end if;
end;;

CREATE TRIGGER `device_attandance_au` AFTER UPDATE ON `device_attandance` FOR EACH ROW
begin
declare vemp_pkey int;
declare vshift_date date;
declare vyearmonth date;
declare vdaytimeId  int;
declare vLOGDATE_intime datetime;
declare vLOGDATE_outime datetime;
declare vduration int;
declare vminuts_calc_perday int;
declare vminutes_per_half int;
declare vsetvalue varchar(10);
declare vmonthly_att_fromdate date;
declare vmonthly_att_todate date;
declare vemp_count int;
declare von_dutty1 varchar(10);
declare voff_dutty1 varchar(10);
declare visnextday int;
declare vstrict_monitorings varchar(10);
declare vis_exception int;
declare von_dutty4 varchar(30);
declare voff_dutty4 varchar(30);
declare vworking_time4 varchar(30);
declare vinclude_break char(1);
declare vINTIME datetime;
declare	vOUTTIME  datetime;
declare von_dutty2 varchar(10);
declare voff_dutty2 varchar(10);
declare vworking_time2 varchar(10);
declare vworking_time1 varchar(10);
declare vfirst_duration float;
declare vsecond_duration float;
declare vvouttime datetime;
declare vtc varchar(100);
declare vminuts_aftr_on_dutty_cal_late int;
declare vminuts_bfr_off_dutty_cal_early int;
declare vstring varchar(1000);
declare vday_time_desc varchar(100);
declare vshift_string varchar(1000);
declare vcount int;
declare vemp_Vercount int;
declare vshift_count int;

set vshift_date = new.SHIFTDATE;

select emp_pkey into vemp_pkey from emp_details where emp_id=new.emp_id;

select count(*) into vshift_count from emp_shift_planner where emp_fkey = vemp_pkey and shift_date = vshift_date and status = 1;

if vshift_count > 0 then
	select shift_id into vdaytimeId from emp_shift_planner where emp_fkey = vemp_pkey and shift_date = vshift_date and status = 1;
else
	select day_time_seq into vdaytimeId from emp_proff where emp_fkey = vemp_pkey;
end if;

select distinct minuts_calc_perday, minutes_per_half, day_time_desc, strict_monitorings, is_exception, on_dutty1, off_dutty1, working_time1, isnextday, include_break
into vminuts_calc_perday, vminutes_per_half, vday_time_desc, vstrict_monitorings, vis_exception, von_dutty1, voff_dutty1, vworking_time1, visnextday, vinclude_break
from working_day_time_procedures where day_time_seq = vdaytimeId;

if vis_exception = 1 then
	block1:begin
	declare vex_week_day varchar(20);
	declare vex_week varchar(10);
	declare vin_time time;
	declare vout_time time;
	declare vduration int;
	declare vfull_day int;
	declare vhalf_day int;
	declare vweek int;
	
	declare exit_loop1 boolean default false;
	
	declare exception_cur cursor for
	select ex_week_day, ex_week, in_time, out_time, full_day, half_day from shift_exceptions
	where shift_id = vdaytimeId and week_off = 'N' and status = 1;
	
	declare continue handler for not found set exit_loop1 = true;
	
	open exception_cur;
	start_loop1: loop
		fetch exception_cur into vex_week_day, vex_week, vin_time, vout_time, vfull_day, vhalf_day;
		
		if exit_loop1 then
			leave start_loop1;
		end if;
		
		set vweek = floor((dayofmonth(vshift_date) - 1) / 7) + 1;
		
		if lcase(dayname(vshift_date)) = lcase(vex_week_day) then
			if vex_week = 'A' or vweek = cast(vex_week as unsigned) then
				set von_dutty1 = vin_time;
				set voff_dutty1 = vout_time;
				set vminuts_calc_perday = vfull_day;
				set vminutes_per_half = vhalf_day;
			end if;
		end if;
	end loop start_loop1;
	close exception_cur;
	end block1;
end if;

set vstring = concat(vdaytimeId, '(', vday_time_desc, ')-', von_dutty1, ' ', voff_dutty1, ' ', vminuts_calc_perday , ' ', vminutes_per_half, ' ', vstrict_monitorings);

select min(LOGDATE) into vLOGDATE_intime from device_attandance att, emp_details ed
where att.emp_id = ed.emp_id and att.company_code = ed.company_code and lcase(c1) = 'in'
and ed.emp_pkey = vemp_pkey and ucase(att.status) = 'Y' and att.SHIFTDATE = vshift_date;

select max(LOGDATE) into vLOGDATE_outime from device_attandance att, emp_details ed
where att.emp_id = ed.emp_id and att.company_code = ed.company_code and lcase(c1) = 'out'
and ed.emp_pkey = vemp_pkey and ucase(att.status) = 'Y' and att.SHIFTDATE = vshift_date;

if vLOGDATE_outime is not null then
	if vinclude_break = 'Y' then
		set vINTIME = vLOGDATE_intime;
		
		if vLOGDATE_intime < vLOGDATE_outime then
			set vOUTTIME = vLOGDATE_outime;  
		else
			set vOUTTIME = null; 
			set vLOGDATE_outime = null;
		end if; 			  
		
		if ucase(vstrict_monitorings) = 'Y' and vLOGDATE_outime is not null then
			if visnextday = 1 then 
				select date_add(vshift_date, interval 1 day) into vvouttime;
			else
				set vvouttime = vLOGDATE_intime;
			end if;
			
			if vLOGDATE_intime <= date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %T') then
				if vLOGDATE_intime <= date_format(concat(date_format(vshift_date, '%Y-%m-%d'), ' ', von_dutty1), '%Y-%m-%d %H:%i:%s') then
					set vINTIME = date_format(concat(date_format(vshift_date, '%Y-%m-%d'), ' ', von_dutty1), '%Y-%m-%d %H:%i:%s');
				else 
					set vINTIME = vINTIME;
				end if; 
				
				if visnextday = 1 then 
					select date_add(vshift_date, interval 1 day) into vvouttime;
				else
					set vvouttime = vINTIME;
				end if;
				
				if vLOGDATE_outime >= date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %T') then
					set vOUTTIME = date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %T');
				else 
					set vOUTTIME = vLOGDATE_outime;
				end if; 
				
				if vINTIME > vOUTTIME then
					set vOUTTIME = null;   
				end if;
			else
				set vINTIME = vLOGDATE_intime;
				set vOUTTIME = vLOGDATE_outime;  
			end if;
		end if;
		
		if vINTIME is not null and vOUTTIME is not null then
			set vduration = greatest(timestampdiff(minute, vINTIME, vOUTTIME), 0);
		end if;
	else
		block2:begin
		declare vfirst_name varchar(100);
		declare	vinval varchar(30);
		declare	voutval varchar(30);
		declare vvouttime datetime;
		
		declare exit_loop2 boolean default false;
		
		declare break_cur cursor for
			select
				FIRST_NAME, EMP_PKEY, INTIME, INVAL,
				(case when INVAL = 'in' and OUTVAL = 'in' then null else OUTTIME end) as OUTTIME,
				OUTVAL
			from
				(
					select 
						MO.C1 as OUTVAL, MO.EMP_PKEY, MO.FIRST_NAME,
						MO.LOGDATE as OUTTIME,
						@S as 'lead(logdate) over(partition by emp_pkey order by logdate)',
						@LOGIN := @S as INTIME,
						@C as 'lead(c1) over(partition by emp_pkey order by logdate)',
						@INVAL := @C as INVAL,
						(case when @PARTITION_BY_COLUMN = EMP_PKEY or @_SEASON is null then @S := LOGDATE
																						else @S := null
							end) TMP_VALUE,
						(case when @PARTITION_BY_COLUMN = EMP_PKEY or @_SEASON is null then @C := C1
																						else @C := null
							end) TMP_VALUE1,
						(@PARTITION_BY_COLUMN := EMP_PKEY) PARTITION_COLUMN
					from 
						(
							select 
									ed.emp_pkey, ed.first_name, att.logdate, lcase(att.c1) c1
							from (select @PARTITION_BY_COLUMN = null,
										@S := null,
										@C := null,
										@LOGIN := null,
										@INVAL := null
								) vars, device_attandance att, emp_details ed
							where 
									att.emp_id = ed.emp_id and ucase(att.status) = 'Y'
									and ed.emp_pkey = vemp_pkey
									and date_format(att.logdate, '%Y-%m-%d %T') between 
										date_format(vLOGDATE_intime, '%Y-%m-%d %T') and date_format(vLOGDATE_outime, '%Y-%m-%d %T')
						order by LOGDATE) MO
				) XX
			where INVAL = 'in' and OUTVAL in ('out');
		
		declare continue handler for not found set exit_loop2 = true;
		
		set vduration = 0;
		
		open break_cur;
		start_loop2: loop
			fetch break_cur into vfirst_name, vemp_pkey, vINTIME, vinval, vOUTTIME, voutval;
			
			if exit_loop2 then
				leave start_loop2;
			end if;
			
			if ucase(vstrict_monitorings) = 'Y' then
				if visnextday = 1 then 
					select date_add(vshift_date, interval 1 day) into vvouttime;
				else
					set vvouttime = vLOGDATE_intime;
				end if;
				
				if vINTIME <= date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %H:%i:%s') then
					if vINTIME <= date_format(concat(date_format(vINTIME, '%Y-%m-%d'), ' ', von_dutty1), '%Y-%m-%d %H:%i:%s') then
						set vINTIME = date_format(concat(date_format(vINTIME, '%Y-%m-%d'), ' ', von_dutty1), '%Y-%m-%d %H:%i:%s');
					else
						set vINTIME = vINTIME;
					end if; 
					
					if visnextday = 1 then 
						select date_add(vshift_date, interval 1 day) into vvouttime;
					else
						set vvouttime = vLOGDATE_intime;
					end if; 

					if vOUTTIME >= date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %H:%i:%s') then
						set vOUTTIME = date_format(concat(date_format(vvouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %H:%i:%s');
					else 
						set vOUTTIME = vOUTTIME;
					end if;
				else
					set vINTIME = null;
					set vOUTTIME = null;
				end if;
			end if;
			
			if vINTIME is not null and vOUTTIME is not null then
				set vduration = greatest(vduration + timestampdiff(minute, vINTIME, vOUTTIME), 0);
			end if;
		end loop start_loop2;
		close break_cur;
		end block2;
	end if;
	
	if ucase(vstrict_monitorings) = 'Y' then
		if vduration >= vminuts_calc_perday then 
			set vsetvalue = 'P/P';
		elseif vduration >= vminutes_per_half then
			if vINTIME = date_format(concat(date_format(vINTIME, '%Y-%m-%d'), ' ', von_dutty1), '%Y-%m-%d %H:%i:%s') then
				set vsetvalue='P/A';
			elseif vouttime = date_format(concat(date_format(vouttime, '%Y-%m-%d'), ' ', voff_dutty1), '%Y-%m-%d %H:%i:%s') then
				set vsetvalue = 'A/P';
			else
				set vsetvalue = 'P/A';
			end if;
		elseif vduration < vminutes_per_half then
			set vsetvalue = 'A/A';
		else
			set vsetvalue = 'A/A';
		end if;
	else
		if vduration >= vminuts_calc_perday then 
			set vsetvalue = 'P/P';
		elseif vduration >= vminutes_per_half then
			set vsetvalue = 'P/A';
		elseif vduration < vminutes_per_half then
			set vsetvalue = 'A/A';
		else
			set vsetvalue = 'A/A';
		end if;
	end if;
elseif vLOGDATE_outime is null and vLOGDATE_intime is not null then
	set vsetvalue = 'A/A';
end if;

select att_start_end_fn(date_format(vshift_date, '%Y-%m-01'), 1) into vmonthly_att_fromdate;
select att_start_end_fn(date_format(vshift_date, '%Y-%m-01'), 2) into vmonthly_att_todate;

if vshift_date between vmonthly_att_fromdate and vmonthly_att_todate then
	set vyearmonth = date_format(vshift_date, '%Y-%m-01');
else
	set vyearmonth = date_add(date_format(vshift_date, '%Y-%m-01'), interval 1 month);
end if;

select count(*) into vemp_count from emp_detail_timeattandance 
where emp_pkey = vemp_pkey and att_date = vshift_date;

select count(*) into vemp_Vercount from emp_ot_timeattandance where emp_pkey = vemp_pkey and att_date = vshift_date and isdelete = 'N';

if vemp_Vercount = 0 then
	if vemp_count = 0 then
		insert into emp_detail_timeattandance (emp_pkey, att_date, att_in_time, att_out_time, duration, present, yearmonth, shift_string, day_time_id)
		values (vemp_pkey, vshift_date, vLOGDATE_intime, vLOGDATE_outime, vduration, vsetvalue, vyearmonth, vstring, vdaytimeId);
	else
		update emp_detail_timeattandance set yearmonth = vyearmonth, att_in_time = vLOGDATE_intime, att_out_time = vLOGDATE_outime, duration = vduration, present = vsetvalue, shift_string = vstring, day_time_id = vdaytimeId
		where emp_pkey = vemp_pkey and att_date = vshift_date;
	end if;
end if;
end;;

DELIMITER ;

CREATE TABLE `device_attandance_hist` (
  `device_attandance_hist_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `device_attandance_seq` int(11) NOT NULL,
  `company_code` varchar(20) DEFAULT NULL,
  `branch_code` varchar(20) DEFAULT NULL,
  `DEVICELOGID` int(11) DEFAULT NULL,
  `DOWNLOADDATE` datetime DEFAULT NULL,
  `DEVICEID` int(11) DEFAULT NULL,
  `device_USERID` varchar(100) DEFAULT NULL,
  `emp_id` varchar(20) DEFAULT NULL,
  `LOGDATE` datetime DEFAULT NULL,
  `DIRECTION` varchar(50) DEFAULT NULL,
  `ATTDIRECTION` varchar(50) DEFAULT NULL,
  `C1` varchar(100) NOT NULL,
  `C2` varchar(100) DEFAULT NULL,
  `C3` varchar(100) DEFAULT NULL,
  `C4` varchar(100) DEFAULT NULL,
  `C5` varchar(100) DEFAULT NULL,
  `C6` varchar(100) DEFAULT NULL,
  `C7` varchar(100) DEFAULT NULL,
  `WORKCODE` varchar(100) DEFAULT NULL,
  `status` varchar(11) DEFAULT NULL,
  `created_by` varchar(50) NOT NULL,
  `creation_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `action` char(1) NOT NULL COMMENT 'if I then insert,U then update',
  PRIMARY KEY (`device_attandance_hist_pkey`),
  KEY `emp_id` (`emp_id`),
  KEY `LOGDATE` (`LOGDATE`),
  KEY `C1` (`C1`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `direct_po_details` (
  `direct_po_details_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `direct_po_fkey` int(11) NOT NULL,
  `item_code` int(11) NOT NULL,
  `uom` int(11) DEFAULT NULL,
  `ordered_qty` int(11) NOT NULL,
  `po_rate` int(11) DEFAULT NULL,
  `po_value` int(11) DEFAULT NULL,
  `created_by` varchar(50) DEFAULT NULL,
  `creation_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `modified_by` varchar(50) DEFAULT NULL,
  `modified_date` timestamp NULL DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`direct_po_details_pkey`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;


CREATE TABLE `direct_purchase_order` (
  `direct_po_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `direct_po_number` varchar(50) NOT NULL,
  `direct_po_date` date DEFAULT NULL,
  `location` varchar(50) NOT NULL,
  `remarks` varchar(50) DEFAULT NULL,
  `created_by` varchar(50) DEFAULT NULL,
  `creation_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modified_by` varchar(50) DEFAULT NULL,
  `modified_date` datetime DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`direct_po_pkey`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;


CREATE TABLE `division` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `div_code` varchar(20) NOT NULL,
  `div_name` varchar(100) NOT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `documents` (
  `document_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `emp_fkey` int(11) DEFAULT NULL,
  `template_fkey` int(11) NOT NULL,
  `doc_id` varchar(30) NOT NULL,
  `company_fkey` int(11) DEFAULT '0',
  `branch_fkey` int(11) DEFAULT '0',
  `supplier_fkey` int(11) DEFAULT '0',
  `customer_fkey` int(11) DEFAULT '0',
  `others_fkey` int(11) DEFAULT '0',
  `policy` int(11) DEFAULT '0',
  `document_name` varchar(100) NOT NULL,
  `document` text NOT NULL,
  `created_by` varchar(30) NOT NULL,
  `creation_date` datetime NOT NULL,
  `modified_by` varchar(30) NOT NULL,
  `modification_date` datetime NOT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`document_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `document_allocation` (
  `document_allocation_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `emp_fkey` int(11) NOT NULL,
  `document_upload_fkey` int(11) NOT NULL,
  `allocated_by` varchar(200) DEFAULT NULL,
  `allocated_date` datetime NOT NULL,
  `end_date_effective` datetime DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`document_allocation_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `document_upload` (
  `document_upload_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `document_name` varchar(100) NOT NULL,
  `document_path` varchar(300) NOT NULL,
  `type` varchar(300) DEFAULT NULL,
  `created_by` varchar(200) NOT NULL,
  `creation_date` datetime NOT NULL,
  `document_allocated_by` varchar(200) NOT NULL,
  `document_allocated_date` datetime DEFAULT NULL,
  `modified_by` varchar(200) DEFAULT NULL,
  `modification_date` datetime DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`document_upload_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `doc_images` (
  `image_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `image_url` varchar(250) DEFAULT NULL,
  `company_code` varchar(50) DEFAULT NULL,
  `created_by` varchar(50) NOT NULL,
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modified_by` varchar(50) NOT NULL,
  `modification_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`image_pkey`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;


CREATE TABLE `doc_template` (
  `template_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `template_name` varchar(200) NOT NULL,
  `template_content` text NOT NULL,
  `placeholders` varchar(500) NOT NULL,
  `availability` varchar(10) NOT NULL DEFAULT '0',
  `editable` varchar(10) NOT NULL DEFAULT '0',
  `policy` varchar(10) NOT NULL DEFAULT '0',
  `created_by` varchar(30) NOT NULL,
  `creation_date` datetime NOT NULL,
  `modified_by` varchar(30) DEFAULT NULL,
  `modification_date` datetime DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`template_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

INSERT INTO `doc_template` (`template_pkey`, `template_name`, `template_content`, `placeholders`, `availability`, `editable`, `policy`, `created_by`, `creation_date`, `modified_by`, `modification_date`, `status`) VALUES
(1,	'Recommendation Letter',	'<p style=\"text-align: justify;\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\"><span lang=\"EN-US\"><span style=\"color:black\">Dear Sir&nbsp; </span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\"><span lang=\"EN-US\" style=\"color:black\">It&#39;s my pleasure to recommend {:empolyee_name} for the position of -------- at your company. {:empolyee_name} and I worked together for just over two years when she was a {:employee_designation} in my department at {:comp_business_name} company.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\"><span lang=\"EN-US\" style=\"color:black\">During her time at {:comp_business_name},{:empolyee_name} was diligent and insightful. She/He was eager to both learn and implement --------- strategies. Ms.&nbsp;{:empolyee_name} mentioned to me that this prospective role at your company would involve leading initiatives aimed at growing prospect lists. She/He is remarkably well-suited for that task. </span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\"><span lang=\"EN-US\" style=\"color:black\">I recommend Ms.&nbsp;{:empolyee_name} without reservations &mdash; she/He had&nbsp; be a stellar addition to your company. Please do not hesitate to reach out with any questions. You can reach me at this email address or at (phone)</span></span></span></p>\n\n<p style=\"text-align: justify;\">&nbsp;</p>\n\n<p style=\"text-align: justify;\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\"><span lang=\"EN-US\" style=\"color:black\">Sincerely,</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\"><span lang=\"EN-US\" style=\"color:black\">Authoised Signatory</span></span></span></p>\n',	'emp,comp_contact',	'1',	'1',	'0',	'Admin',	'2021-06-02 13:58:43',	'',	'0000-00-00 00:00:00',	1),
(2,	'Offer Letter Format-1',	'<p><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">{:empolyee_name}</span></span></p>\n\n<p><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">{:employee_address}</span></span></p>\n\n<p><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">{:employee_city} {:employee_pincode}</span></span></p>\n\n<p><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">Dear&nbsp;{:empolyee_name} ,</span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">This letter is to offer you a position with the Company. It is with great pleasure that we offer you the position of {:employee_designation}. Based on your capabilities and accomplishments, I believe that your talents will not only benefit&nbsp;{:comp_business_name} but also that our mutual relationship will assist you in reaching your personal and professional goals.</span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">Your detailed compensation plan will be given to you at the time of joining. Your compensation will be {:employee_ctc}. Your compensation will also include Insurance (if applicable), Casual, Sick and Privilege leave and other benefits as per corporate policy.</span></span></p>\n\n<p style=\"margin-left:48px; text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">I am anticipating that you will accept this offer by Date (7 days from offer) Upon joining you will be required to sign an &ldquo;Employment Agreement&rdquo;. You will also be required to submit the following documents on the date of your reporting:</span></span></p>\n\n<ol style=\"list-style-type:lower-alpha\">\n	<li style=\"text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">Copy of PAN Card</span></span></li>\n	<li style=\"text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">Adhar card</span></span></li>\n	<li style=\"text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">Two passport-sized photographs.</span></span></li>\n</ol>\n\n<p class=\"MsoBodyText\" style=\"margin-bottom:8px; text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">You will be on probation for six months from the date of your joining.You services will be confirmed in writing after the successful completion of your probation period. The probation period may be extended if your performance does not meet expectations.</span></span></p>\n\n<p style=\"margin-left:48px; text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">Please indicate your acceptance of this offer by signing one copy of this letter in the space provided below. The additional copy is for your files.&nbsp;&nbsp; </span></span></p>\n\n<p style=\"margin-left:48px; text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">{:empolyee_name},I am eagerly looking forward to having you join our team.Should you have any questions, please do not hesitate to contact me.</span></span></p>\n\n<p style=\"margin-left:48px; text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">Sincerely:</span></span></p>\n\n<p style=\"margin-left:48px; text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">{:comp_business_name}</span></span></p>\n\n<p style=\"margin-left:48px; text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">Name of the Corcerned Person: </span></span></p>\n\n<p style=\"margin-left:48px; text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">Title:</span></span></p>\n\n<p style=\"margin-left:48px; text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">I accept this action as outlined above and confirm that my start date is:{:employee_joining_date}</span></span></p>\n\n<p style=\"margin-left:48px; text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">Signature: </span></span></p>\n\n<p style=\"margin-left:48px; text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">Name: </span></span></p>\n\n<p style=\"margin-left:48px; text-align:justify\"><span style=\"font-size:16px;\"><span style=\"font-family:Georgia,serif;\">Date: </span></span></p>\n',	'emp,comp_contact',	'1',	'1',	'0',	'Admin',	'2021-06-02 14:03:38',	'Admin',	'2021-06-02 14:39:24',	1),
(3,	'Offer Letter Format -2',	'<p style=\"margin-left:48px; text-align:justify\">&nbsp;</p>\n\n<p class=\"Address\"><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:10pt\"><span style=\"line-height:115%\"><span style=\"letter-spacing:0.2pt\"><w:sdtpr></w:sdtpr></span></span></span></span><br />\n&nbsp;</p>\n\n<p style=\"margin-bottom:16px\"><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:115%\"><span style=\"letter-spacing:0.2pt\">Dear {:empolyee_name}</span></span></span></span></p>\n\n<p style=\"margin-bottom:16px\"><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:115%\"><span style=\"letter-spacing:0.2pt\">{:comp_business_name}&nbsp;is excited to bring you on board as {:comp_business_nature}</span></span></span></span></p>\n\n<p style=\"margin-bottom:16px\"><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:115%\"><span style=\"letter-spacing:0.2pt\">Below you can read details about&nbsp;compensation, benefits and the terms and conditions of your anticipated job with {:comp_business_name}is offering a [full time, part time, etc.] position for you as{:comp_business_type}, reporting to {:comp_business_nature} starting on {:employee_joining_date} at {:employee_address}. Expected hours of work are [days of week and hours of work].&nbsp;</span></span></span></span></p>\n\n<p style=\"margin-bottom:16px\"><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:115%\"><span style=\"letter-spacing:0.2pt\">We&#39;ll&nbsp;start you at a pay rate of {:employee_ctc} per [year, hour, etc.]. You will be paid on a [weekly, monthly, etc] basis, starting [date of next pay period].&nbsp;</span></span></span></span></p>\n\n<p style=\"margin-bottom:16px\"><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:115%\"><span style=\"letter-spacing:0.2pt\">As part of your compensation, we&#39;re&nbsp;also offering&nbsp;[If applicable, you&rsquo;ll describe your bonus, profit sharing, stock options,&nbsp;commission structure, compensation committee&nbsp;here].</span></span></span></span></p>\n\n<p style=\"margin-bottom:16px\"><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:115%\"><span style=\"letter-spacing:0.2pt\">As an employee of{:comp_business_name} you will be eligible for [briefly name benefits, such as health insurance, dental insurance, etc.].</span></span></span></span></p>\n\n<p style=\"margin-bottom:16px\"><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:115%\"><span style=\"letter-spacing:0.2pt\">Got questions? Feel free to email us or call.&nbsp;</span></span></span></span></p>\n\n<p style=\"margin-bottom:16px\"><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:115%\"><span style=\"letter-spacing:0.2pt\">Sincerely,</span></span></span></span></p>\n\n<p class=\"MsoSignatureCxSpLast\" style=\"margin-bottom:16px\">&nbsp;</p>\n\n<p class=\"Address\"><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\">{:comp_business_name}</span></span></p>\n\n<p class=\"Address\">&nbsp;</p>\n\n<p class=\"Address\">&nbsp;</p>\n\n<p class=\"Address\">&nbsp;</p>\n\n<p class=\"Address\"><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:115%\"><span style=\"letter-spacing:0.2pt\"><w:sdt docpart=\"4D2CBD485DE1457AA2058A4406C0EC9E\" id=\"1634143502\" showingplchdr=\"t\" temporary=\"t\"></w:sdt><w:sdt docpart=\"4D2CBD485DE1457AA2058A4406C0EC9E\" showingplchdr=\"t\" temporary=\"t\"></w:sdt><w:sdt docpart=\"4D2CBD485DE1457AA2058A4406C0EC9E\" showingplchdr=\"t\" temporary=\"t\">{:comp_address}</w:sdt><w:sdt docpart=\"4D2CBD485DE1457AA2058A4406C0EC9E\" showingplchdr=\"t\" temporary=\"t\"></w:sdt><w:sdt docpart=\"4D2CBD485DE1457AA2058A4406C0EC9E\" showingplchdr=\"t\" temporary=\"t\"></w:sdt></span></span></span></span></p>\n\n<p class=\"Address\"><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:115%\"><span style=\"letter-spacing:0.2pt\">{:comp_city}{:comp_pincode}</span></span></span></span></p>\n\n<p class=\"Address\">&nbsp;</p>\n\n<p class=\"Address\">&nbsp;</p>\n\n<p class=\"Address\">&nbsp;</p>\n\n<p class=\"Address\">&nbsp;</p>\n\n<p class=\"Address\"><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:115%\"><span style=\"letter-spacing:0.2pt\"><w:sdtpr></w:sdtpr></span></span></span></span></p>\n\n<p class=\"Address\"><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\">{:empolyee_name}</span></span></p>\n\n<p><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\">{:employee_address}</span></span></p>\n\n<p><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\">{:employee_city} {:employee_pincode}</span></span></p>\n\n<p class=\"Address\">&nbsp;</p>\n\n<p class=\"MsoSignatureCxSpLast\" style=\"margin-bottom:16px\">&nbsp;</p>\n\n<p style=\"margin-left:48px; text-align:justify\">&nbsp;</p>\n\n<p style=\"margin-left:48px; text-align:justify\">&nbsp;</p>\n\n<p style=\"margin-left:48px; text-align:justify\">&nbsp;</p>\n\n<p style=\"margin-left:48px; text-align:justify\">&nbsp;</p>\n\n<p class=\"MsoSignatureCxSpLast\" style=\"margin-bottom:16px\">&nbsp;</p>\n\n<p class=\"MsoSignatureCxSpLast\" style=\"margin-bottom:16px\"><span style=\"font-family:Georgia,serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:115%\"><span style=\"letter-spacing:0.2pt\"><w:sdt docpart=\"89D13704633A4C1B90DD2A5E1EEA3BCC\" id=\"-1241632853\" showingplchdr=\"t\" temporary=\"t\">[Title]</w:sdt></span></span></span></span></p>\n\n<p style=\"margin-left:48px; text-align:justify\"><span style=\"f