CREATE TABLE `emi_upload` (
  `emi_upload_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `loan_pkey` int(11) NOT NULL,
  `emp_pkey` int(11) NOT NULL,
  `month_year` varchar(100) NOT NULL,
  `amt` int(11) NOT NULL,
  `creation_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`emi_upload_pkey`),
  KEY `emp_pkey` (`emp_pkey`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;


CREATE TABLE `employees_mssql` (
  `EmployeeId` int(11) NOT NULL,
  `EmployeeName` varchar(50) NOT NULL,
  `EmployeeCode` varchar(50) NOT NULL,
  `StringCode` varchar(50) NOT NULL,
  `NumericCode` int(11) NOT NULL,
  `Gender` varchar(255) NOT NULL,
  `CompanyId` int(11) NOT NULL,
  `DepartmentId` int(11) NOT NULL,
  `Designation` varchar(255) DEFAULT NULL,
  `CategoryId` int(11) NOT NULL,
  `DOJ` datetime DEFAULT NULL,
  `DOR` datetime DEFAULT NULL,
  `DOC` datetime DEFAULT NULL,
  `EmployeeCodeInDevice` varchar(50) NOT NULL,
  `EmployeeRFIDNumber` varchar(255) DEFAULT NULL,
  `EmployementType` varchar(255) NOT NULL,
  `Status` varchar(255) NOT NULL,
  `EmployeeDevicePassword` varchar(50) DEFAULT NULL,
  `EmployeeDeviceGroup` varchar(50) DEFAULT NULL,
  `FatherName` varchar(255) DEFAULT NULL,
  `MotherName` varchar(255) DEFAULT NULL,
  `ResidentialAddress` varchar(255) DEFAULT NULL,
  `PermanentAddress` varchar(255) DEFAULT NULL,
  `ContactNo` varchar(255) DEFAULT NULL,
  `Email` varchar(255) DEFAULT NULL,
  `DOB` datetime DEFAULT NULL,
  `PlaceOfBirth` varchar(255) DEFAULT NULL,
  `Nomenee1` varchar(255) DEFAULT NULL,
  `Nomenee2` varchar(255) DEFAULT NULL,
  `Remarks` text,
  `RecordStatus` int(11) DEFAULT NULL,
  `C1` varchar(255) DEFAULT NULL,
  `C2` varchar(255) DEFAULT NULL,
  `C3` varchar(255) DEFAULT NULL,
  `C4` varchar(255) DEFAULT NULL,
  `C5` varchar(255) DEFAULT NULL,
  `C6` varchar(255) DEFAULT NULL,
  `C7` varchar(255) DEFAULT NULL,
  `Location` varchar(255) DEFAULT NULL,
  `BLOODGROUP` varchar(255) DEFAULT NULL,
  `WorkPlace` varchar(255) DEFAULT NULL,
  `ExtensionNo` varchar(255) DEFAULT NULL,
  `LoginName` varchar(255) DEFAULT NULL,
  `LoginPassword` varchar(255) DEFAULT NULL,
  `Grade` varchar(255) DEFAULT NULL,
  `Team` varchar(255) DEFAULT NULL,
  `IsRecieveNotification` int(11) DEFAULT NULL,
  `HolidayGroup` int(11) DEFAULT NULL,
  `ShiftGroupId` int(11) DEFAULT NULL,
  `ShiftRosterId` int(11) DEFAULT NULL,
  `LastModifiedBy` varchar(50) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `employee_info` (`emp_pkey` int(11), `branch_code` varchar(30), `emp_id` varchar(30), `EmpName` varchar(302), `employee_id` varchar(30), `branch` varchar(200), `designation` varchar(100), `department` varchar(100), `joining_date` date, `grade` varchar(100), `emp_status` int(11));


CREATE TABLE `employee_regularaization` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `att_date` varchar(100) NOT NULL,
  `C1` varchar(100) NOT NULL,
  `C3` varchar(100) NOT NULL,
  `empid` varchar(100) NOT NULL,
  `LOGDATE` varchar(100) NOT NULL,
  `LOGTIME` varchar(100) NOT NULL,
  `approved` varchar(100) NOT NULL,
  `approved_person` varchar(100) DEFAULT NULL,
  `remarks` varchar(500) DEFAULT NULL,
  `status` int(11) NOT NULL,
  `created_by` varchar(100) DEFAULT NULL,
  `created_date` datetime DEFAULT NULL,
  `updated_by` varchar(100) DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;


CREATE TABLE `employee_structure_vview` (`emp_pkey` int(11), `EmpName` varchar(302), `employee_id` varchar(30), `branch` varchar(200), `designation` varchar(100), `department` varchar(100), `joining_date` date, `employee_type` varchar(50), `Salary_structure` varchar(200), `HOLIDAY_GROUP_NAME` varchar(200), `SHIFT_POLICYS` text, `LEAVEPOLICY` varchar(200), `hierarchy` varchar(302));


CREATE TABLE `emp_advance` (
  `emp_advance_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `emp_fkey` int(11) NOT NULL,
  `advance_amount` float NOT NULL,
  `affected_month` varchar(50) DEFAULT NULL,
  `is_credited` char(1) NOT NULL DEFAULT 'N',
  `remarks` text,
  `created_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` varchar(20) NOT NULL,
  `modified_by` varchar(20) NOT NULL,
  `modified_date` datetime NOT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  `payment_date` date DEFAULT NULL,
  PRIMARY KEY (`emp_advance_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `emp_advance_info` (
  `emp_advance_info_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `emp_fkey` int(11) NOT NULL,
  `advance_forthe_month` varchar(100) NOT NULL,
  `advance_amount` int(11) NOT NULL,
  `mode_of_advance` varchar(100) NOT NULL,
  `advance_details` varchar(500) NOT NULL,
  `attr1` varchar(500) NOT NULL,
  `attr2` int(11) NOT NULL,
  `attr3` int(11) NOT NULL,
  PRIMARY KEY (`emp_advance_info_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `emp_attendance_upload` (
  `emp_attendance_upload_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `emp_fkey` int(11) NOT NULL,
  `attendance_type` int(11) NOT NULL COMMENT '1 for simple attendance,2 for time attendance',
  `in_date` date NOT NULL,
  `in_time` time DEFAULT NULL,
  `out_date` date DEFAULT NULL,
  `out_time` time DEFAULT NULL,
  `created_by` varchar(30) NOT NULL,
  `created_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `is_updated` char(1) DEFAULT NULL COMMENT 'Y updated,N not updated',
  `updated_date` date DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT '1' COMMENT '1 active,0 inactive',
  PRIMARY KEY (`emp_attendance_upload_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DELIMITER ;;

CREATE TRIGGER `emp_attendance_upload_bi` BEFORE INSERT ON `emp_attendance_upload` FOR EACH ROW
begin
declare vtrans_count int;
declare vcompany varchar(30);
declare vbranch varchar(30);
declare vemp_id varchar(20);
declare vatt_count int;
declare vatt_pkey int;
declare vdeviceatt1 int;
declare vdeviceatt2 int;

select count(*) into vatt_count from emp_attendance_upload where emp_fkey=new.emp_fkey and in_date=new.in_date;

if vatt_count >0 then


set new.status=0;
else

select company_code,branch_code,emp_id into vcompany ,vbranch ,vemp_id 
             from emp_details where emp_pkey=new.emp_fkey;
if new.in_date is not null then
INSERT INTO  device_attandance  ( company_code ,  branch_code ,  DEVICELOGID ,  DOWNLOADDATE ,  DEVICEID ,  device_USERID ,  emp_id ,  LOGDATE ,  DIRECTION , C1 ,  C2 ,  C3 ) VALUES
(vcompany ,vbranch,	0,	concat(new.in_date,' ',new.in_time),	0,	'0',	vemp_id ,	concat(new.in_date,' ',new.in_time),	'',	'in',	'',	'Uploaded attandance');
end if;

if new.out_date is not null then
INSERT INTO  device_attandance  ( company_code ,  branch_code ,  DEVICELOGID ,  DOWNLOADDATE ,  DEVICEID ,  device_USERID ,  emp_id ,  LOGDATE ,  DIRECTION , C1 ,  C2 ,  C3 ) VALUES
(vcompany ,vbranch,	0,	concat(new.out_date,' ',new.out_time),	0,	'0',	vemp_id ,	concat(new.out_date ,' ',new.out_time),	'',	'out',	'',	'Uploaded attandance');
end if;
end if;
end;;

DELIMITER ;

