  `month_year` varchar(50) NOT NULL,
  `day_time_seq` varchar(50) NOT NULL,
  `salary_head_item_fkey` int(11) NOT NULL,
  `salary_head_item_desc` varchar(250) NOT NULL,
  `structure_det_value` decimal(10,2) DEFAULT NULL,
  `salary_rate` decimal(10,2) DEFAULT NULL,
  `salary_amount` decimal(10,2) DEFAULT NULL,
  `head_operator` varchar(30) DEFAULT NULL,
  `head_type` varchar(30) DEFAULT NULL,
  `item_part` varchar(30) DEFAULT NULL,
  `remarks` varchar(500) DEFAULT NULL,
  `created_by` varchar(30) DEFAULT NULL,
  `created_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modified_by` varchar(30) DEFAULT NULL,
