CREATE TABLE `emp_config` (
  `type` varchar(100) NOT NULL,
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_code` varchar(20) DEFAULT NULL,
  `branch_code` varchar(20) DEFAULT NULL,
  `emp_fkey` int(11) DEFAULT NULL,
  `month_year` varchar(20) DEFAULT NULL,
  `policy_id` int(11) DEFAULT NULL,
  `creation_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` varchar(50) DEFAULT NULL,
  `modified_by` varchar(50) DEFAULT NULL,
  `modification_date` datetime DEFAULT NULL,
  `hirc_leval` int(11) DEFAULT NULL,
  `hirc_up_flag` varchar(10) DEFAULT 'N',
  `status` int(11) NOT NULL DEFAULT '1' COMMENT '1=Active,0 inactive',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DELIMITER ;;

CREATE TRIGGER `emp_config_bi` BEFORE INSERT ON `emp_config` FOR EACH ROW
begin
declare vtrans_count int;

if new.type='SHIFT' then
update emp_proff set day_time_seq=new.policy_id where emp_fkey=new.emp_fkey;
elseif new.type='MSHIFT' then
update emp_proff set multishift=new.policy_id where emp_fkey=new.emp_fkey;
elseif new.type='HOLIDAY' then
update emp_proff set HOLIDAY_GROUP_ID=new.policy_id where emp_fkey=new.emp_fkey;
elseif new.type='SALARY' then
update emp_proff set structure_id=new.policy_id where emp_fkey=new.emp_fkey;
elseif new.type='LEAVE' then
update emp_proff set LEAVEPOLICY_GROUP_ID=new.policy_id where emp_fkey=new.emp_fkey;
elseif new.type='HIERARCHY' then
update emp_proff set attr1=new.policy_id where emp_fkey=new.emp_fkey;
elseif new.type='NOTICEPER' then
update emp_proff set notice_days=new.policy_id where emp_fkey=new.emp_fkey;
elseif new.type='DIVISION' then
update emp_proff set emp_vertical=new.policy_id where emp_fkey=new.emp_fkey;
elseif new.type='SECTION' then
update emp_proff set emp_sep_priv=new.policy_id where emp_fkey=new.emp_fkey;
elseif new.type='GRADE' then
update emp_proff set emp_grade=new.policy_id where emp_fkey=new.emp_fkey;
end if;
end;;

CREATE TRIGGER `emp_config_au` AFTER UPDATE ON `emp_config` FOR EACH ROW
begin
declare vtrans_count int;

if new.type='SHIFT' then
update emp_proff set day_time_seq=null,modified_by=new.modified_by where emp_fkey=new.emp_fkey;
elseif new.type='HOLIDAY' then
update emp_proff set HOLIDAY_GROUP_ID=null,modified_by=new.modified_by where emp_fkey=new.emp_fkey;
elseif new.type='SALARY' then
update emp_proff set structure_id=null ,modified_by=new.modified_by where emp_fkey=new.emp_fkey;
elseif new.type='LEAVE' then
update emp_proff set LEAVEPOLICY_GROUP_ID=null,modified_by=new.modified_by where emp_fkey=new.emp_fkey;
elseif new.type='HIERARCHY' then
update emp_proff set attr1=null ,modified_by=new.modified_by where emp_fkey=new.emp_fkey;
elseif new.type='NOTICEPER' then
update emp_proff set notice_days=null,modified_by=new.modified_by where emp_fkey=new.emp_fkey;
elseif new.type='DIVISION' then
update emp_proff set emp_vertical=null ,modified_by=new.modified_by where emp_fkey=new.emp_fkey;
elseif new.type='SECTION' then
update emp_proff set emp_sep_priv=null , modified_by=new.modified_by where emp_fkey=new.emp_fkey;
elseif new.type='GRADE' then
update emp_proff set emp_grade=null , modified_by=new.modified_by where emp_fkey=new.emp_fkey;
end if;
end;;

DELIMITER ;

CREATE TABLE `emp_config_history` (`emp_fkey` int(11), `type` varchar(100), `day_time_desc` text, `status` varchar(7), `creation_date` datetime, `created_by` varchar(50), `modification_date` datetime, `modified_by` varchar(50));


CREATE TABLE `emp_ctc_detail` (
  `emp_ctc_detail_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `emp_fkey` int(11) NOT NULL,
  `start_date_effective` date NOT NULL,
  `salary_head_item_fkey` int(11) NOT NULL,
  `salary_head_item_desc` varchar(250) NOT NULL,
  `structure_det_value` int(11) DEFAULT NULL,
  `salary_rate` float DEFAULT NULL,
  `salary_amount` float DEFAULT NULL,
  `creation_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `end_date_effective` date DEFAULT NULL,
  `created_by` varchar(30) DEFAULT NULL,
  `modified_by` varchar(30) DEFAULT NULL,
  `remarks` varchar(3000) DEFAULT NULL,
  PRIMARY KEY (`emp_ctc_detail_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `emp_ctc_transaction` (
  `emp_ctc_transaction` int(11) NOT NULL AUTO_INCREMENT,
  `ctc_upload_fkey` int(11) NOT NULL,
  `ctc_upload_type` int(11) NOT NULL DEFAULT '1' COMMENT '1 gross_uplaod, 2component_upload',
  `emp_fkey` int(11) NOT NULL,
  `emp_anual_ctc` float NOT NULL,
  `emp_derived_anualctc` float DEFAULT NULL,
  `created_by` varchar(30) NOT NULL,
  `created_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modified_date` date DEFAULT NULL,
  `modified_by` int(11) DEFAULT NULL,
  `end_date_effective` date DEFAULT NULL,
  `remarks` varchar(200) DEFAULT NULL,
  `arrear_salary` char(1) NOT NULL DEFAULT 'N',
  `pay_out_month` date DEFAULT NULL,
  `start_date_effective` date NOT NULL,
  `next_increment_date` date DEFAULT NULL,
  PRIMARY KEY (`emp_ctc_transaction`),
  KEY `emp_fkey` (`emp_fkey`),
  CONSTRAINT `emp_ctc_transaction_ibfk_1` FOREIGN KEY (`emp_fkey`) REFERENCES `emp_details` (`emp_pkey`) ON DELETE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `emp_ctc_upload` (
  `emp_ctc_upload_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `emp_fkey` int(11) NOT NULL,
  `emp_anual_ctc` int(11) NOT NULL,
  `emp_monthly_ctc` int(11) DEFAULT NULL,
  `emp_loan_balance` int(11) DEFAULT NULL,
  `emp_advance` int(11) DEFAULT NULL,
  `emp_tds_deducted` int(11) DEFAULT NULL,
  `arrear_salary` char(1) NOT NULL DEFAULT 'N',
  `pay_out_month` date DEFAULT NULL,
  `created_by` varchar(30) NOT NULL,
  `created_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `start_date_effective` date NOT NULL,
  `end_date_effective` date DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `status` int(11) DEFAULT '1',
  `next_increment_date` date DEFAULT NULL,
  `branch` varchar(100) DEFAULT NULL,
  `designation` varchar(100) DEFAULT NULL,
  `department` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`emp_ctc_upload_pkey`),
  KEY `emp_fkey` (`emp_fkey`),
  KEY `created_by` (`created_by`),
  CONSTRAINT `emp_ctc_upload_ibfk_1` FOREIGN KEY (`emp_fkey`) REFERENCES `emp_details` (`emp_pkey`) ON DELETE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DELIMITER ;;

CREATE TRIGGER `emp_ctc_upload_ai` AFTER INSERT ON `emp_ctc_upload` FOR EACH ROW
begin
declare vtrans_count int;
declare vstruture_id int;
declare vcompany_code varchar(30);
declare voutput varchar(30);
declare vupload_count int;

select count(*) into vtrans_count from emp_ctc_transaction where emp_fkey=new.emp_fkey and end_date_effective is null;
select count(*) into vupload_count from emp_ctc_upload where emp_fkey=new.emp_fkey and end_date_effective is null and emp_ctc_upload_pkey <> new.emp_ctc_upload_pkey ;

if vtrans_count >0 then 
update emp_ctc_transaction  set end_date_effective =new.start_date_effective-Interval 1 day,modified_by=new.created_by,modified_date=current_date where emp_fkey=new.emp_fkey and end_date_effective is null;
end if;

INSERT INTO emp_ctc_transaction (
        ctc_upload_fkey,
        emp_fkey,
        emp_anual_ctc,
        created_by,
        arrear_salary,
        pay_out_month,
        start_date_effective,
        next_increment_date
    ) VALUES (
        new.emp_ctc_upload_pkey,
        new.emp_fkey,
        new.emp_anual_ctc,
        new.created_by,
        new.arrear_salary,
        new.pay_out_month,
        new.start_date_effective,
        new.next_increment_date
    );

select structure_id into vstruture_id  from emp_proff where emp_fkey=new.emp_fkey;
select company_code into vcompany_code from emp_details  where emp_pkey=new.emp_fkey;
 	if vstruture_id  is not null then
	SELECT sal_structure_distribution_fn (vcompany_code ,new.emp_fkey, vstruture_id , new.created_by) into voutput ;
	end if;
end;;

DELIMITER ;

