) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DELIMITER ;;

CREATE TRIGGER `emp_detailed_attendance_uploads_bi` BEFORE INSERT ON `emp_detailed_attendance_uploads` FOR EACH ROW
begin
declare vtrans_count int;
declare vcompany varchar(30);
declare vbranch varchar(30);
declare vemp_id varchar(20);
declare vatt_count int;
declare vatt_pkey int;
declare vdeviceatt1 int;
declare vdeviceatt2 int;

select count(*) into vatt_count from emp_detailed_attendance_uploads where emp_fkey=new.emp_fkey and att_time=new.att_time;

if vatt_count >0 then


set new.status=0;
else

select company_code,branch_code,emp_id into vcompany ,vbranch ,vemp_id 
             from emp_details where emp_pkey=new.emp_fkey;
if new.att_time is not null then
 INSERT INTO  device_attandance  ( company_code ,  branch_code ,  DEVICELOGID ,  DOWNLOADDATE ,  DEVICEID ,  device_USERID ,  emp_id ,  LOGDATE ,  DIRECTION , C1 ,  C2 ,  C3 , c4, c5) VALUES
 (vcompany ,vbranch,	0,	new.att_time,	0,	vemp_id,	vemp_id ,	new.att_time,	new.c1,	 new.c1 ,	'',	'Uploaded attandance','1','1');
end if;

end if;
end;;

DELIMITER ;

CREATE TABLE `emp_details` (
  `emp_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `company_code` varchar(30) NOT NULL,
