) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DELIMITER ;;

CREATE TRIGGER `emp_details_bu` BEFORE UPDATE ON `emp_details` FOR EACH ROW
BEGIN
	
    IF (

        IFNULL(OLD.branch_code, '') != IFNULL(NEW.branch_code, '') OR
        IFNULL(OLD.first_name, '') != IFNULL(NEW.first_name, '') OR
        IFNULL(OLD.middile_name, '') != IFNULL(NEW.middile_name, '') OR
        IFNULL(OLD.last_name, '') != IFNULL(NEW.last_name, '') OR
        IFNULL(OLD.classification, '') != IFNULL(NEW.classification, '') OR
        IFNULL(OLD.address, '') != IFNULL(NEW.address, '') OR
        IFNULL(OLD.city, '') != IFNULL(NEW.city, '') OR
        IFNULL(OLD.state, '') != IFNULL(NEW.state, '') OR
        IFNULL(OLD.nationality_id, 0) != IFNULL(NEW.nationality_id, 0) OR
        IFNULL(OLD.pincode, '') != IFNULL(NEW.pincode, '') OR
        IFNULL(OLD.mobile_no, '') != IFNULL(NEW.mobile_no, '') OR
        IFNULL(OLD.email, '') != IFNULL(NEW.email, '') OR
        IFNULL(OLD.maritual_status, '') != IFNULL(NEW.maritual_status, '') OR
        IFNULL(OLD.education, '') != IFNULL(NEW.education, '') OR
        IFNULL(OLD.date_of_birth, '0000-00-00') != IFNULL(NEW.date_of_birth, '0000-00-00') OR
        IFNULL(OLD.bank_name, '') != IFNULL(NEW.bank_name, '') OR
        IFNULL(OLD.branch_name, '') != IFNULL(NEW.branch_name, '') OR
        IFNULL(OLD.branch_address, '') != IFNULL(NEW.branch_address, '') OR
        IFNULL(OLD.name_as_per_bank, '') != IFNULL(NEW.name_as_per_bank, '') OR
        IFNULL(OLD.ifsc_code, '') != IFNULL(NEW.ifsc_code, '') OR
        IFNULL(OLD.account_no, '') != IFNULL(NEW.account_no, '') OR
        IFNULL(OLD.pf, '') != IFNULL(NEW.pf, '') OR
        IFNULL(OLD.company_pf, '') != IFNULL(NEW.company_pf, '') OR
        IFNULL(OLD.previous_member_id, '') != IFNULL(NEW.previous_member_id, '') OR
        IFNULL(OLD.esi_dispensary, '') != IFNULL(NEW.esi_dispensary, '') OR
        IFNULL(OLD.blood, '') != IFNULL(NEW.blood, '') OR
        IFNULL(OLD.esi, '') != IFNULL(NEW.esi, '') OR
        IFNULL(OLD.eps, '') != IFNULL(NEW.eps, '') OR
        IFNULL(OLD.international_worker, '') != IFNULL(NEW.international_worker, '') OR
        IFNULL(OLD.country, 0) != IFNULL(NEW.country, 0) OR
        IFNULL(OLD.physical_handicap, '') != IFNULL(NEW.physical_handicap, '') OR
        IFNULL(OLD.locomotive, '') != IFNULL(NEW.locomotive, '') OR
        IFNULL(OLD.hearing, '') != IFNULL(NEW.hearing, '') OR
        IFNULL(OLD.visual, '') != IFNULL(NEW.visual, '') OR
        IFNULL(OLD.id_card, '') != IFNULL(NEW.id_card, '') OR
        IFNULL(OLD.name_as_on_aadhaar, '') != IFNULL(NEW.name_as_on_aadhaar, '') OR
        IFNULL(OLD.guradian, '') != IFNULL(NEW.guradian, '') OR
        IFNULL(OLD.relation_guardian, '') != IFNULL(NEW.relation_guardian, '') OR
        IFNULL(OLD.pan_no, '') != IFNULL(NEW.pan_no, '') OR
        IFNULL(OLD.name_as_on_pan, '') != IFNULL(NEW.name_as_on_pan, '') OR
        IFNULL(OLD.wps_code, '') != IFNULL(NEW.wps_code, '') OR
        IFNULL(OLD.status, 0) != IFNULL(NEW.status, 0) OR
        IFNULL(OLD.parent, 0) != IFNULL(NEW.parent, 0) OR
        IFNULL(OLD.attr3, '') != IFNULL(NEW.attr3, '') OR
        IFNULL(OLD.attr4, '') != IFNULL(NEW.attr4, '') OR
        IFNULL(OLD.attr5, '') != IFNULL(NEW.attr5, '') OR
        IFNULL(OLD.payment_type, '') != IFNULL(NEW.payment_type, '') OR
        IFNULL(OLD.lwf_code, '') != IFNULL(NEW.lwf_code, '') OR
        IFNULL(OLD.is_manager, 0) != IFNULL(NEW.is_manager, 0) OR
        IFNULL(OLD.profile_pic, '') != IFNULL(NEW.profile_pic, '') OR
        IFNULL(OLD.editable, 0) != IFNULL(NEW.editable, 0)

    ) THEN

        INSERT INTO emp_details_audit (

            emp_pkey,
            company_code,
            branch_code,
            emp_id,

            first_name,
            middile_name,
            last_name,
            classification,

            address,
            city,
            state,
            nationality_id,
            pincode,
            mobile_no,
            email,

            maritual_status,
            education,
            date_of_birth,

            bank_name,
            branch_name,
            branch_address,
            name_as_per_bank,
            ifsc_code,
            account_no,

            pf,
            company_pf,
            previous_member_id,
            esi_dispensary,
            blood,
            esi,
            eps,

            international_worker,
            country,
            physical_handicap,
            locomotive,
            hearing,
            visual,

            id_card,
            name_as_on_aadhaar,
            guradian,
            relation_guardian,

            pan_no,
            name_as_on_pan,
            wps_code,

            status,
            parent,

            attr3,
            attr4,
            attr5,

            payment_type,
            lwf_code,

            is_manager,
            profile_pic,
            editable,

            updated_date,
            updated_time

        ) VALUES (

            OLD.emp_pkey,
            OLD.company_code,
            OLD.branch_code,
            OLD.emp_id,

            OLD.first_name,
            OLD.middile_name,
            OLD.last_name,
            OLD.classification,

            OLD.address,
            OLD.city,
            OLD.state,
            OLD.nationality_id,
            OLD.pincode,
            OLD.mobile_no,
            OLD.email,

            OLD.maritual_status,
            OLD.education,
            OLD.date_of_birth,

            OLD.bank_name,
            OLD.branch_name,
            OLD.branch_address,
            OLD.name_as_per_bank,
            OLD.ifsc_code,
            OLD.account_no,

            OLD.pf,
            OLD.company_pf,
            OLD.previous_member_id,
            OLD.esi_dispensary,
            OLD.blood,
            OLD.esi,
            OLD.eps,

            OLD.international_worker,
            OLD.country,
            OLD.physical_handicap,
            OLD.locomotive,
            OLD.hearing,
            OLD.visual,

            OLD.id_card,
            OLD.name_as_on_aadhaar,
            OLD.guradian,
            OLD.relation_guardian,

            OLD.pan_no,
            OLD.name_as_on_pan,
            OLD.wps_code,

            OLD.status,
            OLD.parent,

            OLD.attr3,
            OLD.attr4,
            OLD.attr5,

            OLD.payment_type,
            OLD.lwf_code,

            OLD.is_manager,
            OLD.profile_pic,
            OLD.editable,

            CURDATE(),
            CURTIME()
        );
    END IF;
    SET NEW.modified_date = NOW();
END;;

DELIMITER ;

SET NAMES utf8mb4;

CREATE TABLE `emp_details_audit` (
