  `country` int(11) DEFAULT NULL,
  `physical_handicap` varchar(10) DEFAULT NULL,
  `locomotive` varchar(10) DEFAULT NULL,
  `hearing` varchar(10) DEFAULT NULL,
  `visual` varchar(10) DEFAULT NULL,
  `id_card` varchar(100) DEFAULT NULL,
  `name_as_on_aadhaar` varchar(100) DEFAULT NULL,
  `guradian` varchar(100) DEFAULT NULL,
  `relation_guardian` varchar(100) DEFAULT NULL,
  `pan_no` varchar(50) DEFAULT NULL,
