  `emp_type` varchar(50) DEFAULT NULL,
  `designation` varchar(100) DEFAULT NULL,
  `emp_dept` varchar(100) DEFAULT NULL,
  `emp_grade` varchar(100) DEFAULT NULL,
  `emp_vertical` varchar(100) DEFAULT NULL,
  `emp_branch` varchar(100) DEFAULT NULL,
  `HOLIDAY_GROUP_ID` int(11) DEFAULT NULL,
  `LEAVEPOLICY_GROUP_ID` int(11) DEFAULT NULL,
  `day_time_seq` int(11) DEFAULT NULL,
  `structure_id` int(11) DEFAULT NULL,
  `notice_days` int(11) DEFAULT NULL,
  `multishift` int(11) DEFAULT NULL,
  `leave_encash_priv` int(11) DEFAULT NULL,
  `leave_mgt_priv` int(11) DEFAULT NULL,
  `emp_sep_priv` int(11) DEFAULT NULL,
  `tax_mgt_priv` int(11) DEFAULT NULL,
  `atten_mgt_priv` int(11) DEFAULT NULL,
  `payro_priv` int(11) DEFAULT NULL,
  `load_adv_exp_priv` int(11) DEFAULT NULL,
  `emp_mgt_priv` int(11) DEFAULT NULL,
  `created_by` varchar(100) DEFAULT NULL,
  `creation_date` datetime DEFAULT CURRENT_TIMESTAMP,
  `modified_by` varchar(100) DEFAULT NULL,
  `modified_date` datetime DEFAULT CURRENT_TIMESTAMP,
  `attr1` varchar(200) DEFAULT NULL,
  `attr2` varchar(200) DEFAULT NULL,
  `attr3` varchar(200) DEFAULT NULL,
  `attr4` varchar(200) DEFAULT NULL,
  `attr5` varchar(200) DEFAULT NULL,
  `attr6` varchar(200) DEFAULT NULL,
  `probation` int(11) unsigned DEFAULT NULL,
  PRIMARY KEY (`emp_proff_pkey`),
  UNIQUE KEY `emp_company_id` (`emp_company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DELIMITER ;;

CREATE TRIGGER `emp_proff_ai` AFTER INSERT ON `emp_proff` FOR EACH ROW
begin

if new.emp_branch is not null then
  update emp_details set branch_code=new.emp_branch where emp_pkey=new.emp_fkey;

end if;


end;;

CREATE TRIGGER `emp_proff_au` AFTER UPDATE ON `emp_proff` FOR EACH ROW
begin

if new.emp_branch is not null then
  update emp_details set branch_code=new.emp_branch where emp_pkey=new.emp_fkey;

end if;


end;;

DELIMITER ;

