CREATE TABLE `grn_stock_details_date_view` (`item_master_pkey` int(11), `item_code` varchar(50), `item_desc` varchar(100), `item_category` varchar(50), `store_master_pkey` varchar(21), `store_code` varchar(20), `store_location` varchar(100), `address` varchar(500), `gr_date` varchar(10), `item_fkey` int(11), `item_qty` bigint(20), `item_state` varchar(3));


CREATE TABLE `grn_stock_det_rate_date_view` (`item_master_pkey` int(11), `item_code` varchar(50), `item_desc` varchar(100), `item_category` varchar(50), `store_master_pkey` int(11), `store_code` varchar(20), `store_location` varchar(100), `address` varchar(500), `gr_date` date, `item_fkey` int(11), `item_qty` int(11), `item_state` varchar(3), `po_rate` int(11));


CREATE TABLE `gross_salary` (`emp_fkey` int(11), `grossctcamount` decimal(32,0));


CREATE TABLE `group_allocation` (
  `allocation_id` int(11) NOT NULL AUTO_INCREMENT,
  `company_code` varchar(30) NOT NULL,
  `group_id` int(11) NOT NULL,
  `branch_code` varchar(50) NOT NULL,
  `dept_code` varchar(50) NOT NULL,
  `designation_id` varchar(50) NOT NULL,
  `emp_type` varchar(50) NOT NULL,
  `Emp_fkey` int(11) NOT NULL,
  `start_month_year` varchar(30) NOT NULL,
  `end_month_year` varchar(30) NOT NULL,
  `status` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`allocation_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `gr_item_details` (
  `gr_item_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `grn_fkey` int(11) NOT NULL,
  `po_fkey` int(11) NOT NULL,
  `item_code` int(11) NOT NULL,
  `uom` int(11) DEFAULT NULL,
  `ordering_qty` int(11) NOT NULL,
  `received_qty` int(11) NOT NULL,
  `current_stock` int(11) DEFAULT NULL,
  `re_order_level` int(11) DEFAULT NULL,
  `package` int(11) DEFAULT NULL,
  `po_rate` int(11) DEFAULT NULL,
  `created_by` varchar(50) NOT NULL,
  `creation_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `modified_by` varchar(50) DEFAULT NULL,
  `modified_date` timestamp NULL DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`gr_item_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `history` (
  `history_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `emp_fkey` int(11) NOT NULL,
  `company` varchar(100) NOT NULL,
  `from_date` varchar(10) NOT NULL,
  `to_date` varchar(10) NOT NULL,
  `designation` varchar(100) NOT NULL,
  `department` varchar(100) NOT NULL,
  `salary` int(9) NOT NULL,
  `status` int(2) NOT NULL DEFAULT '1',
  PRIMARY KEY (`history_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `holidays` (
