CREATE TABLE `Item_allocation_details_view` (`date_allocated` date, `creation_date` datetime, `emp_pkey` int(11), `EmpName` varchar(302), `employee_id` varchar(30), `branch` varchar(200), `designation` varchar(100), `department` varchar(100), `joining_date` date, `store_location` varchar(100), `item_master_pkey` int(11), `item_code` varchar(50), `store_master_pkey` int(11), `item_desc` varchar(100), `qty` int(10), `returned_qty` int(10), `damaged_qty` varchar(100), `amount` double);


CREATE TABLE `item_details` (
  `item_details_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `item_master_fkey` int(11) NOT NULL,
  `item_brand` varchar(50) DEFAULT NULL,
  `item_model` varchar(50) DEFAULT NULL,
  `main_supp_code` varchar(50) DEFAULT NULL,
  `alt_supp_code` varchar(50) DEFAULT NULL,
  `package` varchar(50) DEFAULT NULL,
  `uom` varchar(50) DEFAULT NULL,
  `thickness` float DEFAULT NULL,
  `dimension` float DEFAULT NULL,
  `density` float DEFAULT NULL,
  `created_by` varchar(50) DEFAULT NULL,
  `created_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modified_by` varchar(50) NOT NULL,
  `modified_date` datetime NOT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`item_details_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `item_except_grn_allocation_view` (`item_master_pkey` int(11), `item_code` varchar(50), `item_desc` varchar(100), `item_category` varchar(50), `store_master_pkey` int(11), `store_code` varchar(20), `store_location` varchar(100), `address` varchar(500), `creation_date` timestamp, `item_fkey` int(11), `item_qty` float, `item_state` varchar(30));


CREATE TABLE `item_master` (
  `item_master_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `item_code` varchar(50) NOT NULL,
  `item_desc` varchar(100) NOT NULL,
  `item_category` varchar(50) DEFAULT NULL,
  `item_specification` varchar(50) DEFAULT NULL,
  `image_path` varchar(50) DEFAULT NULL,
  `created_by` varchar(50) DEFAULT NULL,
  `creation_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modified_by` varchar(50) DEFAULT NULL,
  `modified_date` timestamp NULL DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`item_master_pkey`),
  UNIQUE KEY `item_desc_status` (`item_desc`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `item_pricing` (
  `item_pricing_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `item_master_fkey` int(11) NOT NULL,
  `bar_code` varchar(100) DEFAULT NULL,
  `purchase_rate` float DEFAULT NULL,
  `mrp_rate` float DEFAULT NULL,
  `vat_group` varchar(30) DEFAULT NULL,
  `sales_price_group_fkey` int(11) DEFAULT NULL,
  `sales_price_group_fkey1` int(11) DEFAULT NULL,
  `sales_price_group_fkey2` int(11) DEFAULT NULL,
  `sales_price_group_fkey3` int(11) DEFAULT NULL,
  `sales_price_group_fkey4` int(11) DEFAULT NULL,
  `sales_price_group_fkey5` int(11) DEFAULT NULL,
  `sales_price_group_fkey6` int(11) DEFAULT NULL,
  `sales_price_group_fkey7` int(11) DEFAULT NULL,
  `sales_price_group_fkey8` int(11) DEFAULT NULL,
  `sales_price_group_fkey9` int(11) DEFAULT NULL,
  `applicable_scheme` varchar(30) DEFAULT NULL,
  `incentive_applicable` varchar(30) DEFAULT NULL,
  `incentive_perc` float DEFAULT NULL,
  `min_target` float DEFAULT NULL,
  `created_by` varchar(50) NOT NULL,
  `creation_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modified_by` varchar(50) DEFAULT NULL,
  `modified_date` timestamp NULL DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`item_pricing_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `item_purchase` (
  `item_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `item_fkey` int(10) NOT NULL,
  `vendor` varchar(200) NOT NULL,
  `qty` int(20) NOT NULL DEFAULT '0',
  `date_purchased` date NOT NULL,
  `PO_number` int(200) NOT NULL,
  `branch_code` varchar(20) NOT NULL,
  `submitted_on` date NOT NULL,
  `allocated_qty` int(20) NOT NULL,
  `status` int(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`item_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `item_specification` (
  `specification_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `category_code` varchar(50) NOT NULL,
  `description` varchar(50) DEFAULT NULL,
  `item_specification` varchar(50) DEFAULT NULL,
  `created_by` varchar(50) NOT NULL,
  `created_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modified_by` varchar(50) DEFAULT NULL,
  `modified_date` datetime DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`specification_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `itm_allocation` (
  `allocation_pkey` int(200) NOT NULL AUTO_INCREMENT,
  `emp_fkey` int(20) NOT NULL,
  `value` int(20) NOT NULL,
  `item_fkey` int(20) NOT NULL,
  `qty_allocated` int(20) NOT NULL,
  `date_allocated` date NOT NULL,
  `balance_recover_amt` int(11) NOT NULL DEFAULT '0',
  `loan_fkey` int(11) NOT NULL,
  `emi_start_date` date NOT NULL,
  `emi_end_date` date NOT NULL,
  `store_code` varchar(10) NOT NULL,
  `status` int(1) NOT NULL DEFAULT '1',
  `creation_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`allocation_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `leaveentries` (
  `LEAVEENTRYID` int(11) NOT NULL AUTO_INCREMENT,
  `salary_head_item_fkey` int(11) NOT NULL,
  `applied_date` date DEFAULT NULL,
  `LEAVESTATUS` varchar(255) NOT NULL DEFAULT 'Applied',
  `EMP_fkey` int(11) NOT NULL,
  `FROMDATE` date NOT NULL,
  `FROMHALF` int(11) NOT NULL DEFAULT '1' COMMENT '1: First Half, 2: Second Half',
  `TODATE` date NOT NULL,
  `TOHALF` int(11) NOT NULL DEFAULT '2' COMMENT '1: First Half, 2: Second Half',
  `ISAutherized` int(11) DEFAULT '0',
  `ISAutherizedby` int(11) NOT NULL,
  `Autherized_date` date DEFAULT NULL,
  `ISAPPROVED` int(11) DEFAULT '0',
  `APPROVEDBY` int(11) DEFAULT NULL,
  `APPROVED_date` date DEFAULT NULL,
  `Reason` varchar(400) DEFAULT NULL,
  `contact_No` varchar(20) DEFAULT NULL,
  `contact_person` varchar(255) DEFAULT NULL,
