  `created_by` varchar(30) DEFAULT NULL,
  `created_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `modified_by` varchar(30) DEFAULT NULL,
  `modified_date` timestamp NULL DEFAULT '0000-00-00 00:00:00' ON UPDATE CURRENT_TIMESTAMP,
  `status` int(11) NOT NULL DEFAULT '1',
  `leave_balance_upload_pky` int(11) NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`leave_balance_upload_pky`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DELIMITER ;;

CREATE TRIGGER `leave_balance_upload_bi` BEFORE INSERT ON `leave_balance_upload` FOR EACH ROW
begin
declare vleave_balance float;
declare vemp_fkey int;
declare vpolicy_allotted_balance int;
declare vprev_adjustment double;

select emp_fkey into vemp_fkey from emp_proff where emp_company_id = new.empid and emp_fkey in (select emp_pkey from emp_details where status = 1);

select alloted_leave_forthe_year into vpolicy_allotted_balance
from leavepolicy where salary_head_item_fkey=new.leave_type and status=1
and LEAVEPOLICY_GROUP_ID in (SELECT LEAVEPOLICY_GROUP_ID FROM emp_proff WHERE emp_fkey=vemp_fkey);

select leave_balance_inthe_year_fn(vemp_fkey,new.leave_type,null) into vleave_balance;

select adjustment into vprev_adjustment from leave_balance_upload where empid = new.empid and leave_type = new.leave_type order by leave_balance_upload_pky desc limit 1;

set new.balance_bf_adj = vleave_balance;
set new.adjustment = new.leave_balance - vleave_balance + ifnull(vprev_adjustment, 0);
end;;

DELIMITER ;

