CREATE TABLE `mob_user_login_auditor` (
  `auditor_pkey` int(11) NOT NULL,
  `userid` varchar(30) NOT NULL,
  `time_check` datetime NOT NULL COMMENT 'Check In / Check Out Time',
  `in_out` varchar(10) NOT NULL COMMENT 'in / out',
  `location` varchar(100) NOT NULL,
  `latitude` double NOT NULL,
  `longitude` double NOT NULL,
  `uploaded_time` datetime NOT NULL COMMENT 'Sync Time With Server',
  `loc_source` varchar(10) NOT NULL,
  `stay_back` varchar(10) NOT NULL DEFAULT 'N'
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DELIMITER ;;

CREATE TRIGGER `mob_user_login_auditor_ai` AFTER INSERT ON `mob_user_login_auditor` FOR EACH ROW
begin
declare	vcompany_code varchar(20);
declare	vbranch_code varchar(20);
declare	vdbname  varchar(30);
declare	vempid varchar(30);
declare	vempid1 varchar(30);
declare vattandance_seq int;
declare vintime datetime;
declare vcount int;
declare vemp_id varchar(30);
declare vstatus varchar(1);

  SELECT company_code,branch_code,emp_id into vcompany_code,vbranch_code,vemp_id 
  FROM emp_details where concat(lcase(company_code),lcase(emp_id))=lcase(new.userid);
  
  if new.stay_back= 'Y' then 
   set vstatus='N';
 else
   set vstatus='Y';
 end if;
 
select count(*) into vcount from device_attandance where LOGDATE =new.time_check and concat(lcase(company_code),lcase(emp_id))=lcase(new.userid);
if vcount =0 then
insert into device_attandance(company_code,branch_code,DEVICELOGID,DOWNLOADDATE,DEVICEID,device_USERID,emp_id,LOGDATE,
                                       C1,C2,C3,C4,C5,C6,c7,status)
values (vcompany_code,vbranch_code,new.auditor_pkey,new.uploaded_time,0,new.USERID,vemp_id,
       new.time_check ,new.in_out,'MOB',new.location,new.latitude,new.longitude,new.location,new.stay_back,vstatus);


end if;

end;;

DELIMITER ;

