CREATE TABLE `promotions` (
  `promotion_pkey` int(20) NOT NULL AUTO_INCREMENT,
  `emp_fkey` int(20) NOT NULL,
  `created_date` date NOT NULL,
  `approved_by` int(20) NOT NULL,
  `approved_status` varchar(2) NOT NULL DEFAULT 'N',
  `approved_date` date NOT NULL,
  `designation` varchar(20) NOT NULL,
  `emp_type` varchar(20) NOT NULL,
  `emp_dept` varchar(20) NOT NULL,
  `emp_branch` varchar(20) NOT NULL,
  `shift` varchar(20) NOT NULL,
  `leave` varchar(20) NOT NULL,
  `annual_gross` varchar(20) NOT NULL,
  `hierarch` varchar(20) NOT NULL,
  `salary` varchar(20) NOT NULL,
  `remarks` varchar(600) NOT NULL,
  `promotion_status` varchar(30) NOT NULL,
  `created_by` varchar(30) NOT NULL,
  `status` int(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`promotion_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `purchase_list` (
  `purchase_list_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `po_fkey` int(11) NOT NULL,
  `mr_fkey` int(11) NOT NULL,
  `created_by` varchar(50) NOT NULL,
  `creation_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`purchase_list_pkey`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;


CREATE TABLE `purchase_order` (
  `po_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `po_number` varchar(50) NOT NULL,
  `po_date` date NOT NULL,
  `expected_date` date NOT NULL,
  `po_type` varchar(50) NOT NULL,
  `location` varchar(50) NOT NULL,
  `location_code` varchar(50) NOT NULL,
  `supplier_name` varchar(50) NOT NULL,
  `supplier_code` varchar(50) NOT NULL,
  `remarks` varchar(100) NOT NULL,
  `created_by` varchar(50) DEFAULT NULL,
  `creation_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `modified_by` varchar(50) DEFAULT NULL,
  `modified_date` timestamp NULL DEFAULT NULL,
  `grn_status` int(11) NOT NULL DEFAULT '1' COMMENT '0:GRN, 1:PO, 2:PRINTED',
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`po_pkey`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;


CREATE TABLE `qualifcations` (
  `qualification_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `emp_fkey` int(11) NOT NULL,
  `course` varchar(100) NOT NULL,
  `university` varchar(100) NOT NULL,
  `duration` varchar(20) NOT NULL,
  `mark` varchar(11) NOT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`qualification_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `quantity_details` (
  `quantity_details_pkey` int(10) NOT NULL AUTO_INCREMENT,
  `item_master_fkey` int(10) NOT NULL,
  `item_balance` int(11) DEFAULT NULL,
  `in_stock` varchar(50) DEFAULT NULL,
  `stock_on_hand` int(11) DEFAULT NULL,
  `qty_commit` varchar(50) DEFAULT NULL,
  `qty_on_order` varchar(50) DEFAULT NULL,
  `re_order_level` int(4) DEFAULT NULL,
  `economic_order` int(10) DEFAULT NULL,
  `monthly_demand` int(10) DEFAULT NULL,
  `created_by` varchar(50) DEFAULT NULL,
  `created_date` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00' ON UPDATE CURRENT_TIMESTAMP,
  `modified_by` varchar(50) DEFAULT NULL,
  `modified_date` datetime DEFAULT NULL,
  `status` int(10) NOT NULL DEFAULT '1',
  PRIMARY KEY (`quantity_details_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `register_history` (
  `register_history_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `branch` varchar(20) DEFAULT NULL,
  `month` varchar(20) DEFAULT NULL,
  `start_time` datetime DEFAULT NULL,
  `created_date` datetime DEFAULT CURRENT_TIMESTAMP,
  `end_time` datetime DEFAULT NULL,
  `duration` double DEFAULT NULL,
  `created_by` varchar(30) DEFAULT NULL,
  `process` varchar(30) DEFAULT NULL,
  `status` int(11) DEFAULT NULL COMMENT '1=completed,0=working',
  PRIMARY KEY (`register_history_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `reportcriterias` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `reporttype` varchar(50) NOT NULL,
  `reportcriteria` varchar(100) NOT NULL,
  `reportcriteria_desc` varchar(100) NOT NULL,
  `reportcriteria_field` varchar(50) NOT NULL COMMENT 'Field to be filtered on report generation',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '0: Inactive, 1: Active',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

