CREATE TABLE `salary_hike` (
  `salary_hike_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `is_multiple` char(1) NOT NULL DEFAULT 'N',
  `item` char(1) NOT NULL DEFAULT 'N',
  `structure_change` char(1) NOT NULL DEFAULT 'N',
  `action` varchar(30) DEFAULT NULL,
  `remarks` varchar(200) DEFAULT NULL,
  `created_by` varchar(30) NOT NULL,
  `creation_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modified_by` varchar(30) DEFAULT NULL,
  `modification_date` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`salary_hike_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `salary_hike_details` (
  `salary_hike_details_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `salary_hike_fkey` int(11) NOT NULL,
  `item` char(1) NOT NULL DEFAULT 'N',
  `branch_code` varchar(30) NOT NULL,
  `emp_fkey` int(11) NOT NULL,
  `structure_id` int(11) NOT NULL,
  `with_effect_from` date NOT NULL,
  `next_increment_date` date NOT NULL,
  `payout_month` date NOT NULL,
  `salary_head_item_fkey` int(11) DEFAULT NULL,
  `current_amount` float DEFAULT NULL,
  `new_amount` float DEFAULT NULL,
  `increment_amount` float DEFAULT NULL,
  `increment_percentage` float DEFAULT NULL,
  `arrear_salary` char(1) NOT NULL DEFAULT 'N',
  `status` int(11) NOT NULL DEFAULT '1',
  `remarks` varchar(200) DEFAULT NULL,
  `processed` char(1) DEFAULT 'N',
  PRIMARY KEY (`salary_hike_details_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `salary_processing_audit` (
  `salary_processing_audit_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `payroll_master_fkey` int(11) NOT NULL,
  `branch_code` varchar(30) NOT NULL,
  `emp_fkey` int(11) NOT NULL,
  `month_year` varchar(30) NOT NULL,
  `payroll_type` varchar(100) NOT NULL,
  `day_time_seq` int(11) NOT NULL,
  `HOLIDAY_GROUP_ID` int(11) NOT NULL,
  `LEAVEPOLICY_GROUP_ID` int(11) NOT NULL,
  `structure_id` int(11) NOT NULL,
  `remarks` varchar(100) NOT NULL,
  `created_by` varchar(30) NOT NULL,
  `creation_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modified_by` varchar(30) DEFAULT NULL,
  `modification_date` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`salary_processing_audit_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `salary_structure` (
  `structure_id` int(11) NOT NULL AUTO_INCREMENT,
  `company_code` varchar(30) NOT NULL,
  `structure_name` varchar(200) NOT NULL,
  `prorate_code` varchar(25) NOT NULL,
  `prorate_desc` varchar(250) NOT NULL COMMENT 'Calendar,Working days,Fixed days ',
  `fixed_days` int(11) NOT NULL DEFAULT '30',
  `defined_structure_for` varchar(250) NOT NULL COMMENT 'monthly,anually,bymonthly,daily',
  `structure_eg_amt` int(11) NOT NULL,
  `structure_created_date` int(11) NOT NULL,
  `startdate_effective` date NOT NULL,
  `enddate_effective` date NOT NULL,
  `structure_active` int(11) NOT NULL,
  PRIMARY KEY (`structure_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

