CREATE TABLE `scheduled_break_off` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` varchar(10) NOT NULL DEFAULT 'A',
  `emp_fkey` int(11) NOT NULL,
  `break_off_date` date NOT NULL,
  `dutty_time` time DEFAULT NULL,
  `message` varchar(250) DEFAULT NULL,
  `break_off_msg` varchar(250) DEFAULT NULL,
  `first_half` char(1) NOT NULL DEFAULT 'N',
  `created_by` varchar(50) NOT NULL,
  `creation_date` date DEFAULT NULL,
  `modified_by` varchar(50) NOT NULL,
  `modification_date` date NOT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  `coff_status` char(1) NOT NULL DEFAULT 'N',
  `leave_entry_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DELIMITER ;;

CREATE TRIGGER `scheduled_break_off_ai` AFTER INSERT ON `scheduled_break_off` FOR EACH ROW
begin
declare vout varchar(100);

SELECT editpunch_rules(new.emp_fkey, ifnull(new.message,'breakoff'),'breakoff' , new.break_off_date,new.first_half) into vout;
end;;

CREATE TRIGGER `scheduled_break_off_au` AFTER UPDATE ON `scheduled_break_off` FOR EACH ROW
begin
declare vemp_pkey int;
declare vatt_date  date;
declare nday  int;
declare vdaytimeId  int;
declare vLOGDATE_intime datetime;
declare vLOGDATE_outime datetime;
declare vduration int;
declare vminuts_calc_perday int;
declare vminutes_per_half int;
declare vsetvalue varchar(10);
declare vexistvalue varchar(10);
declare vattendance_date int;
declare vmonthly_att_fromdate datetime;
declare vmonthly_att_todate datetime;
declare vemp_count int;
declare vcompany_code varchar(30);
declare vbranch_code varchar(30);
declare vemp_id varchar(30);
declare visnextday int;
declare vincount int;
declare vmin_bfr_on_dutty_cal_ot	int;
declare vmin_aftr_off_dutty_cal_ot int ;
declare vwork_time_day_off_cal_ot int;
declare von_dutty1 varchar(30);
declare voff_dutty1 varchar(30);
declare vworking_time1 int;
declare voff_dutty1_ot varchar(30);
declare von_dutty1_ot  varchar(30);
declare vot_duration int;
declare voutdate date;
declare vout varchar(100);
declare vcount int;
select day_time_seq into vdaytimeId from emp_proff where emp_fkey=new.emp_fkey;
	   
	 select distinct minuts_calc_perday,min_bfr_on_dutty_cal_ot,min_aftr_off_dutty_cal_ot,work_time_day_off_cal_ot,on_dutty1,off_dutty1,working_time1,isnextday
	 into vminuts_calc_perday ,vmin_bfr_on_dutty_cal_ot,vmin_aftr_off_dutty_cal_ot,vwork_time_day_off_cal_ot,von_dutty1,voff_dutty1,vworking_time1,visnextday
	   from working_day_time_procedures where day_time_seq=vdaytimeId ;
	   select company_code,branch_code,emp_id into vcompany_code,vbranch_code,vemp_id from emp_details where emp_pkey=new.emp_fkey;
	   
if new.status=0 then
  delete from device_attandance where c3 is not null and C2 !='MOB' and  date_format(LOGDATE,'%Y-%m-%d')=new.break_off_date
    and emp_id in (select emp_id from emp_details where emp_pkey= new.emp_fkey);
  
elseif new.status=1 then

 	SELECT editpunch_rules(new.emp_fkey, ifnull(new.message,'breakoff'),'breakoff', new.break_off_date,new.first_half) into vout;

end if;
end;;

DELIMITER ;

CREATE TABLE `section` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `section_code` varchar(20) NOT NULL,
  `section_name` varchar(100) NOT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `settings_runner` (
  `setting_runner_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `settings_fkey` int(11) NOT NULL,
  `emp_fkey` int(11) NOT NULL,
  `exit_status` varchar(20) NOT NULL,
  `updated_times` int(11) NOT NULL,
  `creation_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modification_date` datetime DEFAULT NULL,
  PRIMARY KEY (`setting_runner_pkey`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;


CREATE TABLE `shift_exceptions` (
  `shift_exceptions_pkey` int(10) NOT NULL AUTO_INCREMENT,
  `shift_id` int(10) NOT NULL,
  `ex_week_day` varchar(20) NOT NULL,
  `ex_week` varchar(10) NOT NULL,
  `week_off` char(1) NOT NULL,
  `in_time` time DEFAULT NULL,
  `out_time` time DEFAULT NULL,
  `duration` int(11) DEFAULT NULL,
  `full_day` int(11) DEFAULT NULL,
  `half_day` int(11) DEFAULT NULL,
  `creation_date` datetime NOT NULL ON UPDATE CURRENT_TIMESTAMP,
  `created_by` varchar(20) NOT NULL,
  `modification_date` datetime DEFAULT CURRENT_TIMESTAMP,
  `modified_by` varchar(20) DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`shift_exceptions_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `site` (
  `site_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `organization_id` int(11) NOT NULL,
  `site_id` varchar(20) NOT NULL,
  `site_name` varchar(200) NOT NULL,
  `branch_code` varchar(50) NOT NULL,
  `location_id` int(11) NOT NULL COMMENT 'location',
  `work_type_id` int(11) NOT NULL COMMENT 'worktype',
  `user_pkey` int(11) NOT NULL COMMENT 'site manager',
  `latitude` int(11) NOT NULL,
  `longitude` int(11) NOT NULL,
  `address` varchar(500) NOT NULL,
  `payment_mode` varchar(50) DEFAULT NULL,
  `special_remarks` varchar(100) NOT NULL,
  `creation_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `jurisdiction` varchar(100) NOT NULL,
  `expected_starting_date` date NOT NULL,
  `contact_name` int(11) NOT NULL,
  `expected_compleation_date` date NOT NULL,
  `customer_name` varchar(100) NOT NULL,
  `customer_siteid` varchar(20) NOT NULL,
  `customer_refno` varchar(20) NOT NULL,
  `customer_po_number` varchar(20) NOT NULL,
  `customer_contact` varchar(20) NOT NULL,
  `po_expirydate` date NOT NULL,
  `allocated_fund` int(11) NOT NULL,
  `min_days_before` int(11) DEFAULT '30',
  `active` char(1) NOT NULL,
  `status` int(11) NOT NULL DEFAULT '1' COMMENT 'value 0 is deleted',
  PRIMARY KEY (`site_pkey`),
  KEY `contact_name` (`contact_name`),
  CONSTRAINT `site_ibfk_1` FOREIGN KEY (`contact_name`) REFERENCES `contacts` (`contact_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


CREATE TABLE `site_attendance` (
  `site_attendance_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `site_fkey` int(11) NOT NULL,
  `mobile_pkey` int(11) NOT NULL,
  `day_time_seq_fkey` int(11) NOT NULL,
  `designation_id` int(11) NOT NULL,
  `emp_fkey` int(11) NOT NULL,
  `att_date` date DEFAULT NULL,
  `in_time` datetime DEFAULT NULL,
  `out_time` datetime DEFAULT NULL,
  `created_by` varchar(20) NOT NULL,
  `modified_by` varchar(20) DEFAULT NULL,
  `creation_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `modified_date` datetime DEFAULT NULL,
  `upload_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `active` int(11) DEFAULT '1',
  `status` int(1) NOT NULL DEFAULT '1',
  `sales_rate` float DEFAULT NULL,
  `emp_rate` float DEFAULT NULL,
  `duration` float DEFAULT NULL,
  PRIMARY KEY (`site_attendance_pkey`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DELIMITER ;;

CREATE TRIGGER `site_attendance_ai` AFTER INSERT ON `site_attendance` FOR EACH ROW
begin
declare	vcompany_code varchar(20);
declare	vbranch_code varchar(20);
declare	vdbname  varchar(30);
declare	vempid varchar(30);
declare	vempid1 varchar(30);
declare vattandance_seq int;
declare vintime datetime;
declare vcount int;
declare vsite varchar(100);

  SELECT company_code,branch_code ,emp_id into vcompany_code,vbranch_code,vempid FROM emp_details where emp_pkey=new.emp_fkey;
  
 select site_name into vsite from site where site_pkey =new.site_fkey;


end;;

CREATE TRIGGER `site_attendance_bu` BEFORE UPDATE ON `site_attendance` FOR EACH ROW
begin
declare	vcompany_code varchar(20);
declare	vbranch_code varchar(20);
declare	vdbname  varchar(30);
declare	vempid varchar(30);
declare	vempid1 varchar(30);
declare vattandance_seq int;
declare vintime datetime;
declare vcount int;
declare vincount int;
declare voutcount int;
declare vinoutcount  int;
declare vsite varchar(100);
declare vsite_transactions_pkey	 int;
declare vsrate float;
declare veratess float ;
declare vsite_shift_close_pkey int;
declare vinattandance_seq int;
declare voutattandance_seq int;

  SELECT company_code,branch_code ,emp_id into vcompany_code,vbranch_code,vempid FROM emp_details where emp_pkey=new.emp_fkey;
  
 select site_name into vsite from site where site_pkey =new.site_fkey;
 select site_transactions_pkey,srate,eratess into vsite_transactions_pkey,vsrate,veratess from site_transactions
  where site_fkey=new.site_fkey and day_time_seq_fkey=new.day_time_seq_fkey and designation_id=new.designation_id and status=1;


 
  if new.status=3 then
  
  if new.in_time and new.out_time is not null then
     select count(*) into vincount from device_attandance where LOGDATE =new.in_time and emp_id=vempid and c1='in' and status ='Y' ;
   
     select count(*) into voutcount from device_attandance where LOGDATE =new.out_time and emp_id=vempid and c1='out'and status ='Y';
	 
	set new.duration=round(TIMESTAMPDIFF(Minute, new.in_time,new.out_time)/60,2)  ;
	set new.sales_rate = vsrate ;
	set new.emp_rate = veratess ;
	
	 if vincount=0 then
              
			insert into device_attandance(company_code,branch_code,DEVICELOGID,DOWNLOADDATE,DEVICEID,device_USERID,emp_id,LOGDATE,
												   C1,C2,C3,C4,C5,C6,c7)
			values (vcompany_code,vbranch_code,new.site_attendance_pkey,new.upload_time,0,vempid,vempid,
				  DATE_ADD(new.in_time, INTERVAL 1 SECOND)  ,'in','SIT',vsite,new.day_time_seq_fkey,new.designation_id,new.site_fkey,vsite_transactions_pkey	  );
	    
            end if;
     if voutcount	 =0 then
			insert into device_attandance(company_code,branch_code,DEVICELOGID,DOWNLOADDATE,DEVICEID,device_USERID,emp_id,LOGDATE,
												   C1,C2,C3,C4,C5,C6,c7)
			values (vcompany_code,vbranch_code,new.site_attendance_pkey,new.upload_time,0,vempid,vempid,
				   new.out_time ,'out','SIT',vsite,new.day_time_seq_fkey,new.designation_id,new.site_fkey,vsite_transactions_pkey	  );
	  end if;			   
  select count(*) into vcount from site_shift_close where att_date=new.att_date and day_time_seq_fkey= new.day_time_seq_fkey 
   and  shift_closed_status='Y' and rec_status=1;
  if vcount = 0 then
      INSERT INTO site_shift_close (site_fkey,site_transactions_fkey,day_time_seq_fkey, att_date, shift_closed_status, created_by)
        VALUES (new.site_fkey,vsite_transactions_pkey,new.day_time_seq_fkey,	new.att_date,	'Y',	new.created_by);
   end if;
 end if;
 elseif new.status=4 then
 
  select device_attandance_seq into vinattandance_seq  from device_attandance where LOGDATE =DATE_ADD(new.in_time, INTERVAL 1 SECOND)
   and emp_id=vempid and c1='in' and status ='Y' and c7=vsite_transactions_pkey;
 select device_attandance_seq into voutattandance_seq from device_attandance where LOGDATE =new.out_time 
   and emp_id=vempid and c1='out'and status ='Y' and c7=vsite_transactions_pkey ;
  
   select site_shift_close_pkey into vsite_shift_close_pkey from site_shift_close where att_date=new.att_date and day_time_seq_fkey= new.day_time_seq_fkey 
   and  shift_closed_status='Y' and rec_status=1 and site_fkey =new.site_fkey;
   delete from site_shift_close where site_fkey=new.site_fkey and shift_closed_status='Y' and att_date=new.att_date and day_time_seq_fkey= new.day_time_seq_fkey and rec_status=2;
   update site_shift_close set rec_status=2,modified_by=new.modified_by,modified_date=current_date
   where site_shift_close_pkey=vsite_shift_close_pkey and rec_status=1;

   delete from device_attandance where device_attandance_seq= vinattandance_seq;
   delete from device_attandance where device_attandance_seq= voutattandance_seq; 
   delete from emp_site_detail_timeattandance where site_fkey=new.site_fkey and att_date LIKE '%DATE_FORMAT(new.att_date, "%Y-%m")%' ;  
  end if;

end;;

DELIMITER ;

CREATE TABLE `site_attendance_register` (
  `company_code` varchar(20) NOT NULL,
  `branch_code` varchar(20) NOT NULL,
  `registerid` int(11) NOT NULL AUTO_INCREMENT,
