CREATE TABLE `user_credentials` (
  `user_pkey` int(11) NOT NULL AUTO_INCREMENT,
  `emp_fkey` int(11) DEFAULT NULL,
  `company_code` varchar(20) DEFAULT NULL,
  `user_id` varchar(30) DEFAULT NULL,
  `password` varchar(100) DEFAULT NULL,
  `access_allowed` varchar(1) DEFAULT NULL,
  `start_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `end_date` date DEFAULT NULL,
  `first_name` varchar(100) DEFAULT NULL,
  `last_name` varchar(100) DEFAULT NULL,
  `middle_name` varchar(100) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `phone` int(11) DEFAULT NULL,
  `reset_login_flag` varchar(100) DEFAULT 'N' COMMENT 'Y : Need to reset password, N: No need to reset password',
  `locked` int(11) DEFAULT '0' COMMENT '0: Not locked, 1: Locked',
  `incorrect_login_attempt` int(11) DEFAULT '0' COMMENT 'Maximum Attempt : 3',
  `attr1` varchar(200) DEFAULT NULL,
  `attr2` varchar(200) DEFAULT NULL,
  `avatar` text,
  `user_group` int(11) DEFAULT '1' COMMENT 'if 1 normal user 2 for admin',
  PRIMARY KEY (`user_pkey`),
  UNIQUE KEY `user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DELIMITER ;;

CREATE TRIGGER `user_credentials_au` AFTER UPDATE ON `user_credentials` FOR EACH ROW
begin
declare vcount int;
declare vcompany_code varchar(30);
select count(*) into vcount  from user_access where user_fkey=new.emp_fkey and active='Y' and status=1;
if vcount =0 then

if lcase(new.access_allowed) = 'y' then

CALL `insert_default_menu`(new.emp_fkey);
end if;
end if;
if old.email !=new.email then
 select company_code into vcompany_code from emp_details where emp_pkey=new.emp_fkey;
 update mypayrol_control_db.emp_device_comp_branch set email=new.email where  Company_code=vcompany_code and emp_fkey=new.emp_fkey;
end if;

end;;

DELIMITER ;

