  `to_date` varchar(100) NOT NULL,
  `designation` varchar(100) NOT NULL,
  `department` varchar(100) NOT NULL,
  `salary` int(9) DEFAULT NULL,
  `status` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`experience_pkey`),
  KEY `emp_join_fkey` (`emp_join_fkey`),
  CONSTRAINT `work_experience_ibfk_1` FOREIGN KEY (`emp_join_fkey`) REFERENCES `emp_join` (`emp_join_pkey`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `att_in`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `att_in` AS select distinct `att`.`device_attandance_seq` AS `device_attandance_seq`,`ed`.`emp_pkey` AS `EMP_PKEY`,concat(`ed`.`first_name`,`ed`.`middile_name`,`ed`.`last_name`) AS `EmpName`,`att`.`LOGDATE` AS `LOGDATE`,`att`.`C1` AS `C1`,`att`.`C3` AS `c3` from (`device_attandance` `att` join `emp_details` `ed`) where ((`att`.`emp_id` = `ed`.`emp_id`) and (`att`.`C1` = 'in'));

DROP TABLE IF EXISTS `att_out`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `att_out` AS select distinct `att`.`device_attandance_seq` AS `device_attandance_seq`,`ed`.`emp_pkey` AS `EMP_PKEY`,concat(`ed`.`first_name`,' ',`ed`.`middile_name`,' ',`ed`.`last_name`) AS `EmpName`,`att`.`LOGDATE` AS `LOGDATE`,`att`.`C1` AS `C1`,ifnull(`att`.`C3`,'Office') AS `location` from (`device_attandance` `att` join `emp_details` `ed`) where ((`att`.`emp_id` = `ed`.`emp_id`) and (`att`.`C1` = 'out'));

DROP TABLE IF EXISTS `ctc_fixed_amount`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `ctc_fixed_amount` AS select `emp_salary_slip`.`emp_fkey` AS `emp_fkey`,`emp_salary_slip`.`month_year` AS `month_year`,sum(`emp_salary_slip`.`salary_amount`) AS `ctcAmount` from `emp_salary_slip` where (isnull(`emp_salary_slip`.`end_date_effective`) and (lower(`emp_salary_slip`.`head_operator`) = 'addition') and (lower(`emp_salary_slip`.`head_type`) = 'fixed')) group by `emp_salary_slip`.`emp_fkey`,`emp_salary_slip`.`month_year`;

DROP TABLE IF EXISTS `ctc_fixed_rate`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `ctc_fixed_rate` AS select `emp_salary_structure`.`emp_fkey` AS `emp_fkey`,sum(`emp_salary_structure`.`structure_det_value`) AS `ctcRate` from `emp_salary_structure` where (isnull(`emp_salary_structure`.`end_date_effective`) and (lower(`emp_salary_structure`.`head_operator`) = 'addition') and (lower(`emp_salary_structure`.`head_type`) = 'fixed')) group by `emp_salary_structure`.`emp_fkey`;

DROP TABLE IF EXISTS `employee_info`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `employee_info` AS select `ed`.`emp_pkey` AS `emp_pkey`,`ed`.`branch_code` AS `branch_code`,`ed`.`emp_id` AS `emp_id`,concat(`ed`.`first_name`,' ',ifnull(`ed`.`middile_name`,''),' ',ifnull(`ed`.`last_name`,'')) AS `EmpName`,`ep`.`emp_company_id` AS `employee_id`,`br`.`branch_name` AS `branch`,`designation`.`desig_name` AS `designation`,`department`.`dept_name` AS `department`,`ep`.`joining_date` AS `joining_date`,`grade`.`grade_name` AS `grade`,`ed`.`status` AS `emp_status` from (((((`emp_proff` `ep` join `emp_details` `ed` on((`ed`.`emp_pkey` = `ep`.`emp_fkey`))) left join `branches` `br` on((`ed`.`branch_code` = `br`.`branch_code`))) left join `grade` on(((`ep`.`emp_grade` = `grade`.`grade_pkey`) and (`grade`.`status` = 1)))) left join `designation` on(((`ep`.`designation` = `designation`.`desig_code`) and (`designation`.`status` = 1)))) left join `department` on(((`ep`.`emp_dept` = `department`.`dept_code`) and (`department`.`status` = 1))));

DROP TABLE IF EXISTS `employee_structure_vview`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `employee_structure_vview` AS select `ed`.`emp_pkey` AS `emp_pkey`,concat(`ed`.`first_name`,' ',ifnull(`ed`.`middile_name`,''),' ',ifnull(`ed`.`last_name`,'')) AS `EmpName`,`ep`.`emp_company_id` AS `employee_id`,`br`.`branch_name` AS `branch`,`designation`.`desig_name` AS `designation`,`department`.`dept_name` AS `department`,`ep`.`joining_date` AS `joining_date`,`ep`.`emp_type` AS `employee_type`,`salary_structure`.`structure_name` AS `Salary_structure`,`holiday_group`.`HOLIDAY_GROUP_NAME` AS `HOLIDAY_GROUP_NAME`,`working_day_time_procedures`.`day_time_desc` AS `SHIFT_POLICYS`,`leavepolicy_group`.`LEAVEPOLICY_GROUP_NAME` AS `LEAVEPOLICY`,(select concat(`ed`.`first_name`,' ',ifnull(`ed`.`middile_name`,''),' ',ifnull(`ed`.`last_name`,'')) AS `EmpName` from `emp_details` `ed` where (`ed`.`emp_pkey` = `ep`.`attr1`)) AS `hierarchy` from ((((((((`emp_proff` `ep` join `emp_details` `ed` on((`ed`.`emp_pkey` = `ep`.`emp_fkey`))) left join `branches` `br` on((`ed`.`branch_code` = `br`.`branch_code`))) left join `designation` on((`ep`.`designation` = `designation`.`desig_code`))) left join `department` on((`ep`.`emp_dept` = `department`.`dept_code`))) left join `salary_structure` on((`ep`.`structure_id` = `salary_structure`.`structure_id`))) left join `holiday_group` on((`ep`.`HOLIDAY_GROUP_ID` = `holiday_group`.`HOLIDAY_GROUP_ID`))) left join `working_day_time_procedures` on((`ep`.`day_time_seq` = `working_day_time_procedures`.`day_time_seq`))) left join `leavepolicy_group` on((`ep`.`LEAVEPOLICY_GROUP_ID` = `leavepolicy_group`.`LEAVEPOLICY_GROUP_ID`)));

DROP TABLE IF EXISTS `emp_config_history`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `emp_config_history` AS select `emp_config`.`emp_fkey` AS `emp_fkey`,`emp_config`.`type` AS `type`,`working_day_time_procedures`.`day_time_desc` AS `day_time_desc`,(case `emp_config`.`status` when 1 then 'Active' when 0 then 'Changed' end) AS `status`,`emp_config`.`creation_date` AS `creation_date`,(case when (isnull(`emp_config`.`created_by`) or (`emp_config`.`created_by` = ' ')) then 'Admin' else `emp_config`.`created_by` end) AS `created_by`,`emp_config`.`modification_date` AS `modification_date`,`emp_config`.`modified_by` AS `modified_by` from (`emp_config` join `working_day_time_procedures`) where ((`emp_config`.`policy_id` = `working_day_time_procedures`.`day_time_seq`) and (`emp_config`.`policy_id` is not null) and (`emp_config`.`type` = 'SHIFT')) union all select `emp_config`.`emp_fkey` AS `emp_fkey`,`emp_config`.`type` AS `type`,`salary_structure`.`structure_name` AS `structure_name`,(case `emp_config`.`status` when 1 then 'Active' when 0 then 'Changed' end) AS `status`,`emp_config`.`creation_date` AS `creation_date`,(case when (isnull(`emp_config`.`created_by`) or (`emp_config`.`created_by` = ' ')) then 'Admin' else `emp_config`.`created_by` end) AS `created_by`,`emp_config`.`modification_date` AS `modification_date`,`emp_config`.`modified_by` AS `modified_by` from (`emp_config` join `salary_structure`) where ((`emp_config`.`policy_id` = `salary_structure`.`structure_id`) and (`emp_config`.`policy_id` is not null) and (`emp_config`.`type` = 'SALARY')) union all select `emp_config`.`emp_fkey` AS `emp_fkey`,`emp_config`.`type` AS `type`,`leavepolicy_group`.`LEAVEPOLICY_GROUP_NAME` AS `LEAVEPOLICY_GROUP_NAME`,(case `emp_config`.`status` when 1 then 'Active' when 0 then 'Changed' end) AS `status`,`emp_config`.`creation_date` AS `creation_date`,(case when (isnull(`emp_config`.`created_by`) or (`emp_config`.`created_by` = ' ')) then 'Admin' else `emp_config`.`created_by` end) AS `created_by`,`emp_config`.`modification_date` AS `modification_date`,`emp_config`.`modified_by` AS `modified_by` from (`emp_config` join `leavepolicy_group`) where ((`emp_config`.`policy_id` = `leavepolicy_group`.`LEAVEPOLICY_GROUP_ID`) and (`emp_config`.`policy_id` is not null) and (`emp_config`.`type` = 'LEAVE')) union all select `emp_config`.`emp_fkey` AS `emp_fkey`,`emp_config`.`type` AS `type`,`holiday_group`.`HOLIDAY_GROUP_NAME` AS `HOLIDAY_GROUP_NAME`,(case `emp_config`.`status` when 1 then 'Active' when 0 then 'Changed' end) AS `status`,`emp_config`.`creation_date` AS `creation_date`,(case when (isnull(`emp_config`.`created_by`) or (`emp_config`.`created_by` = ' ')) then 'Admin' else `emp_config`.`created_by` end) AS `created_by`,`emp_config`.`modification_date` AS `modification_date`,`emp_config`.`modified_by` AS `modified_by` from (`emp_config` join `holiday_group`) where ((`emp_config`.`policy_id` = `holiday_group`.`HOLIDAY_GROUP_ID`) and (`emp_config`.`policy_id` is not null) and (`emp_config`.`type` = 'HOLIDAY')) union all select `emp_config`.`emp_fkey` AS `emp_fkey`,`emp_config`.`type` AS `type`,concat(`emp_details`.`first_name`,' ',`emp_details`.`last_name`) AS `empname`,(case `emp_config`.`status` when 1 then 'Active' when 0 then 'Changed' end) AS `status`,`emp_config`.`creation_date` AS `creation_date`,(case when (isnull(`emp_config`.`created_by`) or (`emp_config`.`created_by` = ' ')) then 'Admin' else `emp_config`.`created_by` end) AS `created_by`,`emp_config`.`modification_date` AS `modification_date`,`emp_config`.`modified_by` AS `modified_by` from (`emp_config` join `emp_details`) where ((`emp_config`.`policy_id` = `emp_details`.`emp_pkey`) and (`emp_config`.`policy_id` is not null) and (`emp_config`.`type` = 'HIERARCHY')) union all select `emp_ctc_transaction`.`emp_fkey` AS `emp_fkey`,'Monthly CTC' AS `type`,`emp_ctc_transaction`.`emp_derived_anualctc` AS `emp_derived_anualctc`,(case when isnull(`emp_ctc_transaction`.`end_date_effective`) then 'Active' when (`emp_ctc_transaction`.`end_date_effective` is not null) then 'Changed' end) AS `status`,`emp_ctc_transaction`.`created_date` AS `creation_date`,`emp_ctc_transaction`.`created_by` AS `created_by`,`emp_ctc_transaction`.`modified_date` AS `modification_date`,`emp_ctc_transaction`.`modified_by` AS `modified_by` from `emp_ctc_transaction` where (`emp_ctc_transaction`.`emp_derived_anualctc` is not null) order by `emp_fkey`,`type`,`creation_date` desc;

DROP TABLE IF EXISTS `emp_early_in`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `emp_early_in` AS select distinct `ed`.`emp_pkey` AS `emp_pkey`,concat(ifnull(`ed`.`first_name`,''),' ',ifnull(`ed`.`middile_name`,''),' ',ifnull(`ed`.`last_name`,'')) AS `EmpName`,`att`.`LOGDATE` AS `LogDate`,`att`.`C3` AS `Location`,`wtp`.`on_dutty1` AS `SharpInTime`,time_format(`att`.`LOGDATE`,'%H:%i:%s') AS `InTime`,timediff(time_format(`wtp`.`on_dutty1`,'%H:%i:%s'),time_format(`att`.`LOGDATE`,'%H:%i:%s')) AS `EarlyInTime` from (((`device_attandance` `att` join `emp_details` `ed` on(((`att`.`emp_id` = `ed`.`emp_id`) and (lower(`att`.`C1`) = 'in')))) join `emp_proff` `ep` on((`ed`.`emp_pkey` = `ep`.`emp_fkey`))) join `working_day_time_procedures` `wtp` on((`wtp`.`day_time_seq` = `ep`.`day_time_seq`))) where ((time_format(`att`.`LOGDATE`,'%H:%i:%s') < time_format(`wtp`.`on_dutty1`,'%H:%i:%s')) and (`att`.`status` = 'Y')) order by `ed`.`emp_pkey`,concat(ifnull(`ed`.`first_name`,''),' ',ifnull(`ed`.`middile_name`,''),' ',ifnull(`ed`.`last_name`,''));

DROP TABLE IF EXISTS `emp_early_out`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `emp_early_out` AS select distinct `ed`.`emp_pkey` AS `emp_pkey`,concat(ifnull(`ed`.`first_name`,''),' ',ifnull(`ed`.`middile_name`,''),' ',ifnull(`ed`.`last_name`,'')) AS `EmpName`,`att`.`LOGDATE` AS `LogDate`,`att`.`C3` AS `Location`,`wtp`.`off_dutty1` AS `ShiftEndTime`,addtime(`wtp`.`off_dutty1`,-(sec_to_time((`wtp`.`minuts_bfr_off_dutty_cal_early` * 60)))) AS `OffDutyTime`,time_format(`att`.`LOGDATE`,'%H:%i:%s') AS `OutTime`,timediff(addtime(`wtp`.`off_dutty1`,-(sec_to_time((`wtp`.`minuts_bfr_off_dutty_cal_early` * 60)))),time_format(`att`.`LOGDATE`,'%H:%i:%s')) AS `EarlyOutTime` from (((`device_attandance` `att` join `emp_details` `ed` on(((`att`.`emp_id` = `ed`.`emp_id`) and (lower(`att`.`C1`) = 'out')))) join `emp_proff` `ep` on((`ed`.`emp_pkey` = `ep`.`emp_fkey`))) join `working_day_time_procedures` `wtp` on((`wtp`.`day_time_seq` = `ep`.`day_time_seq`))) where ((time_format(`att`.`LOGDATE`,'%H:%i:%s') < addtime(`wtp`.`off_dutty1`,sec_to_time((`wtp`.`minuts_bfr_off_dutty_cal_early` * 60)))) and (`att`.`status` = 'Y') and `att`.`LOGDATE` in (select max(`device_attandance`.`LOGDATE`) from `device_attandance` where ((lower(`device_attandance`.`C1`) = 'out') and (upper(`device_attandance`.`status`) = 'Y')) group by date_format(`device_attandance`.`LOGDATE`,'%Y-%m-%d'),`device_attandance`.`emp_id`)) order by `ed`.`emp_pkey`,concat(ifnull(`ed`.`first_name`,''),' ',ifnull(`ed`.`middile_name`,''),' ',ifnull(`ed`.`last_name`,''));

DROP TABLE IF EXISTS `emp_late_in`;
