DROP TABLE IF EXISTS `leave_taken`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `leave_taken` AS select `lt`.`EMP_fkey` AS `emp_fkey`,`lt`.`salary_head_item_fkey` AS `salary_head_item_fkey`,date_format(`elt`.`leave_date`,'%Y%m') AS `yearmonth`,sum(`elt`.`leave_session`) AS `leavetaken` from (`emp_leave_transactions` `elt` join `leaveentries` `lt` on((`elt`.`LEAVEENTRYID` = `lt`.`LEAVEENTRYID`))) where ((`elt`.`leave_session` = 3) and (`lt`.`REMARKS` <> 'No need Leave') and (`lt`.`LEAVESTATUS` in ('Approved','Autherized'))) group by `lt`.`EMP_fkey`,`lt`.`salary_head_item_fkey`,date_format(`elt`.`leave_date`,'%Y%m') union all select `lt`.`EMP_fkey` AS `emp_fkey`,`lt`.`salary_head_item_fkey` AS `salary_head_item_fkey`,date_format(`elt`.`leave_date`,'%Y%m') AS `yearmonth`,(sum(`elt`.`leave_session`) / 2) AS `leavetaken` from (`emp_leave_transactions` `elt` join `leaveentries` `lt` on((`elt`.`LEAVEENTRYID` = `lt`.`LEAVEENTRYID`))) where ((`elt`.`leave_session` in (2,1)) and (`lt`.`REMARKS` <> 'No need Leave') and (`lt`.`LEAVESTATUS` in ('Approved','Autherized'))) group by `lt`.`EMP_fkey`,`lt`.`salary_head_item_fkey`,date_format(`elt`.`leave_date`,'%Y%m');

DROP TABLE IF EXISTS `present_employee`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `present_employee` AS select distinct concat(`ed`.`first_name`,' ',ifnull(`ed`.`middile_name`,''),' ',ifnull(`ed`.`last_name`,'')) AS `EmpName`,`att`.`C1` AS `Direction`,`ed`.`emp_pkey` AS `emp_pkey`,max(`att`.`LOGDATE`) AS `LOGDATE` from (`device_attandance` `att` join `emp_details` `ed`) where ((`att`.`emp_id` = `ed`.`emp_id`) and (`att`.`LOGDATE` >= (curdate() - interval 1 day)) and (upper(`att`.`status`) = 'Y') and (lower(`att`.`C1`) = 'in') and (not(`ed`.`emp_id` in (select distinct `ed`.`emp_id` from (`device_attandance` `att` join `emp_details` `ed`) where ((`att`.`emp_id` = `ed`.`emp_id`) and (`att`.`LOGDATE` >= curdate()) and (upper(`att`.`status`) = 'Y') and (lower(`att`.`C1`) = 'out')) group by `ed`.`first_name`,`ed`.`last_name`)))) group by `ed`.`first_name`,`ed`.`last_name`;

DROP TABLE IF EXISTS `present_today`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `present_today` AS select distinct concat(`ed`.`first_name`,' ',ifnull(`ed`.`middile_name`,''),' ',ifnull(`ed`.`last_name`,''),' - ',`emp_proff`.`emp_company_id`) AS `EmpName`,`ed`.`emp_pkey` AS `emp_pkey` from (`emp_details` `ed` left join `emp_proff` on((`ed`.`emp_pkey` = `emp_proff`.`emp_fkey`))) where `ed`.`emp_id` in (select `att`.`emp_id` from `device_attandance` `att` where ((`att`.`emp_id`,`att`.`LOGDATE`) in (select `device_attandance`.`emp_id`,max(`device_attandance`.`LOGDATE`) AS `device_attandance_seq` from `device_attandance` where (upper(`device_attandance`.`status`) = 'Y') group by `device_attandance`.`emp_id`) and (lower(`att`.`C1`) = 'in') and (`att`.`LOGDATE` >= (curdate() - interval 1 day))));

DROP TABLE IF EXISTS `present_today_all`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `present_today_all` AS select distinct concat(`ed`.`first_name`,' ',ifnull(`ed`.`middile_name`,''),' ',ifnull(`ed`.`last_name`,''),' - ',`emp_proff`.`emp_company_id`) AS `EmpName`,`att`.`C1` AS `Direction`,`ed`.`emp_pkey` AS `emp_pkey`,max(`att`.`LOGDATE`) AS `LOGDATE` from ((`device_attandance` `att` join `emp_details` `ed`) join `emp_proff`) where ((`att`.`emp_id` = `ed`.`emp_id`) and (`ed`.`emp_pkey` = `emp_proff`.`emp_fkey`) and (`att`.`LOGDATE` >= (curdate() - interval 1 day)) and (upper(`att`.`status`) = 'Y') and (lower(`att`.`C1`) = 'in')) group by `ed`.`first_name`,`ed`.`last_name`;

